theme.template:
{{if $exportableBadges}}
<div class='ipsBox i-padding_3'>
	<div class="ipsMessage ipsMessage--info">
		{lang="acp_achievements_export_badges_blurb" sprintf="$exportableBadges" pluralize="$exportableBadges"}
	</div>
	<div class="ipsSubmitRow">
		<a href="{url="app=core&module=achievements&controller=badges&do=export"}" class="ipsButton ipsButton--primary">{lang="acp_achievements_export"}</a>
	</div>
</div>
{{else}}
<div class='ipsBox i-padding_3'>
	<div class="ipsMessage ipsMessage--error">
		{lang="acp_achievements_export_badges_blurb_error"}
	</div>
</div>
{{endif}}

{{foreach $rules as $rule}}
    {{$extension = $rule->extension();}}
    {{$canUse = $extension ? $extension->canUse() : false;}}
	<li data-role="node">
		<div class="ipsTree_row">
			<div class="ipsTree_align">
				<div class="ipsTree_rowData {{if !$rule->enabled or !$canUse}}i-opacity_4{{endif}}">
					<div class="i-flex i-flex-wrap_wrap i-gap_2">
						<div class="i-flex_01 i-basis_600">
							<div class="ipsTree_title">
								{$extension?->ruleDescription( $rule )|raw}
							</div>
							{{if !$canUse}}
								<div class="i-font-size_-1">{lang="acp_rule_disabled_reason"}</div>
							{{endif}}
							{{if !$rule->enabled}}
								<div class="ipsTree_description">{lang="acp_rule_paused"}</div>
							{{elseif !$canUse}}
								<div class="ipsTree_description">{lang="acp_rule_disabled"}</div>
							{{endif}}
						</div>
						<div class="i-flex_11 i-basis_400">
							<div class="ipsTree_row_cells">
								<!-- {lang="achievements_awards"} -->
								<div class='i-grid i-gap_2'>
									{{if ( $rule->points_subject or $rule->badgeSubject() ) and ( $rule->points_other or $rule->badgeOther() )}}
										{template="ruleAwards" group="achievements" params="$rule->points_subject, $rule->badgeSubject(), $extension?->awardOptions( $rule->filters )['subject']"}
										{template="ruleAwards" group="achievements" params="$rule->points_other, $rule->badgeOther(), $extension?->awardOptions( $rule->filters )['other']"}
									{{elseif $rule->points_subject or $rule->badgeSubject()}}
										{template="ruleAwards" group="achievements" params="$rule->points_subject, $rule->badgeSubject(), $extension?->awardOptions( $rule->filters )['subject']"}
									{{elseif $rule->points_other or $rule->badgeOther()}}
										{template="ruleAwards" group="achievements" params="$rule->points_other, $rule->badgeOther(), $extension?->awardOptions( $rule->filters )['subject']"}
									{{else}}
										{template="ruleAwards" group="achievements" params="$rule->points_other, NULL, NULL"}
									{{endif}}
								</div>
							</div>
						</div>
					</div>
				</div>				
				<div class="ipsTree_controls">
					{template="controlStrip" params="$rule->getButtons( \IPS\Http\Url::internal('app=core&module=achievements&controller=rules') )" group="global" app="core"}
				</div>
			</div>
		</div>
	</li>
{{endforeach}}

{{if settings.dellog_retention_period}}
<div>
	<span class='cStat__number cStat__number--medium' data-number='{$value}' data-ipsTooltip title="{lang="stats_deleted_tooltip" sprintf="$deleted, $total"}">{$value}%</span>
</div>
{{else}}
    <p class='i-color_soft i-text-align_center'>
        {lang="no_data"}
    </p>
{{endif}}

{{reset($values);}}
{{$firstTitle = key( $values );}}
{{$firstCount = array_shift( $values );}}

<div>
	<span class='cStat__number cStat__number--medium' data-number='{$firstCount}'>{number="$firstCount"}</span>
	{{if isset( $previousValues[ $firstTitle ] )}}
		<p class='cStat__change cStat__change--large {{if $previousValues[ $firstTitle ] > $firstCount}}i-color_negative{{elseif $previousValues[ $firstTitle ] < $firstCount}}i-color_positive{{else}}i-color_soft{{endif}}' data-ipsTooltip title="{lang="previous_period"} {number="$previousValues[ $firstTitle ]"}">
			{{if $previousValues[ $firstTitle ] > $firstCount}}
				-{expression="round( 100 - ( $firstCount / $previousValues[ $firstTitle ] * 100 ), 2 )"}%
			{{elseif $previousValues[ $firstTitle ] < $firstCount}}
				{{if $previousValues[ $firstTitle ]}}+{expression="round( ( ( $firstCount - $previousValues[ $firstTitle ] ) / $previousValues[ $firstTitle ] ) * 100, 2 )"}%{{else}}+ ∞{{endif}}
			{{else}}
				&mdash;
			{{endif}}
		</p>
	{{endif}}

	{{if \count( $values )}}
		<hr class='ipsHr'>
		<div class='i-flex'>
			{{foreach $values as $title => $count}}
				<div class='cStatTile__split'>
					<h3 class='cStatTile__subTitle ipsTruncate ipsTruncate_line'>{lang="$title"}</h3>
					<span class='cStat__number cStat__number--small' data-number='{$count}'>{number="$count"}</span>
					{{if isset( $previousValues[ $title ] )}}
						<p class='cStat__change cStat__change--small {{if $previousValues[ $title ] > $count}}i-color_negative{{elseif $previousValues[ $title ] < $count}}i-color_positive{{else}}i-color_soft{{endif}}' data-ipsTooltip title="{lang="previous_period"} {number="$previousValues[ $title ]"}">
							{{if $previousValues[ $title ] > $count}}
								-{expression="round( 100 - ( $count / $previousValues[ $title ] * 100 ), 2 )"}%
							{{elseif $previousValues[ $title ] < $count}}
								{{if $previousValues[ $title ]}}+{expression="round( ( ( $count - $previousValues[ $title ] ) / $previousValues[ $title ] ) * 100, 2 )"}%{{else}}+ ∞{{endif}}
							{{else}}
								&mdash;
							{{endif}}
						</p>
					{{endif}}
				</div>
			{{endforeach}}
		</div>
	{{endif}}	

	{{if \count( $nodes )}}
		<hr class='ipsHr'>
		<div class='i-flex'>
			<div class='cStatTile__split'>
				<p class='cStat__change cStat__change--small'>
					{lang="overview_stats_curfilter" list="$nodes"}
				</p>
			</div>
		</div>
	{{endif}}
</div>

{{if $success}}
	<div class="i-background_2 i-padding_3">
		{lang="task_manager_ran_log"}
		<pre>{{if \is_string( $message )}}{$message}{{else}}{expression="var_export( $message, TRUE )"}{{endif}}</pre>
	</div>
{{else}}
	<p class="ipsMessage ipsMessage--error">
		{$message}
	</p>
{{endif}}
<div class="i-background_3 i-padding_3 i-text-align_center">
	<a href="{url="app=core&module=settings&controller=advanced&do=runTask&id={$id}" csrf="true"}" class="ipsButton ipsButton--primary">{lang="task_manager_run_again"}</a> {lang="or"} <a href="{url="app=core&module=settings&controller=advanced&do=tasks"}" class="ipsButton ipsButton--secondary">{lang="task_manager_return"}</a>
</div>

{{$form = $alert->getNewConversationForm();}}
<div id='elAlert' class="ipsModal {{if $form}}ipsAlert--with-form{{endif}}" data-ipsalertmessage {{if $alert->reply == 2 and !(( $alert->reply !== 2 or !$alert->author()->member_id ) or ( $alert->reply === 2 and ! member.canUseMessenger() ))}}data-alert-required{{endif}}>
    <div class="ipsBox ipsBox--clubAlertModal">
        <h4 class='ipsDialog_title'>{{if $alert->anonymous}}<i class="fa-solid fa-bullhorn" aria-hidden="true"></i>{{endif}} {$alert->title}</h4>

        {{if $alert->author()->member_id and ! $alert->anonymous}}
        <div class='ipsPhotoPanel i-padding_2 i-padding-bottom_0'>
            {template="userPhoto" app="core" group="global" params="$alert->author(), 'tiny'"}
            <div class='ipsPhotoPanel__text'>
                <div class='ipsPhotoPanel__primary'>{lang="byline_nodate" htmlsprintf="$alert->author()->link()"}</div>
            </div>
        </div>
        {{endif}}

        <div class='i-padding_3 ipsRichText'>
            {$alert->content|raw}
        </div>

        {{if $alert->reply === \IPS\core\Alerts\Alert::REPLY_REQUIRED and $alert->author()->member_id and ! $alert->anonymous and ! member.canUseMessenger()}}
        <div data-role="reply-prompt" class="i-padding_2 i-color_soft i-font-size_-2">
            <span class="ipsBadge ipsBadge--icon ipsBadge--negative"><i class="fa-solid fa-info" aria-hidden="true"></i></span> {lang="alert_must_reply_modal_but_no_messenger" sprintf="$alert->author()->name"}
        </div>
        {{elseif $alert->reply == \IPS\core\Alerts\Alert::REPLY_REQUIRED and $alert->author()->member_id and ! $alert->anonymous}}
        <div data-role="reply-prompt" class="i-padding_2 i-color_soft i-font-size_-2">
            <span class="ipsBadge ipsBadge--icon ipsBadge--negative"><i class="fa-solid fa-info" aria-hidden="true"></i></span> {lang="alert_must_reply_modal" sprintf="$alert->author()->name"}
        </div>
        {{endif}}

        {{if $form}}
            <hr class="ipsHr"/>
            {$form|raw}
        {{endif}}
        <div class='ipsSubmitRow'>
            <div class='i-flex i-align-items_center i-justify-content_end i-gap_2'>
                {{if ( $alert->reply !== \IPS\core\Alerts\Alert::REPLY_REQUIRED or !$alert->author()->member_id ) or ( $alert->reply === \IPS\core\Alerts\Alert::REPLY_REQUIRED and ! member.canUseMessenger() ) }}
                    <a class="ipsButton ipsButton--secondary ipsButton--small" href="{url="app=core&module=system&controller=alerts&do=dismiss&id={$alert->id}" seoTemplate="alert" csrf="true"}" data-role="dismiss">{lang="alert_dismiss"}</a>
                {{endif}}
                {{if !$alert->anonymous and $alert->reply and $alert->author()->member_id and member.canUseMessenger()}}
                    <a href='{url="app=core&module=messaging&controller=messenger&do=compose&to={$alert->member_id}&title={$alert->title}&alert={$alert->id}" seoTemplate="messenger_compose"}' class='ipsButton ipsButton--primary ipsButton--small' disabled data-role="reply">{lang="reply"}</a>
                {{endif}}
            </div>
        </div>
	</div>
</div>

{{if $row['api_key']}}
	{{if $apiKey}}
		<i class="fa-solid fa-key" title="{lang="api_id"}" data-ipsTooltip aria-hidden="true"></i> {$apiKey->_title}
	{{else}}
		<i class="fa-solid fa-key" title="{lang="api_id"}" data-ipsTooltip aria-hidden="true"></i> <code>{$row['api_key']}</code>
	{{endif}}
{{elseif $row['access_token']}}
	{{if $row['member_id'] and $member}}
		{template="userPhoto" group="global" params="$member, 'tiny'"}
		{{if $member->member_id}}
			{template="userLink" group="global" params="$member, 'tiny'"}
		{{else}}
			{lang="deleted_member"}
		{{endif}}
		{lang="api_log_member_client" sprintf="$client->_title"}
	{{elseif $client}}
		<i class="fa-solid fa-cubes" title="{lang="oauth_client"}" data-ipsTooltip aria-hidden="true"></i> {$client->_title}
	{{else}}
		<i class="fa-solid fa-cubes" title="{lang="oauth_client"}" data-ipsTooltip aria-hidden="true"></i> <code>{$row['access_token']}</code>
	{{endif}}
{{else}}
	<em class="i-color_soft">{lang="none"}</em>
{{endif}}

{{if $agent}}
	<span data-ipsTooltip title="{$val}">{lang="mobile_app_user_agent" sprintf="$agent->browserVersion, $agent->platform"}</span>
{{elseif mb_strlen( $val ) > 40}}
	<code title="{$val}">{expression="mb_substr( $val, 0, 37 )"}...</code>
{{else}}
	<code>{$val}</code>
{{endif}}

{{if $accessToken['status'] == 'revoked'}}
	<i class="fa-solid fa-xmark" aria-hidden="true"></i> {lang="oauth_status_revoked"}
{{elseif $accessToken['access_token_expires']}}
	{{if $accessToken['access_token_expires'] > time()}}
		<i class="fa-solid fa-check" aria-hidden="true"></i> {lang="oauth_status_active"}
	{{else}}
		{{if $useRefreshTokens and $accessToken['refresh_token']}}
			{{if $accessToken['refresh_token_expires']}}
				{{if $accessToken['refresh_token_expires'] > time()}}
					<i class="fa-solid fa-rotate-right" aria-hidden="true"></i> {lang="oauth_status_refresh"}
				{{else}}
					<i class="fa-solid fa-xmark" aria-hidden="true"></i> {lang="oauth_status_expired"}
				{{endif}}
			{{else}}
				<i class="fa-solid fa-rotate-right" aria-hidden="true"></i> {lang="oauth_status_refresh"}
			{{endif}}
		{{else}}
			<i class="fa-solid fa-xmark" aria-hidden="true"></i> {lang="oauth_status_expired"}
		{{endif}}
	{{endif}}
{{else}}
	<i class="fa-solid fa-check" aria-hidden="true"></i> {lang="oauth_status_active"}
{{endif}}

{{if !request.isSecure()}}
	<div class="ipsMessage ipsMessage--warning i-margin_2">{lang="api_https_warning"}</div>
{{endif}}
<div class="ipsColumns ipsColumns--lines cApiReference" data-controller='core.admin.system.api'>
	<div class="ipsColumns__secondary i-basis_360">
		<h2 class='ipsTitle ipsMinorTitle i-padding-top_2 i-padding-inline_3'>{lang="api_endpoints"}</h2>
			<div class="i-padding_2">
				<ul class="cApiTree i-margin-block_1">
					{{foreach $tree as $app => $controllers}}
						<li>
							<details open>
								<summary>{lang="__app_{$app}"}</summary>
								<i-details-content>
									<ul>
										{{foreach $controllers as $controller => $endpoints}}
											{{if \count( $endpoints ) > 1}}
												<li>
													<details>
														<summary>{lang="__api_{$app}_{$controller}"}</summary>
														<i-details-content>
															<ul>
																{{foreach $endpoints as $key => $endpoint}}
																	<li><a href='{url="app=core&module=applications&controller=api&tab=apiReference&endpoint={$key}"}' data-action='showEndpoint'><code>{expression="\IPS\Api\Controller::parseEndpointForDisplay( $endpoint['title'] )" raw="true"}</code></a></li>
																{{endforeach}}
															</ul>
														</i-details-content>
													</details>
												</li>
											{{else}}
												<li>
													{{foreach $endpoints as $key => $endpoint}}
														<a href='{url="app=core&module=applications&controller=api&tab=apiReference&endpoint={$key}"}' data-action='showEndpoint'><code>{expression="\IPS\Api\Controller::parseEndpointForDisplay( $endpoint['title'] )" raw="true"}</code></a>
													{{endforeach}}
												</li>
											{{endif}}
										{{endforeach}}
									</ul>
								</i-details-content>
							</details>
						</li>
					{{endforeach}}
				</ul>
			</div>
	</div>
	<div class="ipsColumns__primary" data-role="referenceContainer">
		{{if $content}}
			{$content|raw}
		{{endif}}
	</div>
</div>

{{if $multiple}}
<input type="hidden" name="{$name}[__EMPTY]" value="__EMPTY">
{{endif}}
<div data-control="granularCheckboxset" data-count="{expression="\count( $options )"}">
{{if $unlimited !== NULL AND $impliedUnlimited === FALSE}}
<div data-role="checkboxsetUnlimited" class="{{if !\is_array( $value )}}ipsJS_show{{else}}ipsHide{{endif}}">
	<input
		type='checkbox'
		name="{expression="trim( $name, '[]' )"}_unlimited"
	value='{$unlimited}'
	id="{expression="trim( $id ?: $name, '[]' )"}_unlimited"
	{{if $unlimited === $value}}checked{{endif}}
	{{if $disabled}}disabled aria-disabled='true'{{endif}}
	class="ipsSwitch"
	data-role="checkboxsetUnlimitedToggle"
	>
	&nbsp;
	{lang="or"}
	&nbsp;
	<a class="ipsCursor_pointer" data-action="checkboxsetCustomize">{lang="customize"}</a>
</div>
{{endif}}
<div data-role="checkboxsetGranular" class="ipsField__checkboxOverflow {{if $unlimited !== NULL AND $impliedUnlimited === FALSE and !\is_array( $value )}}ipsJS_hide{{endif}}">

	<div class="ipsSpanGrid">
		{{foreach $options as $k => $v}}
        <div class='ipsSpanGrid__3'>Span 3</div>
			<input type="checkbox" class="ipsInput ipsInput--toggle {{if $class}}{$class}{{endif}}" name="{$name}[{$k}]" value="1" {{if ( $unlimited !== NULL AND $unlimited === $value ) or ( \is_array( $value ) AND \in_array( $k, $value ) )}}checked{{endif}} {{if $disabled === TRUE or ( \is_array( $disabled ) and \in_array( $k, $disabled ) )}}disabled{{endif}} {{if isset( $toggles[ $k ] ) and !empty( $toggles[ $k ] )}}data-control="toggle" {{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}} id="elCheckbox_{$name}_{$k}">
			<div class='ipsFieldList__content'>
				<label for='elCheckbox_{$name}_{$k}' id='elField_{$name}_label' data-role="label">{$v|raw}</label>
				{{if isset( $descriptions[ $k ] )}}
					<div class='ipsFieldRow__desc'>
						{$descriptions[ $k ]|raw}
					</div>
				{{endif}}
			</div>
        </div>
		{{endforeach}}
	</div>

	<div class="i-margin-top_1 ipsJS_show ipsField__checkboxOverflow__toggles" data-role="massToggles">
		{lang="or"}
		&nbsp;
		<a class="ipsCursor_pointer" data-action="checkboxsetAll">{lang="all"}</a> / <a class="ipsCursor_pointer" data-action="checkboxsetNone">{lang="none"}</a>
	</div>
</div>
</div>

{{if $application->_disabledMessage}}
	{$application->_disabledMessage}<br>
{{endif}}

{{if !\in_array( $application->directory, \IPS\IPS::$ipsApps )}}
{{if $application->website}}
{{$title = $application->author ?: $application->website();}}
{template="basicUrl" group="global" app="core" location="global" params="$application->website(), TRUE, $title, false, TRUE, TRUE"}
{{elseif $application->author}}
{lang="byline_nodate" sprintf="$application->author"}
{{endif}}
{{endif}}

{{$coverPhoto = $club->coverPhoto( FALSE );}}
{{$memberStatus = $club->memberStatus( \IPS\Member::loggedIn() );}}

<li class="ipsData__item" {{if settings.clubs_require_approval and !$club->approved}}ipsModerated{{endif}}>
	<a href='{$club->url()}' class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{$club->name}</span></a>
	<div class="ipsData__image" aria-hidden="true">
		<a href='{$club->url()}' title="{$club->name}" class='ipsCoverPhoto' data-controller='core.global.core.coverPhoto' data-url="{$club->url()->csrf()}" data-coverOffset='{$coverPhoto->offset}' style='--offset:{$coverPhoto->offset}'>
			{{$cfObject = $coverPhoto->object;}}
			{{if $coverPhoto->file}}
				<div class='ipsCoverPhoto__container'>
					<img src='{$coverPhoto->file->url}' class='ipsCoverPhoto__image' alt='{$club->name}' loading='lazy'>
				</div>
			{{elseif ! empty( $cfObject::$coverPhotoDefault )}}
				<div class='ipsCoverPhoto__container'>
					<div class="ipsFallbackImage" style="--i-empty-image-random--ba-co: {$coverPhoto->object->coverPhotoBackgroundColor()};"></div>
				</div>
			{{endif}}
		</a>
	</div>
	<div class="ipsData__content">
		<div class="ipsData__main">
			<div class="i-flex i-align-items_center i-gap_2">
				<div class="i-flex_00 i-basis_40">{template="clubIcon" group="clubs" app="core" params="$club, 'fluid'"}</div>
				<div class="i-flex_11">
					<div class='ipsData__title'>
						<h2>
							<a href='{$club->url()}' title="{$club->name}">{$club->name}</a>
						</h2>
						<div class="ipsBadges" data-ips-hook="badges">
						    {{foreach $club->badges() as $badge}}{$badge|raw}{{endforeach}}
						</div>
					</div>
					<ul class='ipsList ipsList--sep i-color_soft i-row-gap_0 i-font-size_-1 i-font-weight_500' data-ips-hook="info">
						{{if $club->type != "open"}}
							<li>{lang="club_{$club->type}"}</li>
						{{endif}}
						{{if $club->last_activity}}
							<li>{lang="club_last_activity"} {datetime="$club->last_activity"}</li>
						{{endif}}
					</ul>
				</div>
			</div>
			{{if $club->about}}
				<div class='ipsData__desc'>{$club->about}</div>
			{{endif}}
			{{if ( \in_array( $club->type, array( $club::TYPE_OPEN, $club::TYPE_CLOSED ) ) or \in_array( $memberStatus, array( $club::STATUS_MEMBER, $club::STATUS_MODERATOR, $club::STATUS_LEADER, $club::STATUS_INVITED, $club::STATUS_INVITED_BYPASSING_PAYMENT, $club::STATUS_REQUESTED, $club::STATUS_EXPIRED, $club::STATUS_EXPIRED_MODERATOR ) ) ) and $priceBlurb = $club->priceBlurb()}}
				<div class='i-margin-top_1'>
					<span class="cClubPrice">{$priceBlurb}</span>
					{{if $club->isPaid() and $club->joiningFee() and \IPS\Member::loggedIn()->language()->checkKeyExists('nexus_tax_explain_val')}}
						<span class='cNexusPrice_tax i-color_soft'>{lang="nexus_tax_explain_val"}</span>
					{{endif}}
				</div>
			{{endif}}
		</div>
		{{if $club->type != $club::TYPE_PUBLIC}}
			<div class='i-flex i-align-items_center i-gap_2 i-flex-wrap_wrap i-padding-top_3 i-margin-top_auto'>
				{{if $club->canViewMembers() }}
					<div class="i-flex_11">
						<ul class='ipsCaterpillar i-basis_30'>
							{{foreach $club->randomTenMembers() as $member}}
								<li class='ipsCaterpillar__item'>
									{template="userPhotoFromData" group="global" app="core" params="$member['core_members']['member_id'], $member['core_members']['name'], $member['core_members']['members_seo_name'], \IPS\Member::photoUrl( $member['core_members'] ), 'fluid'"}
								</li>
							{{endforeach}}
						</ul>
					</div>
				{{endif}}
				<div class="i-font-size_-1 i-font-weight_500 i-color_soft">{lang="club_members_count" pluralize="$club->members"}</div>
			</div>
			{{if $club->canJoin()}}
				<div class="i-margin-top_3">
					<a class="ipsButton ipsButton--wide ipsButton--secondary ipsButton--small" href="{$club->url()->setQueryString('do', 'join')->csrf()}" {{if $club->isPaid() and $memberStatus !== $club::STATUS_INVITED_BYPASSING_PAYMENT}}data-confirm data-confirmIcon="info" data-confirmMessage="{lang="club_membership_item"}" data-confirmSubmessage="{$club->memberFeeMessage()}"{{endif}}><i class="fa-solid fa-user-plus" aria-hidden="true"></i>{lang="club_join"}</a>
				</div>
			{{endif}}
		{{endif}}
	</div>
</li>

{{if ! \IPS\Request::i()->isAjax()}}
	{{if \IPS\Settings::i()->clubs_header != 'sidebar'}}
		{template="header" group="clubs" app="core" params="$club"}
	{{endif}}

	<h1 class='ipsTitle ipsTitle--h2 ipsTitle--margin'>{lang="club_rules"}</h1>
{{endif}}

<div id='elClubContainer'>
	{{if ! \IPS\Request::i()->isAjax()}}<div class='ipsBox ipsBox--clubRulesForm'>{{endif}}
		<div class='i-padding_3'>
			<div class='ipsRichText'>{$club->rules|raw}</div>
		</div>
	{{if ! \IPS\Request::i()->isAjax()}}</div>{{endif}}
</div>

{{$memberStatus = $club->memberStatus( \IPS\Member::loggedIn() );}}

<div class="ipsCoverPhotoMeta">
	{{if $position == 'full'}}
		<div class='ipsCoverPhoto__avatar'>
			{template="clubIcon" group="clubs" app="core" params="$club, 'fluid', ''"}
			<!--
			{{if $club->isLeader()}}
				<a href='{$club->url()->setQueryString( 'do', 'editPhoto' )}' class='ipsButton' data-action='editPhoto' data-ipsDialog data-ipsDialog-forceReload='true' data-ipsDialog-modal='true' data-ipsDialog-title='{lang="club_profile_photo"}' title='{lang="club_profile_photo"}' data-ipsTooltip><i class='fa-regular fa-image' aria-hidden="true"></i></a>
			{{endif}}
			-->
		</div>
		<div class='ipsCoverPhoto__titles'>
			<div class='ipsCoverPhoto__title'>
				<h2>
					<a href='{$club->url()}' title='{$club->name}'>{$club->name}</a>
				</h2>
				<div class='ipsBadges' data-ips-hook="badges">
				    {{foreach $club->badges() as $badge}}{$badge|raw}{{endforeach}}
				</div>
			</div>
			<div class='ipsCoverPhoto__subTitle'>
				<ul class='ipsList ipsList--sep' data-ips-hook="clubHeaderLinks">
					<li>{lang="club_{$club->type}"}</li>
					{{if $club->type !== $club::TYPE_PUBLIC}}
						<li>{lang="club_members_count" pluralize="$club->members"}</li>
					{{endif}}
					{{if $club->isLeader() and $club->type === $club::TYPE_CLOSED and $pendingMembers = $club->members( array( $club::STATUS_REQUESTED ), NULL, NULL, 4 )}}
						<li><a href='{$club->url()->setQueryString('do', 'members')->setQueryString('filter', 'requested')->setQueryString('filter', 'requested')}' class='i-color_issue'><i class='fa-solid fa-circle-info' aria-hidden="true"></i> &nbsp;{lang="club_pending_members" pluralize="$pendingMembers"}</a></li>
					{{endif}}
					{{if $club->rules}}
						<li><a href='{$club->url()->setQueryString('do', 'rules')}' data-ipsDialog data-ipsDialog-title='{lang="club_rules"}'>{lang="club_rules"}</a></li>
					{{endif}}
					{{if ( \in_array( $club->type, array( $club::TYPE_OPEN, $club::TYPE_CLOSED ) ) or ( $memberStatus = $club->memberStatus( \IPS\Member::loggedIn() ) and \in_array( $memberStatus, array( $club::STATUS_MEMBER, $club::STATUS_MODERATOR, $club::STATUS_LEADER, $club::STATUS_INVITED, $club::STATUS_INVITED_BYPASSING_PAYMENT, $club::STATUS_REQUESTED, $club::STATUS_EXPIRED, $club::STATUS_EXPIRED_MODERATOR ) ) ) ) and $priceBlurb = $club->priceBlurb()}}
						<li>
							<span>{$priceBlurb}</span>
							{{if $club->isPaid() and $club->joiningFee() and \IPS\Member::loggedIn()->language()->checkKeyExists('nexus_tax_explain_val')}}
								<span class="i-font-size_-2">{lang="nexus_tax_explain_val"}</span>
							{{endif}}
						</li>
					{{endif}}
				</ul>
			</div>
		</div>

		<div class='ipsCoverPhoto__buttons cClubControls__moderate'>
			<a href="#" data-action="saveClubmenu" class="ipsHide ipsButton ipsButton--small ipsButton--positive">{lang="save"}</a>
			<ul class='ipsButtons'>
			    {$club->menu( $container )|raw}
			    {$club->buttons()->contentHtml()|raw}
			</ul>
		</div>
	{{else}}
		<!-- v5 todo: Remove this? -->
		<div class='ipsCoverPhoto__avatar' hidden>
			{template="clubIcon" group="clubs" app="core" params="$club, 'fluid'"}
		</div>
	{{endif}}
</div>

{template="pageHeader" group="global" app="core" params="\IPS\Member::loggedIn()->language()->get('create_club')"}
<div class='ipsBox ipsBox--clubCreate i-padding_3'>
	{$form|raw}
</div>

{{\IPS\Output::i()->cssFiles = array_merge( \IPS\Output::i()->cssFiles, \IPS\Theme::i()->css( 'styles/clubs.css', 'core', 'front' ) );}}

{{$memberStatus = $club->memberStatus( \IPS\Member::loggedIn() );}}

{{if $position == 'full'}}
	<!-- FULL CLUB HEADER -->
	<div id="elClubHeader" class='ipsPageHeader ipsBox ipsBox--clubHeader cClubHeader cClubHeader--main i-margin-bottom_block'>
		{$club->coverPhoto(TRUE, 'full', ( $container ?? $page ) )|raw}
		<div id='elClubControls'>
			<div class='cClubControls__tabs'>
				<i-tabs class='ipsTabs ipsTabs--stretch' id='ipsTabs_club' data-ipsTabBar data-ipsTabBar-disableNav data-controller="core.front.clubs.navbar" data-clubID="{$club->id}">
					<div role='tablist' data-club-menu>
						{{foreach $club->tabs( $container ) as $id => $tab}}
							<a href="{$tab['href']}" class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_club_{$id}_panel" aria-selected="{{if isset( $tab['isActive'] ) AND $tab['isActive']}}true{{else}}false{{endif}}" data-tab="{$id}">{$tab['title']}</a>
						{{endforeach}}
					</div>
					{template="tabScrollers" app="core" group="global" location="global"}
				</i-tabs>
				<div id='elClubTabs_tab_content' class='ipsTabs__panels ipsHide'>
					{{foreach $club->tabs( $container ) as $id => $tab}}
						<div id="ipsTabs_club_{$id}_panel" class="ipsTabs__panel" role="tabpanel" hidden></div>
					{{endforeach}}
				</div>
			</div>
		</div>
	</div>

{{else}}
	<!-- SIDEBAR CLUB HEADER -->
	<div id="elClubHeader_small" class='cClubHeader cClubHeader--sidebar ipsWidget ipsWidget--vertical'>
		{$club->coverPhoto(TRUE, 'sidebar' )|raw}
		<div class='ipsWidget__padding' data-controller="core.front.clubs.navbar" data-clubID="{$club->id}">

			<div class='i-flex i-align-items_center i-gap_2'>
				<div class='i-flex_00 i-basis_50'>
					{template="clubIcon" group="clubs" app="core" params="$club, 'fluid'"}
				</div>
				<div class='i-flex_11'>
					<p class='i-font-weight_600 i-font-size_-1 i-color_soft'>{lang="club_currently_viewing"}</p>
					<h1 class='ipsTitle ipsTitle--h3' data-ips-hook="badges">
					    {{foreach $club->badges() as $badge}}{$badge|raw}{{endforeach}}
						<a href='{$club->url()}'>{$club->name}</a>
					</h1>
				</div>
			</div>

			<ul class='ipsList ipsList--sep i-justify-content_center i-font-weight_600 i-color_soft i-margin-top_2 i-padding-top_2 i-border-top_2'>
				<li>{lang="club_{$club->type}"}</li>
				{{if $club->type !== $club::TYPE_PUBLIC}}
					<li>{lang="club_members_count" pluralize="$club->members"}</li>
				{{endif}}
				{{if $club->isLeader() and $club->type === $club::TYPE_CLOSED and $pendingMembers = $club->members( array( $club::STATUS_REQUESTED ), NULL, NULL, 4 )}}
					<li><a href='{$club->url()->setQueryString('do', 'members')->setQueryString('filter', 'requested')->setQueryString('filter', 'requested')}' class='i-color_issue'><i class='fa-solid fa-circle-info i-margin-end_icon' aria-hidden="true"></i>{lang="club_pending_members" pluralize="$pendingMembers"}</a></li>
				{{endif}}
			</ul>


			{{if $club->type !== \IPS\Member\Club::TYPE_PUBLIC and $club->type !== $club::TYPE_READONLY and $club->canJoin() and request.do != 'rules'}}
				<a class="ipsButton ipsButton--primary i-width_100p i-margin-top_2" href="{$club->url()->setQueryString('do', 'join')->csrf()->addRef( \IPS\Request::i()->url() ) }" {{if $club->isPaid() and $memberStatus !== $club::STATUS_INVITED_BYPASSING_PAYMENT}}data-confirm data-confirmIcon="info" data-confirmMessage="{lang="club_membership_item"}" data-confirmSubmessage="{$club->memberFeeMessage()}"{{endif}}>{lang="club_join"}</a>
			{{endif}}

			{$club->menu( $container ?? $page )|raw}
			<a href="#" data-action="saveClubmenu" class="ipsButton ipsButton--positive i-width_100p ipsHide i-margin-top_2">{lang="save"}</a>

			<div class='ipsSideMenu i-margin-top_2'>
				<ul class='ipsSideMenu__list' data-club-menu>
					{{foreach $club->tabs( $container ) as $id => $tab}}
						<li data-tab="{$id}">
							<a href="{$tab['href']}" class="ipsSideMenu_item {{if isset( $tab['isActive'] ) AND $tab['isActive']}}ipsSideMenu_itemActive{{endif}}" role="tab"> {$tab['title']}</a>
						</li>
					{{endforeach}}
				</ul>
			</div>

			<div class='ipsResponsive_showPhone i-margin-top_2'>
				<button type="button" id="elBrowseClub" popovertarget="elBrowseClub_menu" class='ipsButton ipsButton--inherit i-width_100p'><span>{lang="browse_club"}</span><i class='fa-solid fa-caret-down' aria-hidden="true"></i></button>
				<i-dropdown popover id="elBrowseClub_menu">
					<div class="iDropdown">
						<ul class="iDropdown__items">
							<li class='iDropdown__title'>{lang="browse_club"}</li>
							{{foreach $club->tabs( $container ) as $id => $tab}}
								<li><a href="{$tab['href']}"> {$tab['title']}</a></li>
							{{endforeach}}
						</ul>
					</div>
				</i-dropdown>
			</div>

			<ul class='ipsButtons i-margin-top_2'>
				{$club->buttons()->contentHtml()|raw}
			</ul>
		</div>
	</div>
{{endif}}

{{if \count( $members )}}
<ol class='ipsGrid ipsGrid--lines ipsGrid--clubs-members i-basis_240'>
	{{foreach $members as $member}}
		<li class='i-position_relative i-text-align_center i-padding_3 i-flex i-flex-direction_column i-gap_2' data-ips-js='memberCard'>
			<div class="i-flex i-justify-content_center">
				<div class="i-basis_140">
					{template="userPhotoFromData" group="global" app="core" params="$member['core_members']['member_id'], $member['core_members']['name'], $member['core_members']['members_seo_name'], \IPS\Member::photoUrl( $member['core_members'] ), 'fluid', ''"}
				</div>
			</div>
			<h3 class='i-font-weight_600 i-font-size_3 i-color_hard'>
				{$member['core_members']['name']}
			</h3>
			{{if $club->owner and $member['core_members']['member_id'] === $club->owner->member_id}}
				<div><span class="ipsBadge ipsBadge--positive cClubMemberStatus">{lang="club_owner"}</span></div>
			{{elseif $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_LEADER}}
				<div><span class="ipsBadge ipsBadge--positive cClubMemberStatus">{lang="club_leader"}</span></div>
			{{elseif \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_MODERATOR, \IPS\Member\Club::STATUS_EXPIRED_MODERATOR ) )}}
				<div><span class="ipsBadge ipsBadge--intermediary cClubMemberStatus">{lang="club_moderator"}</span></div>
			{{endif}}
			{{if $club->isLeader() and !\in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_REQUESTED ) ) and ( !$club->owner or $member['core_members']['member_id'] !== $club->owner->member_id )}}
				<button type="button" id="elMember{$member['core_members']['member_id']}Menu" popovertarget="elMember{$member['core_members']['member_id']}Menu_menu" class="ipsButton ipsButton--small ipsButton--soft ipsButton--icon ipsMemberCard_controls"><i class="fa-solid fa-gear" aria-hidden="true"></i> <i class='fa-solid fa-angle-down' aria-hidden="true"></i></button>
				<i-dropdown popover id="elMember{$member['core_members']['member_id']}Menu_menu">
					<div class="iDropdown">
						<ul class="iDropdown__items">
							{{if \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_DECLINED, \IPS\Member\Club::STATUS_BANNED ) )}}
								<li><a href="{$club->url()->setQueryString( array( 'do' => 'reInvite', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm>{lang="club_banned_invite"}</a></li>
							{{else}}
								{{if $club->isPaid() and $club->renewal_price}}
									{{if $member['nexus_purchases']['ps_expire'] or \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_INVITED, \IPS\Member\Club::STATUS_WAITING_PAYMENT ) )}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'bypassPayment', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm data-confirmSubMessage="{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_INVITED}}{lang="club_bypass_fee_renew_warn"}{{else}}{lang="club_bypass_fee_existing_warn"}{{endif}}">{lang="club_bypass_fee"}</a></li>
									{{elseif !$member['nexus_purchases']['ps_expire']}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'restorePayment', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm {{if $member['nexus_purchases']['ps_expire'] === NULL and !\in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_INVITED_BYPASSING_PAYMENT ) )}}data-confirmSubMessage="{lang="club_restore_fee_no_purchase_warn"}"{{endif}}>{lang="club_restore_fee"}</a></li>
									{{endif}}
								{{endif}}
								{{if !\in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_INVITED, \IPS\Member\Club::STATUS_INVITED_BYPASSING_PAYMENT, \IPS\Member\Club::STATUS_WAITING_PAYMENT ) )}}
									{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_LEADER}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'demoteLeader', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm>{lang="club_demote_leader"}</a></li>
									{{else}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'makeLeader', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm data-confirmSubMessage="{lang="club_make_leader_confirm"}">{lang="club_make_leader"}</a></li>
									{{endif}}
									{{if \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_MODERATOR, \IPS\Member\Club::STATUS_EXPIRED_MODERATOR ) )}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'demoteModerator', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm>{lang="club_demote_moderator"}</a></li>
									{{elseif \IPS\Settings::i()->clubs_modperms != -1}}
										<li><a href="{$club->url()->setQueryString( array( 'do' => 'makeModerator', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm data-confirmSubMessage="{lang="club_make_moderator_confirm"}">{lang="club_make_moderator"}</a></li>
									{{endif}}
									<li><a href="{$club->url()->setQueryString( array( 'do' => 'removeMember', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm data-confirmSubMessage="{lang="club_remove_member_confirm"}">{lang="club_remove_member"}</a></li>
								{{else}}
									<li><a href="{$club->url()->setQueryString( array( 'do' => 'removeMember', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm data-confirmSubMessage="{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_INVITED}}{lang="club_remove_accepted_confirm"}{{else}}{lang="club_remove_invitation_confirm"}{{endif}}">{lang="club_remove_invitation"}</a></li>
									<li><a href="{$club->url()->setQueryString( array( 'do' => 'resendInvite', 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-confirm>{lang="club_resend_invitation"}</a></li>
								{{endif}}
							{{endif}}
						</ul>
					</div>
				</i-dropdown>
			{{endif}}

			<div>
				<h4 class='i-font-weight_600'>
					{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_REQUESTED}}
						{lang="club_date_joined_request"}
					{{elseif \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_INVITED, \IPS\Member\Club::STATUS_INVITED_BYPASSING_PAYMENT ) )}}
						{lang="club_date_joined_invite"}
					{{else}}
						{lang="club_date_joined"}
					{{endif}}
				</h4>
				<p>
					{expression="\IPS\DateTime::ts( $member['core_clubs_memberships']['joined'] )->relative()"}
				</p>
			</div>

			{{if $club->isLeader()}}
				{{if $club->isPaid() and $club->renewal_price}}
					{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_INVITED_BYPASSING_PAYMENT}}
						<p class=''>
							{lang="club_fee_waived"}
						</p>
					{{elseif \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_MEMBER, \IPS\Member\Club::STATUS_EXPIRED, \IPS\Member\Club::STATUS_MODERATOR, \IPS\Member\Club::STATUS_EXPIRED_MODERATOR ) )}}
						<hr class='ipsHr ipsHr--small'>
						<h4 class='i-color_soft'>
							{lang="club_membership_renews"}
						</h4>
						<p class=''>
							{{if $member['nexus_purchases']['ps_expire']}}
								{{if !$member['nexus_purchases']['ps_active']}}
								<span class="i-color_warning">
								{{endif}}
								{datetime="$member['nexus_purchases']['ps_expire']"}
								{{if !$member['nexus_purchases']['ps_active']}}
								</span>
								{{endif}}
							{{else}}
								{lang="never"}
							{{endif}}
						</p>
					{{endif}}
				{{endif}}
				{{if ( $member['added_by']['name'] or $member['invited_by']['name'] )}}
					<hr class='ipsHr ipsHr--small'>
					<p class='i-color_soft'>
						{{if \in_array( $member['core_clubs_memberships']['status'], array( \IPS\Member\Club::STATUS_DECLINED, \IPS\Member\Club::STATUS_BANNED ) )}}
							{{if $member['added_by']['name']}}
								{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_BANNED}}
									{lang="club_banned_by" sprintf="$member['added_by']['name']"}
								{{else}}
									{lang="club_declined_by" sprintf="$member['added_by']['name']"}
								{{endif}}
							{{else}}
								{{if $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_BANNED}}
									{lang="club_banned"}
								{{else}}
									{lang="club_declined"}
								{{endif}}
							{{endif}}
						{{else}}
							{{if $member['invited_by']['name']}}
								{lang="club_invited_by" sprintf="$member['invited_by']['name']"}
							{{else}}
								{lang="club_added_by" sprintf="$member['added_by']['name']"}
							{{endif}}
						{{endif}}
					</p>
				{{endif}}
			{{endif}}


			{{if $club->isLeader() && $member['core_clubs_memberships']['status'] === \IPS\Member\Club::STATUS_REQUESTED}}
				<hr class='ipsHr ipsHr--small'>
				<ul class='i-flex i-gap_1 ipsMemberCard_buttons'>
					<li class='i-flex_11'>
						{{if $club->isPaid()}}
							<ul class="ipsButtons">
								<li>
									<a href="{$club->url()->setQueryString( array( 'do' => 'acceptRequest', 'member' => $member['core_members']['member_id'] ) )->csrf()}" class="ipsButton ipsButton--positive" data-ipsTooltip title='{lang="club_accept_request"}' data-action='requestApprove'>
										<i class='fa-solid fa-check' aria-hidden="true"></i>
									</a>
								</li>
								<li>
									<button type="button" id="elMember{$member['core_members']['member_id']}AcceptMenu" popovertarget="elMember{$member['core_members']['member_id']}AcceptMenu_menu" class="ipsButton ipsButton--positive ipsButton--icon"><i class='fa-solid fa-caret-down' aria-hidden="true"></i></button>
									<i-dropdown popover id="elMember{$member['core_members']['member_id']}AcceptMenu_menu" data-role="acceptMenu">
										<div class="iDropdown">
											<ul class="iDropdown__items">
												<li><a href="{$club->url()->setQueryString( array( 'do' => 'acceptRequest', 'waiveFee' => 1, 'member' => $member['core_members']['member_id'] ) )->csrf()}" data-action='requestApprove'>{lang="club_bypass_fee"}</a></li>
											</ul>
										</div>
									</i-dropdown>
								</li>
							</ul>
						{{else}}
							<a href="{$club->url()->setQueryString( array( 'do' => 'acceptRequest', 'member' => $member['core_members']['member_id'] ) )->csrf()}" class="ipsButton ipsButton--positive ipsButton--wide" data-ipsTooltip title='{lang="club_accept_request"}' data-action='requestApprove'><i class='fa-solid fa-check' aria-hidden="true"></i></a>
						{{endif}}
					</li>
					<li class='i-flex_11'>
						<a href="{$club->url()->setQueryString( array( 'do' => 'declineRequest', 'member' => $member['core_members']['member_id'] ) )->csrf()}" class="ipsButton ipsButton--negative ipsButton--wide" data-ipsTooltip title='{lang="club_decline_request"}' data-action='requestDecline'><i class='fa-solid fa-xmark' aria-hidden="true"></i></a>
					</li>
				</ul>
			{{endif}}
		</li>
	{{endforeach}}
</ol>
{{else}}
	<div class="ipsEmptyMessage">{lang="no_results"}</div>
{{endif}}

{{if member.member_id and member.group['g_create_clubs']}}
	<div><a class="ipsButton ipsButton--large ipsButton--primary i-width_100p" href="{url="app=core&module=clubs&controller=directory&do=create" seoTemplate="clubs_list"}" data-ipsDialog data-ipsDialog-title="{lang="create_club"}"><i class="fa-solid fa-users" aria-hidden="true"></i><span>{lang="create_club"}</span></a></div>
{{endif}}

{{if \count( $myClubsInvites )}}
	<div id='elMyClubsInvites' class="ipsWidget ipsWidget--vertical">
		<h2 class="ipsWidget__header">{lang="my_clubs_invites"}</h2>
		<section class="ipsWidget__content">
			<i-data>
				<ul class='ipsData ipsData--table ipsData--my-clubs-sidebar'>
					{{foreach $myClubsInvites as $club}}
					<li class='ipsData__item'>
						<div class='ipsData__icon'>{template="clubIcon" group="clubs" app="core" params="$club, 'fluid'"}</div>
						<div class='ipsData__main'>
							<h3 class='ipsData__title'><a href='{$club->url()}'>{$club->name}</a></h3>
							<div class='ipsData__meta'>
								<ul class='ipsList ipsList--sep'>
									<li>{lang="club_{$club->type}"}</li>
									{{if $club->type !== $club::TYPE_PUBLIC}}
										<li>{lang="club_members_count" pluralize="$club->members"}</li>
									{{endif}}
								</ul>
							</div>
						</div>
						<div class="ipsButtons i-gap_1">
							<a class="ipsButton ipsButton--inherit ipsButton--small i-color_negative" data-ipstooltip title='{{if $club->status !== $club::STATUS_REQUESTED}}{lang="club_decline_invite"}{{else}}{lang="club_cancel_request"}{{endif}}' href="{$club->url()->setQueryString('do', 'leave')->csrf()}" data-confirm>
								<i class="fa-solid fa-xmark" aria-hidden="true"></i>
							</a>
							{{if $club->status !== $club::STATUS_REQUESTED}}
								<a class="ipsButton ipsButton--positive ipsButton--small" data-ipstooltip title='{lang="club_join"}' href="{$club->url()->setQueryString('do', 'join')->csrf()}" {{if $club->isPaid() and $club->status !== $club::STATUS_INVITED_BYPASSING_PAYMENT}}data-confirm data-confirmIcon="info" data-confirmMessage="{lang="club_membership_item"}" data-confirmSubmessage="{$club->memberFeeMessage()}"{{endif}}>
									<i class="fa-solid fa-check" aria-hidden="true"></i>
								</a>
							{{endif}}
						</div>
					</li>
					{{endforeach}}
				</ul>
			</i-data>
		</section>
