{{$url = $node->_importedIntoUrl;}}
{{if $url}}
    <a href="{$url}" target="_blank" data-ipsToolTip title="{$url}" class="ipsBadge ipsBadge--style6">{$node->_application->_title} <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a>
{{else}}
    <span class="ipsBadge ipsBadge--style6">{$node->_application->_title}</span>
{{endif}}

{{$valueAsArray = \is_array( $value ) ? $value : ( \is_string( $value ) ? explode( ',', $value ) : [] );}}
{{$valueToDisplay = \is_array( $value ) ? implode( "\n", $value ) : $value;}}

{{if ( !isset( $autoComplete['commaTrigger'] ) || $autoComplete['commaTrigger'] !== FALSE )}}
	{{// If the stored value has commas in it, we need to explode then implode to get the newlines}}
	{{if $valueToDisplay and mb_stripos( $valueToDisplay, ',') !== FALSE}}
		{{$valueToDisplay = implode("\n", explode(",", $valueToDisplay));}}
	{{endif}}	
{{endif}}

<div>
{{if ( isset( $autoComplete['freeChoice'] ) && !$autoComplete['freeChoice'] ) || ( isset( $autoComplete['prefix'] ) and $autoComplete['prefix'] ) }}
<div {{if isset( $autoComplete['freeChoice'] ) && !$autoComplete['freeChoice']}}class="ipsJS_show"{{endif}} {{if isset( $autoComplete['prefix'] ) and $autoComplete['prefix']}}data-controller='core.global.core.prefixedAutocomplete'{{endif}}>
{{endif}}
{{if isset( $autoComplete['prefix'] ) and $autoComplete['prefix']}}
	<div data-role='prefixRow' class='ipsHide' id='{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}_prefixWrap'>
		<input type='checkbox' name='{$name}_freechoice_prefix' {{if isset($valueAsArray['prefix'])}}checked{{endif}} class='ipsJS_hide'> <button type="button" id="{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}_prefix" popovertarget="{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}_prefix_menu" data-role="prefixButton" class='ipsButton ipsButton--soft ipsButton--small'><span>{{if isset($valueAsArray['prefix'])}}{$valueAsArray['prefix']}{{else}}{lang="select_prefix"}{{endif}}</span> <i class='fa-solid fa-caret-down' aria-hidden="true"></i></button>
		<input type='hidden' data-role='prefixValue' name='{$name}_prefix' value='{{if isset($valueAsArray['prefix'])}}{$valueAsArray['prefix']}{{endif}}'>
		<i-dropdown popover id="{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}_prefix_menu" data-i-dropdown-selectable="radio">
			<div class="iDropdown">
				<ul class="iDropdown__items" data-role="prefixMenu">
					<li>
						<button type="button" data-ipsMenuValue='-' aria-selected="true">{lang="no_prefix"}</button>
					</li>
					<li>
						<hr>
					</li>
				</ul>
			</div>
		</i-dropdown>
	</div>
	<noscript>
		<input type="hidden" name="{$name}_first_as_prefix" value="0">
		{{$valueKeys = \is_array( $value ) ? array_keys( $value ) : array_keys( explode( ',', $value ) );}}
		<input type="checkbox" name="{$name}_first_as_prefix" value="1" id="{$name}_first_as_prefix" {{if array_shift( $valueKeys ) === 'prefix'}}checked{{endif}}> <label for="{$name}_first_as_prefix">{lang="use_first_tag_as_prefix"}</label>
	</noscript>
{{endif}}
<textarea
	name="{$name}"
	id='elInput_{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}'
	class="ipsInput ipsInput--text {$class}"
	{{if $maxlength !== NULL}}maxlength="{$maxlength}"{{endif}}
	{{if $required === TRUE}}aria-required='true'{{endif}}
	{{if $disabled}}disabled aria-disabled='true'{{endif}}
	{{if $placeholder}}placeholder="{$placeholder}"{{endif}}
	data-ipsAutocomplete
	{{if isset( $autoComplete['freeChoice'] ) && !$autoComplete['freeChoice']}}data-ipsAutocomplete-freeChoice='false'{{endif}}
    {{if isset( $autoComplete['suggestionsOnly'] ) && $autoComplete['suggestionsOnly']}}data-ipsautocomplete-suggestionsOnly="true"{{endif}}
	{{if isset( $autoComplete['forceLower'] ) && $autoComplete['forceLower']}}data-ipsAutocomplete-forceLower{{endif}}
	data-ipsAutocomplete-lang='{{if isset( $autoComplete['lang'] ) && $autoComplete['lang']}}{$autoComplete['lang']}{{else}}ac_optional{{endif}}'
	{{if isset( $autoComplete['maxItems'] )}}data-ipsAutocomplete-maxItems='{$autoComplete['maxItems']}'{{endif}}
	{{if isset( $autoComplete['addTokenText'] )}}data-ipsAutocomplete-addTokenText='{$autoComplete['addTokenText']}'{{endif}}
	{{if isset( $autoComplete['addTokenTemplate'] )}}data-ipsAutocomplete-addTokenTemplate='{$autoComplete['addTokenTemplate']}'{{endif}}
	{{if !empty($autoComplete['unique'])}}
		data-ipsAutocomplete-unique
	{{endif}}
	{{if isset($autoComplete['source']) AND \is_array( $autoComplete['source'] )}}
		list='{$name}_datalist'
	{{elseif !empty($autoComplete['source'])}}
		data-ipsAutocomplete-dataSource="{url="{$autoComplete['source']}"}"
		data-ipsAutocomplete-queryParam='input'
	{{endif}}
	{{if !empty($autoComplete['resultItemTemplate'])}}
		data-ipsAutocomplete-resultItemTemplate="{$autoComplete['resultItemTemplate']}"
	{{endif}}
	{{if isset( $autoComplete['minLength'] )}}data-ipsAutocomplete-minLength='{$autoComplete['minLength']}'{{endif}}
	{{if isset( $autoComplete['maxLength'] )}}data-ipsAutocomplete-maxLength='{$autoComplete['maxLength']}'{{endif}}
	{{if isset( $autoComplete['minAjaxLength'] )}}data-ipsAutocomplete-minAjaxLength='{$autoComplete['minAjaxLength']}'{{endif}}
	{{if isset( $autoComplete['disallowedCharacters'] )}}data-ipsAutocomplete-disallowedCharacters='{expression="json_encode( $autoComplete['disallowedCharacters'] )"}'{{endif}}
	{{if isset( $autoComplete['commaTrigger'] ) && $autoComplete['commaTrigger'] === FALSE}}data-ipsAutocomplete-commaTrigger='false'{{endif}}
	{{if isset( $autoComplete['minimized'] )}}data-ipsAutocomplete-minimized{{endif}}
>{{if $valueToDisplay}}{$valueToDisplay}{{endif}}</textarea>

{{if ( isset( $autoComplete['freeChoice'] ) && !$autoComplete['freeChoice'] ) || ( isset( $autoComplete['prefix'] ) and $autoComplete['prefix'] ) }}
</div>
{{endif}}
</div>

{{if isset( $autoComplete['desc'] )}}
	<div class='ipsFieldRow__desc'>
		{$autoComplete['desc']|raw}
	</div>
{{endif}}

{{if $nullLang}}
	<div class="ipsFieldRow__inlineCheckbox i-margin-top_1">
		{lang="or"} 
		<input type="checkbox" data-control="unlimited" name="{$name}_null" id="{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null" value="1" {{if $value === NULL}}checked{{endif}} {{if $disabled}}disabled{{endif}} aria-controls='{$name}' aria-labelledby='{$name}_null_label' class="ipsInput ipsInput--toggle">
		<label for='{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null' id='{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null_label' class='ipsField_unlimited'>{lang="$nullLang"}</label>
	</div>
{{endif}}

{{if isset($autoComplete['source']) AND \is_array( $autoComplete['source'] )}}
	<datalist id="{$name}_datalist">
	    {{if isset( $autoComplete['formatSource'] ) and $autoComplete['formatSource']}}
	        {{foreach $autoComplete['source'] as $k => $v}}
	            <option value="{$k}">{$v|raw}</option>
	        {{endforeach}}
	    {{else}}
		    {{foreach $autoComplete['source'] as $v}}
			    <option value="{$v}">{$v}</option>
		    {{endforeach}}
		{{endif}}
	</datalist>
{{endif}}

{{if $type === 'link'}}
	<a href="{$href}" class='{{if ! $class or ! mb_stristr( $class, 'ipsButton' )}}ipsButton ipsButton--text{{endif}} {{if $class}}{$class}{{endif}}' {{if $attributes}}{{foreach $attributes as $key => $value}}{$key}="{$value}"{{endforeach}}{{endif}}>{lang="$lang"}</a>
{{else}}
	<button type="{$type}" {{if $class}}class="{$class}"{{endif}} {{if $attributes}}{{foreach $attributes as $key => $value}}{$key}="{$value}" {{endforeach}}{{endif}}>{lang="$lang"}</button>
{{endif}}

{{if $id === NULL}}
    {{$id = md5(uniqid());}}
{{endif}}
<input type="hidden" name="{$hiddenName}" value="0">
	<input
		type='checkbox'
		name='{$name}'
		value='1'
		id="check_{$id}"
		data-toggle-id="{$id}"
		{{if $value}}checked{{endif}}
		{{if $disabled}}disabled aria-disabled='true'{{endif}}
		{{if !empty($togglesOn) OR !empty($togglesOff)}}
			data-control="toggle"
		{{endif}}
		{{if !empty($togglesOn)}} data-togglesOn="{expression="implode( ',', $togglesOn )"}" aria-controls="{expression="implode( ' ', $togglesOn )"}"{{endif}}
		{{if !empty($togglesOff)}} data-togglesOff="{expression="implode( ',', $togglesOff )"}" aria-controls="{expression="implode( ' ', $togglesOff )"}"{{endif}}
		{{if $tooltip}}title='{$tooltip}' data-ipsTooltip{{endif}}
		{{if $fancyToggle}}
			class='ipsSwitch'
		{{else}}
			class='ipsInput ipsInput--toggle'
		{{endif}}
	>
{{if $label}}
<label for="check_{$id}">
	{lang="$label"}
</label>
{{endif}}

{{if $multiple}}
	<input type="hidden" name="{$name}[__EMPTY]" value="__EMPTY">
{{endif}}
<div data-control="granularCheckboxset"{{if $condense}} data-count="{expression="\count( $options )"}"{{endif}}>
	{{if $unlimited !== NULL AND $impliedUnlimited === FALSE}}
			<div data-role="checkboxsetUnlimited" class="{{if !\is_array( $value )}}ipsJS_show{{else}}ipsHide{{endif}}">
				<input
					type='checkbox'
					name="{expression="trim( $name, '[]' )"}_unlimited"
					value='{$unlimited}'
					id="{expression="trim( $id ?: $name, '[]' )"}_unlimited"
					{{if $unlimited === $value}}checked{{endif}}
					{{if $disabled}}disabled aria-disabled='true'{{endif}}
					class="ipsSwitch"
					data-role="checkboxsetUnlimitedToggle"
				>
				&nbsp;
				{lang="or"}
				&nbsp;
				<a class="i-cursor_pointer" data-action="checkboxsetCustomize">{lang="customize"}</a>
			</div>
	{{endif}}
	<div data-role="checkboxsetGranular" class="ipsField__checkboxOverflow {{if $unlimited !== NULL AND $impliedUnlimited === FALSE and !\is_array( $value )}}ipsJS_hide{{endif}}">
	{{$userInput = \is_array( $value ) ? array_diff( $value, array_keys( $options ) ) : array();}}
		<input type="search" data-role="search" placeholder="{lang="search"}" class="ipsInput ipsField__checkboxOverflow__search" />
		<ul class="ipsFieldList">
			{{foreach $options as $k => $v}}
				<li data-role="result">
					<input type="checkbox" {{if $class}}class="{$class}"{{endif}} name="{$name}[{$k}]" value="1" {{if ( $unlimited !== NULL AND $unlimited === $value ) or ( \is_array( $value ) AND \in_array( $k, $value ) ) or ( $userSuppliedInput AND count( $userInput ) AND $k == $userSuppliedInput )}}checked{{endif}} {{if $disabled === TRUE or ( \is_array( $disabled ) and \in_array( $k, $disabled ) )}}disabled{{endif}} {{if isset( $toggles[ $k ] ) and !empty( $toggles[ $k ] )}}data-control="toggle" {{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}} id="elCheckbox_{$name}_{$k}" class="ipsInput ipsInput--toggle">
					<div class='ipsFieldList__content'>
						<label for='elCheckbox_{$name}_{$k}' id='elField_{$name}_label' data-role="label">{$v|raw}</label>
						{{if isset( $descriptions[ $k ] )}}
							<div class='ipsFieldRow__desc'>
								{$descriptions[ $k ]|raw}
							</div>
						{{endif}}
					</div>
				</li>
			{{endforeach}}
		</ul>
        {{if $userSuppliedInput}}
        <div id='{$userSuppliedInput}' class='i-margin-top_1'>
            <input type='text' class='ipsInput ipsInput--text' name='{$userSuppliedInput}_{$name}' value='{expression="implode( ',', $userInput )"}'>
        </div>
        {{endif}}

		{{if $showAllNone}}
		<div class="ipsJS_show ipsField__checkboxOverflow__toggles" data-role="massToggles">
			{lang="or"}
			&nbsp;
			<button data-action="checkboxsetAll" type="button">{lang="all"}</button> / <button data-action="checkboxsetNone" type="button">{lang="none"}</button>
		</div>
		{{endif}}
	</div>
</div>

{{if !empty( $tags ) OR $tagSource !== NULL}}
<div class='ipsColumns ipsCodebox__outer-wrap' data-controller='core.global.editor.customtags' data-tagFieldType='codemirror' data-tagFieldID='elCodemirror_{{if $id}}{$id}{{else}}{$name}{{endif}}' {{if $tagSource}}data-tagSource='{$tagSource}'{{endif}}>
	<div class='ipsColumns__primary'>
{{endif}}
<div class='i-background_3 i-padding_2 ipsCodebox__inner-wrap' data-role="editor" {{if $preview}}data-controller="core.global.editor.codePreview" data-name="{$name}" data-preview-url="{$preview}"{{endif}}>
	<textarea
	name="{$name}"
	id='elCodemirror_{{if $id}}{$id}{{else}}{$name}{{endif}}'
	value="{expression="htmlentities( $value === NULL ? '' : $value, ENT_DISALLOWED, 'UTF-8', TRUE )"}"
	class="ipsInput ipsInput--text ipsInput--wide {$class}"
	{{if $maxlength !== NULL}}maxlength="{$maxlength}"{{endif}}
	{{if $required === TRUE}}aria-required='true'{{endif}}
	{{if $disabled}}disabled aria-disabled='true'{{endif}}
	{{if $placeholder}}placeholder="{$placeholder}"{{endif}}
	data-control="codemirror"
	data-mode="{$mode}"
	{{if $height}}data-height="{$height}"{{endif}}
>{{if $value}}{$value}{{endif}}</textarea>
	{{if $preview}}
		<button type="button" data-action="preview" data-ipsDialog data-ipsDialog-content="#{$name}_preview" class="ipsButton ipsButton--soft i-margin-top_3 ipsButton--small ipsJs_hide"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i> {lang="preview"}</button>
		<div id="{$name}_preview" class="ipsHide ipsDialog_loading"></div>
	{{endif}}
</div>

{{if !empty( $tags ) OR $tagSource}}
	</div>
	<div class='ipsColumns__secondary ipsComposeArea_sidebar' data-codemirrorid='elCodemirror_{{if $id}}{$id}{{else}}{$name}{{endif}}'>
		<h3 class='i-padding_2 ipsTitle ipsTitle--h5' data-role='tagsHeader'>{lang="editor_tags"}</h3>
		<ul class='ipsScrollbar' data-role='tagsList'>
		{{if !empty( $tags )}}
			{template="editorTags" app="core" location="global" group="forms" params="$tags, $tagLinks"}
		{{endif}}
		</ul>
	</div>
</div>
{{endif}}

{{$minimized = false;}}
<form accept-charset='utf-8' class="ipsFormWrap ipsFormWrap--comment" action="{$action}" method="post" {{if $uploadField}}enctype="multipart/form-data"{{endif}}>
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		<input type="hidden" name="{$k}" value="{$v}">
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	<div data-role='whosTyping' class='ipsHide i-margin-bottom_2'></div>
	<div class='ipsComposeArea'>
		<div class='ipsComposeArea__photo'>{template="userPhoto" app="core" group="global" params="\IPS\Member::loggedIn(), 'fluid'"}</div>
		<div class='ipsComposeArea_editor'>
			{{foreach $elements as $collection}}
				{{foreach $collection as $input}}
					{{if $input->name == 'guest_name' or $input->name == 'guest_email' or $input instanceof \IPS\Helpers\Form\Select}}
						<ul class='ipsForm ipsForm--vertical ipsForm--guest-post' data-ipsEditor-toolList>
							<li class='ipsFieldRow ipsFieldRow--fullWidth i-padding_0 i-margin-bottom_2'>
								<div class="ipsFieldRow__content">
									{$input->html()|raw}
									{{if $input->error}}
										<div class="ipsFieldRow__warning" data-role="commentFormError">{lang="$input->error"}</div>
									{{endif}}
								</div>
							</li>
						</ul>
					{{endif}}
				{{endforeach}}
			{{endforeach}}
			{{foreach $elements as $collection}}
				{{foreach $collection as $input}}
					{{if $input instanceof \IPS\Helpers\Form\Editor}}
						{{if $input->options['minimize'] !== NULL}}
							{{$minimized = true;}}
						{{endif}}
						{$input->html( TRUE )|raw}
						{{if $input->error}}
							<div class="ipsFieldRow__warning" data-role="commentFormError">{lang="$input->error"}</div>
						{{endif}}
					{{endif}}
				{{endforeach}}
			{{endforeach}}
			<div class='i-flex i-align-items_center i-flex-wrap_wrap i-gap_3 i-margin-top_2' data-ipsEditor-toolList {{if $minimized}}hidden{{endif}}>
				<ul class='i-flex_91 i-flex i-flex-wrap_wrap i-gap_4 i-row-gap_1'>
					{{foreach $elements as $collection}}
						{{foreach $collection as $input}}
							{{if !($input instanceof \IPS\Helpers\Form\Select) && !($input instanceof \IPS\Helpers\Form\Editor) && $input->name != 'guest_name' && $input->name != 'guest_email' && $input->name != 'assign_content_to'}}
								<li class='{{if !($input instanceof \IPS\Helpers\Form\Captcha)}}ipsComposeArea_formControl{{endif}}'>
									{$input->html()|raw}
									{{if $input->error}}
										<div class="ipsFieldRow__warning" data-role="commentFormError">{lang="$input->error"}</div>
									{{endif}}
								</li>
							{{endif}}
						{{endforeach}}
					{{endforeach}}
				</ul>
				<ul class='ipsButtons i-flex_11'>
				    {{foreach $elements as $collection}}
				        {{foreach $collection as $input}}
				            {{if $input->name == 'assign_content_to'}}
				                <li>{{if $input->value}}<span class='ipsHide i-font-weight_bold i-color_soft' data-role='assignmentPrefix'>{lang="assigned_to"} </span>{{endif}}{$input->html()|raw}</li>
				            {{endif}}
                    	{{endforeach}}
                    {{endforeach}}
					{{foreach $actionButtons as $button}}
						<li>{$button|raw}</li>
					{{endforeach}}
				</ul>
			</div>
		</div>
	</div>
</form>

{lang="$lang"} 

{{if \count( $warnings) }}
	{{foreach $warnings as $idx => $warning}}
		{{if $idx === 0}}
			<br><br>
			<a href="{$warning->url()}" data-ipsDialog data-ipsDialog-size='narrow' class='ipsButton ipsButton--small ipsButton--soft'>{lang="view_warning_details"}</a>
		{{endif}}
	{{endforeach}}
{{endif}}

{lang="between"} {$start|raw} {lang="and"} {$end|raw}
{{if $unlimited !== NULL}}
	&nbsp;
	{lang="or"}
	&nbsp;
	<input type="checkbox" data-control="unlimited{{if \count( $toggles )}} toggle{{endif}}" name="{$unlimitedName}" id='{$unlimitedName}' value="{$unlimited}" {{if $unlimitedChecked}}checked{{endif}} {{if \count( $toggles )}}{{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $toggles )"}"{{endif}} aria-labelledby='label_{$unlimitedName}' class="ipsInput ipsInput--toggle">
	<label for='{$unlimitedName}' id='label_{$unlimitedName}' class='ipsField_unlimited'>{lang="$unlimitedLang"}</label>
{{endif}}

{{if $container and \IPS\IPS::classUsesTrait( $container, 'IPS\Content\ClubContainer' ) and $club = $container->club()}}
	{{if settings.clubs and settings.clubs_header == 'full'}}
		{template="header" app="core" group="clubs" params="$club, $container"}
	{{endif}}
{{endif}}

{{/*}}
<!-- This form is used for editing certain types of content: Downloads, Courses, etc -->
{{*/}}

<header class="ipsPageHeader ipsPageHeader--edit-content">
	<h1 class="ipsPageHeader__title">{$title}</h1>
</header>
{$form|raw}

{{if ! empty( $options['profanityBlock'] ) and \is_array( $options['profanityBlock'] )}}
	<div data-role='editorCensorBlock' data-controller='core.global.editor.censorBlock' data-censorBlockWords='{expression="json_encode($options['profanityBlock'])"}' data-editorID='{$name}' class='ipsHide i-margin-bottom_3 i-background_2 i-padding_2 ipsLoading--small'>
		<div class="ipsMessage ipsMessage--warning">
			{lang="profanity_block_public_explanation"}
		</div>
		<div data-role="editorCensorBlockMessage" class="ipsRichText"><div data-role="editorCensorBlockMessageInternal"></div></div>
	</div>
{{endif}}
<div class='ipsEditor' data-ipsEditorv5
    {{if $options['minimize'] !== NULL}}data-ipsEditorv5-minimized{{endif}}

    {{if $postKey}}
        data-ipsEditorv5-postKey="{$postKey}"
    {{endif}}

    {{if $options['autoSaveKey']}}
        data-ipsEditorv5-autoSaveKey="{$options['autoSaveKey']}"
    {{endif}}

    data-ipsEditorv5-name="{$name}"

    {{if $contentClass AND $contentId}}
        data-ipsEditorv5-contentClass='{$contentClass}'
        data-ipsEditorv5-contentId='{$contentId}'
    {{endif}}

    {{if @$options['comments']}}data-ipseditorv5-commenteditor{{endif}}

    {{if settings.giphy_enabled}}data-ipseditorv5-giphyenabled{{endif}}
    {{if \IPS\core\StoredReplies::enabledRepliesExist()}}data-ipseditorv5-stockrepliesenabled{{endif}}
    {{if $options['loadPlugins']}}data-ipseditorv5-loadplugins{{endif}}
    data-ipseditorv5-restrictions="{expression='implode(",",\IPS\Helpers\Form\Editor::getMemberRestrictions( comments: (bool) $options["comments"] ) )'}"
    data-ipseditorv5-restrictionlevel="{expression='\IPS\Helpers\Form\Editor::getMemberRestrictionLevel( comments: (bool) $options["comments"] )'}"
>

	<div data-role='editorComposer'>
		<div {{if $options['minimize']}}class="ipsHide norewrite"{{else}}class="norewrite ipsLoading"{{endif}} data-role="mainEditorArea">
			<textarea name="{$name}" data-role='contentEditor' class="ipsInput ipsInput--text ipsHide">{$value|doubleencode}</textarea>
		</div>
		{{if $options['minimize']}}
			<div class='ipsComposeArea_dummy ipsJS_show'><i class='fa-regular fa-comment' aria-hidden="true"></i> {lang="$options['minimize']"}</div>
		{{endif}}

        <div data-role="editor-messages-container"></div>
		{$uploadControl|raw}
	</div>
</div>

{{foreach $tags as $tagKey => $tagValue}}
	{{if \is_array( $tagValue )}}
		<li>
			<ul>
				<li>
					<h4 class='i-color_hard i-font-weight_500 i-background_3 i-padding_2 i-flex i-align-items_center i-gap_2'>
						<span>{lang="$tagKey"}</span>
						{{if isset( $tagLinks[$tagKey] )}}
							<a href='{$tagLinks[$tagKey]['link']}' data-customtags-dialog class='ipsButton ipsButton--inherit ipsButton--small i-margin-start_auto' target='_blank' {{if isset( $tagLinks[$tagKey]['data'] )}}{{foreach $tagLinks[$tagKey]['data'] AS $dataKey => $dataValue}}data-{$dataKey}='{$dataValue}'{{endforeach}}{{endif}} {{if isset( $tagLinks[$tagKey]['title'] )}}title='{$tagLinks[$tagKey]['title']}' data-ipsTooltip{{endif}}>
								<i class='fa-solid fa-{$tagLinks[$tagKey]['icon']}' aria-hidden="true"></i>
							</a>
						{{endif}}
					</h4>
				</li>
				<li>
					<ul data-role='tagList_{$tagKey}'>
					{{foreach $tagValue as $key => $value}}
						<li>
							<button type="button" data-tagKey="{$key}">
								<code class="language-ipsphtml">{$key}</code>
								{{if $value}}<div class='i-color_soft i-font-size_-2 i-margin-top_1'>{$value}</div>{{endif}}
                            </button>
						</li>
					{{endforeach}}
					</ul>
				</li>
			</ul>
		</li>
	{{else}}
		<li>
			<button type="button" data-tagKey="{$tagKey}">
				<code class="language-ipsphtml">{$tagKey}</code>
				{{if $tagValue}}<div class='i-color_soft i-font-size_-2 i-margin-top_1'>{$tagValue}</div>{{endif}}
			</button>
			{{if isset( $tagLinks[$tagKey] )}}
				<a href='{$tagLinks[$tagKey]['link']}' target='_blank' data-customtags-dialog {{if isset( $tagLinks[$tagKey]['data'] )}}{{foreach $tagLinks[$tagKey]['data'] AS $dataKey => $dataValue}}data-{$dataKey}='{$dataValue}'{{endforeach}}{{endif}} {{if isset( $tagLinks[$tagKey]['title'] )}}title='{$tagLinks[$tagKey]['title']}' data-ipsTooltip{{endif}}'>
					<i class='fa-solid fa-{$tagLinks[$tagKey]['icon']}' aria-hidden="true"></i>
				</a>
			{{endif}}
		</li>
	{{endif}}
{{endforeach}}

{{if $value}}
	<div class="">
		<ul class="ipsList ipsList--inline">
			<li>
				{{if $value['protocol'] === 'sftp'}}
					<span class="ipsBadge ipsBadge--style1">SFTP</span>
				{{elseif $value['protocol'] === 'ssl_ftp'}}
					<span class="ipsBadge ipsBadge--style6">{lang="ftp_with_ssl"}</span>
				{{endif}}
				<span class="i-font-family_monospace">{$value['server']}{{if $value['port']}}:{$value['port']}{{endif}}</span>
			</li>
			<li>
				<i class="fa-solid fa-user" aria-hidden="true"></i> <span class="i-font-family_monospace">{$value['un']}</span>
			</li>
			<li>
				<i class="fa-solid fa-lock" aria-hidden="true"></i> <span class="i-font-family_monospace">{$value['pw']}</span>
			</li>
			{{if $value['path']}}
				<li>
					<i class="fa-solid fa-folder" aria-hidden="true"></i> <span class="i-font-family_monospace">{$value['path']}</span>
				</li>
			{{endif}}
			{{if $url}}
				<li>
					<a href="{$url}" class="ipsButton ipsButton--soft ipsButton--tiny">{lang="connect"}</a>
				</li>
			{{endif}}
		</ul>
	</div>
{{endif}}

{{$idField = $item::$databaseColumnId;}}
<div data-itemid="{$item->$idField}" data-role='contentItemRow'>
	<strong>{$item->mapped('title')}</strong>
	{{if $item->container()}}
		<em>{lang="item_selector_added_to_container" sprintf="$item->container()->_title"}</em>
	{{endif}}
	{{if isset( $item::$databaseColumnMap['date'] )}}
		<span class='i-color_soft'>{lang="item_selector_added_on" htmlsprintf="\IPS\DateTime::ts($item->mapped('date'))->html( false )"}</span>
	{{endif}}	
</div>

{{if empty( $nodes )}}
	<p class='i-padding_2 i-color_soft'>{lang="no_results"}</p>
{{else}}
	<ul>
		{{foreach $nodes as $node}}
			{{if $clubs === NULL or ( $clubs === TRUE and $node->club() ) or ( $clubs === FALSE and !$node->club() )}}
				<li>
					{{if ( $permCheck === NULL or $node->can( $permCheck ) ) and ( $disabledCallback === NULL or $disabledCallback( $node ) ) and !\in_array( $node->_id, $disabledArray )}}
						<div data-action="nodeSelect" class='ipsSelectTree_item {{if $node->hasChildren( 'view', NULL, $subnodes, $where )}}ipsSelectTree_withChildren{{endif}} {{if $autoPopulate AND isset( $children[ $node->_id ] )}}ipsSelectTree_itemOpen{{endif}}' data-id="{$node->_id}{{if $node instanceof \IPS\Node\NodeGroup}}.g{{elseif $nodeClass and !( $node instanceof $nodeClass )}}.s{{endif}}" data-breadcrumb='{expression="json_encode( array_values( array_map( function( $val ){ return isset( $val::$titleLangPrefix ) ? \IPS\Member::loggedIn()->language()->addToStack( $val::$titleLangPrefix . $val->_id, FALSE, array( 'json' => TRUE, 'escape' => TRUE, 'striptags' => TRUE ) ) : ( $val->_title ? $val->_title : $val->_title ); }, iterator_to_array( $node->parents() ) ) ) )"}' {{if $togglePerm and $node->can( $togglePerm, NULL, $togglePermPBR )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggleIds )"}"{{elseif !$togglePerm and isset( $toggleIds[ $node->_id ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggleIds[ $node->_id ] )"}"{{elseif \count( $toggleIdsOff )}}data-toggles="{expression="implode( ',', $toggleIdsOff )"}"{{endif}} {{if $autoPopulate AND isset( $children[ $node->_id ] )}}data-childrenloaded="true"{{endif}}>
							{{if $node->hasChildren( 'view', NULL, $subnodes, $where )}}
								<a href='#' data-action="getChildren" class='ipsSelectTree_toggle'></a>
							{{endif}}
							<span data-role="nodeTitle">
								{{if $clubs === TRUE}}
									{lang="club_container_title" sprintf="$node->club()->name, $node->_title"}
								{{else}}
									{$node->_title}
								{{endif}}
							</span>
						</div>
						{{if $autoPopulate AND isset( $children[ $node->_id ] ) and \get_class( $node ) == ltrim( $nodeClass, '\\' )}}
							<div data-role="childWrapper">
								{template="nodeCascade" app="core" group="forms" location="global" params="$children[ $node->_id ], FALSE, $permCheck, $subnodes, $togglePerm, $toggleIds, $disabledCallback, FALSE, $children, $nodeClass, $where, $disabledArray, NULL, array(), NULL, $togglePermPBR, $toggleIdsOff"}
							</div>
						{{endif}}
					{{else}}
						{{if $disabledCallback === NULL or $disabledCallback( $node ) !== NULL}}
							<div class='ipsSelectTree_item ipsSelectTree_itemDisabled {{if $node->hasChildren( 'view', NULL, $subnodes, $where )}}ipsSelectTree_withChildren{{endif}} {{if $autoPopulate AND isset( $children[ $node->_id ] )}}ipsSelectTree_itemOpen{{endif}}' data-id="{$node->_id}" data-breadcrumb='{expression="json_encode( array_values( array_map( function( $val ){ return isset( $val::$titleLangPrefix ) ? \IPS\Member::loggedIn()->language()->addToStack( $val::$titleLangPrefix . $val->_id, FALSE, array( 'json' => TRUE, 'escape' => TRUE, 'striptags' => TRUE ) ) : ( $val->_title ? $val->_title : $val->_title ); }, iterator_to_array( $node->parents() ) ) ) )"}' {{if $autoPopulate AND isset( $children[ $node->_id ] )}}data-childrenloaded="true"{{endif}}>
								{{if $node->hasChildren( 'view', NULL, $subnodes, $where )}}
									<a href='#' data-action="getChildren" class='ipsSelectTree_toggle'></a>
								{{endif}}
								<span data-role="nodeTitle">
									{{if $clubs === TRUE}}
										{lang="club_container_title" sprintf="$node->club()->name, $node->_title"}
									{{else}}
										{$node->_title}
									{{endif}}
								</span>
							</div>
							{{if $autoPopulate AND isset( $children[ $node->_id ] )}}
								<div data-role="childWrapper">
									{template="nodeCascade" app="core" group="forms" location="global" params="$children[ $node->_id ], FALSE, $permCheck, $subnodes, $togglePerm, $toggleIds, $disabledCallback, FALSE, $children, $nodeClass, $where, $disabledArray, NULL, array(), NULL, $togglePermPBR, $toggleIdsOff"}
								</div>
							{{endif}}
						{{endif}}
					{{endif}}
				</li>
			{{endif}}
		{{endforeach}}
		{{if $noParentNodesTitle and \count( $noParentNodes )}}
			<li>
				<div class='ipsSelectTree_item ipsSelectTree_itemDisabled ipsSelectTree_withChildren {{if $autoPopulate}}ipsSelectTree_itemOpen{{endif}}' data-id="0" data-breadcrumb='{expression="json_encode( array() )"}' {{if $autoPopulate}}data-childrenloaded="true"{{endif}}>
					<a href='#' data-action="getChildren" class='ipsSelectTree_toggle'></a>
					<span data-role="nodeTitle">{lang="$noParentNodesTitle"}</span>
				</div>
				{{if $autoPopulate}}
					<div data-role="childWrapper">
						{template="nodeCascade" app="core" group="forms" location="global" params="$noParentNodes, FALSE, $permCheck, $subnodes, $togglePerm, $toggleIds, $disabledCallback, $autoPopulate, $children, $nodeClass, $where, $disabledArray, NULL, array(), NULL, $togglePermPBR, $toggleIdsOff"}
					</div>
				{{endif}}
			</li>
		{{endif}}
	</ul>
{{endif}}

{{if $range}}
	<div class="i-flex i-align-items_center i-gap_2">
		{{if $min !== NULL}}
			<strong class='i-flex_00 i-font-size_-2' data-role='rangeBoundary' hidden>{$min}</strong>
		{{endif}}
{{endif}}

<input
	type="{{if $range}}range{{else}}number{{endif}}"
	name="{$name}"
	{{if $id !== NULL}}
		id="elNumber_{$id}"
	{{endif}}
	size="5"
	{{if $required === TRUE}}aria-required='true'{{endif}}
	{{if $unlimited !== NULL and $value === $unlimited}}
		value=""
		data-jsdisable="true"
	{{elseif \is_numeric( $value )}}
	    {{if \is_int( $decimals ) or ( $decimals === true and mb_strpos( $value, '.' ) )}}
		    value="{expression="number_format( $value, $decimals === true ? mb_strlen( mb_substr( $value, mb_strpos( $value, '.' ) + 1 ) ) : $decimals, '.', '' )"}"
		{{else}}
		    value="{$value}"
		{{endif}}
	{{else}}
		value="0"
	{{endif}}
	class="ipsInput {{if $range}}ipsInput--range{{else}}ipsInput--text{{endif}}"
	{{if $min !== NULL}}
		min="{$min}"
	{{endif}}
	{{if $max !== NULL}}
		max="{$max}"
	{{endif}}
	{{if $step !== NULL and $step != 'any'}}
		step="{expression="number_format( $step, $decimals, '.', '' )"}"
	{{else}}
		step="any"
	{{endif}}
	{{if $disabled}}disabled aria-disabled='true'{{endif}}
	{{if \count($valueToggles)}}data-control="toggle" data-toggles="{expression="implode( ',', $valueToggles )"}"{{endif}}
>

{{if $range}}
	{{if $max !== NULL}}
		<strong class='i-flex_00 i-font-size_-2' data-role='rangeBoundary'><span id='{$name}_rangeValue' data-role='rangeValue'>{$value}</span> / {$max}</strong>
	{{endif}}
	</div>
{{endif}}
{{if \is_string( $suffix )}}
	{$suffix|raw}
{{elseif isset( $suffix['preUnlimited'] )}}
	{$suffix['preUnlimited']|raw}
{{endif}}
{{if $unlimited !== NULL}}
	&nbsp;
	<div class="ipsFieldRow__inlineCheckbox">
		{lang="or"}
		&nbsp;
		<input type="checkbox" data-control="unlimited{{if \count($toggles)}} toggle{{endif}}" name="{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}" id='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}-unlimitedCheck' value="{$unlimited}" {{if $unlimited === $value}}checked{{endif}} {{if $disabled}}disabled aria-disabled='true'{{endif}} {{if \count($toggles)}}{{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $toggles )"}"{{endif}} aria-labelledby='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}_label' class="ipsInput ipsInput--toggle">
		<label for='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}-unlimitedCheck' id='{expression="preg_replace( '/\[(.+?)\]/', '[$1_unlimited]', $name, 1 )"}_label' class='ipsField_unlimited'>{lang="$unlimitedLang"}</label>
	</div>
{{endif}}
{{if \is_array( $suffix ) and isset( $suffix['postUnlimited'] )}}
	&nbsp;&nbsp;&nbsp;{$suffix['postUnlimited']|raw}
{{endif}}

{{if \IPS\Request::i()->isAjax() AND $buttonMethods = $login->buttonMethods()}}
	<div id='elRegisterSocial' class='i-border-bottom_1 i-padding_3'>
		<h2 class='ipsTitle ipsTitle--h4'>{lang='reg_start_faster'}</h2>
		<p class='i-color_soft'>{lang='reg_connect'}</p>
			<form data-bypassValidation='true' accept-charset='utf-8' method='post' action='{$login->url}'>
			<input type="hidden" name="csrfKey" value="{expression="\IPS\Session::i()->csrfKey"}">
			<div class='i-flex i-flex-wrap_wrap i-gap_2 i-margin-top_3'>
				{{foreach $buttonMethods as $method}}
					<div class="i-flex_11">
						{$method->button()|raw}
					</div>
				{{endforeach}}
			</div>
		</form>
	</div>
{{endif}}

<form accept-charset='utf-8' class="ipsForm {$class} ipsForm--register-popup" action="{$action}" method="post" {{if $uploadField}}enctype="multipart/form-data"{{endif}} {{foreach $attributes as $k => $v}}{$k}="{$v}"{{endforeach}} data-ipsForm data-el='register-pop-up'>
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		{{if \is_array($v)}}
			{{foreach $v as $_k => $_v}}
				<input type="hidden" name="{$k}[{$_k}]" value="{$_v}">
			{{endforeach}}
		{{else}}
			<input type="hidden" name="{$k}" value="{$v}">
		{{endif}}
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	{{if \count( $form->elements ) < 2}}
		<div class="">
			{{if !empty( $sidebar )}}
				<div class='ipsColumns'>
					<div class='ipsColumns__primary'>
			{{endif}}
				<ul class=''>
					{{foreach $elements as $collection}}
						{{foreach $collection as $input}}
							{{if \is_object( $input ) }}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endforeach}}
					{{endforeach}}
				</ul>
			{{if !empty( $sidebar )}}
					</div>
					<div class='ipsColumns__secondary i-basis_180'>
						{expression="array_pop( $sidebar )" raw="true"}
					</div>
				</div>
			{{endif}}
		</div>
	{{else}}
		<i-tabs class='ipsTabs' id='ipsTabs_{$id}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_{$id}_content'>
			<div role='tablist'>
				{{foreach $elements as $name => $content}}
					<button type="button" id='ipsTabs_{$id}_{$name}' class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_{$id}_{$name}_panel" aria-selected="{{if $name == request.tab}}true{{else}}false{{endif}}">
						{{foreach $content as $element}}{{if !\is_string( $element ) and $element->error}}<i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> {{break;}}{{endif}}{{endforeach}} {lang="$name"}
					</button>
				{{endforeach}}
			</div>
			{template="tabScrollers" app="core" group="global" location="global"}
		</i-tabs>
		<div id='ipsTabs_{$id}_content' class='ipsTabs__panels'>
			{{foreach $elements as $name => $content}}
				<div id='ipsTabs_{$id}_{$name}_panel' class="ipsTabs__panel" role="tabpanel" aria-labelledby="ipsTabs_{$id}_{$name}" {{if $name != request.tab}}hidden{{endif}}>
					<ul>
						{{foreach $content as $input}}
							{{if \is_object( $input ) }}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endforeach}}
					</ul>
				</div>
			{{endforeach}}
		</div>
	{{endif}}
	<div class="ipsSubmitRow">
		<ul class='ipsButtons'>
			<li>{template="button" group="forms" app="core" location="global" params="'register_button', 'submit', null, 'ipsButton ipsButton--primary'"}</li>
			{{if $postBeforeRegister}}
				<li><a href="{url="app=core&module=system&controller=register&do=cancelPostBeforeRegister&id={$postBeforeRegister['id']}&pbr={$postBeforeRegister['secret']}" csrf="true" seoTemplate="register"}" class='ipsButton ipsButton--inherit' data-ipsPbrCancel="true">{lang="post_before_register_delete_submission"}</a></li>
			{{endif}}
		</ul>
	</div>
</form>

{{if !\IPS\Request::i()->isAjax() }}<div class="ipsBox ipsBox--popupTemplate">{{endif}}
<form accept-charset='utf-8' class="ipsForm ipsForm--popUpTemplate {$class}" action="{$action}" method="post" {{if $uploadField}}enctype="multipart/form-data"{{endif}} {{foreach $attributes as $k => $v}}{$k}="{$v}"{{endforeach}} data-ipsForm>
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		{{if \is_array($v)}}
			{{foreach $v as $_k => $_v}}
				<input type="hidden" name="{$k}[{$_k}]" value="{$_v}">
			{{endforeach}}
		{{else}}
			<input type="hidden" name="{$k}" value="{$v}">
		{{endif}}
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	{{if $form->error}}
		<div class="ipsMessage ipsMessage--error">
			{$form->error}
		</div>
	{{endif}}
	{{if \count( $form->elements ) < 2}}
		{{if !empty( $sidebar )}}
			<div class='ipsColumns ipsColumns--popupTemplate ipsColumns--lines i-border-top_3'>
				<div class='ipsColumns__primary'>
		{{endif}}
			<ul class=''>
				{{foreach $elements as $collection}}
					{{foreach $collection as $input}}
						{{if \is_object( $input ) }}
							{$input->rowHtml($form)|raw}
						{{else}}
							{$input|raw}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		{{if !empty( $sidebar )}}
				</div>
				<div class='ipsColumns__secondary i-basis_300'>
					{expression="array_pop( $sidebar )" raw="true"}
				</div>
			</div>
		{{endif}}
	{{else}}
		<i-tabs class='ipsTabs' id='ipsTabs_{$id}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_{$id}_content'>
			<div role='tablist'>
				{{foreach $elements as $name => $content}}
					<button type="button" id='ipsTabs_{$id}_{$name}' class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_{$id}_{$name}_panel" aria-selected="{{if $name == request.tab}}true{{else}}false{{endif}}">
						{{foreach $content as $element}}{{if !\is_string( $element ) and $element->error}}<i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> {{break;}}{{endif}}{{endforeach}} {lang="$name"}
					</button>
				{{endforeach}}
			</div>
			{template="tabScrollers" app="core" group="global" location="global"}
		</i-tabs>
		<div id='ipsTabs_{$id}_content' class='ipsTabs__panels'>
			{{foreach $elements as $name => $content}}
				<div id='ipsTabs_{$id}_{$name}_panel' class="ipsTabs__panel" role="tabpanel" aria-labelledby="ipsTabs_{$id}_{$name}" {{if $name != request.tab}}hidden{{endif}}>
					<ul>
						{{foreach $content as $input}}
							{{if \is_object( $input ) }}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endforeach}}
					</ul>
				</div>
			{{endforeach}}
		</div>
	{{endif}}
	<ul class="ipsSubmitRow ipsButtons">
		{{foreach $actionButtons as $button}}
			<li>{$button|raw}</li>
		{{endforeach}}
	</ul>
</form>
{{if !\IPS\Request::i()->isAjax() }}</div>{{endif}}

{{if !member.member_id}}
	{{if !$standalone}}
		<div class='cGuestTeaser'>
			<h2 class='ipsTitle ipsTitle--h3'>{lang="guest_post_header"}</h2>
		{{endif}}
			<p>
				{{if $guestPostBeforeRegister}}
					{lang="guest_post_pbr_blurb"}
				{{else}}
					{lang="guest_post_normal_blurb"}
				{{endif}}
				{lang="guest_post_sign_in"}
				{{if $modQueued}}
					<br><span class='i-color_warning'>{lang="guest_post_mod_approval"}</span>
				{{endif}}
			</p>
	{{if !$standalone}}
		</div>
	{{endif}}
{{elseif $modQueued}}
	<div class="ipsMessage ipsMessage--withButtons ipsMessage--warning i-margin-bottom_2">
		<div>
			<h4 class='ipsMessage__title'>{lang="mod_queue_message"}</h4>
			{{$warnings = member.warnings( 1, NULL, 'mq' );}}
			{{if \count( $warnings ) and member.mod_posts > time()}}
				<p class="i-color_soft">
					{{if \count( $warnings )}}
						{lang="this_will_be_moderated"}
					{{endif}}
					{lang="restriction_ends" sprintf="\IPS\DateTime::ts( \IPS\Member::loggedIn()->mod_posts )->relative()"}
				</p>
			{{endif}}
		</div>
		<div class='ipsButtons'>
			{{foreach $warnings as $idx => $warning}}
				<a href="{$warning->url()}" class='ipsButton' data-ipsDialog data-ipsDialog-size='narrow'>{lang="view_warning_details"}</a>
			{{endforeach}}
		</div>
	</div>	
{{endif}}

{{if $unlimited !== NULL}}
	<ul class="ipsFieldList ipsFieldList--radio" role="radiogroup">
		<li>
			<input type="checkbox" name="{$name}" value="{$unlimited}" id='elRadio_{$name}_{unlimited}_{$htmlId}' data-control="toggle" data-togglesOff="elRadio_{$name}" {{if $value === $unlimited}}checked{{endif}} class="ipsInput ipsInput--toggle">
			<div class='ipsFieldList__content'>
				<label for='elRadio_{$name}_{unlimited}_{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}'>
					{lang="$unlimitedLang"}
				</label>
			</div>
		</li>
	</ul>
{{endif}}
<input type="hidden" name="radio_{$name}__empty" value='1'>
<ul class="ipsFieldList ipsFieldList--radio" role="radiogroup" id="elRadio_{$name}_{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}">
{{foreach $options as $k => $v}}
	<li>
		<input type="radio" name="{$name}" value="{$k}" {{if (string) $value == (string) $k or ( isset( $userSuppliedInput ) and !\in_array( $value, array_keys( $options ) ) and $k == $userSuppliedInput )}}checked{{endif}} {{if $disabled === TRUE or ( \is_array( $disabled ) and \in_array( $k, $disabled ) )}}disabled{{endif}} {{if isset( $toggles[ $k ] ) and !empty( $toggles[ $k ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}} id="elRadio_{$name}_{$k}_{$htmlId}" class="ipsInput ipsInput--toggle">
		<div class='ipsFieldList__content'>
			<label for="elRadio_{$name}_{$k}_{$htmlId}" id='elField_{$name}_{$k}_label'>{$v|raw}</label>
			{{if !empty( $userSuppliedInput ) AND $userSuppliedInput == $k}}
				<input type='text' class='ipsInput ipsInput--text' name='{$userSuppliedInput}_{$name}' value="{{if !\in_array( $value, array_keys( $options ) )}}{$value}{{endif}}" id='{$userSuppliedInput}_{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}'>
			{{endif}}
			{{if isset( $descriptions[ $k ] )}}
				{$descriptions[ $k ]|raw}
			{{endif}}
			{{if isset( $warnings[ $k ] )}}
				{$warnings[ $k ]|raw}
			{{endif}}
		</div>
	</li>
{{endforeach}}
</ul>

{{if $multiple}}
	<input type="hidden" name="{$name}" value="__EMPTY">
{{endif}}
{{$userInput = array_diff( ( \is_array( $value ) ? $value : array( $value ) ), array_keys( $options ) );}}
<select name="{$name}" class="ipsInput ipsInput--select {$class}" {{if $multiple}}multiple{{endif}} {{if $required === TRUE}}required aria-required='true'{{endif}} {{if $disabled === TRUE}}disabled aria-disabled='true'{{endif}} {{if $id !== NULL}}id="elSelect_{$id}"{{endif}} {{if $sort}}data-sort{{endif}}>
	{{foreach $options as $k => $v}}
		{{if \is_array( $v )}}
			<optgroup label="{{if $parse === 'raw'}}{$k}{{else}}{lang="$k"}{{endif}}">
				{{foreach $v as $_k => $_v}}
					<option value='{$_k}' {{if ( ( $value === 0 and $_k === 0 ) or ( $value !== 0 and $value === $_k ) ) or ( \is_array( $value ) and \in_array( $_k, $value ) )}}selected{{endif}} {{if isset( $toggles[ $_k ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggles[ $_k ] )"}" aria-controls="{expression="implode( ',', $toggles[ $_k ] )"}"{{endif}} {{if \is_array($disabled) and \in_array( $_k, $disabled )}}disabled{{endif}}>{$_v|raw}</option>
				{{endforeach}}
			</optgroup>
		{{else}}
			<option value='{$k}' {{if ( ( $value === 0 and $k === 0 ) or ( $value !== 0 and $value === $k ) or ( $value !== 0 and \is_numeric( $value ) and \is_numeric( $k ) and $value == $k ) ) or ( \is_array( $value ) and \in_array( $k, $value ) ) or ( !empty( $userSuppliedInput ) and !\in_array( $value, array_keys( $options ) ) and $k == $userSuppliedInput )}}selected{{endif}} {{if isset( $toggles[ $k ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}} {{if \is_array($disabled) and \in_array( $k, $disabled )}}disabled{{endif}}>{$v|raw}</option>
		{{endif}}
	{{endforeach}}
</select>
{{if $userSuppliedInput}}
<div id='{$userSuppliedInput}' class='i-margin-top_1'>
    {{$key = preg_replace( '/[^a-zA-Z0-9\-_]/', '_', $name );}}
    <input type='text' class='ipsInput ipsInput--text' name='{$userSuppliedInput}_{$name}' value="{{if \count( $userInput )}}{expression="implode( ' , ', $userInput )"}{{endif}}" id='{$userSuppliedInput}_{$key}'>
</div>
{{endif}}
{{if $unlimited !== NULL}}
	<br><br>
	{lang="or"}
	&nbsp;
	<input type="checkbox" role='checkbox' class="ipsInput ipsInput--toggle" data-control="unlimited{{if \count($unlimitedToggles)}} toggle{{endif}}" name="{expression="trim( $name, '[]' )"}_unlimited" id='{expression="trim( $id ?: $name, '[]' )"}_unlimited' value="{$unlimited}" {{if $unlimited === $value}}checked{{endif}} {{if $disabled}}disabled aria-disabled='true'{{endif}} {{if \count( $unlimitedToggles )}}{{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $unlimitedToggles )"}" {{if \is_array( $toggleOn )}}data-togglesOff="{expression="implode( ',', $toggleOn )"}"{{endif}} aria-controls="{expression="implode( ',', $unlimitedToggles )"}"{{endif}} aria-labelledby='{expression="trim( $id ?: $name, '[]' )"}_unlimited_label'>
	<label for='{expression="trim( $id ?: $name, '[]' )"}_unlimited' id='{expression="trim( $id ?: $name, '[]' )"}_unlimited_label' class='ipsField_unlimited'>{lang="$unlimitedLang"}</label>
{{endif}}

{{if $multiple}}
	<input type="hidden" name="{$name}" value="__EMPTY">
{{endif}}
{{$userInput = array_diff( ( \is_array( $value ) ? $value : array( $value ) ), array_keys( $options ) );}}
<select name="{$name}" class="ipsInput ipsInput--select {$class}" {{if $multiple}}multiple{{endif}} {{if $required === TRUE}}required aria-required='true'{{endif}} {{if $disabled === TRUE}}disabled aria-disabled='true'{{endif}} {{if $id !== NULL}}id="elSelect_{$id}"{{endif}} {{if $sort}}data-sort{{endif}}>
	{{foreach $options as $k => $v}}
		{{if \is_array( $v )}}
			<optgroup label="{lang="$k"}">
				{{foreach $v as $_k => $_v}}
					<option value='{$_k}' {{if ( ( $value === 0 and $_k === 0 ) or ( $value !== 0 and $value === $_k ) ) or ( \is_array( $value ) and \in_array( $_k, $value ) )}}selected{{endif}} {{if isset( $toggles[ $_k ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggles[ $_k ] )"}" aria-controls="{expression="implode( ',', $toggles[ $_k ] )"}"{{endif}}>{$_v|raw}</option>
				{{endforeach}}
			</optgroup>
		{{else}}
			<option value='{$k}'  {{if ( ( $value === 0 and $k === 0 ) or ( $value !== 0 and $value === $k ) or ( $value !== 0 and \is_numeric( $value ) and \is_numeric( $k ) and $value == $k ) ) or ( \is_array( $value ) and \in_array( $k, $value ) ) or ( !empty( $userSuppliedInput ) and !\is_array( $value ) and !\in_array( $value, array_keys( $options ) ) and $k == $userSuppliedInput )}}selected{{endif}} {{if \is_array( $disabled ) and \in_array( $k, $disabled )}}disabled{{endif}} {{if isset( $toggles[ $k ] )}}data-control="toggle" data-toggles="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}}>{$v|raw}</option>
		{{endif}}
	{{endforeach}}
</select>
{{if $userSuppliedInput}}
<div id='{$userSuppliedInput}' class='i-margin-top_1'>
    <input type='text' class='ipsInput ipsInput--text' name='{$userSuppliedInput}_{$name}' value="{{if \count( $userInput )}}{expression="implode( ' , ', $userInput )"}{{endif}}">
</div>
{{endif}}
{{if $unlimited !== NULL}}
	<br><br>
	{lang="or"}
	&nbsp;
	<input type="checkbox" data-control="unlimited{{if \count($unlimitedToggles)}} toggle{{endif}}" name="{expression="trim( $name, '[]' )"}_unlimited" id='{expression="trim( $id ?: $name, '[]' )"}_unlimited' value="{$unlimited}" {{if $unlimited === $value}}checked{{endif}} {{if $disabled === TRUE}}disabled aria-disabled='true'{{endif}} {{if \count( $unlimitedToggles )}}{{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $unlimitedToggles )"}" aria-controls="{expression="implode( ',', $unlimitedToggles )"}"{{endif}} aria-labelledby='{expression="trim( $id ?: $name, '[]' )"}_unlimited_label' class="ipsInput ipsInput--toggle">
	<label for='{expression="trim( $id ?: $name, '[]' )"}_unlimited' id='{expression="trim( $id ?: $name, '[]' )"}_unlimited_label' class='ipsField_unlimited'>{lang="$unlimitedLang"}</label>
{{endif}}

{{if !\IPS\Request::i()->isAjax() }}<div class="ipsBox ipsBox--formTemplate">{{endif}}
<form action="{$action}" method="post" accept-charset='utf-8' {{if $uploadField}}enctype="multipart/form-data"{{endif}} data-ipsForm class="ipsFormWrap ipsFormWrap--template" {{foreach $attributes as $k => $v}}{$k}="{$v}"{{endforeach}} {{if \count($tabArray) > 1}}novalidate="true"{{endif}} data-template='front/forms/template'>
	{{if $error}}
		<div class="ipsMessage ipsMessage--error i-margin_1" data-role="formError" tabindex="-1">
			{$error}
		</div>
	{{endif}}
	{{if !empty( $errorTabs )}}
		<p class="ipsMessage ipsMessage--error i-margin_1 ipsJS_show" data-role="formError" tabindex="-1">{lang="tab_error"}</p>
	{{endif}}
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		{{if \is_array($v)}}
			{{foreach $v as $_k => $_v}}
				<input type="hidden" name="{$k}[{$_k}]" value="{$_v}">
			{{endforeach}}
		{{else}}
			<input type="hidden" name="{$k}" value="{$v}">
		{{endif}}
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	{{if \count( $tabs ) < 2}}
		{{if !empty( $sidebar )}}
			<div class='ipsColumns ipsColumns--compose-form ipsColumns--lines'>
				<div class='ipsColumns__primary'>
		{{endif}}
					<ul class='ipsForm {$formClass} ipsForm--template'>
						{expression="array_pop( $tabs )" raw="true"}
						<li class='ipsSubmitRow'>
							{expression="implode( '', $actionButtons)" raw="true"}
						</li>
					</ul>
		{{if !empty( $sidebar )}}
				</div>
				<div class='ipsColumns__secondary'>
					{expression="array_pop( $sidebar )" raw="true"}
				</div>
			</div>
		{{endif}}
	{{else}}
		<i-tabs class='ipsTabs{{if $usingIcons}} ipsTabs--withIcons{{endif}}' id='ipsTabs_{$id}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_{$id}_content'>
			<div role='tablist'>
				{{foreach $tabs as $name => $content}}
					<button type="button" id='ipsTabs_{$id}_{$name}' class="ipsTabs__tab {{if \in_array( $name, $errorTabs )}}ipsTabs__tab--error{{endif}}" role="tab" aria-controls="ipsTabs_{$id}_{$name}_panel" aria-selected="{{if $activeTab == $name}}true{{else}}false{{endif}}">
						{{if \in_array( $name, $errorTabs )}}<i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> {{endif}}{{if isset($tabArray[$name]['icon'])}}<i class='fa-solid fa-{$tabArray[$name]['icon']}' aria-hidden="true"></i> {{endif}}{lang="$name"}
					</button>
				{{endforeach}}
			</div>
			{template="tabScrollers" app="core" group="global" location="global"}
		</i-tabs>
		<div id='ipsTabs_{$id}_content' class='ipsTabs__panels'>
			{{foreach $tabs as $name => $contents}}
				<div id='ipsTabs_{$id}_{$name}_panel' class="ipsTabs__panel ipsTabs__panel--{$name}" role="tabpanel" aria-labelledby="ipsTabs_{$id}_{$name}" {{if $activeTab != $name}}hidden{{endif}}>
					{{if isset( $sidebar[ $name ] )}}
						<div class='ipsColumns ipsColumns--compose-form ipsColumns--lines'>
							<div class='ipsColumns__primary'>
					{{endif}}
								<ul class='ipsForm {$formClass} ipsForm--template {{if isset( $tabClasses[ $name ] )}}{$tabClasses[ $name ]}{{endif}}'>
									<li class='ipsJS_hide'>{lang="$name"}</li>
									{$contents|raw}
								</ul>
					{{if isset( $sidebar[ $name ] )}}
							</div>
							<div class='ipsColumns__secondary'>
								{$sidebar[ $name ]|raw}
							</div>
						</div>
					{{endif}}
				</div>
			{{endforeach}}
		</div>
		<div class="ipsSubmitRow">
			{expression="implode( '', $actionButtons)" raw="true"}
		</div>
	{{endif}}
</form>
{{if !\IPS\Request::i()->isAjax() }}</div>{{endif}}

{{if $showMeter}}
	<div data-ipsPasswordStrength{{if settings.password_strength_meter_enforce}} data-ipsPasswordStrength-enforced data-ipsPasswordStrength-enforcedStrength='{setting="password_strength_option"}'{{endif}}{{if $pwCheckAgainstMember !== NULL}} data-ipsPasswordStrength-checkAgainstMember='{expression="json_encode( array( $pwCheckAgainstMember->name, $pwCheckAgainstMember->email ) )" raw="true"}'{{endif}}{{if \count( $pwCheckAgainstRequest )}} data-ipsPasswordStrength-checkAgainstRequest='{expression="json_encode($pwCheckAgainstRequest)" raw="true"}'{{endif}}>
{{endif}}
{{if $autoComplete}}
	{template="autocomplete" group="forms" location="global" app="core" params="$name, $value, $required, $maxlength, $disabled, '', $placeholder, $nullLang, $autoComplete"}
{{else}}
	<input
		class="ipsInput ipsInput--text"
		type="{$type}"
		name="{$name}"
		{{if !is_null( $value )}}
		value="{{if \is_array( $value )}}{expression="implode( ',', $value )"}{{else}}{$value}{{endif}}"
		{{endif}}
		id="elInput_{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}"
		aria-describedby="elInput_{{if ! empty($htmlId)}}{$htmlId}{{else}}{$name}{{endif}}--error"
		{{if $required === TRUE}}aria-required='true'{{endif}}
		{{if $maxlength !== NULL}}maxlength="{$maxlength}"{{endif}}
		{{if $size !== NULL}}size="{$size}"{{endif}}
		{{if $disabled}}disabled aria-disabled='true'{{endif}}
		{{if $placeholder !== NULL}}placeholder='{$placeholder}'{{endif}}
		{{if $regex !== NULL and $regex}}pattern="{$regex}"{{endif}}
		{{if $htmlAutocomplete !== NULL and $htmlAutocomplete}}autocomplete="{$htmlAutocomplete}"{{endif}}
	>
	{{if $showMeter}}
		<div data-role='strengthInfo' class='ipsHide'>
			<meter max="100" value="0" class='ipsForm_meter' data-role='strengthMeter'></meter>
			<span data-role='strengthText' class='ipsForm_meterAdvice'></span>
		</div>
	{{endif}}
	{{if $nullLang}}
		<div class="ipsFieldRow__inlineCheckbox">
			{lang="or"} 
			<input type="checkbox" data-control="unlimited" name="{$name}_null" id='{$name}_null' value="1" {{if $value === NULL}}checked{{endif}} {{if $disabled}}disabled aria-disabled='true'{{endif}} aria-labelledby='{$name}_null_label' class="ipsInput ipsInput--toggle">
			<label for='{$name}_null' id='{$name}_null_label' class='ipsField_unlimited'>{lang="$nullLang"}</label>
		</div>
	{{endif}}
	{{if $showMeter}}
	</div>
	{{endif}}
{{endif}}

{{if !empty( $tags ) or !empty( $allOptions['tagSource'] )}}
<div
    class='ipsColumns {{if @$allOptions["codeMode"]}}ipsCodebox__outer-wrap{{endif}}'
    data-controller='core.global.editor.customtags'
    data-tagFieldType='{{if @$allOptions["codeMode"]}}codebox{{else}}text{{endif}}'
    data-tagFieldID='elTextarea_{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}'
    {{if !empty($allOptions['tagSource'])}}data-tagsource="{$allOptions['tagSource']}"{{endif}}
>
	<div class='ipsColumns__primary'>
		<div data-role="editor" {{if @$allOptions["codeMode"]}}class='ipsCodebox__inner-wrap'{{endif}}>
{{endif}}
<textarea
	name="{$name}"
	id='elTextarea_{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}'
	value="{{if $value !== null }}{$value}{{endif}}"
	class="ipsInput ipsInput--text ipsInput--wide {$class}"
	{{if $rows !== NULL}}rows="{$rows}"{{endif}}
	{{if $maxlength !== NULL}}maxlength="{$maxlength}"{{endif}}
	{{if $required === TRUE}}aria-required='true'{{endif}}
	{{if $disabled}}disabled aria-disabled='true'{{endif}}
	{{if $placeholder}}placeholder="{$placeholder}"{{endif}}
    {{if @$allOptions['codeMode']}}data-ipscodebox{{if !empty( $allOptions['codeModeAllowedLanguages'] )}} data-ipscodebox-allowed-languages="{expression="json_encode($allOptions['codeModeAllowedLanguages'])"}"{{endif}}{{endif}}
>{{if $value !== null }}{$value}{{endif}}</textarea>
{{if !empty( $tags ) or !empty( $allOptions['tagSource'] )}}
	</div>
{{endif}}
{{if $nullLang}}
	<div class="ipsFieldRow__inlineCheckbox">
		{lang="or"} 
		<input type="checkbox" data-control="unlimited" name="{$name}_null" id="{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null" value="1" {{if $value === NULL}}checked{{endif}} {{if $disabled}}disabled{{endif}} aria-controls='{$name}' aria-labelledby='{$name}_null_label' class="ipsInput ipsInput--toggle">
		<label for='{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null' id='{expression="preg_replace('/[^a-zA-Z0-9\-_]/', '_', $name)"}_null_label' class='ipsField_unlimited'>{lang="$nullLang"}</label>
	</div>
{{endif}}
{{if !empty( $tags ) or !empty( $allOptions['tagSource'] )}}
	</div>
	<div class='ipsColumns__secondary ipsComposeArea_sidebar'>
		<h3 class='i-padding_2 i-font-weight_600 i-color_hard i-font-size_2' data-role='tagsHeader'>{lang="editor_tags"}</h3>
		<ul class='ipsScrollbar' data-role='tagsList'>
            {{$tagLinks = $allOptions['tagLinks'] ?? null;}}
            {template="editorTags" app="core" location="global" group="forms" params="$tags, $tagLinks"}
        </ul>
	</div>
</div>
{{endif}}

{{if \count( $languages ) === 1}}
	{{foreach $languages as $lang}}
		{{if !isset( $editors[ $lang->id ] ) }}
			{{if $textarea}}
				<textarea class='ipsInput ipsInput--text' name="{$name}[{$lang->id}]">{{if isset($values[ $lang->id ])}}{$values[ $lang->id ]}{{endif}}</textarea>
			{{else}}
				<input type='text' class='ipsInput ipsInput--text' name="{$name}[{$lang->id}]" value="{{if isset($values[ $lang->id ])}}{$values[ $lang->id ]}{{endif}}" {{if $placeholder !== NULL}}placeholder='{$placeholder}'{{endif}}>
			{{endif}}
		{{else}}
			{$editors[ $lang->id ]->html()|raw}
		{{endif}}
	{{endforeach}}
{{else}}
	{{if $textarea}}
		<div class="ipsFieldRow__languages">
			{{foreach $languages as $lang}}
				<div>
					<div class="ipsFieldRow__language"><span class="{$lang->_icon}"></span> {$lang->_title} {{if $required and $lang->default}}<span class="ipsFieldRow__required">{lang="required"}</span>{{endif}}</div>
					<textarea name="{$name}[{$lang->id}]" aria-label='{$lang->title}' class='ipsInput ipsInput--text {{if !$required || !$lang->default}} ipsFieldRow_errorExclude{{endif}}'>{{if isset( $values[ $lang->id ])}}{$values[ $lang->id ]}{{endif}}</textarea>
				</div>
			{{endforeach}}
		</div>
	{{else}}
		<ul class='ipsForm ipsForm--translatable'>
			{{foreach $languages as $lang}}
				<li class='ipsFieldRow'>
					<div class='ipsFieldList__content'>
						{{if !isset( $editors[ $lang->id ] ) }}
							<div class="ipsInputIcon">
								<span class="ipsInputIcon__icon {$lang->_icon}"></span>
								<input type='text' name="{$name}[{$lang->id}]" aria-label='{$lang->title}' placeholder="{$lang->title} {{if $required and $lang->default}} - {lang="required"}{{endif}}" {{if isset( $values[ $lang->id ])}}value="{$values[ $lang->id ]}"{{endif}} class="ipsInput ipsInput--text {{if !$required || !$lang->default}}ipsFieldRow_errorExclude{{endif}}">
							</div>
						{{else}}
							<p class='ipsFlagEditor'>
								<span class="{$lang->_icon}"></span> <span class='ipsFlagLabel'>{$lang->_title}</span>
								{{if $required and $lang->default}}<span class="ipsFieldRow__required">{lang="required"}</span>{{endif}}
							</p>
							{$editors[ $lang->id ]->html()|raw}
						{{endif}}
					</div>
				</li>
			{{endforeach}}
		</ul>
	{{endif}}
{{endif}}

{{if $file->isImage()}}
	<img src="{$file->url}" class="ipsImage" data-ipsLightbox>
{{else}}
	<a href="{$downloadUrl}">{$file->originalFilename}</a>
{{endif}}

{{if $multiple}}
<input type="hidden" name="{$name}[__EMPTY]" value="__EMPTY">
{{endif}}

<div data-control="granularCheckboxset" data-count="{expression="\count( $options )"}">

<div data-role="checkboxsetGranular" class=" ">

    <div class="ipsSpanGrid">
        {{foreach $options as $k => $v}}
       <div class="ipsSpanGrid__4">
					<span class=''>
						<input type="checkbox" {{if $class}}class="{$class}"{{endif}} name="{$name}[{$k}]" value="1" {{if ( $unlimited !== NULL AND $unlimited === $value ) or ( \is_array( $value ) AND \in_array( $k, $value ) )}}checked{{endif}} {{if $disabled === TRUE or ( \is_array( $disabled ) and \in_array( $k, $disabled ) )}}disabled{{endif}} {{if isset( $toggles[ $k ] ) and !empty( $toggles[ $k ] )}}data-control="toggle" {{if $toggleOn === FALSE}}data-togglesOff{{else}}data-togglesOn{{endif}}="{expression="implode( ',', $toggles[ $k ] )"}"{{endif}} id="elCheckbox_{$name}_{$k}">
                        <span class="ipsFieldRow_label">     <label for='elCheckbox_{$name}_{$k}' id='elField_{$name}_label' data-role="label">{$k|raw}</label>
                        </span>
                         {{if isset( $descriptions[ $k ] )}}
                        <div class="ipsFieldList__content">
                            {$descriptions[ $k ]|raw}
                        </div>
                        {{endif}}
					</span>

       </div>
        {{endforeach}}
    </div>
</div>
</div>

{{foreach $warnings as $idx => $warning}}
	<div class='i-grid i-gap_1'>
		{{if $idx === 0}}
			<div class='ipsMessage ipsMessage--error'>
				<h4 class='ipsMessage__title'>{lang="you_have_been_warned" sprintf="\IPS\Member::load( $warning->moderator )->name"}</h4>
				{{if \IPS\Member::loggedIn()->isBanned()}}
					{{if $warning->note_member}}
						<p>{$warning->note_member|raw}</p>
					{{endif}}
				{{else}}
					<p>{lang="must_acknowledge_msg"}</p>
					<br>
					<a href='{url="app=core&module=system&controller=warnings&do=view&id={$warning->member}&w={$warning->id}" seoTemplate="warn_view" seoTitle="\IPS\Member::loggedIn()->members_seo_name" ref="(string) \IPS\Request::i()->url()"}' class='ipsButton ipsButton--small ipsButton--soft' data-ipsDialog data-ipsDialog-size='narrow'>{lang="view_warning_details"}</a>
				{{endif}}
			</div>
		{{endif}}
	</div>
{{endforeach}}

{{if \count( $advertisement->_images )}}
<div class='ips{expression="\IPS\IPS::mb_ucfirst(\IPS\SUITE_UNIQUE_KEY)"} i-text-align_center'>
	<ul>
		{{$hmacKey = hash_hmac( "sha256", $advertisement->link, \IPS\Settings::i()->site_secret_key . 'a' );}}
		<li class='ips{expression="\IPS\IPS::mb_ucfirst(\IPS\SUITE_UNIQUE_KEY)"}_large ipsResponsive_showDesktop'>
			{{if $advertisement->link}}
				<a href='{{if $acpLink}}{$acpLink}{{else}}{url="app=core&module=system&controller=redirect&do=advertisement&ad={$advertisement->id}&key={$hmacKey}" base="front"}{{endif}}' {{if $advertisement->new_window}}target='_blank'{{endif}} rel='nofollow noopener'>
			{{endif}}
				<img src='{file="$advertisement->_images['large']" extension="$advertisement->storageExtension()"}' alt="{{if $advertisement->image_alt}}{$advertisement->image_alt}{{else}}{lang="advertisement_alt"}{{endif}}" {{if $acpLink}}style="max-width:100%;max-width:min(100%, 300px);"{{endif}} loading="lazy">
			{{if $advertisement->link}}
				</a>
			{{endif}}
		</li>
		{{if !$acpLink }}
		<li class='ips{expression="\IPS\IPS::mb_ucfirst(\IPS\SUITE_UNIQUE_KEY)"}_medium ipsResponsive_showTablet'>
			{{if $advertisement->link}}
				<a href='{{if $acpLink}}{$acpLink}{{else}}{url="app=core&module=system&controller=redirect&do=advertisement&ad={$advertisement->id}&key={$hmacKey}" base="front"}{{endif}}' {{if $advertisement->new_window}}target='_blank'{{endif}} rel='nofollow noopener'>
			{{endif}}
				<img src='{{if !empty( $advertisement->_images['medium'] )}}{file="$advertisement->_images['medium']" extension="$advertisement->storageExtension()"}{{else}}{file="$advertisement->_images['large']" extension="$advertisement->storageExtension()"}{{endif}}' alt="{{if $advertisement->image_alt}}{$advertisement->image_alt}{{else}}{lang="advertisement_alt"}{{endif}}" {{if $acpLink}}style="max-width:100%;max-width:min(100%, 300px);"{{endif}} loading="lazy">
			{{if $advertisement->link}}
				</a>
			{{endif}}
		</li>

		<li class='ips{expression="\IPS\IPS::mb_ucfirst(\IPS\SUITE_UNIQUE_KEY)"}_small ipsResponsive_showPhone'>
			{{if $advertisement->link}}
				<a href='{{if $acpLink}}{$acpLink}{{else}}{url="app=core&module=system&controller=redirect&do=advertisement&ad={$advertisement->id}&key={$hmacKey}" base="front"}{{endif}}' {{if $advertisement->new_window}}target='_blank'{{endif}} rel='nofollow noopener'>
			{{endif}}
				<img src='{{if !empty( $advertisement->_images['small'] )}}{file="$advertisement->_images['small']" extension="$advertisement->storageExtension()"}{{elseif !empty( $advertisement->_images['medium'] )}}{file="$advertisement->_images['medium']" extension="$advertisement->storageExtension()"}{{else}}{file="$advertisement->_images['large']" extension="$advertisement->storageExtension()"}{{endif}}' alt="{{if $advertisement->image_alt}}{$advertisement->image_alt}{{else}}{lang="advertisement_alt"}{{endif}}" {{if $acpLink}}style="max-width:100%;max-width:min(100%, 300px);"{{endif}} loading="lazy">
			{{if $advertisement->link}}
				</a>
			{{endif}}
		</li>
		{{endif}}
	</ul>
	{{if $acpLink}}
		<div class="i-font-size_-1 i-margin-top_3 i-font-weight_500"><a href="{$acpLink}" rel="noreferrer" class="i-color_soft">{$acpLink}</a></div>
	{{endif}}
</div>
{{endif}}

{{if $announcements = \IPS\core\Announcements\Announcement::loadAllByLocation('content')}}
	<i-announcement-banner class='ipsAnnouncements ipsAnnouncements--content'>
		{{foreach $announcements as $announcement}}
			{{ $announcementCookie = 'announcement_' . $announcement->id; }}
			{{if !\IPS\Member::loggedIn()->member_id OR (\IPS\Member::loggedIn()->member_id AND !isset(\IPS\Request::i()->cookie[$announcementCookie]))}}
				<div class='ipsAnnouncement ipsAnnouncement--{$announcement->color}' data-announcementId="{$announcement->id}">
					{{if $announcement->type == \IPS\core\Announcements\Announcement::TYPE_CONTENT}}
						<a href='{$announcement->url()}' class='ipsAnnouncement__link' data-ipsDialog data-ipsDialog-title="{$announcement->title}"><i class="fa-solid fa-bullhorn ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</a>
					{{elseif $announcement->type == \IPS\core\Announcements\Announcement::TYPE_URL}}
						<a href='{$announcement->url}' class='ipsAnnouncement__link' target="_blank" rel='noopener'><i class="fa-solid fa-arrow-up-right-from-square ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</a>
					{{else}}
						<div class='ipsAnnouncement__text'><i class="fa-solid fa-bullhorn ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</div>
					{{endif}}
					<button type="button" data-role="dismissAnnouncement"><i class="fa-solid fa-xmark" aria-hidden="true"></i><span class="ipsInvisible">{lang="announce_hide"}</span></button>
				</div>
			{{endif}}
		{{endforeach}}
	</i-announcement-banner>
{{endif}}

{{if $announcements = \IPS\core\Announcements\Announcement::loadAllByLocation('top')}}
	<i-announcement-banner class='ipsAnnouncements ipsAnnouncements--top'>
		{{foreach $announcements as $announcement}}
			{{ $announcementCookie = 'announcement_' . $announcement->id; }}
			{{if !isset(\IPS\Request::i()->cookie[$announcementCookie])}}
				<div class='ipsAnnouncement ipsAnnouncement--{$announcement->color}' data-announcementId="{$announcement->id}">
					<div class="ipsWidth">
						{{if $announcement->type == \IPS\core\Announcements\Announcement::TYPE_CONTENT}}
							<a href='{$announcement->url()}' class='ipsAnnouncement__link' data-ipsDialog data-ipsDialog-title="{$announcement->title}"><i class="fa-solid fa-bullhorn ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</a>
						{{elseif $announcement->type == \IPS\core\Announcements\Announcement::TYPE_URL}}
							<a href='{$announcement->url}' class='ipsAnnouncement__link' target="_blank" rel='noopener'><i class="fa-solid fa-arrow-up-right-from-square ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</a>
						{{else}}
							<div class='ipsAnnouncement__text'><i class="fa-solid fa-bullhorn ipsAnnouncement__icon" aria-hidden="true"></i>{$announcement->title}</div>
						{{endif}}
						<button type="button" data-role="dismissAnnouncement"><i class="fa-solid fa-xmark" aria-hidden="true"></i><span class="ipsInvisible">{lang="announce_hide"}</span></button>
					</div>
				</div>
			{{endif}}
		{{endforeach}}
	</i-announcement-banner>
{{endif}}

{{if \count( $segments )}}
    <div class='ipsPieBar {$classes}'>
        <div class='ipsPieBar__bar'>
            {{foreach $segments as $segment}}
                <div class='ipsPieBar__barSegment' style='width: {expression="number_format( $segment['percentage'], 2, '.', '' )"}%' 
                    {{if !empty( $segment['title'] ) || !empty( $segment['tooltip'] )}}
                        {{if !empty( $segment['tooltip'] )}}
                            data-ipsTooltip="{$segment['tooltip']}" {{if !empty( $segment['tooltipSafe'] )}}data-ipsTooltip-safe{{endif}}
                        {{else}}
                            {{if !empty( $segment['title'] )}}title="{$segment['title']}"{{endif}}
                        {{endif}}
                    {{else}}
                        title="{$segment['value']} ({$segment['percentage']}%)"
                        data-ipsTooltip
                    {{endif}}
                ></div>
            {{endforeach}}
        </div>
        <ul class='ipsList ipsList--inline ipsPieBar__legend'>
            {{foreach $segments as $segment}}
                <li class='ipsPieBar__legendItem'>
                    <span class='ipsPieBar__legendItemKey'></span>
                    {{if isset( $segment['nameRaw'] )}}{$segment['nameRaw']|raw}{{else}}{$segment['name']}{{endif}}
                </li>
            {{endforeach}}
        </ul>
    </div>
{{else}}
    <p class='i-color_soft i-text-align_center'>
        {lang="no_data"}
    </p>
{{endif}}

{{if $assignment = $item->assignment and !$assignment->closed}}
    {{$assignedTo = $assignment->assignedTo();}}
    {{if $item->isAssignedToMember()}}
        <span class="ipsBadge ipsBadge--soft ipsBadge--assigned {$classes}" {{if $assignedTo instanceof \IPS\Member\Team}}title='{lang="assigned_to_you_team" sprintf="$assignedTo->name"}'{{else}}title='{lang="assigned_to_you"}'{{endif}} data-ipsTooltip>
            <i class="fa-solid fa-paper-plane" aria-hidden="true"></i>
            <span>{expression="$assignedTo->name"}</span>
        </span>
    {{elseif $item->canAssign()}}
        <span class="ipsBadge ipsBadge--soft ipsBadge--assigned {$classes}" {{if $assignedTo instanceof \IPS\Member\Team}}title='{lang="assigned_to_other_team" sprintf="$assignedTo->name"}'{{else}}title='{lang="assigned_to_other" sprintf="$assignedTo->name"}'{{endif}} data-ipsTooltip>
            <i class="fa-solid fa-paper-plane" aria-hidden="true"></i>
            <span>{expression="$assignedTo->name"}</span>
        </span>
    {{endif}}
{{endif}}

{{if $wordbreak}}<div class=''>{{endif}}
<a href='{$url}'{{if $newWindow === TRUE}} target='_blank' {{if $nofollow === FALSE}}rel="{{if $noreferrer}}noreferrer{{else}}noopener{{endif}}"{{endif}}{{endif}}{{if $nofollow === TRUE}} rel="nofollow{{if $newWindow === TRUE}} {{if $noreferrer}}noreferrer{{else}}noopener{{endif}}{{endif}}"{{endif}}>
	{{if $title}}
		{{if $titleRaw}}
			 {$title|raw}
		{{else}}
			{$title}
		{{endif}}
	{{else}}
		{$url}
	{{endif}}
</a>
{{if $wordbreak}}</div>{{endif}}

{{if !\IPS\Request::i()->isAjax()}}
    <html lang="{expression="\IPS\Member::loggedIn()->language()->bcp47()"}" dir="{{if member.language()->isrtl}}rtl{{else}}ltr{{endif}}" {{if isset(\IPS\Request::i()->cookie['acptheme']) AND \IPS\Request::i()->cookie['acptheme'] == 'dark'}}data-ips-scheme="dark"{{elseif !isset(\IPS\Request::i()->cookie['acptheme']) AND isset(\IPS\Request::i()->cookie['acpthemedefault']) AND \IPS\Request::i()->cookie['acpthemedefault'] == 'dark'}}data-ips-scheme="dark"{{else}}data-ips-scheme="light"{{endif}}>
        <head>
            <meta charset="utf-8">
            {template="includeCSS" app="core" group="global" location="global" params=""}
        </head>
        <body>
            {$html|raw}
            {template="includeJS" app="core" group="global" location="global" params=""}
        </body>
    </html>
{{else}}
    {$html|raw}
{{endif}}

{{if $title and $showTitle}}
<div class='i-padding_3'>
	<h1 class='ipsTitle ipsTitle--h3'>{$title}</h1>
</div>
{{endif}}
<div data-template='block' class='{$class}' {{if $id !== NULL}}id="{$id}"{{endif}}>
	{$content|raw}
</div>

{{if \count( \IPS\Output::i()->breadcrumb )}}
	<nav class='ipsBreadcrumb ipsBreadcrumb--acp'>
		<ol itemscope="" itemtype="https://schema.org/BreadcrumbList" class="ipsBreadcrumb__list">
			{{$i = 0;}}
			{{foreach \IPS\Output::i()->breadcrumb as $k => $b}}
				<li>
					{{if $b[0] === NULL}}
						<span>{lang="$b[1]"}</span>
					{{else}}
						<a href='{$b[0]}'>{lang="$b[1]"}</a>
					{{endif}}
				</li>
				{{$i++;}}
			{{endforeach}}
		</ol>
	</nav>
{{endif}}

{{if isset( $chart->errors ) AND \count( $chart->errors )}}
	<div class='ipsMessage ipsMessage--error'>
		{{foreach $chart->errors as $error}}
			{{if isset($error['sprintf'])}}
				{lang="$error['string']" sprintf="$error['sprintf']"}
			{{else}}
				{lang="$error['string']"}
			{{endif}}
		{{endforeach}}
	</div>
{{endif}}
<div class="ipsChart__table-wrapper ipsLoading ipsLoading--small" data-ipsChart data-ipsChart-type="{$type}" data-ipsChart-extraOptions='{$options|raw}' {{if $format}}data-ipsChart-format='{$format}'{{endif}}>
    <table class="ipsTable" >
        <thead>
            <tr>
                {{foreach $chart->headers as $data}}
                    <th data-colType="{$data['type']}">{$data['label']}</th>
                {{endforeach}}
            </tr>
        </thead>
        <tbody>
            {{foreach $chart->rows as $row}}
                <tr>
                    {{foreach $row as $value}}
                        <td {{if \is_array( $value )}}data-key="{$value['key']}"{{endif}}>{{if \is_array( $value )}}{$value['value']}{{else}}{$value}{{endif}}</td>
                    {{endforeach}}
                </tr>
            {{endforeach}}
        </tbody>
    </table>
</div>
<div class="ipsChart"></div>

{{$idField = $comment::$databaseColumnId;}}
<div data-ips-hook="commentWrap" id='comment-{$comment->$idField}_wrap' data-controller='core.front.core.comment' data-feedid="{$comment->feedId}" data-commentApp='{$app}' data-commentType='{$type}' data-commentID="{$comment->$idField}" data-quoteData='{expression="json_encode( array('userid' => $comment->author()->member_id, 'username' => $comment->author()->name, 'timestamp' => $comment->mapped('date'), 'contentapp' => $app, 'contenttype' => $type, 'contentclass' => $class, 'contentid' => $item->id, 'contentcommentid' => $comment->$idField) )"}' class='ipsEntry__content js-ipsEntry__content'
{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\IntersectionViewTracking' ) AND $hash=$comment->getViewTrackingHash()}}
data-view-hash="{$hash|raw}"
data-view-tracking-data="{expression="base64_encode(json_encode( $comment->getViewTrackingData() ))" raw="true"}"
{{endif}}
>
	<header class='ipsEntry__header'>
		<div class='ipsEntry__header-align'>
			<div class='ipsPhotoPanel'>
				<div class='ipsAvatarStack' data-ips-hook="commentUserPhoto">
					{template="userPhoto" app="core" group="global" params="$comment->author(), 'fluid', $comment->warningRef()"}
					{{if ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Anonymous' ) AND !$comment->isAnonymous() ) and $comment->author()->canHaveAchievements() and \IPS\core\Achievements\Rank::show() and $rank = $comment->author()->rank()}}
						{$rank->html( 'ipsAvatarStack__rank' )|raw}
					{{endif}}
				</div>
				<div class='ipsPhotoPanel__text'>
					<div data-ips-hook="commentUsername" class='ipsEntry__username'>
						<h3>{template="userLink" app="core" group="global" params="$comment->author(), $comment->warningRef(), NULL, \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Anonymous' ) ? $comment->isAnonymous() : FALSE"}</h3>
						{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Anonymous' ) AND !$comment->isAnonymous()}}
							<span class='ipsEntry__group'>
								{{if $comment->author()->modShowBadge()}}
									<a href='{url="app=core&module=staffdirectory&controller=directory" seoTemplate="staffdirectory"}' class="ipsEntry__moderatorBadge" data-ipsTooltip title='{lang="member_is_moderator" sprintf="$comment->author()->name"}'>
										{expression="\IPS\Member\Group::load( $comment->author()->member_group_id )->formattedName" raw="true"}
									</a>
								{{else}}
									{expression="\IPS\Member\Group::load( $comment->author()->member_group_id )->formattedName" raw="true"}
								{{endif}}
							</span>
						{{endif}}
						{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Anonymous' ) and $comment->isAnonymous() and \IPS\Member::loggedIn()->modPermission('can_view_anonymous_posters')}}
							<a data-ipsHover data-ipsHover-width="370" data-ipsHover-onClick href="{$comment->url( 'reveal' )->csrf()}"><span class="ipsAnonymousIcon" data-ipsTooltip title='{lang="post_anonymously_reveal"}'></span></a>
						{{endif}}
					</div>
					<p class='ipsPhotoPanel__secondary'>
						{{if ! \IPS\Output::i()->reduceLinks()}}<a href='{$comment->shareableUrl()}'>{{endif}}{$comment->dateLine()|raw}{{if ! \IPS\Output::i()->reduceLinks()}}</a>{{endif}}
						{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\EditHistory' )  and $comment->editLine()}}
							({lang="edited_lc"})
						{{endif}}
					</p>
				</div>
			</div>
			{{if $comment->author()->hasHighlightedReplies() || ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and $comment->isHighlighted() ) OR ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\MetaData' ) and $comment->isFeatured() ) }}
				<ul data-ips-hook="commentBadges" class='ipsBadges'>
					{{if $comment->author()->hasHighlightedReplies()}}
						<li><span class='ipsBadge ipsBadge--highlightedGroup'>{expression="\IPS\Member\Group::load( $comment->author()->highlightedGroup() )->name" raw="true"}</span></li>
					{{endif}}
					{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\MetaData' ) and $comment->isFeatured() }}
					<li><span class='ipsBadge ipsBadge--positive'>{lang="this_is_a_featured_post"}</span></li>
					{{endif}}
					{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and $comment->isHighlighted()}}
						<li><span class='ipsBadge ipsBadge--popular'>{lang="this_is_a_popular_comment"}</span></li>
					{{endif}}
				</ul>
			{{endif}}
			{{if \count( $item->commentMultimodActions() )}}
				<label>
					<span class="ipsInvisible">{lang="mod_checkbox"}</span>
					<input type="checkbox" name="multimod[{$comment->$idField}]" value="1" data-role="moderation" data-actions="{{if $comment->canSplit()}}split merge{{endif}} {{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) and $comment->hidden() === -1 AND $comment->canUnhide()}}unhide{{elseif \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) and $comment->hidden() === 1 AND $comment->canUnhide()}}approve{{elseif \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) and $comment->canHide()}}hide{{endif}} {{if $comment->canDelete()}}delete{{endif}}" data-state='{{if $comment->tableStates()}}{$comment->tableStates()}{{endif}}' class="ipsInput ipsInput--toggle">
				</label>
			{{endif}}
			{$comment->menu()|raw}
			{{if $comment->author()->member_id}}
				<button class='ipsEntry__topButton ipsEntry__topButton--profile' type='button' aria-controls='mini-profile-comment-{$comment->$idField}' aria-expanded='false' data-ipscontrols data-ipscontrols-src="{$comment->authorMiniProfileUrl}" data-ipstooltip='{lang="author_stats"}'><i class="fa-solid fa-chevron-down" aria-hidden="true"></i><span class="ipsInvisible">{lang="author_stats"}</span></button>
                {template="miniProfileWrap" app="core" group="global" params="$comment->author(), $comment->$idField, 'comment', remoteLoading:true"}
			{{endif}}
		</div>
	</header>
	<div class='ipsEntry__post'>
		{{if member.modPermission('mod_see_warn') and $comment->warning}}
			{template="commentWarned" group="global" app="core" params="$comment"}
		{{endif}}
		{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND  $comment->hidden() AND $comment->hidden() != -2}}
			<div class='ipsEntry__hiddenMessage'>{$comment->hiddenBlurb()}</div>
		{{elseif \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND  $comment->hidden() == -2}}
			<div class='ipsEntry__hiddenMessage'>{$comment->deletedBlurb()}</div>
		{{endif}}
		{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND  $comment->hidden() === 1 && $comment->author()->member_id == \IPS\Member::loggedIn()->member_id}}
			<div class='i-margin-bottom_3'><strong class='i-color_warning'><i class='fa-solid fa-circle-info' aria-hidden="true"></i> {lang="comment_awaiting_approval"}</strong></div>
		{{endif}}
		<div data-ips-hook="comment" class='ipsRichText ipsRichText--user' data-role='commentContent' data-controller='core.front.core.lightboxedImages'>
			{$comment->content()|raw}
			{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\EditHistory' ) and $comment->editLine()}}
				{$comment->editLine()|raw}
			{{endif}}
		</div>
	</div>

	{{if ( ( ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() !== 1 ) || ! \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) ) && \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and settings.reputation_enabled and $comment->hasReactionBar() ) || ( ( ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() === 1 and ( $comment->canUnhide() || $comment->canDelete() ) ) || ! \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) ) && ( $comment->canDelete() ) ) || ( ( ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() === 0 )  || ! \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) ) and $item->canComment() and $editorName )}}
		<div data-ips-hook="commentFooter" class='ipsEntry__footer'>
			<menu class='ipsEntry__controls' data-role="commentControls" data-ips-hook="commentControls">
				{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() === 1 && ( $comment->canUnhide() || $comment->canDelete() )}}
					{{if $comment->canUnhide()}}
						<li><a href='{$comment->url('unhide')->csrf()}' class='ipsButton ipsButton--small ipsButton--positive' data-action='approveComment'><i class='fa-solid fa-check' aria-hidden="true"></i><span>{lang="approve"}</span></a></li>
					{{endif}}
					{{if $comment->canDelete()}}
						<li><a href='{$comment->url('delete')->csrf()->setPage('page',\IPS\Request::i()->page)}' data-action='deleteComment' data-updateOnDelete="#commentCount"><i class='fa-solid fa-xmark' aria-hidden="true"></i><span>{lang="delete"}</span></a></li>
					{{endif}}
					{{if $comment->canEdit() || $comment->canSplit() || $comment->canHide()}}
						<li>
							<button type="button" id="elControlsCommentsSub_{$comment->$idField}" popovertarget="elControlsCommentsSub_{$comment->$idField}_menu"><span>{lang="moderator_tools"}</span><i class='fa-solid fa-caret-down' aria-hidden="true"></i></button>
							<i-dropdown popover id="elControlsCommentsSub_{$comment->$idField}_menu">
								<div class="iDropdown">
									<ul class="iDropdown__items">
										{{if $comment->canEdit()}}
											{{if $comment->mapped('first') and $comment->item()->canEdit()}}
												<li><a href='{$comment->item()->url()->setQueryString( 'do', 'edit' )}'>{lang="edit"}</a></li>
											{{else}}
												<li><a href='{$comment->url('edit')}' data-action='editComment'>{lang="edit"}</a></li>
											{{endif}}
										{{endif}}
										{{if $comment->canSplit()}}
											<li><a href='{$comment->url('split')}' data-action='splitComment' data-ipsDialog data-ipsDialog-title="{lang="split_to_new" sprintf="\IPS\Member::loggedIn()->language()->addToStack( $item::$title )"}">{lang="split"}</a></li>
										{{endif}}
										{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) and $comment->canHide()}}
											<li><a href='{$comment->url('hide')->csrf()}' data-ipsDialog data-ipsDialog-title="{lang="hide"}">{lang="hide"}</a></li>
										{{endif}}
									</ul>
								</div>
							</i-dropdown>
						</li>
					{{endif}}
				{{else}}
					{{if ( ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() === 0 ) || ! \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) ) and $item->canComment() and $editorName}}
						<li data-ipsQuote-editor='{$editorName}' data-ipsQuote-target='#comment-{$comment->$idField}' class='ipsJS_show'>
							<button class='cMultiQuote ipsHide' data-action='multiQuoteComment' data-ipsTooltip data-ipsQuote-multiQuote data-mqId='mq{$comment->$idField}' aria-label='{lang="multiquote"}'><i class='fa-solid fa-plus' aria-hidden="true"></i></button>
						</li>
						<li data-ipsQuote-editor='{$editorName}' data-ipsQuote-target='#comment-{$comment->$idField}' class='ipsJS_show'>
							<a href='#' data-action="quoteComment" data-ipsQuote-singleQuote><i class="fa-solid fa-quote-left" aria-hidden="true"></i><span>{lang="quote"}</span></a>
						</li>
						{{if \IPS\Application::appIsEnabled('cloud')}}
							<li>{template="spam" app="cloud" group="spam" params="$comment, FALSE"}</li>
						{{endif}}	
					{{endif}}
				{{endif}}
				<li class='ipsHide' data-role='commentLoading'>
					<span class='ipsLoading ipsLoading--tiny'></span>
				</li>
			</menu>
			{{if ( ( \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) AND $comment->hidden() !== 1 ) || ! \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Hideable' ) ) && \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and settings.reputation_enabled and $comment->hasReactionBar()}}
				{template="reputation" group="global" app="core" params="$comment"}
			{{endif}}
		</div>
	{{endif}}
	{{if ! \IPS\Output::i()->reduceLinks()}}
	{template="sharemenu" group="global" app="core" params="$comment"}
	{{endif}}
</div>

{{if !\IPS\Request::i()->isAjax()}}
<h1 class='ipsTitle ipsTitle--h3'>{lang="edit_history_title"}</h1>
{{endif}}

{{if \IPS\Settings::i()->edit_log_prune > 0}}
	<div class='ipsMessage ipsMessage--info {{if !\IPS\Request::i()->isAjax()}}i-margin-top_3{{else}}i-margin_2{{endif}}'>{lang="edit_log_prune_notice" pluralize="\IPS\Settings::i()->edit_log_prune"}</div>
{{endif}}

<div class="i-padding_3" data-role="commentFeed">
    {$editHistory|raw}
