		</div>
	</div>
</div>

{{$member = \IPS\Member::load( $message['added_by'] );}}
{{$class = \get_class( $item );}}
<div class="ipsMessage ipsMessage--withButtons {{if isset( $message['color'] )}}ipsMessage--{$message['color']}{{endif}} ipsPull">
	{{if isset( $message['is_public'] ) AND $message['is_public'] }}
		{template="userPhoto" group="global" app="core" params="$member, 'fluid'"}
	{{else}}
		<i class="fa-solid fa-user-shield ipsMessage__icon" aria-hidden="true"></i>
	{{endif}}
	<div>
		<div>
			{{if $member->member_id}}
				<strong class="i-font-weight_600">{lang="content_item_message" sprintf="$member->name"}</strong>{{if isset( $message['date'] ) }}<span class='i-color_soft'>, {datetime="$message['date']"}</span>{{endif}}
			{{else}}
				{{if isset( $message['date'] ) }}<span class='i-color_soft'>{datetime="$message['date']"}</span>{{endif}}
			{{endif}}

			{{if isset( $message['is_public'] ) AND !$message['is_public'] }}
				<span class='ipsBadge'>{lang="message_staff_badge"}</span>
			{{endif}}
		</div>	
		{template="richText" group="global" app="core" location="global" params="$message['message'], array('i-margin-top_1')"}
	</div>
	<ul class='ipsButtons'>
		{{if $item->canOnMessage( 'edit' )}}
			<li>
				<a href='{$item->url()->setQueryString( array( 'do' => 'messageForm', 'meta_id' => $id ) )}' data-ipsDialog data-ipsDialog-title='{lang="edit"}' class="ipsButton"><i class="fa-solid fa-pen-to-square" aria-hidden="true"></i> {lang="edit"}</a>
			</li>
		{{endif}}
		{{if $item->canOnMessage( 'delete' )}}
			<li>
				<a href='{$item->url()->csrf()->setQueryString( array( 'do' => 'messageDelete', 'meta_id' => $id ) )}' data-confirm class="ipsButton"><i class="fa-regular fa-trash-can" aria-hidden="true"></i> {lang="delete"}</a>
			</li>
		{{endif}}
	</ul>	
</div>

{{foreach $messages AS $id => $message}}
	{template="contentItemMessage" app="core" group="global" params="$message, $item, $id"}
{{endforeach}}

{{$idColumn = $item::$databaseColumnId;}}
{{$itemClassSafe = str_replace( '\\', '_', mb_substr( $item::class, 4 ) );}}
<div data-ips-hook="contentWrap" id='{$key}-{$item->$idColumn}_wrap' data-controller='core.front.core.comment' data-feedid="{$item->feedId}" data-commentApp='{$item::$application}' data-commentType='{$item::$module}' data-quoteData='{expression="json_encode( array('userid' => $item->author()->member_id, 'username' => $item->author()->name, 'timestamp' => $item->mapped('date'), 'contentapp' => $item::$application, 'contenttype' => $item::$module, 'contentclass' => $itemClassSafe, 'contentid' => $item->$idColumn) )"}' class='ipsEntry__content js-ipsEntry__content'>
    <div data-role='commentContent' class='ipsRichText ipsRichText--user' data-controller='core.front.core.lightboxedImages'>{$item->content()|raw}</div>

    {{if ( ( \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Hideable' ) AND $item->hidden() === 0 ) || ! \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Hideable' ) ) and $item->canComment()}}
        <div data-ipsquote-editor='{$item::$formLangPrefix}comment' data-ipsquote-target='#{$key}-{$item->$idColumn}' class='ipsHide'>
            <a href='#' data-action='quoteComment' data-ipsqoute-singlequote=''></a>
        </div>
    {{endif}}
</div>

{{foreach $author->contentProfileFields() as $group => $fields}}
	{{foreach $fields as $field => $value}}
		<li data-el='{$field|raw}' data-role='custom-field'>
			{$value|raw}
		</li>
	{{endforeach}}
{{endforeach}}

{{if $sidebar !== NULL}}
	<div class="ipsColumns">
		<div class="ipsColumns__primary">
{{endif}}
			<i-data>
				<ul class="ipsData ipsData--table ipsData--compact ipsData--definition-table">
					{{foreach $rows as $k => $v}}
						<li class="ipsData__item">
							<div class="ipsData__content">
								<div class="i-basis_180">
									<strong class="ipsData__title">
										{{if $parse}}
											{lang="$k"}
										{{else}}
											{$k}
										{{endif}}
									</strong>
								</div>
								<div class="">
									{{if $v}}
										{$v}
									{{else}}
										<em class="i-color_soft">{lang="unknown"}</em>
									{{endif}}
								</div>
							</div>
						</li>
					{{endforeach}}
				</ul>
			</i-data>
{{if $sidebar !== NULL}}
		</div>
		<div class="ipsColumns__secondary i-basis_360">
			{$sidebar|raw}
		</div>
	</div>
{{endif}}

{{$useImage = NULL;}}
<div class='ipsRichEmbed ipsRichEmbed--comment'>
	{template="embedHeader" group="embed" app="core" params="$comment, $item->mapped('title'), $comment->mapped('date'), $url"}
	<div class='ipsRichEmbed__content'>
		<div class='ipsRichEmbed_originalItem'>
			<div>
				{{if $image}}
					{{$useImage = $image;}}
				{{elseif $contentImage = $item->contentImages(1)}}
					{{$attachType = key( $contentImage[0] );}}
					{{$useImage = \IPS\File::get( $attachType, $contentImage[0][ $attachType ] );}}
				{{endif}}

				{{if $useImage}}
					<a href='{$url}' class='ipsRichEmbed_masthead'>
						<img src='{$useImage->url}' alt='' loading="lazy">
					</a>
				{{endif}}

				<div class='i-padding_3'>
					{template="embedOriginalItem" group="embed" app="core" params="$item"}
				</div>
			</div>
		</div>

		<div class='ipsRichEmbed__snippet'>
			{$comment->truncated(TRUE)|raw}
		</div>

		{{if settings.reputation_enabled and \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and \count( $comment->reactions() )}}
			<ul class='ipsList ipsList--inline i-margin-top_2'>
				<li>
					{template="reactionOverview" app="core" group="global" params="$comment, TRUE, 'small'"}
				</li>
			</ul>
		{{endif}}
	</div>
</div>

{{$useImage = NULL;}}
<div class='ipsRichEmbed ipsRichEmbed--review'>
	{template="embedHeader" group="embed" app="core" params="$review, $item->mapped('title'), $review->mapped('date'), $url"}
	<div class='ipsRichEmbed__content'>
		<div class='ipsRichEmbed_originalItem'>
			<div>
				{{if $image}}
					{{$useImage = $image;}}
				{{elseif $contentImage = $item->contentImages(1)}}
					{{$attachType = key( $contentImage[0] );}}
					{{$useImage = \IPS\File::get( $attachType, $contentImage[0][ $attachType ] );}}
				{{endif}}

				{{if $useImage}}
					<a href='{$url}' class='ipsRichEmbed_masthead'>
						<img src='{$useImage->url}' alt='' loading='lazy'>
					</a>
				{{endif}}

				<div class='i-padding_3'>
					{template="embedOriginalItem" group="embed" app="core" params="$item"}
				</div>
			</div>
		</div>

		{template="rating" app="core" params="'veryLarge', $review->mapped('rating')" group="global"} 
		{{if $review->mapped('votes_total')}}
			<p>{$review->helpfulLine()|raw}</p>
		{{endif}}
		<hr class='ipsHr'>
		<div class='ipsRichEmbed__snippet'>
			{$review->truncated(TRUE)|raw}
		</div>

		{{if settings.reputation_enabled and \IPS\IPS::classUsesTrait( $review, 'IPS\Content\Reactable' ) and \count( $review->reactions() )}}
			<ul class='ipsList ipsList--inline i-margin-top_2'>
				<li>
					{template="reactionOverview" app="core" group="global" params="$review, TRUE, 'small'"}
				</li>
			</ul>
		{{endif}}
	</div>
</div>

{{if $code === '1X000/X' and \IPS\Application::appIsEnabled('cloud')}}
    {template="featureDisabled" app="cloud" location="admin" group="global" params="'cloud_service_level_upgrade_needed'"}
{{else}}
    <div class='ipsMessage ipsMessage--error'>
        <span class="ipsMessage_code">{$code}</span>
        {$message|raw}
    </div>

    <div class="i-padding_3">
        {{if ( \IPS\IN_DEV or $member->isAdmin() ) and $extra}}
            <h3 class="i-font-weight_500 i-color_hard i-margin-bottom_2 i-font-size_2">{lang="error_technical_details"}</h3>
            <textarea class="ipsInput ipsInput--text" rows="13" style="font-family: monospace;">{$extra}</textarea>
            <p class="i-color_soft i-text-align_center i-margin-top_2">
                {lang="error_technical_details_desc"}
                {{if member.hasAcpRestriction( 'core', 'support', 'system_logs_view' )}}
                    {lang="error_technical_details_logs"}
                {{endif}}
            </p>
        {{endif}}
        {{if member.hasAcpRestriction( 'core', 'support', 'get_support' )}}
            <div class="i-text-align_center i-padding-block_2">
                <a href='{url="app=core&module=support&controller=support" base="admin"}' title='{lang="get_support"}' class="ipsButton ipsButton--inherit">{lang="get_support"}</a>
            </div>
        {{endif}}
    </div>
{{endif}}

{{if \IPS\Settings::i()->icons_favicon}}
	{{$file = \IPS\File::get( 'core_Icons', \IPS\Settings::i()->icons_favicon );}}
	<link rel='icon' href='{$file->url}' type="{expression="\IPS\File::getMimeType( $file->originalFilename )"}">
{{endif}}

{{if isset( $comment['comment'] )}}
	{{$idField = $comment['comment']::$databaseColumnId;}}
	<div class='ipsEntry ipsEntry--simple ipsEntry--featuredComment' data-commentID='{$id}'>
		<header class="ipsEntry__header">
			<div class="ipsEntry__header-align">
				<div class="ipsPhotoPanel">
					{template="userPhoto" app="core" group="global" params="$comment['comment']->author(), 'fluid', $comment['comment']->warningRef()"}
					<div class="ipsPhotoPanel__text">
						<div class="ipsPhotoPanel__primary">{template="userLink" app="core" group="global" params="$comment['comment']->author(), $comment['comment']->warningRef()"}</div>
						<div class="ipsPhotoPanel__secondary"><a href="{$comment['comment']->url()}" title='{lang="go_to_this_comment" sprintf="\IPS\Member::loggedIn()->language()->get( $commentLang )"}' rel="nofollow" data-action='goToComment'>{$comment['comment']->dateLine()|raw}</a></div>
					</div>
				</div>
			</div>
		</header>
		<div class='ipsEntry__post'>
			<div class='ipsRichText ipsTruncate_2'>{$comment['comment']->truncated( TRUE )|raw}</div>
			{{if \IPS\IPS::classUsesTrait( $comment['comment'], 'IPS\Content\Reactable' ) and settings.reputation_enabled}}
				<div class='i-margin-top_2 i-flex'>
					{template="reactionOverview" group="global" app="core" params="$comment['comment']"}
				</div>
			{{endif}}
			{{if $comment['note']}}
				<div class='ipsEntry__recommendedNote'>
					<p>{$comment['note']}</p>
					{{if isset( $comment['featured_by'] )}}
						<p class='i-font-style_italic i-color_soft i-margin-top_1 i-link-color_inherit'>{lang="recommended_by" htmlsprintf="$comment['featured_by']->link()"}</p>
					{{endif}}
				</div>
			{{elseif isset( $comment['featured_by'] )}}
				{lang="recommended_by" htmlsprintf="$comment['featured_by']->link()"}
			{{endif}}
		</div>
	</div>
{{endif}}

{{$idField = $comment::$databaseColumnId;}}
{{$itemClassSafe = str_replace( '\\', '_', mb_substr( $comment::$itemClass, 4 ) );}}
{{if ! \IPS\Request::i()->isAjax()}}
	<h1 class='ipsTitle ipsTitle--h3'><a href="{$item->url()->setQueryString( array( 'do' => 'findComment', 'comment' => $comment->$idField ) )}">{$header}</a></h1>
{{endif}}
<article id='elComment_{$comment->$idField}' class='ipsEntry js-ipsEntry ipsEntry--find-comment {{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and $comment->isHighlighted()}}ipsEntry--popular{{endif}} {{if $comment->hidden()}}ipsModerated{{endif}}'>
	<div id='comment-{$comment->$idField}_wrap' data-controller='core.front.core.comment' data-feedid="{$comment->feedId}" data-commentApp='{$comment::$application}' data-commentType='{$item::$module}' data-commentID="{$comment->$idField}" data-quoteData='{expression="json_encode( array('userid' => $comment->author()->member_id, 'username' => $comment->author()->name, 'timestamp' => $comment->mapped('date'), 'contentapp' => $comment::$application, 'contenttype' => $item::$module, 'contentclass' => $itemClassSafe, 'contentid' => $item->id, 'contentcommentid' => $comment->$idField) )"}' class='ipsEntry__content js-ipsEntry__content'
{{if \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\IntersectionViewTracking' ) AND $hash=$comment->getViewTrackingHash()}}
data-view-hash="{$hash|raw}"
data-view-tracking-data="{expression="base64_encode(json_encode( $comment->getViewTrackingData() ))" raw="true"}"
{{endif}}
>
		<header class='ipsEntry__header'>
			<div class='ipsEntry__header-align'>
				<div class='ipsPhotoPanel'>
					<div>{template="userPhoto" app="core" group="global" params="$comment->author(), 'mini', $comment->warningRef()"}</div>
					<div class='ipsPhotoPanel__text'>
						<h3 class='ipsPhotoPanel__primary'>
							{template="userLink" app="core" group="global" params="$comment->author(), $comment->warningRef()"}
						</h3>
						<p class='ipsPhotoPanel__secondary'>
							<a href='{$comment->item()->url()->setQueryString( array( 'do' => 'findComment', 'comment' => $comment->id ) )}' class='i-color_inherit'>{$comment->dateLine()|raw}</a>
							{{if $comment->editLine()}}
								&middot; {$comment->editLine()|raw}
							{{endif}}
							{{if $comment->hidden()}}
								&middot; {$comment->hiddenBlurb()}
							{{endif}}
						</p>
						{{if member.modPermission('mod_see_warn') and $comment->warning}}
							{template="commentWarned" group="global" app="core" params="$comment"}
						{{endif}}
					</div>
				</div>
			</div>
		</header>
		<div class='ipsEntry__post'>
			{{if settings.reputation_enabled and \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and $comment->isHighlighted()}}
				<strong class='ipsEntry__popularFlag' data-ipsTooltip title='{lang="this_is_a_popular_comment"}'><i class='fa-solid fa-heart' aria-hidden="true"></i></strong>
			{{endif}}
			<div data-role='commentContent' class='ipsRichText' data-controller='core.front.core.lightboxedImages'>
				{{if $comment->hidden() === 1 && $comment->author()->member_id == \IPS\Member::loggedIn()->member_id}}
					<strong class='i-color_warning'><i class='fa-solid fa-circle-info' aria-hidden="true"></i> {lang="comment_awaiting_approval"}</strong>
				{{endif}}
				{$comment->content()|raw}
			</div>
			{{if $comment->hidden() !== 1 && \IPS\IPS::classUsesTrait( $comment, 'IPS\Content\Reactable' ) and settings.reputation_enabled}}
				<br>
				{template="reputation" group="global" app="core" params="$comment"}
			{{endif}}
		</div>
	</div>
</article>

{{if member.member_id}}
	{{if member.following( $app, $area, $id )}}
		<div data-ips-hook="following" class="ipsButton ipsButton--follow ipsButton--follow-active" data-role="followButton" data-following="true">
			<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}"}" rel="nofollow" title="{lang="following_this_content"}" data-ipsTooltip data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick><i class="fa-solid fa-bell" aria-hidden="true"></i><span class="ipsButton__label">{lang="following_this"}</span><i class='ipsMenuCaret' aria-hidden="true"></i></a>
			{{if \IPS\Member::loggedIn()->group['g_view_followers']}}
			<a class='ipsButton__segment' href='{url="app=core&module=system&controller=notifications&do=followers&follow_app={$app}&follow_area={$area}&follow_id={$id}"}' rel="nofollow" title='{lang="followers_tooltip"}' data-ipsTooltip data-ipsDialog data-ipsDialog-size='narrow' data-ipsDialog-title='{lang="who_follows_this"}'>{number="$count" format="short"}</a>
			{{endif}}
		</div>
	{{else}}	
		<div data-ips-hook="notfollowing" class="ipsButton ipsButton--follow" data-role="followButton" data-following="false">
			<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}"}" rel="nofollow" title="{lang="follow_this_content"}" data-ipsTooltip data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick><i class="fa-regular fa-bell" aria-hidden="true"></i><span class="ipsButton__label">{lang="follow"}</span><i class='ipsMenuCaret' aria-hidden="true"></i></a>
			{{if $count > 0 and \IPS\Member::loggedIn()->group['g_view_followers']}}
				<a class='ipsButton__segment' href='{url="app=core&module=system&controller=notifications&do=followers&follow_app={$app}&follow_area={$area}&follow_id={$id}"}' rel="nofollow" title='{lang="followers_tooltip"}' data-ipsTooltip data-ipsDialog data-ipsDialog-size='narrow' data-ipsDialog-title='{lang="who_follows_this"}'>{number="$count" format="short"}</a>
			{{endif}}
		</div>
	{{endif}}
{{else}}
	<a data-ips-hook="guest" href='{url="app=core&module=system&controller=login" seoTemplate="login"}' rel="nofollow" class="ipsButton ipsButton--follow" data-role="followButton" data-ipsTooltip title='{lang="follow_sign_in"}'>
		<span>
			<i class="fa-regular fa-bell" aria-hidden="true"></i>
			<span class="ipsButton__label">{lang="followers"}</span>
		</span>
		{{if $count > 0 and \IPS\Member::loggedIn()->group['g_view_followers']}}
			<span class='ipsButton__segment'>{number="$count" format="short"}</span>
		{{endif}}
	</a>
{{endif}}

{{if \is_array($item)}}
	{{if $item['feature_color']}}style="--i-featured: {$item['feature_color']}; --i-featured-text: {$item['text_color']};"{{endif}}
{{else}}
	{{$column = $item::$featureColumnName;}}
	{{if $item->$column}}style="--i-featured: {$item->$column}; --i-featured-text: {$item->_featureTextColor};"{{endif}}
{{endif}}

{{if \is_array($item)}}
<span class="ipsContainerTitle" {template="formattedInlineStyle" params="$item" app="core" group="global" location="front"}>{$item['title']}</span>
{{else}}
<span class="ipsContainerTitle" {template="formattedInlineStyle" params="$item" app="core" group="global" location="front"}>{$item->_title}</span>
{{endif}}

{{if $title}}
	{template="pageHeader" app="core" group="global" location="front" params="$title"}
{{endif}}
<div class='{{if $classes}}{$classes}{{endif}}'>
	{$content|raw}
</div>

{{$theme = \IPS\Theme::i();}}
{{foreach $theme->theme_editor_data['header'] as $type => $pos}}
	{{if $pos == $position}}
		<div data-ips-header-content='{$type}'>
			<!-- {$type} -->
			{{if $type == 'logo'}}
				{template="logo" app="core" group="global" params="'desktop'"}
			{{endif}}
			{{if !\in_array( 'ipsLayout_minimalNoHome', \IPS\Output::i()->bodyClasses )}}
			    {{if $type == 'navigation' and !\in_array( 'ipsLayout_minimal', \IPS\Output::i()->bodyClasses )}}
				    {template="navBar" app="core" group="global" params=""}
			    {{endif}}
			    {{if $type == 'user' AND !\in_array( 'ipsLayout_minimal', \IPS\Output::i()->bodyClasses )}}
				    {template="userBar" app="core" group="global" params=""}
			    {{endif}}
			    {{if $type == 'breadcrumb'}}
				    {template="breadcrumb" app="core" group="global" params="'top'"}
			    {{endif}}
			    {{if $type == 'search' and !\in_array( 'ipsLayout_minimal', \IPS\Output::i()->bodyClasses )}}
				    {template="searchDialogTrigger" app="core" group="global" params=""}
			    {{endif}}
			{{endif}}
		</div>
	{{endif}}
{{endforeach}}

{{$width = $mapParameters['width'] ?? 500;}}
{{$height = $mapParameters['height'] ?? 500;}}
<div data-controller="ips.core.map.googlemap" data-map-data='{expression="json_encode( $mapParameters )"}' style="width:{$width}px; height: {$height}px; max-width: 100%; max-height: 100%; overflow: hidden;" >
    {{if isset($mapParameters['lat']) and isset($mapParameters['long']) }}
    <span itemscope itemtype='http://schema.org/GeoCoordinates'>
		<meta itemprop='latitude' content='{$mapParameters["lat"]}'>
		<meta itemprop='longitude' content='{$mapParameters["long"]}'>
	</span>
    {{endif}}
    <div data-role="mapContainer" style="width: 100%; height: 100%;"></div>
</div>

{{foreach $groups as $group}}
	{{$groupNames[] = $group->name;}}
{{endforeach}}
{{$list = \IPS\Member::loggedIn()->language()->formatList( $groupNames );}}

<ul class="ipsData__groups {$extraClasses}" {{if $lang}}data-ipsTooltip title='{lang="$lang" htmlsprintf="$list"}'{{endif}}>
	{{foreach $groups as $group}}
		{{if $group->g_icon }}
			<li><img src='{file="$group->g_icon" extension="core_Theme"}' alt='' loading='lazy' {{if $width = $group->g_icon_width}}width="{$width}"{{endif}}></li>
		{{else}}
			<li><span class='ipsBadge ipsBadge--neutral'>{$group->name}</span></li>
		{{endif}}
	{{endforeach}}
</ul>

{{$termsLang = \IPS\Member::loggedIn()->language()->addToStack( 'terms_of_use' );}}
{{$privacyLang = \IPS\Member::loggedIn()->language()->addToStack( 'terms_privacy' );}}
{{$glLang = \IPS\Member::loggedIn()->language()->addToStack( 'guidelines' );}}
{{$termsUrl = (string) \IPS\Http\Url::internal( 'app=core&module=system&controller=terms', 'front', 'terms' );}}
{{$terms = "<a href='$termsUrl'>$termsLang</a>";}}

{{if \IPS\Settings::i()->privacy_type == 'internal'}}
	{{$privacyUrl = (string) \IPS\Http\Url::internal( 'app=core&module=system&controller=privacy', 'front', 'privacy' );}}
{{else}}
	{{$privacyUrl = \IPS\Settings::i()->privacy_link;}}
{{endif}}
{{$privacy = "<a href='$privacyUrl'>$privacyLang</a>";}}

{{if \IPS\Settings::i()->gl_type == 'internal'}}
	{{$glUrl = (string) \IPS\Http\Url::internal( 'app=core&module=system&controller=guidelines', 'front', 'guidelines' );}}
{{else}}
	{{$glUrl = \IPS\Settings::i()->gl_link;}}
{{endif}}
{{$guidelines = "<a href='$glUrl'>$glLang</a>";}}
{{$cookiesUrl = (string) \IPS\Http\Url::internal( 'app=core&module=system&controller=cookies', 'front', 'cookies' );}}
{{$cookies = \IPS\Member::loggedIn()->language()->addToStack( 'cookies_message', FALSE, array( 'sprintf' => array( $cookiesUrl, $cookiesUrl ) ) );}}
<i-cookie-consent id='elGuestTerms' role="region" aria-labelledby="elGuestTermsLabel" hidden data-role='{{if \IPS\Request::i()->cookieConsentEnabled()}}cookieConsentBar{{else}}guestTermsBar{{endif}}' tabindex="-1">
	<div class='ipsWidth'>
		<div class='ipsColumns i-align-items_center i-gap_3'>
			<div class='ipsColumns__primary'>
				<h4 class='ipsTitle ipsTitle--h5 ipsTitle--margin' id="elGuestTermsLabel">{lang="guest_terms_title"}</h4>
				<p class='i-color_soft'>{lang="guest_terms_bar_text_value" htmlsprintf="$terms, $privacy, $guidelines, $cookies"}</p>
			</div>
			<div class='ipsColumns__secondary'>
                {{if \IPS\Request::i()->cookieConsentEnabled()}}
					<form action="{url="app=core&module=system&controller=cookies&do=cookieConsentToggle&ref={$currentUrl}" csrf="true"}" method="post">
						<input type="hidden" name='ref' value="{$currentUrl}">
						<div class="ipsButtons">
							<button name="status" value="0" class='ipsButton ipsButton--inherit'>{lang='cookieconstent_reject'}</button>
							<button name="status" value="1" class='ipsButton ipsButton--positive'><i class='fa-solid fa-check' aria-hidden="true"></i> {lang='accept_cookies'}</button>
						</div>
					</form>
                {{else}}
					<div class="ipsButtons">
						<a href='{url="app=core&module=system&controller=terms&do=dismiss&ref={$currentUrl}" csrf="true"}' rel='nofollow' class='ipsButton ipsButton--positive' data-action="dismissTerms"><i class='fa-solid fa-check' aria-hidden="true"></i> {lang="guest_terms_close"}</a>
					</div>
                {{endif}}
            </div>
		</div>
	</div>
</i-cookie-consent>

