{{if (cssvar.set__i-change-scheme == "1" && isset(\IPS\Request::i()->cookie['scheme_preference']) && \IPS\Request::i()->cookie['scheme_preference'] === 'system') || (cssvar.set__i-change-scheme == "0" && cssvar.set__i-default-scheme == "system") || (cssvar.set__i-change-scheme == "1" && !isset(\IPS\Request::i()->cookie['scheme_preference']) && cssvar.set__i-default-scheme == "system") }}
	{{/*}}<!-- If you can change the color scheme and you've chosen System OR if you can't change the color scheme and it's set to System.. apply it -->{{*/}}
	<script>(() => document.documentElement.setAttribute('data-ips-scheme', (window.matchMedia('(prefers-color-scheme:dark)').matches) ? 'dark':'light'))();</script>
{{endif}}

{{if $text}}
    {{$url = \IPS\Content\Tag::buildTagUrl( $text );}}
	<a href='{$url}' title="{lang="find_tagged_content" sprintf="$text"}" class='ipsBadge ipsBadge--prefix' rel="tag" data-tag-label='{$text}' data-ipsTooltip><span>{$text}</span></a>
{{endif}}

{{$completion = \intval( (string) \IPS\Member::loggedIn()->profileCompletionPercentage() );}}
{{if ! ( $completion == 100 and $hideOnCompletion )}}
<div data-role='profileWidget' data-controller="core.front.core.profileCompletion">
	{{$progressId = 'ipsProgress-' . mt_rand();}}
	{{if $completion < 100}}
		<div class='i-flex i-align-items_center i-flex-wrap_wrap i-margin-bottom_2'>
			<div class='i-flex_91'>
				<h4 class="ipsTitle ipsTitle--h6">{lang="profile_step_next"} {lang="profile_step_title_{$nextStep->id}"}</h4>
				<small class='i-color_soft' id="{$progressId}">{lang="profile_completion_percent" sprintf="$completion . '%'"}</small>
			</div>
			<ul class="ipsButtons">
				{{if $canDismiss}}
					<li>
						<a class="ipsButton ipsButton--small ipsButton--inherit" href='{url="app=core&module=system&controller=settings&do=dismissProfile" ref="(string) \IPS\Request::i()->url()" csrf="true"}' data-role='dismissProfile'>{lang="dismiss"}</a>
					</li>
				{{endif}}
				<li>
					<a class="ipsButton ipsButton--small ipsButton--primary" href='{url="app=core&module=system&controller=settings&do=completion&_new=1" ref="(string) \IPS\Request::i()->url()" seoTemplate="settings"}'><span>{lang="complete_my_profile"}</span><i class="fa-solid fa-arrow-right-long" aria-hidden="true"></i></a>
				</li>
			</ul>
		</div>
	{{else}}
		<span class='ipsInvisible' id="{$progressId}">{lang="profile_completion_percent" sprintf="'100%'"}</span>
	{{endif}}	
	<progress aria-labelledby="{$progressId}" class="ipsProgress" min="0" max="100" value='{expression="\IPS\Member::loggedIn()->profileCompletionPercentage()"}'></progress>
</div>
{{endif}}

{{if !\IPS\Content\Reaction::isLikeMode()}}
	{{$reactions = \IPS\Content\Reaction::roots();}}
	<ul class='ipsReact_reactions'>
		{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
			<li class="ipsReact_overview">
				{$content->whoReacted(null, $anonymized)}
			</li>
		{{endif}}
		{{foreach $content->reactBlurb() AS $key => $count}}
			{{if isset( $reactions[ $key ] )}}
				{{$reaction = $reactions[ $key ];}}
				<li class='ipsReact_reactCount'>
					{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
						<a href='{$content->url('showReactions')->setQueryString( 'reaction', $reaction->id )}' data-ipsDialog data-ipsDialog-size='medium' data-ipsDialog-title='{lang="see_who_reacted"}' data-ipsTooltip="<strong>{lang="reaction_title_{$reaction->id}"}</strong><br>{lang="loading"}" data-ipsTooltip-ajax="{$content->url('showReactions')->setQueryString( array( 'reaction' => $reaction->id, 'tooltip' => 1 ) )}" data-ipsTooltip-safe title="{lang="see_who_reacted_x" sprintf="\IPS\Member::loggedIn()->language()->addToStack( 'reaction_title_' . $reaction->id )" escape="true"}">
					{{else}}
						<span data-ipsTooltip title="{lang="reaction_title_{$reaction->id}" escape="true"}">
					{{endif}}
							<span>
								<img src='{$reaction->_icon->url}' alt="{lang="reaction_title_{$reaction->id}" escape="true"}" loading="lazy">
							</span>
							<span>
								{$count}
							</span>
					{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
						</a>
					{{else}}
						</span>
					{{endif}}
				</li>
			{{endif}}
		{{endforeach}}
	</ul>
{{else}}
	{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
	<span class='i-link-color_inherit'>
		{$content->whoReacted(null, $anonymized)}
		{{if \IPS\Member::loggedIn()->modPermission('can_remove_reactions')}}
			<a href='{$content->url('showReactions')}' data-ipsDialog data-ipsDialog-size='medium' data-ipsDialog-title='{lang="edit_who_reacted"}' data-ipsTooltip title='{lang="edit_who_reacted"}'> <i class="fa-solid fa-pencil" aria-hidden="true"></i></a>
		{{endif}}
	</span>
	{{endif}}
{{endif}}

{{foreach $rows as $row}}
	<li class='ipsPhotoPanel ipsPhotoPanel--mini ipsPhotoPanel--reaction-log'>
		{template="userPhoto" app="core" group="global" params="\IPS\Member::load( $row['member_id'] ), 'mini'"}
		<div class="ipsPhotoPanel__text">
			<h3 class="ipsPhotoPanel__primary">{template="userLink" app="core" group="global" params="\IPS\Member::load( $row['member_id'] )"}</h3>
			<div class="ipsPhotoPanel__secondary">
				<span>
					{{if !isset( \IPS\Request::i()->reaction ) || \IPS\Request::i()->reaction == 'all'}}
						{{$reaction = \IPS\Content\Reaction::load( $row['reaction'] );}}
						<img src='{$reaction->_icon->url}' height='20' width='20' loading="lazy" alt="">
					{{endif}} <span>{$row['rep_date']|raw}</span>
				</span>
				{{if \IPS\Member::loggedIn()->modPermission('can_remove_reactions') and \count( $row['_buttons'] )}}
					<a href="{$row['_buttons']['delete']['link']}" {{if isset( $row['_buttons']['delete']['data'] )}}
						{{foreach $row['_buttons']['delete']['data'] as $k => $v}}
							data-{$k}="{$v}"
						{{endforeach}}
						{{endif}} class="i-margin-start_icon"><i class="fa-solid fa-{$row['_buttons']['delete']['icon']}" aria-hidden="true"></i></a>
				{{endif}}
			</div>
		</div>
	</li>
{{endforeach}}

{{$reactions = $content->reputation;}}
{{$reactionCount = is_array( $reactions ) ? count( $reactions ) : 0;}}
<div class='ipsReactOverview
	{{if \IPS\Settings::i()->reaction_count_display == 'count'}}
		ipsReactOverview--points
		{{if $reactionCount == 0}}ipsReactOverview--none{{endif}}
	{{else}}
		ipsReactOverview--reactions
		{{if ! is_array( $reactions ) or ! \count( $reactions )}}
			ipsReactOverview--none
		{{endif}}
	{{endif}}
	{{if $size}}ipsReactOverview_{$size}{{endif}}'>
	{{if \IPS\Settings::i()->reaction_count_display == 'count'}}
		<div class='i-text-align_center'>
			<span class='ipsReact_reactCountOnly i-text-align_center {{if $reactionCount >= 1}}i-background_positive{{elseif $reactionCount < 0}}i-background_negative{{else}}i-background_2{{endif}} i-link-color_inherit'>
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					<a href='{$content->url('showReactions')}' data-ipsTooltip title="{lang="see_who_reacted" escape="true"}" data-ipsDialog data-ipsDialog-title="{lang="see_who_reacted" escape="true"}">
				{{endif}}
					{$reactionCount}
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					</a>
				{{endif}}
			</span>
		</div>
		<p class='i-text-align_center'>
			{lang="repuation_points"}
		</p>
	{{else}}
		{{if \count( $content->reactBlurb( $content->reputation ?? null ) )}}
			{{$isItem = ( $content instanceof \IPS\Content\Item ) ? 1 : 0;}}
			<ul>
				{{foreach array_reverse( $content->reactBlurb(), TRUE ) AS $key => $count}}
					{{$reaction = \IPS\Content\Reaction::load( $key );}}
					<li>
						{{if\IPS\Member::loggedIn()->group['gbw_view_reps']}}
							<a href='{$content->url('showReactions')->setQueryString( array( 'reaction' => $reaction->id, 'item' => $isItem ) )}' data-ipsDialog data-ipsDialog-title='{lang="see_who_reacted"}' data-ipsTooltip="{lang="see_who_reacted_x" sprintf="\IPS\Member::loggedIn()->language()->addToStack( 'reaction_title_' . $reaction->id )" escape="true"}">
								<span class="ipsInvisible">{lang="see_who_reacted_x" sprintf="\IPS\Member::loggedIn()->language()->addToStack( 'reaction_title_' . $reaction->id )"}</span>
								<img src='{$reaction->_icon->url}' alt="{lang="reaction_title_{$reaction->id}" escape="true"}" loading="lazy" width="120" height="120">
							</a>
						{{else}}
							<span data-ipsTooltip title="{lang="reaction_title_{$reaction->id}"}">
								<img src='{$reaction->_icon->url}' alt="{lang="reaction_title_{$reaction->id}" escape="true"}" loading="lazy" width="120" height="120">
							</span>
						{{endif}}
					</li>
				{{endforeach}}
			</ul>
		{{endif}}
		{{if \is_array( $reactions )}}
		    {{if $showCount && $size == 'small' && \count( $reactions )}}
			    <span>{expression="\count( $reactions )"}</span>
		    {{elseif $showCount}}
			    <p class='i-text-align_center'>
				    {lang="react_total" pluralize="\count( $reactions )"}
			    </p>
			{{endif}}
		{{endif}}
	{{endif}}
</div>

{{if !\IPS\Request::i()->isAjax()}}<div class='ipsBox ipsBox--reactionTabs'>{{endif}}
<i-tabs class='ipsTabs cReactionTabs' id='ipsTabs_{expression="md5( $url )"}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_{expression="md5( $url )"}_content' {{if \IPS\Request::i()->isAjax()}}data-ipsTabBar-updateURL='false'{{endif}}>
	<div role='tablist'>
		{{foreach $tabs as $i => $tab}}
			<a href='{$url->setQueryString( $tabParam, $i )}' id='ipsTabs_{expression="md5( $url )"}_{$i}' class="ipsTabs__tab {{if isset( $tab['count'] ) && $tab['count'] == 0}}ipsTabs__tab--disabled{{endif}}" title='{{if $parseNames}}{striptags="\IPS\Member::loggedIn()->language()->get( $tab['title'] )"}{{else}}{striptags="$tab['title']"}{{endif}}' role="tab" aria-controls='ipsTabs_{expression="md5( $url )"}_{$i}_panel' aria-selected="{{if $i == $activeId}}true{{else}}false{{endif}}">
				{{if isset( $tab['icon'] )}}
					<img src='{$tab["icon"]->url}' width='20' height='20' alt="{lang="reaction_title_{$i}"}" data-ipsTooltip title="{lang="reaction_title_{$i}"}" loading="lazy">
				{{endif}}
				{{if $parseNames}}{lang="$tab['title']"}{{else}}{$tab['title']|raw}{{endif}}
				{{if isset( $tab['count'] )}}
					<span class='i-opacity_8'>({$tab['count']})</span>
				{{endif}}
			</a>
		{{endforeach}}
	</div>
	{template="tabScrollers" app="core" group="global" location="global"}
</i-tabs>
<section id='ipsTabs_{expression="md5( $url )"}_content' class='ipsTabs__panels {{if $contained}}ipsTabs__panels--padded{{endif}}'>
	{{foreach $tabs as $i => $tab}}
		{{if $i == $activeId}}
			<div id='ipsTabs_{expression="md5( $url )"}_{$i}_panel' class="ipsTabs__panel" aria-labelledby="ipsTabs_{expression="md5( $url )"}_{$i}">
				{$defaultContent|raw}
			</div>
		{{endif}}
	{{endforeach}}
</section>
{{if !\IPS\Request::i()->isAjax()}}</div>{{endif}}

{{if \IPS\IPS::classUsesTrait( $content, 'IPS\Content\Reactable' ) and settings.reputation_enabled and $enabledReactions = \IPS\Content\Reaction::enabledReactions()}}
	<div data-controller='core.front.core.reaction' class='ipsReact {{if $extraClass}}{$extraClass}{{endif}}'>
		{{if \IPS\Settings::i()->reaction_count_display == 'count'}}
			{{$reactionCount = $content->reactionCount();}}
			<div class='ipsReact_reactCountOnly {{if $reactionCount >= 1}}i-background_positive{{elseif $reactionCount < 0}}i-background_negative{{else}}i-background_2{{endif}} i-link-color_inherit {{if !\count( $content->reactions() )}}ipsHide{{endif}}' data-role='reactCount'>
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					<a href='{$content->url('showReactions')}' data-ipsTooltip title='{lang="see_who_reacted" escape="true"}' data-ipsDialog data-ipsDialog-title='{lang="see_who_reacted" escape="true"}'>
				{{endif}}
				<span data-role='reactCountText'>{$reactionCount}</span>
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					</a>
				{{endif}}
			</div>
		{{else}}
			{{$reactBlurb = $content->reactBlurb();}}
			<div class='ipsReact_blurb {{if !$reactBlurb}}ipsHide{{endif}}' data-role='reactionBlurb'>
				{{if $reactBlurb}}
					{template="reactionBlurb" group="global" app="core" params="$content"}
				{{endif}}
			</div>
		{{endif}}

		{{if $content->canReact()}}
			{{$defaultReaction = reset( $enabledReactions );}}
			{{$reactButton = ( $reacted = $content->reacted() and isset( $enabledReactions[ $reacted->id ] ) ) ? $enabledReactions[ $reacted->id ] : $defaultReaction;}}

			<div class='ipsReact_types' data-role='reactionInteraction' data-unreact="{$content->url( 'unreact' )->csrf()}">
				{{if !\IPS\Content\Reaction::isLikeMode()}}
					<ul data-role='reactTypes' hidden>
						{{foreach array_reverse( $enabledReactions ) as $reaction}}
							{{if $reaction->id == $reactButton->id}}
								{{continue;}}
							{{endif}}

							<li>
								<a href='{$content->url( 'react' )->setQueryString( 'reaction', $reaction->id )->csrf()}' class='ipsReact_reaction' data-role="reaction" {{if $reaction->id == $defaultReaction->id}}data-defaultReaction{{endif}}>
									<img src='{{if $reaction->use_custom}}{$reaction->_icon}{{else}}{$reaction->_icon->url}{{endif}}' alt="{lang="reaction_title_{$reaction->id}" escape="true"}" data-ipsTooltip title="{lang="reaction_title_{$reaction->id}" escape="true"}" loading="lazy" width="120" height="120">
									<span class='ipsReact_name'>{lang="reaction_title_{$reaction->id}"}</span>
								</a>
							</li>
						{{endforeach}}
					</ul>
				{{endif}}

				<span class='ipsReact_button {{if $reacted !== FALSE}}ipsReact_reacted{{endif}}' data-action='reactLaunch'>
					<a href='{$content->url( 'react' )->setQueryString( 'reaction', $reactButton->id )->csrf()}' class='ipsReact_reaction' data-role="reaction" {{if $reactButton->id == $defaultReaction->id}}data-defaultReaction{{endif}}>
						<img src='{{if $reactButton->use_custom}}{$reactButton->_icon}{{else}}{$reactButton->_icon->url}{{endif}}' alt="{lang="reaction_title_{$reactButton->id}" escape="true"}" data-ipsTooltip title="{lang="reaction_title_{$reactButton->id}" escape="true"}" loading="lazy" width="120" height="120">
						<span class='ipsReact_name'>{lang="reaction_title_{$reactButton->id}"}</span>
					</a>
				</span>

				<a href='{$content->url( 'unreact' )->csrf()}' class='ipsReact_unreact {{if $reacted == FALSE}}ipsHide{{endif}}' data-action='unreact' data-ipsTooltip title='{lang="reaction_remove"}'><span aria-hidden="true">&times;</span><span class="ipsInvisible">{lang="reaction_remove"}</span></a>
			</div>
		{{endif}}
	</div>
{{endif}}

{{if settings.reputation_enabled and settings.reputation_show_profile and $author->member_id}}
	{{if member.group['gbw_view_reps']}}
		<a href='{url="app=core&module=members&controller=profile&id={$author->member_id}&do=reputation" seoTemplate="profile_reputation" seoTitle="$author->members_seo_name"}' title="{lang="reputation_badge_tooltip"}" data-ipsTooltip class='ipsRepBadge {{if $author->pp_reputation_points > 0}}ipsRepBadge--positive{{elseif $author->pp_reputation_points < 0}}ipsRepBadge--negative{{else}}ipsRepBadge_neutral{{endif}}'>
	{{else}}
		<span title="{lang="reputation_badge_tooltip"}" data-ipsTooltip class='ipsRepBadge {{if $author->pp_reputation_points > 0}}ipsRepBadge--positive{{elseif $author->pp_reputation_points < 0}}ipsRepBadge--negative{{else}}ipsRepBadge_neutral{{endif}}'>
	{{endif}}
			<i class='fa-solid {{if $author->pp_reputation_points > 0}}fa-plus-circle{{elseif $author->pp_reputation_points < 0}}fa-minus-circle{{else}}fa-circle{{endif}}' aria-hidden="true"></i> {number="abs( $author->pp_reputation_points )"}
	{{if member.group['gbw_view_reps']}}
		</a>
	{{else}}
		</span>
	{{endif}}
{{endif}}

{{$allowRep = TRUE;}}
<div data-controller='core.front.core.reaction' class='ipsReact ipsReact_mini {{if !$allowRep}}ipsReact_miniNoInteraction{{endif}}'>

	{{if $content}}
		{{if \IPS\Settings::i()->reaction_count_display == 'count'}}
			<div class='ipsReact_reactCountOnly ipsReact_reactCountOnly_mini {{if $content->reactionCount() >= 1}}i-background_positive{{elseif $content->reactionCount() < 0}}i-background_negative{{else}}i-background_2{{endif}} i-link-color_inherit {{if !\count( $content->reactions() )}}ipsHide{{endif}}' data-role='reactCount'>
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					<a href='{$content->url('showReactions')}' data-ipsTooltip title='{lang="see_who_reacted" escape="true"}' data-ipsDialog data-ipsDialog-title='{lang="see_who_reacted" escape="true"}'>
				{{endif}}
				<span data-role='reactCountText'>{$content->reactionCount()}</span>
				{{if \IPS\Member::loggedIn()->group['gbw_view_reps']}}
					</a>
				{{endif}}
			</div>
		{{else}}
			<div class='ipsReact_blurb {{if !$content->reactBlurb()}}ipsHide{{endif}}' data-role='reactionBlurb'>
				{{if $content->reactBlurb()}}
					{template="reactionBlurb" group="global" app="core" params="$content"}
				{{endif}}
			</div>
		{{endif}}

		{{if $content->canReact()}}
			{{$reactButton = NULL;}}
			{{$defaultReaction = NULL;}}

			{{foreach \IPS\Content\Reaction::roots() AS $id => $reaction}}
				{{if !$defaultReaction}}
					{{$defaultReaction = $reaction;}}
				{{endif}}
				{{if ( $content->reacted() !== FALSE && $reaction->id == $content->reacted()->id ) || ( $content->reacted() === FALSE )}}
					{{$reactButton = $reaction;}}
					{{break;}}
				{{endif}}
			{{endforeach}}
			{{if $allowRep}}
				<span class='ipsReact_count ipsHide' data-role="reactCount">
					<a href='{$content->url('showReactions')}' data-ipsDialog data-ipsDialog-title='{lang="see_who_reacted"}'>
						{expression="\count( $content->reactions() )"}
					</a>
				</span>
				<div class='ipsReact_types' data-role='reactionInteraction' data-unreact="{$content->url( 'unreact' )->csrf()}">
					{{if !\IPS\Content\Reaction::isLikeMode()}}
						<ul data-role='reactTypes'>
							{{foreach \IPS\Content\Reaction::roots() AS $id => $reaction}}
							{{if $reaction->id == $reactButton->id OR $reaction->_enabled === FALSE}}
							{{continue;}}
							{{endif}}

								<li>
									<a href='{$content->url( 'react' )->setQueryString( 'reaction', $reaction->id )->csrf()}' class='ipsReact_reaction' data-role="reaction" {{if $reaction->id == $defaultReaction->id}}data-defaultReaction{{endif}}>
										<img src='{$reaction->_icon->url}' alt="{lang="reaction_title_{$reaction->id}" escape="true"}" data-ipsTooltip title="{lang="reaction_title_{$reaction->id}" escape="true"}">
										<span class='ipsReact_name'>{lang="reaction_title_{$reaction->id}"}</span>
									</a>
								</li>
							{{endforeach}}
							<li>
								<a href='{$content->url( 'unreact' )->csrf()}' class='ipsReact_unreact {{if $content->reacted() == FALSE}}ipsHide{{endif}}' data-action='unreact' data-ipsTooltip title='{lang="reaction_remove"}'>&times;</a>
							</li>
						</ul>
					{{endif}}

					<span class='ipsReact_button {{if $content->reacted() !== FALSE}}ipsReact_reacted{{endif}}' data-action='reactLaunch'>
						<a href='{$content->url( 'react' )->setQueryString( 'reaction', $reactButton->id )->csrf()}' class='ipsReact_reaction' data-role="reaction" {{if $reactButton->id == $defaultReaction->id}}data-defaultReaction{{endif}}>
							<img src='{$reactButton->_icon->url}' alt="{lang="reaction_title_{$reactButton->id}" escape="true"}" data-ipsTooltip title="{lang="reaction_title_{$reactButton->id}" escape="true"}">
							<span class='ipsReact_name'>{lang="reaction_title_{$reactButton->id}"}</span>
						</a>
					</span>
				</div>
			{{endif}}
		{{endif}}
	{{endif}}
</div>

{{$id = 'i-tooltip-' . mt_rand();}}
{{if \IPS\Content\Reaction::isLikeMode()}}
<a href='{$contentURL}' data-ipsDialog data-ipsDialog-destructOnClose data-ipsDialog-size='medium' data-ipsDialog-title='{lang="like_log_title"}' data-ipsTooltip data-ipstooltip-source="{$id}">{$lang} <span id="{$id}" hidden>{$names|raw}</span></a>
