{{if $link===NULL}}
    <strong>{$title}</strong>
{{else}}
    <a data-ips-hook="url" data-ipstooltip  {{if  $hovertitle !== NULL}} _title='{{if !$parsed}}{lang="$hovertitle"}{{else}}{$hovertitle}{{endif}}' {{endif}} href='{$link}'>
        <span class='ipsType i-font-weight_bold'>{$title}</span> <i class="fa-solid fa-arrow-up-right-from-square ipsType i-color_soft i-font-size_-2" aria-hidden="true"></i>
    </a>
{{endif}}

{{if \IPS\Member::loggedIn()->isAdmin()}}
	{{$notifications = \IPS\core\AdminNotification::notifications( NULL, array( \IPS\core\AdminNotification::SEVERITY_CRITICAL ) ); }}
	{{if \count($notifications)}}
		<div data-controller="core.global.core.notificationList" class="cNotificationList i-grid i-gap_1">
			{{foreach $notifications as $notification}}
				{{$style = $notification->style();}}
				<div class="ipsMessage ipsMessage--acp ipsMessage--{$style} ipsPull">
					<i class='fa-solid fa-{{if $style == $notification::STYLE_INFORMATION OR $style == $notification::STYLE_EXPIRE}}circle-info{{else}}download{{endif}} ipsMessage__icon' aria-hidden="true"></i>
					<div class="i-flex i-justify-content_space-between i-gap_2">
						<div class="i-flex_11">
							<p class="ipsMessage__title">{$notification->title()|raw}</p>
							<span class='i-font-size_-2 i-font-weight_normal i-opacity_8'>{lang="acp_notification_frontend_explain"}</span>
						</div>
						{{$dismissible = $notification->dismissible();}}
						{{if $dismissible !== $notification::DISMISSIBLE_NO}}
							<a href="{url="app=core&module=system&controller=ajax&do=dismissAcpNotification&id={$notification->id}" csrf="true"}" class="ipsMessage__close i-flex_00" title="{lang="acp_notification_dismiss_{$dismissible}"}" data-ipsTooltip data-action="dismiss">
								<i class="fa-solid fa-times" aria-hidden="true"></i>
								<span class="ipsInvisible">{lang="closed"}</span>
							</a>
						{{endif}}
					</div>
					{$notification->body()|raw}
				</div>
			{{endforeach}}
		</div>
	{{endif}}
{{endif}}

{{if $icon}}
	<img src="{$icon->url}" alt='' loading='lazy' class="ipsData__customIcon">
{{endif}}

{{if $member->member_id}}
	<a href="{$member->url()}" class="ipsUserPhoto ipsUserPhoto--{$size}" target="_blank" rel="noopener">
		<img src='{$member->photo}' alt='' loading="lazy" referrerpolicy='origin-when-cross-origin'>
	</a>
{{else}}
	<span class="ipsUserPhoto ipsUserPhoto--{$size}">
		<img src='{$member->photo}' alt='' loading="lazy" referrerpolicy='origin-when-cross-origin'>
	</span>
{{endif}}

{{if $member->member_id and \IPS\Member::loggedIn()->canAccessModule( \IPS\Application\Module::get( 'core', 'members' ) )}}
{{$memberURL = ( $warningRef ) ? $member->url()->setQueryString( 'wr', $warningRef ) : $member->url();}}
	<a data-ips-hook="userPhotoWithUrl" href="{$memberURL}" rel="nofollow" {{if $hovercard}}data-ipsHover data-ipsHover-width="370" data-ipsHover-target="{$memberURL->setQueryString( 'do', 'hovercard' )}"{{endif}} class="ipsUserPhoto ipsUserPhoto--{$size}{{if $classes}} {$classes}{{endif}}" title="{lang="view_user_profile" sprintf="$member->name"}" data-group="{$member->member_group_id}" aria-hidden="true" tabindex="-1">
		<img src='{$member->photo}' alt='{$member->name}' loading="lazy">
	</a>
{{else}}
	<span data-ips-hook="userPhotoWithoutUrl" class='ipsUserPhoto ipsUserPhoto--{$size} {{if $classes}}{$classes}{{endif}}' data-group="{$member->member_group_id}">
		<img src='{$member->photo}' alt='{$member->name}' loading="lazy">
	</span>
{{endif}}

{{if $id and \IPS\Member::loggedIn()->canAccessModule( \IPS\Application\Module::get( 'core', 'members' ) )}}
	<a data-ips-hook="userPhotoWithUrl" href="{url="app=core&module=members&controller=profile&id={$id}" seoTemplate="profile" seoTitle="$seoName ?: \IPS\Http\Url::seoTitle( $name )"}" rel="nofollow" {{if $hovercard}}data-ipsHover data-ipsHover-target="{url="app=core&module=members&controller=profile&id={$id}&do=hovercard" seoTemplate="profile" seoTitle="$seoName ?: \IPS\Http\Url::seoTitle( $name )"}"{{endif}} class="ipsUserPhoto ipsUserPhoto--{$size}{{if $classes}} {$classes}{{endif}}" title="{lang="view_user_profile" sprintf="$name"}" aria-hidden="true" tabindex="-1">
		<img src='{$photoUrl}' alt='{$name}' loading="lazy">
	</a>
{{else}}
	<span data-ips-hook="userPhotoWithoutUrl" class='ipsUserPhoto ipsUserPhoto--{$size} {{if $classes}}{$classes}{{endif}}'>
		<img src='{$photoUrl}' alt='{$name}' loading="lazy">
	</span>
{{endif}}

{{if !$area->isEmpty() OR \IPS\Dispatcher::i()->application?->canManageWidgets()}}
{{$dataAttributes = $area->dataAttributes();}}
<section
	class="cWidgetContainer{{foreach $area->classes() as $class}} {$class}{{endforeach}}"
	{{if \IPS\Dispatcher::i()->application->canManageWidgets()}}data-controller='core.front.widgets.area'{{endif}}
	data-role='widgetReceiver'
	data-orientation='{$area->orientation()}'
	data-widgetArea='{$area->id}'
	style="{{foreach $area->styles() as $k => $v}}{$k}:{$v};{{endforeach}}"
	{{foreach $dataAttributes as $k => $v}}
	    data-{$k}="{$v}"
    {{endforeach}}
    {{if !\IPS\Request::i()->_blockManager and (!$area->totalVisibleWidgets() || $area->isEmpty())}} hidden{{endif}}
>
    {{$isCarousel = $area->wrapBehavior === "carousel";}}
    {{if $isCarousel}}
        <div class="cWidgetContainer__carousel-wrap">
    {{endif}}
    {{foreach $area->children as $child}}
        {$child|raw}
    {{endforeach}}

    {{foreach $area->widgets as $_widget}}
        {{if $widget = \IPS\Widget::createWidgetFromStoredData( $_widget )}}
        <div class="ipsWidget__content--wrap">
            <div
                class='{{if \get_class( $widget ) !== 'IPS\cms\widgets\Database'}}ipsWidget{{endif}}{{foreach $area->widgetClasses( $widget ) as $class}} {$class}{{endforeach}}' {{foreach $widget->dataAttributes() as $k => $v}} data-{$k}="{$v}"{{endforeach}}
                data-controller='core.front.widgets.block'
            >
                {$widget->renderCSS()|raw}
                {$area->getWidgetContent()|raw}
            </div>
        </div>
        {{endif}}
    {{endforeach}}

    {{if $isCarousel}}
        </div>
        {{$totalWidgets = $area->totalVisibleWidgets() ?: 1;}}
        <div class="cWidgetContainer__carousel-buttons" data-controller="core.front.widgets.carouselControls" {{if $totalWidgets <= 1}}hidden{{endif}}>
            <div class="cWidgetContainer__carousel-indicator"></div>
            <button data-carousel-arrow="prev">
                <i class="fa-solid fa-chevron-left" aria-hidden="true"></i>
            </button>
            <button data-carousel-arrow="next">
                <i class="fa-solid fa-chevron-right" aria-hidden="true"></i>
            </button>
        </div>
    {{endif}}
</section>
{{endif}}

{{if $id == 'header'}}
	{template="announcementContentTop" app="core" group="global" params=""}
{{endif}}

{{if isset( \IPS\Output::i()->sidebar['widgetareas'][$id] )}}
    {{$area = \IPS\Output::i()->sidebar['widgetareas'][$id];}}
    {template="widgetArea" group="global" app="core" params="$area"}
{{else}}
    {{$widgets = \IPS\Output::i()->sidebar['widgets'] ?? [];}}
    {{if ( ( isset( $widgets[ $id ] ) ) || \IPS\Dispatcher::i()->application?->canManageWidgets() )}}
        {{if isset( $widgets[ $id ] ) AND \is_string( $widgets[ $id ] )}}
        {$widgets[ $id ]|raw}
        {{else}}
        <section class='cWidgetContainer cWidgetContainer--main' {{if ! isset( $widgets[ $id ] )}}hidden{{endif}} {{if \IPS\Dispatcher::i()->application->canManageWidgets()}}data-controller='core.front.widgets.area'{{endif}} data-role='widgetReceiver' data-orientation='{$orientation}' data-widgetArea='{$id}'>
            <ul>
                {{if isset( $widgets[ $id ] )}}
                    {{foreach $widgets[ $id ] as $widget}}
                    <li
                        class='{{if \get_class( $widget ) != 'IPS\cms\widgets\Database'}}ipsWidget ipsWidget--{$orientation}{{endif}}{{foreach $widget->getWrapperClasses() as $class}} {$class}{{endforeach}}' {{foreach $widget->dataAttributes() as $k => $v}} data-{$k}="{$v}"{{endforeach}}
                        data-controller='core.front.widgets.block'
                    >
                        {$widget|raw}
                    </li>
                    {{endforeach}}
                {{endif}}
            </ul>
        </section>
        {{endif}}
    {{endif}}
{{endif}}

{{if settings.mfa_required_groups != '*' and !\IPS\Member::loggedIn()->inGroup( explode( ',', settings.mfa_required_groups ) )}}
{{$url = \IPS\Request::i()->url()->stripQueryString();}}
<div class="i-background_2 i-text-align_center i-padding_2 cOtherMethod">
	<a href='{$url->setQueryString( '_mfa', 'optout' )->csrf()}' class='ipsButton ipsButton--text ipsButton--wide' data-confirm {{if member.language()->checkKeyExists('security_questions_opt_out_warning_value')}}data-confirmSubMessage="{lang="security_questions_opt_out_warning_value"}"{{endif}}>{lang="mfa_opt_out"}</a>
</div>
{{endif}}

{$value|raw}
{{if !empty($log['mlog_smtp_log']) }}
<a data-ipsDialog data-ipsDialog-content="#errorLog-{$log['mlog_id']}" data-ipsDialog-title="{lang="emailerrorlog_logtitle"}" href='#errorLog-{$log['mlog_id']}'>{lang="view_full_smtp_log"}</a>
<div class='ipsHide i-background_3 i-padding_3' id='errorLog-{$log['mlog_id']}'><pre>{$log['mlog_smtp_log']}</pre></div>
{{endif}}

{{if $noHtml}}
{{foreach $counts as $class => $count}}{lang="{$class::$title}_pl"}: {number="$count"}
{{endforeach}}
{{else}}
	<strong>
		{{if $app == 'core'}}
			{lang="module__core_status"}
		{{else}}
			{lang="__app_{$app}"}
		{{endif}}
	</strong>
	<table>
		{{foreach $counts as $class => $count}}
			<tr>
				<td>{lang="{$class::$title}_pl"}</td>
				<td class="i-text-align_end" style="padding-inline-start:1em">{number="$count"}</td>
			</tr>
		{{endforeach}}
	</table>
{{endif}}

{{$currentTimestamp = null;}}
{{foreach $rows as $row}}
	{{if $currentTimestamp != $row['log_date']->format('n') . '|' . $row['log_date']->format('Y')}}
		<li class='cMemberHistory_date'>
			{$row['log_date']->strFormat('%B')} {$row['log_date']->strFormat('%Y')}
		</li>
		{{$currentTimestamp = $row['log_date']->format('n') . '|' . $row['log_date']->format('Y');}}
	{{endif}}
	<li class=''>
		<div class='cMemberHistory_info'>
			<div class="i-color_hard i-font-weight_500 i-link-text-decoration_underline">{$row['log_data']|raw}</div>
			<span class='i-color_soft i-link-color_inherit i-flex i-justify-content_space-between'>
				<span>{$row['log_date']->html()|raw}</span>
				{{if $row['log_ip_address'] and member.hasAcpRestriction( 'core', 'members', 'membertools_ip' )}}
					<span>{$row['log_ip_address']|raw}</span>
				{{endif}}
			</span>
		</div>
	</li>
{{endforeach}}

{{if \count( $rows )}}
	<ol class='cMemberHistory {{foreach $table->classes as $class}}{$class} {{endforeach}}' id='elTable_{$table->uniqueId}' data-role="tableRows">
		{template="$table->rowsTemplate[1]" params="$table, $headers, $rows" object="$table->rowsTemplate[0]"}
	</ol>
{{else}}
	<p class='ipsEmptyMessage'>{lang="customer_no_history"}</p>
{{endif}}
{{if $table->pages > 1}}
	<div class="ipsViewAll">
		<a href="{$table->baseUrl}">{lang="see_all_history"}</a>
	</div>
{{endif}}

{{if \count( $loginMethods ) }}
	<hr class='ipsHr'>
	<h3 class='ipsMinorTitle i-flex i-justify-content_space-between'>{lang="active_account_integrations"}
	{{if \IPS\CIC AND \IPS\Cicloud\isManaged() AND member.hasAcpRestriction( 'core', 'members', 'member_edit' ) and ( member.hasAcpRestriction( 'core', 'members', 'member_edit_admin' ) or !$member->isAdmin() )}}
	<a href="{url="app=core&module=members&controller=members&do=loginAdd&id={$member->member_id}"}" data-ipsDialog data-ipsDialog-title="{lang="add_login_link"}" data-ipsTooltip title="{lang="add_login_link"}" class="i-text-transform_none">{lang="add_button"}</a>
	{{endif}}
	</h3>

	<i-data>
		<ul class='ipsData ipsData--table ipsData--login-methods acpMemberView_integrations'>
			{{foreach $loginMethods as $id => $details}}
				<li class='ipsData__item'>
					{{if $details['link']}}
						<a href="{$details['link']}" target="_blank" rel="noopener" class="ipsData__image" aria-hidden="true" tabindex="-1">
							{{if isset( $details['icon'] )}}
								<img src="{$details['icon']}" class="ipsUserPhoto ipsUserPhoto--tiny" alt="" loading="lazy">
							{{else}}
								<img src='{resource="default_photo.png" app="core" location="global"}' class="ipsUserPhoto ipsUserPhoto--tiny" alt="" loading="lazy">
							{{endif}}
						</a>
					{{else}}
						<div class="ipsData__image" aria-hidden="true">
							{{if isset( $details['icon'] )}}
								<img src="{$details['icon']}" class="ipsUserPhoto ipsUserPhoto--tiny" alt="" loading="lazy">
							{{else}}
								<img src='{resource="default_photo.png" app="core" location="global"}' class="ipsUserPhoto ipsUserPhoto--tiny" alt="" loading="lazy">
							{{endif}}
						</div>
					{{endif}}
					<div class='ipsData__main'>
						{{if isset( $details['edit'] ) and ( $details['edit'] or $details['delete'] ) and member.hasAcpRestriction( 'core', 'members', 'member_edit' ) and ( member.hasAcpRestriction( 'core', 'members', 'member_edit_admin' ) or !$member->isAdmin() )}}
							<ul class="ipsControlStrip">
								{{if $details['edit']}}
									<li class="ipsControlStrip_button">
										<a href="{url="app=core&module=members&controller=members&do=loginEdit&id={$member->member_id}&method={$id}"}" data-ipsDialog data-ipsDialog-title="{$details['title']}" data-ipsTooltip title="{lang="profilesync_configure"}"><i class="ipsControlStrip_icon fa-solid fa-pencil" aria-hidden="true"></i></a>
									</li>
								{{endif}}
								{{if $details['delete']}}
									<li class="ipsControlStrip_button">
										<a href="{url="app=core&module=members&controller=members&do=loginDelete&id={$member->member_id}&method={$id}" csrf="true"}" data-confirm data-ipsTooltip title="{lang="sign_out"}"><i class="ipsControlStrip_icon fa-solid fa-xmark-circle" aria-hidden="true"></i></a>
									</li>
								{{endif}}
							</ul>
						{{endif}}
						<p class='acpMemberView_integrations_text'>
							{{if $details['link']}}
								<a href="{$details['link']}" target="_blank" rel="noopener" class="i-link-color_inherit">
							{{endif}}
							{$details['title']}<br>
							<span class='i-font-size_1 i-color_soft'>{$details['blurb']}</span>
							{{if $details['link']}}
								</a>
							{{endif}}
							{{if isset($details['forceSyncErrors'])}}
							{{foreach $details['forceSyncErrors'] as $type => $error}}
								<p class="i-font-size_-1 i-color_warning">{lang="profilesync_{$type}_admin_error" sprintf="$error"}</p>
							{{endforeach}}
							{{endif}}
						</p>
					</div>
				</li>
			{{endforeach}}
		</ul>
	</i-data>
{{endif}}

{{if $member->canAccessModule( \IPS\Application\Module::get( 'core', 'messaging', 'front' ) ) or $attachmentStorage !== NULL}}
	{{if \IPS\Member::loggedIn()->canAccessModule( \IPS\Application\Module::get( 'core', 'messaging', 'front' ) )}}
	<div class='ipsAcpProfile__half acpMemberView_quota ipsBox' data-ips-template="quotas">
		<h2 class='ipsBox__header'>
			<i class="fa-solid fa-envelope ipsBox__header-icon" aria-hidden="true"></i>
			{lang="messenger_quota_header"}
			{{if $member->canAccessModule( \IPS\Application\Module::get( 'core', 'messaging', 'front' ) ) and member.hasAcpRestriction( 'core', 'members', 'member_edit' ) and ( !$member->isAdmin() or member.hasAcpRestriction( 'core', 'members', 'member_edit_admin' ) )}}
				{{if $messengerCount === NULL}}
					<a href="{url="app=core&module=members&controller=members&do=editBlock&block=IPS\\core\\extensions\\core\\MemberACPProfileBlocks\\Quotas&id={$member->member_id}&enable=1" csrf="true"}" class="ipsBox__header-secondary" data-confirm>
						{lang="admin_enable_messenger"}
					</a>
				{{else}}
					<a href="{url="app=core&module=members&controller=members&do=editBlock&block=IPS\\core\\extensions\\core\\MemberACPProfileBlocks\\Quotas&id={$member->member_id}" csrf="true"}" class="ipsBox__header-secondary" data-confirm data-confirmType="verify" data-confirmIcon="question" data-confirmMessage="{lang="admin_disable_messenger"}" data-confirmSubMessage="{lang="admin_disable_messenger_confirm"}" data-confirmButtons='{expression="json_encode( array( 'yes' => \IPS\Member::loggedIn()->language()->addToStack('no'), 'no' => \IPS\Member::loggedIn()->language()->addToStack('yes'), 'cancel' => \IPS\Member::loggedIn()->language()->addToStack('cancel') ) )" raw="true"}'>
						{lang="admin_disable_messenger"}
					</a>
				{{endif}}
			{{endif}}
		</h2>
		<div class='i-padding_3'>
			{{if $messengerCount !== NULL}}
				{{if $messengerPercent !== NULL}}
					<meter class='ipsMeter i-margin-bottom_1' max='100' high='90' value='{{if $messengerPercent > 100}}100{{else}}{$messengerPercent}{{endif}}'></meter>
				{{endif}}

				<div class="i-flex i-margin-top_1">
					<div class="i-flex_11">
						<span class='acpMemberView_quotaNumber i-font-size_2'>{number="$messengerCount"}</span><br>
						{{if $member->group['g_max_messages'] > 0}}
							<span class='i-font-size_1 i-color_soft'>{lang="quota_allowance" sprintf="\IPS\Member::loggedIn()->language()->formatNumber( $member->group['g_max_messages'] )"}</span>
						{{else}}
							<span class='i-font-size_1 i-color_soft'>{lang="quota_allowance_unlimited"}</span>
						{{endif}}
					</div>
					{{if $messengerPercent !== NULL}}
						<span class='acpMemberView_percentage i-opacity_4 i-color_soft'>{number="$messengerPercent"}%</span>
					{{endif}}
				</div>

			{{else}}
				<div class="i-font-size_1 i-color_soft">
					{{if $member->members_disable_pm == 1}}
						{lang="messenger_quota_disabled_self"}
					{{elseif $member->members_disable_pm == 2}}
						{lang="messenger_quota_disabled_admin"}
					{{else}}
						{lang="messenger_quota_disabled_group"}
					{{endif}}
				</div>
			{{endif}}
		</div>
	</div>
	{{endif}}
	<div class='ipsAcpProfile__half acpMemberView_quota ipsBox' data-ips-template="quotas">
		<h2 class='ipsBox__header'>
			<i class="fa-solid fa-paperclip ipsBox__header-icon" aria-hidden="true"></i>
			{lang="my_attachment_quota"}
			{{if $viewAttachmentsLink}}
				<a href="{$viewAttachmentsLink}" class="ipsBox__header-secondary">{lang="view_attachments"}</a>
			{{endif}}
		</h2>
		<div class='i-padding_3'>
			{{if $attachmentStorage !== NULL}}
				{{if $attachmentPercent !== NULL}}
					<meter class='ipsMeter i-margin-bottom_1' max='100' high='90' value='{{if $attachmentPercent > 100}}100{{else}}{$attachmentPercent}{{endif}}'></meter>
				{{endif}}
				<div class="i-flex i-margin-top_1">
					<div class="i-flex_11">
						<span class='acpMemberView_quotaNumber i-font-size_2'>{filesize="$attachmentStorage"}</span><br>
						{{if $member->group['g_attach_max'] > 0}}
							<span class='i-font-size_1 i-color_soft'>{lang="quota_allowance" sprintf="\IPS\Output\Plugin\Filesize::humanReadableFilesize( $member->group['g_attach_max'] * 1024 )"}</span>
						{{else}}
							<span class='i-font-size_1 i-color_soft'>{lang="quota_allowance_unlimited"}</span>
						{{endif}}
					</div>
					{{if $attachmentPercent !== NULL}}
						<span class='acpMemberView_percentage i-opacity_4 i-color_soft'>{number="$attachmentPercent"}%</span>
					{{endif}}
				</div>
			{{else}}
				<div class="i-font-size_1 i-color_soft">{lang="quota_allowance_disabled"}</div>
			{{endif}}
		</div>
	</div>
{{endif}}

{{if settings.achievements_enabled}}
    <div class='ipsAcpProfile__half acpMemberView_quota ipsBox' data-ips-template="rank">
        <h2 class='ipsBox__header'>
            <i class="fa-solid fa-chart-line ipsBox__header-icon" aria-hidden="true"></i>
            {lang="acp_profile_ranks_title"}
            {{if member.hasAcpRestriction( 'core', 'members', 'member_edit' )}}
                <a href="{url="app=core&module=members&controller=members&do=editBlock&block=IPS\\core\\extensions\\core\\MemberACPProfileBlocks\\Points&id={$member->member_id}"}" class="ipsBox__header-secondary">{lang="acp_profile_points_manage"}</a>
            {{endif}}
        </h2>
        {{if $member->rank()}}
        <div class='i-padding_3'>
            <div class="i-flex i-align-items_center i-margin-bottom_1">
                <span class='acpMemberView_quotaNumber i-flex_11 i-font-size_1'>{$member->rank()->_title}</span><br>
                <span class='i-font-size_1 i-color_soft'>{lang="acp_profile_points" sprintf="$member->achievements_points"}</span>
            </div>
            {{if $nextRank = $member->nextRank()}}
                <meter class='ipsMeter i-margin-bottom_1' max='100' high='90' value='{expression="$member->achievements_points / $nextRank->points * 100"}'></meter>
                <span class='i-font-size_1 i-color_soft'>{lang="acp_rank_points_for_next"} {expression="$nextRank->points - $member->achievements_points"}</span>
            {{endif}}
        </div>
        {{endif}}
    </div>
    <div class='ipsAcpProfile__half acpMemberView_quota ipsBox'>
        <h2 class='ipsBox__header'>
            <i class="fa-solid fa-certificate ipsBox__header-icon" aria-hidden="true"></i>
            {lang="acp_profile_badges_title"}
            {{if member.hasAcpRestriction( 'core', 'members', 'member_edit' )}}
                <a href="{$member->acpUrl()->setQueryString('do', 'badges')}" class="ipsBox__header-secondary">{lang="acp_profile_manage_badges"}</a>
            {{endif}}
        </h2>
        <div class='i-padding_3 i-flex i-flex-wrap_wrap i-gap_2'>
            {{foreach $member->recentBadges(20) as $badge}}
                <span class="i-flex_00 i-basis_40">{$badge->html('ipsDimension:5')|raw}</span>
            {{endforeach}}
        </div>
    </div>
{{endif}}

{{if \count( $locations )}}
	<ul>
		{{foreach $locations as $location}}
			<li>
				{{if $location instanceof \IPS\Content or $location instanceof \IPS\Node\Model}}
					<a href="{{if \IPS\Dispatcher::i()->controllerLocation == 'admin'}}{{if method_exists( $location, 'acpUrl' )}}{$location->acpUrl()}{{else}}{$location->url()}{{endif}}{{else}}{$location->url()}{{endif}}" target="_blank" rel="noreferrer" class="i-color_inherit">
						{{if isset( $location::$icon )}}<i class="fa-solid fa-{$location::$icon}" {{if isset( $location::$title )}}title="{lang="$location::$title"}" data-ipsTooltip{{endif}} aria-hidden="true"></i> {{endif}}
						{{if $location instanceof \IPS\Content\Item}}
							{$location->mapped('title')}
						{{elseif $location instanceof \IPS\Node\Model}}
							{$location->_title}
						{{else}}
							{$location->item()->mapped('title')}
						{{endif}}
					</a>
				{{elseif $location instanceof \IPS\Http\Url}}
