					<img src='{$member->photo}' alt='' loading="lazy">
				</a>
				<div class='ipsPhotoPanel__text'>
					<div class='ipsTitle ipsTitle--h4'>
						<a href='{$member->url()}'>{$member->name}</a>
						{{if \IPS\Member::loggedIn()->member_id AND \IPS\Member::loggedIn()->member_id === $member->member_id AND $member->isOnlineAnonymously()}}
							<span class='cProfileHeader_history' title='{lang="member_is_currently_anon"}' data-ipsTooltip>
								<i class='fa-solid fa-eye-slash' aria-hidden="true"></i>
							</span>
						{{endif}}
					</div>
					<div class='ipsPhotoPanel__secondary i-font-weight_600'>
						{expression="\IPS\Member\Group::load( $member->member_group_id )->formattedName" raw="true"}
					</div>
				</div>
			</div>
			{{if ( \IPS\Member::loggedIn()->modPermission('can_flag_as_spammer') AND $member->member_id != \IPS\Member::loggedIn()->member_id ) || member.canWarn( $member ) || \IPS\Member::loggedIn()->modPermission('can_manage_alerts')}}
				<button type="button" id="elUserHovercard_{$member->member_id}{$rnd}_more" popovertarget="elUserHovercard_{$member->member_id}{$rnd}_more_menu" title='{lang="moderator_tools"}...' data-ipsTooltip class='i-flex_00 ipsButton ipsButton--inherit'><i class="fa-solid fa-ellipsis" aria-hidden="true"></i><span class="ipsInvisible">{lang="moderator_tools"}...</span></button>
				<i-dropdown popover id="elUserHovercard_{$member->member_id}{$rnd}_more_menu">
					<div class="iDropdown">
						<ul class="iDropdown__items">
							{{if member.modPermission('can_flag_as_spammer') and $member->member_id != member.member_id and $member->canBeFlaggedAsSpammer()}}
								{{if $member->members_bitoptions['bw_is_spammer']}}
									<li><a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=0&referrer={$referrer}" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' data-confirm data-confirmSubMessage="{lang="spam_unflag_confirm"}"><i class="fa-solid fa-flag" aria-hidden="true"></i> {lang="spam_unflag"}</a></li>
								{{else}}
									<li><a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=1&referrer={$referrer}" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' data-confirm><i class="fa-solid fa-flag" aria-hidden="true"></i> {lang="spam_flag"}</a></li>
								{{endif}}
							{{endif}}
							{{if member.canWarn( $member )}}
								<li><a href="{$addWarningUrl}" title='{lang="warn_user_title"}' data-ipsDialog data-ipsDialog-title='{lang="warn_user"}' data-ipsDialog-destructOnClose><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> {lang="warn_user"}</a></li>
							{{endif}}
							{{if \IPS\Member::loggedIn()->modPermission('can_manage_alerts')}}
								<li><a href='{url="app=core&module=modcp&controller=modcp&tab=alerts&action=create&user={$member->member_id}" seoTemplate="modcp_alerts"}' title='{lang="alert_send"}' data-ipsDialog data-ipsDialog-title='{lang="alert_send"}' data-ipsDialog-destructOnClose><i class="fa-solid fa-bullhorn" aria-hidden="true"></i> {lang="alert_send"}</a></li>
							{{endif}}
						</ul>
					</div>
				</i-dropdown>
			{{endif}}
		</div>
		<div class='i-flex i-flex-wrap_wrap i-justify-content_space-between i-align-items_center'>
			<div>
				<div class='i-color_soft i-font-weight_500'>{lang="members_joined"}</div>
				<div class='i-color_hard i-font-size_2 i-font-weight_600'>{datetime="$member->joined"}</div>
			</div>
			{{if $member->last_activity && ( ( !$member->isOnlineAnonymously() ) OR ( $member->isOnlineAnonymously() AND \IPS\Member::loggedIn()->isAdmin() ) )}}
				<div class='i-text-align_end'>
					<div class='i-color_soft i-font-weight_500'>
						{{if $member->isOnline() AND ( !$member->isOnlineAnonymously() OR ( $member->isOnlineAnonymously() AND \IPS\Member::loggedIn()->isAdmin() ) )}}
							<span class='ipsOnline' data-ipsTooltip title='{{if $member->isOnlineAnonymously()}}{lang="online_now_anon" sprintf="$member->name"}{{elseif $member->isOnline()}}{lang="online_now" sprintf="$member->name"}{{endif}}'></span> {lang="members_online_now"}
						{{elseif $member->last_activity}}
							<div>{lang="members_last_visit"}</div>
							<div class='i-color_hard i-font-size_2 i-font-weight_600'>{datetime="$member->last_activity"}</div>
						{{endif}}
					</div>
				</div>
			{{endif}}
		</div>
		<div class="ipsFluid i-gap_lines i-padding_0" data-ips-hook="profileHoverStats">
			<div class='i-grid i-place-content_center i-text-align_center i-padding_1'>
				<div class='i-color_hard i-font-size_3 i-font-weight_600'>{number="$member->member_posts" format="short"}</div>
				<div class='i-color_soft i-font-weight_500'>{lang="members_member_posts"}</div>
			</div>
			{{if settings.reputation_enabled and settings.reputation_show_profile}}
				<div class='i-grid i-place-content_center i-text-align_center i-padding_1'>
					<div class='i-color_hard i-font-size_3 i-font-weight_600'>{number="$member->pp_reputation_points" format="short"}</div>
					<div class='i-color_soft i-font-weight_500'>{lang="reputation_title"}</div>
				</div>
			{{endif}}
			{{if $member->canHaveAchievements() and \IPS\core\Achievements\Badge::show() AND \IPS\core\Achievements\Badge::getStore()}}
				<div class='i-grid i-place-content_center i-text-align_center i-padding_1'>
					<div class='i-color_hard i-font-size_3 i-font-weight_600'>{number="$member->badgeCount()" format="short"}</div>
					<div class='i-color_soft i-font-weight_500'>{lang="badges"}</div>
				</div>
			{{endif}}
		</div>
		{{if $member->canHaveAchievements() and \IPS\core\Achievements\Rank::show() AND ( \count( \IPS\core\Achievements\Rank::getStore() ) && $member->rank() ) || ( \count( \IPS\core\Achievements\Badge::getStore() ) && \count( $member->recentBadges( 5 ) ) )}}
			<div class='i-flex i-align-items_center i-flex-wrap_wrap'>
				<div class='i-flex i-align-items_center i-gap_2'>
					{{if \IPS\core\Achievements\Rank::getStore() && $rank = $member->rank()}}
						<div class='i-flex_00' style="width:30px">{$rank->html( '' )|raw}</div>
						<div>
							<div class='i-color_hard i-font-weight_600'>{$rank->_title}</div>
							{{if $rankEarned = $member->rankEarned()}}
								<p class='i-color_soft i-font-weight_500'>{datetime="$rankEarned" format="short"}</p>
							{{endif}}
						</div>
					{{endif}}
				</div>
				{{if \IPS\core\Achievements\Badge::show() AND \IPS\core\Achievements\Badge::getStore()}}
					{{$recentBadges = $member->recentBadges( 5 );}}
					{{if \count( $recentBadges )}}
						<ul class="i-margin-start_auto i-flex i-gap_1">
							{{foreach $recentBadges as $badge}}
								<li style="width:30px">
									{$badge->html( 'ipsCaterpillar__badge', TRUE, TRUE )|raw}
								</li>
							{{endforeach}}
						</ul>
					{{endif}}
				{{endif}}
			</div>
		{{endif}}
		{{if \IPS\Settings::i()->warn_on and !$member->inGroup( explode( ',', \IPS\Settings::i()->warn_protected ) ) and ( \IPS\Member::loggedIn()->modPermission('mod_see_warn') or ( \IPS\Settings::i()->warn_show_own and \IPS\Member::loggedIn()->member_id == $member->member_id ) )}}
			<p class='i-text-align_center'>
				<i class="fa-regular fa-thumbs-down i-margin-end_icon" aria-hidden="true"></i>{lang="member_warn_level" pluralize="$member->warn_level"}
			</p>
		{{endif}}
		{{if \IPS\Member::loggedIn()->modPermission('can_see_emails')}}
			<p class='i-text-align_center'>
				<i class="fa-regular fa-envelope i-margin-end_icon" aria-hidden="true"></i><a href='mailto:{$member->email}' title='{lang="email_this_user"}'>{$member->email}</a>
			</p>
		{{endif}}
		<div class='i-border-end-start-radius_box i-border-end-end-radius_box'>
			<div class='ipsButtons ipsButtons--fill' data-ips-hook="profileHoverButtons">
				{{if ( \IPS\Member::loggedIn()->member_id and \IPS\Member::loggedIn()->member_id !== $member->member_id ) && !$member->members_disable_pm and !\IPS\Member::loggedIn()->members_disable_pm and \IPS\Member::loggedIn()->canAccessModule( \IPS\Application\Module::get( 'core', 'messaging' ) )}}
					<a href='{url="app=core&module=messaging&controller=messenger&do=compose&to={$member->member_id}" seoTemplate="messenger_compose"}' data-ipsDialog data-ipsDialog-title='{lang="compose_new"}' data-ipsDialog-remoteSubmit data-ipsDialog-flashMessage="{lang="message_sent"}" data-ipsDialog-forceReload class='ipsButton ipsButton--inherit'><i class="fa-regular fa-envelope" aria-hidden="true"></i><span>{lang="message_send"}</span></a>
				{{endif}}
				{{if \IPS\Member::loggedIn()->member_id && $member->canBeIgnored() and \IPS\Member::loggedIn()->member_id !== $member->member_id }}
					<a href="{url="app=core&module=system&controller=ignore&id={$member->member_id}" seoTemplate="ignore"}" class='ipsButton ipsButton--inherit'><i class="fa-solid fa-user-slash" aria-hidden="true"></i><span>{lang="add_ignore"}</span></a>
				{{endif}}
				<a href="{url="app=core&module=members&controller=profile&do=content&id={$member->member_id}" base="front" seoTemplate="profile_content" seoTitle="$member->members_seo_name"}" class='ipsButton ipsButton--primary'><i class="fa-regular fa-file-lines" aria-hidden="true"></i><span>{lang="find_content"}</span></a>
			</div>
		</div>
	</div>

{{if \IPS\core\DataLayer::enabled()}}
<script>
    if ( IpsDataLayerConfig && !window.IpsDataLayerConfig && IpsDataLayerConfig._events.social_view.enabled ) {
        $('body').trigger( 'ipsDataLayer', {
            _key: 'social_view',
            _properties: {expression="json_encode(\IPS\core\DataLayer::i()->getMemberProfileEventProperties( $member, ['view_location' => 'hovercard'] ))" raw="true"}
        } );
    }
</script>
{{endif}}

</div>

{{if member.member_id}}
	{{if ( $isFollowing === null and member.following( $app, $area, $id ) ) or $isFollowing}}
		<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}"}" title="{lang="following_this_member"}" data-ipsTooltip class="ipsButton ipsButton--positive" data-role="followButton" data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick>
		    <i class='fa-solid fa-check' aria-hidden="true"></i>
		    <span>{{if $size === 'small'}}{lang="following_member_short"}{{else}}{lang="following_member"}{{endif}}</span>
		    <i class='fa-solid fa-caret-down' aria-hidden="true"></i>
		</a>
	{{else}}	
		<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}"}" title="{lang="follow_this_member"}" data-ipsTooltip class="ipsButton ipsButton--inherit" data-role="followButton" data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick>
		    <i class='fa-solid fa-plus' aria-hidden="true"></i>
		    <span>{{if $size === 'small'}}{lang="follow_member_short"}{{else}}{lang="follow_member"}{{endif}}</span>
	    </a>
	{{endif}}
{{endif}}

{{if member.member_id}}
	{{if member.following( $app, $area, $id )}}
		<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}&from_search=1"}" title="{lang="following_this_member"}" class="ipsButton ipsButton--positive" data-role="followButton" data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick><span>{lang="following_member"}</span><i class='ipsMenuCaret' aria-hidden="true"></i></a>
	{{else}}	
		<a href="{url="app=core&module=system&controller=notifications&do=follow&follow_app={$app}&follow_area={$area}&follow_id={$id}&from_search=1"}" title="{lang="follow_this_member"}" class="ipsButton ipsButton--inherit" data-role="followButton" data-ipsHover data-ipsHover-cache='false' data-ipsHover-onClick><span>{lang="follow_member"}</span></a>
	{{endif}}
{{endif}}

{{if !\IPS\Request::i()->isAjax()}}
<!-- When altering this template be sure to also check for similar in the hovercard -->
<div class="ipsProfileContainer" data-controller='core.front.profile.main'>
	{template="profileHeader" app="core" location="front" group="profile" params="$member, false, $solutions"}
	<div data-role="profileContent">
{{endif}}
		<div class='ipsProfile ipsProfile--profile'>
			<aside class='ipsProfile__aside' id='elProfileInfoColumn'>
				<div class="ipsProfile__sticky-outer">
					<div class="ipsProfile__sticky-inner" data-ips-hook="profileInfoColumn">

						{{if \IPS\Settings::i()->warn_on and !$member->inGroup( explode( ',', \IPS\Settings::i()->warn_protected ) ) and ( \IPS\Member::loggedIn()->modPermission('mod_see_warn') or ( \IPS\Settings::i()->warn_show_own and \IPS\Member::loggedIn()->member_id == $member->member_id ) )}}
							<div class='ipsWidget ipsWidget--warnings'>
								<div class="ipsWidget__content">
									<div class="i-padding_2">
										<div id='elWarningInfo' class="i-padding_1">
											<h4 class='i-margin-bottom_2 i-font-weight_600 i-font-size_3 {{if $member->mod_posts || $member->restrict_post || $member->temp_ban}}i-color_negative{{endif}}'>{{if $member->mod_posts || $member->restrict_post || $member->temp_ban}}<i class="fa-solid fa-triangle-exclamation i-margin-end_icon" aria-hidden="true"></i>{{endif}}{lang="member_warn_level" pluralize="$member->warn_level"}</h4>
											{{if !$member->mod_posts && !$member->restrict_post && !$member->temp_ban}}
												<div class='{{if $member->mod_posts || $member->restrict_post || $member->temp_ban}}i-color_negative i-font-weight_500{{else}}i-color_soft{{endif}}'>{lang="no_restrictions_applied"}</div>
											{{else}}
												<div class='i-font-weight_500 i-color_hard'>{lang="restrictions_applied"}</div>
												<ul class='ipsList ipsList--csv'>
													{{if $member->mod_posts}}
														<li data-ipsTooltip title="{{if $member->mod_posts == -1}}{lang="moderation_modq_perm"}{{else}}{lang="moderation_modq_temp" sprintf="\IPS\DateTime::ts( $member->mod_posts )"}{{endif}}">{lang="moderation_modq"}</li>
													{{endif}}
													{{if $member->restrict_post}}
														<li data-ipsTooltip title="{{if $member->restrict_post == -1}}{lang="moderation_nopost_perm"}{{else}}{lang="moderation_nopost_temp" sprintf="\IPS\DateTime::ts( $member->restrict_post )"}{{endif}}">{lang="moderation_nopost"}</li>
													{{endif}}
													{{if $member->temp_ban}}
														<li data-ipsTooltip title="{{if $member->temp_ban == -1}}{lang="moderation_banned_perm"}{{else}}{lang="moderation_banned_temp" sprintf="\IPS\DateTime::ts( $member->temp_ban )"}{{endif}}">{lang="moderation_banned"}</li>
													{{endif}}
												</ul>
											{{endif}}
										</div>
									</div>
									{{if ( member.canWarn( $member ) || member.modPermission('can_manage_alerts') || ( member.modPermission('can_flag_as_spammer') and !$member->modPermission() and !$member->isAdmin() ) ) and $member->member_id != member.member_id }}
										<ul class='ipsButtons ipsButtons--fill i-padding_1 i-padding-top_0'>
											{{if member.modPermission('can_flag_as_spammer') and $member->member_id != member.member_id and $member->canBeFlaggedAsSpammer()}}
												<li>
													{{if $member->members_bitoptions['bw_is_spammer']}}
														<a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=0" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' class='ipsButton ipsButton--inherit ipsButton--small' title='{lang="spam_unflag"}' data-confirm data-confirmSubMessage="{lang="spam_unflag_confirm"}"><i class="fa-solid fa-user-check" aria-hidden="true"></i> {lang="spam_unflag"}</a>
													{{else}}
														<a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=1" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' class='ipsButton ipsButton--inherit ipsButton--small' title='{lang="spam_flag"}' data-confirm><i class="fa-solid fa-comment-slash" aria-hidden="true"></i> {lang="spam_flag"}</a>
													{{endif}}
												</li>
											{{endif}}
											{{if member.modPermission('can_manage_alerts')}}
												<li>
													<a href='{url="app=core&module=modcp&controller=modcp&tab=alerts&action=create&user={$member->member_id}" seoTemplate="modcp_alerts"}' id='elWarnUserButton' data-ipsDialog data-ipsDialog-title="{lang="alert_send"}" class='ipsButton ipsButton--inherit ipsButton--small' title='{lang="alert_send"}'><i class="fa-solid fa-bullhorn" aria-hidden="true"></i> {lang="alert_send"}</a>
												</li>
											{{endif}}
											{{if member.canWarn( $member )}}
												<li>
													<a href='{$addWarningUrl}' id='elWarnUserButton' data-ipsDialog data-ipsDialog-title="{lang="warn_member" sprintf="$member->name"}" class='ipsButton ipsButton--secondary ipsButton--small' title='{lang="warn_member" sprintf="$member->name"}'><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> {lang="warn_user"}</a>
												</li>
											{{endif}}
										</ul>
									{{endif}}
									{{if \count( $member->warnings( 1 ) )}}
										<i-data data-role="recentWarnings">
											<ol class='ipsData ipsData--table ipsData--compact ipsData--warnings i-border-top_3'>
												{{foreach $member->warnings( 2 ) as $warning}}
													<li class="ipsData__item" id='elWarningOverview_{$warning->id}'>
														<div class='ipsData__icon'>
															<a href="{url="app=core&module=system&controller=warnings&do=view&id={$member->member_id}&w={$warning->id}" seoTemplate="warn_view" seoTitle="$member->members_seo_name"}" data-ipsDialog data-ipsDialog-size='narrow' data-ipsTooltip title='{lang="wan_action_points" pluralize="$warning->points"}'>
																<span class="ipsWarningPoints {{if $warning->expire_date == 0}}ipsWarningPoints--removed{{endif}}">{$warning->points}</span>
															</a>
														</div>
														<div class='ipsData__main'>
															<h4 class='ipsData__title'>
																<a href="{url="app=core&module=system&controller=warnings&do=view&id={$member->member_id}&w={$warning->id}" seoTemplate="warn_view" seoTitle="$member->members_seo_name"}" data-ipsDialog data-ipsDialog-size='narrow' title=''>

																	{{if \IPS\Settings::i()->warnings_acknowledge}}
																		{{if $warning->acknowledged}}
																			<strong class='i-color_positive' title='{lang="warning_acknowledged"}' data-ipsTooltip><i class='fa-solid fa-check-circle' aria-hidden="true"></i></strong>
																		{{else}}
																			<strong class='i-color_soft' title='{lang="warning_not_acknowledged"}' data-ipsTooltip><i class='fa-regular fa-circle' aria-hidden="true"></i></strong>
																		{{endif}}
																	{{endif}}
																	{lang="core_warn_reason_{$warning->reason}"}
																</a>
															</h4>
															<p class='ipsData__meta'>
																{lang="byline_name_date" htmlsprintf="\IPS\Member::load( $warning->moderator )->name, \IPS\DateTime::ts( $warning->date )->html(TRUE)"}
															</p>
															{{if $warning->expire_date == 0}}
																<p class='ipsData__meta i-margin-top_2'>
																	{lang="warning_no_longer_active"}{{if $warning->removed_on}} {lang="warning_expired_on" sprintf="\IPS\DateTime::ts( $warning->removed_on )->relative()"}{{endif}}
																</p>
															{{endif}}													
														</div>
														{{if $warning->canDelete()}}
															<a href="{$warning->url('delete')->csrf()}" title='{lang="revoke_this_warning"}' data-ipsTooltip data-action="revoke" class='ipsButton ipsButton--small ipsButton--text ipsButton--icon' data-ipsDialog data-ipsDialog-title='{lang="revoke_this_warning"}' data-ipsDialog-size='medium'><i class="fa-solid fa-rotate-left" aria-hidden="true"></i></a>
														{{endif}}
													</li>
												{{endforeach}}
											</ol>
											<p class='ipsViewAll'>
												<a href='{url="app=core&module=system&controller=warnings&id={$member->member_id}" seoTemplate="warn_list" seoTitle="$member->members_seo_name"}' title='{lang="see_all_warnings"}' data-ipsDialog data-ipsDialog-remoteVerify='false' data-ipsDialog-remoteSubmit='false' data-ipsDialog-title="{lang="members_warnings" sprintf="$member->name"}">{lang="see_all_c"}</a>
											</p>
										</i-data>
									{{endif}}
								</div>
							</div>
						{{else}}
							{{if \IPS\Member::loggedIn()->modPermission('can_flag_as_spammer') and \IPS\Member::loggedIn()->member_id != $member->member_id and $member->canBeFlaggedAsSpammer()}}
								<div class='ipsWidget ipsWidget--spam'>
									<div class="ipsWidget__content ipsWidget__padding">
										{{if $member->members_bitoptions['bw_is_spammer']}}
											<a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=0" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' class='ipsButton ipsButton--inherit ipsButton--small ipsButton--wide' title='{lang="spam_unflag"}' data-confirm data-confirmSubMessage="{lang="spam_unflag_confirm"}">{lang="spam_unflag"}</a>
										{{else}}
											<a href='{url="app=core&module=system&controller=moderation&do=flagAsSpammer&id={$member->member_id}&s=1" seoTemplate="flag_as_spammer" seoTitle="$member->members_seo_name" csrf="true"}' class='ipsButton ipsButton--inherit ipsButton--small ipsButton--wide' title='{lang="spam_flag"}' data-confirm>{lang="spam_flag"}</a>
										{{endif}}
									</div>
								</div>
							{{endif}}
						{{endif}}

						{{if \IPS\Application::appIsEnabled('nexus') and settings.nexus_subs_enabled and settings.nexus_subs_show_public}}
							{template="profileSubscription" app="nexus" location="front" group="subscription" params="$member"}
						{{endif}}

						{{if $member->isExpert()}}
							<div class='ipsWidget ipsWidget--expert'>
								<h3 class="ipsWidget__header">{lang="community_expert"}</h3>
								<div class="ipsWidget__content ipsWidget__padding">
									<div class='i-flex_11 i-grid i-place-content_center i-font-size_6'>
										<i class="fa-solid fa-medal" aria-hidden="true"></i>
									</div>
								</div>
							</div>
						{{endif}}

						{{if (settings.reputation_enabled and settings.reputation_show_profile) or (\IPS\core\Achievements\Rank::show() and \count( \IPS\core\Achievements\Rank::getStore() ) && $rank = $member->rank())}}
							<div class='ipsWidget ipsWidget--profileAchievements'>
								<div class='ipsWidget__content'>

									<i-data>
										<ul class="ipsData ipsData--table ipsData--profileAchievements">
											{{if settings.reputation_enabled and settings.reputation_show_profile}}
												{{if settings.reputation_leaderboard_on and settings.reputation_show_days_won_trophy and $member->getReputationDaysWonCount() and $lastDayWon = $member->getReputationLastDayWon()}}
													{{$formattedDate = $lastDayWon['date']->dayAndMonth() . (  $lastDayWon['date']->format('Y') == \IPS\DateTime::ts( time() )->format('Y' ) ? '' : " " . $lastDayWon['date']->format('Y') );}}
													<li class='ipsData__item'>
														<a href="{url="app=core&module=discover&controller=popular&tab=leaderboard&custom_date_start={$lastDayWon['date']->getTimeStamp()}&custom_date_end={$lastDayWon['date']->getTimeStamp()}" seoTemplate="leaderboard_leaderboard"}" class='ipsLinkPanel' aria-hidden="true" tabindex="-1"><span>{number="$member->getReputationDaysWonCount()"} {lang="members_days_won_count"}!</span></a>
														<div class="ipsData__content">
															<div class='ipsData__main'>
																<h3 class='ipsData__title'>{number="$member->getReputationDaysWonCount()"} {lang="members_days_won_count"}!</h3>
																<p class='ipsData__desc'>{{if $member->member_id == \IPS\Member::loggedIn()->member_id}}{lang="profile_you_congrats"}{{else}}{lang="profile_member_congrats" sprintf="$member->name"}{{endif}} <a href="{url="app=core&module=discover&controller=popular&tab=leaderboard&custom_date_start={$lastDayWon['date']->getTimeStamp()}&custom_date_end={$lastDayWon['date']->getTimeStamp()}" seoTemplate="leaderboard_leaderboard"}">
																	{{if $member->member_id == \IPS\Member::loggedIn()->member_id}}
																		{lang="profile_you_won" sprintf="$formattedDate"}
																	{{else}}
																		{lang="profile_member_won" sprintf="$formattedDate"}
																	{{endif}}
																</a></p>
															</div>
														</div>
														<div class="i-font-size_7">🏆</div>
													</li>
												{{endif}}
											{{endif}}

											{{if \IPS\core\Achievements\Rank::show() and \count( \IPS\core\Achievements\Rank::getStore() ) && $rank = $member->rank()}}
												{{$progressId = 'ipsProgress-' . mt_rand();}}
												<li class='ipsData__item'>
													<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=badges" seoTemplate="profile_badges" seoTitle="$member->members_seo_name"}" data-action="badgeLog" title="{lang="members_badges" sprintf="$member->name"}" class='ipsLinkPanel' aria-hidden="true" tabindex="-1"><span>{lang="view_all"}</span></a>
													<div class='ipsData__main'>
														<div class="i-flex">
															<div class="i-flex_11">
																<h3 class='ipsData__title'>{$rank->_title}</h3>
																<p id="{$progressId}" class="ipsData__desc">{lang="achievements_current_rank"} ({$rank->rankPosition()['pos']}/{$rank->rankPosition()['max']})</p>
															</div>
															<div class='i-flex_00 i-basis_30'>
																{$rank->html( 'ipsDimension i-basis_30' )|raw}
															</div>
														</div>
														{{if $nextRank = $member->nextRank()}}
															<div class='i-margin-top_2'>
																<progress aria-labelledby="{$progressId}" class='ipsProgress ipsProgress--rank i-margin-bottom_1' value='{expression="($member->achievements_points - $rank->points) / ($nextRank->points - $rank->points) * 100"}' max="100"></progress>
																{{if $member->member_id == \IPS\Member::loggedIn()->member_id}}
																	<div class='i-font-size_-2 i-color_soft'>{lang="achievements_next_rank" pluralize="$nextRank->points - $member->achievements_points"}</div>
																{{endif}}
															</div>
														{{endif}}
													</div>
												</li>
											{{endif}}

											{{if \IPS\core\Achievements\Badge::show() and \count( \IPS\core\Achievements\Badge::getStore() )}}
												{{$recentBadges = $member->recentBadges( 6 );}}	
												{{if \count( $recentBadges )}}
													<li class='ipsData__item'>
														<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=badges" seoTemplate="profile_badges" seoTitle="$member->members_seo_name"}" data-action="badgeLog" title="{lang="members_badges" sprintf="$member->name"}" class='ipsLinkPanel' aria-hidden="true" tabindex="-1"><span>{lang="view_all"}</span></a>
														<div class="ipsData__main">
															<div class="i-flex i-align-items_center i-justify-content_space-between i-margin-bottom_2">
																<h3 class="ipsData__title">
																	{lang="profile_recent_badges"}
																</h3>
																<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=badges" seoTemplate="profile_badges" seoTitle="$member->members_seo_name"}" data-action="badgeLog" title="{lang="members_badges" sprintf="$member->name"}" class='i-font-size_-1 i-font-weight_500 i-color_soft'>{lang="view_all"}</a>
															</div>
															<ul class="i-flex i-gap_1">
																{{foreach $recentBadges as $badge}}
																	<li class='i-basis_40'>
																		{$badge->html( '', TRUE, TRUE )|raw}
																	</li>
																{{endforeach}}
															</ul>
														</div>
													</li>										
												{{endif}}
											{{endif}}

										</ul>
									</i-data>
								</div>
							</div>
						{{endif}}

						<div class='ipsWidget ipsWidget--profileMeta'>
							<div class='ipsWidget__content'>

								<i-data>
									<ul class="ipsData ipsData--table ipsData--profileMeta">
										{{if $member->group['g_icon'] }}
											<li class='ipsData__item i-text-align_center'>
												<div class="ipsData__main"><img src='{file="$member->group['g_icon']" extension="core_Theme"}' alt='' loading='lazy' {{if $width = $member->group['g_icon_width']}}width="{$width}"{{endif}}></div>
											</li>
										{{endif}}

										{{if \IPS\Member::loggedIn()->modPermission('can_see_emails')}}
											<li class="ipsData__item">
												<a href='mailto:{$member->email}' class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{lang="email_this_user"}</span></a>
												<div class="ipsData__icon"><i class="fa-solid fa-envelope" aria-hidden="true"></i></div>
												<div class="ipsData__main">
													<strong class='ipsData__title'>{lang="profile_email"}</strong>
													<div class='ipsData__desc'>
														<div class="i-font-weight_500"><a href='mailto:{$member->email}' title='{lang="email_this_user"}'>{$member->email}</a></div>
														<span class='i-font-size_-1'>{lang="profile_email_addresses"}</span>
													</div>
												</div>
											</li>
										{{endif}}

										<li class='ipsData__item'>
											<a href="{url="app=core&module=members&controller=profile&do=content&id={$member->member_id}" base="front" seoTemplate="profile_content" seoTitle="$member->members_seo_name"}" rel="nofollow" class='ipsLinkPanel' data-action="browseContent" data-type='full' title="{lang="members_content" sprintf="$member->name"}" aria-hidden="true" tabindex="-1"><span>{{if member.member_id === $member->member_id}}{lang="profile_browse_my_content"}{{else}}{lang="profile_browse_content"}{{endif}}</span></a>
											<div class="ipsData__icon"><i class="fa-solid fa-comment" aria-hidden="true"></i></div>
											<div class="ipsData__main">
												<h4 class='ipsData__title'>{lang="members_member_posts"}</h4>
												<div class="ipsData__desc"><a href="{url="app=core&module=members&controller=profile&do=content&id={$member->member_id}" base="front" seoTemplate="profile_content" seoTitle="$member->members_seo_name"}" rel="nofollow" class='ips' data-action="browseContent" data-type='full' title="{lang="members_content" sprintf="$member->name"}"><span>{{if member.member_id === $member->member_id}}{lang="profile_browse_my_content"}{{else}}{lang="profile_browse_content"}{{endif}}</span></a></div>
											</div>
											<div class='i-font-size_4 i-font-weight_600 i-flex_00'>
												{number="$member->member_posts"}
											</div>
										</li>

										{{if $solutions}}
											<li class='ipsData__item'>
												<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=solutions" seoTemplate="profile_solutions" seoTitle="$member->members_seo_name"}" data-action="solutionLog" title="{lang="members_solutions" sprintf="$member->name"}" class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{lang="solutionlog_show_activity"}</span></a>
												<div class="ipsData__icon"><i class="fa-solid fa-clipboard-check" aria-hidden="true"></i></div>
												<div class="ipsData__main">
													<h3 class="ipsData__title">{lang="profile_solutions"}</h3>
													<p class="ipsData__desc">
														<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=solutions" seoTemplate="profile_solutions" seoTitle="$member->members_seo_name"}" data-action="solutionLog" title="{lang="members_solutions" sprintf="$member->name"}">{lang="solutionlog_show_activity"}</a>
													</p>
												</div>
												<div class='i-font-size_4 i-font-weight_600 i-flex_00'>
													{number="$solutions"}
												</div>
											</li>
										{{endif}}

										{{if settings.reputation_enabled and settings.reputation_show_profile}}
											<li class='ipsData__item'>
												{{if member.group['gbw_view_reps']}}
													<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=reputation" seoTemplate="profile_reputation" seoTitle="$member->members_seo_name"}" data-action="repLog" title="{lang="members_reputation" sprintf="$member->name"}" class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{lang="replog_show_activity"}</span></a>
												{{endif}}
												<div class="ipsData__icon"><i class="fa-solid fa-thumbs-up" aria-hidden="true"></i></div>
												<div class="ipsData__main">
													<h3 class='ipsData__title'>{lang="profile_reputation"}</h3>
													{{if $member->reputation()}}
														{{if member.group['gbw_view_reps']}}
															<a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=reputation" seoTemplate="profile_reputation" seoTitle="$member->members_seo_name"}" data-action="repLog" title="{lang="members_reputation" sprintf="$member->name"}" class='ipsData__desc'>
																{$member->reputation()}
															</a>
														{{else}}
															<span class='ipsData__desc'>{$member->reputation()}</span>
														{{endif}}
													{{endif}}
													{{if $member->reputationImage()}}
														<div class='i-margin-top_2'>
															<img src='{file="$member->reputationImage()" extension="core_Theme"}' alt='' loading='lazy'>
														</div>
													{{endif}}
												</div>
												<div class='i-font-size_4 i-font-weight_600 i-flex_00 {{if $member->pp_reputation_points > 1}}i-color_positive{{elseif $member->pp_reputation_points < 0}}i-color_negative{{else}}i-color_soft{{endif}}'>
													{number="$member->pp_reputation_points"}
												</div>
											</li>
										{{endif}}
										{{if $member->birthday AND \IPS\Settings::i()->profile_birthday_type == 'public' or ( \IPS\Settings::i()->profile_birthday_type == 'private' and ( \IPS\Member::loggedIn()->member_id == $member->member_id OR \IPS\Member::loggedIn()->isAdmin() ) )}}
											<li class="ipsData__item">
												<div class="ipsData__icon"><i class="fa-solid fa-cake-candles" aria-hidden="true"></i></div>
												<div class="ipsData__main">
													<strong class='ipsData__title'>{lang="bday"}</strong>
													<div class='ipsData__desc'>{$member->birthday}</div>
												</div>
											</li>
										{{endif}}
										{{if ( ! empty( $followers ) and is_array( $followers ) and count( $followers ) ) || \IPS\Member::loggedIn()->member_id === $member->member_id}}
											<li class="ipsData__item" id='elFollowers' data-feedID='member-{$member->member_id}' data-controller='core.front.profile.followers'>
												{template="followers" group="profile" app="core" params="$member, $followers"}
											</li>
										{{endif}}
									</ul>
								</i-data>

							</div>
						</div>

						{{foreach $sidebarFields as $group => $fields}}
							{{if \count( $fields ) AND \count( array_filter( $fields, function( $fieldValue ){ return $fieldValue['value']; } ) )}}
							<div class='ipsWidget ipsWidget--fields' data-location='customFields'>
								{{if $group != 'core_pfieldgroups_0'}}
									<h2 class='ipsWidget__header'>{lang="$group"}</h2>
								{{endif}}
								<div class="ipsWidget__content">
									<i-data>
										<ul class='ipsData ipsData--table ipsData--profileCustomFields'>
											{{foreach $fields as $field => $value}}
												{{if $value['value'] !== ""}}
													<li class="ipsData__item">
														<div class="ipsData__main">
															{{if $value['custom']}}
																{$value['value']|raw}
															{{else}}
																<strong class='ipsData__title'>{lang="$field"}</strong>
																<div class='ipsData__desc'>{$value['value']|raw}</div>
															{{endif}}
														</div>
													</li>
												{{endif}}
											{{endforeach}}
										</ul>
									</i-data>
								</div>
							</div>
							{{endif}}
						{{endforeach}}
						{{if !empty( $visitors ) || \IPS\Member::loggedIn()->member_id == $member->member_id}}
							<div class='ipsWidget ipsWidget--recent' data-controller='core.front.profile.toggleBlock'>
								{template="recentVisitorsBlock" group="profile" params="$member, $visitors"}
							</div>
						{{endif}}
					</div>
				</div>
			</aside>
			<section class='ipsProfile__main ipsBox ipsBox--profileMain ipsPull'>
				{$mainContent|raw}
			</section>
		</div>
{{if !\IPS\Request::i()->isAjax()}}
	</div>
</div>
{{endif}}

{{if \count( $clubs )}}
	{{if $pagination}}
		{$pagination|raw}
	{{endif}}

	<i-data>
		<ul class='ipsData ipsData--grid ipsData--profile-clubs'>
			{{foreach $clubs as $club}}
				{template="clubCard" group="clubs" app="core" params="$club"}
			{{endforeach}}
		</ul>
	</i-data>

	{{if $pagination}}
		{$pagination|raw}
	{{endif}}
{{else}}
	<p class='ipsEmptyMessage'>
		{lang="member_no_clubs" sprintf="$member->name"}
	</p>
{{endif}}

{{$coverPhoto = $member->coverPhoto();}}
<header class="ipsPageHeader ipsBox ipsBox--profileHeader ipsPull i-margin-bottom_block" data-ips-hook="profileHeader" data-role="profileHeader">
	<div class='ipsCoverPhoto ipsCoverPhoto--profile {{if $small === true}}ipsCoverPhoto--minimal{{endif}}' id='elProfileHeader' data-controller='core.global.core.coverPhoto' data-url="{$member->url()->csrf()}" data-coverOffset='{$coverPhoto->offset}' style='--offset:{$coverPhoto->offset}'>
		{{if $coverPhoto->file}}
			<div class='ipsCoverPhoto__container'>
				<img src='{$coverPhoto->file->url}' class='ipsCoverPhoto__image' data-action="toggleCoverPhoto" alt='' loading='lazy'>
			</div>
		{{else}}
			<div class='ipsCoverPhoto__container'>
				<div class="ipsFallbackImage" style="--i-empty-image-random--ba-co: {$member->coverPhotoBackgroundColor()};"></div>
			</div>
		{{endif}}
		{{if \IPS\Member::loggedIn()->modPermission('can_modify_profiles') or ( \IPS\Member::loggedIn()->member_id == $member->member_id )}}
			<div class="ipsCoverPhoto__overlay-buttons" data-hideoncoveredit data-ips-hook="profileHeaderMenu">{expression="$member->menu( 'profile' )" raw="true"}</div>
		{{endif}}
	</div>
	<div class="ipsCoverPhotoMeta">
		<div class='ipsCoverPhoto__avatar' id='elProfilePhoto'>
			{{if $member->pp_main_photo and ( mb_substr( $member->pp_photo_type, 0, 5 ) === 'sync-' or $member->pp_photo_type === 'custom' )}}
				<a href='{file="$member->pp_main_photo" extension="core_Profile"}' data-ipsLightbox class='ipsUserPhoto'>
					<img src='{$member->photo}' alt='' loading='lazy'>
				</a>
			{{else}}
				<span class='ipsUserPhoto'>
					<img src='{$member->photo}' alt='' loading='lazy'>
				</span>
			{{endif}}
		</div>
		<div class='ipsCoverPhoto__titles'>
			<div class='ipsCoverPhoto__title'>
				<h1>{$member->name}</h1>
				{{if \IPS\Member::loggedIn()->group['g_view_displaynamehistory'] AND $member->hasNameChanges()}}
					<a href='{$member->url()->setQueryString( 'do', 'namehistory' )}' class='ipsCoverPhoto__title-icon' title='{lang="membername_history"}' data-ipsTooltip data-ipsDialog data-ipsDialog-modal='true' data-ipsDialog-size='narrow' data-ipsDialog-title='{lang="membername_history"}'>
						<i class='fa-solid fa-clock-rotate-left' aria-hidden="true"></i>
					</a>
				{{endif}}
				{{if \IPS\Member::loggedIn()->member_id AND \IPS\Member::loggedIn()->member_id === $member->member_id AND $member->isOnlineAnonymously()}}
					<span class='ipsCoverPhoto__title-icon' title='{lang="member_is_currently_anon"}' data-ipsTooltip>
						<i class='fa-solid fa-eye-slash' aria-hidden="true"></i>
					</span>
				{{endif}}
			</div>
			<div class='ipsCoverPhoto__desc'>
				{expression="\IPS\Member\Group::load( $member->member_group_id )->formattedName" raw="true"}
			</div>
		</div>
		<ul class="ipsCoverPhoto__stats" data-ips-hook="profileHeaderStats">
			<li>
				<h4 class='ipsCoverPhoto__statTitle'>{lang="joined"}</h4>
				<span class='ipsCoverPhoto__statValue'>{datetime="$member->joined"}</span>
			</li>
			{{if ( !$member->isOnlineAnonymously() ) OR ( $member->isOnlineAnonymously() AND \IPS\Member::loggedIn()->isAdmin() )}}
				<li>
					<h4 class='ipsCoverPhoto__statTitle'>{lang="members_last_visit"}</h4>
					<span class='ipsCoverPhoto__statValue'>
						{{if $member->last_activity}}{datetime="$member->last_activity"}{{else}}{lang="never"}{{endif}}
						{{if $member->isOnline() AND ( !$member->isOnlineAnonymously() OR ( $member->isOnlineAnonymously() AND \IPS\Member::loggedIn()->isAdmin() ) )}}
							<i class="ipsOnline" data-ipsTooltip title='{{if $member->isOnlineAnonymously()}}{lang="online_now_anon" sprintf="$member->name"}{{elseif $member->isOnline()}}{lang="online_now" sprintf="$member->name"}{{endif}}' aria-hidden="true"></i>
						{{endif}}
					</span>
				</li>
			{{endif}}
			{{if $member->isOnline() AND ( !$member->isOnlineAnonymously() OR ( $member->isOnlineAnonymously() AND \IPS\Member::loggedIn()->isAdmin() ) ) AND $member->location}}
				<li>
					<h4 class='ipsCoverPhoto__statTitle'>{lang="online_users_location_lang"}</h4>
					<span class='ipsCoverPhoto__statValue'>{$member->location()|raw}</span>
				</li>
			{{endif}}
		</ul>
		<div class='ipsCoverPhoto__buttons' data-ips-hook="profileHeaderButtons">
			{{if \IPS\Member::loggedIn()->member_id != $member->member_id}}
				{{if member.canFollow( $member ) or member.following('core', 'member', $member->member_id )}}
					{template="memberFollow" app="core" group="profile" params="'core', 'member', $member->member_id, $member->followersCount()"}
				{{endif}}
				{{if \IPS\Member::loggedIn()->member_id && !$member->members_disable_pm and !\IPS\Member::loggedIn()->members_disable_pm and \IPS\Member::loggedIn()->canAccessModule( \IPS\Application\Module::get( 'core', 'messaging' ) )}}
					<a href='{url="app=core&module=messaging&controller=messenger&do=compose&to={$member->member_id}" seoTemplate="messenger_compose"}' data-ipsDialog data-ipsDialog-title='{lang="compose_new"}' data-ipsDialog-remoteSubmit data-ipsDialog-flashMessage="{lang="message_sent"}" class='ipsButton ipsButton--inherit'><i class='fa-solid fa-envelope' aria-hidden="true"></i><span>{lang="message_send"}</span></a>
				{{endif}}
			{{endif}}

			<a href='{$member->url()}' class='ipsButton ipsButton--primary' data-action="goToProfile" data-type='full' title="{lang="members_profile" sprintf="$member->name"}"><i class="fa-regular fa-circle-user" aria-hidden="true"></i><span>{lang="profile_view_profile"}</span></a>

			<a href="{url="app=core&module=members&controller=profile&do=content&id={$member->member_id}" base="front" seoTemplate="profile_content" seoTitle="$member->members_seo_name"}" rel="nofollow" class='ipsButton ipsButton--primary' data-action="browseContent" data-type='full' title="{lang="members_content" sprintf="$member->name"}"><i class="fa-regular fa-file-lines" aria-hidden="true"></i><span>{{if member.member_id === $member->member_id}}{lang="profile_browse_my_content"}{{else}}{lang="profile_browse_content"}{{endif}}</span></a>
		</div>
	</div>
</header>

{{if \count( $tabs ) > 1}}
	<div class="ipsPwaStickyFix ipsPwaStickyFix--ipsTabs"></div>
	<i-tabs class='ipsTabs ipsTabs--sticky ipsTabs--profile ipsTabs--stretch' id='elProfileTabs' data-ipsTabBar data-ipsTabBar-contentArea='#elProfileTabs_content'>
		<div role="tablist">
			{{foreach $tabs as $tab => $tabData}}
				<a href="{$tabData['url']}" id='elProfileTab_{$tab}' class='ipsTabs__tab' role="tab" aria-controls="elProfileTab_{$tab}_panel" aria-selected="{{if $activeTab == $tab}}true{{else}}false{{endif}}">{lang="$tabData['title']"}</a>
			{{endforeach}}
		</div>
		{template="tabScrollers" app="core" group="global" location="global"}
	</i-tabs>
{{endif}}
<div id='elProfileTabs_content' class='ipsTabs__panels ipsTabs__panels--profile'>
	{{foreach $tabs as $tab => $title}}
		{{if $activeTab == $tab}}
			<div id="elProfileTab_{$tab}_panel" class='ipsTabs__panel' role="tabpanel" aria-labelledby="elProfileTab_{$tab}">
				{$activeTabContents|raw}
			</div>
		{{endif}}
	{{endforeach}}
</div>

{{if $member->members_bitoptions['pp_setting_count_visitors']}}

	<h2 class='ipsWidget__header'>
		<span>{lang="profile_recent_visitors"}</span>
		{{if \IPS\Member::loggedIn()->modPermission('can_modify_profiles') or ( \IPS\Member::loggedIn()->member_id == $member->member_id and $member->group['g_edit_profile'] )}}
			<a href='{url="app=core&module=members&controller=profile&do=visitors&id=$member->member_id" seoTemplate="profile" seoTitle="$member->members_seo_name" csrf="true"}' class='i-color_inherit i-opacity_5 i-margin-start_auto' data-ipsTooltip title='{lang="hide_recent_visitors"}' data-action='disable'><i class='fa-solid fa-xmark' aria-hidden="true"></i><span class="ipsInvisible">{lang="hide_recent_visitors"}</span></a>
		{{endif}}
	</h2>
	<div class="ipsWidget__content">
		{{if \is_array( $visitors ) AND \count( $visitors ) }}
			<i-data>
				<ul class='ipsData ipsData--table ipsData--profileVisitors'>
				{{foreach $visitors as $visitor}}
					<li class="ipsData__item">
						<div class='ipsData__icon'>
							{template="userPhoto" app="core" group="global" params="$visitor['member'], 'fluid'"}
						</div>
						<div class='ipsData__main'>
							<div class='ipsData__title'>{$visitor['member']->link()|raw}</div>
							<div class='ipsData__meta'>{datetime="$visitor['visit_time']"}</div>
						</div>
					</li>
				{{endforeach}}
				</ul>
			</i-data>
			<div class='i-color_soft i-padding_2 i-font-size_500 i-border-top_3 i-text-align_end'>
				{lang="profile_views" pluralize="$member->members_profile_views"}
			</div>
		{{else}}
			<div class='i-text-align_center i-color_soft i-padding_2'>{lang="no_recent_visitors"}</div>
		{{endif}}
	</div>
{{else}}
	<h2 class='ipsWidget__header'>{lang="profile_recent_visitors"}</h2>
	<div class='ipsWidget__content ipsWidget__padding i-text-align_center'>
		<p class='i-color_soft'>{lang="disabled_recent_visitors"}</p>
        {{if \IPS\Member::loggedIn()->modPermission('can_modify_profiles') or ( \IPS\Member::loggedIn()->member_id == $member->member_id and $member->group['g_edit_profile'] )}}
			<div class='i-margin-top_1 i-font-weight_500'><a href='{url="app=core&module=members&controller=profile&do=visitors&id={$member->member_id}&state=1" seoTemplate="profile" seoTitle="$member->members_seo_name" csrf="TRUE"}' data-action='enable'>{lang="enable"}</a></div>
        {{endif}}
	</div>
{{endif}}

{{$baseUrl = \IPS\Http\Url::internal( "app=core&module=members&controller=profile&id={$member->member_id}&do=content", 'front', 'profile_content', $member->members_seo_name );}}
{{if !\IPS\Request::i()->isAjax()}}
<div class="ipsProfileContainer" data-controller='core.front.profile.main' id='elProfileUserContent'>
	{template="profileHeader" app="core" location="front" group="profile" params="$member, true"}
	<div data-role="profileContent">
{{endif}}
		<div class='ipsProfile ipsProfile--badges'>
            {{if $member->canHaveAchievements() and \IPS\core\Achievements\Rank::show() and \IPS\core\Achievements\Rank::getStore() and $rank = $member->rank()}}
                <aside class='ipsProfile__aside'>
                    <div class="ipsProfile__sticky-outer">
                        <div class="ipsProfile__sticky-inner">
                            <div class='ipsWidget'>
                                <h2 class='ipsWidget__header'>{lang="achievements_profile_rank_progress"}</h2>
                                <div class='i-padding_3'>
                                    {{if $rank}}
                                    <p class='i-margin-bottom_3'>
                                        {{if $percentage}}
                                            {lang="profile_rank_progress_blurb_percentage" sprintf="$member->name, $member->rank()->rankPosition()['pos'], $member->rank()->rankPosition()['max'], $percentage"}
                                        <span class="i-color_soft i-font-size_-2" data-ipsToolTip title="{lang="profile_rank_progress_blurb_percentage_info"}"><i class="fa-solid fa-circle-info" aria-hidden="true"></i></span>
                                        {{else}}
                                            {lang="profile_rank_progress_blurb" sprintf="$member->name, $member->rank()->rankPosition()['pos'], $member->rank()->rankPosition()['max']"}
                                        {{endif}}
                                    </p>
                                    <hr class='ipsHr i-margin-block_3'>
                                    {{endif}}

                                    <ul class='cRankHistory'>
                                        {{if $member->rankHistory()['earned']}}
                                            {{foreach $member->rankHistory()['earned'] as $entry}}
                                                <li class='cRankHistory__item'>
                                                    <div class='cRankHistory__icon'>{$entry['rank']->html( 'cRankHistory__itemBadge' )|raw}</div>
                                                    <div>
                                                        <h3 class='i-font-weight_semi-bold i-color_hard i-font-size_2'>{$entry['rank']->_title}</h3>
                                                        {{if ! $entry['time'] or ( $entry['time']->getTimestamp() < settings.achievements_last_rebuilt)}}
                                                            {{if \IPS\Settings::i()->achievements_last_rebuilt}}<p class='i-color_soft'>{lang="badge_earned_date_while_rebuilding" htmlsprintf="\IPS\DateTime::ts( (int) \IPS\Settings::i()->achievements_last_rebuilt )->shortMonthAndFullYear()"}</p>{{endif}}
                                                        {{elseif $entry['time']}}
                                                        <p class='i-color_soft'>{lang="badge_earned_date" htmlsprintf="$entry['time']->html()"}</p>
                                                        {{endif}}
                                                    </div>
                                                </li>
                                            {{endforeach}}
                                        {{endif}}
                                        {{if $member->rankHistory()['not_earned']}}
                                            {{foreach $member->rankHistory()['not_earned'] as $entry}}
                                                <li class='cRankHistory__item'>
                                                <div class='cRankHistory__icon'>{$entry['rank']->html( 'cRankHistory__itemBadge cRankHistory__itemBadge--unearned' )|raw}</div>
                                                    <div class='i-opacity_6'>
                                                        <h3 class='i-font-weight_semi-bold i-font-size_2'>{$entry['rank']->_title}</h3>
                                                        <p><em>{lang="badge_earned_but_not_really"}</em></p>
                                                    </div>
                                                </li>
                                            {{endforeach}}
                                        {{endif}}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </div>
                </aside>
            {{endif}}
			<section class='ipsProfile__main ipsBox'>
                <h2 class='ipsBox__header'>{lang="achievements_profile_title" pluralize="$member->badgeCount()"}</h2>
                {{if $member->badgeCount()}}
                    <div class='i-padding_3 ipsGrid i-basis_200 i-gap_4 cProfileBadgeGrid'>
                        {{foreach $member->recentBadges( NULL ) as $badge}}
                            <div class='i-flex i-gap_2 i-align-items_center' data-badge='{$badge->_id}'>
                                <div class="i-flex_00">{$badge->html('i-flex_00 i-basis_40 ipsDimension', FALSE, TRUE)|raw}</div>
                                <div class="i-flex_11">
                                    {{if ! empty( $badge->recognize ) AND $badge->recognize->contentWrapper() }}
                                    <h4 class='i-font-weight_semi-bold'>
                                        {lang="badge_from_recognize" sprintf="$badge->_title, $badge->recognize->content()->url(), $badge->recognize->content()->indefiniteArticle()"}
                                    </h4>
                                    {{else}}
                                    <h4 class='i-font-weight_semi-bold'>{$badge->_title}</h4>
                                    {{endif}}
                                    {{if ! empty( $badge->awardDescription )}}
                                        <p class='i-font-size_-2 i-color_soft'>{$badge->awardDescription}</p>
                                    {{endif}}
                                    {{if $badge->datetime < settings.achievements_last_rebuilt}}
                                        {{if \IPS\Settings::i()->achievements_last_rebuilt}}<p class='i-font-size_-2 i-color_soft'>{lang="badge_earned_date_while_rebuilding" htmlsprintf="\IPS\DateTime::ts( (int) \IPS\Settings::i()->achievements_last_rebuilt )->shortMonthAndFullYear()"}</p>{{endif}}
                                    {{else}}
                                    <p class='i-font-size_-2 i-color_soft'>{lang="badge_earned_date" htmlsprintf="\IPS\DateTime::ts( $badge->datetime )->html( false )"}</p>
                                    {{endif}}
                                </div>
                            </div>
                        {{endforeach}}
                    </div>
                {{else}}
                    <div class='i-padding_3 i-text-align_center i-color_soft'>
                        {{if $member->member_id === \IPS\Member::loggedIn()->member_id}}
                            {lang="achievements_self_none" sprintf=""}
                        {{else}}
                            {lang="achievements_member_none" sprintf="$member->name"}
                        {{endif}}
                    </div>
                {{endif}}
			</section>
		</div>
{{if !\IPS\Request::i()->isAjax()}}
	</div>
</div>
{{endif}}

{{if !\IPS\Request::i()->isAjax()}}
<div class="ipsProfileContainer" data-controller='core.front.profile.main'>
	{template="profileHeader" app="core" location="front" group="profile" params="$member, true"}
	<div data-role="profileContent">
{{endif}}
		<div class="ipsProfile ipsProfile--reputation">
			<aside class="ipsProfile__aside">
				<div class="ipsProfile__sticky-outer">
					<div class="ipsProfile__sticky-inner">
						<div class="cProfileRepScore i-padding_2 {{if $member->pp_reputation_points > 1}}cProfileRepScore--positive{{elseif $member->pp_reputation_points < 0}}cProfileRepScore--negative{{else}}cProfileRepScore--neutral{{endif}}">
							<h2 class='ipsMinorTitle i-color_inherit i-opacity_5'>{lang="profile_reputation"}</h2>
							<span class='cProfileRepScore__points'>{number="$member->pp_reputation_points"}</span>
							{{if $member->reputation()}}
								<span class='cProfileRepScore__title'>{$member->reputation()}</span>
							{{endif}}
							{{if $member->reputationImage()}}
								<div class='i-background_1 i-border-radius_box i-padding_2 i-text-align_center'>
									<img src='{file="$member->reputationImage()" extension="core_Theme"}' alt=''>
							</div>
							{{endif}}
						</div>
						{{if \count( $reactions['given'] ) OR \count( $reactions['received'] )}}
							<div class="ipsWidget i-padding_3">
								{{if \count( $reactions['given'] )}}
									<h2 class='ipsMinorTitle'>{lang="replog_reactions_given"}</h2>
									<div class='ipsGrid ipsGrid--profile-reactions-given i-basis_80 i-margin-top_2 i-margin-bottom_4'>
										{{foreach $reactions['given'] as $reaction}}
											<div class="i-flex i-align-items_center i-gap_1">
												<img src='{$reaction['reaction']->_icon->url}' width="20" height="20" alt='{$reaction['reaction']->_title}' loading='lazy' data-ipsTooltip>
												<span class='i-color_soft i-font-weight_600'><span class="i-opacity_4">x</span> {$reaction['count']}</span>
											</div>
										{{endforeach}}
									</div>
								{{endif}}

								{{if \count( $reactions['received'] )}}
									<h2 class='ipsMinorTitle'>{lang="replog_reactions_received"}</h2>
									<div class='ipsGrid ipsGrid--profile-reactions-received i-basis_80 i-margin-top_2'>
										{{foreach $reactions['received'] as $reaction}}
											<div class="i-flex i-align-items_center i-gap_1">
												<img src='{$reaction['reaction']->_icon->url}' width="20" height="20" alt='{$reaction['reaction']->_title}' loading='lazy' data-ipsTooltip>
												<span class='i-color_soft i-font-weight_600'><span class="i-opacity_4">x</span> {$reaction['count']}</span>
											</div>
										{{endforeach}}
									</div>
								{{endif}}		
							</div>
						{{endif}}						
						<div class='ipsWidget i-padding_2'>
							<div class="ipsSideMenu" data-ipsTabBar data-ipsTabBar-contentArea='#elUserReputation' data-ipsTabBar-itemselector=".ipsSideMenu_item" data-ipsTabBar-activeClass="ipsSideMenu_itemActive" data-ipsSideMenu>
								<h3 class="ipsSideMenu__view">
									<a href="#user_reputation" data-action="openSideMenu"><i class="fa-solid fa-bars" aria-hidden="true"></i><span>{lang="user_content_type"}</span></a>
								</h3>
								<div class="ipsSideMenu__menu">
									{{foreach $types as $app => $_types}}
										<h4 class='ipsSideMenu__subTitle'>{lang="module__{$app}"}</h4>
										<ul class="ipsSideMenu__list">
											{{foreach $_types as $key => $class}}
												<li><a href="{url="app=core&module=members&controller=profile&id={$member->member_id}&do=reputation&type={$key}&change_section=1" seoTemplate="profile_reputation" seoTitle="$member->members_seo_name"}" class="ipsSideMenu_item {{if $currentType == $key}}ipsSideMenu_itemActive{{endif}}">{lang="{$class::$title}_pl"}</a></li>
											{{endforeach}}
										</ul>
									{{endforeach}}
								</div>
							</div>
						</div>
					</div>
				</div>
			</aside>
			<section class='ipsProfile__main ipsBox ipsPull'>
				<h2 class='ipsBox__header'>{lang="replog_title"}</h2>
				<div id='elUserReputation'>
					{template="userReputationSection" group="profile" app="core" params="$table"}
				</div>
			</section>
		</div>
{{if !\IPS\Request::i()->isAjax()}}
	</div>
</div>
{{endif}}

{{if \count( $rows )}}
	{{foreach $rows as $row}}
		{{$reaction = \IPS\Content\Reaction::load( $row->rep_reaction );}}
		<li class='ipsData__item'>		
			{{if !\IPS\Content\Reaction::isLikeMode()}}
				<div>
					<img src='{file="$reaction->_icon" extension="core_Reaction"}' alt='{$reaction->_title}' width='20' height='20' data-ipsTooltip title='{$reaction->_title}'>
				</div>
			{{endif}}
			<div class='ipsData__icon i-align-self_center'>
				{{if $row->rep_member == \IPS\Request::i()->id}}
					{template="userPhoto" group="global" app="core" params="\IPS\Member::load( \IPS\Request::i()->id ), 'mini'"}
				{{else}}
					{template="userPhoto" group="global" app="core" params="\IPS\Member::load( $row->rep_member ), 'mini'"}
				{{endif}}
			</div>
			<div class='ipsData__main'>
				<div class='ipsData__title'>
					<span class=''>
						{{if !\IPS\Content\Reaction::isLikeMode()}}
							{{if $row instanceof \IPS\Content\Comment or $row instanceof \IPS\Content\Review}}
								{{$item = $row->item();}}
								{{if $row->rep_member != \IPS\Request::i()->id}}
									{lang="replog_rate_comment_received" htmlsprintf="\IPS\Member::load( $row->rep_member_received )->link(), \IPS\Member::load( $row->rep_member )->link()"} <a href='{$item->url()}'>{$item->mapped('title')}</a>
								{{else}}
									{{if $row->rep_member_received}}
										{lang="replog_rate_comment_gave" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), \IPS\Member::load( $row->rep_member_received )->link()"} <a href='{$item->url()}'>{$item->mapped('title')}</a>
									{{else}}
										{lang="replog_rate_comment_gave_no_recipient" htmlsprintf="\IPS\Member::load( $row->rep_member )->link()"} <a href='{$item->url()}'>{$item->mapped('title')}</a>
									{{endif}}
								{{endif}}
							{{else}}
								{{if $row->rep_member != \IPS\Request::i()->id}}
									{lang="replog_rate_item_received" htmlsprintf="\IPS\Member::load( $row->rep_member_received )->link(), \IPS\Member::load( $row->rep_member )->link(), $row->indefiniteArticle()"} <a href='{$row->url()}'>{$row->mapped('title')}</a>
								{{else}}
									{{if $row->rep_member_received}}
										{lang="replog_rate_item_gave" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), \IPS\Member::load( $row->rep_member_received )->link(), $row->indefiniteArticle()"} <a href='{$row->url()}'>{$row->mapped('title')}</a>
									{{else}}
										{lang="replog_rate_item_gave_no_recipient" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), $row->indefiniteArticle()"} <a href='{$row->url()}'>{$row->mapped('title')}</a>
									{{endif}}
								{{endif}}
							{{endif}}
						{{else}}
							<strong>
								{{if $row instanceof \IPS\Content\Comment or $row instanceof \IPS\Content\Review}}
									{{$item = $row->item();}}
									{{if $row->rep_member_received}}
										{lang="replog_like_comment" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), $row->url(), $row->indefiniteArticle(), \IPS\Member::load( $row->rep_member_received )->link()"} <a href='{$item->url()}'>{$item->mapped('title')}</a>
									{{else}}
										{lang="replog_like_comment_no_recipient" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), $row->url(), $row->indefiniteArticle()"} <a href='{$item->url()}'>{$item->mapped('title')}</a>
									{{endif}}
								{{else}}
									{{if $row->rep_member_received}}
										{lang="replog_like_item" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), $row->indefiniteArticle(), \IPS\Member::load( $row->rep_member_received )->link()"} <a href='{$row->url()}'>{$row->mapped('title')}</a>
									{{else}}
										{lang="replog_like_item_no_recipient" htmlsprintf="\IPS\Member::load( $row->rep_member )->link(), $row->indefiniteArticle()"} <a href='{$row->url()}'>{$row->mapped('title')}</a>
									{{endif}}
								{{endif}}
							</strong>
						{{endif}}
					</span>
					<span class='i-color_soft'>&nbsp;&nbsp;{datetime="$row->rep_date"}</span>
				</div>
				{{if $result = $row->truncated()}}
					<div class='ipsData__desc ipsRichText ipsTruncate_2'>
						{$result|raw}
					</div>
				{{endif}}
			</div>
		</li>
	{{endforeach}}
{{endif}}

{{if \count( $rows )}}
	{{foreach $rows as $row}}
		<li class='ipsData__item'>		
			<div class='ipsData__icon'>
				{template="userPhoto" group="global" app="core" params="\IPS\Member::load( \IPS\Request::i()->id ), 'mini'"}
			</div>
			<div class='ipsData__main'>
				<div class='ipsData__title'>
					<span>
						{lang="solution_headline" sprintf="\IPS\Member::load( \IPS\Request::i()->id )->name, $row->url(), \IPS\Member::loggedIn()->language()->addToStack( $row::$title . '_lc' ), $row->item()->url(), $row->item()->mapped('title')"}
					</span>
					<span class='i-color_soft'>&nbsp;&nbsp;{datetime="$row->solved_date"}</span>
				</div>
				{{if $result = $row->truncated()}}
					<div class='ipsRichText ipsData__desc ipsTruncate_2'>
						{$result|raw}
					</div>
				{{endif}}
			</div>
		</li>
	{{endforeach}}
{{endif}}

{{$pinnedTags = $table->getPinnedTagItems();}}
<header class='ipsPageHeader ipsPageHeader--promote-public-table ipsBox'>
	<h1 class='ipsPageHeader__title'>{lang="promote_table_header"}</h1>
	<p class='ipsPageHeader__desc'>{lang="promote_table_header_desc"}</p>
</header>

<div class='ipsBox ipsBox--promotePublicTable ipsPull'>
	{{if $table->pages > 1}}
		<div class="ipsButtonBar ipsButtonBar--top">
			<div class="ipsButtonBar__pagination" data-role="tablePagination">
				{template="pagination" group="global" app="core" location="global" params="$table->baseUrl, $table->pages, $table->page, $table->limit, TRUE, $table->getPaginationKey()"}
			</div>
		</div>
	{{endif}}

	{{if \is_array( $rows ) AND \count( $rows )}}
		<div class='{{foreach $table->classes as $class}}{$class} {{endforeach}}' id='elTable_{$table->uniqueId}' data-role="tableRows">
			<i-data>
				<div class='ipsData ipsData--grid ipsData--featured-content'>
					{template="$table->rowsTemplate[1]" params="$table, $headers, $rows" object="$table->rowsTemplate[0]"}
				</div>
			</i-data>
		</div>
	{{elseif ! $pinnedTags}}
		<p class='ipsEmptyMessage'>{lang="promote_table_none"}</p>
	{{endif}}

	{{if $table->pages > 1}}
		<div class="ipsButtonBar ipsButtonBar--bottom">
			<div class="ipsButtonBar__pagination" data-role="tablePagination">
				{template="pagination" group="global" app="core" location="global" params="$table->baseUrl, $table->pages, $table->page, $table->limit, TRUE, $table->getPaginationKey()"}
			</div>
		</div>
	{{endif}}
	{{if $pinnedTags}}
	    {{foreach $pinnedTags as $row}}
	        {{$tag = $row['tag'];}}
            {{if $pinnedItems = $tag->getPinnedItems()}}
                <div id='elTagPinnedItems'>
                    <h3 class="i-color_soft i-text-transform_uppercase i-font-weight_600 i-font-size_-2 i-padding-block_2 i-padding-inline_3 i-background_2 i-border-top_3 i-border-bottom_3">
                        <a href="{$tag->url()}">{lang="tags__pinned_entries" sprintf="$tag->text"}</span></a>
                    </h3>
                    <i-data>
                        <ol class='ipsData ipsData--grid ipsData--carousel' id="tags-pinned-carousel" tabindex="0">
                            {{foreach $pinnedItems as $pinned}}
                                {template="pinnedItem" app="core" group="tags" location="front" params="$pinned, $tag, false"}
                            {{endforeach}}
                        </ol>
						{template="carouselNavigation" group="global" app="core" params="'tags-pinned-carousel'"}
                    </i-data>
                </div>
            {{endif}}
        {{endforeach}}
	{{endif}}
</div>

{{if \count( $rows )}} 
	{{foreach $rows as $item}}
		{{if ( $item->object() instanceof \IPS\Content and  $item->object()->hidden() === 0 ) or ( ! $item->object() instanceof \IPS\Content )}}
			{template="promotePublicTableRow" params="$item" app="core" group="promote"}
		{{endif}}
	{{endforeach}}
{{endif}}

{{$filter = \IPS\Request::i()->filter;}}
{{if $currentStatus === -1}}
	<span class='ipsBadge ipsBadge--negative'>{lang="$text"}</span>
{{elseif ( $ad['ad_end'] AND $ad['ad_end'] < time() ) OR ( $ad['ad_maximum_unit'] == 'i' AND $ad['ad_maximum_value'] > -1 AND $ad['ad_impressions'] >= $ad['ad_maximum_value'] ) OR ( $ad['ad_maximum_unit'] == 'c' AND $ad['ad_maximum_value'] > -1 AND $ad['ad_clicks'] >= $ad['ad_maximum_value'] ) }}
	<span class='ipsBadge ipsBadge--neutral' data-ipsTooltip title='{lang="ad_nostatus_change"}'>{lang="disabled"}</span>
{{else}}
	<span data-ipsStatusToggle>
		<a href="{url="app=core&module=promotion&controller=advertisements&do=toggle&id=$id&status=0&filter={$filter}" csrf="true"}" data-ipsTooltip title="{lang="set_inactive"}" {{if $currentStatus !== 1}}hidden{{endif}} data-state="enabled">
			<span class='ipsBadge ipsBadge--positive'>
				{lang="enabled"}
			</span>
		</a>
		<a href="{url="app=core&module=promotion&controller=advertisements&do=toggle&id=$id&status=1&filter={$filter}" csrf="true"}" data-ipsTooltip title="{lang="set_active"}" {{if $currentStatus !== 0}}hidden{{endif}} data-state="disabled">
			<span class='ipsBadge ipsBadge--negative'>
				{lang="disabled"}
			</span>
		</a>
	</span>
{{endif}}

{{if ($blocks = \IPS\core\Statistics\Chart::getSavedBlocks()) AND !empty($blocks)}}
<div data-role="savedOverviewStats" data-controller='core.admin.stats.overview' data-url='?app=core&module=stats&controller=overview&do=loadBlock'>
    <div class='ipsBox i-padding_3 i-margin-bottom_2 i-flex i-flex-wrap_wrap i-align-items_center i-gap_2'>
        {{if ($apps = \IPS\core\Statistics\Chart::getAppsToFilterBy()) and count( $apps ) > 1}}
            <ul class='ipsList ipsList--inline i-flex_11 i-margin-block_1'>
                <li>
                    <strong>{lang="stats_show_c"}</strong>
                </li>

                {{foreach \IPS\Application::applications() as $key => $app}}
                    {{if isset( $apps[ $key ] )}}
                        <li>
                            <label for='toggle_app_{$app->directory}'>
                                <input
                                        type='checkbox'
                                        id='toggle_app_{$app->directory}'
                                        name='toggle_app_{$app->directory}'
                                        data-action='toggleApp'
                                        data-toggledApp='{$app->directory}'
                                        checked
                                >
                                {$app->_title}
                            </label>
                        </li>
                    {{endif}}
                {{endforeach}}
            </ul>
        {{else}}
            <div class='i-flex_11'></div>
        {{endif}}
    </div>
    <hr class='ipsHr' />
    <div class='cStatsGrid'>
        <div class='ipsGrid i-basis_340'>
            {{foreach $blocks as $block}}
                {template="overviewStatisticBlock" group="reports" location="admin" app="core" params="$block['blockKey'], $block['subblock'], $block['details'], $block['saved_stat_id']"}
            {{endforeach}}
        </div>
    </div>
