										</a>
									</li>
								{{endforeach}}
							</ul>
						{{endif}}

						{{$countOne = 0;}}
						{{if $totalCustomFields > 1}}
							{{foreach $elements[''] as $id => $element}}
								{{if \in_array( $id, $exclude )}}
									{{continue;}}
								{{endif}}
								{{$countOne++;}}

								<hr class='ipsHr'>
								<h3 class="ipsSideMenu__title">{lang="$id"}</h3>
								<div class='ipsFieldRow--fullWidth'>
									{$element->html()|raw}
								</div>

								{{if $countOne >= $perCol}}
									{{break;}}
								{{endif}}
							{{endforeach}}
						{{endif}}
					</div>
					<div class='ipsSpanGrid__6'>
						{{$countTwo = 0;}}
						{{foreach $elements[''] as $id => $element}}
							{{if \in_array( $id, $exclude )}}
								{{continue;}}
							{{endif}}
							{{$countTwo++;}}

							{{if $countTwo <= $countOne}}
								{{continue;}}
							{{endif}}

							{{if $countTwo !== ( $countOne + 1 )}}
								<!-- HR except for first item -->
								<hr class='ipsHr'>
							{{endif}}

							<h3 class="ipsSideMenu__title">{lang="$id"}</h3>
							<div class='ipsFieldRow--fullWidth'>
								{$element->html()|raw}
							</div>

							{{if $countTwo >= $perCol}}
								{{break;}}
							{{endif}}
						{{endforeach}}
					</div>			
				</div>			
			</div>
		</div>
	</div>
