	            {{$currentUrl = base64_encode((string) request.url());}}
	            {{$status = (int) !\IPS\Member::loggedIn()->optionalCookiesAllowed;}}
	            <a href='{url="app=core&module=system&controller=cookies&do=cookieConsentToggle&ref={$currentUrl}&status={$status}" csrf="true"}' rel='nofollow'>
					<span class="ipsSwitch i-font-size_3 i-margin-start_2" {{if !$status}}data-checked{{endif}}></span>
					<span class="ipsInvisible">
						{{if !$status}}{lang="cookies_optional_toggle_enabled"}{{else}}{lang="cookies_optional_toggle_disabled"}{{endif}}
					</span>
	            </a>
	        </h3>
	        <p>{lang="cookies_optional_desc"}</p>
	    {{endif}}
		{{if \IPS\Member::loggedIn()->language()->checkKeyExists('cookie_3rdpartynotice_value') AND !empty( \IPS\Member::loggedIn()->language()->get('cookie_3rdpartynotice_value') )}}
			<h3>{lang="cookies_third_party"}</h3>
			{lang="cookie_3rdpartynotice_value"}
		{{endif}}
		<h3>{lang="cookies_change_header"}</h3>
		<p>{lang="cookies_change_text"}</p>
    </div>
</div>

{{if !\IPS\Request::i()->isAjax()}}
	{template="pageHeader" group="global" app="core" params="\IPS\Member::loggedIn()->language()->addToStack('menu_followed_content')"}
	<div data-role="profileContent">
{{endif}}
		<div class="ipsColumns ipsColumns--lines ipsColumns--followed-content ipsBox ipsBox--followedContent ipsPull">
			<aside class="ipsColumns__secondary i-basis_340 i-padding_3">
				<div class="ipsSideMenu" data-ipsTabBar data-ipsTabBar-contentArea='#elFollowedContent' data-ipsTabBar-itemselector=".ipsSideMenu_item" data-ipsTabBar-activeClass="ipsSideMenu_itemActive" data-ipsSideMenu>
					<h3 class="ipsSideMenu__view">
						<a href="#user_content" data-action="openSideMenu"><i class="fa-solid fa-bars" aria-hidden="true"></i><span>{lang="user_content_type"}</span></a>
					</h3>
					<div class="ipsSideMenu__menu">
						{{foreach $types as $app => $_types}}
							{{if $app != "core"}}
								<h4 class='ipsSideMenu__subTitle'>{lang="module__{$app}"}</h4>
								<ul class="ipsSideMenu__list">
									{{foreach $_types as $key => $class}}
										<li><a href="{$table->baseUrl->setQueryString( array( 'type' => $key, 'change_section' => 1 ) )->setPage( 'page', 1 )}" class="ipsSideMenu_item {{if $currentType == $key}}ipsSideMenu_itemActive{{endif}}" {{if $currentType == $key}}aria-selected="true"{{endif}}>{{if is_subclass_of( $class, 'IPS\Content\Item' )}}{lang="{$class::$title}_pl"}{{else}}{lang="{$class::$nodeTitle}"}{{endif}}</a></li>	
									{{endforeach}}
								</ul>
							{{endif}}
						{{endforeach}}
						<h4 class='ipsSideMenu__subTitle'>{lang="other"}</h4>
						<ul class='ipsSideMenu__list'>
							<li><a href="{$table->baseUrl->setQueryString( array( 'type' => 'core_member', 'change_section' => 1 ) )->setPage( 'page', 1 )}" class="ipsSideMenu_item {{if $currentType == 'core_member'}}ipsSideMenu_itemActive{{endif}}">{lang="members"}</a></li>
							{{if \IPS\Settings::i()->tags_enabled}}
							<li><a href="{$table->baseUrl->setQueryString( array( 'type' => 'core_tag', 'change_section' => 1 ) )->setPage( 'page', 1 )}" class="ipsSideMenu_item {{if $currentType == 'core_tag'}}ipsSideMenu_itemActive{{endif}}">{lang="tags"}</a></li>
							{{endif}}
						</ul>
					</div>
				</div>
			</aside>
			<section class='ipsColumns__primary' id='elFollowedContent'>
				{template="followedContentSection" group="system" app="core" params="$types, $currentAppModule, $currentType, (string) $table"}
			</section>
		</div>
{{if !\IPS\Request::i()->isAjax()}}
	</div>
{{endif}}

{{foreach $rows as $row}}
	{{$loadedMember = \IPS\Member::load( $row->member_id );}}
	<li class='ipsData__item' data-controller='core.front.system.manageFollowed' data-followID='{$row->_followData['follow_area']}-{$row->_followData['follow_rel_id']}'>
		<div class='ipsData__icon'>
			{template="userPhoto" group="global" app="core" params="$loadedMember, 'small'"}
		</div>
		<div class='ipsData__content'>
			<div class='ipsData__main'>
				<div class='ipsData__title'>
					<h3>{$loadedMember->link( NULL, FALSE )|raw}</h3> {{if $loadedMember->isOnline()}}<i class="ipsOnline" data-ipsTooltip title='{lang="online_now" sprintf="$row->name"}' aria-hidden="true"></i>{{endif}}
				</div>
				<p class='ipsData__desc ipsData__desc--all'>
					{expression="\IPS\Member\Group::load( $row->member_group_id )->formattedName" raw="true"}
					{{if $loadedMember->last_activity}}
						&middot; {lang="members_last_visit"}: {datetime="$loadedMember->last_activity"}
					{{endif}}
				</p>
				<ul class="ipsList ipsList--inline i-row-gap_0 i-margin-top_1 i-font-weight_500">
					<li title='{lang="follow_when"}' data-role='followDate' hidden><i class='fa-regular fa-clock' aria-hidden="true"></i> {datetime="$row->_followData['follow_added']"}</li>
					<li title='{lang="follow_how"}' data-role='followFrequency'>
						{{if $row->_followData['follow_notify_freq'] == 'none'}}
							<i class='fa-regular fa-bell-slash' aria-hidden="true"></i>
						{{else}}
							<i class='fa-regular fa-bell' aria-hidden="true"></i>
						{{endif}} {lang="follow_freq_{$row->_followData['follow_notify_freq']}"}
					</li>
					<li data-role='followAnonymous' {{if !$row->_followData['follow_is_anon']}}hidden{{endif}}><i class="fa-regular fa-eye-slash" aria-hidden="true"></i> {lang="follow_is_anon"}</li>
				</ul>
			</div>
			<div class='cFollowedContent_manage'>
				{template="manageFollow" group="system" app="core" params="$row->_followData['follow_app'], $row->_followData['follow_area'], $row->_followData['follow_rel_id']"}
			</div>
		</div>

		{{if $table->canModerate()}}
			<label class="ipsData__mod">
				<span class="ipsInvisible">{lang="mod_checkbox"}</span>
				<input type='checkbox' data-role='moderation' name="moderate[{$row->member_id}]" data-actions="{expression="implode( ' ', $table->multimodActions( $row ) )"}" data-state='' class="ipsInput ipsInput--toggle">
			</label>
		{{endif}}
	</li>
{{endforeach}}

