{template="pageHeader" group="global" params="\IPS\Member::loggedIn()->language()->addToStack('unsubscribed')"}
<div class='ipsBox ipsBox--padding'>
	{{if $action === 'markSolved'}}{lang="unsubscribed_solved_desc"}{{elseif $action === 'expertNudge'}}{lang="unsubscribed_expert_nudge_desc"}{{else}}{lang="unsubscribed_desc"}{{endif}}
</div>

{{if \IPS\CIC AND \IPS\Cicloud\isManaged()}}
	<h2 class="ipsTitle ipsTitle--h3 i-text-align_center i-padding_3">{lang="managed_upgrade_allow_head" sprintf="\IPS\Cicloud\managedSupportEmail()"}</h2>
{{endif}}
{{foreach $elements as $collection}}
	{{foreach $collection as $input}}
		{{if \count( $input->options['options'] ) > 1}}
			<div class="i-background_3 i-padding_3">
				<div class="i-margin-bottom_1">{lang="upgrade_choose_version"}</div>
		{{endif}}
		{{foreach $input->options['options'] as $longVersion => $humanVersion}}
			<form accept-charset='utf-8' action="{$action}" method="post">
				<input type="hidden" name="{$id}_submitted" value="1">
				{{foreach $hiddenValues as $k => $v}}
					{{if \is_array($v)}}
						{{foreach $v as $_k => $_v}}
							<input type="hidden" name="{$k}[{$_k}]" value="{$_v}">
						{{endforeach}}
					{{else}}
						<input type="hidden" name="{$k}" value="{$v}">
					{{endif}}
				{{endforeach}}
				<input type="hidden" name="version" value="{$longVersion}">

				{{if \count( $input->options['options'] ) > 1}}
					<div class="ipsBox i-margin-bottom_1">
						{{if $humanVersion === \IPS\Application::load('core')->version}}
							<h2 class="ipsBox__header">{lang="upgrade_check_patches"}</h2>
						{{else}}
							<h2 class='ipsBox__header'>{$humanVersion}</h2>
						{{endif}}
						<div class="i-padding_3 ipsRichText ipsRichText--release-notes">
							{{if $humanVersion === \IPS\Application::load('core')->version}}
								{{if $input->options['_details'][ $longVersion ]['releasenotes']}}
									<ul>
										{{foreach $input->options['_details'][ $longVersion ]['changes'] as $issue}}
											<li>{$issue}</li>
										{{endforeach}}
									</ul>
								{{endif}}
							{{else}}
								{{if $input->options['_details'][ $longVersion ]['security']}}
									<p><strong class="i-color_warning">{lang="this_is_a_security_update"}</strong></p>
								{{endif}}
								{{if $input->options['_details'][ $longVersion ]['releasenotes']}}
									<div>{$input->options['_details'][ $longVersion ]['releasenotes']|raw}</div>
								{{endif}}
							{{endif}}
							<input type="submit" class="ipsButton ipsButton--primary" value="{{if \IPS\CIC}}{lang="start_upgrade"}{{else}}{lang="continue"}{{endif}}">
							{{if $input->options['_details'][ $longVersion ]['updateurl']}}
								<a href='{$input->options['_details'][ $longVersion ]['updateurl']}' target="_blank" rel="noopener" class='ipsButton ipsButton--secondary ipsButton--small'>{lang="dashboard_version_moreinfo"}</a>
							{{endif}}
						</div>
					</div>
				{{else}}
					<div class="i-background_1 i-padding_3 ipsRichText ipsRichText--release-notes">
						{{if $humanVersion === \IPS\Application::load('core')->version}}
							<h2>{lang="upgrade_check_patches"}</h2>
							{{if $input->options['_details'][ $longVersion ]['releasenotes']}}
								<ul>
									{{foreach $input->options['_details'][ $longVersion ]['changes'] as $issue}}
										<li>{$issue}</li>
									{{endforeach}}
								</ul>
							{{endif}}
						{{else}}
							<h2>{lang="dashboard_version_info" sprintf="$humanVersion"}</h2>
							{{if $input->options['_details'][ $longVersion ]['security']}}
								<p><strong class="i-color_warning">{lang="this_is_a_security_update"}</strong></p>
							{{endif}}
							{{if $input->options['_details'][ $longVersion ]['releasenotes']}}
								<div>{$input->options['_details'][ $longVersion ]['releasenotes']|raw}</div>
							{{endif}}
						{{endif}}
					</div>
					<div class="ipsSubmitRow">
						<input type="submit" class="ipsButton ipsButton--primary" value="{{if \IPS\CIC}}{lang="start_upgrade"}{{else}}{lang="continue"}{{endif}}">
						{{if $input->options['_details'][ $longVersion ]['updateurl']}}
							<a href='{$input->options['_details'][ $longVersion ]['updateurl']}' target="_blank" rel="noopener" class='ipsButton ipsButton--secondary ipsButton--small'>{lang="dashboard_version_moreinfo"}</a>
						{{endif}}
					</div>
				{{endif}}
			</form>
		{{endforeach}}
		{{if \count( $input->options['options'] ) > 1}}
			</div>
		{{endif}}
	{{endforeach}}
{{endforeach}}

{{foreach $rows as $row}}
	<li class="ipsData__item {{if method_exists( $row, 'tableClass' ) && $row->tableClass()}}ipsData__item--{$row->tableClass()}{{endif}} ">
		<div class='ipsData__icon'>
			<a href="{url="app=core&module=system&controller=warnings&do=view&id={$row->member}&w={$row->id}" seoTemplate="warn_view" seoTitle="\IPS\Member::load( $row->member )->members_seo_name"}" data-ipsDialog data-ipsDialog-size='narrow' data-ipsTooltip title='{lang="wan_action_points" pluralize="$row->points"}'>
                <span class="ipsWarningPoints {{if $row->expire_date == 0}}ipsWarningPoints--removed{{endif}}">{$row->points}</span>
			</a>
		</div>
		<div class='ipsData__content'>
			<div class='ipsData__main'>
				<h4 class='ipsData__title'>				
					<a href='{$row->url()}' title='{lang="view_announcement"}' {{if $row->tableHoverUrl}}data-ipsHover{{endif}}>
						{{if $row->mapped('title')}}{$row->mapped('title')}{{else}}<em class="i-color_soft">{lang="content_deleted"}</em>{{endif}}
					</a>
				</h4>
				<ul class='ipsList ipsList--sep'>
					{{if \IPS\Settings::i()->warnings_acknowledge}}
						<li>
							{{if $row->acknowledged}}
								<strong class='i-color_positive'><i class='fa-solid fa-check-circle' aria-hidden="true"></i> {lang="warning_acknowledged"}</strong>
							{{else}}
								<strong class='i-color_soft'><i class='fa-regular fa-circle' aria-hidden="true"></i> {lang="warning_not_acknowledged"}</strong>
							{{endif}}
						</li>
					{{endif}}
					<li class='i-color_soft'>{lang="warned_by" sprintf="\IPS\Member::load( $row->moderator )->name"}{datetime="$row->__get( $row::$databaseColumnMap['date'] )"}
						{{if $row->expire_date > 0}}<em><strong>({lang="warning_expires" sprintf="\IPS\DateTime::ts( $row->expire_date )"})</em></strong>{{endif}}
						{{if $row->expire_date == 0}}
						<em><strong>{lang="warning_no_longer_active"}{{if $row->removed_on}} {lang="warning_expired_on" sprintf="\IPS\DateTime::ts( $row->removed_on )->relative()"}{{endif}}</em></strong>
						{{endif}}
					</li>
				</ul>
				{{if $row->note_member or ($row->note_mods and member.modPermission('mod_see_warn'))}}
					<div class='ipsFluid i-margin-top_3'>
						{{if $row->note_member}}
							<div>
								<strong class="i-color_hard i-font-weight_500">{lang="warn_member_note"}:</strong>
								<div class="ipsRichText">{$row->note_member|raw}</div>
							</div>
						{{endif}}
						{{if $row->note_mods and member.modPermission('mod_see_warn')}}
							<div>
								<strong class="i-color_hard i-font-weight_500">{lang="warn_mod_note"}:</strong>
								<div class="ipsRichText">{$row->note_mods|raw}</div>
							</div>
						{{endif}}
					</div>
				{{endif}}
			</div>
			{{if $row->canDelete()}}
				<div>
					<a href="{$row->url('delete')->csrf()}" title='{lang="revoke_this_warning"}' data-action="revoke" class='ipsButton ipsButton--small ipsButton--inherit' data-ipsDialog data-ipsDialog-title='{lang="revoke_this_warning"}' data-ipsDialog-size='medium'><i class="fa-solid fa-rotate-left" aria-hidden="true"></i> {lang="revoke_this_warning"}</a>
				</div>
			{{endif}}
		</div>
		{{if $table->canModerate()}}
			<label class="ipsData__mod">
				<span class="ipsInvisible">{lang="mod_checkbox"}</span>
				<input type='checkbox' data-role='moderation' name="moderate[{$row->id}]" data-actions="{expression="implode( ' ', $table->multimodActions( $row ) )"}" data-state='{{if !$row->active}}hidden{{endif}}' class="ipsInput ipsInput--toggle">
			</label>
		{{endif}}
	</li>
{{endforeach}}

{{foreach $rows as $row}}
	{{$idField = $row::$databaseColumnId;}}
	<!-- v5 todo: This is used in profiles, when viewing comment entries (ie. Event Comments) -->
	<li class='ipsData__item' data-rowID='{$row->$idField}'>
		<article id='elComment_{$row->$idField}' class='ipsEntry ipsEntry--simple ipsEntry--profile-activity-comments {{if \IPS\IPS::classUsesTrait( $row, 'IPS\Content\Reactable' ) and $row->isHighlighted()}}ipsEntry--popular{{endif}} {{if $row->hidden()}}ipsModerated{{endif}}'>
			<div id='comment-{$row->$idField}_wrap' class='ipsEntry__content js-ipsEntry__content'>	
				<header class='ipsEntry__header'>
					<div class="ipsEntry__header-align">
						<div class="i-flex_11">
							{$row->contentTableHeader()|raw}
						</div>
						<ul class='i-flex i-align-items_center i-gap_3'>
							{{if $row->canReportOrRevoke() === TRUE}}
								<li><a href='{$row->url('report')}' {{if member.member_id or \IPS\Helpers\Form\Captcha::supportsModal()}}data-ipsDialog data-ipsDialog-remoteSubmit data-ipsDialog-size='medium' data-ipsDialog-flashMessage='{lang="report_submit_success"}' data-ipsDialog-title="{lang="report_reply"}"{{endif}} data-action='reportComment' title='{lang="report_content"}' class='i-color_soft'>{lang="report"}</a></li>
							{{endif}}
							{{if $table->canModerate() and ( $row->canSplit() or ( $row->hidden() === -1 AND $row->canUnhide() ) or ( $row->hidden() === 1 AND $row->canUnhide() ) or $row->canDelete() )}}
								<li>
									<input type="checkbox" name="moderate[{$row->$idField}]" value="1" data-role="moderation" data-actions="{{if $row->canSplit()}}split{{endif}} {{if $row->hidden() === -1 AND $row->canUnhide()}}unhide{{elseif $row->hidden() === 1 AND $row->canUnhide()}}approve{{elseif $row->canHide()}}hide{{endif}} {{if $row->canDelete()}}delete{{endif}}" data-state='{{if $row->tableStates()}}{$row->tableStates()}{{endif}}' class="ipsInput ipsInput--toggle">
								</li>
							{{endif}}
						</ul>
					</div>
				</header>
				<div class='ipsEntry__post'>
					{{if \IPS\Request::i()->controller == 'activity'}}
						<div class='ipsPhotoPanel ipsPhotoPanel--mini'>
							{template="userPhoto" group="global" app="core" params="$row->author(), 'mini'"}
							<div class="ipsPhotoPanel__text">
								<h3 class="ipsPhotoPanel__primary">{$row->author()->link( NULL, NULL, \IPS\IPS::classUsesTrait( $row, 'IPS\Content\Anonymous' ) ? $row->isAnonymous() : FALSE )|raw}</h3>
					{{endif}}
					<p class="ipsPhotoPanel__secondary">
						<a href='{$row->url( 'find' )}'>{$row->dateLine()|raw}</a>
						{{if $row->editLine()}}
							&middot; {$row->editLine()|raw}
						{{endif}}
						{{if $row->hidden()}}
							&middot; {$row->hiddenBlurb()}
						{{endif}}							
					</p>
					{{if \IPS\Request::i()->controller == 'activity'}}
							</div>
						</div>
					{{endif}}
					<div>
						{{if \IPS\IPS::classUsesTrait( $row, 'IPS\Content\Reactable' ) and $row->isHighlighted()}}
							<ul class='ipsBadges'>
								<li><span class='ipsBadge ipsBadge--popular'>{lang="this_is_a_popular_post"}</span></li>
							</ul>
						{{endif}}
					</div>
					<div data-role='commentContent' class='ipsRichText i-margin-top_3' data-controller='core.front.core.lightboxedImages'>
						{{if $row->hidden() === 1 && $row->author()->member_id == \IPS\Member::loggedIn()->member_id}}
							<strong class='i-color_warning'><i class='fa-solid fa-circle-info' aria-hidden="true"></i> {lang="comment_awaiting_approval"}</strong>
						{{endif}}
						{$row->content()|raw}
					</div>
				</div>
				{{if $row->hidden() !== 1 && \IPS\IPS::classUsesTrait( $row, 'IPS\Content\Reactable' ) and settings.reputation_enabled}}
					<div class='ipsEntry__footer'>
						{template="reputation" group="global" app="core" params="$row"}
					</div>
				{{endif}}
			</div>
		</article>
	</li>
{{endforeach}}

{{foreach $rows as $row}}
	{{$contentItemClass = $row::$contentItemClass;}}
	<li class="ipsData__item {{if method_exists( $row, 'tableClass' ) && $row->tableClass()}}ipsData__item--{$row->tableClass()}{{endif}}" data-controller='core.front.system.manageFollowed' data-followID='{$row->_followData['follow_area']}-{$row->_followData['follow_rel_id']}'{{if $contentItemClass::containerUnread( $row )}}data-ips-unread{{else}}data-ips-read{{endif}}>
		<div class='ipsData__content'>
			<div class='ipsData__main'>
				<h4 class='ipsData__title'>
					{{if $row->_locked}}
						<i class="fa-solid fa-lock" aria-hidden="true"></i>
					{{endif}}
					<a href='{$row->url()}'>{$row->_title}</a>
				</h4>
				<div class='ipsData__desc ipsTruncate_2'>{$row->_description}</div>
				<ul class='ipsList ipsList--inline i-color_soft'>
					{{if $row->_items}}
						<li>{lang="node_content_items" pluralize="$row->_items"}</li>
					{{endif}}
					{{if $row->_comments}}
						<li>{lang="node_content_comments" pluralize="$row->_comments"}</li>
					{{endif}}
					{{if $row->_reviews}}
						<li>{lang="node_content_reviews" pluralize="$row->_reviews"}</li>
					{{endif}}
				</ul>
				<ul class="ipsList ipsList--inline i-row-gap_0 i-margin-top_1 i-font-weight_500">
					<li title='{lang="follow_when"}' data-role='followDate' hidden><i class='fa-regular fa-clock' aria-hidden="true"></i> {datetime="$row->_followData['follow_added']"}</li>
					<li title='{lang="follow_how"}' data-role='followFrequency'>
						{{if $row->_followData['follow_notify_freq'] == 'none'}}
							<i class='fa-regular fa-bell-slash' aria-hidden="true"></i>
						{{else}}
							<i class='fa-regular fa-bell' aria-hidden="true"></i>
						{{endif}} {lang="follow_freq_{$row->_followData['follow_notify_freq']}"}
					</li>
					<li data-role='followAnonymous' {{if !$row->_followData['follow_is_anon']}}hidden{{endif}}><i class="fa-regular fa-eye-slash" aria-hidden="true"></i> {lang="follow_is_anon"}</li>
				</ul>
			</div>
			<div class='cFollowedContent_manage'>
				{template="manageFollow" group="system" app="core" params="$row->_followData['follow_app'], $row->_followData['follow_area'], $row->_followData['follow_rel_id']"}
			</div>
		</div>

		{{if $table->canModerate()}}
			<label class="ipsData__mod">
				<span class="ipsInvisible">{lang="mod_checkbox"}</span>
				<input type='checkbox' data-role='moderation' name="moderate[{$row->_id}]" data-actions="{expression="implode( ' ', $table->multimodActions( $row ) )"}" data-state='' class="ipsInput ipsInput--toggle">
			</label>
		{{endif}}
	</li>
{{endforeach}}

{{if \count( $rows )}}
	{{foreach $rows as $row}}
	{{$idField = $row::$databaseColumnId;}}
		<li class="ipsData__item {{if method_exists( $row, 'tableClass' ) && $row->tableClass()}}ipsData__item--{$row->tableClass()}{{endif}} {{if $row->hidden()}}ipsModerated{{endif}}" data-controller='core.front.system.manageFollowed' data-followID='{$row->_followData['follow_area']}-{$row->_followData['follow_rel_id']}' {{if $row->unread()}}data-ips-unread{{else}}data-ips-read{{endif}}>
			<div class='ipsData__content'>
				<div class='ipsData__main'>
					<div class='ipsData__title'>
						<div class='ipsBadges'>
							{{if $row->mapped('locked')}}
								<i class="fa-solid fa-lock" aria-hidden="true"></i>
							{{endif}}

							{{foreach $row->badges() as $badge}}{$badge|raw}{{endforeach}}

							{{if $row->prefix()}}
								{template="prefix" group="global" app="core" params="$row->prefix( TRUE ), $row->prefix()"}
							{{endif}}
						</div>
						<h4>
							<a href='{$row->url()}'>
								{{if $row->mapped('title')}}{$row->mapped('title')}{{else}}<em class="i-color_soft">{lang="content_deleted"}</em>{{endif}}
							</a>
						</h4>
					</div>
					{{if method_exists( $row, 'tableDescription' )}}
						<div class='ipsData__desc'>
							{$row->tableDescription()|raw}
						</div>
					{{else}}
						<div class='ipsData__meta'>
	                        {lang="byline_name_date" htmlsprintf="$row->author()->link( $row->warningRef() ), \IPS\DateTime::ts( $row->__get( $row::$databaseColumnMap['date'] ) )->html(TRUE)"}
							{lang="in"} <a href="{$row->container()->url()}">{$row->container()->_title}</a>
						</div>
					{{endif}}
					<ul class="ipsList ipsList--inline i-row-gap_0 i-margin-top_1 i-font-weight_500">
						<li title='{lang="follow_when"}' data-role='followDate' hidden><i class='fa-regular fa-clock' aria-hidden="true"></i> {datetime="$row->_followData['follow_added']"}</li>
						<li title='{lang="follow_how"}' data-role='followFrequency'>
							{{if $row->_followData['follow_notify_freq'] == 'none'}}
								<i class='fa-regular fa-bell-slash' aria-hidden="true"></i>
							{{else}}
								<i class='fa-regular fa-bell' aria-hidden="true"></i>
							{{endif}} {lang="follow_freq_{$row->_followData['follow_notify_freq']}"}
						</li>
						<li data-role='followAnonymous' {{if !$row->_followData['follow_is_anon']}}hidden{{endif}}><i class="fa-regular fa-eye-slash" aria-hidden="true"></i> {lang="follow_is_anon"}</li>
					</ul>
				</div>
				<div class='cFollowedContent_manage'>
					{template="manageFollow" group="system" app="core" params="$row->_followData['follow_app'], $row->_followData['follow_area'], $row->_followData['follow_rel_id']"}
				</div>
			</div>

			{{if $table->canModerate()}}
				<label class="ipsData__mod">
					<span class="ipsInvisible">{lang="mod_checkbox"}</span>
					<input type='checkbox' data-role='moderation' name="moderate[{$row->$idField}]" data-actions="{expression="implode( ' ', $table->multimodActions( $row ) )"}" data-state='{{if $row->tableStates()}}{$row->tableStates()}{{endif}}' class="ipsInput ipsInput--toggle">
				</label>
			{{endif}}

		</li>
	{{endforeach}}
{{endif}}

{{if empty( $rows )}}
	<tr>
		<td colspan="{expression="\count( $headers )"}">
			<div class='i-padding_4 i-color_soft'>
				{lang="no_results"}
				{{if ( isset( $table->rootButtons['add'] ) )}}
					&nbsp;&nbsp;
					<a 
						{{if isset( $table->rootButtons['add']['link'] )}}href='{$table->rootButtons['add']['link']}'{{endif}}
						title='{lang="$table->rootButtons['add']['title']"}'
						class='ipsButton ipsButton--secondary ipsButton--small {{if isset( $table->rootButtons['add']['class'] )}}{$table->rootButtons['add']['class']}{{endif}}'
						role="button"
						{{if isset( $table->rootButtons['add']['data'] )}}
							{{foreach $table->rootButtons['add']['data'] as $k => $v}}
								data-{$k}="{$v}"
							{{endforeach}}
						{{endif}}
						{{if isset( $table->rootButtons['add']['hotkey'] )}}
							data-keyAction='{$table->rootButtons['add']['hotkey']}'
						{{endif}}
					>{lang="$table->rootButtons['add']['title']"}</a>
				{{endif}}
			</div>
		</td>
	</tr>
{{else}}
	{{foreach $rows as $rowId => $r}}
		<tr class='{{if isset( $table->highlightRows[ $rowId ] )}} {$table->highlightRows[ $rowId ]}{{endif}}' data-keyNavBlock {{if isset( $r['_buttons']['view'] )}}data-tableClickTarget="view"{{elseif isset( $r['_buttons']['edit'] )}}data-tableClickTarget="edit"{{endif}}>
			{{foreach $r as $k => $v}}
				<td class='{{if $k === 'photo'}}ipsTable_icon{{endif}} {{if $k === ( $table->mainColumn ?: $table->quickSearch ) OR $k === 'o_invoice'}}ipsTable_wrap{{endif}} {{if $k === $table->mainColumn}}ipsTable_primary{{endif}} {{if $k === '_buttons'}}ipsTable_controls{{endif}}{{if isset( $table->rowClasses[ $k ] )}}{expression="implode( ' ', $table->rowClasses[ $k ] )"}{{endif}}' {{if $k !== $table->mainColumn && $k !== '_buttons' && $k !== 'photo'}}data-title="{lang="{$table->langPrefix}{$k}"}"{{endif}}>
					{{if $k === '_buttons'}}
						{template="controlStrip" params="$v" group="global" app="core"}
					{{else}}
						{$v|raw}
					{{endif}}
				</td>
			{{endforeach}}
		</tr>
	{{endforeach}}
{{endif}}

{{$rowIds = array();}}
{{foreach $rows as $row}}
	{{$idField = $row::$databaseColumnId;}}
	{{$rowIds[] = $row->$idField;}}
{{endforeach}}
{{if \count( $rows )}}
	{{foreach $rows as $row}}
	{{$idField = $row::$databaseColumnId;}}
		{{if $row->mapped('moved_to')}}
			{{if $movedTo = $row->movedTo()}}
				<li class="ipsData__item ipsData__item--moved">
					<a href='{$movedTo->url()}' class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{$row->mapped('title')}</span></a>
					<div class='ipsData__icon ipsData__icon--indicator'>
						<i class="fa-solid fa-arrow-left" aria-hidden="true"></i>
					</div>
					<div class='ipsData__content'>
						<div class='ipsData__main'>
							<div class='ipsData__title'>
								<h4><a href='{$movedTo->url()}' title='{lang="go_to_new_location"}'>{$row->mapped('title')}</a></h4>
							</div>
							<p class='ipsData__meta'>
								{{if isset( $row::$databaseColumnMap['status'] )}}
									{{$statusField = $row::$databaseColumnMap['status'];}}
									{{if $row->$statusField == 'merged'}}
										{lang="merged_to" sprintf="$movedTo->url(), $movedTo->mapped('title')"}
									{{else}}
										{lang="moved_to" sprintf="$movedTo->container()->url(), $movedTo->container()->_title"}
									{{endif}}
								{{else}}
									{lang="moved_to" sprintf="$movedTo->container()->url(), $movedTo->container()->_title"}
								{{endif}}
							</p>
						</div>
					</div>
					{{if $table->canModerate()}}
						<label class="ipsData__mod">
							<span class="ipsInvisible">{lang="mod_checkbox"}</span>
							<input type='checkbox' data-role='moderation' name="moderate[{$row->$idField}]" data-actions="{expression="implode( ' ', $table->multimodActions( $row ) )"}" data-state='{{if $row->mapped('pinned')}}pinned{{endif}} {{if $row->mapped('featured')}}featured{{endif}}' class="ipsInput ipsInput--toggle">
						</label>
					{{endif}}
				</li>
			{{endif}}
		{{else}}
