		{{if $isCarousel}}
			{{$carouselID = 'widget--clubs_' . mt_rand();}}
			{template="carouselNavigation" group="global" app="core" params="$carouselID"}
		{{endif}}
	</header>
{{endif}}
<div class="ipsWidget__content">
	<i-data>
		<ul class='ipsData ipsData--{$layout} {{if $isCarousel}}ipsData--carousel{{endif}} ipsData--widget-clubs' {{if $isCarousel}}id='{$carouselID}' tabindex="0"{{endif}}>
			{{foreach $clubs as $club}}
				<li class='ipsData__item'>
					<a href="{$club->url()}" class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{$club->name}</span></a>
					<div class='ipsData__image'>{template="clubIcon" group="clubs" app="core" params="$club, 'fluid', ''"}</div>
					<div class="ipsData__content">
						<div class='ipsData__main'>
							<h4 class='ipsData__title'><a href='{$club->url()}'>{$club->name}</a></h4>
							<p class='ipsData__meta'>
								{lang="club_{$club->type}"}
								{{if $club->type !== $club::TYPE_PUBLIC}} &middot; {lang="club_members_count" pluralize="$club->members"}{{endif}}
							</p>
						</div>
					</div>
				</li>
			{{endforeach}}
		</ul>
	</i-data>
</div>

{template="includeJS" app="core" group="global" location="global" params=""}
{{$visibilityFields = array( 'show_on_all_devices', 'devices_to_show', 'clubs_visibility');}}
<form accept-charset='utf-8' class="ipsFormWrap ipsFormWrap--widget-template" action="{$action}" method="post" {{if $uploadField}}enctype="multipart/form-data"{{endif}} {{foreach $attributes as $k => $v}}{$k}="{$v}"{{endforeach}} data-ipsForm>
	<input type="hidden" name="{$id}_submitted" value="1">
	{{foreach $hiddenValues as $k => $v}}
		<input type="hidden" name="{$k}" value="{$v}">
	{{endforeach}}
	{{if $uploadField}}
		<input type="hidden" name="MAX_FILE_SIZE" value="{$uploadField}">
		<input type="hidden" name="plupload" value="{expression="md5( mt_rand() )"}">
	{{endif}}
	<h4 class='ipsTitle ipsTitle--h3 ipsTitle--padding'>{lang="editBlockSettings"}</h4>

	{{$hasSettings = FALSE;}}
	{{$showVisibility = false;}}
	{{$showAdvanced = false;}}
	{{foreach $elements as $collection}}
		{{foreach $collection as $inputName => $input}}
		    {{if \in_array( $inputName, $visibilityFields )}}
		        {{$showVisibility = true;}}
		    {{elseif mb_substr( $inputName, 0, 12 ) == 'widget_adv__' }}
		        {{$showAdvanced = true;}}
			{{else}}
				{{$hasSettings = TRUE;}}
			{{endif}}
		{{endforeach}}
	{{endforeach}}

	<i-tabs class='ipsTabs' id='ipsTabs_{$id}' data-ipsTabBar data-ipsTabBar-contentArea='#ipsTabs_{$id}_content'>
		<div role='tablist'>
			{{$checkedTab = NULL;}}
			{{if $hasSettings}}
				<button type="button" id='ipsTabs_{$id}_settings' class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_{$id}_settings_panel" aria-selected="{{if !$checkedTab}}true{{$checkedTab = 'settings';}}{{else}}false{{endif}}">
					{lang="settings"}
				</button>
			{{endif}}
			{{if $showVisibility}}
				<button type="button" id='ipsTabs_{$id}_visibility' class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_{$id}_visibility_panel" aria-selected="{{if !$checkedTab}}true{{$checkedTab = 'visibility';}}{{else}}false{{endif}}">
					{lang="visibility"}
				</button>
		    {{endif}}
		    {{if $showAdvanced}}
				<button type="button" id='ipsTabs_{$id}_advanced' class="ipsTabs__tab" role="tab" aria-controls="ipsTabs_{$id}_advanced_panel" aria-selected="false">
					{lang="widget_tab_advanced"}
				</button>
			{{endif}}
		</div>
		{template="tabScrollers" app="core" group="global" location="global"}
	</i-tabs>
	<div id='ipsTabs_{$id}_content' class='ipsTabs__panels'>
	    {{if $hasSettings}}
		<div id='ipsTabs_{$id}_settings_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}} ipsTabs__panel" role="tabpanel" aria-labelledby="ipsTabs_{$id}_settings" {{if $checkedTab != 'settings'}}hidden{{endif}}>
			<ul class='ipsForm ipsForm--vertical ipsForm--widget-template'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \mb_substr( $inputName, 0, 12 ) != 'widget_adv__' and ! \in_array( $inputName, $visibilityFields, TRUE )}}
							{{if \is_object( $input )}}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>
		{{endif}}
		{{if $showVisibility}}
		<div id='ipsTabs_{$id}_visibility_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}} ipsTabs__panel" role="tabpanel" aria-labelledby="ipsTabs_{$id}_visibility" {{if $checkedTab != 'visibility'}}hidden{{endif}}>
			<ul class='ipsForm ipsForm--vertical ipsForm--widget-template'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \is_object( $input ) and \in_array( $input->name, $visibilityFields, TRUE )}}
							{$input->rowHtml($form)|raw}
						{{elseif \in_array( $inputName, $visibilityFields, TRUE )}}
							{$input|raw}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>
		{{endif}}

        {{if $showAdvanced}}
		<div id='ipsTabs_{$id}_advanced_panel' class="{{if $widget->menuStyle !== 'modal'}}ipsMenu_innerContent{{endif}}ipsTabs__panel" role="tabpanel" aria-labelledby="ipsTabs_{$id}_advanced" hidden>
			<ul class='ipsForm ipsForm--vertical ipsForm--widget-template'>
				{{foreach $elements as $collection}}
					{{foreach $collection as $inputName => $input}}
						{{if \mb_substr( $inputName, 0, 12 ) == 'widget_adv__' and ! \in_array( $inputName, $visibilityFields, TRUE )}}
							{{if \is_object( $input )}}
								{$input->rowHtml($form)|raw}
							{{else}}
								{$input|raw}
							{{endif}}
						{{endif}}
					{{endforeach}}
				{{endforeach}}
			</ul>
		</div>
		{{endif}}
	</div>
	<div class='ipsMenu_footerBar i-text-align_center'>
		{{foreach $actionButtons as $button}}
			{$button|raw}
		{{endforeach}}
	</div>
</form>

{{$buttonMethods = $login->buttonMethods();}}
{{$usernamePasswordMethods = $login->usernamePasswordMethods();}}
{{$ref = \IPS\Request::i()->externalref ?: base64_encode( \IPS\Request::i()->url() ); }}
<div class='ipsWidget__content'>
	<div class='ipsWidget__padding'>
		<h2 class="ipsTitle ipsTitle--h3 ipsTitle--margin">{$title}</h2>
		<div class="ipsRichText">{$text|raw}</div>
	</div>
	<div class="ipsSubmitRow i-flex i-flex-wrap_wrap i-gap_1 i-justify-content_space-between">
		{{if $usernamePasswordMethods}}
			<ul class="ipsButtons ipsButtons--fill">
				<li>
					<a href='{url="app=core&module=system&controller=register" seoTemplate="register"}' class="ipsButton ipsButton--primary"><i class="fa-solid fa-user-plus" aria-hidden="true"></i><span>{lang="sign_up"}</span></a>
				</li>
				<li>
					<a href='{url="app=core&module=system&controller=login" seoTemplate="login"}' class="ipsButton ipsButton--inherit"><i class="fa-solid fa-arrow-right-to-bracket" aria-hidden="true"></i><span>{lang="sign_in_short"}</span></a>
				</li>
			</ul>
		{{endif}}
		{{if $buttonMethods}}
			<form accept-charset='utf-8' method='post' action='{$login->url}' target="_parent">
				<input type="hidden" name="csrfKey" value="{expression="\IPS\Session::i()->csrfKey"}">
				<input type="hidden" name="ref" value="{$ref}">
				<div class='ipsButtons ipsButtons--fill'>
					{{foreach $buttonMethods as $method}}
						{$method->button()|raw}
					{{endforeach}}
				</div>
			</form>
		{{endif}}
	</div>
</div>

{{if ! \is_array( $images )}}
<div><img src="{$images}" class="ipsPageBuilderUpload" loading="lazy" alt=""></div>
{{endif}}

{{if !empty( $similar ) }}
	<h3 class='ipsWidget__header'>{$title}</h3>
	{{if $isCarousel}}
    	{{$carouselID = 'widget-related-content_' . mt_rand();}}
    	{template="carouselNavigation" group="global" app="core" params="$carouselID"}
    {{endif}}
	{{if isset($orientation) and $orientation == 'vertical'}}
		<div class='ipsWidget__content'>
			<i-data>
				<ul class='ipsData ipsData--{$layout} {{if $isCarousel}}ipsData--carousel{{endif}} ipsData--related-content' {{if $isCarousel}}id='{$carouselID}' tabindex="0"{{endif}}>
					{{foreach $similar as $item}}
						{{$numComments = ( $item::$firstCommentRequired ) ? $item->mapped('num_comments') - 1 : $item->mapped('num_comments');}}
						<li class='ipsData__item {{if $item->hidden()}} ipsModerated{{endif}}'>
							<a href="{$item->url( "getPrefComment" )}" title='{lang="view_this_topic" sprintf="$item->title"}' class="ipsLinkPanel" aria-hidden="true"><span>{$item->mapped('title')}</span></a>
							<div class='ipsData__icon'>{template="userPhoto" group="global" app="core" params="$item->author(), 'fluid'"}</div>
							<div class='ipsData__main'>
								<div class='ipsData__title'>
									<div class='ipsBadges'>
										{{if $item->hidden() === -1}}
											<span class="ipsBadge ipsBadge--icon ipsBadge--warning" data-ipsTooltip title='{$item->hiddenBlurb()}'><i class='fa-solid fa-eye-slash' aria-hidden="true"></i></span>
										{{elseif $item->hidden() === 1}}
											<span class="ipsBadge ipsBadge--icon ipsBadge--warning" data-ipsTooltip title='{lang="pending_approval"}'><i class='fa-solid fa-triangle-exclamation' aria-hidden="true"></i></span>
										{{endif}}
										{{if $item->mapped('featured')}}
											<span class="ipsBadge ipsBadge--icon ipsBadge--positive" data-ipsTooltip title='{lang="featured"}'><i class='fa-solid fa-star' aria-hidden="true"></i></span>
										{{endif}}
										{{if \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Solvable' ) and $item->isSolved()}}
											<span class="ipsBadge ipsBadge--icon ipsBadge--positive" data-ipsTooltip title='{lang="this_is_solved"}'><i class='fa-solid fa-check' aria-hidden="true"></i></span>
										{{endif}}
									</div>
									<h4><a href="{$item->url( "getPrefComment" )}" title='{lang="view_this_topic" sprintf="$item->title"}'>{$item->mapped('title')}</a></h4>
								</div>
								<p class='ipsData__meta'>
									{lang="byline_nodate" htmlsprintf="$item->author()->link( NULL, NULL, \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Anonymous' ) ? $item->isAnonymous() : FALSE )"} &middot; {lang="started_date" htmlsprintf="\IPS\DateTime::ts( $item->mapped('date') )->html( false )"}
								</p>
							</div>
							<div class="ipsData__extra">
								<ul class="ipsData__stats">
									<li data-statType='replies'>
										<span class='ipsData__stats-icon' data-stat-value='{expression="\IPS\Member::loggedIn()->language()->formatNumber( $numComments )"}' aria-hidden="true" data-ipstooltip title='{lang="replies_number" pluralize="$numComments"}'></span>
										<span class='ipsData__stats-label'>{lang="replies_number" pluralize="$numComments"}</span>
									</li>
								</ul>
							</div>
						</li>
					{{endforeach}}
				</ul>
			</i-data>
		</div>
	{{else}}
		<div class='ipsWidget__content'>
			<i-data>
				<ul class="ipsData ipsData--{$layout} {{if $isCarousel}}ipsData--carousel{{endif}} ipsData--related-content" {{if $isCarousel}}id='{$carouselID}' tabindex="0"{{endif}}>
					{{foreach $similar as $item}}
						<li class="ipsData__item {{if $item->hidden()}}ipsModerated{{endif}}">
							<a href='{$item->url( "getPrefComment" )}' title='{lang="view_this_topic" sprintf="$item->title"}' class="ipsLinkPanel" aria-hidden="true"><span>{$item->mapped('title')}</span></a>
							<div class='ipsData__content'>
								<div class='ipsData__main'>
									<div class='ipsData__title'>
										<div class='ipsBadges'>
											{{foreach $item->badges() as $badge}}{$badge|raw}{{endforeach}}
											{{if $item->prefix()}}
												{template="prefix" group="global" app="core" params="$item->prefix( TRUE ), $item->prefix()"}
											{{endif}}
										</div>
										<h4>
														<a href='{$item->url( "getPrefComment" )}' {{if $item->tableHoverUrl and $item->canView()}}data-ipsHover data-ipsHover-target='{$item->url()->setQueryString('preview', 1)}' data-ipsHover-timeout='1.5' {{endif}}>{$item->mapped('title')}</a>
										</h4>
										{{if $item->commentPageCount() > 1}}
											{$item->commentPagination( array(), 'miniPagination' )|raw}
										{{endif}}
									</div>
									<div class='ipsData__meta'>{lang="byline_name_date" htmlsprintf="$item->author()->link( NULL, NULL, \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Anonymous' ) ? $item->isAnonymous() : FALSE ), \IPS\DateTime::ts( $item->mapped('date') )->html(TRUE)"}</div>
									{{if \count( $item->tags() )}}
										{template="tags" group="global" app="core" params="$item->tags(), true, true"}
									{{endif}}
								</div>
								<ul class="ipsData__stats">
									{{foreach $item->stats(FALSE) as $k => $v}}
										<li {{if \in_array( $k, $item->hotStats )}}class="ipsData__stats-hot" data-text='{lang="hot_item"}' data-ipsTooltip title='{lang="hot_item_desc"}'{{endif}}>
											<span>{number="$v"}</span>
											<span>{lang="{$k}" pluralize="$v"}</span>
										</li>
									{{endforeach}}
								</ul>
								<div class="ipsData__last">
									{{if $item->mapped('num_comments')}}
										{template="userPhoto" app="core" group="global" params="$item->lastCommenter(), 'fluid'"}
									{{else}}
										{template="userPhoto" app="core" group="global" params="$item->author(), 'fluid'"}
									{{endif}}
									<div class='ipsData__last-text'>
										<div class='ipsData__last-primary'>
											{{if $item->mapped('num_comments')}}
												{$item->lastCommenter()->link()|raw}
											{{else}}
												{$item->author()->link( NULL, NULL, \IPS\IPS::classUsesTrait( $item, 'IPS\Content\Anonymous' ) ? $item->isAnonymous() : FALSE )|raw}
											{{endif}}
										</div>
										<div class='ipsData__last-secondary'>
											<a href='{$item->url( 'getLastComment' )}' title='{lang="get_last_post"}'>{{if $item->mapped('last_comment')}}{datetime="$item->mapped('last_comment')"}{{else}}{datetime="$item->mapped('date')"}{{endif}}</a>
										</div>
									</div>
								</div>
							</div>
						</li>
					{{endforeach}}
				</ul>
			</i-data>
		</div>
	{{endif}}
{{endif}}

{{if $isCarousel}}
	{{$carouselID = $soloTag ? $soloTag : 'widget-tags_' . mt_rand();}}
{{endif}}
<i-data>
    <ul class='ipsData ipsData--{$layout} ipsData--widget-tags {{if $isCarousel}}ipsData--carousel{{endif}}' {{if $isCarousel}}id='{$carouselID}' tabindex="0"{{endif}}>
        {{foreach $items as $item}}
            <li class='ipsData__item'>
                <a href="{$item->url( 'getPrefComment' )}" class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{$item->mapped( 'title' )}</span></a>
				{{if in_array($layout, array("wallpaper", "featured", "grid"))}}
					<div class="ipsData__image" aria-hidden="true">
						{{if $image = $item->primaryImage()}}
							<img src="{$image->url}" alt="{$item->title}" loading="lazy">
						{{else}}
							<i aria-hidden="true"></i>
						{{endif}}
					</div>
				{{else}}
					<div class='ipsData__icon'>
						{template="userPhoto" app="core" group="global" params="$item->author(), 'fluid'"}
					</div>
				{{endif}}
				<div class="ipsData__content">
					<div class='ipsData__main'>
						<div class='ipsData__title'>
							<h4><a href="{$item->url()}" title='{lang="view_this_topic" sprintf="$item->mapped( 'title' )"}'>{$item->mapped( 'title' )}</a></h4>
						</div>
						<div class='ipsData__desc ipsRichText' data-controller='core.front.core.lightboxedImages'>{$item->truncated()|raw}</div>
						<p class='ipsData__meta'>
						    {lang="byline_name_date" htmlsprintf="$item->author()->link( NULL, NULL, $item->isAnonymous() ), \IPS\DateTime::ts( $item->mapped('date') )->html(FALSE)"}
						</p>
					</div>
				</div>
			</li>
		{{endforeach}}
	</ul>
	{{if $isCarousel && !$soloTag}}
		{template="carouselNavigation" group="global" app="core" params="$carouselID"}
	{{endif}}
</i-data>

{{if (count( $data ) < 2) & $isCarousel}}
	{{ $soloTag = 'widget-tags_' . mt_rand(); }}
{{else}}
	{{ $soloTag = false; }}
{{endif}}
<header class='ipsWidget__header'>
	<h3>{$title}</h3>
	{{if $soloTag && $isCarousel}}
		{template="carouselNavigation" group="global" app="core" params="$soloTag"}
	{{endif}}
</header>
{{$key = md5( uniqid( microtime() ) );}}
<div class='ipsWidget__content'>
    {{if count( $data ) > 1}}
	<i-tabs class='ipsTabs ipsTabs--stretch' id='ipsTabs_{$key}' data-ipsTabBar data-ipsTabBar-updateURL='false' data-ipsTabBar-contentArea='#ipsTabs_{$key}_content'>
		<div role="tablist">
			{{$checked = NULL;}}
		    {{foreach $data as $tag => $items}}
				{{$tabId = \preg_replace('/[^a-zA-Z0-9\-]/', '', $tag);}}
				<button type="button" id='ipsTabs_{$key}_{$tabId}' class='ipsTabs__tab' role="tab" aria-controls="ipsTabs_{$key}_{$tabId}_panel" aria-selected="{{if !$checked}}true{{$checked = $tabId;}}{{else}}false{{endif}}">{$tag}</button>
			{{endforeach}}
		</div>
		{template="tabScrollers" app="core" group="global" location="global"}
	</i-tabs>
	<section id='ipsTabs_{$key}_content' class='ipsTabs__panels'>
	    {{foreach $data as $tag => $items}}
			{{$tabId = \preg_replace('/[^a-zA-Z0-9\-]/', '', $tag);}}
			<div id="ipsTabs_{$key}_{$tabId}_panel" class='ipsTabs__panel' role="tabpanel" aria-labelledby="ipsTabs_{$key}_{$tabId}" {{if $checked != $tabId}}hidden{{endif}}>
				{template="tagRows" group="widgets" app="core" params="$items, $layout, $isCarousel, $soloTag"}
			</div>
		{{endforeach}}
	</section>
	{{else}}
	    {{foreach $data as $tag => $items}}
	        {template="tagRows" group="widgets" app="core" params="$items, $layout, $isCarousel, $soloTag"}
        {{endforeach}}
	{{endif}}
</div>

{{if \count( $results )}}
	<i-data>
		<ol class="ipsData ipsData--{$layout} cTopContributors">
			{{foreach $results as $memberId => $rep}}
				{{$member = \IPS\Member::load( $memberId );}}
				<li class='ipsData__item'>
					<a href="{$member->url()}" class="ipsLinkPanel" aria-hidden="true" tabindex="-1"><span>{$member->name}</span></a>
					<div class="{{if \in_array($layout, array('table', 'minimal'))}}ipsData__icon{{else}}ipsData__image{{endif}}">
						{template="userPhoto" app="core" group="global" params="$member, 'fluid'"}
					</div>
					<div class='ipsData__content'>
						<div class='ipsData__main'>
							<div class='ipsData__title'>{$member->link()|raw}</div>
							<div class='ipsData__meta'>
								{{if member.group['gbw_view_reps']}}
									<a href='{url="app=core&module=members&controller=profile&id={$member->member_id}&do=reputation" seoTemplate="profile_reputation" seoTitle="$member->members_seo_name"}' title="{lang="reputation_badge_tooltip_period"}" data-ipsTooltip class='ipsRepBadge {{if $rep > 0}}ipsRepBadge--positive{{elseif $rep < 0}}ipsRepBadge--negative{{else}}ipsRepBadge_neutral{{endif}}'><i class='{{if $rep > 0}}fa-solid fa-plus-circle{{elseif $rep < 0}}fa-solid fa-minus-circle{{else}}fa-regular fa-circle{{endif}}' aria-hidden="true"></i> {expression="\IPS\Member::loggedIn()->language()->formatNumber( $rep )"}</a>
								{{else}}
									<span title="{lang="reputation_badge_tooltip_period"}" data-ipsTooltip class='ipsRepBadge {{if $rep > 0}}ipsRepBadge--positive{{elseif $rep < 0}}ipsRepBadge--negative{{else}}ipsRepBadge_neutral{{endif}}'><i class='{{if $rep > 0}}fa-solid fa-plus-circle{{elseif $rep < 0}}fa-solid fa-minus-circle{{else}}fa-regular fa-circle{{endif}}' aria-hidden="true"></i> {expression="\IPS\Member::loggedIn()->language()->formatNumber( $rep )"}</span>
								{{endif}}
							</div>
						</div>
					</div>
				</li>
			{{endforeach}}
		</ol>
	</i-data>
	{{if settings.reputation_leaderboard_on and member.canAccessModule( \IPS\Application\Module::get( 'core', 'discover' ) )}}
		<div class="i-padding_2 i-text-align_end i-background_2 i-border-end-start-radius_box i-border-end-end-radius_box i-border-top_3">
			{{$_timeframe = $timeframe == 'all' ? 'time=oldest' : ( $timeframe == 'year' ? ( 'custom_date_start=' . ( time() - 31536000 ) ) : ( 'time=' . $timeframe ) );}}
			<a href="{url="app=core&module=discover&controller=popular&tab=leaderboard&{$_timeframe}" seoTemplate="leaderboard_leaderboard"}" class='i-font-weight_600 i-color_soft i-font-size_-2'>{lang="leaderboard_show_more"} <i class="fa-solid fa-arrow-right-long i-margin-start_icon" aria-hidden="true"></i></a>
		</div>
	{{endif}}
{{else}}
	<div class='ipsEmptyMessage'>
		<p>{lang="top_contributors_empty__{$timeframe}"}</p>
	</div>
{{endif}}

theme.css:
/* ======================================================== */
/* 2FA */

#elTwoFactorAuthentication {
	position: fixed;
	inset: 0;
	display: flex;
	justify-content: center;
	align-items: center;
	z-index: 10000;
	overflow: hidden;
}

	#elTwoFactorAuthentication > div {
		max-width: 500px;
		background: var(--i-background_1);
		box-shadow: 0px 5px 55px rgba(0,0,0,0.4);
		border-radius: 6px;
		overflow: auto;
	}

	#elTwoFactorAuthentication .c2FA_info {
		max-width: 80%;
		margin-left: auto;
		margin-right: auto;
	}

	#elTwoFactorAuthentication button[name="_mfaCancel"] {
		border: none;
		padding-bottom: 7px;
	}

		#elTwoFactorAuthentication button[name="_mfaCancel"] i[class*=" fa-"] {
			cursor: pointer;
		}

#elGoogleAuthenticator input[type="text"] {
	font-size: 30px;
	text-align: center;
}

#elAuthy select {
	width: 100%;
}

#elAuthy input[type="text"] {
	font-size: 30px;
	text-align: center;
}

.cAuthy_container {
	position: relative;
}

.cAuthy_icon {
	width: 36px;
	height: 36px;
	position: absolute;
	top: 8px;
	inset-inline-start: 8px;
}

/* Core app, non-framework styles */
#elErrorMessage {
	max-width: 800px;
	margin-left: auto;
	margin-right: auto;
}

/* Hovercards */
.ipsHovercard[data-role="advicePopup"] {
    display: none;
	width: 300px;
}
	.ipsHovercard[data-role="advicePopup"] > div {
		min-height: 60px;
	}

.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem {
	right: 100%;
	top: 15px;
}
	.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem:before {
		right: 1px;
		border-right-color: inherit;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem:after{
		border-right-color: currentColor;
	}

.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem {
	left: 100%;
	top: 15px;
}
	.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem:before {
		left: 1px;
		border-left-color: inherit;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem:after{
		border-left-color: currentColor;
	}

.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem{
	left: 50%;
	margin-left: -1em;
	top: 100%;
}
	.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem:before {
		border-top-color: inherit;
		top: 1px;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem:after{
		border-top-color: currentColor;
	}



/* Share Links */
.ipsShareLinks{
	display: flex;
	flex-wrap: wrap;
	gap: .4em;
}
.ipsShareLink {
	width: 2.4em;
	height: 2.4em;
	border-radius: min(var(--i-design-radius), 6px);
	display: inline-grid;
	place-content: center;
	color: #fff !important;
	font-size: max(15px, 1em);
}

	.ipsShareLink--internal { background: #008b00; }
	.ipsShareLink--deviantart { background: #00e59b; }
	.ipsShareLink--email { background: #444; }
	.ipsShareLink--facebook { background: #1778F2; }
	.ipsShareLink--linkedin { background: #0a66c2; }
	.ipsShareLink--reddit { background: #FF4500; }
	.ipsShareLink--vk { background: #507299; }
	.ipsShareLink--weibo { background: #D32F2F; }
	.ipsShareLink--youtube { background: #ff0000; }
	.ipsShareLink--foursquare { background: #2D5BE3; }
	.ipsShareLink--etsy { background: #F56400; }
	.ipsShareLink--flickr { background: #ff0084; }
	.ipsShareLink--github { background: #24292f; }
	.ipsShareLink--instagram { background: #E13D62; }
	.ipsShareLink--pinterest { background: #BD081C; }
	.ipsShareLink--slack { background: #42C299; }
	.ipsShareLink--xing { background: #B0D400; }
	.ipsShareLink--tumblr { background: #36465D; }
	.ipsShareLink--twitch { background: #772ce8; }
	.ipsShareLink--discord { background: #5865f2; }
	.ipsShareLink--x { background: #000000; }
    .ipsShareLink--bluesky { background: #59baff; }

/* Status update widget */
.ipsWidget .cStatusUpdateWidget .ipsComposeArea_dummy {
	padding: 7px 10px;
	font-size: var(--i-font-size_-1);
}

	.ipsWidget .cStatusUpdateWidget .ipsComposeArea_dummy i[class*=" fa-"] {
		margin-inline-end: 5px;
	}

	.ipsWidget .cStatusUpdateWidget [data-role="attachmentArea"] {
		display: none !important;
	}

#elGuestTerms {
	background: var(--if-light, var(--i-background_1)) var(--if-dark, var(--i-background_3));
	border-top: 1px solid color-mix(in srgb, var(--i-color_root) 10%, transparent);
	background-clip: var(--if-light,padding-box) var(--if-dark,border-box);
	position: sticky;
	bottom: 0;
	padding: 1.3em 0;
	z-index: 4000;
	outline-offset: -2px;
}

@media (max-width: 979px){
	#elGuestTerms{
		bottom: var(--i-mobileFooter--he);
	}
}

/* Hide certain elements if optional cookies have been rejected */
.cOptionalCookiesRejected [data-role="dismissAnnouncement"],
.cOptionalCookiesRejected #elNavTheme{
	display: none !important;
}

/* Guest Sign In */
.cGuestTeaser_social {
	width: 250px;
	margin-bottom: 5px;
}

/* Ensure Google captcha logo appears on top of other elements */
.grecaptcha-badge{
	z-index: 10;
}

@media (max-width: 979px){
	/* Move recaptcha badge above mobile footer */
	.grecaptcha-badge{
		bottom: calc(var(--i-mobileFooter--he) + 10px) !important;
	}
}
@media (min-width: 980px){
	.ipsLayout:has(#elGuestTerms) .grecaptcha-badge{
		bottom: 120px !important; /* Magic number */
	}
}

/* Color chooser for Content Item Messages */
.cColorChoices li {
	position: relative;
}
.cColorChoice_chooser {
	background-color: var(--_ba-co);
	width: 42px;
	height: 36px;
	display: block;
	position: relative;
	border-radius: 4px;
}

.cColorChoices [type="radio"] {
	position: absolute;
	width: 100%;
	height: 100%;
	z-index: 1;
	appearance: none;
	cursor: pointer;
}
	.cColorChoices [type="radio"]:checked + .cColorChoice_chooser {
		outline: 2px solid currentColor;
		outline-offset: 1px;
	}

/* Club embeds */
.cClubEmbedHeader {
	position: relative;
	height: 180px;
}

	.cClubEmbedHeader.cClubEmbedHeaderNoPhoto,
	.cClubEmbedHeader.cClubEmbedHeaderNoPhoto span {
		height: 120px;
	}

.cClubEmbedHeader .ipsUserPhoto {
	position: absolute;
	left: 50%;
	top: 50%;
	transform: translate(-50%, -50%);
	border: 2px solid #fff;
}

/* Notifications Menu Browser Prompt */
.cNotifcationPrompt {
	position: relative;
	background: var(--i-background_dark);
	color: #fff;
}

	.cNotifcationPrompt_title {
		color: inherit;
	}

	.cNotifcationPrompt_text {
		opacity: 0.7;
	}

	.cNotifcationPrompt_icon {
		display: block;
		background-image: url('{resource="notification.svg" inCss="true" location="front" app="core"}');
		background-repeat: no-repeat;
		background-size: cover;
		aspect-ratio: 1;
	}

.cNotifcationPrompt_dismiss {
	background: hsl(0 0% 0% / .6);
	width: 16px;
	height: 16px;
	border-radius: 16px;
	line-height: 16px;
	text-align: center;
	color: #fff;
	font-size: 12px;
	position: absolute;
	top: 9px;
	inset-inline-end: 9px;
}

.cContentMessageEditor.cContentMessageEditor--private .ipsEditor{
	border-color: var(--i-color_negative);
	--bo-sh: color-mix(in srgb, var(--i-color_negative) 15%, transparent);
	box-shadow: var(--bo-sh) 0px 0px 0px 6px;
}

.cContentMessageEditor.cContentMessageEditor--public .ipsEditor{
	border-color: var(--i-color_positive);
	--bo-sh: color-mix(in srgb, var(--i-color_positive) 15%, transparent);
	box-shadow: var(--bo-sh) 0px 0px 0px 6px;
}


.cLogin_single{
	max-width: 500px;
	margin: 0 auto;
}

/* PHONES */
@media screen and (max-width: 767px) {
	.cUserHovercard {
		min-width: 0;
	}

	/* Google MFA */
	#elGoogleAuthenticator .ipsSpanGrid__8 {
		margin-top: 0;
		margin-bottom: 10px;
	}

	/* Guest Sign In */
	.cGuestTeaser_social {
		width: 100%;
	}

		.cGuestTeaser_social a {
			margin: 0 auto;
		}

	/* Reset guest teaser on mobile back to normal layout from tablet flex layout */
	.cGuestTeaser .ipsGrid {
		display: block !important;
	}
		.cGuestTeaser .ipsSpanGrid__6 {
			display: block !important;
		}
}

/* BOTH */
@media screen and (max-width: 979px) {

	/* Use flex to ensure positioning in guest teaser for tablet */
	.cGuestTeaser .ipsGrid {
		display: flex;
	}
		.cGuestTeaser .ipsSpanGrid__6 {
			display: flex;
			flex: 1;
			flex-direction: column;
		}
			.cGuestTeaser .ipsSpanGrid__6 a {
				margin-top: auto;
			}
}






/* v5 code */


/* Achievements Widget */
.cAchievementsWidget__badge{
	width: 40px;
}




/*
	----------------
	- Page builder
	----------------
*/

/*
	Hide empty widget containers if they aren't being managed
	This can happen when widgets have just been saved, since ipsHide isn't applied
	If these are visible, they create extra space due to margins from .ipsLayout__primary-column > *
*/
.cWidgetContainer:not(.cWidgetContainer_managing):empty{
	display: none;
}



/* Main wrapper */
.cWidgetContainer--main{
	--i-block--padding-block: 0;
	--i-block--padding-inline: 0;
	--i-block--margin-top: 0;
	--i-block--gap: 0;
	--i-block--size: 300px;
	--i-block--transform-offset: 20;
	/* Grid allows the widgets/containers to be spaced apart using gap */
	display: grid;
	gap: var(--i-sp_block);
}

/* Sidebar Manager */
.ipsApp.cWidgetsManaging {
	--i-manage-widgets-sidebar: clamp(300px, 18vw, 375px);
	margin-inline-start: var(--i-manage-widgets-sidebar);
	position: relative; /* This ensures dropdown menus are positioned correctly. Redundant once [popover] is implemented */
}

.cWidgetContainer_managing:not(.cWidgetContainer .cWidgetContainer_managing) {
    min-height: 100px;
}

.cWidgetContainer{
    position: relative;
}

/*
    ----------------
    - Widget groups/alignment
    ----------------
*/

/* General groups */
.cWidgetContainer--isGroup{
	display: flex;
	flex-wrap: wrap;
	gap: var(--i-block--gap);
	padding-block: calc(1px * var(--i-block--padding-block));
	padding-inline: calc(1px * var(--i-block--padding-inline));
}

	.cWidgetContainer--isWidget{
		flex: 1 1 var(--i-block--size);
	}

/* Carousel */
.cWidgetContainer--carousel {
	gap: 0;
	display: grid;
	grid-auto-flow: row;

	/* Add widget box styles to carousel container */
	background: var(--i-widget--ba-co);
	border-radius: var(--i-widget--bo-ra);
	box-shadow: var(--i-widget--bo-sh);
	border-width: var(--i-widget--bo-wi);
	border-style: var(--i-widget--bo-st);
	border-color: var(--i-widget--bo-co);
	background-clip: padding-box;
	container-type: inline-size;
	overflow: hidden;
}

.cWidgetContainer--carousel > .cWidgetContainer__carousel-wrap{
	display: grid;
	grid-auto-columns: min(var(--i-block--size), 100%);
	overflow: auto;
	-ms-overflow-style: none;
	scrollbar-width: none;
	overscroll-behavior-x: contain;
	scroll-snap-type: x mandatory;
	gap: 0 1px;
}

/* Remove all styles from widgets inside carousel groups. The :not(#x) selector aims to future-proof any other complex selectors */
.cWidgetContainer--carousel .ipsWidget:not(#x){
	border-width: 0;
	box-shadow: none;
	background: none;
	border-radius: 0;
}

	.cWidgetContainer--carousel > .cWidgetContainer__carousel-wrap::-webkit-scrollbar {
		display: none;
	}		

	.cWidgetContainer--carousel > .cWidgetContainer__carousel-wrap > .cWidgetContainer {
		scroll-snap-align: start;
		grid-row: 1;
	}

	.cWidgetContainer--carousel > .cWidgetContainer__carousel-wrap > .cWidgetContainer:last-of-type {
		scroll-snap-align: end;
	}

	.cWidgetContainer__carousel-buttons {
		/*order: 1;*/
		/*width: 100cqw;*/
		/*position: sticky;*/
		/*inset-inline-start: 0;*/
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding: 5px;
		font-size: .9em;
		font-weight: 500;
		border-top: 1px solid var(--i-background_4);
  		background: var(--i-background_2);
	}

	.cWidgetContainer__carousel-buttons button:dir(rtl) {
		transform: scaleX(-1);
	}
	.cWidgetContainer__carousel-buttons button {
		width: 3em;
		height: 3em;
		text-align: center;
		border-radius: min(var(--i-design-radius), 6px);
		touch-action: manipulation;
	}
	.cWidgetContainer__carousel-buttons button[disabled] {
		opacity: 0.3;
		pointer-events: none;
	}
	@media (any-hover:hover){
		.cWidgetContainer__carousel-buttons button:hover{
			background-color: color-mix(in srgb, currentColor 5%, transparent);
		}
	}

	.cWidgetContainer__carousel-buttons [data-carousel-arrow="prev"] {
		order: -1;
	}

	.cWidgetContainer--carousel > .cWidgetContainer__carousel-wrap > .cWidgetContainer > .ipsWidget__content--wrap > .cSidebarBlock_managing {
		border-radius: 0;
		outline-width: 2px;
	}

/* Grid */
.cWidgetContainer--grid{
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(min(var(--i-block--size), 100%), 1fr));
}

/* Center */
.cWidgetContainer--center{
	justify-content: center;
}

	.cWidgetContainer--center .cWidgetContainer--isWidget{
		flex-grow: 0;
	}

/* Columns */
.cWidgetContainer--columnLeft > .cWidgetContainer--isWidget:nth-of-type(even),
.cWidgetContainer--columnRight > .cWidgetContainer--isWidget:nth-of-type(odd){
	flex: 999 1 max(calc(100% - var(--i-block--size) - var(--i-block--gap)), 50%);
}

/* Stack */
.cWidgetContainer--stack{
	display: grid;
}


/*
	----------------
	- Managing widgets
	----------------
*/

/* Add a faint, dashed outline around main widget areas (header, main, footer, sidebar) */
.cWidgetContainer_managing.cWidgetContainer--main,
.cWidgetContainer_managing.cWidgetContainer--isGroup{
	outline: 1px dashed var(--i-color_soft);
	outline-offset: 4px;
	border-radius: var(--i-box--bo-ra);
}

.cWidgetContainer_managing.cWidgetContainer--dragInside{
	outline: 2px dashed var(--i-color_hard);
	outline-offset: 5px;
}

/* Widgets */
.cWidgetsManaging .ipsWidget{
	isolation: isolate;
}
.cSidebarBlock_managing{
	outline: 3px solid var(--i-color_soft);
	outline-color: color-mix(in srgb, var(--i-color_soft) 30%, transparent);
	border-radius: var(--i-box--bo-ra);

	position: absolute;
	inset: 2px;
	display: flex;
	gap: .4em;
	align-items: baseline;
	padding: 1em;
	opacity: 0;
}

	.cSidebarBlock_managing__heading {
		opacity: 1;
		transition: opacity 0.1s ease-out;
	}
	/* Hide the title on hover so the contents are visible */
	.cSidebarBlock_managing__heading:hover {
		opacity: 0;
		transition-delay: 0.5s;
	}

	/* Only show manage panel when hovering or active */
	.cWidgetContainer--menu_open .cSidebarBlock_managing,
	.cSidebarBlock_managing:hover{
		opacity: 1;
	}

	/* Hover */
	.cSidebarBlock_managing:where(:hover){
		outline-color: var(--i-color_soft);
	}

	/* Active */
	.cWidgetContainer--menu_open.cWidgetContainer--isWidget .cSidebarBlock_managing{
		outline: 4px solid var(--i-primary);
	}




	/* ipsWidget__content--wrap--editing Is set while the widget is being edited, whether via the dialog or **inline**; in this case we don't want to show the dragging cursor */
	.cSidebarBlock_managing:not(.ipsWidget__content--wrap--editing > .cSidebarBlock_managing) {
		cursor: move;
	}

	.ipsWidget__content--wrap--editing > .cSidebarBlock_managing {
		background: none;
		flex-direction: column;
		gap: calc(4px + .4em);
		left: calc(10px + 100%) !important;
		inset: revert;
		top: 0;
		outline: none;
	}

	.ipsWidget__content--wrap--editing > .cSidebarBlock_managing > * {
		aspect-ratio: 1;
		outline: 3px solid var(--i-secondary);
		box-shadow: var(--i-dropdown--bo-sh);
	}

	.ipsWidgetBlank:not([hidden]) ~ .cSidebarBlock_managing {
		background: none;
	}

	.cSidebarBlock_managing .ipsButton--inherit {
		color: var(--i-color_hard);
		background-color: var(--i-background_4);
	}

	.cSidebarBlock_managing h4 {
		background: #000;
		color: #fff;
		font-weight: 600;
		padding: 0.6em 1em;
		border-radius: 6px;
		margin-inline-end: auto;
	}



.ipsWidget__content--wrap--editing .tiptap.ProseMirror {
	min-height: revert;
	padding: calc(var(--Widget__padding--pa, 1.5em) - 2px) !important; /* We take off 2px to account for the editor outline */
}

/* Menu open on a group */
.cWidgetContainer--isGroup.cWidgetContainer--menu_open{
	outline: 3px solid var(--i-primary);
	outline-offset: 2px;
	border-radius: var(--i-box--bo-ra);
}

/* Apply an outline to groups when a widget is dragged over them */
.cWidgetContainer--dragInside {
	outline: 3px solid var(--i-primary);
	outline-offset: 4px;
	border-radius: var(--i-box--bo-ra);
	transition: scroll-padding-left 0.2s ease-out;
}

:is(.cWidgetContainer--dragLeft,
.cWidgetContainer--dragRight,
.cWidgetContainer--dragBelow,
.cWidgetContainer--dragAbove):not(.ipsScrolling,.ipsScrolling > *) {
	z-index: var(--ips-js-zindex-top);
	transition: transform 0.2s ease-out;
}

.cWidgetContainer--dragLeft:not(.ipsScrolling,.ipsScrolling > *) {
	transform-origin: left;
	transform: translateX(calc(var(--i-block--transform-offset) * -1px));
}

.cWidgetContainer--dragRight:not(.ipsScrolling,.ipsScrolling > *) {
	transform-origin: right;
	transform: translateX(calc(var(--i-block--transform-offset) * 1px));
}

/* For carousel widget groups, because of the scroll, transforming the first scrolling child just moves the scrollable area so it doesn't look "transformed". nth-child(2) because the widget area menu is the first child */
.cWidgetContainer--carousel.cWidgetContainer--dragBeforeFirst {
	scroll-padding-inline-start: calc(var(--i-block--transform-offset) * 1px);
}

:not(:dir(rtl)).cWidgetContainer--carousel.cWidgetContainer--dragAfterLast > .cWidgetContainer__carousel-wrap > .cWidgetContainer {
	transform-origin: left;
	transform: translateX(calc(var(--i-block--transform-offset) * -1px));
}

:dir(rtl).cWidgetContainer--carousel.cWidgetContainer--dragAfterLast > .cWidgetContainer__carousel-wrap > .cWidgetContainer {
	transform-origin: right;
	transform: translateX(calc(var(--i-block--transform-offset) * 1px));
}

.cWidgetContainer--dragAbove:not(.ipsScrolling,.ipsScrolling > *) {
	transform-origin: top;
	transform: translateY(calc(var(--i-block--transform-offset) * 1px));
}

.cWidgetContainer--dragBelow:not(.ipsScrolling,.ipsScrolling > *) {
	transform-origin: bottom;
	transform: translateY(calc(var(--i-block--transform-offset) * -1px));
}


/* Remove .ipsWidget__content--wrap when widgets aren't being edited */
.cWidgetContainer--main:not(.cWidgetContainer_managing) .ipsWidget__content--wrap{
	display: contents;
}

.cWidgetContainer_managing .ipsWidget__content--wrap{
	height: 100%;
}

/* Ensure widgets occupy the full height of other widgets in the widget group. Useful in situations when some widgets have more content than others */
.cWidgetContainer--isWidget .ipsWidget{
	min-height: 100%;
}

/* Ensure empty widgets occupy some height so they don't collapse to 0px */
.cWidgetContainer_managing{
	min-height: 100px !important;
}

.cWidgetContainer > .cWidgetContainer__menu_region {
	position: absolute; /* This must be fixed so that menus for areas inside a scrollable container will show outside the scrollable container */
	z-index: 1;
	background-color: #0000;
	margin: calc(1em + 5px) 5px;
}

.cWidgetContainer.cWidgetContainer--menu_open > .cWidgetContainer__menu_region {
	z-index: 2;
	position: fixed;
	background-color: var(--i-background_1);
}

.cWidgetContainer__menu {
	z-index: 999;
	position: fixed;
	display: flex;
	padding: 5px;
	left: 50%;
	bottom: 26px;
	gap: 5px;
	transform: translateX(-50%);
	color: hsl(0 0% 100%);
	/* This breaks the backdrop filter on the dropout children */
	border-width: 0;
	border-radius: 10px;
	box-shadow: hsl(0 0% 0% / .2) 0px 6px 20px;
	background: hsl(0 0% 0% / .8);
	-webkit-backdrop-filter: blur(16px);
	backdrop-filter: blur(16px);

	animation-name: cWidgetContainer__menu;
	animation-duration: 0.4s;
}

.cWidgetContainer__menu.ipsMenu {
	top: revert;
}

.cWidgetContainer__menu--empty {
	display: none !important;
}

.cWidgetContainer__menu:not(#x)::before {
	content: none;
}

.cWidgetContainer__menu [disabled] {
	opacity: 0.5;
	filter: grayscale(1);
}

	/* This is an edge case. For the images widget, the dimentions are defined by the widget itself but we still want the carousel option, so we hide them */
	.cWidgetContainer__menu[data-widget-base^="app_cms_pagebuilderupload"] :is([data-role="area-min_size"], [data-role="area-gaps"]) {
		display: none;
	}

@keyframes cWidgetContainer__menu{
	0%, 100%{
		transform: translateX(-50%) scale(1);
	}
	50%{
		transform: translateX(-50%) scale(1.08);
	}
}

.cWidgetContainer__menu_dropout, .cWidgetContainer__menu_item {
	flex: 0 0 auto;
	width: 60px;
	position: relative; /* Ensure dropdowns are positioned correctly */
	display: grid;
	place-content: center;
	aspect-ratio: 1;
	border-radius: 6px;
}

/* This is necessary because the dropout panel is inside the toggle button. If the cursor:pointer applied directly to the toggler then the panel will also have it */
.cWidgetContainer__menu_dropout::after {
	content: "";
	width: 100%;
	opacity: 0;
	height: 100%;
	position: absolute;
	cursor: pointer;
	border-radius: inherit;
}

:is(.cWidgetContainer__menu_dropout, .cWidgetContainer__menu_item):hover, .cWidgetContainer__menu_dropout--open {
	background-color: hsl(0 0% 100% / .15);
}

.cWidgetContainer__menu_item[disabled] {
	pointer-events: none;
}

/* Some icons are wrapped in a button which affects their alignment */
:where(.cWidgetContainer__menu_dropout button){
	display: block;
}

.cBuilderSvg {
	--i-svg--st-wi: 4;
	--i-svg--co: hsl(0 0% 90% / .34);
	--i-svg--st: hsl(0 0% 90%);

	width: auto;
	height: 38px;
	display: block;
	color: var(--i-svg--co);
}

.cBuilderMenuText {
	height: 60px;
	padding: 1em;
	font-weight: bold;
	align-content: center;
}

.cWidgetContainer__menu [type="range"] {
	--i-co: currentColor;
	-webkit-appearance: none;
	appearance: none;
	background: transparent;
	cursor: ew-resize;
	width: 220px;
	border: 0;
	height: 1.4em;
	box-shadow: none;
	padding: 0;
	color: var(--i-co);
}

@media (any-hover:hover){
	.cWidgetContainer__menu :hover > [type="range"]{
		--_thumb--sc: 1;
	}
}

.cWidgetContainer__menu [type="range"]::-webkit-slider-runnable-track {
	background: currentColor;
	height: 1px;
	transition: .2s;
}
.cWidgetContainer__menu [type="range"]::-moz-range-track {
	background: currentColor;
	height: 1px;
	transition: .2s;
}

.cWidgetContainer__menu [type="range"]::-webkit-slider-thumb {
	-webkit-appearance: none;
	appearance: none;
	margin-top: -6px;
	background-color: var(--i-co);
	border: none;
	height: 12px;
	width: 12px;
	border-radius: 50%;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	outline: 2px solid var(--panel--ba-co);
}
.cWidgetContainer__menu [type="range"]::-moz-range-thumb {
	background-color: var(--i-co);
	border: none;
	height: 12px;
	width: 12px;
	border-radius: 50%;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	outline: 2px solid var(--panel--ba-co);
}

@media(hover:none){
	.cWidgetContainer__menu [type="range"]::-webkit-slider-thumb {
		width: 40px;
		height: 20px;
		margin-top: -10px;
		border-radius: 6px;
		transform: none;
	}
}

.cWidgetContainer__menu_dropout i.fas.fa-info-circle.ipsTitle--h4{
	display: none;
}

	.cWidgetContainer__menu [data-role="otherChildren"] {
		background: hsl(0 0% 0% / .8);
		color: hsl(0 0% 100%);
		transition: opacity 0.2s, bottom 0.2s;
		position: absolute;
		bottom: calc(100% - 10px);
		left: 0;
		display: flex;
		flex-direction: column;
		width: max-content;
		opacity: 0;
		pointer-events: none;
		border-radius: 10px;
		overflow: hidden; /* Crop the highlight color on hovered buttons */
	}

		/* Hover */
		.cWidgetContainer__menu_dropout--open [data-role="otherChildren"] {
			bottom: calc(100% + 8px);
			opacity: 1;
			pointer-events: auto;
			-webkit-backdrop-filter: blur(20px);
			backdrop-filter: blur(20px);
		}

	.cWidgetContainer__menu-icon--carousel-toggle{

	}

	.cWidgetContainer__menu .rangecontainer {
		flex-direction: column;
	}

	/* Pop-up menu options */
	.cWidgetContainer__menu-icon, :where(.cWidgetContainer__menu_dropout [data-role="otherChildren"] > *) {
		align-self: stretch;
		display: flex;
		align-items: center;
		gap: .8em;
		padding: .7em 1em;
		white-space: nowrap;
		color: #fff;
		/* font-weight: 600; */
	}

		.cWidgetContainer__menu-icon:hover{
			background-color: hsl(0 0% 100% / .1);
		}

		.cWidgetContainer__menu-icon[data-active]{
			background-color: hsl(0 0% 100% / .25);
		}

		/* Pseudo checkbox for Carousel option */
		.cWidgetContainer__menu-checkbox{
			width: 1.2em;
			height: 1.2em;
			border-radius: 4px;
			background: hsl(0 0% 100% / .3);
			border: 1px solid hsl(0 0% 100% / .2);
			display: grid;
			place-content: center;
			line-height: 1;
			margin-inline-start: auto;
			font-family: sans-serif; /* Needed to prevent emoji from showing */
		}

		.cWidgetContainer__menu-checkbox[data-checked]::before{
			content: '\2714';
			font-size: .7em;
		}

		/* Mini icons in pop-up menus */
		.cWidgetContainer__menu-icon .cBuilderSvg {
			height: auto;
			width: 22px;
			flex: 0 0 auto;
		}
		.cWidgetContainer__menu-icon--carousel-toggle > input[type="checkbox"] {
			cursor: pointer;
		}

	.cWidgetContainer .cWidgetContainer__menu_dropout:not(.cWidgetContainer__menu_dropout--down,.cWidgetContainer__menu_dropout--up) [data-role="otherChildren"],
	.cWidgetContainer .cWidgetContainer__menu_dropout:not(.cWidgetContainer__menu_dropout--down,.cWidgetContainer__menu_dropout--up) {
		height: 60px;
	}
	.cWidgetContainer .cWidgetContainer__menu_dropout:is(.cWidgetContainer__menu_dropout--down,.cWidgetContainer__menu_dropout--up) [data-role="otherChildren"],
	.cWidgetContainer .cWidgetContainer__menu_dropout:is(.cWidgetContainer__menu_dropout--down,.cWidgetContainer__menu_dropout--up) {
		width: 60px;
	}

	.cWidgetContainer__menu--label {
		cursor: revert;
	}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--down {
			flex-direction: column;
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--left {
			flex-direction: row-reverse;
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--up {
			flex-direction: column-reverse;
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--down [data-role="otherChildren"] {
			flex-direction: column;
			transform-origin: top;
			height: revert;
			width: inherit;
		}
		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--down:not(:hover) [data-role="otherChildren"] {
			transform: scaleX(1) scaleY(0);
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--up [data-role="otherChildren"] {
			flex-direction: column-reverse;
			transform-origin: bottom;
			height: revert;
			width: inherit;
		}
		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--up:not(:hover) [data-role="otherChildren"] {
			transform: scaleX(1) scaleY(0);
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--left [data-role="otherChildren"] {
			flex-direction: row-reverse;
			transform-origin: right;
		}

		.cWidgetContainer__menu_dropout.cWidgetContainer__menu_dropout--left:not(:hover) [data-role="otherChildren"] {
			transform: scaleX(0) scaleY(1);
		}

	.ipsWidget__content--wrap--editing {
		z-index: 3;
	}

	.ipsWidget__content--wrap--editing > .ipsWidget {
		display: grid;
	}

	.ipsWidget__content--wrap--editing :is(.ipsComposeArea_editor:not(.ipsComposeArea_minimized) [data-role="mainEditorArea"], .ipsEditor__tiptap-wrap) {
		padding: 0 !important;
		position: relative;
		min-height: fit-content !important;
		grid-template-rows: auto; /* By default, this is auto 1fr so that there is room for the toolbar, but for the inline editor the toolbar is displayed above the content so we just want auto */
	}

	.ipsWidget__content--wrap--editing .ipsEditor__toolbar--main {
		position: absolute;
		bottom: calc(20px + 100%);
		top: revert;
		min-height: fit-content;
		width: 100%;
		margin: 0;
		box-shadow: var(--i-dropdown--bo-sh);
		border-radius: var(--i-box--bo-ra);
		outline: 2px solid var(--i-primary);
	}

	.ipsWidget__content--wrap--editing > .ipsWidget :not(.ipsComposeArea_editor *),
	.ipsWidget__content--wrap--editing :is([data-role="editorComposer"], [data-role="mainEditorArea"], .ipsEditor),
	.ipsWidget__content--wrap--editing [data-role="mainEditorArea"] :not(.ipsEditor__toolbar, .ipsEditor__toolbar *, .tiptap *) {
		padding: 0;
		margin: 0;
		width: 100%;
		height: 100%;
	}

	.ipsWidget__content--wrap--editing .ipsEditor {
		border-radius: var(--i-box--bo-ra);
	}

	.ipsWidget__content--wrap--editing .ipsEditor__tiptap-wrap {
		box-shadow: var(--i-dropdown--bo-sh);
	}

	.ipsWidget__content--wrap--editing > .ipsWidget .ipsComposeArea_editor {
		width: 100%;
		height: 100%;
	}

	.ipsWidget__content--wrap--editing :is(
		.cSidebarBlock_managing,
		.ipsEditor__toolbar--main,
		[data-ipseditor-toollist]
	){
		z-index: calc(var(--ips-js-zindex-top) - 10);
	}

	.ipsWidget__content--wrap--editing .ipsComposeArea_editor [data-ipseditor-toollist] {
		bottom: revert;
		margin: 0;
		outline: 2px solid var(--i-primary);
		width: 100%;
		top: calc(20px + 100%);
		box-shadow: var(--i-dropdown--bo-sh);
		position: absolute;
		border-radius: var(--i-box--bo-ra);
		background-color: var(--i-background_1);
	}
	.ipsWidget__content--wrap--editing .ipsComposeArea_dropZone {
		margin: 0;
	}

.cSidebarBlock_loading {
	min-height: 120px;
}

