:root {
	--condition-title-width: 90px;
	--condition-line-width: 3px;
}

.cRulesForm {
	max-width: 100ch;
}

	.cRulesForm__condition{
		display: flex;
		flex-wrap: wrap;
		gap: 1em;
		align-items: baseline;
	}

	.cRulesForm__condition select {
		width: auto;
	}

	.cRulesForm__condition [type="number"]{
		width: 12ch;
	}

		.cRulesForm__condition__title {
			background: var(--i-primary);
			color: var(--i-primary-contrast);
			border-radius: 5px;
			width: 90px;
			padding-top: .3em;
			padding-bottom: .3em;
		}

		.cRulesForm__conditionButtons {
			color: var(--i-color_primary);
		}

			.cRulesForm_conditionWrap:not( .ipsHide ) + .cRulesForm__conditionButtons {
				padding-top: 1em;
			}

		.cRulesForm__conditionButton {
			color: inherit;
			padding: .4em 1em;
			border-radius: 5px;
			font-weight: 500;
			display: inline-flex;
			align-items: center;
			gap: .5em;
		}

			.cRulesForm__conditionButton:hover {
				background: var(--i-background_3);
			}

			.cRulesForm__conditionButton__icon {
				font-size: 10px;
			}

		.cRulesForm__condition__close {
			position: absolute;
			inset-inline-end: -6px;
			top: -6px;
			width: 1.8em;
			height: 1.8em;
			font-size: 12px;
			display: grid;
			place-content: center;
			border-radius: 50%;
			background: var(--i-base-contrast_2);
			color: var(--i-base_1);
		}

		.cRulesForm__condition__toDesc {
			margin-bottom: .4em;
		}

			.cRulesForm__condition__toDesc:empty {
				display: none;
			}

			.cRulesForm__assign-rewards :is(select, [type="number"]){
				margin: 0 .4em;
			}

	/* This used to be done using visibility:hidden in the style attribute directly but that caused issues */
	.cRulesForm [data-role="toggleFilter"] input[type="checkbox"][data-filter] {
		display: none;
	}

@media (min-width: 768px){
	.cRulesForm__container::before {
		content: '';
		width: 3px;
		background: var(--i-background_4);
		position: absolute;
		top: 40px;
		bottom: 40px;
		inset-inline-start: 6em;
	}
	.cRulesForm__conditionButtons {
		padding-inline-start: 6em;
	}
	.cRulesForm__condition--subCondition {
		margin-inline-start: 2em;
	}
}

/* Badges */
.ipsAchievementsBadge{
	display: inline-block;
	border-radius: 4px;
	border: 1px solid currentColor;
	color: var(--achievementsBadge--color, var(--i-color_hard));
	background: var(--achievementsBadge--background-color, var(--i-background_3));
	padding: .1em .6em;
	margin: 0 .1em;
	font-size: 95%;
}

[data-ips-scheme="dark"] .ipsAchievementsBadge{
	border-color: transparent;
}

.ipsAchievementsBadge--milestone{
	--achievementsBadge--color: #10967E;
	--achievementsBadge--background-color: #E5FDF9;
}

.ipsAchievementsBadge--location{
	--achievementsBadge--color: #8168BD;
	--achievementsBadge--background-color: #F4F0FF;
}

[data-ips-scheme="dark"] .ipsAchievementsBadge--milestone{
	--achievementsBadge--background-color: #10967E;
	--achievementsBadge--color: #E5FDF9;
}

[data-ips-scheme="dark"] .ipsAchievementsBadge--location{
	--achievementsBadge--background-color: #8168BD;
	--achievementsBadge--color: #F4F0FF;
}

.ipsControlStrip {
	display: flex;
	justify-content: end;
	gap: 4px;
}

.ipsControlStrip_button {
	flex: 1 1 auto;
}

/* Don't stretch buttons on large screens */
@media (min-width: 500px){
	.ipsControlStrip_button {
		flex: 0 0 auto;
	}
}

/* Only show first 3 buttons OR first 2 buttons + dropdown */
.ipsControlStrip_button--more,
.ipsControlStrip_button:nth-child(2) ~ .ipsControlStrip_button{
	display: none;
}
/* Show 3rd option if it's the last (excluding dropdown button) */
.ipsControlStrip_button:nth-child(3):nth-last-child(2),
/* Show more menu when 4+ options exist */
.ipsControlStrip_button:nth-child(4) ~ .ipsControlStrip_button--more{
	display: block;
}

.ipsControlStrip_button > a,
.ipsControlStrip_button > button{
	display: flex;
	align-items: center;
	justify-content: center;
	color: inherit;
	min-width: 2.4em;
	min-height: 2.4em;
	border-radius: 5px;
	width: 100%;
}

	.ipsControlStrip_disabled {
		background: transparent;
		pointer-events: none;
	}

		.ipsControlStrip_disabled .ipsControlStrip_icon {
			opacity: .5;
		}

	.ipsTree_row:hover :where(.ipsControlStrip_button > :is(a, button)) {
		background: var(--i-background_3);
	}

	@media (hover:none){
		.ipsControlStrip_button > :is(a, button):not(:hover){
			background: var(--i-background_3);
		}
	}

	.ipsControlStrip_button > :is(a, button):hover{
		color: var(--i-primary-contrast);
		background: var(--i-primary);
	}

/* Hide text but keep for screen readers */
:where(.ipsControlStrip:not(.ipsControlStrip_showText) .ipsControlStrip_item) {
	border: 0;
	clip-path: inset(50%);
	height: 1px;
	margin: -1px;
	overflow: hidden;
	padding: 0;
	position: absolute;
	white-space: nowrap;
	width: 1px;
}

/* Show text option */
.ipsControlStrip_showText a {
	width: auto;
	padding: 0 .7em;
}

.ipsControlStrip_item {
	font-size: .9em;
	margin-inline-start: .6em;
	font-weight: 600;
}

/* RESET FORM STYLES */
.ipsWidthHeight {
	background: #fff;
	border: 1px dashed #000;
	margin-bottom: 10px;
}
/* jQuery UI doesn't support resizing RTL */
[dir="rtl"] .ipsWidthHeight {
	display: none;
}

.ui-icon-gripsmall-diagonal-se {
	background: url('{resource="resizable.png" app="core" location="global" inCss="true"}');
}

.ui-resizable {
	position: relative;
}
.ui-resizable-handle {
	position: absolute;
	font-size: 0.1px;
	display: block;
}
.ui-resizable-se {
	cursor: nwse-resize;
	width: 12px;
	height: 12px;
	right: 0px;
	bottom: 0px;
}

/* Highlighted search result */
[data-ips-scheme="light"] .ipsFieldRow_searchResult {
	background-color: #f4e5c4;
	border-color: #ebc46f;
	color: #7a5206;
}
[data-ips-scheme="dark"] .ipsFieldRow_searchResult {
	background-color: #534531;
	border-color: #786743;
	color: #f8e5d4;
}

/* Convert the Badge creator form into a grid UI */
[data-controller="ips.core.badgepreview"] svg {
    width: 180px;
}

@media (min-width: 1100px){
	.ipsBadgePicker--form {
		display: grid;
		grid-template-columns: 220px 1fr 1fr 1fr 1fr 1fr 1fr;
	}

		:where(.ipsBadgePicker--form > li){
			grid-column: 1/-1;
		}

		.ipsFieldRow--badge-creator-preview .ipsFieldRow__content{
			position: sticky;
			top: 90px;
		}

		.ipsFieldRow--badge-creator {
			grid-column: span 2;
			align-content: start !important;
		}

		.ipsFieldRow--badge-creator:not(.ipsHide, [hidden]){
			display: grid !important;
			grid-template-columns: 1fr !important;
		}

			.ipsFieldRow--badge-creator .ipsFieldRow__label{
				text-align: start !important;
				display: flex !important;
			}

			.ipsFieldRow--badge-creator .ipsFieldRow__required{
				flex: 0 0 auto !important;
			}

			.ipsFieldRow--badge-creator .sp-colorize{
				max-width: none;
			}

		.ipsFieldRow--badge-creator-preview:not([hidden], .ipsHide, #x) {
			grid-column: 1/2;
			grid-row-end: span 5;
			display: block !important;
		}
		.ipsFieldRow--badge-creator-preview > .ipsFieldRow__content {
			padding: 1em;
		}

		.ipsFieldRow--badge-creator-icon {
			grid-column: span 4;
		}

		.ipsBadgePicker--include-number-overlay .ipsFieldRow--badge-creator-icon {
			grid-column: span 2;
		}

		[data-controller="ips.core.badgepreview"] svg,
		.ipsFieldRow--badge-creator .sp-colorize-container{
			width: 100%;
		}

		.ipsFieldRow--badge-creator [data-controller="core.admin.core.nodeCopySetting"] {
			display: none;
		}
}

[data-controller="ips.core.badgepreview"] svg {
	-webkit-filter: drop-shadow( 2px 2px 4px var(--i-color_root));
	filter: drop-shadow( 2px 2px 4px var(--i-color_root));
}

/* Remove redundant borders and improve spacing for tabbed content, ie. ACP > Settings */
.acpFormTabContent .ipsBox{
	border-width: 0;
	border-radius: 0;
}

/* Sticky submit row */
.ipsSubmitRow{
	position: -webkit-sticky;
	position: sticky;
	bottom: 0;
	z-index: 3; /* High enough to overlap editor */
}

/* When an editor dropdown menu is open, increase the z-index of the toolbar to ensure the toolbar/dropdown sits above the sticky .ipsSubmitRow element */
.ipsEditor__toolbar--main:has(.ipsEditor__anchored-panel:not([hidden])){
	z-index: 4;
}

/* Remove sticky footer when selectTree is active, otherwise the footer overlaps it */
.ipsForm:has(.ipsSelectTree_active) + .ipsSubmitRow{
	position: static;
}

/* Overwrite front-end variables */
:root{
	--i-layout-gutter: 15px;
}

/* ACP Charts */
svg[style*="hidden"] rect[fill="#ffffff"],
svg[style*="hidden"] path[fill="#ffffff"]{
	fill: var(--i-background_1);
}

svg[style*="hidden"] rect[fill="#edf0f5"]{
	fill: var(--i-background_1);
}

svg[style*="hidden"] text[fill="#444444"]{
	fill: var(--i-color_soft);
}

svg[style*="hidden"] text[fill="#222222"]{
	fill: var(--i-color_hard);
}

svg[style*="hidden"] text[fill="#000000"]{
	fill: var(--i-color_hard);
}

svg[style*="hidden"] rect[width="1"],
svg[style*="hidden"] rect[height="1"]{
	fill: var(--i-background_3);
}

#elLogo {
	height: 62px;
	display: flex;
	align-items: center;
	justify-content: center;
}

	#elLogo img {
		width: 30px;
	}

#acpAppList .ipsNotification {
	top: 3px;
	inset-inline-end: 3px;
}

	#acpAppList .acpAppList__sub .ipsNotification {
		position: static;
		margin-inline-start: 1em;
	}

/* Hide menu stuff */
#acpAppList #elHideMenu {
	width: 16px;
	height: 32px;
	line-height: 32px;
	position: fixed;
	bottom: 0;
	z-index: 6000;
	background: var(--i-background_1);
	border-radius: 5px 0 0 0;
}

	#acpAppList #elHideMenu a{
		color: inherit !important;
	}

	body.cAdminDevModeOn #acpAppList #elHideMenu {
		bottom: 60px;
	}

	#acpAppList #elHideMenu {
		inset-inline-start: 54px;
		inset-inline-start: calc(60px - 16px);
	}

	#acpAppList #elHideMenu a {
		padding: 0 !important;
		height: 100% !important;
	}

/* ACP search bar */
.acpSearch{
	background: var(--i-background_3);
	color: var(--i-color_root);
	border-radius: 6px;
	flex: 1 1 100%;
	display: flex;
	align-items: center;
	height: 41px;
	margin-inline-end: 10px;
}

	.acpSearch:focus-within {
		background: var(--i-background_1);
		outline: 2px solid var(--i-primary);
		outline-offset: -1px;
	}

	.acpSearch .fa-magnifying-glass{
		margin: 0 1em;
		opacity: .6;
	}

	#acpSearchKeyword {
		border: 0;
		background: transparent;
		max-width: 100%;
		padding: .75em 0;
		color: inherit;
		box-shadow: none;
		flex: 1 1 100%;
		outline: none;
	}

	@media (hover: none) and (max-width: 1024px) {
		#acpSearchKeyword{
			font-size: max(16px, 1em);
		}
	}

	#acpSearchKeyword::-webkit-input-placeholder {
		color: var(--i-color_soft);
		opacity: 1;
	}
	#acpSearchKeyword::placeholder {
		color: var(--i-color_soft);
		opacity: 1;
	}

	.acpSearch__close{
		display: none;
	}

/* Admin controls */
#elAdminControls {
	display: flex;
	align-items: center;
	flex: 0 0 auto;
	font-size: 13px;
	font-weight: 600;
	margin-inline-start: auto;
}

	#elAdminControls > li > a,
	#elAdminControls > li > button {
		color: inherit;
		display: flex;
		align-items: center;
		gap: .5em;
		padding: 0 15px;
		border-radius: 4px;
		min-height: 40px;
	}
	@media (hover){
		#elAdminControls > li > a:hover,
		#elAdminControls > li > button:hover {
			background: var(--i-background_3);
		}
	}

		.acpHighlightLink_wrap{
			position: relative;
		}

		#elAdminControls .acpHighlightLink {
			color: hsl(129 70% 40%);
		}
		[data-ips-scheme="dark"] #elAdminControls .acpHighlightLink {
			color: hsl(129 60% 70%);
		}

			#elAdminControls .acpHighlightLink_wrap:hover .acpHighlightLink{
				background: color-mix(in srgb, currentColor 12%, transparent);
			}

		#elAdminControls .acpHighlightLink_close{
			position: absolute;
			top: -6px;
			inset-inline-end: -6px;
			opacity: 0;
		}

		#elAdminControls .acpHighlightLink_close a{
			font-size: 11px;
			width: 1.9em;
			height: 1.9em;
			display: flex;
			justify-content: center;
			align-items: center;
			border-radius: 20px;
			color: #fff;
			background: hsl(129 30% 50%);
		}

		[data-ips-scheme="dark"] #elAdminControls .acpHighlightLink_close a{
			background: hsl(129 40% 30%);
		}

			#elAdminControls .acpHighlightLink_wrap:hover .acpHighlightLink_close{
				opacity: 100%;
			}

			#elAdminControls .acpHighlightLink_close i{
				opacity: 1;
			}

	/* Notifications icon */
	#elAdminControls .ipsNotification{
		top: 0;
		inset-inline-end: 0;
	}

	#elAdminControls .fa-angle-down{
		opacity: .5;
		font-size: .8em;
	}

	#elAdminUser{
		padding: 0 15px;
		cursor: pointer;
	}

		#elAdminUser .ipsUserPhoto{
			width: 36px;
			display: inline-block;
			vertical-align: middle;
		}

	#elAdminControls .ipsUserPhoto{
		margin: 0;
		margin-inline-end: 5px;
	}

/* Page titles */
#acpPageHeader {
	padding: 25px 15px 10px 15px;
	position: relative;
}

	#acpPageHeader .ipsType_pageTitle {
		color: inherit;
		font-weight: 500;
		font-size: 26px;
		min-width: 0;
	}

	.ipsBreadcrumb--acp {
		margin-bottom: 10px;
	}

.acpPageHeader_flex {
	display: flex;
	justify-content: space-between;
	flex-wrap: wrap;
	align-items: center;
	gap: 1em;
}

/* Main content area */
#acpContent {
	padding: 15px var(--i-layout-gutter);
	/* Bad idea? */
	display: flex;
	flex-direction: column;
	gap: 1em;
}

/* Prevent content areas from collapsing (Statistics overview) */
#acpContent > *{
	flex: 0 0 auto;
}
	.acpNoPadding #acpContent {
		padding: 0;
	}

	/* Non-responsive pages don't display properly */
	#acpContent > .ipsResponsive_hidePhone {
		display: flex;
		flex-direction: column;
		gap: 1em;
	}

/* Password hovercard */
.ipsHovercard[data-role="advicePopup"] {
    display: none;
	width: 300px;
}
	.ipsHovercard[data-role="advicePopup"] > div {
		min-height: 60px;
	}
		.ipsHovercard[data-role="advicePopup"] > div .ipsTitle {
			font-size: 16px;
		}

.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem {
	right: 100%;
	top: 25px;
}
	.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem:before {
		border-right-color: inherit;
		left: -1px;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_ltr .ipsHovercard_stem:after {
		border-right-color: var(--i-background_3);
	}

.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem {
	left: 100%;
	top: 25px;
	border-left-color: inherit;
}
	.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem:before {
		border-left-color: inherit;
		right: -1px;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_rtl .ipsHovercard_stem:after {
		border-left-color: var(--i-background_3);
	}

.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem {
	left: 50%;
	margin-inline-start: -15px;
	top: 100%;
}
	.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem:before {
		border-top-color: inherit;
		bottom: -1px;
	}
	.ipsHovercard[data-role="advicePopup"].cStem_above .ipsHovercard_stem:after {
		border-top-color: var(--i-background_3);
	}

/* Hover fallbacks for non-js */
.ipsJS_none #acpAppList:hover > li:not( #elReorderAppMenu ) > a {
	background: transparent;
}

.ipsJS_none #acpAppList > li:not( #elReorderAppMenu ):hover > a {
	color: #fff;
	background: #394248;
}

.ipsJS_none #acpAppList:hover > li > .acpAppList__sub {
	display: none;
}

.ipsJS_none #acpAppList > li:hover > a + .acpAppList__sub {
	display: block;
	opacity: 1;
}

/* MISC */
.cACPkeywords{
	--_co: currentColor;
	color: inherit;
	background: var(--i-background_3);
	background: color-mix(in srgb, var(--_co) 10%, transparent);
	font-weight: 700;
	cursor: pointer;
}
#acpPageHeader .cACPkeywords{
	font-size: 12px;
	vertical-align: middle;
	margin-inline-start: 1em;
}
.ipsTabs .cACPkeywords{
	margin-inline-start: 1em;
}
.ipsFieldRow__label .cACPkeywords:not(.ipsFieldRow__required ~ *){
	margin-inline-start: auto;
}


/* NOTIFICATIONS */

.cAcpNotifications {
	font-size: 20px;
	position: relative;
}

@keyframes notificationAnimate
{
    0% {transform: rotateZ(8deg) scale(1);}
    20% {transform: rotateZ(-8deg) scale(1.2);}
    40% {transform: rotateZ(8deg) scale(1.4);}
    60% {transform: rotateZ(-8deg) scale(1.4);}
    80% {transform: rotateZ(8deg) scale(1.2);}
    100% {transform: rotateZ(0deg) scale(1);}
}

.cAcpNotifications_animate {
	animation: notificationAnimate 0.8s ease;
}

.cNotification_error {
	border-inline-start: 7px solid var(--i-color_negative);
}
.cNotification_warning {
	border-inline-start: 7px solid var(--i-color_warning);
}
.cNotification_information {
	border-inline-start: 7px solid var(--i-secondary);
}
.cNotification_expire {
	border-inline-start: 7px solid var(--i-background_5);
}

/* NEW FEATURES TOUR */
.acpNewFeature {
	position: fixed;
	inset: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: none;
}

.acpNewFeature_wrap {
	width: 340px;
	height: 475px;
	background: var(--i-background_2);
	border-radius: 3px;
	box-shadow: 0px 5px 35px rgba(0,0,0,0.1);
	position: relative;
	pointer-events: auto;
}

	.acpNewFeature_inner {
		position: absolute;
		padding: 20px;
		inset: 0;
		overflow: hidden;
	}

.acpNewFeature_mainTitle {
	font-size: 17px;
	color: var(--i-color_root);
	font-weight: 400;
	text-align: center;
	margin: 0;
}

.acpNewFeature_cardWrap {
	margin: 20px 0;
	position: relative;
}

	.acpNewFeature_card {
		position:absolute;
		inset: 0;
	}

.acpNewFeature_dots {
	text-align: center;
	position: absolute;
	bottom: 10px;
	left: 20px;
	right: 20px;
}

	.acpNewFeature_dot {
		display: inline-block;
	}

	.acpNewFeature_dot > a {
		display: block;
		border: 1px solid #3D6594;
		border-color: var(--i-primary);
		border-radius: 11px;
		width: 11px;
		height: 11px;
		margin-inline-end: 2px;
	}

		.acpNewFeature_dot.acpNewFeature_active > a {
			background: #3D6594;
			background: var(--i-primary);
		}

	.acpNewFeature_dot:last-child > a {
		margin-inline-end: 0;
	}

.acpNewFeature_info {
	text-align: center;
}

.acpNewFeature_title {
	text-align: center;
	font-size: 17px;
	margin-bottom: 0;
	margin-top: 20px;
}

.acpNewFeature_desc {
	text-align: center;
	font-size: 14px;
	margin-top: 10px;
	opacity: 0.8;
	max-height: 150px;
	overflow-y: auto;
}

.acpNewFeature_image {
	width: 340px;
	height: 150px;
	margin-inline-start: -20px;
	background: var(--i-background_4);
	border-top: 1px solid rgba(0,0,0,0.1);
	border-bottom: 1px solid rgba(0,0,0,0.1);
}

.acpNewFeature_close {
	background: #111;
	color: #fff;
	font-family: 'arial', sans-serif;
	font-size: 19px;
	font-weight: 300;
	width: 30px;
	height: 30px;
	border-radius: 30px;
	line-height: 30px;
	display: block;
	position: absolute;
	top: -10px;
	inset-inline-end: -10px;
	text-align: center;
	z-index: 100;
}

	.acpNewFeature_close:hover {
		color: #fff;
	}

.acpNewFeature_arrow {
	font-size: 50px;
	color: #fff;
	position: absolute;
	top: 50%;
	margin-top: -30px;
	transition: 0.2s all ease-in-out;
	width: 60px;
	height: 60px;
	text-align: center;
}

	.acpNewFeature_arrow:hover {
		color: #fff;
	}

	.acpNewFeature_prev {
		inset-inline-start: -60px;
	}
	.acpNewFeature_next {
		inset-inline-end: -60px;
	}

/* PHONES */
@media screen and (max-width: 767px) {
	.acpNewFeature_arrow {
		top: auto;
		bottom: -70px;
	}
	.acpNewFeature_prev {
		inset-inline-start: 20%;
	}
	.acpNewFeature_next {
		inset-inline-end: 20%;
	}
}

/* Data rows */
.ipsDataItem{
	border-bottom-color: var(--i-background_3);
}

/* Hover cards */
/* USER HOVERCARDS */
.cUserHovercard {
	min-height: 200px;
}

.cUserHovercard .ipsPageHead_special {
	background-repeat: no-repeat;
	background-size: cover;
	background-position: bottom;
	height: 85px;
	width: 100%;
	background-color: var(--i-background_dark);
}

.cUserHovercard .ipsPageHead_special .ipsUserPhoto {
	position: absolute;
	top: 35px;
	inset-inline-start: 15px;
}

.cUserHovercard .ipsPageHead_special .ipsType_sectionHead, 
.cUserHovercard .ipsPageHead_special p {
	position: absolute;
	color: #fff;
	inset-inline-start: 110px;
}
.cUserHovercard .ipsPageHead_special p {
	top: 60px;
}

.cUserHovercard .ipsPageHead_special .ipsTitle {
	top: 28px;
	font-size: 24px;
	max-width: 325px;
	line-height: 36px;
}

.cUserHovercard .cUserHovercard_data {
	max-width: 330px;
	margin-inline-start: 105px;
}

.cUserHovercard .ipsRepBadge {
    width: 80px;
    position: absolute;
    top: 120px;
    text-align: center;
	inset-inline-start: 20px;
}

/* Fix white corners on color pickers in the theme settings */
.sp-colorize-container{
	border-radius: 4px;
}

/*
	V5 ACP Layout
*/

.cAdminDevModeWarning {
	display: grid;
	place-content: center;
	position: fixed;
	bottom: 8px;
	inset-inline-start: 8px;
	width: 2.3em;
	height: 2.3em;
	background: #f4b738;
	font-size: 18px;
	color: #fff;
	z-index: 5010;
	transition: 0.2s background ease-in-out;
	border-radius: 5px;
}

	.cAdminDevModeWarning:hover {
		color: #fff;
		background: #ce9929;
		cursor: help;
	}

/* Columns */
#acpMainLayout{
	display: flex;
}

:root{
	--acp-nav--ba-co: #0e1d30;
	--acp-sub--ba-co: var(--i-background_1);
}
[data-ips-scheme="dark"]{
	--acp-nav--ba-co: var(--i-background_1);
	--acp-sub--ba-co: var(--i-background_2);
}

#acpAppMenu{
	--menu-width: 220px;
	--icon-width: 60px;
	background: var(--acp-nav--ba-co);
	position: sticky;
	top: 0;
	align-self: start;
	height: 100vh;
	flex: 0 0 calc(var(--menu-width) + var(--icon-width));
}

#acpAppList{
	overflow: auto;
	height: 100vh;
	display: flex;
	flex-direction: column;
	overscroll-behavior: contain;
}

@media (max-width: 1899px){
	/* Cater for Development Mode icon */
	.cAdminDevModeOn #acpAppList{
		padding-bottom: 60px;
	}
}

	#acpAppList .ipsScrollbar::-webkit-scrollbar-thumb { 
		background-color: rgba(0,0,0,0.05);
	}
	#acpAppList:hover .ipsScrollbar::-webkit-scrollbar-thumb { 
		background-color: rgba(0,0,0,0.2);
	}
	#acpAppList .ipsScrollbar::-webkit-scrollbar-track-piece { 
		background-color: transparent;
	}

	.acpAppList_icon {
		font-size: 20px;
	}

	.acpAppList__label{
		display: none;
	}

	#acpAppList > li {
		width: var(--icon-width);
		flex: 0 0 auto;
	}

		#acpAppList > li > a {
			display: flex;
			justify-content: center;
			align-items: center;
			height: var(--icon-width);
			color: rgba(255,255,255,0.7);
			position: relative;
			font-weight: 550;
		}

			#acpAppList > li.acpAppList_dragging .acpAppList__sub {
				display: none !important;
			}

			#acpAppList > li.acpAppList_active > a {
				color: #fff;
				background: rgba(255,255,255,0.05);
			}

		#acpAppList > li.acpAppList_active .acpAppList__sub {
			display: block;
		}

		.acpAppList__sub {
			color: var(--i-color_soft);
			background: var(--acp-sub--ba-co);
			border-inline-end: 1px solid var(--i-background_4);
			width: var(--menu-width);
			position: absolute;
			top: 0;
			bottom: 0;
			inset-inline-start: var(--icon-width);
			display: none;
			z-index: 3500;
			line-height: 1.8;
		}

		.acpAppList__sub > ul{
			position: sticky;
			top: 0;
			max-height: 100vh;
			overflow-y: auto;
			overscroll-behavior: contain;
		}

			:where(.acpAppList__sub > ul) > li{
				margin-bottom: 1em;
				padding: 0 1em;
			}

			.acpAppList_header {
				color: var(--i-color_hard);
				font-size: 17px;
				font-weight: 600;
				display: block;
				line-height: 61px;
				padding-inline-start: 1.5em;
				white-space: nowrap;
				overflow: hidden;
				text-overflow: ellipsis;
				margin: 0;
			}

			.acpAppList__sub a {
				color: var(--i-color_soft);
				display: block;
				padding: .25em 1em;
				border-radius: 5px;
			}

				.acpAppList__sub a:hover{
					color: var(--i-color_hard);
					background: var(--i-background_2);
				}

				:where([data-ips-scheme="dark"]) .acpAppList__sub a:hover{
					background: var(--i-background_3);
				}

				.acpAppList__sub .acpAppListItem_active a{
					color: var(--i-color_hard);
					background: var(--i-background_3);
					font-weight: 600;
				}

				:where([data-ips-scheme="dark"]) .acpAppList__sub .acpAppListItem_active a{
					background: var(--i-background_4);
				}

			.acpAppList__sub h3 {
				color: var(--i-color_hard);
				padding: 1em;
				padding-bottom: 0;
				text-transform: uppercase;
				font-weight: bold;
				background: var(--acp-sub--ba-co);
				position: -webkit-sticky;
				position: sticky;
				top: 0;
				z-index: 1;
			}

			.acpAppList__sub > li {
				margin-bottom: 20px;
			}

			.acpAppList__sub .acpModuleMenu_active {
				font-weight: bold;
			}

/* Wider menu on larger screens */
@media (min-width: 1900px){
	#acpAppMenu{
		--icon-width: 250px;
		--menu-width: 280px;
	}
	#elLogo{
		justify-content: start;
	}
	.acpAppList_icon{
		font-size: 1.2em;
		flex: 0 0 1.4em;
		text-align: center;
		margin-inline-end: .6em;
	}
	#acpAppList > li > a{
		height: auto;
		padding: 1em;
		justify-content: start;
		margin-inline: 1em;
		border-radius: 5px;
	}
	.acpAppList__label{
		display: block;
	}
	.acpAppList_header{
		display: none;
	}
	#acpAppList .ipsNotification {
		position: static;
		margin-inline-start: auto;
	}
}

/* Reorder navigation */
#elReorderAppMenu {
	margin-top: auto;
	padding: 8px;
	display: flex;
}

/* Move icon to bottom right on large screens */
@media (min-width: 1900px){
	#elReorderAppMenu{
		justify-content: end;
	}
}

/* Reorder/save buttons */
#elReorderAppMenu button{
	width: 2.3em;
	height: 2.3em;
	display: grid;
	place-content: center;
	font-size: 18px;
}

/* Drag handles */
[data-role="reorder"] {
	border-radius: 50%;
	font-size: 11px;
	width: 2em;
	height: 2em;
	line-height: 2em;
	text-align: center;
	display: block;
	cursor: grab;
	pointer-events: auto;
	position: absolute;
	inset-inline-end: 0;
}

	/* Drag handles on icons */
	#acpAppList > li > a > [data-role="reorder"] {
		background: #f5f5f5;
		color: #000;
		top: calc(50% - 9px);
		inset-inline-end: 5px;
		z-index: 3;
	}

/* Grab cursor */
#acpAppList > .ui-sortable-handle,
.acpAppList__sub .ui-sortable > li{
	cursor: grab;
}
.ui-sortable-handle .acpAppList__sub{
	cursor: initial;
}
/* Submenus */
.acpAppList__sub .ui-sortable > li:hover{
	background: var(--i-background_2);
}
/* Remove sticky headers */
.acpAppList__sub .ui-sortable h3{
	background: none;
	position: relative;
}
/* Placeholders while dragging */
.acpAppList__sub .ui-sortable-placeholder{
	outline: 2px solid currentColor;
	outline-offset: -4px;
	visibility: visible !important;
	z-index: 1001;
	position: relative;
	border-radius: 10px;
	opacity: .3;
	pointer-events: none;
}
/* Prevent links from being clicked while reordering menus */
#acpAppList .ui-sortable-handle a{
	pointer-events: none;
}

	/*
		Hide the reorder icon for the logo since it can't be repositioned
		!important is needed to overwrite inline style tag
	*/
	#acpAppList #elLogo [data-role="reorder"]{
		display: none !important;
	}

#acpMainArea{
	flex: 1 1 100%;
}

/* Header */
#ipsLayout_header {
	background: var(--i-background_1);
	color: var(--i-color_hard);
	display: flex;
	align-items: center;
	position: sticky;
	top: 0;
	z-index: var(--i-z-index_headerPrimary);
	box-sizing: content-box;
	height: 61px;
	padding: 0 10px;
	padding-top: env(safe-area-inset-top);
	box-shadow: hsl(0 0% 0% / .1) 0px 1px 0px 0px;
}

/* Mobile */
@media (max-width: 979px){
	#acpAppMenu{
		display: none;
	}
}

#acpLiveSearchResults {
	--_offset: 10px;
	width: min(100vw - 10px - var(--_offset), 750px);
	top: 70px;
	inset-inline-start: var(--_offset);
	position: fixed;
	background: var(--i-background_1);
	border-radius: 5px;
	box-shadow: 0px 10px 40px rgba(0,0,0,0.2);
}

/* Reposition dropdown on larger screens */
@media (min-width: 980px){
	#acpLiveSearchResults {
		--_offset: 280px;
	}
}
@media (min-width: 1900px){
	#acpLiveSearchResults {
		--_offset: 530px;
	}
}

	.cAcpSearch_areas,
	.cAcpSearch_results {
		padding: 6px;
	}

		.cAcpSearch_areas a{
			border-radius: 4px;
		}

		.cAcpSearch_results [data-role="result"]:not([class]) a,
		.cAcpSearch_results [data-role="result"][class=""] a{
			display: block;
			padding: .7em 1em;
			border-radius: 5px;
			color: var(--i-color_hard);
		}

			.cAcpSearch_results [data-role="result"]:not([class]) a:hover,
			.cAcpSearch_results [data-role="result"][class=""] a:hover{
				background: var(--i-background_2);
			}

	#acpLiveSearchResults [data-role="searchMenu"] {
		background: var(--i-background_2);
		border-inline-end: 1px solid var(--i-background_4);
		border-start-start-radius: 5px;
		border-end-start-radius: 5px;
	}

#acpLiveSearchResults::before {
	content: '';
	display: block;
	border-width: 7px;
	border-style: solid;
	border-color: transparent;
	border-bottom-color: var(--i-background_2);
	position: absolute;
	top: -14px;
	inset-inline-start: 23px;
	width: 0;
	height: 0;
	pointer-events: none;
}

#acpLiveSearchResults [data-resultsSection],
#acpLiveSearchResults [data-role="searchResults"] {
	overflow: auto;
	height: 100%;
}

#acpLiveSearchResults .ipsPadding_top {
	padding-top: 2px;
}

.cAcpSearch_areas .ipsSideMenu_item:not(.ipsSideMenu_itemActive) .ipsSideMenu_itemCount{
	background: var(--i-background_4);
	color: inherit;
}

/* Hide "No results" message when results are visible */
.cAcpSearch_results [data-resultssection]:not([style*="none"]) ~ .cAcpSearch_none{
	display: none;
}

@media (max-width: 519px){
	.cAcpSearch{
		max-height: calc(100vh - 80px);
		max-height: calc(100svh - 80px);
		overflow: auto;
	}
	/* Inlined categories */
	.cAcpSearch_areas .ipsSideMenu_list{
		display: flex;
		flex-wrap: wrap;
	}
	/* Hide inactive categories */
	.cAcpSearch_areas .ipsSideMenu_itemDisabled{
		display: none;
	}
}

@media (min-width: 520px){
	.cAcpSearch{
		display: grid;
		grid-template-columns: 1fr 2fr;
		max-height: 600px;
		height: 80vh;
	}
	.cAcpSearch > *{
		overflow: auto;
	}
}

/*
	----------------
	- Boxes
	----------------
*/

/* Make box headers smaller */
.ipsBox__header{
	font-size: 1em;
}
/* Icons */
.ipsBox__header-icon{
	color: var(--i-color_soft);
	font-size: .9em;
}
/* Faint secondary links */
.ipsBox__header-secondary{
	color: var(--i-color_soft);
	font-size: inherit;
}


/* Dashboard: Collapse widgets */
[data-widgetCollapse]{
	cursor: pointer;
}

	[data-widgetCollapse] .fa-caret-down{
		transition: .2s;
		margin-inline-end: .4em;
	}

	.ipsBox:has([data-widgetcollapsed="true"]) [data-widgetCollapse] .fa-caret-down{
		transform: rotate(-.25turn);
	}

/* Dashboard: Smart Community header */
.ipsBox.ipsBox--smart-community-splash {
	border: none;
	border-radius: 0;
	box-shadow: none;
}


/* Table search */
.acpTable_search {
	flex: 1 1 auto;
	display: grid;
	grid-template-columns: 3em auto 40px;
	width: 300px;
	max-width: calc(100vw - 40px);
}

	.acpTable_search .fa-magnifying-glass{
		grid-column: 1;
		grid-row: 1;
		z-index: 1;
		place-self: center;
		pointer-events: none;
	}

	.acpTable_search input{
		--i-outline-color: var(--i-primary);
		background: color-mix(in srgb, currentColor 12%, transparent);
		color: var(--i-co);
		padding: .8em 1.2em;
		padding-inline-start: 3em;
		border-radius: 5px;
		grid-column: 1/-1;
		grid-row: 1;
	}

	.acpTable_search:hover input{
		background: color-mix(in srgb, currentColor 20%, transparent);
	}

	.acpTable_search ::placeholder{
		opacity: 1;
		text-transform: uppercase;
	}

	.acpWidgetSearch {
		display: grid;
		place-content: center;
		color: var(--i-color_soft);
		grid-column: 3;
		grid-row: 1;
	}

		.acpWidgetSearch:hover {
			color: var(--i-color_hard);
		}

/* Apple pie chart */
.ipsPieBar__bar {
	height: 38px;
	background: #ddd;
	overflow: hidden;
	white-space: nowrap;
	display: flex;
	border-radius: 5px;
	position: relative;
}

.ipsPieBar__barSegment {
	height: 38px;
}

.ipsList--inline > .ipsPieBar__legendItem {
	display: inline-flex;
	align-items: center;
}

.ipsPieBar__barSegment:nth-child(10n-9),
.ipsPieBar__legendItem:nth-child(10n-9) > .ipsPieBar__legendItemKey {
	background: #10967e;
}
.ipsPieBar__barSegment:nth-child(10n-8),
.ipsPieBar__legendItem:nth-child(10n-8) > .ipsPieBar__legendItemKey {
	background: #ea7963;
}
.ipsPieBar__barSegment:nth-child(10n-7),
.ipsPieBar__legendItem:nth-child(10n-7) > .ipsPieBar__legendItemKey {
	background: #de6470;
}
.ipsPieBar__barSegment:nth-child(10n-6),
.ipsPieBar__legendItem:nth-child(10n-6) > .ipsPieBar__legendItemKey {
	background: #6b9dde;
}
.ipsPieBar__barSegment:nth-child(10n-5),
.ipsPieBar__legendItem:nth-child(10n-5) > .ipsPieBar__legendItemKey {
	background: #b09be4;
}
.ipsPieBar__barSegment:nth-child(10n-4),
.ipsPieBar__legendItem:nth-child(10n-4) > .ipsPieBar__legendItemKey {
	background: #eec766;
}
.ipsPieBar__barSegment:nth-child(10n-3),
.ipsPieBar__legendItem:nth-child(10n-3) > .ipsPieBar__legendItemKey {
	background: #9fc973;
}
.ipsPieBar__barSegment:nth-child(10n-2),
.ipsPieBar__legendItem:nth-child(10n-2) > .ipsPieBar__legendItemKey {
	background: #e291bf;
}
.ipsPieBar__barSegment:nth-child(10n-1),
.ipsPieBar__legendItem:nth-child(10n-1) > .ipsPieBar__legendItemKey {
	background: #55c1a6;
}
.ipsPieBar__barSegment:nth-child(10n),
.ipsPieBar__legendItem:nth-child(10n) > .ipsPieBar__legendItemKey {
	background: #5fb9da;
}

.ipsPieBar__legend {
	text-align: start;
    margin-top: 10px;
}

.ipsPieBar__legendItemKey {
	display: inline-block;
	width: 14px;
	height: 14px;
	margin-inline-end: 4px;
	border-radius: 5px;
}

/* Loading */
.icon-spinner2:before,
.ipsLoading:before{
	border-color: var(--i-background_3);
	border-top-color: var(--i-color_root);
}

/* Stats bar */
.acpStatsBar {
	height: 38px;
	background: #ddd;
	overflow: hidden;
	white-space: nowrap;
	display: flex;
	border-radius: 5px;
	position: relative;
}

	.acpStatsBar::after{
		content: '';
		position: absolute;
		inset: 0;
		border: 1px solid color-mix(in srgb, var(--i-color_hard) 15%, transparent);
		border-radius: inherit;
		pointer-events: none;
	}

	.acpStatsBar_segment,
	.acpStatsBar_subsegment {
		height: 38px;
	}

	.acpStatsBar_subsegment {
		background: rgba(0,0,0,0.2);
	}

	.ipsList--inline > .acpStatsBar_legend{
		display: inline-flex;
		align-items: center;
	}

	.acpStatsBar_segment:nth-child(10n-9),
	.acpStatsBar_legend:nth-child(10n-9) > .acpStatsBar_preview {
		background: #10967e;
	}
	.acpStatsBar_segment:nth-child(10n-8),
	.acpStatsBar_legend:nth-child(10n-8) > .acpStatsBar_preview {
		background: #ea7963;
	}
	.acpStatsBar_segment:nth-child(10n-7),
	.acpStatsBar_legend:nth-child(10n-7) > .acpStatsBar_preview {
		background: #de6470;
	}
	.acpStatsBar_segment:nth-child(10n-6),
	.acpStatsBar_legend:nth-child(10n-6) > .acpStatsBar_preview {
		background: #6b9dde;
	}
	.acpStatsBar_segment:nth-child(10n-5),
	.acpStatsBar_legend:nth-child(10n-5) > .acpStatsBar_preview {
		background: #b09be4;
	}
	.acpStatsBar_segment:nth-child(10n-4),
	.acpStatsBar_legend:nth-child(10n-4) > .acpStatsBar_preview {
		background: #eec766;
	}
	.acpStatsBar_segment:nth-child(10n-3),
	.acpStatsBar_legend:nth-child(10n-3) > .acpStatsBar_preview {
		background: #9fc973;
	}
	.acpStatsBar_segment:nth-child(10n-2),
	.acpStatsBar_legend:nth-child(10n-2) > .acpStatsBar_preview {
		background: #e291bf;
	}
	.acpStatsBar_segment:nth-child(10n-1),
	.acpStatsBar_legend:nth-child(10n-1) > .acpStatsBar_preview {
		background: #55c1a6;
	}
	.acpStatsBar_segment:nth-child(10n),
	.acpStatsBar_legend:nth-child(10n) > .acpStatsBar_preview {
		background: #5fb9da;
	}

	.acpStatsBar_preview {
		display: inline-block;
		width: 14px;
		height: 14px;
		margin-inline-end: 4px;
		border-radius: 5px;
	}

/* Widget layout options in the Developer Center */
#form_dev_widget_layouts .ipsFieldList {
	display: flex;
	flex-direction: row;
	gap: 20px;
	flex-wrap: wrap;
	justify-content: stretch;
}

#form_dev_widget_layouts .cBuilderSvg {
	--i-svg--st-wi: 4;
	--i-svg--co: var(--i-background_6);
	--i-svg--st: color-mix(in srgb, var(--i-color_root) 90%, var(--i-background_6));
	color: var(--i-svg--co);
}

#form_dev_widget_layouts .cBuilderSvg [data-role="outerborder"] {
	stroke: var(--i-svg--st);
}
#form_dev_widget_layouts .cBuilderSvg [data-role="background"] {
	fill: var(--i-background_2);
}

.cSupportQuery {
	border: 0 !important;
	white-space: pre-wrap;
}

/* Used in Pages > Media */
.ipsTreeList a {
	color: inherit;
	padding: .5em 0;
	display: block;
	position: relative;
}

.ipsTreeList li a { padding-inline-start: 1em;	}
.ipsTreeList li li a { padding-inline-start: 2em; }
.ipsTreeList li li li a { padding-inline-start: 3em; }
.ipsTreeList li li li li a { padding-inline-start: 4em; }

.ipsTreeList_inactiveBranch > ul {
	display: none;
}

.ipsTreeList_inactiveBranch > a::before,
.ipsTreeList_activeBranch > a::before {
	content: '\f0da';
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	margin-inline-end: .5em;
}

	.ipsTreeList_activeBranch > a::before {
		content: '\f0d7';
	}

.ipsTreeList_activeNode > a {
	background: var(--i-primary);
	color: var(--i-primary-contrast);
}

/* Remove stacked styles which happens if .ipsBox--tree is placed inside .ipsBox */
.ipsBox .ipsBox--tree{
	border-width: 0;
	box-shadow: none;
	background-color: transparent;
}

/* Indent child trees */
.ipsTree .ipsTree{
	margin-inline-start: 3em
}


.ipsTree_row {
	display: flex;
	align-items: center;
	padding: 1.2em;
	gap: 1em;
	border-bottom: 1px solid var(--i-background_3);
}

.ipsTree_open,
.ipsTree_parent:not(.ipsTree_noToggle):hover{
	background-color: var(--i-background_2);
}

	.ipsTree_row.ipsTree_draggingInto {
		background: var(--i-background_3);
	}

	.ipsTree_swatch {
		display: inline-block;
		width: 12px;
		height: 12px;
		border-radius: 3px;
		background-color: var(--i-featured, var(--i-background_3));
		vertical-align: middle;
		margin-inline-end: 6px;
	}
	.ipsTree_row + form > .ipsTree_rows {
		padding-inline-start: 1em;
	}

.ipsTree_loadingRow {
	padding: 10px;
	padding-inline-start: 40px;
}
	.ipsTree_loadingRow::before {
		inset-inline-start: 20px;
	}

/* Drag */
.ipsTree_drag{
	flex: 0 0 auto;
}
.ipsTree_dragHandle {
	cursor: move;
	display: block;
	text-align: center;
	min-width: 30px;
}
.ipsTree_dragHandle:not(:hover){
	opacity: .2;
}

/* Align data */
.ipsTree_align{
	flex: 1 1 auto;
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: inherit;
}

.ipsTree_rowData {
	flex: 999 1 50%;
	position: relative;
	font-weight: 500;
	color: var(--i-color_hard);
}

	.ipsTree__icon{
		color: var(--i-color_soft);
		text-align: center;
		width: 1.25em;
	}

	.ipsTree__icon:where(:not(:has(.ipsFlag, .ipsIcon--emoji))){
		opacity: .5;
	}

.ipsTree__thumb {
	width: 24px;
	vertical-align: middle;
	margin-inline-end: .6em;
}

/* Larger icons if it's the first child, eg. Ranks */
.ipsTree_row > .ipsTree__thumb:first-child{
	width: 64px;
}

/* Titles */
.ipsTree_title{
	font-weight: 500;
	color: var(--i-color_hard);
	font-size: 1.08em;
}
	.ipsTree_title a {
		color: inherit;
	}
	.ipsTree_title strong{
		font-weight: inherit;
	}

/* Fix alignment of "Enabled"/"Disabled" badge */
.ipsTree_toggleEnable,
.ipsTree_toggleDisable{
	display: flex;
}

/* Stack styles */
.ipsTree_parent:not(.ipsTree_noToggle) {
	cursor: pointer;
}

/* Expand arrow */
.ipsTree_align::before {
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	font-size: 11px;
	opacity: .5;
	transition: .2s all linear;
	align-self: center;
	width: 1em;
}

	:where([dir="rtl"]) .ipsTree_parent .ipsTree_align::before {
		transform: rotate(180deg);
	}

	.ipsTree_open .ipsTree_align::before {
		transform: rotate(90deg);
		opacity: 1;
	}

	/* Show arrow */
	.ipsTree_parent:not(.ipsTree_noToggle) .ipsTree_align::before {
		content: '\f054' !important;
	}

	/* Indent all sibling trees of .ipsTree_parent */
	.ipsTree:has(> li > .ipsTree_parent:not(.ipsTree_noToggle)) > li > .ipsTree_row > .ipsTree_align::before{
		content: '';
	}

	/* Remove pointer-events from expandable tree categories. This prevents new pages from opening when trees should instead expand */
	.ipsTree_parent > .ipsTree_align > .ipsTree_rowData > .ipsTree_title a{
		pointer-events: none;
	}

/* Nested sortable classes */
.mjs-nestedSortable-error {
	border: 1px solid #e85959 !important;
	background: #f3d9d9 !important;
	min-height: 48px !important;
	position: relative;
}

	.mjs-nestedSortable-error:before,
	.mjs-nestedSortable-error:after {
		display: block;
		position: absolute;
		line-height: 48px;
		font-size: 11px;
		color: #e85959;
	}

	.mjs-nestedSortable-error:before {
		content: attr(data-error);
		inset-inline-start: 30px;
	}

	.mjs-nestedSortable-error:after {
		content: '\f071';
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		inset-inline-start: 10px;
	}

.sortable-placeholder {
	border: 1px solid var(--i-primary);
	background: var(--i-background_selected);
	min-height: 68px;
}

.ipsTree_row .ipsTree_row_cells {
	font-weight: 500;
	display: flex;
	flex-wrap: wrap;
	gap: .5em 2em;
	color: var(--i-color_soft);
}

:where(.ipsTree_row .ipsTree_row_cells) a{
	color: inherit;
}

.ipsTree_controls{
	align-self: center;
}

/* Sometimes .ipsTree_controls have different button amounts. This makes them all the same width */
.ipsTree:has(.ipsControlStrip > li:nth-child(2)) .ipsControlStrip{
	min-width: calc((2.4em + 4px) * 2);
}
.ipsTree:has(.ipsControlStrip > li:nth-child(3)) .ipsControlStrip{
	min-width: calc((2.4em + 4px) * 3);
}
.ipsTree:has(.ipsControlStrip > li:nth-child(4)) .ipsControlStrip{
	min-width: calc((2.4em + 4px) * 4);
}

@media (max-width: 500px){
	.ipsTree .ipsTree_controls{
		flex: 1 1 100%;
	}
}

/* Pretty print and code */
.ipsCode {
	background: var(--i-background_2);
	border-color: var(--i-background_5) !important;
}
[data-ips-scheme="dark"] .ipsApp .CodeMirror{
	background: var(--i-background_1);
	color: var(--i-color_hard);
	border-color: var(--i-background_5);
}
    [data-ips-scheme="dark"] .CodeMirror-gutters{
        border-color: var(--i-background_3);
        background: var(--i-background_1);
    }
    [data-ips-scheme="dark"] .CodeMirror-linenumber{
        color: var(--i-background_5);
    }
    [data-ips-scheme="dark"] .diffDeleted{
        background: #673f3f;
        color: #fff;
    }
    [data-ips-scheme="dark"] .diffInserted{
        background: #52613f;
        color: #fff;
    }
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-merge-l-chunk {
        background: var(--i-background_5);
    }
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-merge-gap {
        background: var(--i-background_6);
    }

    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-meta{ color: #a5acbd; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-tag { color: #a0dd96; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-attribute { color: #bdbdf9; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-string { color: #f9e1a8; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-comment { color: #fdc389; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-error { color: #d56262; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-qualifier { color: #86c1ab; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-atom { color: #f9d88a; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-number { color: #f7ca90; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-def { color: #a9a9ff; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-variable-3, 
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-type { color: #e3fbf2; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-keyword { color: #ffa1a1; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-variable-2{ color: #94c0ec; }
    [data-ips-scheme="dark"] .ipsApp .cm-s-default .cm-builtin{ color: #b89cf9; }

    [data-ips-scheme="dark"] .CodeMirror-selected { background: rgba(255,255,255,0.25); }
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-focused .CodeMirror-selected { background: rgba(255,255,255,0.25); }
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line::selection, 
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line > span::selection, 
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line > span > span::selection { background: rgba(255,255,255,0.25); }
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line::-moz-selection, 
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line > span::-moz-selection, 
    [data-ips-scheme="dark"] .ipsApp .CodeMirror-line > span > span::-moz-selection { background: rgba(255,255,255,0.25); }

    [data-ips-scheme="dark"] .pln{
    color: #fff
}
@media screen{
    [data-ips-scheme="dark"] .str{
        color:#f9e1a8
    }
    [data-ips-scheme="dark"] .kwd{
        color:#ffa1a1
    }
    [data-ips-scheme="dark"] .com{
        color:#fdc389
    }
    [data-ips-scheme="dark"] .typ{
        color:#aeecd5
    }
    [data-ips-scheme="dark"] .lit{
        color:#a9a9ff
    }
    [data-ips-scheme="dark"] .pun,
    [data-ips-scheme="dark"] .opn,
    [data-ips-scheme="dark"] .clo{
        color:#f9d88a
    }
    [data-ips-scheme="dark"] .tag{
        color:#a0dd96
    }
    [data-ips-scheme="dark"] .atn{
        color:#d56262
    }
    [data-ips-scheme="dark"] .atv{
        color:#a0dd96
    }
    [data-ips-scheme="dark"] .dec,
    [data-ips-scheme="dark"] .var{
