}
[data-ips-scheme="dark"] li.L1,
[data-ips-scheme="dark"] li.L3,
[data-ips-scheme="dark"] li.L5,
[data-ips-scheme="dark"] li.L7,
[data-ips-scheme="dark"] li.L9{
