}

[data-ips-scheme="dark"] code [style*="color: #000000"]{
	color: #fff !important;
}
[data-ips-scheme="dark"] code [style*="color: #0000BB"]{
	color: #a9a9ff !important;
}
[data-ips-scheme="dark"] code [style*="color: #007700"]{
	color: #a0dd96 !important;
}
