}

/* Export diff template names */
.acpBlock_title{
    font-size: 18px;
    font-weight: bold;
    color: var(--i-color_hard);
    padding: 1em;
}

:root{
	--i-sticky-offset: 61px;
	overflow-wrap: break-word;
}

/* Add .fa-star-o, which is used on the Applications page (set as default) */
.fa-star-o::before{
	content: '\f005';
	font-weight: 400;
}

/* Increase size of main buttons */
.acpToolbar .ipsButton{
	--i-button--pa-bl: 1.1em;
}

/* Horizontal forms in ACP by default. Most forms in the ACP don't assign --horizontal, even though they should */
.ipsForm--admin-template:not(.ipsForm--horizontal, .ipsForm--vertical) .ipsFieldRow[style*="list-item"]{
	display: grid !important;
}

.ipsForm:not(.ipsForm--admin-template) .ipsFieldRow--fullWidth > *{
	grid-column: 1/-1;
}

@media (min-width: 890px){
	.ipsForm--admin-template:where(:not(.ipsForm--horizontal, .ipsForm--vertical)) > .ipsFieldRow{
		grid-template-columns: max(14em, 22%) 1fr;
	}
	.ipsForm--admin-template:not(.ipsForm--horizontal, .ipsForm--vertical) .ipsFieldRow__required{
		flex: 1 1 100%;
	}
	.ipsForm--admin-template:where(:not(.ipsForm--horizontal, .ipsForm--vertical)) > .ipsFieldRow > .ipsFieldRow__label{
		text-align: end;
		align-self: baseline;
	}
	.ipsForm--admin-template:not(.ipsForm--horizontal, .ipsForm--vertical) .ipsFieldRow__label{
		display: grid;
		place-items: end;
	}
	/* Reset form alignment in dropdowns */
	.iDropdown .ipsFieldRow__label{
		place-items: start !important;
	}
}

/* Increase gaps in forms */
.ipsFieldRow{
	column-gap: 1.5em;
	padding: 1.5em;
}

/* Add background to form section headers */
.ipsFieldRow__section{
	background-color: var(--i-background_3);
	border: 1px solid var(--i-background_5);
	border-width: 1px 0;
	margin-top: -1px;
}

.ipsFieldRow__section:first-child{
	margin-top: 0;
	border-top-width: 0;
}
/* Add radius if it's the first element in a non-tab element */
.ipsFieldRow__section:not(.ipsTabs__panel *):first-child{
	border-top-left-radius: var(--i-box--bo-ra);
	border-top-right-radius: var(--i-box--bo-ra);
}

/* Matrix rows: These should occpuy the full form width, since they don't have a label */
.ipsFieldRow--matrix{
	display: block;
	padding: 0;
}

/* Reduce size of labels in ACP */
.ipsFieldRow__label{
	font-size: inherit;
}

/* Make some labels bolder */
.ipsFieldList label{
	font-weight: 500;
	color: var(--i-color_hard);
}

/* Descriptions under radio labels, Eg: ACP > Editor > Settings */
.ipsFieldList__content .ipsFieldRow__desc{
	margin-top: 0;
}

/* Add a max-width to inputs */
.ipsFieldRow__content :where(input, select){
	max-width: min(35em, 100%);
}

.ipsFieldRow__content :where(select, [type="date"]){
	width: auto;
}

.ipsFieldRow__content :where([type="number"]){
	max-width: 8em;
}

/* Space out filters (Eg. Statistics > Member Visits) */
.ipsForm__filtering{
	padding: 1em;
}
.ipsForm__filtering :is(input, button){
	margin: 0 .4em;
}

/* Remove border from "spectrum" color picker to prevent the checkered background issue */
.sp-original-input-container input{
	border-width: 0;
}

/* Social icons */
#form_site_social_profiles .ipsField_stack{
	max-width: 550px;
}
	#form_site_social_profiles .ipsFieldRow__content :where(input, select){
		max-width: none;
		width: 100%;
	}
	#form_site_social_profiles [data-ipsstack-keyvalue-name="key"]{
		flex: 1 1 auto;
	}

/* Remove radius of update notifications */
html .cAcpNotificationBanner{
	border-radius: 0;;
}

/* Add padding to buttons when they're inside tabbed content */
.ipsTabs__panel .ipsButtons--admin{
	padding: 1em;
}

.ipsButtons--admin:has( + .ipsBox){
	margin-bottom: 1.5em;
}

/* Always enable .ipsLinkPanel in ACP */
.ipsLinkPanel ~ *:not(:is(a, button, input, textarea, [data-ipsTooltip])){
	pointer-events: none;
}
.ipsLinkPanel ~ * :is(a, button, input, textarea, [data-ipsTooltip]){
	pointer-events: auto;
}
.ipsLinkPanel ~ * a:hover{
	text-decoration: underline;
}

/* Better alignment of user photos in admin panel tables (ie. Clubs) */
.ipsTable .ipsUserPhoto{
	vertical-align: middle;
}

.ipsTable .ipsUserPhoto:has( ~ a){
	margin-inline-end: .5em;
}

/* Larger button on ACP login page */
.ipsForm--admin-login-form .ipsButton{
	padding: 1.1em;
}

/* ACP Off-canvas menus */
.ipsApp_admin .ipsOffCanvas__title:first-child{
	padding-top: 1em;
}
/* Add '-' before sublinks in ACP off-canvas navigation */
.ipsApp_admin .ipsOffCanvas__nav i-details-content a::before{
	content: "-";
	margin-inline-end: .3em;
	opacity: .3;
}

#emoticonsManagement [data-role="dragHandle"] {
	cursor: move;
}

.cEmoticons_box {
	background: var(--i-background_1);
	border-radius: 6px;
	box-shadow: color-mix(in srgb, var(--i-color_root) 10%, transparent) 0px 0px 0px 1px;
	position: relative;
}

.cEmoticons_box [data-delete] {
	position: absolute;
	top: 5px;
	inset-inline-end: 5px;
}

#emoticonsManagement img {
	height: 100px;
	width: 100%;
	object-fit: scale-down;
}

.cTranslateTable .ipsTable_wrap {
	max-width: 220px;
}

.cTranslateTable_field {
	position: relative;
}

	.cTranslateTable_field [data-action] {
		display: none;
		position: absolute;
		bottom: 10px;
		z-index: 4000;
		line-height: 20px;
	}

		.cTranslateTable_field_focus textarea ~ [data-action] {
			display: block;
		}

		.cTranslateTable_field [data-action="saveWords"] {
			inset-inline-end: 10px;
		}

		.cTranslateTable_field [data-action="revertWords"] {
			inset-inline-end: 65px;
		}

.cTranslateTable textarea {
	height: 100%;
	min-height: 50px;
	min-width: 150px;
	field-sizing: content;
}

/* Full-height resource manager */
#acpMainArea{
	display: flex;
	flex-direction: column;
}

	:where(#acpMainArea > *){
		flex: 0 0 auto;
	}

	#acpContent{
		flex: 1 1 100%;
	}

[data-controller="core.admin.customization.media"]{
	container-type: inline-size;
	flex: 1 0 auto;
	min-height: 60vh;
	min-height: 60svh;
}

.cMedia_manager{
	display: grid;
	min-height: 100%;
}

	.cMedia_manager__side{
		background-color: var(--i-background_1);
		border: 0px solid var(--i-background_4);
		border-inline-end-width: 1px;
		border-start-start-radius: inherit;
		border-end-start-radius: inherit;
	}

		#elMedia_sidebar{
			position: -webkit-sticky;
			position: sticky;
			top: var(--i-sticky-offset);
			padding: 1.8em;
		}

		.ipsTitle[data-role="itemFilename"]{
			margin-bottom: 1.5em;
		}

		.cMedia_manager__fileInfo{
			display: grid;
			gap: 2em;
			margin: 2em 0;
		}

	.cMedia_manager__main{
		background-color: var(--i-background_2);
		container-type: inline-size;
		border-start-end-radius: inherit;
		border-end-end-radius: inherit;
	}

		.cMedia__managerToolbar {
			background: var(--i-background_1);
			border-bottom: 1px solid var(--i-background_4);
			position: sticky;
			top: var(--i-sticky-offset);
			z-index: 1;
			padding: 10px;
			display: flex;
			flex-wrap: wrap;
			gap: 10px;
			border-start-end-radius: inherit;
		}

		#elMedia_searchField {
			flex: 999 1 300px;
		}

.cMedia_manager__items{
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
	padding: 1em;
	gap: 1em;
}

	.cMedia_item {
		background: var(--i-background_1);
		border: 1px solid var(--i-background_4);
		border-radius: 8px;
		padding: .5em;
		cursor: pointer;
		text-align: center;
	}

	.cMedia_item:where(:hover){
		border-color: var(--i-background_5);
	}

	.cMedia_itemSelected {
		border-color: var(--i-primary);
		background: var(--i-primary);
		color: var(--i-primary-contrast);
	}

	.cMedia_itemDisabled,
	.cMedia_treeDisabled {
		opacity: .3;
		pointer-events: none;
	}

		.cMedia_item .ipsThumb img{
			object-fit: contain;
		}

		/* Icons for different file types (text, font, other) */
		.cMedia_manager [data-filetype="text"] .ipsThumb i::before{
			content: "\f1c9";
		}
		.cMedia_manager [data-filetype="font"] .ipsThumb i::before{
			content: "\f031";
		}
		.cMedia_manager [data-filetype="other"] .ipsThumb i::before{
			content: "\f49e";
		}

		.cMedia_content{
			padding-top: 1em;
			padding-bottom: .5em;
		}

		.cMedia_filename {
			font-weight: 500;
		}

		.cMedia_item:not(.cMedia_itemSelected) .cMedia_filename {
			color: var(--i-color_hard);
		}


/*
	----------------
	- Large devices
	----------------
*/

/* Side column */
@container (min-width: 650px){
	.cMedia_manager{
		grid-template-columns: clamp(300px, 20%, 380px) 1fr;
	}
}

/*
	----------------
	- Small devices
	----------------
*/

/* Side column */
@container (max-width: 649px){
	.cMedia_manager{
		grid-template-rows: 1fr auto;
	}
	.cMedia_manager__side{
		order: 1;
		position: sticky;
		z-index: 1;
		bottom: 0;
		border-width: 1px 0 0 0;
		transition: .5s;
		background: color-mix(in srgb, var(--i-background_1) 50%, transparent);
		-webkit-backdrop-filter: blur(20px);
		backdrop-filter: blur(20px);
	}

		/* Hide file info bar if no resource is selected */
		.cMedia_manager:not(:has(.cMedia_itemSelected)) .cMedia_manager__side{
			display: none;
		}

		#elMedia_sidebar{
			padding: 1em;
		}

	.ipsTitle[data-role="itemFilename"]{
		margin-bottom: .5em;
	}
	.cMedia_manager__fileInfo{
		display: none;
	}
	.cMedia__managerToolbar{
		position: static;
	}
}

/* File grid */
@container (max-width: 570px){
	.cMedia_manager__items{
		grid-template-columns: 1fr;
	}
	.cMedia_item {
		display: grid;
		grid-template-columns: 50px 1fr;
		gap: 15px;
		text-align: start;
	}
}

/* ----- */
#elTemplateEditor {
	margin: 0 -15px -5px -15px;
	border-top: 1px solid rgba(0,0,0,0.1);
}

.cTemplateControls,
#elTemplateEditor .ipsTabs {
	background: var(--i-background_2);
}

#elTemplateEditor > .ipsColumns > .ipsColumn_wide {
	border-inline-end: 4px solid var(--i-background_2);
}

.cTemplateControls {
	height: 66px;
	padding-top: 15px;
}

	.cTemplateControls .ipsButton.ipsButton--disabled {
		opacity: 0.2;
	}

#elTemplateEditor_fileListControls {
	padding-left: 15px;
	padding-right: 15px;
}

	#elTemplateEditor_fileListControls > div:first-child {
		display: flex;
	}

		#elTemplateEditor_fileListControls > div:first-child input[type="text"] {
			flex-grow: 1;
			padding: 0 7px;
			/* border: 0; */
			border-right-width: 0px;
			line-height: 34px;
			border-start-start-radius: 3px;
			border-end-start-radius: 3px;
			box-shadow: none;
		}

#elTemplateEditor_panelToolbar {
	padding-inline-end: 15px;
}

#elTemplateEditor > .ipsColumns > .ipsColumn {
	padding: 0;
}

#elTemplateEditor_info {
	position: fixed;
	bottom: 0;
	inset-inline-start: 270px;
	inset-inline-end: 0;
	background: var(--i-background_1);
	text-align: center;
	padding: 7px;
	border-top: 1px solid rgba(0,0,0,0.2);
	border-color: var(--i-background_3);
}

#elTemplateEditor .ipsTabs {
	padding: 0;
}

	#elTemplateEditor .ipsTabs__tab {
		text-overflow: clip !important;
		margin-inline-end: 0;
		color: inherit;
		border-radius: 0;
	}

	#elTemplateEditor .ipsTabs__tab[aria-selected="true"] {
		background: var(--i-background_1);
		font-weight: bold;
	}

#elTemplateEditor [data-role="editor"],
#elTemplateEditor .CodeMirror {
	border-width: 0px !important;
	border-radius: 0px !important;
	padding-bottom: 10px;
}



#elTemplateEditor [data-role="editor"] {
	font-family: monospace;
	font-size: 13px;
}

#elTemplateEditor [data-role="templateToolbar"] {
	margin-bottom: 15px;
}

#elTemplateEditor_panelWrap {
	position: absolute;
	inset: 0;
}

#elTemplateEditor_outerPanelWrap {
	position: relative;
}

#elTemplateEditor [data-role="templatePanelWrap"] {
	width: 100%;
	background-color: var(--i-background_1);
	position: absolute;
	top: 49px;
	left: 0;
	right: 0;
	bottom: 0;
}

	#elTemplateEditor [data-role="templatePanelWrap"] textarea {
		height: 550px;
	}

#elTemplateEditor [data-action="closeTab"] {
	font-size: 12px;
	color: var(--i-color_soft);
	margin-inline-start: 3px;
}

	#elTemplateEditor [data-action="closeTab"]:hover,
	#elTemplateEditor [data-state="unsaved"] [data-action="closeTab"] {
		color: var(--i-color_hard);
	}

#elTemplateEditor input[data-role="templateSearch"] {
 	background-clip: padding-box;
	width: 75%;
	max-width: 350px;
	padding: 7px;
}
#elTemplateFilterMenu {
	line-height: 34px;
	border-start-end-radius: 3px;
	border-end-end-radius: 3px;
}

/* FILE LISTING STYLES */
#elTemplateEditor_fileList {
	height: 550px;
	overflow: auto;
}

.cTemplateList a {
	padding: 5px 0;
	display: block;
	position: relative;
	color: var(--i-color_root);
}

.cTemplateList li.cTemplateList_inactiveBranch > a::before,
.cTemplateList li.cTemplateList_activeBranch > a::before {
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	display: inline-block;
	line-height: 6px;
	font-size: 14px;
}
	.cTemplateList li.cTemplateList_inactiveBranch > a::before,
	.cTemplateList li.cTemplateList_activeBranch > a::before {
		content: '\f0da';
		margin-inline-end: 7px;
	}
	[dir="rtl"] .cTemplateList li.cTemplateList_inactiveBranch > a::before,
	[dir="rtl"] .cTemplateList li.cTemplateList_activeBranch > a::before {
		content: '\f0d9';
	}

	[dir="ltr"] .cTemplateList li.cTemplateList_activeBranch > a::before,
	[dir="rtl"] .cTemplateList li.cTemplateList_activeBranch > a::before {
		content: '\f0d7';
	}

.cTemplateList li.cTemplateList_inactiveBranch > ul {
	display: none;
}

.cTemplateList_highlight {
	background: var(--i-background_2);
}

.cTemplateList li a {
	padding-inline-start: 15px;
}
	.cTemplateList li li a {
		padding-inline-start: 30px;
	}
		.cTemplateList li li li a {
			padding-inline-start: 45px;
		}
			.cTemplateList li li li li a {
				padding-inline-start: 70px;
			}

.cTemplateList li.cTemplateList_activeNode > a {
	background: var(--i-primary);
	color: #fff;
}

.cTemplateList li:not( .cTemplateList_activeNode ) > a:hover {
	background: var(--i-background_3);
}

/* INHERITED VALUES */
a[data-inherited-value]:after {
	position: absolute;
	margin-top: 2px;
	inset-inline-end: 5px;
}

li[class^="cTemplateState_"]:before {
	display: inline-block;
	color: #fff !important;
}

a[data-inherited-value]:after, li[class^="cTemplateState_"]:before {
	font-size: 9px;
	font-weight: bold;
	text-transform: uppercase;
	font-family: monospace;
	padding: 0 5px;
	color: #b3b3b3;
	line-height: 14px;
	border-radius: 10px;
	opacity: 0.1;
	transition: 0.4s all linear;
}

a[data-inherited-value="original"]:after {
	display: none;
}

	.cTemplateList:hover a[data-inherited-value]:after, li[class^="cTemplateState_"]:before {
		opacity: 1;
	}

.cTemplateList a[data-inherited-value="custom"]:after, .cTemplateState_custom:before {
	content: 'C';
	background: #c9c030;
	color: #fff;
}

.cTemplateList a[data-inherited-value="inherit"]:after, .cTemplateState_inherit:before {
	content: 'I';
	background: #83b256;
	color: #fff;
}

.cTemplateList a[data-inherited-value="changed"]:after, .cTemplateState_changed:before {
	content: 'M';
	background: #eb841d;
	color: #fff;
}

.cTemplateList a[data-inherited-value="outofdate"]:after, .cTemplateState_outofdate:before {
	content: 'M';
	background: #c93054;
	color: #fff;
}

.cTemplateMergeHeaders {
	border: 1px solid var(--i-background_4);
	border-bottom: 0;
}
.cTemplateMergeHeader {
	width: 47%;
	display: inline-block;
}
.cTemplateMergeHeader_spacer {
	width: 6%;
	display: inline-block;
}

.ipsCms_theme_image_preview {
	max-height: 100px;
	max-width: 100px;
}

.ipsThemeKey {
	border-bottom: 1px dotted black;
}

:is(
#ipsTabs_tabs_form_form_tab_theme_designer_form_css_panel,
#ipsTabs_tabs_form_form_tab_theme_designer_form_js_panel
) .ipsFieldRow__label {
	display: none;
}

[data-vle]:hover {
	background: #eeebd6;
	cursor: pointer;
}

.cOnboardBox  {
	padding: clamp(1em, 5vw, 3em);
	max-width: 900px;
	margin: 70px auto 0;
	border-top: 10px solid var(--i-primary);
}

	.cOnboardBox .ipsHr {
		margin: 35px 0;
	}

.cOnboardBox__item{
	display: flex;
	gap: 2em;
	padding: 2em 0;
	border-bottom: 1px solid var(--i-background_4);
}

.cOnboardBox__stepIcon {
	flex: 0 0 1em;
	text-align: center;
	font-size: 24px;
	opacity: .3;
}

.cOnboard__sectionTitle {
	font-weight: 600;
	cursor: pointer;
	font-size: 18px;
	color: var(--i-color_hard);
	border-bottom: 1px solid var(--i-background_4);
}

	.cOnboard__sectionTitle i {
		font-size: 20px;
		transition: 0.2s all ease-in-out;
	}

.cOnboard__infoTitle {
	color: var(--i-color_hard);
	font-size: 1.3em;
	font-weight: 600;
	margin-bottom: .4em;
}

.cOnboard__section--closed.cOnboard__section--done i {
	transform: rotate(0);
	opacity: 0.6;
}
	.cOnboard__section--closed.cOnboard__section--done i::before {
		content: '\f05d';
	}

.cOnboard__section--closed :is(.cOnboard__sectionContents, .cOnboard__sectionButtons){
	display: none;
}

.cOnboard__section--closed .cOnboard__sectionIcon {
	transform: rotate(-90deg);
}

/*
	----------------
	- Reset styles
	----------------
*/

/* Reset all elements to ideal format */
*, ::before, ::after {
	margin: 0;
	padding: 0;
	box-sizing: border-box;
	min-width: 0;
	min-height: 0;
}

html{
	-webkit-text-size-adjust: 100%;
	text-size-adjust: 100%;
	accent-color: var(--i-primary);
}

hr{
	color: inherit;
}

hr,
iframe,
fieldset{
	border-width: 0;
}

iframe:where([src*="youtube."], [src*="youtube-nocookie."], [src*="vimeo."], [src*="dailymotion."], [src^="https://embed.ted.com/"]){
	width: 100%;
	height: auto;
	aspect-ratio: 16/9;
}

img, svg{
	border: 0;
	display: inline-block;
	max-width: 100%;
	height: auto;
	vertical-align: top;
}

/* Prevent alt text from overflowing image if URL fails to load */
:where(img::before){
	display: block;
	overflow: hidden;
	height: 100%;
}

h1, h2, h3, h4, h5, h6{
	font: inherit;
}

b, strong { font-weight: bolder; }

menu, ol, ul, summary{
	list-style-type: none;
}
blockquote, q { quotes: none; }
table { border-collapse: collapse; border-spacing: 0; }

input, textarea, select, button{
	background: none;
	border: 0;
	color: inherit;
	font: inherit;
	line-height: inherit;
	text-align: inherit;
	text-transform: inherit;
}

/*
	Date inputs in iOS Safari stretch beyond 100% due to padding, even though box-sizing: border-box is used. Removing padding fixes the issue. Last tested in iOS 26.3.1
	Eg. Search Events on Events landing page
*/
@supports(-webkit-touch-callout: none){
	input[type="date"],
	input[type="time"]{
		padding-inline: 0;
	}
}

textarea, select{
	-webkit-appearance: none;
	appearance: none;
	box-shadow: none;
}

textarea{
	display: block;
	width: 100%;
}

select{
	cursor: pointer;
	font-weight: normal; /* Fix the serif font from appearing in Safari. Last tested in 18.3 */
}

[type="search"]{
	-webkit-appearance: none;
	appearance: none;
}

[type="date"],
[type="time"]{
	accent-color: currentColor;
}

::placeholder{
	color: inherit;
	opacity: .5;
}

button, [type="submit"], summary{
	-webkit-appearance: none;
	appearance: none;
	cursor: pointer;
	touch-action: manipulation;
	-webkit-user-select: none;
	user-select: none;
}

button{
	text-align: inherit;
}

details summary::-webkit-details-marker {
	display:none;
}

:focus{
	outline-color: transparent;
}

:focus-visible{
	outline: var(--i-outline-width) var(--i-outline-style) var(--i-outline-color);
	outline-offset: var(--i-outline-offset);
}

address{
	font-style: inherit;
}

dialog{
	border-width: 0;
	margin: auto;
}

/* Ensure closed dialogs are always hidden */
dialog:not([open]){
	display: none !important;
}

.sr-only,
.ipsInvisible {
	border: 0 !important;
	clip: rect(1px, 1px, 1px, 1px) !important;
	clip-path: inset(50%) !important;
	height: 1px !important;
	margin: -1px !important;
	overflow: hidden !important;
	padding: 0 !important;
	position: absolute !important;
	white-space: nowrap !important;
	width: 1px !important;
}

[hidden]{
	display: none !important;
}
:where([popover]){
	background: none;
	border-width: 0;
	/* Safari bug fix: popovers can fall under other elements during their closing transition without this */
    z-index: 9999;
}
/* Ensure closed popovers are always hidden */
[popover]:not(#x):not(:popover-open) {
	display: none;
}
/* Polyfill */
@supports not selector(:popover-open) {
	:where([popover]){
		display: block;
	}
	[popover]:not(#x):not(.\:popover-open) {
		display: none;
	}
}

:root{

	/*
		----------------
		- Color palette
		----------------
	*/

	--light__i-primary: hsl(220 85% 50%);
	--light__i-primary-relative-l: 33;
	--light__i-secondary: hsl(220 49% 13%);
	--light__i-secondary-relative-l: 10;
	--light__i-base: oklch(calc(var(--light__i-base-l) * 1%) calc(var(--light__i-base-c) * 1%) var(--light__i-base-h));

	--light__i-base-l: 100;
	--light__i-base-c: 30;
	--light__i-base-h: 260;

	--dark__i-primary: hsl(215 85% 50%);
	--dark__i-primary-relative-l: 37;
	--dark__i-secondary: hsl(215 18% 26%);
	--dark__i-secondary-relative-l: 24;

	--dark__i-base: oklch(calc(var(--dark__i-base-l) * 1%) calc(var(--dark__i-base-c) * 1%) var(--dark__i-base-h));
	--dark__i-base-l: 30;
	--dark__i-base-c: 20;
	--dark__i-base-h: 260;


	/*
		----------------
