	src: url('{resource="fonts/InstrumentSans.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Inter";
	src: url('{resource="fonts/Inter.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Manrope";
	src: url('{resource="fonts/Manrope.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Merriweather Sans";
	src: url('{resource="fonts/MerriweatherSans.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Open Sans";
	src: url('{resource="fonts/OpenSans.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Pathway Extreme";
	src: url('{resource="fonts/PathwayExtreme.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Roboto Flex";
	src: url('{resource="fonts/RobotoFlex.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Roboto Serif";
	src: url('{resource="fonts/RobotoSerif.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}
@font-face{
	font-family: "Roboto Slab";
	src: url('{resource="fonts/RobotoSlab.woff2" inCss="true" app="core" location="front"}') format('woff2');
