}
@font-face{
	font-family: "Source Sans 3";
	src: url('{resource="fonts/SourceSans3.woff2" inCss="true" app="core" location="front"}') format('woff2');
	font-display: swap;
	font-weight: 100 900;
}

/*
	----------------
	- Global
	----------------
*/

/* Ensure anchored content appears below sticky header. By default, it'll match the height of the offset, but extra space can be added by defining --i-scroll-padding */
html{
	scroll-padding-top: calc(var(--i-sticky-offset) + var(--i-scroll-padding, 0px));
	/* Ensure the mobile footer doesn't obscure keyboard focused content */
	scroll-padding-bottom: calc(10px + var(--i-mobileFooter--he));
	overflow-x: hidden;
	overflow-y: scroll;
}

body{
	background-color: var(--i-body--ba-co);
	color: var(--i-co);
	font-family: var(--i-font-family);
	font-size: var(--i-font-size);
	line-height: 1.52;
	min-height: 100vh;
}

a{
	color: var(--i-link--co, var(--i-co));
	text-decoration: var(--i-link--te-de, none);
}

@media (any-hover:hover){
	a:where(:hover){
		color: var(--i-link-hover--co, var(--i-link--co, var(--i-co)));
		text-decoration: var(--i-link-hover--te-de, var(--i-link--te-de, none));
	}
}


/*
	----------------
	- Accessibility links
	----------------
*/

/* Skip to content */
.ipsSkipToContent:focus{
	--i-outline-offset: 0px;
	position: absolute;
	top: 10px;
	inset-inline-start: 10px;
	z-index: 9999;
	background: hsl(0 0% 0% / 70%);
	-webkit-backdrop-filter: blur(8px);
	backdrop-filter: blur(8px);
	color: hsl(0 0% 100%);
	border-radius: 6px;
	padding: .8em 1.2em;
}
	.ipsSkipToContent:not(:focus){
		position: absolute;
		clip-path: inset(50%);
		height: 1px;
		overflow: hidden;
		padding: 0;
		white-space: nowrap;
		width: 1px;
	}

/*
	----------------
	- SVG
	----------------
*/

.ipsSvg{
	height: 1em;
	width: auto;
}

/*
	----------------
	- Icons
	----------------
*/

/* Reserve space for loading icons? */
:where(.ipsLayout :is(.fa-regular, .fa-solid, .fa-brands)){
	min-width: 1em;
	text-align: center;
}

.fa-ips{
	display: inline-block;
	min-width: 1.2em;
	text-align: center;
	flex: 0 0 auto;
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-style: normal;
	font-weight: var(--icon--fo-we, 900);
}

	.fa-ips::before{
		content: var(--icon, "\f1c5");
	}

.ipsEmoji,
.ipsIcon--emoji {
	font-weight: normal;
	font-family: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", "Segoe UI Symbol", "Android Emoji", "EmojiSymbols";
}

/* Resize classic emoticons since they're 2x */
.ipsRichText .ipsEmoji img[src*="@2x.png"]{
	width: 24px;
	vertical-align: middle;
}

/* Flip the arrow direction in RTL */
[dir="rtl"] .fa-angles-left{
	--fa: "\f101";
}
[dir="rtl"] .fa-angles-right{
	--fa: "\f100";
}
[dir="rtl"] .fa-angle-left{
	--fa: "\f105";
}
[dir="rtl"] .fa-angle-right{
	--fa: "\f104";
}
[dir="rtl"] .fa-arrow-left-long{
	--fa: "\f178";
}
[dir="rtl"] .fa-arrow-right-long{
	--fa: "\f177";
}
[dir="rtl"] .fa-arrow-left{
	--fa: "\f061";
}
[dir="rtl"] .fa-arrow-right{
	--fa: "\f060";
}

/*
	----------------
	- Dialogs
	----------------
*/

dialog::backdrop{
	background: hsl(210 20% 8% / .5);
	-webkit-backdrop-filter: blur(1px);
	backdrop-filter: blur(1px);
}

:where([data-ips-scheme="dark"]) dialog::backdrop{
	background:hsl(210 10% 40% / .7);
}


/*
	----------------
	- PWA sticky fix
	----------------
*/

/* This element improves the display of sticky elements in PWAs. It sits under the status bar when sticky elements are stuck */
.ipsPwaStickyFix{
	display: none;
}

@media (display-mode: standalone){
	.ipsPwaStickyFix{
		display: block;
		position: sticky;
		background-color: var(--i-background_1);
		top: 0;
		height: 0;
		z-index: var(--i-z-index_sticky, 4);
		border-top-left-radius: inherit;
		border-top-right-radius: inherit;
	}
	.ipsPwaStickyFix::after{
		content: "";
		height: env(safe-area-inset-top);
		top: 0; left: 0; right: 0;
		position: absolute;
		background: inherit;
		border-top-left-radius: inherit;
		border-top-right-radius: inherit;
	}
}

/* PWA Loading indicator */
i-pwa-loading{
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 1000;
}
i-pwa-loading::before{
	content: "";
	height: 6px;
	display: block;
	width: 50vw;
	border-radius: 10px;
	background: var(--i-primary);
	animation-name: ipsPwaLoader;
	animation-duration: 1s;
	animation-iteration-count: infinite;
	transform-origin: 0 0;
}

@keyframes ipsPwaLoader{
	0%{
		transform: translateX(-100%);
	}
	100%{
		transform: translateX(100vw);
	}
}

::highlight(search-results) {
	/* The var is needed instead of currentColor due to #6939 */
	background: color-mix(in hsl, var(--i-primary) 15%, transparent);
	color: var(--i-color_primary);
}

/* Badges */
.ipsBadges{
	display: inline-flex;
	flex-wrap: wrap;
	gap: 3px;
}

	/* Improve alignment of badges in certain situations (otherwise vertical-align is needed on the badge) */
	.ipsBadges > li{ display: contents; }

	/* Hide badge container if it doesn't contain a badge */
	.ipsBadges:not(:has(.ipsBadge)){ display: none !important; }
	@supports not selector(a:has(b)){
		.ipsBadges:-moz-only-whitespace{ display: none !important; }
	}

.ipsBadge{
	--i-badge: var(--i-background_6);
	background: var(--i-badge);
	color: oklch(from var(--i-badge)
			clamp(0.4, (.75 - l) * 10000, 1)
			clamp(0, c * 5 * (1 - clamp(0, (.75 - l) * 10000, 1)), .2)
			h
		);
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: .4em;
	text-align: center;
	font-weight: 600;
	text-transform: uppercase;
	min-height: 1.8em;
	min-width: 1.8em;
	overflow-wrap: anywhere; /* Necessary for custom fields in Pages */
	padding: 0 .8em;
	font-size: max(.7em, 10px);
	border-radius: min(var(--i-design-radius), .4em);
	text-decoration: none !important;
}

:where(.ipsBadge){
	position: relative; /* Required to contain the absolute elements such as the "Expert follow" button */
}

@supports (not (color: oklch(from red l c h))) or (not (color: oklch(from var(--i-badge) clamp(0.35, (.75 - l) * 10000, 1) clamp(0, c * 1000 * (1 - clamp(0, (.75 - l) * 10000, 1)), .3) h))){
	.ipsBadge{
		color: color-mix(in hsl, var(--i-badge), hsl(none none var(--if-light,20%) var(--if-dark,80%)) 100%);
	}
}
@supports (not (color: color-mix(in srgb, red, blue))){
	.ipsBadge{
		color: var(--i-color_hard);
	}
}

/* Remove the underline from links if they contain a badge. Eg, Featured forum names on expanded fluid view layout */
a:has(.ipsBadge){
	text-decoration: none !important;
}

.ipsBadge a{
	color: inherit;
}

.ipsBadge--negative,
.ipsBadge--hidden,
.ipsBadge--pending,
.ipsBadge--warning{
	--i-badge: hsl(0 var(--if-light, 70% 85%) var(--if-dark, 30% 28%));
}

.ipsBadge--locked{
	--i-badge: var(--i-background_5);
}

.ipsBadge--hot,
.ipsBadge--intermediary,
.ipsBadge--assigned{
	--i-badge: hsl(24 var(--if-light, 47% 83%) var(--if-dark, 31% 25%));
}
.ipsBadge--assigned{
	text-transform: none;
}
.ipsBadge--neutral,
.ipsBadge--poll{

}
.ipsBadge--positive,
.ipsBadge--popular,
.ipsBadge--solved{
	--i-badge: hsl(var(--if-light, 117 56% 85%) var(--if-dark, 150 72% 35%));
}
.ipsBadge--pinned{
	--i-badge: hsl(350 var(--if-light, 56% 80%) var(--if-dark, 33% 35%));
}
.ipsBadge--featured{
	--i-badge: hsl(39 var(--if-light, 73% 82%) var(--if-dark, 57% 41%));
}
.ipsBadge--author{
	background-color: color-mix(in srgb, var(--i-primary) 20%, var(--i-background_1));
	color: var(--i-color_primary);	
}
.ipsBadge--prefix{
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
	text-transform: none;
}
.ipsBadge--new{
	background-color: var(--i-featured, var(--i-primary));
	color: hsl(0 0% 100%);
	font-weight: 700;
	font-size: 10px;
}
.ipsBadge--highlightedGroup {
	--i-badge: var(--i-entry-color);
}
.ipsBadge--solution{
	background-color: var(--i-background_positive);
	color: hsl(0 0% 100%);
}
.ipsBadge--expert{
	--i-badge: color-mix(in srgb, var(--i-primary) 20%, var(--i-background_1));
}

	.ipsBadge--expert [data-role="followButton"]{
		position: absolute;
		inset: 0;
		overflow: hidden;
		opacity: 0;
	}

	.ipsBadge--expert:has(.ipsButton--positive){
		background-color: var(--i-secondary);
		color: var(--i-secondary-contrast);
	}

	.ipsBadge--expert:has(.ipsButton)::after{
		content: '\f234';
		border-inline-start: 1px solid hsl(0 0% 100% / .3);
		padding-inline-start: .7em;
		margin-inline-start: .3em;
		font-family: "Font Awesome 6 Free";
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-style: normal;
		font-weight: 900;
	}
	.ipsBadge--expert:has(.ipsButton--positive)::after{
		content: '\f00c'
	}

.ipsBadge[style*="--i-featured"]{
	--i-badge: var(--i-featured);
}

/* These styles are used on fields in Pages */
.ipsBadge--style1 {
	--i-badge: var(--i-primary);
	color: var(--i-primary-contrast);
}

.ipsBadge--style2 {
	--i-badge: var(--i-secondary);
	color: var(--i-secondary-contrast);
}

.ipsBadge--style3 {
	--i-badge: var(--i-background_4);
}

.ipsBadge--style4 {
	--i-badge: var(--i-base-contrast_4);
}

.ipsBadge--style5 {
	--i-badge: hsl(160 50% 50%);
}

.ipsBadge--style6 {
	--i-badge: hsl(20 50% 50%);
}

.ipsBadge--style7 {
	--i-badge: hsl(50 50% 50%);
}

.ipsBadge--string{
	text-transform: none;
}
.ipsBadge > i{
	font-size: .8em;
}

.ipsBadge--icon{
	padding: 0;
}

	.ipsBadge--icon > span,
	.ipsBadge--text > i{
		display: none;
	}

.ipsBadge--rare {
	position: absolute;
	top: -6px;
	inset-inline-start: -10px;
	transform: rotate(calc(var(--i-lang-dir) * -20deg));
	white-space: nowrap; /* Prevent "RARE" from breaking with translations or Windows fonts */
	padding: 0 .3em;
	pointer-events: none; /* Prevents the badge tooltip from working */
}

/* Reputation badges */
.ipsRepBadge {
	font-size: .8em;
	display: inline-block;
	font-weight: 600;
	color: var(--i-color_soft)
}

	.ipsRepBadge--positive {
		color: var(--i-color_positive);
	}

	.ipsRepBadge--negative {
		color: var(--i-color_negative);
	}

/* ======================================================== */
/* POINTS (for warnings) */
.ipsWarningPoints {
	display: inline-grid;
	place-content: center;
	color: #fff;
	background-color: var(--i-color_negative);
	font-weight: bold;
	width: 2em;
	height: 2em;
	border-radius: 50%;
	font-size: 1.12em;
}

.ipsWarningPoints--removed {
	background: var(--i-color_soft);
	background-color: color-mix(in hsl, var(--i-color_soft) 10%, transparent);
}

.ipsWarningPoints--small {
	font-size: .85em;
	vertical-align: middle;
}

/* Container titles, with featured colors */
.ipsContainerTitle{
	font-weight: 600;
	color: var(--i-color_featured, var(--i-featured, var(--i-color_hard)));
}

/*
	----------------
	- Boxes
	----------------
*/

/* Global box styles */
.ipsBox__header, .ipsWidget__header, .ipsInnerBox__header{
	padding: 1em 1.2em;
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 1em;
	border-radius: calc(var(--i-box--bo-ra) - var(--i-box--bo-wi)) calc(var(--i-box--bo-ra) - var(--i-box--bo-wi)) 0 0;
	border-bottom: 1px solid var(--i-background_4);
	font-size: 1.4em;
	font-weight: 600;
}

/* Don't wrap forum category headers, since the collapse button will be on its own line */
.ipsBox__header:has(.ipsBox__header-toggle){
	flex-wrap: nowrap;
}

	.ipsBox__header :where(a),
	.ipsWidget__header :where(a),
	.ipsInnerBox__header :where(a){
		color: inherit;
	}

	.ipsBox__header-secondary,
	.ipsWidget__header-secondary,
	.ipsInnerBox__header-secondary{
		margin-inline-start: auto;
		font-size: var(--i-rem);
	}

.ipsBox,
.ipsEntry,
.ipsWizard{
	background-color: var(--i-box--ba-co);
	border-radius: var(--i-box--bo-ra);
	box-shadow: var(--i-box--bo-sh);
	border-width: var(--i-box--bo-wi);
	border-style: var(--i-box--bo-st);
	border-color: var(--i-box--bo-co);
}

/* Adding this class will ensure child elements inherit the border-radius while still allowing sticky tabs to work */
.ipsBox--clip{
	overflow: clip;
}

/* Remove styles from nested .ipsBox elements */
.ipsBox .ipsBox, .ipsDialog .ipsBox, .ipsDialog .ipsWizard, .ipsWizard .ipsBox, .ipsDialog .ipsWidget, .ipsWidget .ipsBox{
	box-shadow: none;
	border-width: 0;
	background: transparent;
}

	.ipsBox__header{
		flex: 0 0 auto; /* Useful when in flex-direction:column layouts */
		--i-co: var(--i-boxHeader--co);
		background-color: var(--i-boxHeader--ba-co);
		color: var(--i-co);
	}

	.ipsBox__padding, .ipsBox--padding{
		padding: var(--i-box--pa-bl) var(--i-box--pa-in);
	}	

	.ipsBox__footer{
		padding: var(--i-sp_2) var(--i-sp_3);
		background-color: var(--i-background_3);
		border-bottom-left-radius: inherit;
		border-bottom-right-radius: inherit;
	}

/* Inner boxes */
.ipsInnerBox{
	border: 2px solid var(--i-background_3);
	border-radius: var(--i-box--bo-ra);
}

	.ipsInnerBox__header{
		color: var(--i-color_hard);
		font-weight: 600;
		font-size: 1.1em;
	}

	.ipsInnerBox--padding, .ipsInnerBox__padding{
		padding: 2em;
	}


/* Tinted boxes */
.ipsInnerBox--inherit{
	background-color: var(--i-background_2);
}


/* Collapse icon */
.ipsBox__header-toggle{
	margin-inline-start: auto;
	background: color-mix(in srgb, var(--i-co) 5%, transparent);
	border-radius: 4px;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 14px;
	height: 1.7em;
	width: 2.6em;
}

@media (hover:hover){
	.ipsBox__header-toggle{
		opacity: .6;
		transition: opacity 0.15s linear;
		background: color-mix(in srgb, var(--i-co) 20%, transparent);
	}
	.ipsBox__header:not(:hover) .ipsBox__header-toggle{
		opacity: 0;
	}
}

	.ipsBox__header-toggle:hover,
	.ipsBox__header-toggle:focus-visible{
		opacity: 1 !important;
	}

	.ipsBox__header-toggle::before{
		content: "\2b";
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
	}

		.ipsBox__header-toggle[aria-expanded="true"]::before{
			content: "\f068";
		}

/* Collapsed forum category headers */
.ipsBox__header:has([aria-expanded="false"]){
	border-width: 0;
	border-radius: inherit;
}

/*
	----------------
	- Widgets
	----------------
*/

.ipsWidget{
	background: var(--i-widget--ba-co);
	border-radius: var(--i-widget--bo-ra);
	box-shadow: var(--i-widget--bo-sh);
	border-width: var(--i-widget--bo-wi);
	border-style: var(--i-widget--bo-st);
	border-color: var(--i-widget--bo-co);
	background-clip: padding-box;
	position: relative;
}

/* Remove widget styles from certain elements */
.ipsWidget[data-blockid^="app_core_advertisements_"],
.ipsWidget.ipsWidget--transparent {
	background: transparent;
	box-shadow: none;
	border-width: 0;
}

	.ipsWidget__header{
		flex: 0 0 auto; /* Useful in flex-direction:column elements */
		--i-co: var(--i-widget-header--co);
		color: var(--i-co);
		background-color: var(--i-widget-header--ba-co);
		font-size: 1.1em;
		font-weight: 600;
	}

	/* Used when widgets have been assigned custom background colors, padding, etc */
	.ipsWidget__customStyles{
		border-radius: inherit;
	}

	.ipsWidget__padding{
		padding: var(--Widget__padding--pa, 1.5em);
	}

	/* Remove padding from transparent widgets */
	:where(.ipsWidget--transparent) .ipsWidget__padding{
		padding: 0;
	}
	.ipsWidget:has(.ipsCarousel--page-builder-image-widget) .ipsWidget__padding{
		padding: 0;
	}

/* CMS navigation */
.ipsWidget__nav{
	font-weight: 500;
	padding: 5px;
}

.ipsWidget__nav :is(a, summary){
	display: flex;
	align-items: center;
	gap: .8em;
	padding: .7em;
	padding-inline-start: 1.4em;
	border-radius: min(var(--i-design-radius), 5px);
}

.ipsWidget__nav details details :is(a, summary){
	padding-inline-start: 3em;
}

.ipsWidget__nav details details details :is(a, summary){
	padding-inline-start: 4.6em;
}

.ipsWidget__nav :is(a, summary):hover{
	color: var(--i-color_hard);
	background-color: var(--i-background_2);
}

.ipsWidget__nav summary{
	color: var(--i-color_hard);
}

.ipsWidget__nav summary::after{
	margin: -2em 0;
	font-size: .8em;
	content: "\2b";
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	margin-inline-start: auto;
	width: 2em;
	height: 2em;
	color: var(--i-color_soft);
	border-radius: 4px;
	display: grid;
	place-content: center;
}

.ipsWidget__nav summary:hover::after{
	background: color-mix(in srgb, var(--i-color_soft) 10%, transparent);
}

.ipsWidget__nav [open] > summary::after{
	content: "\f068";
}

.ipsWidget__nav a{
	color: var(--i-color_root);
}

.ipsWidget__nav details a::before{
	content: "-";
	margin-inline-start: 1em;
	opacity: .5;
	align-self: baseline;
}

.ipsWidget__nav a[aria-current="page"]{
	background-color: var(--i-background_3);
	color: var(--i-color_hard);
}

/*
	----------------
	- Responsive pull
	----------------
*/
@media (max-width: 767px){
	html .ipsPull{
		border-radius: 0;
		margin-left: calc(var(--i-layout-gutter) * -1);
		margin-right: calc(var(--i-layout-gutter) * -1);
		border-left-width: 0;
		border-right-width: 0;
	}

		.ipsPull .ipsPull{
			margin-left: 0;
			margin-right: 0;
		}

		.ipsPull .ipsBox__header,
		.ipsPull .ipsButtonBar{
			border-radius: 0;
		}
}

/*
	----------------
	- Other
	----------------
*/

/* Let certain divs inherit border-radius, so it can correctly be applied to .ipsBox__header, etc */
:where(.ipsBox > [data-tableid]){
	border-radius: inherit;
}

/*
	----------------
	- Buttons
	----------------
*/

.ipsButtons{
	display: flex;
	align-items: center;
	justify-content: center;
	flex-wrap: wrap;
	gap: 7px;
}

	.ipsButtons--start{
		justify-content: flex-start;
	}
	.ipsButtons--end{
		justify-content: flex-end;
	}

	/* Let buttons determine their width */
	.ipsButtons > li{ display: contents; }

	/* Hide empty button containers */
	.ipsButtons:not(:has(.ipsButton)){ display: none }
	@supports not selector(a:has(b)){
		.ipsButtons:-moz-only-whitespace{ display: none }
	}

/* Full width buttons */
.ipsButtons--fill .ipsButton{
	flex-grow: 1;
}
.ipsButtons--fill .ipsButton--primary{
	flex-grow: 2;
}

@media (max-width: 600px){
	/* Buttons fill the entire width on small screens. */
	.ipsButtons :is(.ipsButton, .ipsButtonGroup){
		flex-grow: 1;
	}
	/* Primary buttons occupy more space */
	.ipsButtons .ipsButton--primary{
		flex-grow: 3;
	}
	/* If at least 3 buttons exist, make the primary button occupy its own row */
	.ipsButtons:has(> li:nth-child(3)) .ipsButton--primary{
		flex: 999 1 100%;
	}
		.ipsButtons:has(.ipsButtonGroup) .ipsButton--primary{
			flex: 999 1 auto;
		}

		.ipsButtons .ipsButton--text{
			--i-button--pa-in: 1em;
		}
}

/* Button groups  */
.ipsButtonGroup{
	--i-co: var(--i-color_soft);
	--i-outline-color: currentColor;
	align-items: stretch;
	background-clip: padding-box;
	background-color: var(--i-background_1);
	border: 1px solid color-mix(in srgb, var(--i-co) 20%, transparent);
	border-radius: calc(var(--i-button--bo-ra) * 1px);
	box-shadow: hsl(0 0% 0% / .06) 0px 2px 3px;
	color: var(--i-co);
	display: inline-flex;
	flex-wrap: wrap;
	gap: 3px;
	padding: 3px;
	vertical-align: baseline;
}

	.ipsButtonGroup--small{
		--i-button--pa-bl: .8em;
		--i-button--pa-in: 1.2em;
		--i-button--fo-si: .85em;
	}

	.ipsPageHeader .ipsButtonGroup{
		display: flex;
	}

	.ipsButtonGroup .ipsButton{
		flex: 1 1 auto;
	}

.ipsButton{
	--i-button--co: var(--i-co);
	--i-button--ba-co: transparent;
	--i-button--bo-co: transparent;
	--i-button-hover--ba-co: color-mix(in srgb, var(--i-button--ba-co), #fff 20%);
	--i-outline-color: var(--i-button--ba-co);
	align-items: center;
	background-color: var(--i-button--ba-co);
	border-width: var(--i-button--bo-wi);
	border-style: var(--i-button--bo-st);
	border-color: var(--i-button--bo-co);
	border-radius: calc(var(--i-button--bo-ra) * 1px);
	box-shadow: var(--i-button--bo-sh);
	color: var(--i-button--co);
	cursor: pointer;
	display: inline-flex;
	font-size: var(--i-button--fo-si, inherit);
	font-weight: var(--i-button--fo-we);
	gap: 0 .6em;
	justify-content: center;
	line-height: var(--i-button--li-he, 1);
	min-width: 44px;
	padding: var(--i-button--pa-bl) var(--i-button--pa-in);
	/* position: relative; */ /* This causes the "Save" button to overlap the auto-complete menu while editing the Poll widget */
	text-align: center;
	text-decoration: none !important;
	text-transform: var(--i-button--te-tr, none);
	touch-action: manipulation;
	vertical-align: baseline;
}

/* This is rarely used, but appears in the Buy Now button on a paid product (Eg. +GST) */
.ipsButton .i-color_soft{
	color: inherit;
	opacity: .6;
}

/* Fallback */
@supports not (color: color-mix(in srgb, red, red)){
	.ipsButton{
		--i-button-hover--ba-co: var(--i-button--ba-co);
	}
}

/* Flex gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsButton > :not(:first-child){
		margin-inline-start: .6em;
	}
}

	/* Links are sometimes placed inside div.button, such as on the "Manage Followed Content" page */
	.ipsButton a{
		color: inherit;
	}

	.ipsButton svg{
		height: 1em;
		width: auto;
	}

	.ipsButton:active{
		transform: translateY(1px);
	}

	@media (any-hover:hover){
		.ipsButton:hover{
			background-color: var(--i-button-hover--ba-co);
		}
	}

		.ipsButtonGroup > li{
			display: contents;
		}

		.ipsButtonGroup .ipsButton{
			border-radius: max(0px, var(--i-button--bo-ra) * 1px - 3px);
			flex: 1 1 auto;
			padding-top: calc(var(--i-button--pa-bl) - 3px);
			padding-bottom: calc(var(--i-button--pa-bl) - 3px);
		}

		.ipsButtonGroup .ipsButton:where(:hover){
			background-color: var(--i-background_3);
			color: var(--i-color_hard);
		}

		.ipsButtonGroup .ipsButton--active{
			--i-outline-color: var(--i-secondary);
			background-color: var(--i-secondary);
			color: var(--i-secondary-contrast);
		}

.ipsButton__segment{
	flex-grow: 0;
	padding: 0 .85em;
	border-inline-start: 1px solid transparent;
	border-color: color-mix(in srgb, currentColor 15%, transparent);
	display: flex;
	align-items: center;
	align-self: stretch;
	margin-top: calc(var(--i-button--pa-bl) * -.4);
	margin-bottom: calc(var(--i-button--pa-bl) * -.4);
	margin-inline-end: calc(var(--i-button--pa-in) * -1);
	margin-inline-start: calc(var(--i-button--pa-in) - .6em);
}

	.ipsButton--text{
		--i-button--co: var(--i-co);
		--i-outline-color: var(--i-button--co);
		--i-button-hover--ba-co: color-mix(in srgb, var(--i-button--co) 5%, transparent);
	}

	.ipsButton--inherit,
	.ipsButton--follow:not(.ipsButton--follow-active){
		--i-outline-color: var(--i-button--co);
		--i-button--co: currentColor;
		--i-button--bo-co: transparent;
		--i-button--ba-co: color-mix(in srgb, var(--i-button--co) 10%, transparent);
		--i-button-hover--ba-co: color-mix(in srgb, var(--i-button--co) 15%, transparent);
	}

	.ipsButton--primary{
		--i-button--ba-co: var(--i-primary-button--ba-co);
		--i-button--co: var(--i-primary-button--co);
	}

	.ipsButton--secondary{
		--i-button--ba-co: var(--i-secondary-button--ba-co);
		--i-button--co: var(--i-secondary-button--co);
	}

	.ipsButton--positive{
		--i-button--ba-co: var(--i-color_positive);
		--i-button--co: hsl(0 0% 100%);
	}

	.ipsButton--negative{
		--i-button--ba-co: var(--i-color_negative);
		--i-button--co: hsl(0 0% 100%);
	}

	.ipsButton--soft{
		--i-outline-color: currentColor;
		--i-button--ba-co: var(--i-background_1);
		--i-button-hover--ba-co: color-mix(in srgb, var(--i-button--co) 3%, var(--i-button--ba-co));
		--i-button--bo-co: color-mix(in srgb, var(--i-button--co) 20%, transparent);
		--i-button--bo-sh: hsl(0 0% 0% / .06) 0px 2px 3px;
		background-clip: padding-box;
	}

	.ipsButton--overlay{
		--i-button--co: hsl(0 0% 100%);
		--i-button--ba-co: hsl(0 0% 0% / .4);
		--i-button-hover--ba-co: hsl(0 0% 0% / .7);
		-webkit-backdrop-filter: blur(4px);
		backdrop-filter: blur(4px);
	}

	.ipsButton--follow-active{
		--i-button--ba-co: var(--i-secondary);
		--i-button--co: var(--i-secondary-contrast);
	}

	.ipsButton[disabled],
	.ipsButton[aria-disabled="true"],
	.ipsButton--disabled{
		filter: grayscale(1) opacity(60%);
		pointer-events: none;
		cursor: not-allowed;
	}

/* Follow buttons */
[data-controller="core.front.core.followButton"]{
	display: contents;
}
.ipsButton--follow{
	padding: 0;
	gap: 0;
}
	.ipsButton--follow > a,
	.ipsButton--follow > span{
		display: flex;
		gap: .6em;
		padding: var(--i-button--pa-bl) var(--i-button--pa-in);
		color: inherit;
	}
	.ipsButton--follow a{
		pointer-events: auto;
		/* Necessary for full width Follow buttons */
		flex: 1 1 auto;
		justify-content: center;
	}
	.ipsButton--follow a:first-child{
		border-start-start-radius: inherit;
		border-end-start-radius: inherit;
	}
	.ipsButton--follow a:last-child{
		border-start-end-radius: inherit;
		border-end-end-radius: inherit;
	}
	@media (any-hover:hover){
		.ipsButton--follow-active{
			--i-button-hover--ba-co: var(--i-button--ba-co);
		}
		.ipsButton--follow-active a:hover{
			background-color: color-mix(in srgb, currentColor 10%, transparent);
		}
	}
	.ipsButton--follow .ipsButton__segment{
		margin: 0;
		padding: var(--i-button--pa-bl) calc(var(--i-button--pa-in) * .7);
		flex: 0 0 auto;
	}

/* Larger size */
.ipsButton--large,
.ipsButtons--large,
.ipsButtons--main{
	--i-button--pa-bl: 1.2em;
	--i-button--pa-in: 1.8em;
}

.ipsButtonGroup.ipsButtons--large{
	--i-button--pa-in: .8em;
}

.ipsButton--small,
.ipsButtons--small{
	--i-button--pa-bl: .8em;
	--i-button--pa-in: 1.2em;
	--i-button--fo-si: .85em;
}

.ipsButton--tiny,
.ipsButtons--tiny{
	--i-button--pa-bl: .4em;
	--i-button--pa-in: 1.2em;
	--i-button--fo-si: .85em;
}

.ipsButtons--main{
	justify-content: flex-end;
}

@media (max-width: 700px){
	.ipsButtons--main{
		--i-button--pa-bl: .9em;
		--i-button--pa-in: .9em;
	}
}

/* Automatic contrast for inherited buttons in ipsButtons--main */
:where(.ipsButtons--main:not(.ipsBox *)){
	--i-co: var(--i-color_contrast, currentColor);
	color: var(--i-co);
}

.ipsButton--wide{
	width: 100%;
}

/* Icon button */
.ipsButton--icon{
	--i-button--pa-in: .75em;
}

/* Dropdown icon in buttons */
.ipsMenuCaret{
	flex: 0 0 auto;
	align-self: center;
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	font-style: normal;
	font-size: .8em;
	opacity: .7;
}

	.ipsMenuCaret::before{
		content: "\f0d7";
	}

	button[aria-expanded="true"] .ipsMenuCaret::before{
		content: "\f0d8";
	}

/* Social buttons */
.ipsSocial {
	color: #fff;
	display: flex;
	align-items: stretch; /* Overwrite default Safari styles */
	font-weight: 600;
	border-radius: min(var(--i-design-radius), var(--i-button--bo-ra) * 1px);
	overflow: hidden;
	width: 100%;
	text-align: center;
	box-shadow: inset color-mix(in srgb, var(--i-co) 20%, transparent) 0px 0px 0px 1px;
}

	@media (any-hover:hover){
		.ipsSocial:hover{
			filter: brightness(1.07);
		}
	}

	.ipsSocial__icon {
		display: grid;
		place-content: center;
		flex: 0 0 auto;
		width: 2.6em; /* Needed to prevent text from squashing */
		background: hsl(0 0% 0% / .2);
		font-size: 1.2em;
	}

		.ipsSocial__icon svg{
			fill: currentColor;
			height: 1em;
		}

		.ipsSocial__icon img {
			max-width: 1em;
		}

	.ipsSocial__text {
		padding: calc(1px + var(--i-button--pa-bl)) var(--i-button--pa-in);
		flex: 1 1 auto;
		line-height: 1;
	}

	.ipsSocial--microsoft {
		background-color: #008b00;
	}

	.ipsSocial--facebook {
		background-color: #3a579a;
	}

	.ipsSocial--twitter {
		background-color: #000000;
	}

	.ipsSocial--linkedIn {
		background: #007eb3;
	}

	.ipsSocial--google {
		background-color: #4285F4;
	}

	.ipsSocial--internal {
		background-color: #008b00;
	}

@property --i-card--backdrop-scroll{
	syntax: "<percentage>";
	inherits: true;
	initial-value: 100%;
}
@property --i-card--backdrop-transition{
	syntax: "<percentage>";
	inherits: true;
	initial-value: 0%;
}

i-card{
	--i-card--ba-co: var(--i-box--ba-co);
	--i-card--bo-sh: hsl(0 0% 0% / .4) 0px 20px 60px;
	--i-card--tr-du: .2s;
	--i-card--bo-ra: 14px;
	--i-card--backdrop-transition: 0%;
	--i-card--backdrop-scroll: 100%;
	--i-card--translate-closed: 0% 100%;
	display: flex;
	flex-direction: column;
	scrollbar-width: none;
	transition-property: display, overlay, --i-card--backdrop-transition;
	transition-behavior: allow-discrete;
	transition-timing-function: ease-in;
	transition-duration: var(--i-card--tr-du);
	/* Reset popover styles */
	inset: 0;
	width: auto;
	height: auto;
	/* Polyfill */
	position: fixed;
	top: 0; left: 0; right: 0; bottom: 0;
	/* Used for mobile and off-canvas */
	overflow: auto;
	overscroll-behavior: contain;
	scroll-snap-type: both mandatory;
}

/* Prevents Chrome 133 from crashing when closing the popover */
@supports (-webkit-app-region: drag) and (not (appearance: base-select)) {
	i-card{
		transition-behavior: normal;
	}
}

[data-ips-scheme="dark"] i-card{
	--i-card--bo-sh: inset hsl(0 0% 100% / .1) 0px 1px 0px, hsl(0 0% 0% / 0.9) 0px 30px 60px, hsl(0 0% 0% / .3) 0px 0px 0px 1px;
}

html:has(i-card:popover-open){
	/* Prevent page from being scrolled */
    overflow: hidden;
    overscroll-behavior: none;
}
html:has(i-card.\:popover-open){
	overflow: hidden;
}

i-card:popover-open{
	--i-card--backdrop-transition: 100%;
}
i-card.\:popover-open{
	--i-card--backdrop-transition: 100%;
}
@starting-style{
	i-card:popover-open{
		--i-card--backdrop-transition: 0%;
	}
}

/* We need to use a pseudo element here since Safari instantly deletes the ::backdrop from the DOM on close. Last checked in 26.2 */
i-card::before{
	content: "";
	position: fixed;
	pointer-events: none;
	inset: inherit;
	background: hsl(0 0% 0% / .6);
	opacity: var(--i-card--backdrop-transition);
	-webkit-backdrop-filter: blur(1px);
	backdrop-filter: blur(1px);
}

i-card::-webkit-scrollbar{
	-webkit-appearance: none;
	display: none;
	width: 0px;
}

/* Prevent outside styles from leaking in */
.iCard:not(#x){
	font-size: var(--i-rem);
	font-style: normal;
	font-weight: normal;
	letter-spacing: normal;
	text-align: start;
	text-shadow: none;
	text-transform: none;
}

/* Card */
.iCard{
	flex: 0 0 auto;
	background: var(--i-card--ba-co);
	color: var(--i-color_root);
	border-radius: var(--i-card--bo-ra, 8px);
	box-shadow: var(--i-card--bo-sh);
	display: flex;
	flex-direction: column;
	/* Sit on top of fixed background */
	position: relative;
	min-height: 15em;
	max-height: calc(100% - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 30px);
	transition-property: opacity, translate;
	transition-timing-function: ease-in-out;
	transition-duration: var(--i-card--tr-du);
}

i-card:not(:popover-open) > .iCard{
	translate: var(--i-card--translate-closed);
}
@starting-style{
	:popover-open > .iCard{
		translate: var(--i-card--translate-closed);
	}
}

/* Swipe to dismiss */
.iCardSwipe{
	flex: 0 0 20px;
	display: block;
	margin-bottom: 20px;
	scroll-snap-align: start;
}
	/* Repaint Safari to prevent excess overscroll. Last tested in 26.2 */
	@supports (-webkit-hyphens: auto){
		i-card:popover-open .iCardSwipe{
			transition: var(--i-card--tr-du);
		}
		@starting-style{
			i-card:popover-open .iCardSwipe{
				flex-basis: 21px;
			}
		}
	}

/* Light dismiss button */
.iCardDismiss{
	/* Ensure this element is hidden but still usable, since parent styles can leak in (background colors, etc) */
	opacity: 0;
	-webkit-tap-highlight-color: transparent;
	width: 100%;
	height: 100%;
	flex: 0 0 auto;
}

/* Scroll snapping: Used for mobiles and offcanvas */
.iCardSnap{
	order: 1; /* This is prepended via JS, so move it to the end */
	flex: 0 0 1px; /* This element must occupy space for snapping to occur (Firefox bug) */
	scroll-snap-align: end;
}

/* Large screens: Centered card */
@media (min-width: 601px){
	i-card{
		--i-card--translate-closed: 0% 100px;
	}
	.iCard{
		margin: auto;
		width: min(800px, 100% - 40px);
		opacity: 0;
	}
	:popover-open > .iCard{
		opacity: 1;
	}
	.\:popover-open > .iCard{
		opacity: 1;
	}
	@starting-style{
		:popover-open > .iCard{
			opacity: 0;
		}
	}
	/* Hide swipe-to-dismiss and snap on large screens */
	.iCardSnap,
	.iCardSwipe{
		display: none;
	}
	/* Full-screen dismiss button */
	.iCardDismiss{
		position: fixed;
	}
}

/* Small screens: Card is attached to bottom of screen */
@media (max-width: 600px){
	i-card{
		--i-card--translate-closed: 0 calc(100% + 20px);
	}
	/* Fading backdrop */
	i-card::before{
		opacity: min(var(--i-card--backdrop-scroll), var(--i-card--backdrop-transition));
	}
	.iCard{
		flex: 0 0 auto;
		/* Full width, touching bottom of screen */
		width: auto;
		margin: 5px;
		margin-bottom: calc(env(safe-area-inset-bottom, 0px) + 5px);
		margin-top: auto;
	}

	/* Touch enhancements */
	@media (hover:none){
		/* Drag handle */
		i-card:defined .iCard::before{
			content: "";
			display: block;
			background: hsl(0 0% 100% / .6);
			box-shadow: inset 0px 1px 0px hsl(0 0% 100% / .5);
			-webkit-backdrop-filter: blur(8px);
			backdrop-filter: blur(8px);
			border-radius: 6px;
			width: 50px;
			height: 6px;
			position: absolute;
			top: -14px;
			left: calc(50% - 25px);
			pointer-events: none;
		}
	}

	/* Zero-JS fallback: */
	/* 1. Prevent the dismiss button from causing a scrollbar since swipe-to-dismiss isn't available */
	i-card:not(:defined) .iCardDismiss{
		flex: 1 1 auto;
	}
	/* 2. Ensure tapping backdrop closes dropdowns */
	html:has(i-card:not(:defined):popover-open){
		pointer-events: none;
	}
	i-card:not(:defined) .iCard{
		pointer-events: auto;
	}
}

/* Fade out the backdrop when scrolling to dismiss */
@supports ((animation-timeline: scroll()) and (animation-range: 0 100%)){
	@keyframes iCardScroll{
		from{
			--i-card--backdrop-scroll: 0%;
		}
	}
	i-card:defined{
		animation: iCardScroll linear forwards;
		animation-timeline: scroll(self);
		animation-range: 0 100%;
	}
}

/* Off-canvas cards */
i-card.ipsOffCanvas{
	--i-card--translate-closed: 100% 0%;
	flex-direction: row;
	/* Inline scroll animation */
	animation-timeline: scroll(self inline);
	/* Keep the footer visible */
	bottom: var(--i-mobileFooter--he);
}
/* Align content to the end for undefined cards */
i-card.ipsOffCanvas:not(:defined){
	justify-content: end;
}
	/* RTL: To keep the JS simple, cards always animate in from the right side */
	:where([dir="rtl"] .ipsOffCanvas){
		direction: ltr;
	}
		:where([dir="rtl"] .ipsOffCanvas > .iCard){
			direction: rtl;
		}
	/* Fading backdrop */
	.ipsOffCanvas::before{
		opacity: min(var(--i-card--backdrop-scroll), var(--i-card--backdrop-transition));
	}
	/* Hide drag handle */
	.ipsOffCanvas:defined .iCard::before{
		content: none;
	}
	.ipsOffCanvas .iCard{
		width: min(100% - 10px, 400px);
		margin: 5px;
		margin-top: calc(env(safe-area-inset-top, 0px) + 5px);
		max-height: none;
		opacity: 1;
	}
	/* Display snap/swipe elements */
	.ipsOffCanvas .iCardSnap,
	.ipsOffCanvas .iCardSwipe{
		display: block;
	}
	/* Let dismiss occupy space */
	.ipsOffCanvas .iCardDismiss{
		position: static;
	}

.iCard__header{
	flex: 0 0 auto;
	padding: 1.2em 1.5em;
	color: var(--i-color_hard);
	border-bottom: 1px solid var(--i-background_5);
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: .8em;
	font-size: 1.2em;
	font-weight: 700;
}

:where(.iCard__header) a{
	color: inherit;
}
:where(.iCard__header a):hover{
	text-decoration: underline;
}

.iCard__headerButtons{
	margin: -.8em;
	margin-inline-start: auto;
	flex: 0 0 auto;
	display: flex;
}

.iCard__headerButtons a,
.iCard__headerButtons button{
	width: max(44px, 2.5em);
	height: max(44px, 2.5em);
	display: grid;
	place-content: center;
	border-radius: min(var(--i-design-radius), 5px);
	opacity: .6;
	text-decoration: none;
}
@media(hover:hover){
	.iCard__headerButtons a:hover,
	.iCard__headerButtons button:hover{
		background: color-mix(in hsl, currentColor 10%, transparent);
	}
}

.iCard__content{
	overflow: auto;
	scrollbar-width: thin;
	flex: 1 1 auto;
	scroll-snap-type: both mandatory;
}

.iCard__footer{
	flex: 0 0 auto;
	padding: 1em;
	color: var(--i-color_soft);
	border-top: 1px solid var(--i-background_5);
	font-weight: 500;
}

a.iCard__footer{
	display: block;
	text-align: center;
	border-bottom-left-radius: inherit;
	border-bottom-right-radius: inherit;
}

a.iCard__footer:hover{
	background: color-mix(in srgb, currentColor 6%, transparent);
}

/* This instantly hides the popover after the swipe gesture. It prevents a "backdrop flash" in Safari caused by the -scroll variable reverting back to 100% once the swipe gesture has occurred. Last tested in 26.1 */
/* And ensure menus with [autofocus] inputs sit above the keyboard in iOS. Without this, the keyboard overlaps the menu. Fixed in iOS 26 */
i-card[hidden-via-swipe],
i-card:has([autofocus]):popover-open{
	--i-card--tr-du: 0s;
}

/* Prevent the menu from closing when the keyboard is active, since a vertical swipe can often close the menu accidentally */
i-card:has(input:focus, textarea:focus){
	overflow: hidden;
}

/*
	----------------
	- Carousel
	----------------
*/

.ipsCarousel{
	--i-carousel--show: 1;
	--i-column-gap: 1em;
	--i-carousel--pa: 0;
	/* --i-carousel--scroll: 1; */
	/* --i-carousel--autoplay: 1000; */
	display: flex;
	gap: var(--i-column-gap);
	overflow-x: scroll;
	overscroll-behavior-x: contain;
	scroll-behavior: smooth;
	scroll-snap-type: x mandatory;
	padding: var(--i-carousel--pa);
	scroll-padding-inline: var(--i-carousel--pa);
	scrollbar-width: none;
	scrollbar-color: color-mix(in srgb, var(--i-co) 20%, transparent) transparent;
	position: relative; /* Required for scrollLeft as part of i-carousel-navigation */
}

/* Scroll-padding prevents entry.isIntersecting from working in RTL Safari. Without this fix, carousel arrow navigation can break. Last tested in 26.1 */
@supports (-webkit-hyphens: auto){
	[dir="rtl"] .ipsCarousel::after{
		content: "";
		flex: 0 0 max(var(--i-carousel--pa) - var(--i-column-gap), 1px);
	}
}

:where(.ipsCarousel){
	--i-basis: 0%; /* This is set to 0% which reduces the flex-basis of items to the --i-carousel-show amount */
}

/* Allow basis to control the item width */
.ipsCarousel:where([class*=" i-basis_"], [class^="i-basis_"]){
	--i-carousel--show: 99; /* 99 disables the maximum column amount */
}

/* Add padding to carousels if necessary */
.ipsCarousel--padding{
	--i-carousel--pa: 2em;
}

.ipsCarousel--1{ --i-carousel--show: 1 }
.ipsCarousel--2{ --i-carousel--show: 2 }
.ipsCarousel--3{ --i-carousel--show: 3 }
.ipsCarousel--4{ --i-carousel--show: 4 }
.ipsCarousel--5{ --i-carousel--show: 5 }
.ipsCarousel--6{ --i-carousel--show: 6 }

.ipsCarousel::-webkit-scrollbar {
	-webkit-appearance: none;
	height: 0px;
}

/* Scrollbars */
@media(hover: hover){
	.ipsCarousel--scrollbar{
		padding-bottom: 20px;
		scrollbar-width: thin;
	}
	.ipsCarousel--scrollbar::-webkit-scrollbar {
		height: 28px;
	}
	.ipsCarousel--scrollbar::-webkit-scrollbar-track {
		background: transparent;
		border-radius: 6px;
	}
	.ipsCarousel--scrollbar::-webkit-scrollbar-thumb {
		border: 12px solid transparent;
	    border-radius: 20px;
	    background-color: color-mix(in srgb, var(--i-co) 0%, transparent);
	    background-clip: content-box;
	}
		.ipsCarousel--scrollbar:hover::-webkit-scrollbar-thumb{
	    	background-color: color-mix(in srgb, var(--i-co) 20%, transparent);
		}
		.ipsCarousel--scrollbar::-webkit-scrollbar-thumb:hover{
	    	background-color: var(--i-co);
	    	border-width: 10px;
		}
}

/* Carousel items */
.ipsCarousel > *{
	flex: 0 0 auto;
	flex-basis: min(
		100%,
		clamp(
			var(--i-basis),
			(100% - (var(--i-column-gap) * (var(--i-carousel--show) - 1))) / var(--i-carousel--show),
			100%
		)
	);
	scroll-snap-align: start;
}

.ipsCarousel > *:last-child{
	scroll-snap-align: end;
}

	.ipsCarousel:has(:focus-visible):focus-within > *:not(:focus-within){
		scroll-snap-align: none;
	}


/* Navigation buttons */
.ipsCarouselNav{
	display: flex;
	justify-content: center;
}

	:is(.ipsBox__header, .ipsWidget__header) .ipsCarouselNav{
		margin: -2em auto;
		margin-inline-end: -0.8em;
	}

	/* Add space between carousel and controls, unless the carousel already has padding */
	:where(.ipsCarousel:not(.ipsCarousel--padding, .ipsCarousel--images) + .ipsCarouselNav, .ipsCarouselNav + .ipsCarousel:not(.ipsCarousel--padding, .ipsCarousel--images)){
		padding-top: 2em;
	}

	/* If the carousel needs padding, the bottom navigation probably needs a space too */
	:where(.ipsCarousel--padding + .ipsCarouselNav){
		padding-bottom: 1em;
	}

.ipsCarouselNav__button{
	display: grid;
	place-content: center;
	min-height: max(34px,2em);
	min-width: max(34px,2.5em);
	border-radius: min(var(--i-design-radius), 6px);
	touch-action: manipulation;
}

@media (any-hover:hover){
	.ipsCarouselNav__button:hover{
		background: color-mix(in srgb, currentColor 4%, transparent);
	}
}

	[dir="ltr"] [data-carousel-arrow="prev"] .fa-ips::before,
	[dir="rtl"] [data-carousel-arrow="next"] .fa-ips::before{
		content: "\f104";
	}

	[dir="rtl"] [data-carousel-arrow="prev"] .fa-ips::before,
	[dir="ltr"] [data-carousel-arrow="next"] .fa-ips::before{
		content: "\f105";
	}

/*
	----------------
	- Thumbnail carousel: Used for images of different sizes such as Download screenshots
	----------------
*/

.ipsCarousel--images{
	--_height: 160px;
	min-height: 1em;
}

.ipsCarousel--images > *{
	flex: 0 0 auto;
	max-width: 100%;
}

	/* Force image to be correct height */
	.ipsCarousel--images .ipsThumb{
		display: block;
	}

	.ipsCarousel--images :is(.ipsThumb, .ipsFigure){
		aspect-ratio: var(--i-ratio, auto);
		height: var(--_height);
		width: auto;
	}

	.ipsCarousel--images .ipsThumb img{
		width: auto;
	}

	.ipsCarousel--images .ipsFigure:has(video){
		aspect-ratio: 16/9;
	}

.ipsColorSchemeChanger{
	flex: 0 0 auto;
	display: flex;
	gap: 1px;
}

	.ipsColorSchemeChanger button{
		display: grid;
		place-content: center;
		width: 2.8em;
		height: 2.8em;
		border-radius: min(var(--i-design-radius), 4px);
	}

		.ipsColorSchemeChanger button:hover{
			background-color: hsl(0 0% 100% / .1);
			background-color: color-mix(in srgb, currentColor 10%, transparent);
		}

		.ipsColorSchemeChanger button[aria-current]{
			background-color: hsl(0 0% 100% / .2);
			background-color: color-mix(in srgb, currentColor 20%, transparent);
		}

	.ipsColorSchemeChanger [aria-current] :is(.fa-lightbulb, .fa-moon){
		font-weight: bold;
	}

/* Hide if the setting says so */
[data-ips-theme-setting-change-scheme="0"] [data-controller="core.front.core.colorScheme"]{
	display: none;
}

.ipsComposeAreaWrapper{
	background: var(--i-background_2);
	padding: 1.4em;
}

/* Add a border and inherit the border-radius when necessary (eg. database reviews/comments) */
.ipsBox .ipsComposeAreaWrapper{
	border-radius: 0 0 var(--i-box--bo-ra) var(--i-box--bo-ra);
	border-top: 1px solid var(--i-background_4);
}

/* Join the conversation */
.cGuestTeaser{
	padding: 2em;
}
.ipsComposeAreaWrapper .cGuestTeaser{
	padding: 0;
	margin-bottom: 2em;
}

/* Editor ipsBox */
.ipsComposeArea{
	display: flex;
	gap: 1.2em;
}

	.ipsComposeArea__photo{
		flex: 0 0 50px;
	}

	@media (max-width: 767px){
		.ipsComposeArea__photo{
			display: none;
		}
	}

	.ipsComposeArea_editor{
		flex: 1 1 100%;
	}

	@media (min-width: 768px){
		.ipsComposeArea__photo + .ipsComposeArea_editor .ipsEditor::before{
			content: '';
			width: 10px;
			height: 10px;
			position: absolute;
			border: inherit;
			border-inline-end-width: 0 !important;
			border-bottom-width: 0 !important;
			top: 19px;
			inset-inline-end: calc(100% - 5px);
			transform: rotate(calc(-45deg * var(--i-lang-dir)));
			background: var(--i-background_1);
			box-sizing: content-box;
		}

		.ipsComposeArea__photo + .ipsComposeArea_editor .ipsEditor:focus-within::before{
			border-color: var(--i-input-active--bo-co);
		}
	}

.ipsComposeArea_editor .ipsNotification {
	top: 0;
}

.ipsComposeArea_dummy {
	padding: 1em;
	color: var(--i-color_soft);
	cursor: pointer;
}

.ipsComposeArea_dummy i{
	margin-inline-end: .3em;
}

.ipsComposeArea_dummy .i-color_warning{
	display: block;
	font-weight: 500;
}

/* Post preview */
.ipsComposeArea_editor [data-role="previewContainer"] iframe{
	--i-compose-frame-width: 100%;
	width: min(100%, var(--i-compose-frame-width));
}

	[data-preview-size="tablet"] [data-role="previewContainer"] iframe {--i-compose-frame-width: 780px;}
	[data-preview-size="phone"] [data-role="previewContainer"] iframe {--i-compose-frame-width: 375px;}

	.ipsComposeArea_smallPreview {
		box-shadow: hsl(0 0% 0% / .1) 0px 5px 16px -5px;
		margin: 10px 0;
	}

	.ipsComposeArea_editor [data-action="closePreview"],
	.ipsComposeArea_editorPaste .ipsComposeArea_editorPasteSwitch {
		font-family: arial, sans-serif;
		width: 1.5em;
		height: 1.5em;
		border-radius: 50%;
		font-size: 20px;
		background: #000;
		color: #fff;
		display: grid;
		place-content: center;
		text-decoration: none !important;
		flex: 0 0 auto;
		cursor: pointer;
		margin-inline-start: auto;
	}

/* Paste bar */
.ipsComposeArea_editorPaste {
	background: var(--i-background_dark);
	color: var(--i-color_background-dark-contrast);
	display: flex;
	align-items: center;
	gap: 1em;
	font-size: .9em;
	border-radius: 5px;
	padding-inline-start: 1em;
	padding-inline-end: .5em;
	min-height: 3.5em;
}

	.ipsComposeArea_editorPaste[style*="block"]{
		display: flex !important;
	}

	.ipsComposeArea_editorPaste .fa-solid{
		margin-inline-end: .6em;
	}

.ipsComposeArea_editorPaste a {
	color: inherit;
	text-decoration: underline;
}

.ipsComposeArea--textarea {
	position: relative;
}

/* Ensure notice bars are hidden whenever editor is minimized */
.ipsComposeArea_minimized .ipsComposeArea_editorPaste {
	display: none !important;
}

/* SIDEBAR */
.ipsComposeArea_sidebar {
	--i-basis: 300px !important;
	display: flex;
	flex-direction: column;
	background: var(--i-background_2);
	border: 1px solid var(--i-background_4);
	border-radius: var(--i-box--bo-ra);
}

.ipsComposeArea_sidebar [data-role="tagsList"] {
	overflow-y: auto;
	flex: 1 0 360px;
}

.ipsComposeArea_sidebar [data-tagKey] {
	width: 100%;
	padding: 1.5em;
	cursor: pointer;
	word-break: break-word;
	border-bottom: 1px solid var(--i-background_4);
}

.ipsComposeArea_sidebar [data-tagKey]:hover{
	background-color: var(--i-background_1);;
}

.ipsComposeArea_sidebar [data-tagkey] code {
	display: block;
	padding: 0 !important;
	font-size: 0.9em;
	background-color: transparent;
}

/* Drag files here to attach */
.ipsComposeArea_dropZone {
	padding: 0.8em 1em;
	padding-inline-end: .3em;
	display: grid;
	grid-template-columns: auto 1fr;
	align-items: baseline;
	gap: .7em;
	margin: .5em;
	background-color: var(--i-background_3);
	border-radius: 5px;
}

/* Existing attachment/stock photo */
.ipsComposeArea__media-other{
	margin: -.6em 0;
}
.ipsComposeArea__media-other a {
	font-size: max(1em, 16px);
	padding: .4em .8em;
	display: block;
	color: var(--i-color_soft);
	border-radius: min(var(--i-design-radius), 5px);
}

	.ipsComposeArea__media-other a:hover{
		color: var(--i-color_root);
		background: var(--i-background_1);
	}

/* Compose warnings */
.ipsComposeArea_warning {
	color: var(--i-color_warning);
	margin-bottom: 1.4em;
	font-weight: 500;
}

@media (min-width: 768px){
	.ipsComposeArea_warning{
		margin-inline-start: 75px;
	}
}

	.ipsComposeArea--unavailable {
		pointer-events: none;
	}

/* ATTACHMENTS */
.ipsUploader{
	font-size: var(--i-font-size);
	font-weight: normal;
}
	.ipsUploader__buttons{
		display: flex;
		flex-wrap: wrap;
		gap: .5em;
	}

	.ipsAttachment_dropZoneSmall_info{
		flex: 999 1 50%;
		display: grid;
	}

	.ipsUploader__container {
		margin-top: .4em;
		display: grid;
		gap: 1em;
	}

	/* Hide empty file list if files have been uploaded and then deleted */
	.ipsUploader__container:not(:has(*)){
		display: none;
	}

	.ipsUploader__container--files {
		grid-template-columns: repeat(auto-fit, minmax(min(350px, 100%), 1fr));
	}
	.ipsUploader__container--images {
		grid-template-columns: repeat(auto-fill, minmax(min(180px, 100%), 1fr));
	}

	.ipsUploader__row {
		--_ba-co: var(--if-light,var(--i-background_1)) var(--if-dark, var(--i-background_5));
		background: var(--_ba-co);
		border-radius: min(var(--i-design-radius), 6px);
		padding: .7em;
		position: relative;
		display: flex;
		align-items: center;
		box-shadow: hsl(0 0% 5% / 7%) 0px 1px 1px, hsl(0 0% 5% / 7%) 0px 5px 16px;
		gap: 1em;
	}

		.ipsUploader__row.ipsAttach_error {
			border-color: var(--i-color_negative) !important;
			background: var(--i-background_negative-soft);
		}

			.ipsUploader__row.ipsAttach_error .ipsUploader__rowPreview__generic {
				background: var(--i-background_1);
			}

			.ipsUploader__row.ipsAttach_error .ipsUploader__rowPreview__generic i[class*=" fa-"]:before {
				content: "\f071";
			}

		.ipsUploader--insertable .ipsUploader__row {
			cursor: pointer;
		}

		.ipsUploader__container--files .ipsUploader__row {
			height: 110px;			
		}

		.ipsUploader__container--images .ipsUploader__row {
			display: block;
		} 

	.ipsUploader__rowPreview {
		text-align: center;
		align-self: stretch;
		flex: 0 0 100px;
		background-image: none !important; /* Uploader sets the background image, but in this scenario we don't want to use it */
	}

		.ipsUploader__container--images .ipsUploader__rowPreview,
		.ipsUploader__row[data-filetype="video"] .ipsUploader__rowPreview__generic {
			height: 140px;
		}

		.ipsUploader__row :is(img, video) {
			width: 100%;
			height: 100%;
			object-fit: scale-down;
			border-radius: min(var(--i-design-radius), 5px);
			pointer-events: none;
		}

		.ipsUploader__rowPreview__generic {
			background: var(--i-background_3);
			height: 100%;
			display: grid;
			place-content: center;
		}

		.ipsUploader__rowPreview__generic [class*="fa-"] {
			font-size: 22px;
			color: var(--i-color_soft);
		}

	.ipsUploader_rowMeta {
		flex: 1 1 100%;
		position: relative;
		max-width: 100%;
	}

	.ipsUploader__container--images .ipsUploader_rowMeta {
		padding: .6em .3em .3em;
	}

	.ipsUploader_rowTitle {
		font-weight: 550;
		color: var(--i-color_hard);
		white-space: nowrap;
		overflow: hidden;
		width: 100%;
		text-overflow: ellipsis;
	}

	.ipsUploader_rowDesc{
		color: var(--i-color_soft);
	}

	.ipsUploader__rowDelete {
		font-family: Arial, sans-serif;
		width: 1.38em;
		height: 1.38em;
		background: var(--i-base-contrast_5);
		color: var(--i-base_2);
		display: grid;
		place-content: center;
		border-radius: 50%;
		position: absolute;
		top: -4px;
		font-size: 16px;
		text-decoration: none;
		inset-inline-end: -4px;
	}

	.ipsUploader .ipsMeter {
		margin-top: 8px;
	}

	.ipsUploader__rowInsert {
		position: absolute;
		top: 0;
		bottom: 0;
		inset-inline-end: 0;
		background: var(--i-background_1);
		background: 
			linear-gradient(
				to right,
				color-mix(in srgb, var(--_ba-co) 0%, transparent),
				var(--_ba-co) 2em
			);
		display: flex;
		align-items: center;
		padding-inline-start: 3em;
	}

		.ipsUploader__rowInsert a {
			font-size: .9em;
			color: var(--i-color_primary);
			text-decoration: none;
			font-weight: 500;
		}

		@media (min-width: 980px){
			.ipsUploader--insertable .ipsUploader__row:not(:hover) .ipsUploader__rowInsert {
				opacity: 0;
			}
		}

@media screen and (max-width: 979px) {
	.ipsUploader__container--files .ipsUploader__row {
		height: auto;
	}
	.ipsUploader__container--images .ipsUploader__rowPreview{
		max-height: 100px;
	}
}

.ipsAttachment_dropZone {
	background-color: var(--if-light, var(--i-background_3)) var(--if-dark, var(--i-background_2));
	padding: 1.4em;
	transition: background-color 0.2s;
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 1em 1.4em;
	border-radius: min(var(--i-design-radius), 5px);
}

:is(.ipsAttachment_dropZone, .ipsComposeArea_dropZone).ipsDragging {
	background-color: var(--i-background_4);
}

.ipsUploader__icon{
	font-size: 1.1em;
	color: var(--i-color_soft);
	opacity: .5;
}

.ipsAttachment_fileList{
	flex: 1 1 100%;
}

	/* Hide empty file lists */
	.ipsAttachment_fileList:has(.ipsUploader__container:empty),
	.ipsAttachment_fileList:has([data-role="fileList"]:empty){
		display: none;
	}

.ipsAttachment_dropZone * {
	/*pointer-events: none;  This prevents dragleave from firing when dragging over elements in the drop zone */
}

	.ipsAttachment_dropZone a,
	.ipsAttachment_dropZone .moxie-shim,
	.ipsAttachment_dropZone .moxie-shim * {
		pointer-events: auto; /* Reinstate default events for button */
	}

	.ipsAttachment__desc{
		color: var(--i-color_hard);
		font-weight: 550;
		font-size: 1em;
	}

		.ipsAttachment__desc span{
			cursor: pointer;
			position: relative;
			z-index: 1;
			text-decoration: underline;
		}

	.ipsAttachment_supportDrag:is([data-supports-drag="false"] *),
	.ipsAttachment_nonDrag:not([data-supports-drag="false"] *) {
		display: none;
	}

.ipsAttach {
	position: relative;
}

.ipsAttach.ipsAttach_selected {
	outline: 2px solid var(--i-primary);
	outline-offset: -2px;
}

.ipsAttach:has(:checked) {
	outline: 2px solid var(--i-primary);
	outline-offset: -2px;
}

/* Insert existing attachment / Select featured image */
.ipsAttach_selection {
	width: 24px;
	height: 24px; 
	border-radius: 50%;
	display: inline-grid;
	place-content: center;
	color: #fff;
	background: var(--i-background_dark);
	background: color-mix(in srgb, var(--i-background_dark) 40%, transparent);
	-webkit-backdrop-filter: blur(10px);
	backdrop-filter: blur(10px);
}

	.ipsAttach_selectionOn .ipsAttach_selection {
		background: var(--i-primary);
		color: var(--i-primary-contrast);
		outline: 2px solid hsl(0 0% 100%);
	}

/* IMAGE ATTACHMENTS */
/* Used for Insert Existing Attachment */
.ipsAttachment_fileList--grid{
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
	gap: .5em;
	padding: .5em;
	background: var(--i-background_3);
}

/* Used for screenshot selection (Downloads) */
.ipsAttachment_fileList--radios{
	display: flex;
	overflow: auto;
	gap: 1em;
	padding: 1em;
	background: var(--i-background_3);
	text-align: center;
	border-radius: min(var(--i-design-radius), 5px);
}

	.ipsAttachment_fileList--radios .ipsImageAttach{
		flex: 0 0 auto;
		padding: 8px;
	}

	.ipsAttachment_fileList--radios .ipsImageAttach_thumb{
		aspect-ratio: auto;
	}

	.ipsAttachment_fileList--radios .ipsImageAttach_thumb :is(img, video){
		width: auto;
		height: 170px;
		border-radius: min(var(--i-design-radius), 5px);
		object-fit: scale-down;
	}

	.ipsAttachment_fileList--radios input{
		margin: calc(5px + 8px) 0 5px;
	}

.ipsImageAttach {
	position: relative;
	padding: 1em;
	background: var(--i-background_1);
	border-radius: min(var(--i-design-radius), 5px);
	isolation: isolate;
}

.ipsImageAttach_thumb {
	aspect-ratio: 16/9;
}

	.ipsImageAttach_thumb :is(img, video) {
		width: 100%;
		height: 100%;
		object-fit: contain;
		cursor: pointer;
	}

	.ipsImageAttach_thumb .ipsThumb{
		height: 100%;
		aspect-ratio: auto;
		border-radius: 0;
	}

.ipsImageAttach_status {
	display: block;
	line-height: 125px;
	opacity: 0.5;
}








/* Feature content: image selection */
/* Convert ipsThumbs into their natural ratio so thumbs aren't cropped via 'cover' or 'contain' */
.cPromote_attachList{
	display: flex;
	flex-wrap: wrap;
	gap: 15px;
}
.cPromote_attachList [data-role="preview"] img{
	height: 100px;
	border-radius: var(--i-thumb--bo-ra);
	object-fit: scale-down;
	background-color: var(--i-box--ba-co);
}

.cPromote_attachImage {
	position: relative;
}

	.cPromote_attachImage {
		border-radius: var(--i-thumb--bo-ra);
		outline: 2px solid transparent;
		outline-offset: 2px;
	}

		.cPromote_attachImage:where(:has(.cPromote_attachImage__checkbox)):hover{
			outline-color: var(--i-background_6);
		}

		.cPromote_attachImage:has([type="checkbox"]:checked){
			outline-color: var(--i-primary);
		}

	.cPromote_attachImage .ipsMeter {
		width: auto;
		position: absolute;
		left: 5px;
		right: 5px;
		bottom: 10px;
	}

	.ipsImageAttach_controls{
		position: absolute;
		top: 0;
		inset-inline-end: 0;
		display: flex;
		justify-content: end;
		gap: 10px;
		padding: 10px;
	}

	.cPromote_attachImage__checkbox {
		position: absolute;
		inset: 0;
		padding: 8px;
		display: grid;
		justify-content: end;
		cursor: pointer;
	}

/* SERVICE FIELDS */

	#eOriginalText textarea {
		height: 200px !important;
	}

.ipsAttach .ipsAttach_title {
	max-width: 100%;
	text-overflow: ellipsis;
	overflow: hidden;
	margin-top: .7em;
	font-weight: 600;
	color: var(--i-color_hard);
}

	.ipsAttach .ipsAttach_title + p {
		color: var(--i-color_soft);
		font-size: .9em;
	}

.ipsAttach:not(.ipsAttach_done) [data-role="preview"] {
	opacity: 0.5;
}

/* Stock replies */
.ipsStockReplies_menu {
	border-radius: 0px;
	height: 250px;
	overflow-y: auto;
}

.ipsStockReplies_row.i-padding_2 {
	padding-inline-start: 1.5em;
}
	.ipsStockReplies_row:hover {
		cursor: pointer;
		background: var(--i-background_2);
	}

.ipsStockReplies_content .ipsLoading {
	height: 250px;
}

/* My Media */
.cMyMedia{
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
}
.cMyMedia__align{
	display: contents;
}

.cMyMedia .ipsColumns{
	flex: 1 1 auto;
}

.cMyMedia .ipsColumns__primary{
	height: 100%;
	overflow: auto;
}

.cMyMedia_controls{
	flex: 0 0 auto;
}

.cMyMedia [data-role="myMediaContent"] {
	overflow-y: auto;
}

/*
	----------------
	- Cover photos
	----------------
*/

.ipsCoverPhoto {
	display: grid;
}

.ipsPageHeader .ipsCoverPhoto{
	padding: 8px;
	padding-bottom: 0;
}

.ipsCoverPhoto > *{
	grid-area: 1/1;
}

	.ipsCoverPhoto__container {
		background-color: var(--i-background_6);
		aspect-ratio: 4;
		position: relative;
		overflow: hidden;
		border-radius: inherit;
		transition-property: aspect-ratio;
		transition-duration: .3s;
		transition-timing-function: ease-in-out;
		border-radius: var(--i-box--bo-ra);
		min-height: 160px;
		max-width: 100%;
	}

	.ipsCoverPhoto__container::after{
		content: '';
		position: absolute;
		inset: 0;
		border: 1px solid currentColor;
		opacity: .3;
		border-radius: inherit;
		pointer-events: none;
	}

	/* Shorter cover photos */
	.ipsCoverPhoto--minimal .ipsCoverPhoto__container {
		aspect-ratio: 10;
	}

	/* Expanded */
	.ipsCoverPhoto--expanded .ipsCoverPhoto__container{
		aspect-ratio: var(--coverPhoto--ratio, auto);
		min-height: 0;
	}

	/* Expand cursors */
	.ipsCoverPhoto__image[data-action="toggleCoverPhoto"]{
		cursor: zoom-in;
	}
	.ipsCoverPhoto--expanded .ipsCoverPhoto__image[data-action="toggleCoverPhoto"]{
		cursor: zoom-out;
	}

	/* Cover Photo dropdown menu items: The JS requires clicks on 'a', not 'span' or FA icon */
	.ipsMenu--coverPhoto :is(span, i){
		pointer-events: none;
	}

/* Remove edit button from widgets */
.cWidgetContainer .ipsCoverPhoto [id^="elEditPhoto_"]{
	display: none;
}

	.ipsCoverPhoto__image {
		height: 100%;
		width: 100%;
		object-fit: cover;
		object-position: 50% calc(clamp(0, var(--offset), 100) * 1%);
		user-select: none;
	}

	/* Editing using scroll */
	.ipsCoverPhoto--editing .ipsCoverPhoto__container{
		overflow-y: auto;
		cursor: ns-resize;
		overscroll-behavior: contain;
		scrollbar-width: none;
	}

	.ipsCoverPhoto--editing .ipsCoverPhoto__container::-webkit-scrollbar {
		-webkit-appearance: none;
		width: 0px;
	}

	.ipsCoverPhoto--editing .ipsCoverPhoto__container::after{
		content: none;
	}

	.ipsCoverPhoto--editing .ipsCoverPhoto__image{
		position: static;
		display: block;
		height: auto;
		min-height: 100%; /* Ensure wide and short images work on mobile */
		pointer-events: none;
	}	

	.ipsCoverPhoto--editing [data-hideoncoveredit]{
		display: none;
	}

	.ipsCoverPhoto__overlay-buttons {
		place-self: start end;
		margin: 10px;
		transition: opacity .3s linear;
		position: relative;
		display: flex;
		gap: 8px;
	}

	.ipsCoverPhoto--expanded .ipsCoverPhoto__overlay-buttons{
		opacity: 0;
		pointer-events: none;
	}

/* Editing tooltip */
.ipsCoverPhoto__tooltip{
	align-self: start;
	justify-self: center;
	transform: translateY(calc(-100% - 10px));

	background: var(--i-tooltip--ba-co);
	color: hsl(0 0% 100%);
	-webkit-backdrop-filter: blur(20px);
	backdrop-filter: blur(20px);
	font-size: 13px;
	line-height: 1.6;
	font-weight: 500;
	padding: .5em 1em;
	border-radius: 6px;
	box-shadow: 0 2px 6px hsl(0 0% 0% / 0.1);
	max-width: min(100% - 40px, 30em);
	text-align: center;
	transition-property: display, opacity, translate;
	transition-behavior: allow-discrete;
	transition-duration: .3s;

	opacity: 0;
	translate: 0 20px;
}

.ipsCoverPhoto__tooltip:not([hidden]) {
	opacity: 1;
	translate: 0 0;
}

@starting-style {
	.ipsCoverPhoto__tooltip:not([hidden]) {
		opacity: 0;
		translate: 0 20px;
	}
}









/* Coverphoto Footers */
.ipsCoverPhotoMeta{
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 1em;
	padding: 1em 2em;
}

/* Hide empty cover photo footers. These can occur if no footer is specified, since the wrapper still exists. Page Records are an example */
.ipsCoverPhotoMeta:not(:has(*)){
	display: none;
}

	.ipsCoverPhoto__avatar{
		flex: 0 0 50px;
		position: relative;
	}

.ipsCoverPhoto__buttons{
	display: flex;
	gap: 8px;
	flex-wrap: wrap;
	margin-inline-start: auto;
}

	.ipsCoverPhoto__buttons > *,
	.ipsCoverPhoto__buttons .ipsButton{
		flex-grow: 1;
	}
.ipsCoverPhoto__title{
	font-size: 1.6em;
	font-weight: 700;
}

	.ipsCoverPhoto__title :is(h1, h2, h3, h4){
		color: var(--i-color_hard);
		line-height: 1.2;
	}

	.ipsCoverPhoto__title a:not(.ipsBadge){
		color: inherit;
	}

	.ipsCoverPhoto__title :is(h1, h2, h3, h4):not(:only-child){
		display: inline;
	}

	:where(.ipsCoverPhoto__title > *){
		margin-inline-end: .3em;
	}

	.ipsCoverPhoto__title-icon{
		font-size: max(11px, .6em);
		margin-top: calc(1ex - 1cap);
	}

.ipsCoverPhoto__subTitle{
	font-weight: 500;
	color: var(--i-color_soft);
}

.ipsCoverPhoto__stats{
	display: flex;
	flex-wrap: wrap;
	white-space: nowrap;
	gap: 1px;
	overflow: hidden;
}

.ipsCoverPhoto__stats li{
	flex: 1 1 auto;
	position: relative;
	padding: .5em clamp(1em, 3vw, 2.5em);
	outline: 1px solid var(--i-background_3);
}

.ipsCoverPhoto__stats li:has(.ipsCoverPhoto__link):hover{
	background: var(--i-background_2);
}

	.ipsCoverPhoto__statTitle{
		font-weight: 600;
		color: var(--i-color_hard);
	}

	/* Capitalize the first letter since some language strings are lowercase (Blogs) */
	.ipsCoverPhoto__statTitle:first-letter{
		text-transform: capitalize;
	}

	.ipsCoverPhoto__statValue{
		color: var(--i-color_root);
		font-weight: 500;
	}

	.ipsCoverPhoto__statValue a{
		color: inherit;
	}

	/* Always show long dates */
	.ipsCoverPhoto__statValue .ipsTime__long{
		display: revert;
	}
	.ipsCoverPhoto__statValue .ipsTime__short{
		display: none;
	}

	.ipsCoverPhoto__link{
		position: absolute;
		inset: 0;
	}

@media (max-width: 979px){
	.ipsCoverPhotoMeta{
		padding: 1em;
	}
	.ipsCoverPhoto__titles{
		flex: 999 1 auto;
	}
	.ipsCoverPhoto__buttons{
		flex: 1 1 auto;
	}
	.ipsCoverPhoto__stats{
		order: 1;
		flex: 1 1 100%;
		text-align: center;
		border: 1px solid var(--i-background_3);
		border-width: 1px 0 0 0;
		margin: 0 -1em -1em;
	}
}

@media (min-width: 980px){
	.ipsCoverPhoto__avatar{
		flex-basis: 120px;
		margin-bottom: -.5em;
		margin-inline-start: -.5em;
		margin-inline-end: .5em;
		align-self: flex-end;
		transition: flex-basis .3s linear;
	}
	.ipsCoverPhoto--expanded ~ .ipsCoverPhotoMeta .ipsCoverPhoto__avatar{
		flex-basis: 70px;
	}
	.ipsCoverPhoto__avatar .ipsUserPhoto{
		width: 100%;
		position: absolute;
		bottom: 0;
		left: 0;
		border: 3px solid var(--i-background_1);
	}
	.ipsCoverPhoto__titles{
		margin-inline-end: 1.5em;
	}
	.ipsCoverPhoto__stats{
		border-inline-start: 1px solid var(--i-background_3);
	}
}

/* Button bar */
.ipsButtonBar{
	--i-co: var(--i-color_soft);
	display: flex;
	flex-wrap: wrap;
	font-weight: 600;
	font-size: max(.8em, 11px);
	border: 0px solid var(--i-background_4);
}

	:where(.ipsBox) .ipsButtonBar{
		background: var(--i-background_2);
	}

	.ipsButtonBar > *{
		padding: .6em;
	}

	:where(.ipsBox) .ipsButtonBar--top{
		border-radius: var(--i-box--bo-ra) var(--i-box--bo-ra) 0 0;
		border-bottom-width: 1px;
	}

	:where(.ipsBox) .ipsButtonBar--bottom{
		border-radius: 0 0 var(--i-box--bo-ra) var(--i-box--bo-ra);
		border-top-width: 1px;
	}

	/* Remove border-radius if the buttonBar isn't the first element */
	:where(.ipsColumns, .ipsTabs__panels, .ipsBox:has(.ipsBox__header), .ipsProfile__main) .ipsButtonBar--top{
		border-radius: 0;
	}

	/* Tweak the button bar so it can be used between elements */
	:where(.ipsProfile__main, .ipsColumns--followed-content) .ipsButtonBar--top{
		border-radius: 0;
	}

	/* Hide empty pagination. This prevents an empty gap when the bars wrap on mobiles */
	.ipsButtonBar__pagination:not(:has(a)){
		display: none;
	}

	.ipsButtonBar__end{
		margin-inline-start: auto;
		display: flex;
		flex-wrap: wrap;
		gap: .6em;
	}

		.ipsButtonBar__end .ipsButtonBar__mod{
			display: contents;
		}

@media (max-width: 767px){
	.ipsButtonBar{
		flex-direction: column;
		align-items: stretch;
	}
	.ipsButtonBar__pagination, .ipsButtonBar .ipsPaginationNav{
		align-self: stretch;
	}
	.ipsButtonBar__end{
		order: -1;
	}
	.ipsPagination__next,
	.ipsPagination__last{
		order: 1;
	}
}

@media (max-width: 500px){
	.ipsButtonBar__end{
		margin: 0;
	}
	/* If the pagination bar is visible, add a border to the filter bar to separate them visually */
	.ipsButtonBar__pagination:not([hidden]) ~ .ipsButtonBar__end:not(:only-child){
		border-bottom: 1px solid;
		border-bottom-color: color-mix(in srgb, currentColor 10%, transparent);
	}
}

/*
	----------------
	- Data filters
	----------------
*/

.ipsDataFilters{
	flex: 1 1 auto;
	display: flex;
	flex-wrap: wrap;
}

	.ipsDataFilters + .ipsDataFilters{
		margin-inline-start: .4em;
	}

.ipsDataFilters > li{
	flex-grow: 1;
}

/* Prevent the auto-check icon from expanding to full width in topics on mobiles */
.ipsDataFilters > li:has([data-ipsautocheck], [href="#elFolderSettings_menu"]){
	flex-grow: 0;
	margin-inline-start: auto;
}

.ipsDataFilters__button{
	height: 100%;
	width: 100%; /* Full-width <button> */
	display: flex;
	align-items: center;
	justify-content: center;
	gap: .5em;
	color: var(--i-co);
	padding: .8em 1.2em;
	text-decoration: none;
	text-transform: uppercase;
	border-radius: min(var(--i-design-radius), .3em);
	position: relative; /* For notification badge */
}

	/* Automatic contrast for some buttons (Eg. at the top of topics) */
	.ipsDataFilters__button:where(:not(.ipsBox *, .ipsDialog *, .ipsWidget *)){
		color: var(--i-color_contrast, var(--i-co));
	}

	@media (hover){
		.ipsDataFilters__button:where(:hover){
			background-color: color-mix(in srgb, currentColor 8%, transparent);
		}
	}

	.ipsDataFilters__button--active,
	.ipsDataFilters__button[aria-expanded="true"]{
		--i-outline-color: var(--i-secondary);
		background-color: var(--i-secondary);
		color: var(--i-secondary-contrast);
	}

/*
	----------------
	- Data Lists/tables
	----------------
*/

i-data{
	display: block;
	container: ipsData / inline-size;
}

/* List */
.ipsData{
	--i-data--padding: 1.3em;
	--i-data--cell-spacing: var(--i-data--padding);
	--i-data--icon-width: 40px;
	--i-data--latest--width: clamp(13em, 25%, 17em);
	--i-data--icon-ratio: 1;
	--i-data--icon-radius: min(var(--i-design-radius), 6px);
	--i-data--title: 1em;
	--i-data--border: 1px;
	--i-data--desc-truncate: 4;

	/* Hide latest avatar by default */
	--i-data--show-latest-photo: ;
	--i-data--hide-latest-photo: initial;

	/* Hide stat icons by default */
	--i-data--show-stats-icon: ;
	--i-data--hide-stats-icon: initial;

	/* Show stat labels by default */
	--i-data--show-stats-label: initial;
	--i-data--hide-stats-label: ;

	/* Show tags by default */
	--i-data--show-tags: initial;
	--i-data--hide-tags: ;

	/* Hide views on small UIs by default */
	--i-data--show-views: initial;
	--i-data--hide-views: ;

	/* Show last user by default */
	--i-data--show-last: initial;
	--i-data--hide-last: ;

	/* Prioritize the latest replier over the original author */
	--i-data--show-last-author: ;
	--i-data--show-last-reply: initial;

	/* Show Page fields by default */
	--i-data--show-fields: initial;
	--i-data--hide-fields: ;

	--i-data--show-category: initial;
	--i-data--hide-category: ;

	display: grid;
}

/* Replace basis variable with i-basis_x if a class is added */
.ipsData[class*="i-basis_"]{
	--i-data--basis: var(--i-basis);
}

/* Widgets */
.ipsData--compact{
	--i-data--padding: 1em;
	--i-data--cell-spacing: 1em;
	--i-data--icon-width: 32px;
}

/* Global data styles */
.ipsData__item{
	gap: var(--i-data--cell-spacing);
	padding: var(--i-data--padding);
	display: flex;
	align-items: center;
	position: relative; /* Clickable rows */
	/* container: ipsData__item / inline-size; */
}

/* Add container query to certain ipsData__item elements */
.ipsData--mini-grid .ipsData__item,
.ipsData--wallpaper .ipsData__item,
.ipsData--grid .ipsData__item{
	container: ipsData__item / inline-size;
}

	/* Flex gap fallback for < iOS 14.1 */
	@supports (-webkit-touch-callout: none) and (not(translate: none)){
		.ipsData__item > *{
			margin: calc(var(--i-data--cell-spacing) / 2);
		}
	}

	/* Some items need borders */
	:is(.ipsData--table, .ipsData--minimal, .ipsData--featured, .ipsData--snippet) .ipsData__item{
		border-bottom: var(--i-data--border) solid var(--i-data--bo-co);
	}
	:is(.ipsData--table, .ipsData--minimal, .ipsData--featured, .ipsData--snippet) .ipsData__item:last-child{
		border-bottom-width: 0;
	}

	/* Warning: used in Mod Cpanel > Reported content */
	.ipsData__item--warning {
		--i-co: var(--i-color_moderated);
		background-color: var(--i-background_moderated);
	}
		.ipsData__item--warning,
		.ipsData__item:where(:has(+ .ipsData__item--assigned)){
			border-color: color-mix(in srgb, var(--i-background_moderated), var(--if-light, black 8%) var(--if-dark, white 8%));
		}

	/* Assigned */
	.ipsData__item--assigned{
		--i-co: var(--i-color_assigned);
		background-color: var(--i-background_assigned);
		--i-background_hover: color-mix(in srgb, var(--i-color_assigned) 3%, transparent);
	}
		.ipsData__item--assigned,
		.ipsData__item:where(:has(+ .ipsData__item--assigned)){
			border-color: color-mix(in srgb, var(--i-background_assigned), var(--if-light, black 8%) var(--if-dark, white 8%));
		}

	/* Selected */
	:where(.ipsData__item:has(:is(.ipsInput, [data-role="moderation"]):checked)){
		background-color: var(--i-background_selected);
	}
		.ipsData__item:has(:is(.ipsInput, [data-role="moderation"]):checked),
		.ipsData__item:where(:has(+ .ipsData__item :is(.ipsInput, [data-role="moderation"]):checked)){
			border-color: color-mix(in srgb, var(--i-background_selected), var(--if-light, black 10%) var(--if-dark, white 8%));
		}
		/* :has() fallback */
		.ipsData__item--selected {
			background-color: var(--i-background_selected);
		}

	@supports (color: color-mix(in srgb, var(--x), transparent)){
		:is(.ipsData__item--assigned, .ipsData__item--warning):where(:not(.ipsData__item--selected)){
			color: var(--i-co);
			--i-color_soft: color-mix(in srgb, var(--i-co) 65%, transparent);
			--i-color_hard: color-mix(in srgb, var(--i-co), var(--if-light, black 15%) var(--if-dark, white 80%));
			--i-color_root: var(--i-co);
			--i-link--co: var(--i-color_hard);
			--i-link-hover--co: var(--i-color_hard);
		}
	}

			/* Extend content, or extend element if it's the only child */
			.ipsData__content,
			.ipsData__main,
			.ipsData__item > :only-child{
				flex: 999 999 100%;
			}

			/* Remove padding when ipsEntry is the only child. This happens often when viewing "Profile > See my activity" */
			.ipsData__item:has( > .ipsEntry:only-child){
				padding: 0;
				border-width: 0;
				display: block;
			}

		/* Center all icons/images */
		.ipsData__icon{
			flex: 0 0 auto;
			text-align: center;
			position: relative;
		}

		/* Stacked user photos, for replies */
		.ipsData__icon .ipsUserPhoto:has(~ .ipsUserPhoto){
			transform: scale(.7);
			transform-origin: 0 0;
		}

		.ipsData__icon .ipsUserPhoto ~ .ipsUserPhoto{
			position: absolute;
			bottom: 0;
			inset-inline-end: 0;
			transform: scale(.6);
			transform-origin: 100% 100%;
			outline: 4px solid var(--i-box--ba-co);
		}

		/* Image, used for thumbnails/cover photos. Stretches to full width in the grid UI */
		.ipsData__image{
			flex: 0 0 var(--i-data--icon-width);
			aspect-ratio: var(--i-data--icon-ratio);
			display: var(--i-data--display-image, grid);
			border-radius: var(--i-data--icon-radius);
			/* This prevents the a:hover color from applying */
			color: inherit;
			/* This removes underlines when emoji are used */
			text-decoration: none !important;
			/* Ensure FA icons are centered within their min-width */
			text-align: center;
		}

		/* Let icons use this as a container, for cqmin font-size */
		.ipsData__image:has(i, .ipsIcon){
			container-type: size;
		}
		/* The container-type adds a new stacking context. Remove the pointer events, and then re-add them for links below */
		.ipsData__image:not(a):has(i, .ipsIcon){
			pointer-events: none;
		}

		/* Add pointer-events back to links inside images. Eg. badges in Tags grid */
		.ipsData__image a{
			pointer-events: auto;
		}

		.ipsData__image > *{
			grid-area: 1/-1;
		}

			/* Adjust cover photos inside ipsData__image */
			.ipsData__image .ipsCoverPhoto{
				height: 100%;
			}

				.ipsData__image .ipsCoverPhoto__container{
					min-height: 0;
					aspect-ratio: auto;
				}

			/* Make all child elements occupy full size */
			.ipsData__image > i, 
			.ipsData__image > .ipsIcon,
			.ipsData__image > .ipsNsfwOverlay{
				width: 100%;
				height: 100%;
				border-radius: inherit;
				/* Adjust font-size for emoji and FA icons */
				font-size: 50cqmin;
				line-height: 1;
				aspect-ratio: var(--i-data--icon-ratio);
			}

			/* Images */
			.ipsData__image img,
			.ipsData__image video{
				border-radius: inherit;
				width: 100%;
				height: 100%;
				object-fit: cover;
			}

			/* Custom uploaded icons */
			.ipsData--table .ipsData__customIcon{
				object-fit: scale-down;
				border-radius: 0;
			}

			/* Emoji */
			.ipsData__image .ipsIcon--emoji{
				display: grid;
				place-content: center;
				/* Emoji should occupy the full width of the column */
				font-size: 100cqmin;
				height: 100%; /* Safari fix */
			}

			.ipsData__image .ipsIcon--fa{
				display: grid;
				place-content: center;
			}

			/* Avatars inside ipsData__image, eg Most Contributions widget */
			.ipsData__image .ipsUserPhoto{
				border-radius: inherit;
				aspect-ratio: var(--i-data--icon-ratio);
				width: 100%;
			}

			/* Remove pseudo element */
			.ipsData__image .ipsUserPhoto::after{
				content: none;
			}

		/* "No image" icon */
		.ipsData__image > i{
			display: grid;
			place-content: center;
		}
		/* Style the <i></i> elements */
		/* We don't want to style all FA icons (Quest task list) */
		.ipsData__image > i:not([class*="fa-"]){
			--i-co: var(--i-color_soft);
			background: var(--i-background_3);
			color: var(--i-co);
			font-family: "Font Awesome 6 Free";
			font-weight: var(--i-data--fallback-icon-weight, 900);
			-webkit-font-smoothing: antialiased;
			font-style: normal;
			font-variant: normal;
			line-height: 1;
			text-rendering: auto;
		}

			.ipsData__image > i:not([class*="fa-"])::before{
				content: var(--i-data--fallback-icon, "\f1c5");
			}

			/* FA icons have a background */
			.ipsData--table .ipsData__image .ipsIcon--fa{
				--i-co: var(--i-featured, var(--i-primary));
				aspect-ratio: var(--i-data--icon-ratio);
				border-radius: var(--i-design-radius);
				background: var(--i-co);
				color: #fff;
			}

				/* Fade icons when no new content exists */
				[data-ips-member] .ipsData--table.ipsData--category [data-ips-read] .ipsData__image{
					filter: var(--i-data--read-icon-filter, opacity(.25));
					/* The filter property makes the icon sit on top of ipsLinkPanel, so we need to fix that */
					pointer-events: none;
				}

			/* Default icons for forums */
			.ipsData__item--discussions{
				--i-data--fallback-icon: "\f15c";
				--i-data--fallback-icon-weight: 400;
			}
			.ipsData__item--password{
				--i-data--fallback-icon: "\f023";
			}
			.ipsData__item--redirect{
				--i-data--fallback-icon: "\f061";
			}

		/* Badges on images (Tags overview) */
		.ipsData__image .ipsBadge{
			align-self: start;
			justify-self: end;
			margin: 10px;
			background-color: oklch(from var(--i-badge) min(.44, l) min(.065, c) h);
			color: hsl(0 0% 100%);
			z-index: 3; /* Higher than nsfw overlay */
		}

		.ipsData__image .ipsBadge--icon{
			font-size: 13px;
		}

			:where(.ipsData__icon a){
				display: block;
				text-decoration: none !important;
			}

			.ipsData__icon:has(.ipsDateBlock){
				--i-data--icon-width: 3em;
			}

	/* Hide images based on configuration */
	.cWidgetContainer--noImages .ipsData__icon,
	.cWidgetContainer--noImages .ipsData__image {
		display: none !important;
	}

	/* Indicator cells */
	.ipsData__icon--indicator{
		width: 2em; /* Same size as avatars, so "Moved" icon aligns neatly */
	}

	/* Thumbnails */
	.ipsData__icon .ipsThumb{
		aspect-ratio: var(--i-data--icon-ratio);
	}

	.ipsData__item .ipsFigure{
		flex: 0 0 var(--i-data--icon-width);
	}

	.ipsData--cart-dropdown .ipsData__image,
	.ipsLayout__secondary-column .ipsData__item > .ipsFigure{
		flex-basis: 3.5em;
	}

	/* Avatars */
	.ipsData__icon .ipsUserPhoto{
		width: 28px;
	}

	/* Events */
	.ipsData__item > .ipsCalendarDate{
		flex: 0 0 clamp(34px, 10%, 3.2em);
		align-self: start;
	}

	.ipsData--grid .ipsData__image .ipsCalendarDate:not(:only-child){
		place-self: start;
		width: 50px;
		margin: 8px;
	}

	/* Experimental. This might be a poor decision */
	.ipsData__main > :last-child{
		margin-bottom: 0 !important;
		/* Padding needs to be removed too due to .ipsData__title:focus-within */
		padding-bottom: 0 !important;
	}

	.ipsData__title{
		font-size: var(--i-data--title);
		font-weight: 500;
		color: var(--i-color_hard);
		overflow-wrap: break-word;
		line-height: 1.3;
		/* Clear floated items such as ratings or badges */
		display: flow-root;
	}

	/* Create a contrast-friendly version of the featured color */
	@supports (color: hsl(from var(--i) h s 30%)) and (color: oklch(from red l c h)){
		[style*="--i-featured"]{
			--i-color_featured: oklch(from var(--i-featured) var(--if-light, min(l, .45)) var(--if-dark, max(l, .8)) c h);
		}
	}

	/* Inherit the featured color */
	:where([style*="--i-featured"] .ipsData__title) a{
		color: inherit;
	}

	/* Apply the feature color to certain titles */
	.ipsData--category [style*="--i-featured"] .ipsData__title,
	[style*="--i-featured"] .ipsData--forumFeedViewParent .ipsData__title{
		color: var(--i-color_featured, var(--i-featured));
	}

		/* Bold titles for unread content */
		[data-ips-unread] .ipsData__title{
			font-weight: bold;
		}

		/* Bold titles for unread content */
		[data-ips-member] [data-ips-read] .ipsData__title{
			font-weight: normal;
		}

	/* Align children inside .ipsData__title */
	:where(.ipsData__title > :is(h1, h2, h3, h4, h5):not(:only-child)){
		display: inline;
	}

	.ipsData__title > *{
		vertical-align: top;
	}

	:where(.ipsData__title > :not(:last-child)){
		margin-inline-end: .4em;
	}

	/* Float badges in certain layouts */
	:is(.ipsData--wallpaper, .ipsData--grid, .ipsData--mini-grid) .ipsData__title .ipsBadges{
		float: inline-end;
		margin: 0;
	}

	/* Club names */
	.ipsData__club{
		color: var(--i-color_soft);
		margin: .5em 0 .2em;
		display: flex;
		align-items: center;
		gap: .6em;
		font-weight: 450;
	}
	.ipsData__club a{
		color: inherit;
	}
		.ipsData__club::before{
			content: '\f2bd';
			font-family: var(--i-font-awesome);
			-webkit-font-smoothing: antialiased;
			text-rendering: auto;
			font-style: normal;
			font-weight: 900;
			opacity: .5;
			pointer-events: none;
		}

	.ipsData__desc,
	.ipsData__meta{
		--i-co: var(--i-color_soft);
		--i-link--co: var(--i-co);
		--i-link-hover--co: var(--i-co);
		--i-link-hover--te-de: underline;
		color: var(--i-co);
	}

	/* Remove empty meta tags? This can happen with the Featured Content widget */
	.ipsData__meta:empty{
		display: none;
	}

	:where(.ipsData__meta){
		font-size: 1em; /* Sometimes __meta uses <small> elements */
	}

	/* Always show long dates in meta */
	.ipsData__meta .ipsTime__long{
		display: revert;
	}
	.ipsData__meta .ipsTime__short{
		display: none;
	}

	/* Prefixes can be added to meta */
	.ipsData__meta .ipsBadges{
		margin-inline-end: .6em;
	}

	:where(.ipsData__desc){
		margin-top: .4em;
	}

	/* Forum catgories */
	.ipsData__category{
		display: var(--i-data--show-category, block) var(--i-data--hide-category, none);
		color: var(--i-color_soft);
		font-weight: 600;
		font-size: .92em;
		margin-bottom: .4em;
	}
		:where(.ipsData__category) a{
			color: inherit;
		}

	/* Truncate simple descriptions using line-clamp since the text in this element is just a string */
	.ipsData__desc:not(.ipsData__desc--all){
		display: var(--i-data--display-desc, -webkit-box);
		-webkit-line-clamp: var(--i-data--desc-truncate);
		-webkit-box-orient: vertical;
		text-overflow: ellipsis;
		overflow: hidden;
	}

	/* If a <p> tag exists, it's likely .ipsRichText. Truncate these descriptions using max-height to prevent issues with paragraphs, images, etc */
	.ipsData__desc:has(p):not(.ipsData__desc--all){
		display: var(--i-data--display-desc, flow-root);
		max-height: calc(var(--i-data--desc-truncate) * 1.5em);
		max-height: calc(var(--i-data--desc-truncate) * 1lh);
	}
	/* Fade out ipsData__desc if it contains large elements since they can't be truncated. A faded image looks better than a solid crop */
	.ipsData__desc:where(:has(img, iframe, blockquote):not(.ipsData__desc--all)){
		mask-image: linear-gradient(#000 calc((var(--i-data--desc-truncate)) * 1lh), transparent calc((var(--i-data--desc-truncate) + 2) * 1lh));
	}

	.ipsData__desc[data-truncate-expanded="true"]{
		display: var(--i-data--display-desc, block);
		max-height: none !important;
		overflow: visible;
		mask-image: none;
	}

	/* Convert br elements into a space if it's a simple truncation */
	.ipsData__desc:not(.ipsData__desc--all, [data-truncate-expanded="true"]) > br{
		content: "";
		margin-inline-end: 1em;
	}

	/* Hide empty descriptions */
	.ipsData__desc:-moz-only-whitespace{ display: none; }

	.ipsData .ipsTags{
		display: var(--i-data--show-tags, flex) var(--i-data--hide-tags, none);
		font-size: max(.7em, 10px); /* Tags and prefixes should use the same font-size */
		margin: .6em 0;
	}

		.ipsData__groups{
			display: var(--i-data--display-groups, flex);
			flex: 0 0 auto;
			flex-wrap: wrap;
			gap: .1em .4em;
			line-height: 1; /* Remove empty space below icons */
		}

		@container (min-width: 750px){
			.ipsData__groups{
				display: var(--i-data--display-groups, grid);
			}
		}

		.ipsData__groups img{
			max-height: 1.2em;
			width: auto;
		}

		.ipsData__groups .ipsBadge{
			vertical-align: top;
		}

		.ipsData__container-title{
			font-weight: 500;
			color: var(--i-color_featured, var(--i-featured, var(--i-color_hard)));
		}

/*
	----------------
	- Stats
	----------------
*/

.ipsData__stats{
	color: var(--i-color_soft);
	display: var(--i-data--display-stats, flex);
	align-items: center;
	flex-wrap: wrap;
	gap: 0 clamp(1em, 6cqw, 1.8em);
}

/* Flex gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsData__stats > :not(:first-child){
		margin-inline-start: 1.5em;
	}
}

/* If stats include an icon, lower its opacity (Eg. Album widget) */
.ipsData__stats .fa-regular:not(.ipsRating *),
.ipsData__stats .fa-solid:not(.ipsRating *){
	opacity: .4;
	font-size: .9em;
	margin-inline-end: .25em;
}

/* Darker and bolder stats for featured and tables */
:where(:is(.ipsData--table, .ipsData--featured) .ipsData__stats [data-stattype*="comments"]:first-child){
	color: var(--i-color_root);
}

/* Sometimes stats can be linked (Comments in Page listings) */
.ipsData__stats :where(a:not([class])){
	color: inherit;
}

/* Hide a stats list item if it contains a hidden reaction component. This is used in expanded topic lists */
.ipsData__stats > li:has(.ipsReactOverview--none){
	display: none;
}

/*
	----------------
	- Stat icons, typically shown in small UIs
	----------------
*/

.ipsData__stats-icon{
	display: var(--i-data--show-stats-icon, inline-flex) var(--i-data--hide-stats-icon, none);
	align-items: baseline;
}

	/* Icon */
	.ipsData__stats-icon::before{
		content: var(--_i-icon, "\e473");
		font-weight: 900;
		font-family: "Font Awesome 6 Free";
		font-style: normal;
		font-size: .9em;
		opacity: .6;
		-webkit-font-smoothing: antialiased;
		font-variant: normal;
		text-rendering: auto;
		margin-inline-end: .4em;
	}

	.ipsData__stats [data-stattype*="comments"]{ --_i-icon: "\f075" }
	.ipsData__stats [data-stattype*="views"]{ --_i-icon: "\f06e" }
	.ipsData__stats [data-stattype="price"]{ --_i-icon: "\f07a" }
	.ipsData__stats [data-stattype="purchases"]{ --_i-icon: "\f291" }
	.ipsData__stats [data-stattype="downloads"]{ --_i-icon: "\f019" }
	.ipsData__stats [data-stattype="images"]{ --_i-icon: "\f083" }
	.ipsData__stats [data-stattype="albums"]{ --_i-icon: "\f302" }
	.ipsData__stats [data-stattype="image_comments"]{ --_i-icon: "\f302" }
	.ipsData__stats [data-stattype="album_comments"]{ --_i-icon: "\f075" }

	/* Value */
	.ipsData__stats-icon[data-stat-value]::after{
		content: attr(data-stat-value);
	}

	/* Remove the label if icons are shown */
	.ipsData__stats-icon[data-stat-value] ~ .ipsData__stats-label{
		display: var(--i-data--show-stats-label, inline) var(--i-data--hide-stats-label, none);
	}



/* If the stats are inside __main (usually under description or meta), add a space */
:where(.ipsData__main :is(.ipsData__desc, .ipsData__meta) ~ .ipsData__stats){
	margin-top: .6em;
}

	.ipsData__stats-hot {
		background: #da621a;
		color: #fff;
		font-size: max(.9em, 12px);
		font-weight: 500;
		display: inline-block;
		padding: 0 .4em;
		position: relative;
		vertical-align: middle;
		border-radius: 4px;
		white-space: nowrap;
	}

		.ipsData__stats-hot::before {
			content: attr(data-text);
			text-transform: uppercase;
			font-size: .8em;
			opacity: 0.6;
			margin-inline-end: .4em;
			vertical-align: .1em;
		}

		@container (max-width: 500px){

			/* Use short dates for small UI */
			:where(.ipsData__item) .ipsTime__long{
				display: none;
			}
			:where(.ipsData__item) .ipsTime__short{
				display: revert;
			}

			/* Hide views by default, with option of restoring */
			.ipsData__stats [data-stattype*="views"]{
				display: var(--i-data--show-views, block) var(--i-data--hide-views, none);
			}

		}

/*
	----------------
	- Active users
	----------------
*/

/* Hide element if it's empty, otherwise it occupies space in the mobile UI due to the grid gap */
.ipsData [data-role="activeUsers"]:empty{
	display: none;
}


/*
	----------------
	- Latest content
	- Inline by default, with a stacked version for large tables
	----------------
*/

.ipsData__last{
	display: var(--i-data--show-last, flex) var(--i-data--hide-last, none);
	align-items: center;
	gap: 0 .8em;
}

/*
	Some data lists will display the last commenter in the "extra row", but some UI's might prefer the original author
	The following lets us display the original author instead of the last commenter
	Hide the original author by default
*/
.ipsData__last--author{
	display: var(--i-data--show-last-author, flex) var(--i-data--show-last-reply, none);
}

/* Optionally show the meta/original author instead of the latest reply */
/* When the original author is shown, hide the reply data and the meta since we don't want to display duplicated content */
.ipsData__last--author ~ .ipsData__last{
	display: var(--i-data--show-last-author, none) var(--i-data--show-last-reply, flex);
}
.ipsData__item:has(.ipsData__last--author) .ipsData__meta{
	display: var(--i-data--show-last-author, none) var(--i-data--show-last-reply, block);
}

/* Gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsData__last > :not(:first-child){
		margin-inline-start: .7em;
	}
}

:where(.ipsData__last-secondary) a{
	color: inherit;
}

.ipsData__last .ipsUserPhoto{
	flex: 0 0 auto;
	width: 1.4em; /* Width is required to fix premature wrapping bug */
	display: var(--i-data--show-latest-photo, block) var(--i-data--hide-latest-photo, none);
}

/* Inline latest content */
.ipsData__last-text{
	flex: 1 1 100%;
	display: flex;
	flex-wrap: wrap;
	gap: 0 .4em;
	align-items: baseline;
}

/* Flex gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsData__last-text > :not(:first-child){
		margin-inline-start: .6em;
	}
}

:where(.ipsData__last-primary a:not(.ipsUsername)){
	color: var(--i-color_hard);
}

/* Bold "last" and "comment stat" for unread entries */
:where(.ipsData--table.ipsData--category [data-ips-unread] .ipsData__last-primary){
	color: var(--i-color_hard);
	font-weight: 700;
}

/* Add middot between latest author and date */
:where(.ipsData__last:has(.ipsData__last-primary):has(.ipsData__last-secondary)) .ipsData__last-text::after{
	content: "\00B7";
}

:where(.ipsData__last-secondary){
	font-size: 1em; /* Reset font-size for <small> elements */
	color: var(--i-color_soft);
	order: 1;
}


/* Improved alignment for stats/latest */
.ipsData__extra{
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
	gap: .5em 1em;
	margin-top: .75em;
}

/* Move stats to end and flip them so most prominent one is at the end */
:where(.ipsData__extra .ipsData__stats){
	order: 1;
	flex-direction: row-reverse;
}

/* Sometimes stats can have a checkbox (Downloads Grid UI). Ensure it's always last in the list */
:where(.ipsData__extra .ipsData__stats > li:has(.ipsInput)){
	order: -1;
}

/* And then move rating to the start */
:where(.ipsData__extra .ipsData__stats li:has(.ipsRating)){
	order: 3;
}

@container (max-width: 750px){

	/* Smaller font-size in small UI */
	.ipsData__meta, .ipsData__extra{
		font-size: max(11px, .92em);
	}

	.ipsData--category .ipsData__extra{
		margin-top: .5em;
	}

	/* Soft "last content" in small entries UI */
	:is(.ipsData--table, .ipsData--minimal, .ipsData--mini-grid) [data-ips-read] .ipsData__last-primary{
		color: var(--i-color_soft);
	}

}

/* If a username exists in the meta area and if there are more than 0 comments, we can assume that the username in the "last" area has replied to the content. Prepend a "replied icon" */
:where(.ipsData__item:has(.ipsData__meta .ipsUsername):not(:has([data-stattype*="comments"][data-v="0"]))) .ipsData__last:not(.ipsData__last--author) .ipsData__last-text::after{
	content: "\f3e5";
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	font-size: .7em;
	color: var(--i-color_soft);
	opacity: .7;
}

/* Mod checkbox */
.ipsData__mod{
	flex: 0 0 auto;
}
.ipsData__mod .ipsInput{
	display: flex;
}

/* Snippet */
.ipsData--snippet-topic-list{
	--i-data--icon-width: 3em;
}
.ipsData--snippet-topic-list .ipsData__icon{
	align-self: flex-start;
}
.ipsData--snippet-topic-list .ipsData__desc{
	margin-top: .8em;
}
.ipsData--snippet-topic-list .ipsData__last .ipsUserPhoto{
	width: 1.2em;
}

/*
	----------------
	- Pages Fields
	----------------
*/

.ipsData__fields{
	align-items: center;
	display: var(--i-data--show-fields, flex) var(--i-data--hide-fields, none);
	flex-wrap: wrap;
	gap: 1em;
	margin-top: 1em;
}

.ipsData__fields:not(:has(li)){
	display: none;
}

/*
	----------------
	- Data statuses
	----------------
*/

/* Statuses */
.ipsModerated:not(:has([data-role="moderation"]:checked)){
	--i-co: var(--i-color_moderated);
	--i-link--co: var(--i-color_moderated);
	--i-link-hover--co: var(--i-color_moderated);
	--i-color_root: var(--i-color_moderated);
	--i-color_soft: var(--i-color_moderated);
	--i-color_hard: var(--i-color_moderated);
	background-color: var(--i-background_moderated) !important;
	border-color: var(--i-background_moderated);
	border-color: color-mix(in srgb, var(--i-color_moderated) 60%, transparent);
	color: var(--i-co) !important;
	outline: 4px solid color-mix(in srgb, var(--i-color_moderated) 15%, transparent);
}
.ipsData__item:has(+ .ipsModerated [data-role="moderation"]:not(:checked)){
	border-color: color-mix(in srgb, var(--i-color_moderated) 60%, transparent);
}
.ipsModerated:not(:has([data-role="moderation"]:checked)) *{
	--i-co: var(--i-color_moderated) !important;
}

/* :has polyfill */
/* This version means that "selected moderated" entries still have red text */
@supports not selector(a:has(b)){
	.ipsModerated:not(.ipsSelected, .ipsEntry--selected){
		--i-co: var(--i-color_moderated);
		--i-link--co: var(--i-color_moderated);
		--i-link-hover--co: var(--i-color_moderated);
		--i-color_root: var(--i-color_moderated);
		--i-color_soft: var(--i-color_moderated);
		--i-color_hard: var(--i-color_moderated);
		background-color: var(--i-background_moderated) !important;
		border-color: var(--i-background_moderated);
		border-color: color-mix(in srgb, var(--i-background_moderated), var(--if-light, black) var(--if-dark, white) 12%);
		color: var(--i-co) !important;
	}
	.ipsModerated:not(.ipsSelected, .ipsEntry--selected) *{
		--i-co: var(--i-color_moderated) !important;
	}
}

:where(.ipsBox, .ipsWidget, .ipsDialog) .ipsModerated{
	outline-width: 0 !important;
}

.ipsSelected{
	background-color: var(--i-background_selected) !important;
}

/* Sublists */
.ipsSubList{
	display: var(--i-data--display-subforums, flex);
	flex-wrap: wrap;
	margin-top: 1.2em;
	font-size: 0.9em;
	color: var(--i-color_root);
}

	.ipsSubList a{
		color: inherit;
		display: block;
		text-decoration: none !important;
		padding: .5em 1.2em;
		border-radius: min(var(--i-design-radius), 5px);
	}

		.ipsSubList a::before{
			content: "\e185";
			font-family: var(--i-font-awesome);
			font-weight: 900;
			-webkit-font-smoothing: antialiased;
			display: inline-block;
			font-style: normal;
			font-variant: normal;
			line-height: 1;
			text-rendering: auto;
			vertical-align: 1px;
			margin-inline-end: .6em;
			font-size: .8em;
			/* Prevents layout shift */
			width: 1em;
		}

		/* Display 'read' status only to members */
		[data-ips-member] .ipsSubList__item--unread{
			font-weight: bold;
			color: var(--i-color_hard);
		}

			[data-ips-member] .ipsSubList__item--read a::before{
				font-weight: 400;
				opacity: .7;
			}

@media (any-hover:hover){
	.ipsSubList a:hover{
		background-color: color-mix(in srgb, currentColor 8%, transparent);
	}
}

/* Rating */
.ipsData .ipsRating{
	display: var(--i-data--display-rating, flex);
	margin: .6em 0;
	flex: 0 0 auto;
}

/*
	----------------
	- Contextual data tables
	----------------
*/

/* Active */
.ipsData__item--active {
	--i-co: var(--i-primary-contrast);
	--i-color_root: var(--i-primary-contrast);
	--i-color_soft: color-mix(in srgb, var(--i-co) 80%, transparent);
	--i-color_hard: var(--i-co);
	background: var(--i-primary) !important;
	color: var(--i-co);
}

	.ipsData__item--active .ipsIndicator,
	.ipsData__item--active .ipsData__title a{
		color: inherit;
	}

@container (max-width: 750px){

	/* Relocate mod checkbox in some tables to left side on mobiles */
	.ipsData__item--snippet .ipsData__mod{
		position: absolute;
		bottom: var(--i-data--padding);
		inset-inline-start: var(--i-data--padding);
	}

	.ipsData--snippet-topic-list .ipsData__mod{
		align-self: end;
	}

}


/*
	----------------
	- Tables
	----------------
*/

.ipsData--table{
	--i-data--title: 1.1em;
	--i-data--padding: clamp(1em, 2cqw, 1.3em);
	--i-data--desc-truncate: 2;

	--i-data--show-last-author: ;
	--i-data--show-last-reply: initial;
}
@supports not (padding: 1cqw){
	.ipsData--table{
		--i-data--padding: 1em;
	}
}

/* Large */
@container (min-width: 750.1px){

	.ipsData--table .ipsData__content{
		display: contents;
	}
	.ipsData--table .ipsData__main{
		flex: 1 1 auto;
	}

	.ipsData--table .ipsData__extra{
		display: contents;
	}

	.ipsData--table .ipsData__stats{
		flex: 0 0 11ch;
		display: grid;
		align-content: center;
		justify-items: end; /* Aligns text and ratings to the end */
		/* The below prevents unintended wrapping in certain scenarios, such as:
			0
			replies
		*/
		min-width: fit-content;
		margin-inline-end: 1em;

		/* Overwrite the "small" design, which moves stats to the end */
		order: unset;
	}

	/* If group badges exist, add a basis to stats so they vertically align neatly */
	.ipsData--table:has(.ipsData__groups) .ipsData__stats{
		flex: 0 0 10ch;
	}

	/* Large stats: Place the stats in a row, with each value/label stacked vertically */
	.ipsData--table .ipsData__stats--large{
		display: var(--i-data--display-stats, flex);
		gap: 2em;
		line-height: 1.1;
		flex: 0 0 auto;
		text-align: center;
	}

		:where(.ipsData--table .ipsData__stats--large li){
			display: grid;
			gap: .25em;
		}
		:where(.ipsData--table .ipsData__stats--large span:first-of-type){
			font-size: 1.3em;
			color: var(--i-color_root);
		}

	/* v5 todo: Relocate live activity to meta position? */
	.ipsData--table .ipsData__stats .ipsLiveActivity{
		margin-inline-end: -.5em;
	}
	.ipsData--table .ipsData__last{
		flex: 0 0 var(--i-data--latest--width);
		order: 1; /* Move latest to end in table UI */
	}
	.ipsData--table .ipsData__mod{
		order: 2;
	}

	/* Remove middot/replied icon */
	.ipsData--table .ipsData__last::after{
		display: none;
	}

	/* Stacked "latest" column in large tables */
	.ipsData--table .ipsData__last .ipsUserPhoto{
		width: 2.4em;
	}
	.ipsData--table .ipsData__last-text{
		display: grid;
	}
	/* Remove middot/reply icon */
	.ipsData--table .ipsData__last-text::after{
		display: none;
	}

}

/* Small */
@container (max-width: 750px){

	.ipsData--table{
		--i-data--show-stats-icon: initial;
		--i-data--hide-stats-icon: ;

		--i-data--show-stats-label: ;
		--i-data--hide-stats-label: initial;
	}

	/* Align the image to the start */
	.ipsData--table :is(.ipsData__image, .ipsFigure, .ipsData__icon){
		align-self: start;
	}

	/* Space out all content elements when stacked */
	.ipsData--table .ipsData__content{
		display: grid;
		gap: .3em;
	}
	.ipsData--table.ipsData--category .ipsData__content{
		gap: 1em;
	}

	/* Floated assigned badges */
	.ipsData--table .ipsBadge--assigned{
		float: inline-end;
		margin-inline-end: 0;
	}

	/* .1em is used since 0em causes touch-target concerns with Lighthouse */
	.ipsData--table .ipsData__extra{
		margin-top: .1em;
	}

	.ipsData--table .ipsData__mod{
		align-self: end;
	}

	/* Stack the last into in category tables, in small contexts. The primary slot often contains long topic titles, and when they wrap, the middot is placed poorly. So lets just keep everything on 2 rows with no middots */
	.ipsData--grid.ipsData--category .ipsData__last-text{
		display: grid;
	}
	.ipsData--grid.ipsData--category .ipsData__last-text::after{
		display: none;
	}
}


/* Categories */
.ipsData--category{
	--i-data--icon-width: 32px;
	--i-data--latest--width: clamp(16em, 33%, 22em);
	--i-data--title: 1.2em;
	--i-data--desc-truncate: 99;

	--i-data--show-latest-photo: initial;
	--i-data--hide-latest-photo: ;
}

/* Ensure indicators in categorys are always centered, since the text is always centered here */
.ipsData--category .ipsData__item > .ipsIndicator{
	align-self: center;
}

/*
	----------------
	- Wallpaper
	----------------
*/
.ipsData--wallpaper{
	--i-data--basis: 290px;
	--i-data--padding: 1.4em;
	--i-data--radius: var(--i-design-radius);
	--i-data--title: 1.2em;
	--i-data--gap: 1em;
	--i-data--max: 99;
	--i-data--min: 1;
	--i-data--icon-ratio: auto;
	--i-data--wallpaper-height: min(110%, 400px);

	--i-data--display-desc: none;

	--i-data--show-tags: ;
	--i-data--hide-tags: initial;

	--i-data--show-stats-icon: initial;
	--i-data--hide-stats-icon: ;

	--i-data--show-stats-label: ;
	--i-data--hide-stats-label: initial;

	--i-data--show-last-author: initial;
	--i-data--show-last-reply: ;

	--i-data--display-groups: none;

	grid-template-columns: repeat(auto-fill, minmax(
		min(
			100% / var(--i-data--min) - var(--i-data--gap),
			max(
				var(--i-data--basis),
				100% / var(--i-data--max) - var(--i-data--gap)
			)
		)
		, 1fr
	));
	gap: var(--i-data--gap);
	padding: var(--i-data--gap);
}

:where(.ipsWidget i-data:last-child .ipsData--wallpaper) {
	overflow: hidden;
	border-bottom-left-radius: var(--i-box--bo-ra);
	border-bottom-right-radius: var(--i-box--bo-ra);
}

/* If Wallpaper carousels are added to a widget group which displays widgets as columns, ensure the Wallpaper carousels occupy 100% of their widget height, otherwise a tall widget next to a Wallpaper Carousel can leave empty space below the carousel */
:where(.ipsWidget:has(.ipsData--wallpaper.ipsData--carousel)){
    display: flex;
    flex-direction: column;
}
:where(.ipsWidget:has(.ipsData--wallpaper.ipsData--carousel) .ipsWidget__content){
    flex: 1 1 auto;
    display: grid;
}
:where(.ipsData--wallpaper.ipsData--carousel){
    min-height: 100%;
}

/* If the gap is removed, change the scrollbar to white so it's easier to see */
.cWidgetContainer--isWidget[style*="--i-widget--gap:0px"] .ipsData--wallpaper.ipsData--carousel{
	scrollbar-color: hsl(0 0% 100% / .5) transparent;
}

/* If placed within a widget, let the widget settings control the variables */
:where(.cWidgetContainer--isWidget) .ipsData--wallpaper {
	--i-data--basis: var(--i-widget--size, 290px);
	--i-data--gap: var(--i-widget--gap, 1em);
}

@media (any-hover:hover){
	.ipsData--wallpaper .ipsData__item:hover > .ipsLinkPanel{
		background-color: hsl(0 0% 100% / .15);
	}		
}

.ipsData--wallpaper .ipsData__item{
	display: grid;
	padding: 0;
	overflow: hidden;
	border-radius: min(var(--i-data--radius), var(--i-data--gap)); /* Wallpaper grids with 0px gap should have 0px radius */
	background: var(--i-background_dark); /* Added here to ensure the background appears even if images/icons don't exist */
	isolation: isolate; /* This helps with moving the absolute positioned image to the back */
}

/* Pseudo element is needed since height is controlled by percentage (based on width) */
.ipsData--wallpaper .ipsData__item::before{
	content: "";
	padding-top: var(--i-data--wallpaper-height);
	grid-area: 1/1;
}

.ipsData--wallpaper .ipsData__item > *{
	grid-area: 1/1;
}

/* Flex gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsData--wallpaper .ipsData__item > *{
		margin: 0;
	}
}

.ipsData--wallpaper .ipsData__image,
.ipsData--wallpaper .ipsFigure{
	align-self: stretch;
	border-radius: 0;
	position: absolute;
	z-index: -1;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
}

.ipsData--wallpaper .ipsData__image > i{
	color: hsl(0 0% 100% / .3);
	background-color: transparent;
	font-size: 30cqmin;
}

.ipsData--wallpaper .ipsData__image > i::before{
	height: 1em;
}

.ipsData--wallpaper .ipsData__content{
	--i-color_soft: hsl(0 0% 100% / .8);
	--i-color_hard: hsl(0 0% 100%);
	--i-color_root: hsl(0 0% 100%);
	--i-link--co: var(--i-color_hard);
	--i-link-hover--co: var(--i-color_hard);
	color: var(--i-color_root);

	align-self: end;
	display: grid;
	gap: .6em;

	padding: var(--i-data--padding);
	padding-top: 8em;
	background-image: linear-gradient(hsl(220 22% 10% / 0), hsl(220 22% 10% / .7) 8em);
}

/* Brighten the category name and indicator, since dark colors won't have enough contrast */
.ipsData--wallpaper .ipsIndicator,
.ipsData--wallpaper .ipsContainerTitle{
	color: inherit;
}

.ipsData--wallpaper .ipsBadge--prefix{
	/* display: flex;
	width: fit-content; */
}

.ipsData--wallpaper .ipsData__meta{
	flex: 1 1 auto;
}

.ipsData--wallpaper .ipsRating{
	margin: 0;
}

/* Tags */
.ipsData--wallpaper .ipsTags__item:not(.ipsTags__item--prefix), 
.ipsData--wallpaper .ipsTags__more{
	color: inherit;
}

.ipsData--wallpaper .ipsData__extra{
	margin-top: 0;
}

.ipsData--wallpaper .ipsData__stats-icon::before,
.ipsData--wallpaper .ipsData__stats :is(.fa-regular, .fa-solid){
	opacity: 1;
}

/* Move mod checkbox to top right */
.ipsData--wallpaper .ipsData__mod{
	place-self: start end;
	padding: 1em;
}

.ipsData--wallpaper .ipsInput:where([type="checkbox"], [type="radio"]){
	--i-input--ba-co: hsl(0 0% 100%);
	--i-input--bo-wi: 0px;
	box-shadow: hsl(0 0% 0% / .5) 0px 0px 0px 1px;
}

/* Add outline to selected wallpaper items */
.ipsData--wallpaper .ipsData__item:has(:is(.ipsInput, [data-role="moderation"]):checked){
	outline: 2px solid var(--i-primary);
	outline-offset: 2px;
}

/*
	----------------
	- Mini grid
	----------------
*/
.ipsData--mini-grid{
	--i-data--basis: 330px;
	--i-data--cell-spacing: 1em;
	--i-data--padding: 1.2em;
	--i-data--border: 1px;
	--i-data--icon-ratio: 1;
	--i-data--icon-width: 4em;
	--i-data--icon-radius: min(5px, var(--i-design-radius));
	--i-data--gap: var(--i-data--border);
	--i-data--display-meta: none;
	--i-data--display-desc: none;

	--i-data--show-stats-icon: initial;
	--i-data--hide-stats-icon: ;

	--i-data--show-stats-label: ;
	--i-data--hide-stats-label: initial;

	--i-data--show-last-author: initial;
	--i-data--show-last-reply: ;

	--i-data--show-tags: ;
	--i-data--hide-tags: initial;

	--i-data--show-fields: ;
	--i-data--hide-fields: initial;

	grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--i-data--basis)), 1fr));
	gap: var(--i-data--gap);
	padding: max(0px, var(--i-data--gap) - 1px);
	overflow: hidden;
}

/* If placed within a widget, let the widget settings control the variables */
:where(.cWidgetContainer--isWidget) .ipsData--mini-grid {
	--i-data--basis: var(--i-widget--size, 300px);
	--i-data--gap: max(1px, var(--i-widget--gap) + var(--i-data--border)); /* We need at least 1px gap for grids */
}

	.ipsData--mini-grid.ipsData--carousel:has(.ipsData__item:nth-child(6)){
		display: grid;
		grid-template-rows: repeat(2, auto);
		grid-template-columns: none;
		grid-auto-flow: column;
		grid-auto-columns: min(var(--i-data--basis), 80%);
	}

	.ipsData--mini-grid.ipsData--carousel:has(.ipsData__item:nth-child(9)){
		grid-template-rows: repeat(3, auto);
	}

	.ipsData--mini-grid .ipsData__item{
		border-width: 0;
		outline: var(--i-data--border) solid var(--i-data--bo-co);
	}

	.ipsData--mini-grid .ipsRating{
		margin: .4em 0;
	}

	/* Make the last content soft, otherwise it's a little too much... */
	.ipsData--mini-grid .ipsData__last-primary{
		color: var(--i-color_soft);
	}

	.ipsData--mini-grid .ipsData__fields{
		margin-top: 0;
	}


/*
	----------------
	- Grid
	----------------
*/
.ipsData--grid{
	--i-data--basis: 320px;
	--i-data--icon-ratio: 16/10;
	--i-data--icon-width: 100%;
	--i-data--radius: 0px;
	--i-data--border: 1px;
	--i-data--gap: 0px;
	--i-data--max: 99;
	--i-data--min: 1;
	--i-data--padding: 1.2em;
	--i-data--cell-spacing: 1.2em;
	--i-data--desc-truncate: 3;

	--i-data--show-stats-icon: initial;
	--i-data--hide-stats-icon: ;

	--i-data--show-stats-label: ;
	--i-data--hide-stats-label: initial;

	/* Show latest photo */
	--i-data--show-latest-photo: initial;
	--i-data--hide-latest-photo: ;

	grid-template-columns: repeat(auto-fill, minmax(
        min(
            100% / (var(--i-data--min) + .99), 
            max(
                var(--i-data--basis),
                100% / (var(--i-data--max) + .99)
            )
        ), 1fr
	));
	gap: max(1px, var(--i-data--gap));
	padding: var(--i-data--gap);
	overflow: hidden;
}

.ipsData--grid:has(.ipsData__image){
	--i-data--padding: 1.5em;
	--i-data--title: 1.15em;
}

.ipsData--grid.ipsData--category{
	--i-data--title: 1.3em;
}

/* Inherit border-radius */
:where(.ipsWidget__content > .ipsData--grid:only-child){
	border-bottom-left-radius: var(--i-box--bo-ra);
	border-bottom-right-radius: var(--i-box--bo-ra);
}

/* If placed within a widget, let the widget settings control the variables */
:where(.cWidgetContainer--isWidget) .ipsData--grid{
	--i-data--basis: var(--i-widget--size, 320px);
	--i-data--gap: var(--i-widget--gap, var(--i-data--border));
}

	/* Add border using outline so we can fall down to a 1px border */
	.ipsData--grid .ipsData__item{
		align-items: stretch;
		border-width: 0;
		outline: var(--i-data--border) solid var(--i-data--bo-co);
		border-radius: var(--i-data--radius);

		/* Always stack grid items? Add this to the legacy code if it's moved to a :has() selector */
		flex-direction: column;
	}

	/* Cover photos */
	.ipsData--grid .ipsData__image{
		background: var(--i-background_3);
		flex: 0 0 auto;
		margin: calc(var(--i-data--padding) * -.3);
		margin-bottom: 0;
	}

		/* If the __image element contains an image, hide the fallback icons */
		.ipsData--grid .ipsData__image img ~ :is(.ipsIcon, i:not[class]){
			display: none !important;
		}

		/* Emoji and icons */
		.ipsData--grid .ipsData__image > :is(.ipsIcon, i:not[class]){
			font-size: 50cqmin;
		}

	/* We need flex here so we can push the latest reply to the bottom */
	.ipsData--grid .ipsData__content{
		display: flex;
		flex-direction: column;
		gap: .6em;
	}

	/* Flex gap fallback for < iOS 14.1 */
	@supports (-webkit-touch-callout: none) and (not(translate: none)){
		.ipsData--grid .ipsData__content > :not(:first-child){
			margin-top: .6em;
		}
	}

	.ipsData--grid .ipsData__main{
		margin-bottom: auto;
		flex: 0 0 auto;
	}

	/* Increase margin of descriptions in grid categories */
	.ipsData--grid .ipsData__desc{
		margin-top: .6em;
	}

	/* Push everything down after description/meta */
	.ipsData--grid .ipsData__desc,
	.ipsData--grid .ipsData__meta{
		margin-bottom: auto;
	}

		/* If the cell contains both desc and meta, remove the auto margin from meta */
		.ipsData--grid .ipsData__desc ~ .ipsData__meta{
			margin-bottom: 0;
		}

	/* Inline stats */
	.ipsData--grid .ipsData__stats {
		text-align: start;
		gap: 0.3em 1.5em;
	}
	.ipsData--grid .ipsData__last + .ipsData__stats{
		/* Ensure stats are always at the end, even if they've wrapped onto their own line due to a long username in ipsData__last */
		margin-inline-start: auto;
	}

/* Reposition mod checkbox to top right */
.ipsData--grid .ipsData__mod{
	position: absolute;
	padding: 6px;
	top: 5px;
	inset-inline-end: 5px;
	background: var(--i-box--ba-co);
	border-radius: 6px;
}

/*
	----------------
	- Minimal
	----------------
*/
.ipsData--minimal{
	--i-data--padding: 1em;
	--i-data--cell-spacing: 1em;
	--i-data--icon-width: 30px;

	--i-data--display-desc: none;

	--i-data--show-stats-icon: initial;
	--i-data--hide-stats-icon: ;

	--i-data--show-stats-label: ;
	--i-data--hide-stats-label: initial;

	--i-data--show-tags: ;
	--i-data--hide-tags: initial;

	--i-data--show-last-author: initial;
	--i-data--show-last-reply: ;

	--i-data--show-fields: ;
	--i-data--hide-fields: initial;

	--i-data--show-category: ;
	--i-data--hide-category: initial;
}
.ipsData--minimal .ipsData__extra{
	margin-top: .2em;
}
.ipsData--minimal .ipsData__stats{
	gap: .7em 2em;
}
/* Flex gap fallback for < iOS 14.1 */
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsData--minimal .ipsData__stats > :not(:first-child){
		margin-inline-start: 2em;
	}
}
.ipsData--minimal .ipsData__extra .ipsData__stats{
	order: 1;
	margin-inline-start: auto;
}

/* Hide certain elements */
.ipsData--minimal .ipsBadge--prefix,
.ipsData--minimal .ipsRating,
.ipsData--minimal .ipsTime__long{
	display: none;
}
.ipsData--minimal .ipsTime__short{
	display: revert;
}

/* If placed within a widget, let the widget settings control the variables */
:where(.cWidgetContainer--isWidget) .ipsData--carousel.ipsData--minimal {
	--i-data--basis: var(--i-widget--size, 300px);
}

/* Minimal carousels always have a 1px border between items */
.ipsData--carousel.ipsData--minimal {
	--i-data--gap: 1px;
	scroll-padding-inline: 0px;
}

	.ipsData--carousel.ipsData--minimal .ipsData__item{
		border-width: 0;
		outline: 1px solid var(--i-data--bo-co);
	}


/*
	----------------
	- Featured
	----------------
*/

.ipsData--featured{
	--i-data--icon-width: min(180px, 20%);
	--i-data--title: clamp(1.1em, 1em + 0.7cqw, 1.5em);
	--i-data--padding: clamp(1.1em, 3cqw, 2.2em);
	/* Reset gap and basis, since these should always be 0px and 100% for Featured */
	--i-data--gap: 1px;
	--i-data--basis: 100%;
}
@supports not (padding: 1cqw){
	.ipsData--featured{
		--i-data--title: 1.2em;
		--i-data--padding: 1em;
	}
}

@container (max-width: 500px){
	:where(.ipsData--featured .ipsData__title .ipsBadges){
		float: inline-end;
	}
}

/* Show stats icons if they exist on small UI */
@container (max-width: 600px){
	.ipsData--featured{
		--i-data--show-stats-icon: initial;
		--i-data--hide-stats-icon: ;

		--i-data--show-stats-label: ;
		--i-data--hide-stats-label: initial;
	}
}

/* Display more of the description on large UI */
@container (min-width: 800px){
	.ipsData--featured{
		--i-data--desc-truncate: 6;
		/* Show latest photo */
		--i-data--show-latest-photo: initial;
		--i-data--hide-latest-photo: ;
	}
}

.ipsData--featured .ipsData__item{
	align-items: start;
}

.ipsData--featured .ipsData__content{
	align-self: center;
	display: flex;
	flex-direction: column;
}

.ipsData--featured .ipsData__desc{
	--i-co: var(--i-color_root);
	margin: .5em 0;
}

@container (min-width: 600px){

	.ipsData--featured .ipsData__content{
		align-self: stretch;
		align-content: space-between;
		gap: 1em;
	}

	.ipsData--featured .ipsTags{
		margin-top: 1.5em;
	}

	.ipsData--featured .ipsData__extra{
		display: flex;
		flex-wrap: wrap;
		gap: 1em;
		margin-top: auto;
	}

	.ipsData--featured .ipsData__stats {
		order: 1;
		margin-inline-start: auto;
		flex-direction: row-reverse;
	}
}


/*
	----------------
	- Align stats/latest correctly in certain designs
	----------------
*/

:where(.ipsData--wallpaper, .ipsData--grid, .ipsData--mini-grid) .ipsData__extra{
	margin-top: .3em;
}

/*
	----------------
	- Carousel
	----------------
*/

:where(.ipsData--carousel){
	--i-data--basis: 100%; /* Give carousels 100% width by default, but allow other classes like .ipsData--grid to overwrite them */

	/* Set defaults, but let other classes overwrite, such as .ipsData--grid */
	--i-data--gap: 0px;
	--i-data--border: 1px;
}

/* If placed within a widget, let the widget settings control the variables */
:where(.cWidgetContainer--isWidget .ipsData--carousel){
	--i-data--basis: var(--i-widget--size, 100%);
	--i-data--gap: var(--i-widget--gap, 0px);
}

.ipsData--carousel{
	display: flex;
	--i-data--min: 1;
	--i-data--max: 99;
	gap: max(1px, var(--i-data--gap));
	overflow: auto;
	overscroll-behavior-x: contain;
	/* Snap padding should cater for the border, otherwise the border of the "out of view" element is visible */
	scroll-padding-inline: max(0px, var(--i-data--gap));
	scroll-behavior: smooth;
	scroll-snap-type: x mandatory;
	scrollbar-width: thin;
	scrollbar-color: color-mix(in srgb, var(--i-co) 40%, transparent) transparent;
	position: relative; /* Required for scrollLeft as part of i-carousel-navigation */
}

/* Scroll-padding prevents entry.isIntersecting from working in RTL Safari. Without this fix, carousel arrow navigation can break. Last tested in 26.1 */
@supports (-webkit-hyphens: auto){
	[dir="rtl"] .ipsData--carousel::after{
		content: "";
		flex: 0 0 max(var(--i-data--padding) - var(--i-data--gap), 1px);
	}
}

/* Carousel items */
.ipsData--carousel .ipsData__item{
	scroll-snap-align: start;
	border-width: 0;
	flex: 0 0 200px;
	flex-basis:
		min(
			(100% - (var(--i-data--gap) * (var(--i-data--min) - 1))) / var(--i-data--min),
			clamp(
				var(--i-data--basis),
				(100% - (var(--i-data--gap) * (var(--i-data--max) - 1))) / var(--i-data--max),
				100%
			)
		)
	;
}

.ipsData--carousel .ipsData__item:last-child{
	scroll-snap-align: end;
}

.ipsData--carousel:has(:focus-visible):focus-within .ipsData__item:not(:focus-within){
	scroll-snap-align: none;
}

.ipsData--carousel ~ .ipsCarouselNav{
	border-top: 1px solid var(--i-background_3);
	padding: 1em;
}


/* Non-JS moderation bar */
.ipsData__modBar{
	background: var(--i-background_4);
	padding: var(--i-sp_2);
	display: flex;
	justify-content: flex-end;
	gap: var(--i-sp_2);
}


/*
	----------------
	- Link panels
	----------------
*/

.ipsLinkPanelWrap{
	isolation: isolate;
	position: relative;
}

.ipsLinkPanel{
	position: absolute;
	top: 0; left: 0; right: 0; bottom: 0; /* Inset isn't used here as it prevents the linkpanel from working in ancient browsers */
	border-radius: inherit;
	grid-column: initial; /* Ensure ipsLinkPanel isn't restricted by any grid areas (such as .ipsData--grid) */
}

/* Hide panels if disabled via settings */
[data-ips-theme-setting-link-panels="0"] .ipsLinkPanel{
	display: none;
}

/* isolation: isolate; doesn't work correctly in Safari in this context. Last tested in 18.3 */
:where(:is(.ipsLinkPanelWrap, .ipsStreamItem, .ipsData__item) :is(a, button, input, textarea, [data-ipsTooltip], iframe, abbr, select, summary)){
	position: relative;
}
@media (any-hover:hover){
	:where([data-ips-theme-setting-link-panels="1"] :is(.ipsLinkPanelWrap, .ipsStreamItem, .ipsData__item)) a:hover{
		text-decoration: underline;
	}
}

	.ipsLinkPanel span{
		clip-path: inset(50%);
		height: 1px;
		margin: -1px;
		overflow: hidden;
		position: absolute;
		white-space: nowrap;
		width: 1px;
	}

	@media (any-hover:hover){
		:hover > .ipsLinkPanel{
			background: var(--i-background_hover);
		}		
	}

/* Apply border-radius to last row in certain situations */
:where(.ipsWidget, .ipsBox:not(:has(.ipsButtonBar--bottom)) .ipsData__item:last-child .ipsLinkPanel){
	border-radius: 0 0 var(--i-box--bo-ra) var(--i-box--bo-ra);
}

/*
	----------------
	- Hide elements in certain widgets/sizes
	----------------
*/

.ipsData--featured :is([data-show-on]:not([data-show-on~="featured"]), [data-hide-on~="featured"]),
.ipsData--grid :is([data-show-on]:not([data-show-on~="grid"]), [data-hide-on~="grid"]),
.ipsData--minimal :is([data-show-on]:not([data-show-on~="minimal"]), [data-hide-on~="minimal"]),
.ipsData--mini-grid :is([data-show-on]:not([data-show-on~="mini-grid"]), [data-hide-on~="mini-grid"]),
.ipsData--table :is([data-show-on]:not([data-show-on~="table"]), [data-hide-on~="table"]),
.ipsData--wallpaper :is([data-show-on]:not([data-show-on~="wallpaper"]), [data-hide-on~="wallpaper"]){
	display: none !important;
}

@container (max-width: 750px){
	/* Hide pagination from the topic feed when it's small */
	.ipsData--topic-feed-widget:is(.ipsData--table, .ipsData--minimal, .ipsData--mini-grid) .ipsMiniPagination{
		display: none;
	}
}

/*
	----------------
	- Adjust certain data elements
	----------------
*/

/* Messenger */
.ipsData__item--messenger{
	--i-data--cell-spacing: .8em;
	--i-data--padding: 1.2em;
	--i-data--icon-width: 26px;
}

/* Increase snippet in postFeed */
.ipsData--widget-forums-postFeed.ipsData--table{
	--i-data--desc-truncate: 10;
}
.ipsData--widget-forums-postFeed.ipsData--table .ipsData__icon{
	align-self: start;
}
.ipsData--widget-forums-postFeed .ipsData__meta{
	margin-top: .5em;
}

/* Notifications dropdown */
.ipsData--user-notifications{
	--i-data--title: 1em;
}
.ipsData__item--notification[data-ips-read] .ipsData__title a{
	color: var(--i-color_soft);
}


/*
	----------------
	- Loading skeletons. Eg, used in Events Overview and Fluid forum view 
	----------------
*/

@keyframes ipsData__item--loading {
	0% { opacity: .5 }
}

.ipsData__item--loading :is(.ipsData__icon, .ipsData__image, .ipsData__title, .ipsData__meta, .ipsData__desc){
	background: var(--i-background_3);
	animation: ipsData__item--loading 1s infinite alternate;
}

.ipsData__item--loading .ipsData__title{
	height: 1em;
	height: 1lh;
	max-width: min(20ch, 70%);
}
.ipsData__item--loading .ipsData__meta{
	height: .7em;
	height: .7lh;
	max-width: min(32ch, 90%);
	margin-top: .3em;
}
.ipsData__item--loading .ipsData__desc{
	height: 3em;
	height: 3lh;
	margin-top: .5em;
	display: block; /* Ensure description is shown, since it is hidden due to .ipsData__desc:-moz-only-whitespace */
}

.ipsData__item--loading .ipsData__stats::before,
.ipsData__item--loading .ipsData__stats::after,
.ipsData__item--loading .ipsData__last::before,
.ipsData__item--loading .ipsData__last::after{
	content: '';
	display: block;
	background: var(--i-background_3);
	height: .8em;
	height: .8lh;
	width: 9ch;
	margin: .1lh 0;
}
.ipsData__item--loading .ipsData__stats::after{
	width: 8ch;
}

/* View All row */
.ipsViewAll a{
	text-align: end;
	display: block;
	background: var(--i-background_2);
	border-top: 1px solid var(--i-background_4);
	padding: .9em;
	color: var(--i-color_root);
	font-weight: 550;
	font-size: .92em;
}

:where(.ipsWidget, .ipsBox) .ipsViewAll a{
	border-bottom-left-radius: var(--i-box--bo-ra);
	border-bottom-right-radius: var(--i-box--bo-ra);
}

@media (any-hover:hover){
	.ipsViewAll a:hover{
		color: var(--i-color_hard);
	}
}

/*
	----------------
	- Legacy browsers
	----------------
*/

@supports not selector(a:has(b)){
	/* The container-type is assigned using :has(), so we need to reset font-sizes if :has() isnt' supported */
	.ipsData__image > i, 
	.ipsData__image > .ipsIcon,
	.ipsData__image > .ipsNsfwOverlay,
	.ipsData__image .ipsIcon--emoji,
	.ipsData--wallpaper .ipsData__image > i,
	.ipsData--grid .ipsData__image > :is(.ipsIcon, i:not[class]){
		font-size: 1em;
	}
}

@supports not (aspect-ratio: 1){
	.ipsData__image::before{
		content: '';
		display: block;
		padding-top: 100%;
	}
	.ipsData--grid .ipsData__image::before{
		padding-top: 56.25%;
	}
	.ipsData__image img{
		position: absolute;
	}
}

@supports not (container-type: inline-size){
	.ipsData__image{
		position: relative;
	}
	.ipsData__image:not(a){
		pointer-events: none;
	}
	.ipsData__stats{
		gap: 0 2em;
	}
	.ipsData--table{
		--i-data--padding: 1.3em;
	}
}

@property --i-dropdown--backdrop-scroll{
	syntax: "<percentage>";
	inherits: true;
	initial-value: 0%;
}
@property --i-dropdown--backdrop-transition{
	syntax: "<percentage>";
	inherits: true;
	initial-value: 0%;
}

i-dropdown{
	inset: auto; /* Reset [popover] defaults. Required for RTL */
	--i-dropdown--tr-du: .3s;
	scrollbar-width: none;
}

i-dropdown::-webkit-scrollbar{
	-webkit-appearance: none;
	display: none;
	width: 0px;
}

/* Menu */
.iDropdown{
	background: var(--i-dropdown--ba-co);
	color: var(--i-dropdown--co);
	border-radius: var(--i-dropdown--bo-ra);
	box-shadow: var(--i-dropdown--bo-sh);

	transition-timing-function: ease-in-out;
	transition-duration: var(--i-dropdown--tr-du);

	display: flex;
	flex-direction: column;

	/* Prevent outside styles from leaking in */
	font-family: var(--i-font-family);
	font-size: var(--i-rem);
	font-style: normal;
	font-weight: normal;
	letter-spacing: normal;
	line-height: 1.5;
	text-align: start;
	text-decoration: none;
	text-shadow: none;
	text-transform: none;
}

.iDropdown__header{
	flex: 0 0 auto;
	padding: 1em 1.4em;
	color: var(--i-color_hard);
	border-bottom: 1px solid var(--i-background_5);
	display: flex;
	align-items: center;
	justify-content: space-between;
	flex-wrap: wrap;
	gap: 1em;
}

.iDropdown__headerTitle{
	font-weight: 600;
	font-size: 1.3em;
}

:where(.iDropdown__header) a{
	color: inherit;
}
:where(.iDropdown__header a):hover{
	text-decoration: underline;
}

.iDropdown__content{
	overflow: auto;
	scrollbar-width: thin;
	flex: 1 1 auto;
}

.iDropdown__footer{
	flex: 0 0 auto;
	padding: 1em;
	color: var(--i-color_soft);
	border-top: 1px solid var(--i-background_5);
	font-weight: 500;
}

a.iDropdown__footer{
	display: block;
	text-align: center;
	border-bottom-left-radius: inherit;
	border-bottom-right-radius: inherit;
}

a.iDropdown__footer:hover{
	background: color-mix(in srgb, currentColor 6%, transparent);
}

/* Dropdown links */
.iDropdown__items{
	--i-outline-offset: -2px;
	padding: 8px;
	overflow: auto;
}
.iDropdown__title{
	font-weight: 600;
	color: var(--i-color_soft);
	padding: 0.8em 1em;
	margin-bottom: 4px;
	text-transform: uppercase;
	font-size: 0.9em;
}
.iDropdown__items > li > :is(a, button, label){
	display: flex;
	align-items: center;
	gap: .8em;
	padding: .8em 1em;
	border-radius: 5px;
	text-decoration: none !important;
	cursor: pointer;
	color: inherit;
	width: 100%;
	font-weight: 500;
}

/* Space out inputs so active ones aren't one large clump */
.iDropdown__items > li > label{
	margin: 2px 0;
	-webkit-tap-highlight-color: transparent;
}

	.iDropdown__items :is(.fa-solid, .fa-regular, .fa-brands):first-child{
		opacity: .5;
		width: 1.2em;
		margin-inline-end: .3em;
		text-align: center;
	}

@media(hover){
	.iDropdown__items > li > :is(a, button, label):hover{
		background-color: var(--if-light, var(--i-background_3)) var(--if-dark, var(--i-background_4));
		color: var(--i-color_hard);
	}
}

/* Active */
.iDropdown__items > li > label:has([type="radio"]:checked),
i-dropdown:not([data-i-dropdown-selectable="checkbox"]) .iDropdown__items > li > :is([aria-selected="true"], [aria-current]){
	--i-outline-offset: -4px;
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
}
/* Active hover */
@media(hover){
	.iDropdown__items > li > label:has([type="radio"]:checked):hover,
	i-dropdown:not([data-i-dropdown-selectable="checkbox"]) .iDropdown__items > li > :is([aria-selected="true"], [aria-current]):hover{
		background-color: var(--if-light, var(--i-primary-dark)) var(--if-dark, var(--i-primary-light));
		color: var(--i-primary-contrast);
	}
}

/* Disabled */
.iDropdown__items [data-disabled],
.iDropdown__items label:has(:disabled){
	pointer-events: none;
	font-style: italic;
	opacity: .4;
}

/* Checkbox and radio */
.iDropdown__items :is([type="checkbox"], [type="radio"]),
.iDropdown__input{
	appearance: none;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 1.2em;
	height: 1.2em;
	color: inherit;
	/* Without this, the inputs use the default cursor */
	cursor: inherit;
	/* For <i class="iDropdown__input" aria-hidden="true"></i> */
	font-style: normal;
	/* Improve focus-visible styles for keyboard users */
	outline-offset: 2px;
  	border-radius: 4px;
}

@supports not selector(a:has(b)){
    .iDropdown__items :is([type="checkbox"], [type="radio"]):checked,
    :is([aria-selected="true"], [aria-current]) > .iDropdown__input{
        color: var(--i-color_primary);
    }
}

.iDropdown__items [type="checkbox"]::before,
.iDropdown__items [type="radio"]::before,
.iDropdown__input::before{
	content: "";
	border-radius: 50%;
	width: .6em;
	height: .6em;
	background: currentColor;
	opacity: .25;
}
.iDropdown__items [type="checkbox"]::before,
[data-i-dropdown-selectable="checkbox"] .iDropdown__input::before{
	border-radius: 2px;
}

	.iDropdown__items input:checked::before,
	:is([aria-selected="true"], [aria-current]) > .iDropdown__input::before{
		content: "\f00c";
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;

		opacity: 1;
		background: transparent;
		width: auto;
		height: auto;
		line-height: 0;
	}

/* Since multiple :checked checkboxes looks odd, we simplify the UI */
.iDropdown__items > li > label:has([type="checkbox"]:checked),
[data-i-dropdown-selectable="checkbox"] .iDropdown__items > li > :is([aria-selected="true"], [aria-current]){
	color: var(--i-color_hard);
}
.iDropdown__items [type="checkbox"]:checked,
[data-i-dropdown-selectable="checkbox"] :is([aria-selected="true"], [aria-current]) .iDropdown__input{
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
	border-radius: 4px;
}
.iDropdown__items [type="checkbox"]:checked::before,
[data-i-dropdown-selectable="checkbox"] :is([aria-selected="true"], [aria-current]) .iDropdown__input::before{
	font-size: .7em;
}

.iDropdown__items hr{
	margin: .6em 0;
	background: currentColor;
	height: 1px;
	border-width: 0;
	opacity: .3;
}

/* Descriptions, display under the main item text */
.iDropdown__minor{
	font-weight: normal;
	margin-top: .3em;
	display: block;
	opacity: .7;
	font-size: .9em;
}

/* Mobile */
@media (max-width: 499px){

	html:has(i-dropdown:popover-open){
		overflow: hidden;
	}

	i-dropdown{
		--i-dropdown--backdrop-transition: 0%;
		--i-dropdown--backdrop-scroll: 100%;

		width: 100%;
		height: 100%;
		overflow-y: auto;
		overscroll-behavior-y: contain;
		scroll-snap-type: y mandatory;
		transition-property: display, overlay, --i-dropdown--backdrop-transition;
		transition-behavior: allow-discrete;
		transition-timing-function: ease-in;
		transition-duration: var(--i-dropdown--tr-du);
		/* Polyfill */
		top: 0; left: 0;
		position: fixed;
	}
	i-dropdown:popover-open{
		--i-dropdown--backdrop-transition: 100%;
	}
	i-dropdown[class*=":popover-open"]{
		--i-dropdown--backdrop-transition: 100%;
	}
	@starting-style{
		i-dropdown:popover-open{
			--i-dropdown--backdrop-transition: 0%;
		}
	}

	/* We need to use a pseudo element here since Safari instantly deletes the ::backdrop from the DOM on close. Last checked in 26.5 */
	i-dropdown::before{
		content: "";
		position: fixed;
		pointer-events: none;
		top: 0; left: 0; right: 0; bottom: 0;
		background: hsl(0 0% 0% / .6);
		-webkit-backdrop-filter: blur(1px);
		backdrop-filter: blur(1px);
		opacity: min(var(--i-dropdown--backdrop-scroll), var(--i-dropdown--backdrop-transition));
	}

	.iDropdownSwipe{
		height: 20px;
		margin-bottom: 100vh;
		scroll-snap-align: start;
	}

	/* Tap to dismiss */
	.iDropdownDismiss{
		background: none !important;
		border-width: 0;
		padding: 1em;
		text-align: end;
		display: block;
		-webkit-tap-highlight-color: transparent;
		width: 100%;
		position: relative;
	}
		/* Full screen dismiss */
		.iDropdownDismiss::before{
			content: "";
			position: fixed;
			inset: 0;
		}
		/* Close icon on focus (VoiceOver on iOS) */
		.iDropdownDismiss:focus-visible::after{
			content: "\00d7";
			content: "\00d7" / "";
			font-size: 2em;
			color: #fff;
		}

	/* Zero-JS fallback: Ensure tapping backdrop closes dropdowns if JS hasn't loaded */
	body:has(i-dropdown:not(:defined):popover-open){
		pointer-events: none;
	}
	/* Align menu to bottom if JS hasn't loaded */
	i-dropdown:not(:defined){
		pointer-events: auto;
		height: auto;
		top: auto;
		bottom: 0;
		overflow: visible;
	}
	i-dropdown:not(:defined)::before{
		opacity: 1;
	}

	.iDropdown{
		border-radius: max(var(--i-dropdown--bo-ra), 10px);
		border-bottom-left-radius: 0;
		border-bottom-right-radius: 0;
		box-shadow: var(--if-light, var(--i-dropdown--bo-sh)) var(--if-dark, inset hsl(0 0% 100% / .1) 0px 1px 0px, hsl(0 0% 0% / .6) 0px -1px 0px);
		min-height: min(15em, 100% - 50px);
		max-height: calc(100% - env(safe-area-inset-top) - 50px);
		padding-bottom: env(safe-area-inset-bottom);
		/* Height + drag handle */
		translate: 0 calc(100% + 20px);
		transition-timing-function: ease-out;
		transition-property: translate;
		/* Widths are sometimes defined elsewhere. Ensure that mobile menus are always 100% */
		width: 100% !important;
	}

	/* Elastic background */
	.iDropdown::after{
		content: "";
		display: block;
		height: 1px;
		box-shadow: 0px 220px 0px 220px var(--i-dropdown--ba-co);
	}

	:popover-open > .iDropdown{
		translate: 0 0;
	}
	@starting-style{
		:popover-open > .iDropdown{
			translate: 0 calc(100% + 20px);
		}
	}
	.\:popover-open > .iDropdown{
		translate: 0 0;
	}

	/* Drag handle */
	@media (hover:none){ 
		i-dropdown:defined .iDropdown::before{
			content: "";
			display: block;
			background: hsl(0 0% 100% / .6);
			box-shadow: inset 0px 1px 0px hsl(0 0% 100% / .5);
			-webkit-backdrop-filter: blur(8px);
			backdrop-filter: blur(8px);
			border-radius: 6px;
			width: 50px;
			height: 6px;
			position: absolute;
			top: -14px;
			left: calc(50% - 25px);
			pointer-events: none;
		}
	}

	i-dropdown::after{
		content: "";
		display: block;
		scroll-snap-align: end;
		height: 1px;
		margin-top: -2px;
	}

	/* Repaint Safari to prevent excess overscroll. Last tested in 26.5 */
	@supports (-webkit-hyphens: auto){
		i-dropdown:popover-open::after{
			transition: var(--i-dropdown--tr-du);
		}
		@starting-style{
			i-dropdown:popover-open::after{
				height: 2px;
			}
		}
	}

	.iDropdown__items{
		flex: 1 1 auto;
	}

	/* Fade out the backdrop when scrolling to dismiss */
	@supports ((animation-timeline: scroll()) and (animation-range: 0 100%)){
		@keyframes iPopoverScroll{
			from{
				--i-dropdown--backdrop-scroll: 0%;
			}
		}
		i-dropdown:defined{
			animation: iPopoverScroll linear forwards;
			animation-timeline: scroll(self);
			animation-range: 0 100%;
		}
	}

	/* This instantly hides the popover after the swipe gesture. It prevents a "backdrop flash" in Safari caused by the -scroll variable reverting back to 100% once the swipe gesture has occurred. Last tested in 26.5 */
	i-dropdown[hidden-via-swipe]{
		transition-duration: 0s;
	}

	/* Ensure menus with [autofocus] inputs sit above the keyboard in iOS. Without this, the keyboard overlaps the menu. Fixed in iOS 26 */
	i-dropdown:has([autofocus]):popover-open{
		--i-dropdown--tr-du: 0s;
	}

	/* Make autocomplete menus more usable on mobiles */
	i-dropdown .ipsAutocompleteMenu{
		position: relative;
		top: auto;
	}
	/* Prevent the menu from closing when the keyboard is active, since a vertical swipe can often close the menu accidentally */
	i-dropdown:has(:is(input:not([type="checkbox"], [type="radio"]), textarea, [contenteditable="true"]):focus){
		overflow: hidden;
	}
}

/* Desktop (dropdown) */
@media (min-width: 500px){
	i-dropdown{
        --i-dropdown--tr-du: .12s;
        --_offset: 6px;
		display: block;
		overflow: visible; /* Required to ensure box-shadow isn't clipped */

		/* Offset and browser gutter */
		padding: var(--_offset) 10px;

		opacity: 0;
		translate: 0 20px;
		transition-property: display, overlay, translate, opacity;
		transition-behavior: allow-discrete;
		transition-timing-function: ease-in;
		transition-duration: var(--i-dropdown--tr-du);		
	}

	/* Anchor positioning */
    @supports (position-area: bottom) and (not (-webkit-hyphens: auto)){
        i-dropdown{
            inset: auto;
			position: absolute;
			position-area: bottom;
            justify-self: anchor-center;
			position-try: flip-block, flip-inline, flip-block flip-inline;
        }
		/* Dropdown menus inside dialogs need this (eg. the Gallery submission form) */
		dialog i-dropdown{
			position: fixed;
		}
    }

    /*  
        Anchor positioning fallback:
        If anchor isn't supported, we position menus using position:absolute
    */
	@supports (-webkit-hyphens: auto) or (not (position-area: bottom)){
		i-dropdown{
			position: absolute;
            top: var(--_anchor-v, 0px);
            left: 0px;
            /*
				This transform ensures the menu stays within the browser window
            	Horizontal: Center the menu and prevent it from overflowing browser
            	Vertical: Pull the menu up if:
					1. There isn't enough space below the menu
					AND
					2. There's enough space above the menu, ensuring it doesn't fall outside the top of the browser
			*/
			transform: translate(
				clamp(0%, var(--_anchor-h) - 50%, 100vw - 100%),
				clamp(
					-100% - var(--_anchor-height),
					max(
						var(--_remaining-height) - 100%,
						100% - var(--_anchor-v)
					) * 999,
					0%
				)
			);
		}

		/* UI #211125, Safari: Closing, transitioned menus in Safari will jump in position if their parent uses position:relative. We can fix this by using position:fixed; for closed menus. Last tested in 26.5 */
		@supports (-webkit-hyphens: auto){
			i-dropdown:not(:popover-open){
				position: fixed;
            	top: var(--_anchor-v-fixed, 0px);
			}
		}

        /* If JS fails, display the menu as a centered popover with a backdrop */
		i-dropdown:not(:defined){
			inset: 0;
			margin: auto;
			position: fixed;
		}
		i-dropdown:not(:defined)::backdrop{
			background: hsl(0 0% 0% / .1);
		}
		i-dropdown:not(:defined) .iDropdown{
			max-height: 80vh;
		}
	}

	/* Safari bug: Dropdowns in container parents jump to different positions while closing. Lets remove the transition completely on those. Last tested in 26.5 */
	@supports (-webkit-hyphens: auto){
		:is(.ipsData, .ipsPageAction, .ipsEntry__meta, .ipsProfileContainer, .cGalleryDialog, #elMessageSidebar) i-dropdown:not(:popover-open){
			transition-duration: 0s;
		}
	}

	i-dropdown:popover-open{
		opacity: 1;
		translate: 0 0px;
		@starting-style{
			&{
				opacity: 0;
				translate: 0 20px;
			}
		}
	}

	@supports not selector(:popover-open){
		/* If popover isn't supported, we position menus using position:fixed */
		/* This allows us to position menus even if they're inside overflow hidden/scroll parents */
		i-dropdown{
			position: fixed;
			top: calc(var(--_anchor-v, 0px) - var(--_anchor-scroll, 0px));
			transition: none;
			/* Display popovers */
			opacity: 1;
			translate: 0;
		}
	}

	/* Hide swipe and dismiss elements on desktop */
	.iDropdownSwipe,
	.iDropdownDismiss{
		display: none;
	}

	/* Dropdown width */
	.iDropdown{
		min-width: 18em;
		max-width: 32em;
	}

	.iDropdown__content{
		max-height: min(600px, 50vh);
	}

}

/* Prevents Chrome 133 from crashing when closing the popover */
@supports (-webkit-app-region: drag) and (not (appearance: base-select)) {
	i-dropdown{
		transition-behavior: normal;
	}
}

.ipsEditor{
	--ipsEditor--mi-he: 300px;
	border: var(--i-input--bo-wi) var(--i-input--bo-st, solid) var(--i-input--bo-co);
  	box-shadow: var(--i-input--bo-sh, none);
	background: var(--i-background_1);
	border-radius: min(var(--i-design-radius), 6px);	
	background-clip: padding-box;
	position: relative;
	transition: border-color .15s;
}

	.ipsEditor:hover {
		border-color: var(--i-color_soft);
	}

	.ipsEditor:focus-within{
		border-color: var(--i-input-active--bo-co);
	}

.ipsFormWrap--comment .ProseMirror,
.ipsRichText--user .ProseMirror{
	font-size: calc(var(--set__i-user-content-font-size, 100) * .01em);
	line-height: 1.8;
}

/* Prevent iOS zoom */
@media (hover:none) and (pointer:coarse){
	.ProseMirror{
		font-size: max(16px, 1em);
	}
	.ipsFormWrap--comment .ProseMirror,
	.ipsRichText--user .ProseMirror{
		font-size: max(16px, var(--set__i-user-content-font-size, 100) * .01em);
	}
}

/* Add a min-height to loading editor */
.ipsLoading[data-role="mainEditorArea"]{
	min-height: var(--ipsEditor--mi-he, 300px);
}

/* Grid is used here to position the toolbar above the textarea */
.ipsEditor__tiptap-wrap {
	display: grid;
	grid-template-rows: auto 1fr;
	min-height: var(--ipsEditor--mi-he, 300px);
}

.tiptap.ProseMirror, .ipsEditor__monaco-root {
	/* Without the z-index, dropdown panels inside the editor are hidden behind the upload area text. */
	z-index: 2;
	padding: 20px;
	min-height: 100px; /* The editor content won't even be visible if the editor isn't wrapped inside the ipsEditorV5 element */
	outline: none;
	width: 100%;
	height: 100%;
}
	.ipsEditor__monaco-root {
		padding: 0;
	}

	/* Code mode editor */
	.ipsEditor__monaco-root .monaco-editor {
		width: 100%;
		height: 100%;
	}

		.ipsCodebox__inner-wrap, .ipsCodebox__inner-wrap > [data-role="reactRoot"], .ipsEditor__tiptap-wrap--codeMode {
			--ipsEditor--mi-he: min(80vh, 500px);
			height: 100%;
		}

	.ipsMenu:has(.ipsEditor, .ipsCodebox__outer-wrap) {
		min-width: min(90vw, 600px);
	}

	:where(.ipsEditor__toolbar){
		/* Prevent tiptap elements from inheriting external font styles */
		color: var(--i-color_root);
		font-size: var(--i-font-size);
		font-weight: normal;
		font-style: normal;
		text-decoration: none;
		letter-spacing: normal;
		text-transform: none;
		text-shadow: none;
	}
	/* Main toolbar */
	.ipsEditor__toolbar--main {
		order: -1; /* Ensure the toolbar is always above the textarea */
		display: flex;
		flex-wrap: wrap;
		gap: 2px;
		position: -webkit-sticky;
		position: sticky;
		top: var(--i-sticky-offset, 0px);
		z-index: 3;
		background: var(--i-box--ba-co);
		color: var(--i-color_root);
		border-bottom: 2px solid var(--i-background_3);
		margin: 0 .4em;
		padding: .4em 0;
		container-type: inline-size;
		container-name: toolbar;

		/* We do this to create a new stacking context. This makes sure that fixed positioning of anchored children (e.g. dropdowns) is effectively RELATIVE, so scrolling and stuff will make those children automatically reposition */
		transform: translate(0);
	}

	/* Icon parents */
	.ipsEditor__toolbar--main > li{
		position: relative; /* Let dropdowns use absolute positioning */
	}

/* All icons/dropdown menu options */
.ipsEditor__toolbar-item {
	display: flex;
	align-items: center;
	border-radius: min(5px, var(--i-design-radius));
	padding: 0 .7em;
	cursor: pointer;
	user-select: none;
	white-space: nowrap; /* Prevent options like "Heading 1" from wrapping */
}

/* Main toolbar icons */
:is(.ipsEditor__toolbar--main, .ipsEditor__toolbar--row) > li > .ipsEditor__toolbar-item{
	min-width: 2.4em;
	min-height: 2.4em;
	justify-content: center;
	gap: .5em;
}

/* Icons */
.ipsEditor__toolbar-item svg{
	width: 1.18em;
	height: 1.18em;
}

/* Move dropdown arrow to end */
.ipsEditor__toolbar-item .fa-caret-down{
	order: 1;
	margin-inline-start: auto;
	opacity: .4;
}

/* Some buttons have an extra child element, used to display the current value, such as Font-Family and Image Alignment. We need to remove it so the flex alignment continues to work */
.ipsEditor__toolbar-item div[data-role="currentValue"]{
	display: contents;
}
/* With the above, we need to restore a gap in the Code language selection */
[data-toolbar-item="codelanguage"] .fa-caret-down{
	margin-inline-start: .4em;
}

 @media (any-hover:hover){
	.ipsEditor__toolbar .ipsEditor__toolbar-item:hover:not(.ipsEditor__toolbar-item--unavailable, .ipsEditor__toolbar-item[disabled], .ipsEditor__toolbar-select-option[data-current="yes"]),
	.ipsColorOptions__option:hover {
		background-color: color-mix(in srgb, currentColor 10%, transparent);
	}
 }


 	/* Active main toolbar items */
	:is(.ipsEditor__toolbar--main, .ipsEditor__toolbar--row) > li > .ipsEditor__toolbar-item--active{
		background-color: color-mix(in srgb, currentColor 25%, transparent);
	}

	/* Active nested dropdown items (Left, Right, Center, etc) */
	.ipsEditor__anchored-panel .ipsEditor__toolbar-item--active{
		background-color: color-mix(in srgb, currentColor 25%, transparent);
	}

	@media (any-hover:hover){
		.ipsEditor__toolbar-item--active:is(:hover, :focus-visible) {
			background-color: color-mix(in srgb, currentColor 35%, transparent);
		}
	}

/* Active items in Select menu (Eg. Paragraph) */
.ipsEditor__toolbar-select-option[data-current="yes"] {
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
}
	/* Make sure inner elements such as <h1> are coloured correctly */
	.ipsEditor__toolbar-select-option[data-current="yes"] *{
		color: inherit;
	}
	/* Active items:hover */
	.ipsEditor__toolbar-select-option[data-current="yes"]:hover {
		background-color: var(--i-primary-light);
	}

/* Hide labels in the Font Family menu, and in the main toolbar */
#editorToolbarPanel_nested_fontFamily .ipsEditor__toolbar-label,
.ipsEditor__toolbar-label:not(.ipsColorOptions__panel *, .ipsEditor__toolbar--nested *) {
	clip-path: inset(50%);
	height: 1px;
	margin: -1px;
	overflow: hidden;
	position: absolute;
	white-space: nowrap;
	width: 1px;
}

/* Dropdown options */
:is(.ipsEditor__toolbar--nested, .ipsEditor__toolbar-select-options) .ipsEditor__toolbar-item {
	flex-grow: 1;
}

/* Select menus */
.ipsEditor__toolbar-select {
	cursor: pointer;
	position: relative;
}

	.ipsEditor__toolbar-select > .ipsEditor__toolbar-select-option {
		display: contents; /* Let the parent element handle alignment */
	}

	/* Ensure dropdown menus sit on top of all other elements */
	.ipsEditor__anchored-panel{
		--i-editor-panel-zi: 10;
	}

	/* Popover dropdowns. Using :where() so that only UA styles are overridden */
	:where(.ipsEditor__anchored-panel[popover]) {
		background: transparent;
		border: none;
		overflow: visible;
	}

	/* Dropdown menu: Format, font-size, etc */
	.ipsEditor__toolbar-select-options, .ipsEditor__toolbar-panel, .ipsEditor__iconpicker-wrap, .ipsEditor__anchored-panel {
		z-index: var(--i-editor-panel-zi);
		position: absolute;
	}
	.ipsEditor__toolbar-select-options, .ipsEditor__toolbar-panel, .ipsEditor__toolbar--nested {
		background: var(--i-dropdown--ba-co);
		color: var(--i-color_root);
		box-shadow: var(--i-dropdown--bo-sh);
		border-radius: var(--i-dropdown--bo-ra);
		max-height: 500px;
		overflow-y: auto;
		padding: 5px;
		min-width: 220px;
	}

	/* Dropdown Menu: Mention */
	.ipsEditor__toolbar-select-options--mentionSuggestions:not(#x) {
		z-index: var(--ips-js-zindex-top, var(--i-editor-panel-zi));
	}

	/* Dropdown menus (Insert), Select menus (Font-size) and colors */
	.ipsEditor__toolbar--nested .ipsEditor__toolbar-item,
	.ipsEditor__toolbar-select-option,
	.ipsColorOptions__option {
		width: 100%;
		border-radius: min(5px, var(--i-design-radius));
		flex: 0 0 auto;
		display: flex;
		align-items: center;
		gap: 1em;
		padding: .5em 1em;
	}

		/* Align dropdown menu icons/labels */
		.ipsEditor__anchored-panel .ipsEditor__toolbar-item i:first-child {
			width: 1em;
		}

		/* Remove margins from "Heading previews" in dropdown menu */
		.ipsEditor__toolbar-select-options :is(h1, h2, h3, h4, h5, h6){
			margin: 0;
		}

	/* Submenus inside dropdown menus: Text align, Font, etc */
	.ipsEditor__toolbar--nested .ipsEditor__anchored-panel{
		position: static !important;
		margin: 5px 0;
		margin-inline-start: 1em;
		border-inline-start: 2px solid color-mix(in hsl, currentColor 20%, transparent);

		/* Remove styles from the Font Family menu */
		box-shadow: none;
		background: none;
		border-radius: 0;
		min-width: 0;
		max-height: none;
	}

	/* Animate the submenus if discrete transitions are supported */
	@supports (transition-behavior: allow-discrete){

		.ipsEditor__toolbar .ipsEditor__toolbar--row[hidden],
		.ipsEditor__toolbar--nested .ipsEditor__anchored-panel[hidden]{
			max-height: 0px;
			overflow: clip;
			opacity: 0;
		}

		.ipsEditor__toolbar .ipsEditor__toolbar--row,
		.ipsEditor__toolbar--nested .ipsEditor__anchored-panel{
			interpolate-size: allow-keywords;
			max-height: 200px;
			transition: display,
						overflow,
						opacity,
						max-height;
			transition-duration: .4s;
			transition-behavior: allow-discrete;
			overflow: auto;
			opacity: 1;
		}

		@starting-style {
			.ipsEditor__toolbar .ipsEditor__toolbar--row,
			.ipsEditor__toolbar--nested .ipsEditor__anchored-panel{
				max-height: 0px;
				overflow: clip;
				opacity: 0;
			}
		}

	}


		.ipsEditor__toolbar--nested .ipsEditor__anchored-panel .ipsEditor__toolbar--nested{
			min-width: 0;
			padding: 0;
			padding-inline-start: 5px;
			box-shadow: none;
			background: none;
			border-radius: 0;
			position: static;
		}

			.ipsEditor__toolbar--nested .ipsEditor__anchored-panel .ipsEditor__toolbar--nested .ipsEditor__toolbar-item{
				padding: .4em 1em;
			}

	.ipsEditor__toolbar-select-options[data-panel-anchor="block"] > .ipsEditor__toolbar-select-option {
		width: 100%;
	}

	/* Extra row of buttons in toolbar (when tables are selected) */
	.ipsEditor__toolbar-item-wrap:has(.ipsEditor__toolbar--row) {
		flex: 1 1 100%;
	}
	.ipsEditor__toolbar--row{
		display: flex;
		gap: 2px;
		background-color: var(--i-background_2);
	}
	/* Hide the above toolbar item if it contains an empty row */
	.ipsEditor__toolbar-item-wrap:has(.ipsEditor__toolbar--row[hidden]){
		display: none;
	}
	.ipsEditor__toolbar--main .ipsEditor__toolbar--row {
		margin-bottom: -0.4em; /* This moves the bottom border of the containing toolbar up */
		padding-block: 0.2em;
	}

[data-tippy-root] {
	z-index: calc(var(--ips-js-zindex-top) - 10) !important;
}

:where(.tiptap .react-renderer) {
	display: contents;
}

/* Node view wrap stuff */
:where(.tiptap .react-renderer > [data-node-view-wrapper]) {
	width: fit-content;
	position: relative;
	display: inline-block;
}

:where(.tiptap .react-renderer.node-ipsBox > [data-node-view-wrapper]) {
	width:100%;
	display: flow-root;
}

/* Selected elements in editor (video, embed, etc) */
.ProseMirror-selectednode,
.tiptap.ProseMirror .react-renderer:not(.ProseMirror-selectednode, .node-codeBlock, .node-ipsBox, .node-blockquote),
.node-ipsEmbed {
	outline-color: var(--i-background_6);
}

.tiptap.ProseMirror .react-renderer:hover:not(.ProseMirror-selectednode, .node-codeBlock, .node-ipsBox, .node-blockquote) > [data-node-view-wrapper]:hover,
:is(.ProseMirror-selectednode,
.node-ipsEmbed) > [data-node-view-wrapper] {
	outline-width: 2px;
	outline-style: solid;
	outline-color: inherit;
}

.tiptap [data-node-view-wrapper][data-is-resizing] {
	outline: 2px solid var(--i-primary) !important;
}

.tiptap [data-node-view-wrapper][data-attachment-type="file"]:not(.ProseMirror-selectednode > *) {
	outline: none;
}

/* Since the inline/block class is applied to the wrapper, we need to adjust the file display */
.tiptap [data-attachment-type="file"]:is(.ipsAttachLink_inline, .ipsAttachLink_block) {
	padding: 0;
}
.tiptap [data-attachment-type="file"]:is(.ipsAttachLink_inline, .ipsAttachLink_block) > .ipsAttachLink {
	margin: 0;
}
.tiptap [data-attachment-type="file"].ipsAttachLink_block > .ipsAttachLink {
	padding: 0.8em 1.2em;
}

:is(.ipsRichTextBox, .ipsQuote_contents > *) > .node-codeBlock > pre {
	margin-block: 0;
}

.node-ipsEmbed:not(.ProseMirror-selectednode) {
	outline-color: var(--i-background_4);
}
.ProseMirror-selectednode {
	outline-color: var(--i-primary);
}
.ProseMirror-selectednode:not(.react-renderer) {
	outline: 2px solid var(--i-primary);
}

/* Ensure overflowing content is visible, otherwise the "insert element before/after" icons are cropped */
.tiptap .react-renderer:not(.react-renderer--no-indicators) :is(.ipsCode.ipsCode--nodeview-wrapper, .ipsQuote) {
	overflow: visible;
}
.tiptap .react-renderer:not(.react-renderer--no-indicators) .ipsCode--nodeview-wrapper {
	padding: 0;
}
/* But the above causes long code strings to break outside code boxes, so we need to fix that */
.tiptap .ipsCode--nodeview-wrapper > [data-node-view-content] {
	overflow: auto;
	display: block;
	padding-inline: 1.3em;
	padding-block-end: 1.3em;
}

.react-renderer :is(iframe) {
	border-width: 0 !important;
}

.tiptap :is(p,ol,ul).ProseMirror-selectednode {
	outline-width:0px;
}

/* Add a space after quotes, boxes and embeds */
.tiptap :is(.node-blockquote, .node-ipsBox, .node-ipsEmbed) {
	margin-bottom: 1em;
}

.ipsEditor__create-sibling {
	--i-indicator-size: 20px;
	--i-hz-offset: 1em;
	display: flex;
	justify-content: center;
	align-items: center;
	position: absolute;
	/* Ensure sibling icons aren't overlapped by external elements */
	z-index: 4;
	height: var(--i-indicator-size);
	width: var(--i-indicator-size);
	font-size: .6em;
	color: var(--i-primary-contrast);
	background: var(--i-primary);
	border-radius: 50%;
	margin: -1px; /* The -1px centers the button along the 2px node outline */
}

/* Show create sibling icons when active or hovered. We use opacity to make hovering easier */
.ipsEditor__create-sibling-wrapper{
	opacity: 0;
}
:is([data-node-view-wrapper]:hover, .ipsEditor__table-wrapper:hover, .ProseMirror-selectednode) .ipsEditor__create-sibling-wrapper{
	opacity: 1;
}

	.tiptap [data-is-resizing] .ipsEditor__node-options,
	.ipsEditor__nodewrap--narrow .ipsEditor__node-options--media:not(.ProseMirror-selectednode > [data-node-view-wrapper] > *) {
		display: none !important;
	}

/* Tables */
.ipsEditor__table-wrapper{
	position: relative;
}

		/* Buttons at top right of embeds/images/videos */
		.ipsEditor__node-options > .ipsEditor__toolbar-item{
			color: var(--i-primary-contrast);
			background: var(--i-primary);
			padding: .7em;
			width: auto;
			height: auto;
		}

		.ipsEditor__node-options > .ipsEditor__toolbar-item:is(:hover, :focus-visible, .ipsEditor__toolbar-item--active), .ipsEditor__create-sibling:hover {
			background: var(--i-primary-light);
		}

		/* Semi-transparent settings icon on images */
		.ipsEditor__node-options--media > .ipsEditor__toolbar-item{
			background: hsl(0 0% 0% / .4);
			color: #fff;
			backdrop-filter: blur(5px);
		}
		.ipsEditor__node-options--media > .ipsEditor__toolbar-item:is(:hover, :focus-visible, .ipsEditor__toolbar-item--active){
			background: hsl(0 0% 0% / .6);
		}

	.ipsEditor__create-sibling--before {
		left: var(--i-hz-offset);
		top: calc(var(--i-indicator-size) * -0.5);
		transform: rotate(-90deg);
		transform-origin: center;
	}
	.ipsEditor__create-sibling--after {
		inset-inline-end: var(--i-hz-offset);
		bottom: calc(var(--i-indicator-size) * -0.5);
		transform: rotate(90deg);
		transform-origin: center;
	}

	[data-attachment-type="file"] {
		display: inline-block;
	}
	[data-attachment-type="file"] a {
		cursor: default;
	}

.ipsEditor__node-hover-overlay {
	position: absolute;
	inset: 0;
}

/*
	----------------
	- Link panel
	----------------
*/
.ipsEditor__toolbar-panel-row {
	display: flex;
	align-items: center;
	gap: 1em;
}
	/* Without this, the inputs width collapses */
	.ipsEditor__toolbar-panel-row .ipsInput{
		width: revert;
		min-width: min(60vw, 200px);
	}

/*
	----------------
	- Global messages
	----------------
*/

/* Sticky messages at bottom of editor */
[data-role="editor-messages-container"] {
	position: sticky;
	bottom: 0.25em;
	z-index: 2; /* Need this so the messages (e.g. autosave message) appear above the content inside the editor */
	font-weight: normal;
	font-size: var(--i-font-size);
}

/* Mobile selection toolbar */
@media(max-width: 979px) {
	[data-role="editor-messages-container"] {
		bottom: calc(var(--i-mobileFooter--he) + 0.25em);
	}
}

	.ipsEditor__global-messages {
		display: flex;
		flex-direction: column;
		gap: 0.5em;
		padding: 0.5em;
	}

		.ipsEditor__global-message {
			align-items: center;
			-webkit-backdrop-filter: blur(8px);
			backdrop-filter: blur(8px);
			background: color-mix(in srgb, var(--i-background_dark) 80%, transparent);
			color: #fff;
			border-radius: min(var(--i-design-radius), 5px);
			display: flex;
			font-weight: 500;
			justify-content: space-between;
			padding: 0.5em 0.7em;
		}

		.ipsEditor__global-message :is(.far, .fa-regular, .fa-solid, .fas) {
			font-size: 1.2em;
		}
		.ipsEditor__autosave-clear {
			text-decoration: underline;
			color: inherit;
		}

/*
	----------------
	- Box Support
	----------------
*/
.ipsRichTextBox__nodeview-wrap summary.ipsRichTextBox__title {
	cursor: text;
}

/* Collapsed boxes - in-editor-preview. This works differently from simple details/summary elements */
.ipsRichTextBox__node-view-wrapper--collapsed > [data-node-view-content-react] > :not(.ipsRichTextBox__title:first-child) {
	/*display: none;*/
	/* display: none messes with the positioning in the editor because it makes the element unselectable */
	height: 0 !important;
	width: 0 !important;
	margin: 0 !important;
	padding: 0 !important;
	border: none !important;
	overflow: hidden !important;
}

.ipsRichTextBox__node-view-wrapper--collapsed > [data-node-view-content-react] > .ipsRichTextBox__title:first-child {
	margin-block-end: 0;
	border-bottom: none;
	padding-block-end:0;
}

:root {
	--i-ri-box-title-placeholder: "Add a box title...";
}
.ipsRichTextBox__nodeview-wrap .ipsRichTextBox__title--empty:not(.ipsRichTextBox__title--selection-within)::before {
	position: absolute;
	content: var(--i-ri-box-title-placeholder);
	opacity: 0.35;
	cursor: text;
	transition: opacity 0.2s ease;
	z-index: -1;
}
.ipsRichTextBox__nodeview-wrap .ipsRichTextBox__title--empty:not(.ipsRichTextBox__title--selection-within):hover::before {
	opacity: 0.6;
}

/* Dropdown menu: Color options */
	.ipsColorOptions__option {
		text-wrap: nowrap;
	}

		.ipsColorOptions__option::before{
			content: "";
			background: var(--i-richtext-background-color);
			width: 1.4em;
			height: 1.4em;
			flex: 0 0 auto;
			border-radius: 4px;
		}

		.ipsColorOptions__option[data-i-background-color^="theme_"]::before {
			border-color: color-mix(in srgb, var(--i-richtext-background-color) 30%, var(--i-color_root) 15%, transparent);
			border-width: 1px;
			border-style: solid;
		}

/* Show no background for the "No highlighting" option */
#editorToolbarPanel_nested_highlight [data-i-background-color="root"]{
	--i-richtext-background-color: var(--i-background_1);
}

.ipsEditor__toolbar-item--font-color:not([data-i-color="root"]){
	color: var(--i-richtext-color);
	background: color-mix(in srgb, var(--i-richtext-color) 20%, transparent);
}

.ipsEditor__toolbar-item--box-color:not(#x) {
	border-bottom: 5px solid color-mix(in srgb, var(--i-richtext-color, var(--i-background_2)) 85%, var(--i-color_root));
	padding-top: 5px;
	color: inherit;
	background-color: color-mix(in srgb, var(--i-richtext-color, var(--i-background_2)) 20%, var(--i-background_2));
}
	.ipsEditor__toolbar-item--box-color:not(#x)[data-i-color*="theme_"] {
		border-color: color-mix(in srgb, var(--i-richtext-color) 85%, var(--i-color_root));
		background-color: var(--i-richtext-color);
	}


/* Giphy Panel */
.ipsEditor__giphy-panel {
	display: flex;
	flex-direction: column;
	max-height: 400px;
	width: 400px;
	max-width: 90vw;
	padding: 0;
}

	.ipsEditor__giphy-panel > form {
		display: contents;
	}

	/* Search */
	.ipsEditor__giphy-search {
		margin: 8px;
		flex: 0 0 auto;
		width: calc(100% - 16px) !important;
	}

	.ipsEditor__giphy-attribution {
		padding: 0.5em;
		position: absolute;
		inset-inline-end: 0;
		inset-block-end: 0;
		font-weight: 600;
		background-color: var(--i-background_dark);
		color: var(--i-color_background-dark-contrast);
		font-size: .9em;
		border-top-left-radius: 0.5em;
		box-shadow: var(--i-dropdown--bo-sh);
	}
	.ipsEditor__giphy-attribution:dir(rtl) {
		border-top-right-radius: 0.5em;
		border-top-left-radius: 0;
	}
	.ipsEditor__giphy-attribution > img {
		--i-logo-margin: 0.13lh;
		height: calc(1lh - 2 * var(--i-logo-margin));
		margin-top: var(--i-logo-margin);
		margin-inline: 0.6ch;
	}

	.ipsEditor__giphy-results {
		overflow-y: auto;
		flex-grow: 1;
		min-height: 200px;
		padding-inline: 8px;

		--i-giphy-ratio: 16/9;
		display: flex;
		align-items: flex-start;
		flex-wrap: wrap;
		gap: 7px;
	}

		.ipsEditor__giphy-results-page{
			display: contents;
		}

		.ipsEditor__giphy-results-page button{
			aspect-ratio: var(--i-giphy-ratio);
			flex-grow: calc(10 * (var(--i-giphy-ratio)));
			flex-shrink: 1;
			flex-basis: calc(var(--i-giphy-ratio) * 90px);
			background: var(--i-background_3);
			padding: 0;
		}

			.ipsEditor__giphy-results-page img{
				aspect-ratio: var(--i-giphy-ratio);
				width: 100%;
			}

.ipsEditor__giphy-results h3 {
	display: block;
	align-self: center;
	flex-basis: 100%;
	text-align: center;
}

/* Restrict width of embedded content (iframes, etc) */
.tiptap .node-ipsEmbed, .tiptap [data-node-view-wrapper]{
	max-width: 100%;
}

/* Set custom widths for embedded content */
.tiptap .node-ipsEmbed:not([data-embed-type="og"]) > [data-node-view-wrapper]{
	width: min(var(--i-media-width, 100%), var(--i-embed-max-width, 500px));
}

.node-ipsEmbed:is([data-embed-type="og"]) [data-node-view-wrapper] {
	border-radius: min(var(--i-design-radius), 6px);
}

.node-ipsEmbed:is([data-embed-type="og"]) [data-node-view-wrapper] [data-role="embed-node-view-content-wrap"] > :not(a, .ipsEmbeddedLink) {
	max-width:100%;
	border-radius: min(var(--i-design-radius), 6px);
	overflow: hidden;
}

	.node-ipsEmbed:not(.ProseMirror-selectednode):is([data-embed-type="og"]) [data-node-view-wrapper] {
		outline-width:0;
	}

.node-ipsEmbed [data-node-view-wrapper] > div > * {
	margin: 0 !important;
}

/* Disabled buttons */
.ipsEditor__toolbar-item--unavailable, .ipsEditor__toolbar-item[disabled] {
	pointer-events: none;
	opacity: .2;
}
.ipsEditor__toolbar-item--no_pointer_events {
	pointer-events: none;
}

/* The codeblock dropdown */
.ipsCode--nodeview-wrapper > .ipsEditor__toolbar {
	font-family: var(--i-font-family);
	cursor: default;
	margin-bottom: 1em;
	padding-inline: 1.3em;
	padding-block-start: 1.3em;
}

.ipsEditor__toolbar--nodeview:not(#x) {
	flex-wrap: nowrap;
	position:relative;
}
.ipsEditor__toolbar--nodeview:not(#x) > * {
	min-width: revert !important;
}

.ipsEditor__toolbar--nodeview .ipsEditor__toolbar-item {
	cursor: pointer;
}
.ipsEditor__toolbar--nodeview .ipsEditor__toolbar-panel {
	cursor: default;
}
/* The "code format" dropdown menu at the top of code blocks in the editor */
.ipsCode [data-role="toolbar"] > .ipsEditor__toolbar-item {
	display: block;
	width: fit-content;
	margin-bottom: 1em;
	position: sticky;
	left: 0;
	background: color-mix(in srgb, currentColor 15%, transparent);
	padding: 0.5em 0.9em;
	font-size: 0.7em;
	border-radius: min(var(--i-design-radius), 5px);
	font-family: var(--i-font-family);
	font-weight: 600;
	color: var(--i-color_soft);
	outline-width: 0;
}

/* The box tools */
[data-node-view-wrapper] .ipsEditor__node-options {
	align-items: center;
	display: flex;
	gap: .25em;
	position: absolute;
	top: 1em;
	inset-inline-end: 1em;
	transition: inset-inline-end 0.25s, top 0.25s;
}

[data-node-view-wrapper].ipsEditor__nodewrap--narrow .ipsEditor__node-options--media {
	inset-inline-end: calc( -1em - 30px);
	top: 0;
}

.ipsEditor__tiptap-wrap .ipsRichText summary::after,
.ipsEditor__tiptap-wrap .ipsRichTextBox__title:not(.ipsRichTextBox--alwaysopen > .ipsRichTextBox__title)::after {
	display: none;
}

[data-node-view-content] > .ipsRichTextBox {
	overflow: visible;
}

.ipsEditor__node-options > button {
	display: inline-grid;
	place-content: center;
	width: 2em;
	height: 2em;
	border-radius: 5px;
	padding: 0;
}

/* "Remove embed" icon is made up of 2 icons. Ensure the alignment is correct in Safari */
.ipsEditor__toolbar-item--escapeembed > * {
	grid-area: 1/1;
	margin: auto;
}

/* Ensure these sit on top of .ipsRichTextBox */
.ipsEditor__node-options > button,
.ipsRichTextBox__marker{
	position: relative;
	z-index: 1;
}

/* Clicking mentions does nothing */
.tiptap [data-mentionid] {
	cursor: default;
}

/* Add a larger gap and prevent usernames from wrapping in @mentions menu */
.ipsEditor__toolbar-select-options--mentionSuggestions .ipsEditor__toolbar-select-option{
	gap: 1em;
}
	.ipsEditor__toolbar-select-options--mentionSuggestions .ipsEditor__toolbar-select-option .ipsUserPhoto{
		width: 34px;
	}

/* Active item in Mention dropdown */
.ipsEditor__toolbar-select-options--mentionSuggestions:not(:hover) .ipsEditor__toolbar-select-option--active,
.ipsEditor__toolbar-select-options--mentionSuggestions button:hover{
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
}


/* Quotes are expanded */
.tiptap .ipsQuote,
.tiptap .ipsQuote_contents {
	min-height: revert;
	display: flow-root;
}


.tiptap img.ProseMirror-separator {
	width: revert !important;
}

.ipsEditor__link-options {
	max-height: none;
	overflow-y: hidden;
}

.ipsEditor__toolbar-panel--link {
	gap: 5px;
	display: grid;
	width: min(80vw, 350px);
	grid-template-columns: auto 3em;
}

.ipsEditor__toolbar-panel--link .ipsEditor__toolbar-panel-row {
	display: grid;
	grid-template-columns: 5ch 1fr;
	grid-column: 1;
}

.ipsEditor__toolbar-panel--link label{
	text-align: end;
	font-weight: 600;
}

.ipsEditor__toolbar-panel--link [data-role="unlink"] {
	grid-row-start: 1;
	grid-column: 2;
}

:root {
	--i-editor-panel-zi: 1; /* z-index that panels in the editor use */
}


.ipsEditor__toolbar-panel--link [data-role='unlink'].ipsEditor__remove-link--fullheight {
	grid-row-end: 3;
}


.ipsEditor__toolbar-panel--link [data-role="convert_to_embed"] {
	grid-row-start: 2;
	grid-column: 2;
}

.ipsEditor__link-panel-status {
	max-height: 1lh;
	grid-row: span 1;
	grid-column: span 2;
	text-align: end;
	font-size: 0.75em;
	padding: 0 calc(0.7em / 0.75);
	color: var(--i-color_positive);
}
.ipsEditor__link-panel-status [data-role=content] {
	transition: opacity 0.1s ease-in;
}
.ipsEditor__link-panel-status--processing [data-role=content] {
	opacity: 0;
}

.ipsEditor__close-link-panel {
	display: none;
}

/* On mobile, we show a check button */
@media(max-width: 767px) {
	.ipsEditor__close-link-panel {
		margin-top: 1em;
		display: flex;
		grid-row: span 1;
		grid-column: span 2;
	}

	.ipsEditor__link-panel-status {
		display: none;
	}
}


.ipsEditor__toolbar-panel--embed {
	max-width: 210px;
	grid-template-columns: 1fr;
	grid-auto-flow: row;
	position: revert;
	width: max-content;
	gap: 5px;
}

.ipsEditor__toolbar-panel--embed > * {
	gap: 5px;
	display: grid;
	grid-auto-flow: column;
	align-items: center;
}

.ipsEditor__toolbar-panel--embed > * > label {
	width: max-content;
	white-space: nowrap;
}

.ipsEditor__toolbar-panel--embed > * > .ipsInput {
	width: revert;
	flex-grow: 1;
}


/* Inline styles for the page builder */
.ipsEditor__toolbar--hovering:not(#x) {
	width: 100%;
	margin-inline: 0;
	bottom: 20px;
	top: revert;
}

[data-role="toollist-wrap"] {
	inset-inline-end: calc(100% + var(--i-hz-offset, 20px));
}

.cWidgetContainer__portal-menu {
	padding: 1em;
}
[data-role="toollist-wrap"], .cWidgetContainer__portal-menu {
	--i-hz-offset: 20px;
	display: flex;
	flex-direction: column;
	gap: 1em;
}

[data-role="toollist-wrap"], .ipsEditor__toolbar--hovering:not(#x), .cWidgetContainer__portal-menu {
	position: absolute;
	z-index: calc(var(--ips-js-zindex-top) - 10); /* -10 so that the tooltips appear above the menu */
}

[data-role="toollist-wrap"] > [data-ipseditor-toollist], [data-role="toollist-wrap"] > .ipsEditor__global-messages > .ipsEditor__global-message, .ipsEditor__toolbar--hovering:not(#x), .cWidgetContainer__portal-menu {
	outline: 2px solid var(--i-primary);
	border-radius: var(--i-box--bo-ra);
	background: var(--i-background_3);
}

[data-resize-active] .cWidgetContainer__portal-menu {
	opacity: 0;
}

[data-mouse-down-drag-active] {
	touch-action: none;
}

[data-mouse-down-drag-active] * {
	cursor: var(--i-drag-cursor, move) !important;
}

/* Firefox: Prevent videos from playing when dragging to resize */
.tiptap [data-attachment-type="video"][data-is-resizing] video{
	pointer-events: none;
}

.cWidgetContainer__portal-menu [data-action='cancel'] {
	background-color: var(--i-color_negative);
	color: var(--i-primary-contrast);
}

[data-role="toollist-wrap"] > .ipsEditor__global-messages {
	padding: 0;
	order: -1;
}
[data-role="toollist-wrap"] .ipsComposeArea_dropZone {
	margin: 0 !important;
}

.tiptap [data-drag-handle] {
	cursor: move;
}

.tiptap [data-drag-handle]:is([data-is-resizing]) {
	cursor: inherit;
}

/* Ensure videos can be resized without playing in Firefox */
[data-is-resizing] *{
	pointer-events: none;
}

/* The width options for images and attachments */
.ipsEditor__toolbar-item--imagewidth {
	width: max-content;
}

.ipsEditor__width-form {
	display: grid;
	min-width: 220px;
	gap: 1em;
	padding: 0.5em;
	grid-auto-flow: row;
}
@container(max-width: 767px) {
	.ipsEditor__width-form {
		width: 80cqw;
	}
}

.ipsEditor__width-form > div {
	display: flex;
	flex-direction: row;
	justify-content: stretch;
	align-items: baseline;
}

.ipsEditor__width-form > div > * {
	flex: 1 1 fit-content;
}
.ipsEditor__width-form [data-role="status-indicator"] {
	position: relative;
	display: flex;
	align-items: flex-end;
	flex-direction: column;
}
.ipsEditor__width-form [data-role="status-indicator"] > .ipsLoading:not(#x)::before {
	inset-inline-end: 0;
	height: 1em;
	width: 1em;
	font-size: revert;
}
.ipsEditor__width-form [data-role="status-indicator"] .fa-solid.fa-check {
	position: absolute;
	color: var(--i-color_positive);
	font-size: 0.75em;
	bottom: -0.5lh;
}

.ipsEditor__width-form > [data-role="custom-width-wrap"] {
	position: relative;
}
.ipsEditor__width-form > [data-role="custom-width-wrap"]::after {
	position: absolute;
	inset-inline-end: 35px;
	display: block;
	inset-block-end: 0.7em;
	content: 'px';
	color: var(--i-color_soft);
}

/* Right border to indicate the snap */
.tiptap :where([data-is-resizing]).ipsRichText__align--width-fullwidth::after {
	position: absolute;
	content: "";
	opacity: 0;
	right: 0;
	top: 0;
	height: 100%;
	background-color: var(--i-color_primary);
	transition: opacity 0.1s ease 10ms;
	width: 5px;
}
.tiptap .ipsRichText__align--width-fullwidth-snap::after {
	display: block;
	opacity: 0.7;
}

.tiptap .ipsRichText__align--width-fullwidth-snap.ipsRichText__align--width-fullwidth-snap-right::after {
	left: 0;
	right: revert;
}

.ipsRichText :is(.ipsRichText__align--width-custom, .ipsRichText__align--width-fullwidth)[data-node-view-wrapper] img {
	width: 100%;
	display: inline-block;
}
.tiptap .ipsRichText__align--inline[data-node-view-wrapper] > .ipsEditor__create-sibling-wrapper {
	display: none;
}
.tiptap .ipsEditor__media-resize-handle {
	display: block;
	position: absolute;
	bottom: -3px;
	right: -3px;
	height: 8px;
	width: 8px;
	outline: 1px solid var(--i-primary-contrast);
	background: var(--i-primary);
	cursor: nwse-resize;
}
	.tiptap .ipsEditor__media-resize-handle--nesw {
		cursor: nesw-resize;
		right: revert;
		left: -3px;
	}

/* Text align can break the inline toolbars and menus */
.tiptap :is(.ipsEditor__node-options--media, .ipsEditor__toolbar, .ipsEditor__toolbar-panel, .ipsEditor__toolbar-item) {
	text-align: start;
}

/* MEDIA Embeds use their own variable for default width and max width */
/*.tiptap .node-ipsEmbed:is([data-embed-type="video"], [data-embed-type="photo"], [data-embed-type="brightcove"]), */
.tiptap .node-ipsEmbed:is([data-embed-type="video"], [data-embed-type="photo"], [data-embed-type="brightcove"]) > [data-node-view-wrapper] {
	width: var(--i-media-width, 100%);
	max-width: var(--i-embed-media-max-width, 100%);
}

/* Embed alignment */
[data-role="embed-node-view-content-wrap"] {
	display: contents;
}

.tiptap .node-ipsEmbed[data-alignment] {
	display: flex;
}

.tiptap .node-ipsEmbed[data-alignment="center"] {
	justify-content: center;
}
.tiptap .node-ipsEmbed[data-alignment="end"] {
	justify-content: end;
}

.tiptap .node-ipsEmbed[data-alignment] .ipsEmbedded__wrap > *:not(#x) {
	margin-block: 0;
}

/* When page editor is active, editors should be hidden */
.cWidgetsManaging .ipsWidget__content--wrap :is(.ipsEditor, [data-ipseditorv5], .tiptap, .ipsEditor__tiptap-wrap, .ipsEditor__toolbar):not(#x, .ipsWidget__content--wrap--editing *) {
	z-index: 0;
	pointer-events: none;
}
.cWidgetsManaging .ipsWidget__content--wrap :is([data-role="mainEditorArea"].ipsLoading):not(#x, .ipsWidget__content--wrap--editing *)::before {
	display: none;
}

/* Table Resize UI */
.resize-cursor {
	/* not 100% sure why but the official Tiptap demo includes cursor defined twice like this so we're rolling with it*/
	cursor: ew-resize;
	cursor: col-resize;
}

.column-resize-handle {
	background-color: var(--i-primary);
	bottom: calc(-2 * var(--i-ta--bo-wi));
	position: absolute;
	right: calc(-2 * var(--i-ta--bo-wi));
	pointer-events: none;
	top: 0;
	width: clamp(3px, calc(4 * var(--i-ta--bo-wi)), 8px );
	z-index:1; /* THe th/td following this element may overlap it */
}

.ipsEditor__table-wrapper {
	position: relative;
	width: min-content;
	max-width:100%;
}

.ipsEditor__table-wrapper.ProseMirror-selectednode {
	outline-offset: 3px;
	max-width: 100%;
}

.ipsEditor__table-wrapper > .tableWrapper {
	outline: none !important;
}

/* This is done with a psuedo element to not interrupt the existing styles and colors */
.tiptap .ipsEditor__table-wrapper .selectedCell {
	position: relative;
}
.tiptap .ipsEditor__table-wrapper .selectedCell::after {
	content: "";
	position: absolute;
	inset: 0;
	display: block;
	z-index: 1;
	background-color: oklch(from var(--i-color_primary) l c h / 0.1);
}

/* Space apart consecutive node content. There is a corresponding rule in 3-richtext.css to apply this style to the content outside the editor */
:is(.node-ipsEmbed, .node-blockquote, .node-codeBlock) + :is(.node-blockquote, .node-codeBlock) > :is(.ipsCode, .ipsQuote),
:is(.node-ipsEmbed, .node-blockquote, .node-codeBlock) + :is(.node-ipsEmbed) {
	margin-top: 1em;
}


/* ! Drag Handles */
.ipsEditor__node-drag-handle {
	position: absolute;
	cursor: move;
}

.ipsEditor__node-drag-handle:not(.ipsEditor__node-options *) {
	inset-inline-end: 1em;
	inset-block-start: 1em;
}

/* Firefox doesn't fire the drag event if the ::before pseudoelement (fa icon) is dragged, so this element sits inside the drag handle over top the icon. */
.ipsEditor__node-drag-handle-overlay {
	inset: 0;
	position: absolute;
	display: inline-block;
}

/* Latex equations inside the editor */
i-latex-nodeview {
	display: inline-block;
}

i-latex-nodeview [data-latex-source] {
	background: var(--i-background_3);
	padding: .2em .5em;
	border-radius: 4px;
	font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, 'DejaVu Sans Mono', monospace;
	font-weight: normal;
}

i-latex-nodeview > i-latex:not(.iLatex--no-decoration) {
	outline: 1px solid var(--i-primary);
	padding: 3px;
	border-radius: 3px;
	cursor: pointer;
}

.ipsEditor__drop-cursor {
	z-index: calc(var(--ips-js-zindex-top) + 50) !important;
	color: red !important;
	opacity: 0.5;
}

/* Engagement: styles for various features that generall fall under user engagement */
/* ======================================================== */
/* LIKE & REP BUTTONS */

/* Ensure the hovered reaction list is positioned correctly when "total reputation count" is displayed */
.ipsReact_types{
	position: relative;
}

.ipsReact {
	--_react-size: 34px;
	--_icon-size: calc(var(--_react-size) * .8);
	--_gap: 5px;
	position: relative;
	display: flex;
	align-items: center;
	font-size: var(--i-font-size_-2);
	z-index: 1;
	height: var(--_react-size);
}

.ipsReact :where(a){
	color: inherit;
	text-decoration: none;
}

.ipsReact img{
	object-fit: contain;
}

.ipsReact_reaction{
	-webkit-tap-highlight-color: transparent;
}

.ipsReact_reaction img {
	width: var(--_icon-size);
	height: var(--_icon-size);
	display: block;
}

.ipsReact_button {
	display: block;
	position: relative;
	transition: .2s all ease-in-out;
	filter: grayscale(100%) opacity(60%);
}

	.ipsReact_button.ipsReact_reacted,
	body.ipsApp_noTouch .ipsReact_types:hover .ipsReact_button,
	body:not(.ipsApp_noTouch) .ipsReact_types.ipsReact_types_active .ipsReact_button {
		filter: none;
	}

.ipsReact_types ul {
	position: absolute;	
	background: var(--i-background_1);	
	display: flex;
	align-items: center;
	gap: var(--_gap);
	pointer-events: none;
	border-radius: 100px;
}

@media (max-width: 767px){
	.ipsReact_types ul{
		bottom: 100%;
		flex-direction: column;
		transform-origin: 50% 100%;
	}
}

@media (min-width: 768px){
	.ipsReact_types ul{
		inset-inline-end: calc(100% - 1px); /* Cater for sub-pixel rounding. If there was a tiny gap, the mouseleave event was triggered, closing the menu */
		transform-origin: right center;
	}
	:where([dir="rtl"]) .ipsReact_types ul{
		transform-origin: left center;
	}
}

	.ipsReact .ipsReact_types ul.ipsReact_hover {
		pointer-events: auto;
		animation: reaction-hover 0.3s ease-in-out forwards;
	}

	.ipsReact .ipsReact_types ul.ipsReact_hoverOut {
		animation: reaction-hover-out 0.2s ease-in-out 0.4s forwards;
	}

	/* Create the pseudo gap which separates the animated list with the solo icon */
	.ipsReact_types ul::after{
		content: '';
	}

/* Tooltip */
.ipsReact_name {
	display: none;
}

.ipsReact_reaction{
	display: grid;
	place-content: center;
	position: relative;
	height: var(--_react-size);
	width: var(--_react-size);
}

a.ipsReact_reaction::after {
	content: '';
	position: absolute;
	top: 50%;
	left: 50%;
	margin-top: -75%;
	margin-left: -75%;
	width: 150%;
	height: 150%;
	border-radius: 50%;
	pointer-events: none;
	border: 2px solid currentColor;
	opacity: 0;
}

	a.ipsReact_reaction.ipsReact_active::after {
		animation: reaction-click-ring 0.8s ease-out forwards;
	}

	a.ipsReact_reaction.ipsReact_active img {
		animation: reaction-click 0.6s ease-out forwards;
	}	

.ipsReact_unreact {
	background: var(--i-background_dark);
	color: #fff !important;
	width: 20px;
	height: 20px;
	border-radius: 50%;
	font-size: 14px;
	font-family: 'Arial', sans-serif;
	display: grid;
	place-content: center;
	position: absolute;
	top: -10px;
	inset-inline-end: -6px;
}

.ipsReact_unreact[style*="inline"]{
	display: grid !important;
}

/* Reaction button */
.ipsReact_blurb:not(.ipsHide) + .ipsReact_types {
	border-inline-start: 1px solid var(--i-background_3);
	padding-inline-start: 1em;
	margin-inline-start: 1em;
	position: relative;
}

/* Nudge reaction button in slightly on small devices, so it's not too close to the edge */
@media (max-width: 600px){
	.ipsReact_blurb:not(.ipsHide) + .ipsReact_types{
		margin-inline-end: 1em;
	}
}

.ipsReact_reactions {
	display: flex;
	justify-content: flex-end;
	align-items: center;
	flex-wrap: wrap;
	gap: 2px 7px;
}

.ipsReact_reactCount {
	display: flex;
	font-weight: 500;
}

	.ipsReact_reactCount > a,
	.ipsReact_reactCount > span {
		display: flex;
		align-items: center;
		color: var(--i-color_hard);
		padding: 4px;
		border: 1px solid var(--i-background_4);
		background: var(--i-background_1);
		border-radius: 50px;
	}

		.ipsReact_reactCount > a:hover {
			border-color: var(--i-background_6);
			outline: 4px solid var(--i-background_3);
		}

	.ipsReact_reactCount img {
		width: 20px;
		height: 20px;
	}

		.ipsReact_reactCount > span > span:last-child,
		.ipsReact_reactCount > a > span:last-child {
			font-size: var(--i-font-size_-2);
			padding: 0 .8em;
		}

.ipsReact_reactCountOnly {
	padding: 0 7px;
	font-weight: bold;
	line-height: 24px;
	border-radius: 2px;
	font-size: var(--i-font-size_-2);
	display: inline-block;
}

@media screen and (max-width: 767px) {
	.ipsReact_button .ipsReact_reaction::after,
	.ipsReact_overview{
		display: none;
	}
}

.ipsReact_reactCountOnly_mini {
	line-height: 18px;
	font-size: max(10px, .7em);
}

.ipsReactOverview {
	text-align: center;
}

/* Hide reaction container if it's empty */
.ipsReactOverview:not(:has(*)){ display: none }
@supports not selector(a:has(b)){
	.ipsReactOverview:-moz-only-whitespace{ display: none }
}

.ipsReactOverview ul {
	display: flex;
	align-items: center;
	justify-content: center; /* Featured comments at the top of topics */
	gap: .3em;
}

	.ipsReactOverview ul + span{
		vertical-align: middle;
	}

	.ipsReactOverview ul img {
		max-height: 1.8em;
		width: auto;
	}

		.ipsReactOverview_small ul img {
			max-height: 1.6em;
		}

.ipsReactOverview p {
	display: block;
    margin-top: .5em;
    font-size: var(--i-font-size_-2);
    text-transform: uppercase;
    opacity: 0.5;
	font-weight: 500;
}

/* REACTION ANIMATION DEFINITIONS */
@keyframes reaction-click-ring {
	0% {
		opacity: 1;
		transform: scale3d(0.4, 0.4, 1);
	}
	40% {
		transform: scale3d(1, 1, 1);
		opacity: .8;
	}
	100% {
		opacity: 0;
		transform: scale3d(1.2, 1.2, 1);
	}
}

@keyframes reaction-click {
	0% {
		opacity: 0;
		transform: scale3d(0.1, 0.1, 1);
	}
	30% {
		transform: scale3d(1.3, 1.3, 1);
		opacity: 1;
	}
	100% {
		transform: scale3d(1, 1, 1);
	}
}

@keyframes reaction-hover {
	0% {
		opacity: 0;
		transform: scale3d(0, 1, 1);
	}
	50% {
		transform: scale3d(1.2, 1, 1);
		opacity: 1;
	}
	100% {
		transform: scale3d(1, 1, 1);
	}
}

@keyframes reaction-hover-out {
	0% {
		opacity: 1;
		transform: scale3d(1, 1, 1);
	}
	60% {
		transform: scale3d(0, 0, 1);
	}
	100% {
		opacity: 0;
	}
}

.ipsReputation_count {
	background: #fff;
	display: inline-block;
	position: relative;
	font-size: var(--i-font-size_-1);
	font-weight: bold;
	border-radius: min(var(--i-design-radius, 4px));
	border: 1px solid rgba(0,0,0,0.1);
}

	.ipsReputation_count.i-color_positive {
		background: var(--i-background_positive-soft);
	}

	.ipsReputation_count.i-color_negative {
		background: var(--i-background_negative-soft);
	}

.ipsLikeRep [data-action="giveReputation"] + .ipsReputation_count {
	font-size: var(--i-font-size_-2);
	margin-inline-start: 10px;
}

.ipsLikeRep [data-action="giveReputation"] + .ipsReputation_count::before {
	content: '';
	display: block;
	width: 1px;
	height: 100%;
	position: absolute;
	background: currentColor;
	opacity: .1;
	top: 0;
	inset-inline-start: -8px;
}

/* ======================================================== */
/* FOLLOW/LIKE */
.ipsFollowerList {
	max-height: 300px;
}

/* ======================================================== */
/* SHARE LINKS */
.ipsPageActions{
	display: flex;
	flex-wrap: wrap;
	justify-content: center;
	gap: .6em;
	font-size: calc(.85em + var(--i-range) * .1);
}

	:where(.ipsPageActions > :is(li, div)){
		display: contents;
	}

	.ipsPageActions .ipsButton{
		flex: 1 1 auto;
	}

	@container (max-width: 600px){
		.ipsPageActions--mini-responsive .ipsButton__label{
			display: none;
		}
	}

	.ipsPageActions__mainLink {
		display: block;
		padding: .6em 1em;
		border-radius: min(var(--i-design-radius), 5px);
		background-color: color-mix(in hsl, currentColor 10%, transparent);
		color: var(--i-color_root);
		font-weight: 500;
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
		width: 100%;
	}

	.ipsPageActions__mainLink:hover{
		background-color: color-mix(in hsl, currentColor 15%, transparent);
	}

		.ipsPageActions__mainLink i{
			opacity: .5;
			margin-inline-end: .3em;
		}

/*
	----------------
	- Leaderboard
	----------------
*/

.ipsLeaderboard_trophy {
	color: #ffffff;
	background-color: var(--i-trophy-first--background);
	font-size: 1.5em;
	width: 2em;
	height: 2em;
	border-radius: 50%;
	position: relative;
	display: inline-flex;
	align-items: center;
	justify-content: center;
}

.ipsLeaderboard_trophy_2{
	background-color: var(--i-trophy-second--background);
}

.ipsLeaderboard_trophy_3{
	background-color: var(--i-trophy-third--background);
}

.ipsLeaderboard_trophy_4 {
	display: none;
}

/*
	----------------
	- Entries: User submitted content. Comments, posts, etc
	----------------
*/

.ipsEntry{
	--i-post--pa-in: clamp(1em, 2vw, 1.5em);
	--i-post--pa-bl: clamp(1em, 2vw, 1.5em);
	--i-entry-color: initial;
	position: relative;
	margin-bottom: 1em;
}

/* Add an outline to certain entries */
.ipsEntry--popular, .ipsEntry--solved, .ipsEntry--selected, .ipsEntry--highlighted{
	outline: 4px solid color-mix(in srgb, var(--i-entry-color, transparent) 20%, transparent);
	border-color: var(--i-entry-color, var(--i-color_positive));
}

/* This is split from the above so it doesn't break the above selector in browsers which don't support :has() */
.ipsEntry:has([data-role="moderation"]:checked){
	outline: 4px solid color-mix(in srgb, var(--i-entry-color, transparent) 20%, transparent);
	border-color: var(--i-entry-color, var(--i-color_positive));
}

.ipsEntry--highlighted{
	--i-entry-color: var(--i-primary);
}

.ipsModerated{
	--i-entry-color: var(--i-color_moderated);
}

.ipsEntry--popular {
	--i-entry-color: var(--i-color_positive);
}

.ipsEntry--solved{
	--i-entry-color: var(--i-color_positive);
}

.ipsEntry--selected{
	--i-entry-color: var(--i-primary);
	background-color: var(--i-background_selected) !important;
}

	.ipsEntry:has([data-role="moderation"]:checked){
		--i-entry-color: var(--i-primary);
		background-color: var(--i-background_selected) !important;
	}

	/* Remove box styles from entries if they're inside .ipsBox */
	:where(.ipsBox, .ipsWidget, .ipsDialog) .ipsEntry{
		box-shadow: none;
		background: none;
		border-width: 0;
		border-radius: 0;
		margin: 0;
		outline-width: 0 !important; /* Remove outlines (from moderated, solved, featured states, etc) */
	}

	@media (max-width: 767px){
		.ipsPull .ipsEntry{
			border-left-width: 0;
			border-right-width: 0;
			border-radius: 0;
		}
		.ipsEntry--highlighted{
			outline-offset: -5px;
		}
	}

/* Post header */
.ipsEntry__header{
	--_padding: calc(var(--i-rem) * 1.3);
	color: var(--i-co);
	padding: var(--_padding);
	padding-bottom: 0;
}

/* Reduce gap between mini-profile-toggle and browser */
@media (max-width: 550px){
	.ipsEntry__topButton--profile{
		margin-inline-end: -12px;
	}
}

	.ipsEntry__header a{
		color: inherit;
	}

	.ipsEntry__header-align{
		display: flex;
		align-items: center;
		flex-wrap: wrap;
	}

	.ipsEntry__header .ipsPhotoPanel{
		flex: 999 1 10%; /* 10% is needed to prevent unintended wrapping on small screens */
	}

	.ipsEntry__header .ipsPhotoPanel__secondary{
		font-size: .9em;
	}

	.ipsEntry__header .ipsEntry__group{
		font-size: max(.8em, 11px);
		font-weight: 500;
		color: var(--i-color_soft);
		margin-inline-start: 1.5em;
	}

	.ipsEntry__header-align .ipsInput{
		margin-inline-end: .8em;
	}

/* Solo post date */
.ipsEntry__header .ipsEntry__date{
	display: none;
	opacity: .6;
	font-size: .9em;
	flex-grow: 9999;
}

	.ipsEntry__date a{
		color: inherit;
	}

.ipsEntry__profile-row{
	flex: 1 1 100%;
}

.ipsEntry__profile{
	font-size: max(.8em, 12px);
	padding-top: 1.5em;
}

.ipsEntry__profile-row:has(.ipsEntry__profile){
	margin: 0 calc(var(--_padding) * -1);
}

.ipsEntry__profile-row > .ipsControls__fail-message {
	margin-top: 1.5em;
}

.ipsEntry__username{
	font-weight: 600;
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	color: var(--i-color_hard);
}

	:where(.ipsEntry__username) a{
		color: inherit;
	}

/* Tools */
.ipsEntry__topButton{
	color: var(--i-color_soft);
	display: grid;
	place-content: center;
	border-radius: min(var(--i-design-radius), 5px);
	flex: 0 0 32px;
	align-self: stretch;
}
@media (any-hover:hover){
	.ipsEntry__topButton:hover{
		color: var(--i-color_hard);
		background: var(--i-background_2);
	}
}

/* This hides the "comment_xxx" text from the top right of posts */
.ipsEntry__topButton .ipsMenuLabel{
	clip-path: inset(50%);
	height: 1px;
	margin: -1px;
	overflow: hidden;
	position: absolute;
	white-space: nowrap;
	width: 1px;
}

.ipsEntry__topButton--profile i{
	transition: transform .2s linear;
}

	.ipsEntry__topButton--profile[aria-expanded="true"] i{
		transform: rotateX(180deg);
	}

/* Author stats: Post count, solution count, etc */
.ipsEntry__authorStats{
	--i-co: var(--i-color_soft);
	color: var(--i-co);
	font-weight: 500;
	font-size: max(.9em, 12px);
	display: flex;
	flex-wrap: wrap;
}

	.ipsEntry__authorStats > li > *{
		display: flex;
		align-items: center;
		justify-content: center;
		gap: .5em;
		color: inherit;
		padding: .7em 1em;
		line-height: 1; /* Windows fix? */
	}

	.ipsEntry__authorStats i{
		opacity: .6;
	}

	.ipsEntry__authorStats img{
		height: 1em;
	}

.ipsEntry__authorStats--mini-profile{
	overflow: hidden;
	border: 0 solid var(--i-background_3);
	border-width: 1px 0;
	gap: 1px;
}

	.ipsEntry__authorStats--mini-profile > li {
		outline: 1px solid var(--i-background_3);
		flex: 1 1 auto;
	}

	.ipsEntry__authorStats--mini-profile > li > *{
		padding: 1em;
	}

	.ipsEntry__authorStats--mini-profile a:hover{
		background-color: var(--i-background_2);
	}

	.ipsEntry__authorStats--mini-profile [data-i-el="group-icon"]{
		display: grid;
		place-content: center;
		padding: 0 1em;
	}

		.ipsEntry__authorStats--mini-profile [data-i-el="group-icon"] img{
			max-height: 1.5em;
			padding: 0;
			width: auto;
		}


/* Minimal stats UI */
.ipsEntry__authorStats--minimal{
	justify-content: center;
	margin-left: calc(var(--i-post--pa-in) * -.8);
	margin-right: calc(var(--i-post--pa-in) * -.8);
	text-align: center;
}

	.ipsEntry__authorStats--minimal > li > *{
		border-radius: 5px;
	}

	.ipsEntry__authorStats--minimal [data-i-el="label"]{
		clip-path: inset(50%);
		height: 1px;
		margin: -1px;
		overflow: hidden;
		position: absolute;
		white-space: nowrap;
		width: 1px;
	}

	.ipsEntry__authorStats--minimal a:hover{
		background: var(--i-background_3);
	}

/* Custom fields */
.ipsEntry__authorFields{
	text-align: start;
	color: var(--i-color_soft);
	font-size: max(.9em, 12px);
	display: grid;
	gap: .8em;
}

	.ipsEntry__authorFields [data-i-el="title"]{
		font-weight: 600;
		color: var(--i-color_hard);
		display: block;
	}

	/* Hide custom fields if they're empty */
	.ipsEntry__authorFields:not(:has(*)){ display: none }
	@supports not selector(a:has(b)){
		.ipsEntry__authorFields:-moz-only-whitespace{ display: none }
	}

	.ipsEntry__profile .ipsEntry__authorFields{
		padding: 1.3em;
		border-bottom: 1px solid var(--i-background_3);
	}

.ipsEntry__content{
	position: relative; /* Required for quote tooltip */
}

@media (min-width: 601px){
	.ipsEntry__header .ipsBadges{
		margin-inline-end: 1.2em;
	}
}

@media (max-width: 600px){
	.ipsEntry__header .ipsBadges{
		flex: 1 1 100%;
		margin-top: 1.5em;
		order: 10;
	}
}

	/* This helps with vertical alignment */
	:where(.ipsEntry--simple, .ipsEntry--post) .ipsEntry__post > .ipsBadges > li{
		display: contents;
	}

.ipsEntry--simple .ipsEntry__post, .ipsEntry--post .ipsEntry__post{
	padding: var(--i-post--pa-bl) var(--i-post--pa-in);
	flex-grow: 1;
}

	/* Increase font-size unless the content is being edited */
	:where(.ipsRichText--user:not(:has(.ipsEditor))){
		font-size: calc(var(--set__i-user-content-font-size, 100) * .01em);
		line-height: 1.8;
	}

/* Signature */
.ipsEntry__signature{
	margin-top: 1em;
	border-top: 1px solid;
	border-color: color-mix(in srgb, currentColor 15%, transparent);
	padding: 1em 0;
}

/* Controls */
.ipsEntry__footer{
	padding: .6em;
	display: flex;
	align-items: center;
	flex-wrap: wrap-reverse; /* Make sure reactions sit on top of buttons when they wrap */
	gap: .6em;
	font-size: .9em;
}

	/* Hide the footer if it only contains an empty/invisible reaction component */
	.ipsEntry__footer:has(> .ipsReact:only-child):not(:has(.ipsReact_types)):has(.ipsReact_blurb.ipsHide){
		display: none;
	}

	.ipsEntry__controls{
		color: var(--i-color_primary);
		display: flex;
		gap: 1px;
		flex-wrap: wrap;
		align-items: center;
		font-weight: 600;
	}

	.ipsEntry__controls > li{
		border-radius: 5px;
		height: 2.5em;
		/* Needed for helpful */
		display: flex;
		position: relative;
	}

	@media (any-hover:hover){
		.ipsEntry__controls > li:not(:has(p)):hover{
			background-color: color-mix(in srgb, currentColor 10%, transparent);
		}
	}

		.ipsEntry__controls > li > :where(a, button, p){
			display: flex;
			align-items: center;
			gap: .5em;
			padding: 0 1em;			
			color: inherit;
			border-radius: inherit;
		}

		.ipsEntry__controls [data-active="helpful"]{
			color: var(--i-color_positive);
		}

			.ipsEntry__controls p{
				color: var(--i-color_soft);
			}

/* Split buttons, such as helpful */
.ipsEntry__controls-badge{
	margin-inline-start: -.4em;
    position: relative ;
    padding: 0 .8em;
	border-start-start-radius: 0;
	border-end-start-radius: 0;
}

.ipsEntry__controls-badge:hover{
	background-color: color-mix(in srgb, currentColor 5%, transparent);
}
	.ipsEntry__controls-badge::before{
		content: '';
		position: absolute;
		inset-inline-start: 0;
		top: .5em;
		bottom: .5em;
		border-left: 1px solid currentcolor;
		opacity: .15;
	}

.ipsEntry__footer .ipsReact{
	margin-inline-start: auto;
}


/*
	----------------
	- Simple entries (used in widgets or inside ipsBox)
	----------------
*/

/* Add a border to the top of posts */
:where(.ipsBox, .ipsWidget, .ipsDialog) .ipsEntry--simple{
	border-top: 6px solid var(--i-entry-color, var(--i-background_4));
}

/* Remove the top border on the first post in the minimal topic view */
.ipsEntry--first-simple{
	border-top-width: 0;
}

	:where(.ipsEntry--first-simple .ipsEntry__post .ipsRichText--user){
		font-size: max(var(--set__i-user-content-font-size, 100) * .01em, 1.12em, 16px);
	}

/* Hide side column and meta row */
.ipsEntry--simple .ipsEntry__author-column,
.ipsEntry--simple .ipsEntry__meta{
	display: none;
}

/* v5 todo: This overwrites :where(.ipsEntry--simple, .ipsEntry--post) .ipsEntry__post in this same file. What do we need? */
.ipsEntry--simple .ipsEntry__post{
	--i-post--pa-bl: 1.5em;
	--i-post--pa-in: 1.5em;
}

/* Add a margin to badges in simple comments (ie. Featured CMS comments) */
.ipsEntry--simple .ipsEntry__post .ipsBadges{
	margin-bottom: .6em;
}


/*
	----------------
	- Posts
	----------------
*/

.ipsEntry--post{
	display: grid;
}

/* Author column */
.ipsEntry__author-column{
	display: grid;
	align-content: start;
	gap: 1.2em;
	text-align: center;
	padding: var(--i-post--pa-bl) var(--i-post--pa-in);
	border-inline-end: 1px solid var(--i-background_3);
	position: relative;
}

	.ipsEntry__author-online{
		display: none;
		position: absolute;
		top: -1px;
		inset-inline-start: -1px;
		border: .6em solid var(--i-background_positive);
		border-bottom-color: transparent;
		border-inline-end-color: transparent;
		border-start-start-radius: var(--i-box--bo-ra);
	}

	.ipsEntry__author-column .ipsEntry__username{
		font-size: 1.1em;
		font-weight: 700;
		justify-content: center;
		gap: .5em;
	}

	.ipsEntry__author-column .ipsEntry__author-moderator-badge{
		--i-badge: hsl(var(--if-light, 117 56% 80%) var(--if-dark, 150 62% 25%));
		font-size: .8em;
	}

	.ipsEntry__author-column .ipsAvatarStack{
		width: 50%;
		justify-self: center;
	}

	.ipsEntry__author-column .ipsEntry__group{
		margin-top: -1em;
		color: var(--i-color_soft);
		font-size: .9em;
	}

	.ipsEntry__group a{
		color: inherit;
	}

	.ipsEntry__moderatorBadge{
		font-weight: 500;
	}

	.ipsEntry__moderatorBadge::before{
		content: "\f3ed";
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		margin-inline-end: .2em;
		opacity: .6;
		display: inline-block;
		width: 1em; /* Layout shift */
	}


/* Hide badges by default */
.ipsEntry__authorStats [data-i-el="badges"]{
	display: none;
}

/* Date: Shown on desktops in Posts */
.ipsEntry__meta{
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 0 1em;
	margin-bottom: var(--i-post--pa-bl);
}

	.ipsEntry__meta .ipsEntry__date{
		--i-co: var(--i-color_soft);
		color: var(--i-co);
		font-size: var(--i-font-size_-1);
		white-space: nowrap; /* Necessary to stop the date from weirdly wrapping in some situations */
		margin-inline-end: auto;
	}

	/* Increase height of top buttons slightly (ellipsis) */
	.ipsEntry__meta .ipsEntry__topButton{
		min-height: 2em;
		margin-block: -0.4em;
	}

/* Post content */
.ipsEntry--post .ipsEntry__content{
	display: flex;
	flex-direction: column;
}

/* Editing a post: */
/* Pull out edit form so it touches the sides. Margins are em's, so we adjust them based on the user font-size value */
.ipsEntry__post .ipsRichText--user .ipsForm--edit{
	margin-inline: calc(100 / var(--set__i-user-content-font-size, 100) * var(--i-post--pa-in) * -1);
}
/* Remove top padding */
.ipsEntry__post .ipsForm--edit .ipsFieldRow:first-of-type{
	padding-top: 0;
}
/* Remove bottom padding to remove excess gap */
.ipsEntry__post:has(.ipsForm--edit){
	padding-bottom: 0;
}
/* Remove Required label */
.ipsEntry__post .ipsForm--edit .ipsFieldRow__label[for="comment_value"]{
	display: none;
}
/* Remove border-radius */
.ipsEntry__post .ipsForm--edit .ipsSubmitRow{
	border-radius: 0;
}
/* Hide footer (Post controls and reactions) when edit form is active */
.ipsEntry:has(.ipsForm--edit) .ipsEntry__footer{
	display: none;
}

/*
	----------------
	- Other components
	----------------
*/

/* Ignored */
.ipsEntry--ignored{
	font-weight: 500;
	color: var(--i-color_soft);
	padding: 1em;
	font-size: max(.9em, 11px);
}

	.ipsEntry--simple ~ .ipsEntry--ignored,
	:is(.ipsEntries--topic, .ipsEntries--comments, .ipsEntries--reviews) .ipsEntry--ignored{
		text-align: center;
		background-color: var(--i-background_2);
		border-top: 1px solid var(--i-background_5);
	}

/* Hidden message */
.ipsEntry__hiddenMessage{
	background-color: color-mix(in srgb, var(--i-co) 10%, transparent);
	padding: .8em 1em;
	border-radius: 5px;
	margin-bottom: 1em;
	font-weight: 500;
	font-size: .95em;
}

.ipsUnreadBar {
	color: var(--i-color_primary);
	margin: 1em;
	display: flex;
	align-items: center;
	gap: 0 1.2em;
	font-weight: 600;
	font-size: .9em;
	text-align: center;
}

	.ipsUnreadBar::before,
	.ipsUnreadBar::after {
		content: '';
		height: 3px;
		border-radius: 3px;
		flex: 1 1 auto;
		background: currentColor;
	}

.ipsBox .ipsUnreadBar:not(hr){
	display: block;
	color: var(--i-primary-contrast);
	background: var(--i-primary);
	padding: .4em;
	margin: 5px;
	border-radius: 5px;
}

.ipsBox .ipsUnreadBar::before,
.ipsBox .ipsUnreadBar::after{
	content: none;
}

hr.ipsUnreadBar{
	display: block;
	padding: 0;
	background-color: currentColor;
	border-radius: 4px;
	height: 6px;
}

/* Recommended note */
.ipsEntry__recommendedNote{
	background: var(--i-background_2);
	border-radius: 6px;
	margin-top: 1em;
	padding: 1em;
}

/* Truncate posts if using the compact style and are viewing pages beyond 1 */
.ipsEntry__truncate:not([data-truncate-expanded]){
	max-height: 30em;
}
	html .ipsEntry__truncate ~ .ipsTruncate_more{
		background: var(--i-secondary);
		color: var(--i-secondary-contrast);
		margin-left: auto;
		margin-right: auto;
		width: fit-content;
		padding: 0 1em;
		border-radius: 5px;
	}

/* 
	Container queries don't work well here at the moment. They have layout containment, so "Edit post" dropdown menus are overlaid by sidebars.
	These menus are located inside the post area due to data-ipsMenu-appendTo which is necessary for editing posts
*/
@media (min-width: 768px) {

	.ipsEntry--post{
		grid-template-columns: var(--post-column--fl-ba, 230px) 1fr;
	}

	/* Column styles */
	.ipsEntry--post .ipsEntry__header,
	.ipsEntry--post .ipsEntry__post > .ipsBadges{
		display: none;
	}

}

@media (max-width: 767px){
	.ipsEntry--post .ipsEntry__author-column,
	.ipsEntry--post .ipsEntry__meta{
		display: none;
	}
}

[data-ips-comments-loading]{
	opacity: .5;
	pointer-events: none;
}

/* Ensure elements occupy space so the intersectionObserver can respond to them */
[data-ipsfetch]:not([data-ipsfetch-loaded]){
	min-height: 1px;
}
/* Animated spinner while data-ipsfetch content loads */
i-fetch-spinner{
	display: grid;
	place-content: center;
	min-height: 200px;
}
	i-fetch-spinner::before{
		content: "";
		display: block;
		width: 30px;
		height: 30px;
		border-radius: 50%;
		border: 5px solid color-mix(in hsl, currentColor 30%, transparent);
		border-top-color: currentColor;
		animation: i-fetch-spinner .8s infinite linear;
	}
@keyframes i-fetch-spinner {
	0% { transform: rotate(0turn); }
	100% { transform: rotate(1turn); }
}

/*
	----------------
	- Form
	----------------
*/

.ipsFieldRow{
	display: grid;
	gap: .8em;
	padding: 1.5em;
	border-bottom: 1px solid color-mix(in srgb, currentColor 10%, transparent);
}

	.ipsFieldRow[style*="list-item"]{
		display: grid !important;
	}

	.ipsFieldRow ~ li:has(> .ipsHr:only-child){
		display: none;
	}

/* Form headers, eg in "Edit Profile" modal */
.ipsFieldRow__section{
	padding: 1em;
	font-weight: 600;
	color: var(--i-color_hard);
	font-size: 1.2em;
	border-bottom: 1px solid var(--i-background_3);
}

.ipsFieldRow__section:last-child, .ipsFieldRow:nth-last-child(1 of :not([hidden])){
	border-bottom-width: 0;
}


/* Submit row */
.ipsSubmitRow{
	flex: 0 0 auto; /* Useful when in flex-direction:column layouts */
	margin-top: auto; /* Push this bar down if its previous siblings don't have flex-grow: 1; */
	background: var(--i-background_2);
	padding: 1em;
	border-top: 1px solid var(--i-background_4);
	border-bottom-left-radius: var(--i-box--bo-ra);
	border-bottom-right-radius: var(--i-box--bo-ra);
	text-align: center;
}
/* Hide empty submit rows, eg. Notification settings */
.ipsSubmitRow:not(:has(*)){
	display: none;
}
/* Pull up submit row so it overlaps fieldRow border */
.ipsFieldRow + .ipsSubmitRow{
	margin-top: -1px;
}
/* Apply submit row styles to alternate HTML markup */
.ipsFieldRow:has(> .ipsFieldRow__content > button:only-child){
	background: var(--i-background_2);
	padding: 1em;
	border-top: 1px solid var(--i-background_4);
	border-bottom-left-radius: var(--i-box--bo-ra);
	border-bottom-right-radius: var(--i-box--bo-ra);
	text-align: center;
	margin-top: -1px; /* This prevents a double border */
}


/* Labels */
.ipsFieldRow__label{
	font-weight: 600;
	font-size: 1.1em;
	color: var(--i-color_hard);
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 0em 2em;
}

	/* Potential fix for Opera Mobile, where labels and "Required" were wrapping prematurely */
	.ipsFieldRow__label > *{
		min-width: fit-content;
	}

	/* Hide labels on certain forms */
	.ipsFieldRow--noLabel .ipsFieldRow__label,
	.ipsForm--noLabels .ipsFieldRow:not(.ipsFieldRow--checkbox) .ipsFieldRow__label {
		clip: rect(1px, 1px, 1px, 1px);
		clip-path: inset(50%);
		height: 1px;
		margin: -1px;
		overflow: hidden;
		padding: 0;
		position: absolute;
		white-space: nowrap;
		width: 1px;
	}

	/* ..or if they're empty */
	.ipsFieldRow__label:has(span:only-child:empty){
		display: none;
	}
	/* Hide empty labels, but keep parent visible incase it contains "Required". Topic content forms are an example */
	.ipsFieldRow__label span:empty{
		display: none;
	}

	/* Labels next to radios */
	.ipsFieldList--radio label{
		font-weight: 500;
		color: var(--i-color_hard);
	}

	/* Underline links */
	.ipsFieldRow__label a{
		text-decoration: underline;
	}

.ipsFieldRow__required {
	font-size: max(.7em, 10px);
	text-transform: uppercase;
	color: var(--if-light, hsl(0 78% 37%)) var(--if-dark, hsl(0 89% 70%));
	margin-inline-start: auto;
}

/* Language labels (with flags) */
.ipsFieldRow__languages{
	display: grid;
	gap: 2em;
}
.ipsFieldRow__language{
	font-weight: 500;
	color: var(--i-color_hard);
	margin-bottom: .5em;
}
.ipsFieldRow__language .ipsFlag{
	margin-inline-end: .3em;
}

/* Descriptions */
.ipsFieldRow__desc {
	font-size: 0.9em;
	margin-top: .75em;
	color: var(--i-color_soft);
}
	.ipsFieldRow__label ~ .ipsFieldRow__desc{
		margin-top: 0;
	}

	/* Remove margin from radio option descriptions */
	.ipsFieldList--radio .ipsFieldRow__desc{
		margin-top: 0;
	}

	/* Underline links in form descriptions */
	.ipsFieldRow__desc a{
		text-decoration: underline;
	}

/* Warning */
.ipsFieldRow__warning{
	color: var(--i-color_warning);
	background: color-mix(in srgb, var(--i-color_warning) 15%, transparent);
	border: 1px solid color-mix(in srgb, var(--i-color_warning) 40%, transparent);
	padding: 0.8em 1em;
	border-radius: 5px;
	font-weight: 500;
	margin-top: 1em;
	font-size: .9em;
}

	.ipsFieldRow__warning .fa-circle-exclamation{
		margin-inline-end: .4em;
	}

	.ipsFieldRow__warning:empty{
		display: none;
	}


/* Horizontal UI */
@media (min-width: 700px){
	.ipsForm--horizontal  .ipsFieldRow{
		display: flex;
		align-items: flex-start;
	}
	.ipsForm--horizontal .ipsFieldRow[style*="list-item"]{
		display: flex !important;
	}
	.ipsForm--horizontal .ipsFieldRow__required{
		flex: 1 1 100%;
	}	
	.ipsForm--horizontal .ipsFieldRow__label{
		flex: 1 1 20em;
		display: grid;
		text-align: end;
		place-items: end;
	}
	.ipsForm:not(.ipsForm--horizontal) .ipsFieldRow--fullWidth > *{
		flex: 1 1 100%;
		max-width: none;
	}
}

/* Adjust the padding of the review form, since the parent wrapper already has padding */
.ipsForm--review > .ipsFieldRow:first-child{
	padding-top: 0;
}

.ipsForm--review .ipsFieldRow{
	border-width: 0;
	padding-left: 0;
	padding-right: 0;
}

.ipsForm--review .ipsSubmitRow{
	padding-bottom: 0;
	border-width: 0;
	background: transparent;
}







.ipsFieldRow--checkbox{
	display: flex;
	align-items: center;
	gap: 1em;
}

/* Follow pop-up menu */
.ipsForm--notifications-follow .ipsFieldRow:has([name="follow_public_checkbox"]){
	display: flex;
	align-items: center;
}

/* Vertically stack question and options */
.ipsPollList--questions .ipsFieldRow{
	display: grid;
}

/* Fix Safari alignment bug */
.ipsPollList--questions .ipsFieldList{
	align-self: start;
}

.ipsFieldRow__content{
	flex: 999 1 55%;
}

/* Inline checkboxes */
.ipsFieldRow__content--checkboxes{
	display: flex;
	flex-wrap: wrap;
	gap: 1em 2em;
}

	.ipsFieldRow__inlineCheckbox,
	.ipsFieldRow__content--checkboxes > *{
		display: flex;
		align-items: center;
		gap: .5em;
	}

	.ipsFieldRow__inlineCheckbox{
		display: inline-flex;
	}

/* Stacked form: Used for addresses, poll options, etc */
.ipsFieldListParent{
	display: grid;
	gap: 2em;
}

	.ipsFieldList > *{
		display: flex;
		align-items: center;
		gap: .8em;
		padding: .4em;
	}

	.ipsFieldList > input{
		flex: 0 0 auto;
		align-self: baseline;
		margin-top: .2em;
	}

	.ipsFieldList__content{
		flex: 1 1 auto;
	}

	.ipsFieldRow label[for],
	:where(label:has(input)){
		cursor: pointer;
	}

	/* Remove cursor if the field is an autocomplete, since clicking the label does nothing */
	.ipsFieldRow label[for]:has(~ [data-controller="core.global.core.optionalAutocomplete"]){
		cursor: default;
	}

	/* Highlight code tags (ACP > Content Discovery > Search) */
	.ipsFieldList__content code{
		background: var(--i-background_5);
		color: var(--i-color_hard);
		border-radius: 4px;
		padding: .3em;
		display: inline-block;
	}

/* Full width inputs */
:is(.ipsFieldRow--fullWidth, .ipsForm--fullWidth) :is(select, textarea, input:not([type="radio"], [type="checkbox"]), .ipsField_autocomplete, .ipsSelectTree), .ipsInput--wide{
	width: 100%;
	max-width: none;
}

/* Select menus: If they're followed by a label, set their width to auto */
.ipsFieldRow__content select:has(+ span){
	width: auto;
	margin-inline-end: .6em;
}

/* Title suggestions on create-item forms */
@media (prefers-reduced-motion: no-preference) {
	.ipsTitleSuggestions{
		interpolate-size: allow-keywords;
		height: 0;
		opacity: 0;
		overflow-y: clip;
		transition-property: display, content-visibility, opacity, height;
		transition-duration: .3s;
		transition-behavior: allow-discrete;
	}

		.ipsTitleSuggestions:not([hidden]) {
			height: auto;
			opacity: 1;

			@starting-style{
				&{
					height: 0;
					opacity: 0;
				}
			}
		}

	/* Animated height fallback */
	@supports not (interpolate-size: allow-keywords){
		.ipsTitleSuggestions{
			height: auto;
			display: grid;
			grid-template-rows: 0fr;
			transition-property: display, opacity, content-visibility, grid-template-rows;
		}
		.ipsTitleSuggestions:not([hidden]) {
			grid-template-rows: 1fr;

			@starting-style{
				& {
					grid-template-rows: 0fr;
					opacity: 0;
				}
			}
		}
	}

}
.ipsTitleSuggestions__content {
	padding-top: 1em;
	padding-inline-start: .5em;
	border-inline-start: 1px solid var(--i-background_4);
	margin-inline-start: 1.2em;
	margin-top: 1px;
}
.ipsTitleSuggestions .ipsData__item{
	border-width: 0;
	border-radius: min(var(--i-design-radius), 6px);
	padding: .7em;
}
	.ipsTitleSuggestions .ipsData__icon .ipsUserPhoto{
		width: 1.5em;
		display: block;
	}
	@container (min-width: 600px){
		.ipsTitleSuggestions .ipsData__main{
			display: flex;
			flex-wrap: wrap;
			align-items: center;
		}
	}


/* Date fields in "New" form */
.cCreateTopic_date{
	display: grid;
	gap: .5em;
}

/* Stacks */
.ipsFieldRow:not(.ipsFieldRow--fullWidth) .ipsField_stack { 
	max-width: 350px;
}

.ipsField_stackItem[style*="absolute"]{
	background: var(--i-background_2);
}

.ipsField_stackItem{
	display: flex;
	gap: .4em;
	padding: .4em 0;
	position: relative;
	min-height: 54px;
}

	.ipsField_stackDrag{
		cursor: move;
		display: grid;
		place-content: center;
		padding: 0 1em;
		flex: 0 0 auto;
		color: var(--i-color_soft);
	}

	/* Sometimes the data-action attribute is added to divs instead of the drag handle */
	[data-action="stackDrag"]{
		cursor: move;
	}

	.ipsField_stackItem_keyValue{
		display: flex;
		gap: .5em;
	}

	.ipsField_stackDelete{
		flex: 0 0 auto;
		order: 1;
		cursor: pointer;
		color: var(--i-color_soft);
		font-weight: 500;
		padding: 0 1em;
		display: grid;
		place-content: center;
		border-radius: 6px;
	}
		.ipsField_stackDelete:hover{
			background: var(--i-background_2);
		}

.ipsField_stackAdd{
	margin-inline-start: 5em;
}

[data-ipsstack-wrapper] {
	flex: 1 1 auto;
}

/*
	----------------
	- Translatable inputs
	----------------
*/

.ipsForm--translatable{
	display: grid;
	gap: 1em;
}

.ipsForm--translatable .ipsFieldRow{
	padding: 0;
	border-width: 0;
}

/*
	----------------
	- Polls
	----------------
*/

/* Polls have parent and child .ipsFieldRows, which doubles up on padding/borders. This fixes that */
.ipsTabs__panel[class*="_pollTab"] > .ipsForm > .ipsFieldRow{
	display: contents;
}

/* Poll forms */
[data-role="pollContainer"]{
	display: grid;
	gap: 1em;
	padding: 1em;
}
	[data-role="pollContainer"] [data-role="question"]{
		background: var(--i-background_2);
		padding: 1.5em;
		border-radius: var(--i-box--bo-ra);
	}

/* Draggable */
@media (hover: none){
	.ipsAttachment_supportDrag {
		display: none;
	}
}

/* Loading attachments */
.ipsAttachment_loading.ipsLoading--small {
	font-size: 30px;
	margin-top: 2px;
	margin-inline-end: 6px;
}
	.ipsAttachment_loading.ipsAttachment_loading_editor {
		margin-top: -2px;
	}


/* Content item */
.ipsContentItemSelector > *{
	margin-top: 10px;
}

.ipsContentItemSelector > :first-child {
	margin-top: 5px;
}

.ipsContentItemSelector [data-role="contentItemRow"]{
	padding-inline-start: 5px;
}

.cContentItem_delete {
	height: 18px;
	line-height: 18px;
	background: var(--i-primary);
	color: var(--i-primary-contrast);
	display: inline-block;
	font-size: 13px;
	border-radius: 12px;
	padding: 0 .85em;
	cursor: pointer;
	margin: 1px 5px !important;
	margin-inline-start: 0 !important;
	float: inline-start;
}

/* Select tree */
.ipsSelectTree {
	display: flex;
	align-items: center;
	min-height: 2.7em;
	min-width: min(350px, 100%);
	width: fit-content;
	padding: 0 1em;
	position: relative;
	cursor: pointer;
	background-color: var(--i-input--ba-co);
	background-clip: padding-box;
	border-color: var(--i-input--bo-co);
	border-radius: var(--i-input--bo-ra);
	border-style: var(--i-input--bo-st, solid);
	border-width: var(--i-input--bo-wi);
	box-shadow: var(--i-input--bo-sh, none);
	color: var(--i-co);
}

	.ipsSelectTree:not(.ipsSelectTree_active):hover{
		border-color: var(--i-input-hover--bo-co);
	}

	.ipsSelectTree_active{
		border-color: var(--i-input-active--bo-co);
	}

	.ipsSelectTree.ipsSelectTree_disabled {
		opacity: .4;
		background-color: var(--i-background_3);
		font-style: italic;
		pointer-events: none;
	}

	.ipsSelectTree_value{
		margin-inline-end: 1em;
	}

	.ipsSelectTree_expand {
		margin-inline-start: auto;
		opacity: .3;
		flex: 0 0 auto;
	}

	.ipsSelectTree [data-role="tokenList"]{
		display: flex;
		flex-wrap: wrap;
		padding: 0.5em 0;
	}

	.ipsSelectTree [data-role="tokenList"] li {
		line-height: 1;
		margin-inline-end: 5px;
	}

		.ipsSelectTree [data-role="tokenList"] .cToken {
			background: var(--i-primary);
			color: var(--i-primary-contrast);
			margin-bottom: 4px;
		}

.ipsSelectTree_nodes {
	width: 100%;
	background: var(--i-dropdown--ba-co);
}

	i-dropdown .ipsSelectTree_nodes {
		padding-inline-start: 0.5em;
		border-inline-start: 1px solid var(--i-box--bo-co);
	}

		i-dropdown .ipsSelectTree_nodes > i-tabs {
			padding-block-start: 0;
		}

		i-dropdown .ipsSelectTree_nodes--auto-expanded {
			padding-inline-start: 0;
			border-inline-start: 0;
			min-height: var(--i-nodes-min-height, 100px); /* Prevent layout shifts on mobile */
		}
		i-dropdown .ipsSelectTree_nodes--auto-expanded > *:not(.x) {
			padding-inline: 0;
		}
		i-dropdown .ipsSelectTree:has(+ .ipsSelectTree_nodes--auto-expanded) > .ipsSelectTree_expand {
			display:none;
		}


		/* Prevent layout shifts with a fixed height and overflow */
		@media(max-width: 499px) {
			i-dropdown .ipsSelectTree_nodes > [data-role="nodeList"] {
				height: 300px;
				overflow-y: scroll;
			}
		}

		.ipsSelectTree_nodes--collapsed {
			height: 0;
			overflow: hidden;
		}
		i-dropdown .ipsSelectTree_nodes:not(.ipsSelectTree_nodes--collapsed) {
			margin-block-start: 0.5em;
		}

	.ipsSelectTree_nodes:not(i-dropdown *) {
		position: absolute;
		top: 100%;
		inset-inline-start: -1px;
		min-width: max(100%, 300px);
		width: max-content;
		max-width: 450px;
		box-shadow: var(--i-dropdown--bo-sh);
		border-radius: var(--i-input--bo-ra);
	}

	/* Use position:fixed and anchor so the tree is displayed outside of ipsDialog_content (with overflow:auto) */
	@supports (anchor-name: --x){
		.ipsDialog .ipsSelectTree{
			anchor-name: --ipsSelectTree;
		}
		.ipsDialog .ipsSelectTree_nodes{
			position: fixed;
			position-anchor: --ipsSelectTree;
			top: anchor(bottom) !important;
			left: anchor(left);
			right: anchor(right);
			bottom: auto !important;
			width: auto;
			min-width: 0;
		}
	}

	/* For older browsers, display the tree below the toggle */
	@supports not (anchor-name: --x){
		.ipsDialog .ipsSelectTree{
			flex-wrap: wrap;
		}
		.ipsDialog .ipsSelectTree_nodes{
			position: relative;
			top: auto !important;
			bottom: auto !important;
			left: auto;
			right: auto;
			margin: 5px -10px;
			/* Occupy the same width as .ipsSelectTree */
			width: min-content;
			flex: 999 1 100%;
		}

		/* Preserve height for placeholders since they'll otherwise become squashed */
		.ipsDialog .ipsSelectTree_value{
			min-height: 2.7em;
			align-content: center;
		}
	}

	.ipsSelectTree_nodes.ipsSelectTree_bottom {
		margin-top: 5px;
	}
	.ipsSelectTree_nodes.ipsSelectTree_top {
		margin-bottom: 5px
	}

	.ipsSelectTree_nodes [data-role="nodeList"] {
		max-height: 300px;
		overflow: auto;
		padding: .4em;
	}

			.ipsSelectTree_item{
				border-radius: min(var(--i-design-radius), 5px);
				display: flex;
				align-items: center;
				gap: .5em;
				padding: .7em 1em;
				padding-inline-start: 1.5em;
			}

				/* Reduce padding on collapsible headers since they include an icon */
				.ipsSelectTree_nodes [data-role="nodeList"] li .ipsSelectTree_item.ipsSelectTree_withChildren {
					padding-inline-start: .3em;
				}

				.ipsSelectTree_nodes [data-role="nodeList"] li .ipsSelectTree_item:not(.ipsSelectTree_itemDisabled, .ipsSelectTree_selected):hover {
					background: color-mix(in srgb, currentColor 8%, transparent);
				}

			.ipsSelectTree_nodes [data-role="nodeList"] li [data-role="childWrapper"] {
				margin-inline-start: 12px;
				padding-inline-start: 4px;
				border-inline-start: 1px dashed;
				border-color: color-mix(in srgb, currentColor 20%, transparent);
			}

			.ipsSelectTree_nodes [data-role="nodeList"] li .ipsSelectTree_toggle {
				flex: 0 0 auto;
				width: 1.3em;
				display: grid;
				place-content: center;
				color: inherit;
			}

				.ipsSelectTree_nodes [data-role="nodeList"] li .ipsSelectTree_item > .ipsSelectTree_toggle::before {
					content: '\f054';
					font-family: var(--i-font-awesome);
					-webkit-font-smoothing: antialiased;
					text-rendering: auto;
					font-weight: 900;
					font-size: .8em;
					transition: .2s;
				}

					.ipsSelectTree_nodes [data-role="nodeList"] li .ipsSelectTree_item.ipsSelectTree_itemOpen > .ipsSelectTree_toggle::before {
						transform: rotate(90deg);
					}

		.ipsSelectTree_nodes .ipsSelectTree_loadMore {
			text-align: center;
			padding: 7px 0px 0px;
		}

			.ipsSelectTree_nodes .ipsSelectTree_loadMore .ipsLoading {
				margin-inline-end: 4px;
			}

.ipsSelectTree_selected {
	background: var(--i-primary);
	color: var(--i-primary-contrast);
}

	.ipsSelectTree_selected::after {
		content: '\f00c';
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		margin-inline-start: auto;
	}

.ipsSelectTree_itemDisabled > [data-role="nodeTitle"] {
	opacity: .5;
	cursor: default;
}

.ipsSelectTree_placeholder {
	opacity: .6;
}

.ipsSelectTree_search {
	margin-top: 7px;
	position: relative;
}

	.ipsApp .ipsSelectTree_search input {
		border: 1px solid;
		border-color: color-mix(in srgb, currentColor 10%, transparent);
		font-size: .9em;
		padding-inline-start: 26px;
	}

	.ipsSelectTree_search::after {
		content: '\f002';
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		position: absolute;
		top: 7px;
		inset-inline-start: 7px;
	}

/*
	----------------
	- Grids
	----------------
*/

.ipsGrid{
	--i-basis: 260px;
	--i-column-gap: var(--i-sp_2);
	--i-row-gap: var(--i-column-gap);

	--i-grid--min: 1;
	--i-grid--max: 99;
	display: grid;
	gap: var(--i-row-gap) var(--i-column-gap);
	grid-template-columns: repeat(auto-fill, minmax(
		min(
			100% / var(--i-grid--min) - var(--i-column-gap),
			max(
				var(--i-basis),
				100% / var(--i-grid--max) - var(--i-column-gap)
			)
		)
		, 1fr
	));
}

.ipsGrid--auto-fit{
	grid-template-columns: repeat(auto-fit, minmax(
		min(
			100% / var(--i-grid--min) - var(--i-column-gap),
			max(
				var(--i-basis),
				100% / var(--i-grid--max) - var(--i-column-gap)
			)
		)
		, 1fr
	));
}

.ipsGrid--1{ grid-template-columns: 1fr; }
.ipsGrid--2{ grid-template-columns: repeat(2, 1fr); }
.ipsGrid--3{ grid-template-columns: repeat(3, 1fr); }
.ipsGrid--4{ grid-template-columns: repeat(4, 1fr); }
.ipsGrid--5{ grid-template-columns: repeat(5, 1fr); }
.ipsGrid--6{ grid-template-columns: repeat(6, 1fr); }
.ipsGrid--7{ grid-template-columns: repeat(7, 1fr); }
.ipsGrid--8{ grid-template-columns: repeat(8, 1fr); }

.ipsGrid--max-1{ --i-grid--max: 1; }
.ipsGrid--max-2{ --i-grid--max: 2; }
.ipsGrid--max-3{ --i-grid--max: 3; }
.ipsGrid--max-4{ --i-grid--max: 4; }
.ipsGrid--max-5{ --i-grid--max: 5; }
.ipsGrid--max-6{ --i-grid--max: 6; }
.ipsGrid--max-7{ --i-grid--max: 7; }
.ipsGrid--max-8{ --i-grid--max: 8; }

.ipsGrid--min-1{ --i-grid--min: 1; }
.ipsGrid--min-2{ --i-grid--min: 2; }
.ipsGrid--min-3{ --i-grid--min: 3; }
.ipsGrid--min-4{ --i-grid--min: 4; }
.ipsGrid--min-5{ --i-grid--min: 5; }
.ipsGrid--min-6{ --i-grid--min: 6; }

.ipsGrid--categories{
	--i-basis: 320px;
	--i-column-gap: 1.5em;
}

/* Stretch item to full width */
.ipsGrid__stretch{
	grid-column: 1/-1;
}

/* Image grid */
.ipsImageGrid{
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 20px;
}

	.ipsImageGrid img{
		max-height: 80px;
	}

/*
	----------------
	- Grid with separator lines
	----------------
*/

.ipsGrid--lines{
	--ipsGrid--lines--bo-co: var(--i-background_3);
	gap: 1px;
	overflow: hidden;
}

.ipsBox > .ipsGrid--lines{ border-radius: inherit; }

	:where(.ipsGrid--lines > *){
		outline: 1px solid var(--ipsGrid--lines--bo-co);
		padding: 1em;
	}

/*
	----------------
	- Masonry
	----------------
*/

.ipsMasonry{
	--i-ratio: 16/9;
	--i-column-gap: 7px;
	--i-basis: clamp(120px, 25%, 240px);
	display: flex;
	align-items: flex-start;
	flex-wrap: wrap;
	gap: var(--i-column-gap);
}

	.ipsMasonry__item,
	.ipsMasonry::after{
		flex-grow: calc(10 * (var(--i-ratio)));
		flex-shrink: 1;
		flex-basis: calc(var(--i-ratio) * var(--i-basis));
	}

	.ipsMasonry__item{
		aspect-ratio: var(--i-ratio);
	}

	.ipsMasonry__item:has(:checked){
		outline: 2px solid var(--i-primary);
		outline-offset: 2px;
	}

	.ipsMasonry::after{
		content: '';
		flex-basis: 50%;
	}

		.ipsMasonry .ipsFigure{
			aspect-ratio: var(--i-ratio);
			border-radius: 0;
		}

/*
	----------------
	- Fluid
	----------------
*/

.ipsFluid{
	--i-basis: auto;
	--i-column-gap: var(--i-sp_2);
	--i-row-gap: var(--i-column-gap);
	--i-fluid--min: 1;
	--i-fluid--max: 99;
	display: flex;
	flex-wrap: wrap;
	gap: var(--i-row-gap) var(--i-column-gap);
}

	.ipsFluid > *{
		flex: 1 1 0%;
		flex-basis:
			min(
				(100% - (var(--i-column-gap) * (var(--i-fluid--min) - 1))) / var(--i-fluid--min),
				clamp(
					var(--i-basis),
					(100% - (var(--i-column-gap) * (var(--i-fluid--max) - 1))) / var(--i-fluid--max),
					100%
				)
			)
		;
	}

.ipsFluid--2 { --i-fluid--max: 2; }
.ipsFluid--3 { --i-fluid--max: 3; }
.ipsFluid--4 { --i-fluid--max: 4; }
.ipsFluid--5 { --i-fluid--max: 5; }
.ipsFluid--6 { --i-fluid--max: 6; }
.ipsFluid--7 { --i-fluid--max: 7; }
.ipsFluid--8 { --i-fluid--max: 8; }

.ipsFluid--min-1 { --i-fluid--min: 1; }
.ipsFluid--min-2 { --i-fluid--min: 2; }
.ipsFluid--min-3 { --i-fluid--min: 3; }
.ipsFluid--min-4 { --i-fluid--min: 4; }
.ipsFluid--min-5 { --i-fluid--min: 5; }
.ipsFluid--min-6 { --i-fluid--min: 6; }

/*
	----------------
	- Columns
	----------------
*/

.ipsColumns{
	--i-basis: 300px;
	--i-column-gap: var(--i-sp_2);
	--i-row-gap: var(--i-column-gap);
	display: flex;
	flex-wrap: wrap;
	gap: var(--i-row-gap) var(--i-column-gap);
}

	.ipsColumns--reverse{
		flex-wrap: wrap-reverse;
	}

	.ipsColumns__primary{
		flex: 9999 1 55%;
	}

	.ipsColumns__secondary{
		--i-basis: auto;
		flex: 1 1 var(--i-basis);
	}

@media (max-width: 767px){
	.ipsColumns--stack{
		display: grid;
	}
}


/* Lines */
.ipsColumns--lines{
	gap: 1px;
	background-color: var(--i-background_4);
}

:where(.ipsColumns--lines > .ipsColumns__primary){
	background-color: var(--i-background_1);
}

:where(.ipsColumns--lines > .ipsColumns__secondary){
	background-color: var(--i-background_2);
}

@media (min-width: 980px){
	.ipsColumns--lines > :nth-child(1):nth-last-child(2){
		border-start-start-radius: inherit;
		border-end-start-radius: inherit;
	}

	.ipsColumns--lines > :nth-child(2):nth-last-child(1){
		border-start-end-radius: inherit;
		border-end-end-radius: inherit;
	}
}

.ipsColumns--padding .ipsColumns__primary,
.ipsColumns--padding .ipsColumns__secondary,
.ipsFluid--padding > *{
	padding: var(--i-sp_3);
}


/* v5 todo: These are old 12 column grids. Slowly merge these out over time. */
.ipsSpanGrid{
	display: grid;
	gap: var(--i-sp_2);
}

/* Support old grids from v4, but deprecate over time */
.ipsGrid:has(> [class*="ipsGrid_span"]){
	display: grid;
	gap: var(--i-sp_2);
}

@media (min-width: 768px){
	.ipsSpanGrid{
		grid-template-columns: repeat(12, 1fr);
	}
	.ipsGrid:has(> [class*="ipsGrid_span"]){
		grid-template-columns: repeat(12, 1fr);
	}
	/* These classes are prefixed to prevent .ipsSpanGrid__x from applying a width inside .ipsGrid */
	.ipsSpanGrid .ipsSpanGrid__2, .ipsGrid_span2{ grid-column: span 2; }
	.ipsSpanGrid .ipsSpanGrid__3, .ipsGrid_span3{ grid-column: span 3; }
	.ipsSpanGrid .ipsSpanGrid__4, .ipsGrid_span4{ grid-column: span 4; }
	.ipsSpanGrid .ipsSpanGrid__5, .ipsGrid_span5{ grid-column: span 5; }
	.ipsSpanGrid .ipsSpanGrid__6, .ipsGrid_span6{ grid-column: span 6; }
	.ipsSpanGrid .ipsSpanGrid__7, .ipsGrid_span7{ grid-column: span 7; }
	.ipsSpanGrid .ipsSpanGrid__8, .ipsGrid_span8{ grid-column: span 8; }
	.ipsSpanGrid .ipsSpanGrid__9, .ipsGrid_span9{ grid-column: span 9; }
	.ipsSpanGrid .ipsSpanGrid__10, .ipsGrid_span10{ grid-column: span 10; }
	.ipsSpanGrid .ipsSpanGrid__11, .ipsGrid_span11{ grid-column: span 11; }
	.ipsSpanGrid .ipsSpanGrid__12, .ipsGrid_span12{ grid-column: span 12; }
}

/*
	----------------
	- Aria toggle
	----------------
*/

:where([data-ips-animating]),
:where([data-ips-animating])::backdrop{
	--i-animation-name: initial;
	--i-animation-duration: initial;
	animation-name: var(--i-animation-name, none);
	animation-duration: var(--i-animation-duration, .25s);
	animation-timing-function: ease-in-out;
}

/* When the element is being hidden, reverse the animation */
:where([data-ips-animating="closing"]),
:where([data-ips-animating="closing"])::backdrop{
	animation-direction: reverse;
}

/* Remove animations if requested */
@media (prefers-reduced-motion: reduce){
	[data-ips-animating], [data-ips-animating]::backdrop{
		animation-duration: 0s;
	}
}

[data-ips-hidden-animation="slide"]{
	--i-animation-name: ipshidden_slide;
}

@keyframes ipshidden_slide{
	0%{
		max-height: 0;
		overflow: hidden;
	}
	100%{
		max-height: var(--i-animating-height);
		overflow: hidden;
	}
}

[data-ips-hidden-animation="slide-fade"]{
	--i-animation-name: ipshidden_slide-fade;
}

@keyframes ipshidden_slide-fade{
	0%{
		opacity: 0;
		max-height: 0;
		overflow: hidden;
	}
	100%{
		opacity: 1;
		max-height: var(--i-animating-height);
		overflow: hidden;
	}
}

[data-ips-hidden-animation="fade"]{
	--i-animation-name: ipshidden_fade;
}

@keyframes ipshidden_fade{
	from{
		opacity: 0;
	}
}

/* Apply a default animation to certain elements */
[data-ips-animating]::backdrop{
	animation-name: ipshidden_fade;
}

/* Dynamic text for aria-expanded triggers */
/* Hide trigger if content is expanded */
[aria-expanded="true"] .ipsAria__expanded-false,
[aria-expanded="false"] .ipsAria__expanded-true,
.ipsAria__expanded-hide[aria-expanded="true"]{
	display: none !important;
}


/* Transitioned details/summary */
@media (prefers-reduced-motion: no-preference) {
	details{
		interpolate-size: allow-keywords;

		&::details-content{
			height: 0;
			opacity: 0;
			overflow-y: clip;
			transition-property: content-visibility, opacity, height;
			transition-duration: .3s;
			transition-behavior: allow-discrete;
		}
		&[open]::details-content {
			height: auto;
			opacity: 1;
		}

		/* Animated height fallback */
		@supports not (interpolate-size: allow-keywords){
			&::details-content{
				display: none;
				height: auto;
				grid-template-rows: 0fr;
				transition-property: display, opacity, content-visibility, grid-template-rows;
			}
			&[open]::details-content{
				display: grid;
				grid-template-rows: 1fr;
			}
			@starting-style{
				&[open]::details-content{
					grid-template-rows: 0fr;
					opacity: 0;
				}
			}
		}
	}
}
/* This element is only needed for the fallback. It can be removed once interpolate-size is widely supported */
i-details-content{
	display: block;
}

/* ======================================================== */
/* ICON PICKER */
/* The icon picker is used to select either a font awesome icon or an emoji */

.ipsIconPicker__dialog--positioned {
	/* This prevents the icon panel from being covered up by other elements in the editor, such as new line arrows and the uploader text */
	z-index: calc(var(--ips-js-zindex-top) + 1);
	margin: 0;
}


.ipsEditor__iconpicker-wrap >  .ipsIconPicker__dialog {
	/* Make sure the icon picker is static so the editor internals can position it */
	position: static !important;
}


.ipsIconPicker__dialog {
	background: transparent;
	border-radius: var(--i-box--bo-ra);
}

.ipsIconPicker__dialog--modal {
	width: 90vw;
	max-width: 1200px;
	height: 100%;
}

.ipsIconPicker {
	--i-box--ba-co: var(--i-dropdown--ba-co);
	box-shadow: var(--i-dropdown--bo-sh);
	background: var(--i-box--ba-co);
	border-radius: var(--i-box--bo-ra);
	overflow: hidden;
	display: flex;
	flex-direction: column;
	flex: 1 1 auto;
}
	.ipsIconPicker__dialog--modal .ipsIconPicker {
		height: 100%;
		width: 100%;
	}

.ipsIconPicker__search{
	flex: 0 0 auto;
	display: flex;
	gap: .7em;
	background: var(--i-background_3);
	position: relative;
	padding: .7em;
}
	.ipsIconPicker--anchored .ipsIconPicker__search {
		background: var(--i-background_2);
		padding: 0.5em;
		gap: 0.5em;
	}

.ipsIconPicker__search::before {
	content: '\f002';
	position: absolute;
	inset-inline-start: 2em;
	align-self: center;
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	pointer-events: none;
}
	.ipsIconPicker--anchored .ipsIconPicker__search::before {
		inset-inline-start: 1.3em;
	}

.ipsIconPicker__search [type="text"]{
	flex: 1 1 100%;
	padding: .8em 1em;
	padding-inline-start: 3em;
	font-size: 1.1em;
}

	.ipsIconPicker--anchored .ipsIconPicker__search [type="text"] {
		padding: 0.5em;
		padding-inline-start: 2.4em;
		font-size: 1em;
	}

.ipsIconPicker__search [type="text"]::placeholder{
	opacity: 1;
	color: var(--i-color_soft);
}

.ipsIconPicker__close{
	width: 1.5em;
	aspect-ratio: 1;
	display: grid;
	place-content: center;
	font-size: 1.8em;
	color: var(--i-color_soft);
	margin-inline-start: auto;
}

	.ipsIconPicker__close:hover{
		color: var(--i-color_hard);
	}

.ipsIconPicker__tabs{
	display: flex;
	align-items: center;
	border-bottom: 1px solid var(--i-background_3);
	padding: .5em;
	flex: 0 0 auto;
}

.ipsIconPicker__tabs [data-role="tabs"]{
	--i-co: var(--i-color_soft);
	--hover-co: var(--i-color_hard);
	--hover-ba-co: var(--i-background_3);
	--active-co: var(--i-secondary-contrast);
	--active-ba-co: var(--i-secondary);
	display: flex;	
	gap: .5em;
}
	.ipsIconPicker--anchored .ipsIconPicker__tabs [data-role="tabs"] {
		flex-grow: 1;
		justify-content: stretch;
	}
		.ipsIconPicker--anchored .ipsIconPicker__tabs [data-role="tabs"] > button {
			flex-grow: 1;
			text-align: center;
			font-size: 12px;
			padding: 0.6em;
		}

.ipsIconPicker__tabs [data-role="tabs"] button{
	--i-outline-offset: -2px;
	display: block;
	padding: 0.8em 1.4em;
	border-radius: 5px;
	font-weight: 600;
}

	.ipsIconPicker__tabs [data-role="tabs"] button:where(:hover){
		color: var(--hover-co);
		background: var(--hover-ba-co);
	}

	.ipsIconPicker__tabs [data-role="tabs"] [data-active]{
		color: var(--active-co);
		background: var(--active-ba-co);
	}

.ipsIconPicker__category-title{
	padding: 1em;
	background: var(--i-background_1);
	color: var(--i-color_soft);
	position: -webkit-sticky;
	position: sticky;
	top: 0;
	z-index: 3;
	font-weight: 600;
}
	.ipsIconPicker--anchored .ipsIconPicker__category-title {
		padding: 0.5em;
		top: -1px; /* Pretty sure this is a subpixel rendering thing (since the positioner sets the panel's position to a decimal px value), but for some reason setting this to 0 occasionally results in a thin sliver of visible emojis/icons between the header and the search area when left as 0 */
		background: var(--i-background_2);
	}

.ipsIconPicker [data-role="iconarea"], .ipsIconPicker__selectedIcons {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(clamp(55px, 7vw, 80px), 1fr));
	text-align: center;
	padding: 1em;
	content-visibility: auto;
}

/* Only render the button when it's in the view port. Reserve a height for it to reduce jumpy scrolling */
.ipsIconPicker__option{
	content-visibility: auto;
	contain-intrinsic-size: auto clamp(55px, 7vw, 80px);
}

	/* A 40px grid for anchored icon menus */
	.ipsIconPicker--anchored [data-role="iconarea"] {
		grid-template-columns: repeat(auto-fill, minmax(40px, 1fr));
		padding: 0.5em;
	}
		.ipsIconPicker--anchored .ipsIconPicker__root-icon-area--empty {
			display: flex;
			align-items: center;
			justify-content: center;
		}

.ipsIconPicker [data-role="iconpicker_item"] {
	display: grid;
	place-content: center;
	border-radius: min(var(--i-design-radius), 5px);
	aspect-ratio: 1;
	position: relative;
}
	.ipsIconPicker [data-role="iconpicker_item"][data-icon-selected]::after {
		content: '×';
		background: var(--i-secondary);
		color: var(--i-secondary-contrast);
		position: absolute;
		inset-inline-end: 4px;
		top: 4px;
		border-radius: 50%;
		font-size: 14px;
		font-weight: bold;
		height: 1.2em;
		width: 1.2em;
		line-height: 1;
		text-align: center;
	}

	.ipsIconPicker [data-role="iconpicker_item"]:hover {
		background: var(--i-background_2);
	}

	.ipsIconPicker [data-role="iconpicker_item"]:is(.ipsIconPicker__option--active, :focus, :focus-visible) {
		z-index: 1;
		outline: var(--i-outline-width) var(--i-outline-style) var(--i-outline-color);
		outline-offset: var(--i-outline-offset);
		background: var(--if-light, var(--i-background_3)) var(--if-dark, var(--i-background_5));
	}

	.ipsIconPicker [data-role="iconpicker_item"][disabled]{
		filter: grayscale(1) opacity(60%);
		pointer-events: none;
		cursor: not-allowed;
	}

.ipsIconPicker__option {
	font-size: 42px; /* The FA SVGs render at around 42 px on average, should make emojis a similar size */
	display: grid;
	place-content: center;
	/* Prevent overflow from long (broken) emojis. The small amount of padding helps to prevent FA icons from being clipped if they slightly overflow their box */
	overflow: hidden;
	padding: 2px;
	/* Ensure all symbols are displayed as emoji */
	font-family: "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
}
	/* Emoji font size */
	.ipsIconPicker--anchored [data-role="emojiarea"] .ipsIconPicker__option {
		font-size: 28px;
		overflow: hidden;
	}
	/* FA font size */
	.ipsIconPicker--anchored [data-role="faarea"] .ipsIconPicker__option {
		font-size: 20px;
	}
	/* Stickers/custom emoticons */
	.ipsIconPicker__option img{
		object-fit: scale-down;
		width: 80%;
		height: 80%;
	}

.ipsIconPicker__option svg {
	width: 1em;
}

.ipsIconPicker__title{
	display: none;
}

.ipsIconPicker__container {
	color: var(--i-color_soft);
	display: flex;
	flex-direction: column;
	position: relative;
	flex: 1 1 auto;
}
.ipsLoading [data-role="iconpicker_item"] {
	content-visibility: hidden;
}

.ipsIconPicker__fa-attribution{
	position: absolute;
	top: 1em;
	inset-inline-end: 1.3em;
	z-index: 10;
	font-weight: 600;
	color: var(--i-color_soft);
	font-size: .9em;
}
	.ipsIconPicker--anchored .ipsIconPicker__fa-attribution{
		top: revert;
		bottom: 0;
		padding-top: 0.25em;
		padding-left: 0.5em;
		background-color: var(--i-background_1);
		inset-inline-end: 1em;
		border-top-left-radius: 0.25em;
	}

	[data-role="emojiarea"] .ipsIconPicker__fa-attribution{
		display: none;
	}

	.ipsIconPicker__fa-attribution i{
		font-size: .8em;
		margin-inline-start: .3em;
	}

.ipsIconPicker [data-role="icons"] {
	overflow-y: scroll;
	overflow-x: hidden;
	flex: 1 1 auto;
	overscroll-behavior: contain;
	height: 100%;
}
	.ipsIconPicker--anchored [data-role="icons"] {
		min-height: 50px;
		min-width: 280px;
		scrollbar-width: thin;
		padding-bottom: 0.8em;
	}

	.ipsIconPicker--panel [data-role="icons"] {
		overflow-y: auto;
		scrollbar-width: none;
		padding-bottom: 0;
	}

	.ipsIconPicker .ipsLoading * {
		opacity: 0;
	}

	/* No results */
	.ipsIconPicker__root-icon-area--empty{
		display: grid;
		place-content: center;;
	}

.ipsIconPicker__search [data-role="type_selectors"]{
	flex: 0 0 auto;
	display: flex;
}

/* Hide selector parent if it's empty (FA icons don't have color options) */
/* Hide all selectors if FA tab is selected */
.ipsIconPicker__search [data-role="type_selectors"]:not(:has(*)),
.ipsIconPicker:has([data-tab="fa"][data-active]) [data-role="type_selectors"]{
	display: none;
}

	.ipsIconPicker__search [data-role="type_selectors"] select {
		font-size: 20px;
		padding: 0 0.8em;
		padding-inline-end: calc(1.1em + 12px);
		background-size: auto 12px;
		background-position: calc(100% - 0.8em) 50%;
	}

		/* todo when we upgrade the emoji data list to a version of unicode past 15.0, there will be wider hair style support. At this point, we should unhide this; at the time of creating the iconpicker feature, there were only 3 base emojis that supported hair styles */
		.ipsIconPicker__search [data-role="type_selectors"] select[data-field="hair"] {
			display: none;
		}

/* Hide "Selected icons" if it's empty */
.ipsIconPicker [data-role="selected_icons"]:not(:has([data-role="iconpicker_item"])){
	display: none;
}


/**
These support the icon picker implemented as a dropdown and suggestion panel via tiptap
 */

/* Dropdown toolbar menu */
.ipsIconPicker--anchored {
	width: 340px;
	max-width: 95vw;
	height: 450px;
	--i-arrow-border-top: 0;
	--i-arrow-border-bottom: 1;
}

/* Shortcode menu */
.ipsIconPicker__dialog--panel:not(.ipsIconPicker__dialog--positioned) .ipsIconPicker {
	display: none;
}
.ipsIconPicker--panel {
	max-height: 300px;
	width: 300px;
	height: revert;
}

	.ipsIconPicker--panel [data-role="iconarea"]{
		display: block;
	}

	/* Show shortcodes in this menu */
	.ipsIconPicker--panel [data-role="iconpicker_item"]{
		display: flex;
		aspect-ratio: auto;
		align-items: center;
		justify-content: start;
		gap: .8em;
		width: 100%;
		outline-width: 0 !important;
		padding: 0 0.4em;
		overflow: hidden;
	}

	.ipsIconPicker--panel [data-role="iconpicker_item"]:is(.ipsIconPicker__option--active, :focus-visible){
		background: var(--if-light, var(--i-background_3)) var(--if-dark, var(--i-background_5));
	}

	.ipsIconPicker--panel [data-role="emojiarea"] .ipsIconPicker__option{
		font-size: 23px;
	}

	.ipsIconPicker--panel .ipsIconPicker__option[data-icon-title]::after{
		display: block;
		font-family: var(--i-font-family);
		font-size: 0.8rem;
		color: var(--i-color_soft);
		content: attr(data-icon-title);
	}

	/* Shift contextual panel away from text */
	.ipsIconPicker__dialog--panel {
		margin-top: 10px !important;
	}

	.ipsIconPicker__dialog--panel.ipsIconPicker__dialog--popup {
		margin-top: -10px !important;
	}

	.ipsIconPicker--panel :is(.ipsIconPicker__tabs, .ipsIconPicker__search, .ipsSubmitRow, .ipsIconPicker__category-title),
	.ipsIconPicker--anchored :is(.ipsSubmitRow, .ipsIconPicker__close, [data-role="selected_icons"]) {
		display: none;
	}
	.ipsIconPicker--panel::after {
		--i-arrow-offset: calc(sqrt(2) * -1); /* The arrow borders are at a 45degree angle, so the shadow has to be offset by this much to make the effective "border" 1px */
		--i-arrow-sh-co: color-mix(in srgb, var(--i-color_hard) 10%, transparent);
		content: "";
		position: absolute;
		bottom: 100%;
		left: clamp(10px, 1px * var(--i-arrow-left, 0) - 8px, 100% - 10px);
		height: 16px;
		width: 16px;
		filter: drop-shadow(var(--i-arrow-sh-co) 0px calc(1px * var(--i-arrow-offset)) 0px);
		border: 8px solid transparent;
		border-top-color: var(--i-box--ba-co);
		border-bottom-color: var(--i-box--ba-co);
		border-top-width: calc(var(--i-arrow-border-top) * 8px);
		border-bottom-width: calc(var(--i-arrow-border-bottom) * 8px);
	}

	.ipsIconPicker__dialog--popup .ipsIconPicker--panel::after {
		--i-arrow-offset: calc(sqrt(2));
		top:100%;
	}

	.ipsIconPicker--anchored .ipsIconPicker__container {
		min-height: 80px;
	}

/*
	----------------
	- Avatars and thumbnails
	----------------
*/

.ipsUserPhoto, .ipsThumb{
	color: var(--i-co);
	aspect-ratio: 1;
	vertical-align: top;
	overflow: hidden;
	max-width: 100%;
}

/* We don't use inline-grid here since it caused some laggy behavior in Safari */
.ipsUserPhoto{
	border-radius: var(--i-avatar--bo-ra);
	display: inline-block;
	position: relative;
	background: var(--i-background_3);
	width: 100px;
}

	.ipsUserPhoto img{
		border-radius: inherit; /* Improved rendering in Safari */
		position: absolute;
		top: 0;
		left: 0;
		width: 100%;
		height: 100%;
		/* Some images are uploaded via the ACP, without being cropped into a square */
		object-fit: cover;
	}

.ipsUserPhoto--tinier {
	width: 24px;
}

.ipsUserPhoto--tiny {
	width: 34px;
}

.ipsUserPhoto--mini {
	width: 44px;
}

.ipsUserPhoto--small {
	width: 54px;
}

.ipsUserPhoto--medium {
	width: 75px;
}

.ipsUserPhoto--large {
	width: 90px;
}

.ipsThumb{
	--i-ipsThumb--ratio: 1;
	display: inline-grid;
	aspect-ratio: var(--i-ipsThumb--ratio);
	border-radius: var(--i-thumb--bo-ra);
}

	/* Empty thumbs contain an <i> element which we style into an icon */
	.ipsThumb > i{
		container-type: size;
		display: grid;
		place-content: center;
		opacity: .1;
		overflow: hidden;
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-style: normal;
		font-weight: 900;
		/* Fix alignment in Safari */
		line-height: 0;
	}

	.ipsThumb:not(:has(img)){ background-color: var(--i-background_3) }

	:where(.ipsThumb i)::before{
		content: "\f03e";
		font-size: 40cqmin;
	}

.ipsThumb > img,
.ipsThumb > i{
	width: 100%;
	height: 100%;
	grid-area: 1/1;
}

	.ipsUserPhoto::after, .ipsThumb::after{
		content: "";
		pointer-events: none;
		border-radius: inherit;
		grid-area: 1/1;
	}
	.ipsUserPhoto::after{
		position: absolute;
		inset: 0;
	}

		:where(a.ipsUserPhoto, a.ipsThumb):hover::after{
			background: color-mix(in srgb, var(--i-color_root) 10%, transparent);
		}

	.ipsThumb img{
		object-fit: cover;
		border-radius: inherit;
	}

/* Legacy browers (Safari 14) */
@supports not (aspect-ratio: 1){
	.ipsThumb{
		position: relative;
	}
	.ipsThumb img{
		position: absolute;
	}
	.ipsThumb::before,
	.ipsUserPhoto::before{
		content: "";
		display: block;
		padding-top: 100%;
	}
}

/* Display rank and moderator/admin status */
.ipsAvatarStack{
	position: relative;
}

	.ipsAvatarStack__badge{
		position: absolute;
		z-index: 1;
		inset-inline-end: 0;
		inset-block-start: 0;
		display: flex;
		justify-content: center;
		align-items: center;
		width: min(2.2em, 60%);
		aspect-ratio: 1;
		font-size: calc(var(--i-rem) * .8);
		background: var(--i-background_dark);
		color: hsl(0 0% 100%);
		border: 2px solid var(--i-background_1);
		border-radius: 50%;
		margin-block-start: -.5em;
		margin-inline-end: -.5em;
	}

		.ipsAvatarStack__badge::before{
			content: var(--_icon, none);
			font-family: var(--i-font-awesome);
			-webkit-font-smoothing: antialiased;
			text-rendering: auto;
			font-style: normal;
			font-weight: 900;
			font-size: .8em;
		}

		/*.ipsAvatarStack__badge--moderator{
			--_icon: "\f023";
		}*/
		.ipsAvatarStack__badge--new{
			--_icon: "\f256";
		}

	.ipsAvatarStack__rank{
		position: absolute;
		z-index: 1;
		inset-inline-start: -5%;
		inset-block-end: -5%;
		width: max(30%, 17px);
		--bo-wi: 2px;
		filter: drop-shadow( var(--bo-wi) 0 0 var(--i-background_1) ) drop-shadow( 0 var(--bo-wi) 0 var(--i-background_1) ) drop-shadow( calc( var(--bo-wi) * -1 ) 0 0 var(--i-background_1) ) drop-shadow( 0 calc( var(--bo-wi) * -1 ) 0 var(--i-background_1) );
	}

		.ipsPhotoPanel .ipsAvatarStack__rank{
			--bo-wi: 1px;
		}


/*
	----------------
	- Avatar panel
	----------------
*/

.ipsPhotoPanel{
	--i-column-gap: initial;
	--i-photoPanelAvatar: initial;
	display: flex;
	gap: var(--i-column-gap, 1em);
	align-items: start;
}
@supports (-webkit-touch-callout: none) and (not(translate: none)){
	.ipsPhotoPanel > :not(:first-child){
		margin-inline-start: var(--i-column-gap, 1em);
	}
}

	.ipsPhotoPanel > .ipsUserPhoto,
	.ipsPhotoPanel .ipsAvatarStack{
		flex: 0 0 auto;
		width: var(--i-photoPanelAvatar, 2.5em);
	}

	.ipsPhotoPanel__text{
		flex: 999 1 auto;
		display: grid;
		gap: .1em 1.5em;
		line-height: 1.3;
		align-self: center;
	}

		.ipsPhotoPanel__primary{
			font-weight: 500;
		}

		.ipsPhotoPanel__secondary{
			color: var(--i-color_soft);
			font-size: inherit; /* For <small> elements */
		}

		@container (max-width: 720px){
			.ipsPhotoPanel__secondary:has(.ipsUsername){
				color: inherit;
			}
		}

			.ipsPhotoPanel__secondary a{
				color: inherit;
			}

.ipsPhotoPanel--small{
	--i-column-gap: .6em;
	--i-photoPanelAvatar: 1.4em;
}

/* Inline photo panels: Used in ipsPageHeader */
.ipsPhotoPanel--inline{
	--i-column-gap: .8em;
	--i-photoPanelAvatar: 1.5em;
	align-items: center;
}

.ipsPhotoPanel--inline .ipsPhotoPanel__text{
	display: flex;
	flex-wrap: wrap;
}



/*

	----------------
	- Image Block
	----------------
*/
.ipsFigure{
	--ipsFigure--icon: "\f87c";
	color: hsl(0 0% 100%);
	display: grid;
	border-radius: min(var(--i-design-radius), 8px);
	background: oklch(40% calc(var(--i-base-c) * 40%) var(--i-base-h));
	overflow: hidden;
}

.ipsFigure--transparent{
	background: transparent;
}

.ipsFigure[style*="--_height"]{
	height: var(--_height);
}

:where(.ipsCarousel .ipsFigure:only-child){
	height: 100%;
}

	.ipsFigure a{
		color: inherit;
	}

	.ipsFigure:has(.ipsFigure__main:focus-visible){
		outline: 2px solid var(--i-color_root);
		outline-offset: 2px;
	}

	.ipsFigure > *{
		grid-area: 1/1;
		border-radius: inherit;
		position: relative;
	}

	.ipsFigure :is(a, button, input, img, video){
		pointer-events: auto;
	}

	.ipsFigure__main{
		display: grid;
		overflow: hidden;
/*		place-content: center;*/ /* Required for images which have width/height attributes */
		/* isolation: isolate; Safari video border-radius bug */
	}

		.ipsFigure__main > *{
			grid-area: 1/-1;
			object-fit: cover;
			place-self: stretch;
			width: 100%;
			height: 100%;
		}

		.ipsFigure__main > span{
			display: grid;
			place-items: center;
		}

		/* This ensures the Page Builder image carousel adheres to the height setting */
		.ipsFigure[style*="--_height"] .ipsFigure__main img{
			max-height: var(--_height, 100%);
		}

		/* "No image" and "Play" icons */
		.ipsFigure__icon,
		.ipsFigure__play{
			container-type: inline-size;
			display: grid;
			place-content: center;
			position: relative;
			z-index: 2;
		}

			.ipsFigure__icon::before,
			.ipsFigure__play::before{
				content: var(--ipsFigure--icon);
				font-family: var(--i-font-awesome);
				-webkit-font-smoothing: antialiased;
				text-rendering: auto;
				font-weight: 900;
				font-style: normal;
				opacity: .2;
				font-size: min(80px, 25cqmin);
			}

			.ipsFigure__play::before{
				content: "\f144";
				font-weight: 400;
				pointer-events: none;
				text-shadow: hsl(0 0% 0% / .2) 0px 1px 2px;
				opacity: .8;
			}

	.ipsFigure__header{
		align-self: start;
		pointer-events: none;
		padding: 1em;
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		justify-content: flex-end;
		gap: .5em;
	}

	.ipsFigure__footer{
		position: relative;
		text-shadow: hsl(0 0% 0% / .2) 0px 1px 2px;
		align-self: end;
		pointer-events: none;
		padding: 1em;
		z-index: 1;
	}

		.ipsFigure__footer a:hover{
			text-decoration: underline;
		}

		.ipsFigure__footer .ipsIndicator{
			margin-inline-end: .4em;
			color: inherit;
		}

		:where(.ipsFigure__footer > :first-child:not(:only-child)){
			font-weight: 600;
		}

		:where(.ipsFigure__footer > :last-child:not(:only-child)){
			opacity: .8;
			margin-top: .3em;
			font-size: .9em;
		}

		.ipsFigure__footer::before{
			content: '';
			position: absolute;
			inset: 0;
			top: -60px;
			z-index: -1;
			border-bottom-left-radius: inherit;
			border-bottom-right-radius: inherit;
			background-image: linear-gradient(to bottom, hsl(0 0% 0% / 0) 0%, hsl(0 0% 0% / .01) 8%, hsl(0 0% 0% / .04) 15%, hsl(0 0% 0% / .1) 22%, hsl(0 0% 0% / .17) 29%, hsl(0 0% 0% / .26) 35%, hsl(0 0% 0% / .35) 41%, hsl(0 0% 0% / .45) 47%, hsl(0 0% 0% / .55) 53%, hsl(0 0% 0% / .65) 59%, hsl(0 0% 0% / .74) 65%, hsl(0 0% 0% / .82) 71%, hsl(0 0% 0% / .9) 77%, hsl(0 0% 0% / .95) 84%, hsl(0 0% 0% / .98) 92%, hsl(0 0% 0%) 100%);
			opacity: .6;
		}

.ipsFigure__title{
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
	text-overflow: ellipsis;
	/* This ensures the outline isn't clipped by the overflow */
	padding: 1em;
	margin: -1em;
}

/* Ratio */
.ipsFigure--ratio{
	--_ratio: 1;
}

	.ipsFigure--ratio .ipsFigure__main{
		aspect-ratio: var(--_ratio);
	}

/* Contain */
:is(.ipsFigure--contain, .ipsMasonry) .ipsFigure__main > :is(video, img){
	object-fit: scale-down;
	width: auto;
	height: auto;
	max-width: 100%;
}

/* Add a blurred image in the background for --contain styles, if a background-image exists */
.ipsFigure--contain[style*="--_backdrop"]{
	background-image: var(--_backdrop);
	background-size: cover;
	background-position: 50%;
}

.ipsFigure--contain[style*="--_backdrop"] .ipsFigure__main{
	background: hsl(0 0% 0% / .5);
	-webkit-backdrop-filter: blur(80px);
	backdrop-filter: blur(80px);
}

/* Hover effect */
@media (any-hover:hover){
	.ipsFigure--hover .ipsFigure__footer{
		transition: opacity .15s linear;
		opacity: 0;
	}
		.ipsFigure--hover:hover .ipsFigure__footer,
		.ipsFigure--hover .ipsFigure__footer:focus-within{
			opacity: 1;
		}
}

.ipsNsfwOverlay{
	-webkit-backdrop-filter: blur(30px) brightness(.9);
	backdrop-filter: blur(30px) brightness(.9);
	display: grid;
	place-content: center;
	font-weight: 600;
	padding: .5em;
	text-align: center;
	z-index: 2;
	container-type: inline-size;
}

	/* If the overlay doesn't contain any content (just the icon, which typically happens for smaller thumbnails), then make sure the link is clickable */
	.ipsNsfwOverlay--no-content{
		pointer-events: none;
	}
		/* Show the NSFW icon if the overlay has no text/button */
		.ipsNsfwOverlay--no-content::before{
			content: '\f070';
			font-family: var(--i-font-awesome);
			-webkit-font-smoothing: antialiased;
			text-rendering: auto;
			font-weight: 400;
			color: hsl(0 0% 100% / .6);
			font-size: min(80px, 20cqmin);
		}

	.ipsNsfwOverlay button{
		background: hsl(0 0% 100% / .2);
		border-radius: 5px;
		padding: .5em 1.2em;
		margin-top: 1em;
		place-self: center;
	}

		.ipsNsfwOverlay button:hover{
			background: hsl(0 0% 100% / .3);
		}

.ipsFigure:has(.ipsNsfwOverlay) :is(.ipsFigure__header, .ipsFigure__footer),
.ipsFigure__header:not(:has(*)){
	display: none;
}

/* Simplify the NSFW overlay on small screens when used in the masonry layout */
@media (max-width: 767px){
	.ipsMasonry .ipsNsfwOverlay{
		pointer-events: none;
	}
		.ipsMasonry .ipsNsfwOverlay *{
			display: none;
		}
		.ipsMasonry .ipsNsfwOverlay::before{
			content: '\f070';
			font-family: var(--i-font-awesome);
			-webkit-font-smoothing: antialiased;
			text-rendering: auto;
			font-weight: 400;
			grid-area: 1/-1;
			display: grid;
			place-content: center;
			opacity: .6;
			font-size: min(80px, 20cqmin);
		}
}

.ipsData__icon .ipsFigure__main{
	aspect-ratio: 1;
}


/*
	----------------
	- Fallback image
		* Used in cover photos and some grid UI's
		* A random color is assigned (from a predefined list) based on the nth-child selector
	----------------
*/

.ipsFallbackImage{
	background-color: var(--i-empty-image--ba-co, oklch(var(--if-light, 60% 25%) var(--if-dark, 35% 15%) var(--_hue, var(--i-base-h))));
	display: grid;
	border-radius: inherit;
	overflow: hidden;
}

	.ipsFallbackImage::before{
		content: '';
		background-image: url('{resource="pattern.svg" app="core" location="global" inCss="true"}');
		background-size: cover;
		background-position: 50%;
		mix-blend-mode: overlay;
		opacity: .5;
	}

/* Default pattern image */
.ipsCoverPhoto__container .ipsFallbackImage{
	position: absolute;
	inset: 0;
}

/* "Random" background color */
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 7) .ipsFallbackImage){ --_hue: 0; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 6) .ipsFallbackImage){ --_hue: 45; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 5) .ipsFallbackImage){ --_hue: 90; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 4) .ipsFallbackImage){ --_hue: 135; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 3) .ipsFallbackImage){ --_hue: 180; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 2) .ipsFallbackImage){ --_hue: 225; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 1) .ipsFallbackImage){ --_hue: 270; }
:where(:is(.ipsData__item, .ipsData__blog-item):nth-child(8n - 0) .ipsFallbackImage){ --_hue: 315; }

/*
	----------------
	- Inputs
	- All inputs (checkbox, radio, text, number, range, etc) use .ipsInput
	----------------
*/

.ipsInput:where(:not([type="checkbox"], [type="radio"], [type="range"])){
	--i-co: currentColor;
	--i-outline-width: 0px;
	background-color: var(--i-input--ba-co);
	border-radius: var(--i-input--bo-ra);
	border: var(--i-input--bo-wi) var(--i-input--bo-st, solid) var(--i-input--bo-co);
	box-shadow: var(--i-input--bo-sh, none);
	color: var(--i-co);
	display: inline-flex;
	padding: var(--i-input--pa-bl) var(--i-input--pa-in);
	width: 100%;
	max-width: 100%; /* Necessary if width is overwritten somewhere */
	vertical-align: middle;
}

.ipsEditor__tiptap-wrap--codeMode {
	--i-outline-width: 0px;
	background-color: var(--i-box--ba-co);
	border-radius: var(--i-input--bo-ra);
	border: var(--i-input--bo-wi) var(--i-input--bo-st, solid) var(--i-input--bo-co);
	box-shadow: var(--i-input--bo-sh, none);
}

:where([data-ips-scheme="light"]) :where(.ipsInput:not([type="checkbox"], [type="radio"], [type="range"])){
	background-clip: padding-box;
}

@media (any-hover:hover){
	.ipsInput:where(:not([type="checkbox"], [type="radio"], [type="range"], .ipsInput--pseudo)):hover{
		border-color: var(--i-input-hover--bo-co);
	}
}

/* Mobiles/tablets */
@media (hover: none) and (max-width: 1024px) {
	.ipsInput:where(:not([type="checkbox"], [type="radio"], [type="range"])){
		font-size: max(16px, 1em);
	}
}

.ipsInput:focus-within,
.ipsInput:where(:not([type="checkbox"], [type="radio"], [type="range"])):focus{
	outline: 2px solid var(--i-input-active--bo-co);
	outline-offset: -1px;
}

.ipsInput::placeholder{
	color: inherit;
	opacity: var(--i-placeholder--op, .75);
}

.ipsInput:where([type="number"], [type="date"], [type="time"]){
	width: auto;
}

.ipsInput[type="number"]:is([size="3"], [size="4"], [size="5"], [size="6"], [size="7"], [size="8"], [size="9"], [size="10"]){
	width: calc(4ch + var(--_size, 3) * 1ch);
	padding-inline: 0;
	text-align: center;
}

.ipsInput[type="number"][size="4"]{
	--_size: 4;
}
.ipsInput[type="number"][size="5"]{
	--_size: 5;
}
.ipsInput[type="number"][size="6"]{
	--_size: 6;
}
.ipsInput[type="number"][size="7"]{
	--_size: 7;
}
.ipsInput[type="number"][size="8"]{
	--_size: 8;
}
.ipsInput[type="number"][size="9"]{
	--_size: 9;
}
.ipsInput[type="number"][size="10"]{
	--_size: 10;
}

/* Stripe inputs are handled by an iframe. Since the text is always black, invert the iframe in dark mode to make the text readable */
[data-ips-scheme="dark"] .ipsInput--stripeInput iframe{
	filter: invert(1);
}

/* Fluid */
.ipsInput--fluid{
	field-sizing: content;
}

/* Range */
.ipsInput:where([type="range"]) {
	flex: 1 1 auto; /* Used in ACP for alignment with current/max value */
	--i-co: var(--i-color_root);
	--_track--op: .2;
	-webkit-appearance: none;
	appearance: none;
	background: transparent;
	cursor: ew-resize;
	width: 100%;
	border: 0;
	height: 1.4em;
	box-shadow: none;
	padding: 0;
	color: var(--i-co);
	outline: none !important;
}

.ipsInput:where([type="range"]):focus-visible::-webkit-slider-thumb{
	outline: 2px solid var(--i-input-active--bo-co);
	outline-offset: 4px;
}
.ipsInput:where([type="range"]):focus-visible::-moz-range-thumb{
	outline: 2px solid var(--i-input-active--bo-co);
	outline-offset: 4px;
}

.ipsInput:where([type="range"]):is(:hover, :focus-visible){
	--_track--op: .5;
	--_thumb--sc: 1;
}

.ipsInput:where([type="range"])::-webkit-slider-runnable-track {
	background: currentColor;
	opacity: var(--_track--op);
	height: 5px;
	border-radius: 3px;
	transition: .2s;
}
.ipsInput:where([type="range"])::-moz-range-track {
	background: currentColor;
	opacity: var(--_track--op);
	height: 5px;
	border-radius: 3px;
	transition: .2s;
}

.ipsInput:where([type="range"])::-webkit-slider-thumb {
	-webkit-appearance: none;
	appearance: none;
	margin-top: -6px;
	background-color: var(--i-co);
	border: none;
	height: 16px;
	width: 8px;
	border-radius: 3px;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	box-shadow: var(--i-background_1) 0px 0px 0px 2px;
}
.ipsInput:where([type="range"])::-moz-range-thumb {
	background-color: var(--i-co);
	border: none;
	height: 16px;
	width: 8px;
	border-radius: 3px;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	box-shadow: var(--i-background_1) 0px 0px 0px 2px;
}

@media(hover:none){
	.ipsInput:where([type="range"])::-webkit-slider-thumb {
		width: 40px;
		height: 20px;
		margin-top: -10px;
		border-radius: 6px;
		transform: none;
	}
}


/* Colors */
.ipsInput:where([type="color"]) {
	padding: 0;
	border-radius: inherit;
	height: 100%;
	opacity: 0;
}

.ipsInput:where([type="color"])::-moz-color-swatch {
	border:none;
	padding: 0;
	margin: 0;
}

.ipsInput:where([type="color"])::-webkit-color-swatch {
	border: none;
	padding: 0;
	margin: 0;
}

.ipsInput:where([type="color"])::-webkit-color-swatch-wrapper {
	padding: 0;
	margin: 0;
	border: none;
}

.ipsInput__color-wrap {
	--i-co-inverse: #000;
	--i-co: #fff;
	display: flex;
	gap: .5em;
	align-items: center;
}

.ipsInput__color-wrap-inner {
	display: inline-flex;
	justify-content: stretch;
	min-width: 50px;
	border-radius: calc(var(--i-button--bo-ra, 3) * 1px);
	/*overflow: hidden;*/
	height: 2em;
	height: 2lh;
	position: relative;
	flex-basis: 14ch;
	border: 1px solid color-mix(in srgb, var(--i-color_soft) 20%, transparent);
	background: var(--i-co);
}
.ipsInput__color-wrap-inner input {
	cursor: pointer;
}

.ipsInput__color-wrap-inner .ipsInput__color-iro-container {
	display: none;
}

.ipsInput__color-wrap-inner .ipsInput__color-iro-container--open {
	display: block;
	position: absolute;
	top: 100%;
	z-index: var(--ips-js-zindex-top);
}

.ipsInput--color-disabled {
	background: none;
	position: relative;
}

.ipsInput--color-disabled::before,
.ipsInput--color-disabled::after {
	position: absolute;
	content: "";
	inset: 0;
}
.ipsInput--color-disabled::before {
	background: var(--i-background_1);
}
.ipsInput--color-disabled::after, .ipsCheckerboard {
	--i-ch-fg: color-mix(in srgb, var(--i-background_1) 75%, var(--i-color_root));
	background-image: linear-gradient(45deg, var(--i-ch-fg) 25%, transparent 25%), linear-gradient(-45deg, var(--i-ch-fg) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, var(--i-ch-fg) 75%), linear-gradient(-45deg, transparent 75%, var(--i-ch-fg) 75%);
	background-size: 1lh 1lh;
	background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
}


.ipsInput--color-disabled input[type='color']:not(:active, :focus-within) {
	opacity:0;
}

.ipsInput__color-label {
	position: absolute;
	inset: 0;
	display: inline;
	align-content: center;
	padding: 0 1em;
	color: var(--i-co-inverse);
	border-radius: inherit;
}

.ipsInput__color-label:focus-visible {
	outline-offset: 0;
	outline-color: black;
}

/* Add arrow to select elements */
select.ipsInput{
	padding: var(--i-input--pa-bl) var(--i-input--pa-in);
	padding-inline-end: calc(var(--i-input--pa-in) * 3);
	background-image: var(--i-select--arrow);
	background-size: auto 1em;
	background-repeat: no-repeat;
	background-position: calc(100% - 1em) 50%;
}

	[dir="rtl"] select.ipsInput{
		background-position: 1em 50%;
	}

	/* Smaller selects */
	select.ipsInput:is([name*="[day]"], [name*="[month]"], [name*="[year]"]){
		width: auto;
	}

/* Multi-select */
@media not (hover:none){
	select.ipsInput[multiple]{
		background-image: none;
		padding-inline-end: var(--i-input--pa-in);
	}
}
select.ipsInput[multiple] option:hover{
	background-color: var(--i-background_3);
}

select.ipsInput[multiple] option:checked{
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
}

/* Auto widths */
.ipsInput--auto{
	width: auto;
}

/* Larger inputs. The middle selector caters for auto-completes */
.ipsInput--primary,
.ipsInput--primary input,
.ipsFieldRow--primary input {
	font-size: 1.2em;
}

/* v5 todo: Only used in Commerce.. */
.ipsInput--dummy{
	min-height: 2em;
}

/* Hide 'x' in search input */
.ipsInput::-webkit-search-cancel-button{
	display: none;
}

:where(textarea).ipsInput{
	height: auto;
	padding: var(--i-input--pa-bl) var(--i-input--pa-in);
	resize: vertical;
}

/* Disabled */
.ipsInput:disabled{
	opacity: .4;
	font-style: italic;
	pointer-events: none;
}

.ipsInput:disabled{
	background-color: var(--i-background_3);
}

/* Monospace textarea */
textarea.ipsField_codeInput {
	font-family: "Courier New", Courier, monospace;
}

/* Autocomplete menus (tags, assign to, etc) */
[data-controller="core.global.core.prefixedAutocomplete"]{
	display: flex;
	flex-wrap: wrap-reverse;
	gap: .5em;
}

	/* Topic prefix select menu */
	.ipsFieldRow__content [data-role="prefixRow"] {
		flex: 1 0 auto;
	}

		.ipsFieldRow__content [data-role="prefixRow"] .ipsButton {
			height: 100%;
			width: 100%;
		}

/* Choose Tag(s) input */
.ipsAutoComplete__list{
	display: flex;
	flex-wrap: wrap;
	gap: .3em;
	/* Necessary for the "clickable Add Tags" panel, using the ::before element */
	isolation: isolate;
}

	.ipsAutoComplete__add {
		flex-grow: 1;
	}
	.ipsAutoComplete__add > input[type="text"] {
		width: 100%;
		height: 100%;
	}

	.ipsAutoComplete__add:not(:first-child){
		margin-inline-start: 1em;
	}
	/* Make the "Choose Tag(s)" option expand to full width. This makes the entire input area clickable instead of just the text. */
	.ipsAutoComplete__add [data-action="addToken"]::before{
		content: '';
		position: absolute;
		inset: 0;
		z-index: -1;
	}

		.ipsAutoComplete__add [data-action="addToken"]{
			display: block;
			font-size: .9em;
			color: var(--i-color_root);
			padding: 0 .6em;
			line-height: 2;
		}
		.ipsAutoComplete__add [data-action="addToken"]:hover{
			color: var(--i-color_hard);
		}

	/* Tokens */
	.cToken {
		--_co: var(--i-color_primary);
		background-color: var(--i-background_4);
		background-color: color-mix(in srgb, currentColor 10%, transparent);
		color: var(--_co);
		display: inline-flex;
		font-size: .9em;
		border-radius: min(5px, var(--i-design-radius));
		padding: 0 1em;
		cursor: pointer;
		max-width: 100%;
		overflow: hidden;
		font-weight: 500;
		line-height: 2;
	}

		.cToken.cToken_selected {
			--_co: var(--i-primary-contrast);
			background: var(--i-primary);
		}

		.cToken_close{
			padding: 0 .5em;
			margin-inline-start: 1em;
			margin-inline-end: -1em;
			border-inline-start: 1px solid color-mix(in srgb, var(--_co) 9%, transparent);
		}

		.cToken_close:not(:hover){
			opacity: .6;
		}

		.cToken_close:hover{
			background: color-mix(in srgb, var(--_co) 7%, transparent);
		}

.ipsAutocompleteMenu {
	background: var(--i-dropdown--ba-co);
	box-shadow: var(--i-dropdown--bo-sh);
	border-radius: var(--i-dropdown--bo-ra);
	z-index: var(--ips-js-zindex-top, 9999);
	position: absolute;
	top: 100%;
	left: 0;
	width: 100%;
	margin: 3px 0;
	min-width: min(300px, 90vw);
}

	/* Ensure the dropdown menu is displayed correctly in an overflowing dialog */
	@supports (anchor-name: --x) {
		.ipsDialog .ipsAutocompleteMenu{
			position: fixed;
			top: anchor(bottom);
			left: anchor(left);
			right: anchor(right);
			width: auto;
			min-width: 0;
		}
	}

	.ipsAutocompleteMenu__search input{
		padding: 1em;
		border-bottom: 1px solid var(--i-background_6);
		width: 100%;
	}

	.ipsAutocompleteMenu_itemWrapper {
		max-height: 200px;
		overflow: auto;
		border-radius: inherit;
		padding: .3em;
	}
	/* No results */
	.ipsAutocompleteMenu_empty{
		padding: .9em 1.3em;
		color: var(--i-color_soft);
		font-style: italic;
		cursor: default;
		/* Cater for .3em padding on the above list */
		margin-top: -.6em;
	}
	.ipsAutocompleteMenu_item {
		padding: .6em 1em;
		border-radius: inherit;
	}

		.ipsAutocompleteMenu_item[data-selected] {
			background: var(--i-primary);
			color: var(--i-primary-contrast);
			cursor: pointer;
		}

		.ipsAutocompleteMenu_item[data-selected] *{
			color: inherit;
		}

		.ipsAutocompleteMenu_item[data-selected] .i-color_soft{
			opacity: .7;
		}

.ipsField_autocomplete {
	position: relative;
	display: block;
	padding: var(--i-input--pa-bl);
}

/* When an "item prefix" select menu is part of the UI, make the auto-complete occupy the remaining space */
[data-role="prefixRow"] ~ .ipsField_autocomplete{
	width: auto;
	flex: 999 1 300px;
}

.ipsField_autocomplete .ipsList--inline{
	--i-column-gap: .3em;
}

.ipsField_autocomplete [type="text"] {
	border: 0;
	border-radius: 0;
	padding: 0;
	background: transparent !important;
	width: 20px;
	max-width: 100%;
	box-shadow: none;
	outline: none;
}

.ipsField_autocomplete.ipsField_autocompleteDisabled {
	pointer-events: none;
}

	.ipsField_autocomplete.ipsField_autocompleteDisabled .cToken {
		opacity: 0.6;
	}

.ipsField_autocomplete_loading {
	position: absolute;
	inset-inline-end: 10px;
}

.ipsField_autocomplete_loading::before{
	content: 'loading..'
}

.ipsDialog .ipsField_autocomplete [data-action="addToken"] {
	background: var(--i-secondary);
	color: var(--i-secondary-contrast);
	display: inline-flex;
	align-items: center;
	gap: .6em;
	font-size: .9em;
	border-radius: min(5px, var(--i-design-radius));
	padding: 0 1em;
	cursor: pointer;
	max-width: 100%;
	overflow: hidden;
	font-weight: 500;
	line-height: 2;
}

/* Tooltips are shown when duplicate items are entered into the autocomplete */
.ipsAutoComplete .ipsTooltip--autoComplete{
	position: absolute;
	bottom: calc(100% + 6px);
	left: 50%;
	transform: translateX(-50%);
}
.ipsTooltip--autoComplete:not([hidden]){
	opacity: 1;
	translate: 0 0;
}
	@starting-style {
		.ipsTooltip--autoComplete:not([hidden]){
			opacity: 0;
			translate: 0 10px;
		}
	}

/* Restyle the "Assign to.." autocomplete in the reply form */
#elInput_assign_content_to_wrapper{
	--i-outline-color: var(--i-button--co);
	--i-button--co: currentColor;
	--i-button--bo-co: transparent;
	--i-button--ba-co: color-mix(in srgb, var(--i-button--co) 10%, transparent);
	--button-hover--ba-co: color-mix(in srgb, var(--i-button--co) 15%, transparent);
	--button-hover--ba-im: linear-gradient(hsl(0 0% 0% / 0) 0% 100%);

	all: revert;
	display: flex;
	position: relative;
	background-color: var(--i-button--ba-co);
	background-image: var(--button-hover--ba-im);
	border-width: 0;
	border-radius: calc(var(--i-button--bo-ra) * 1px);
	box-shadow: var(--i-button--bo-sh);

	height: calc(1em + var(--i-button--pa-bl) * 2);
}

	#elInput_assign_content_to_wrapper:hover{
		background-image: linear-gradient(var(--button-hover--ba-co) 0% 100%), var(--button-hover--ba-im);
	}

	#elInput_assign_content_to_wrapper .ipsAutoComplete__list{
		font-size: var(--i-button--fo-si, inherit);
		font-weight: var(--i-button--fo-we);
		color: var(--i-button--co);
		line-height: var(--i-button--li-he, 1);
		padding: 0;
	}

	#elInput_assign_content_to_wrapper .ipsAutoComplete__list li{
		align-items: center;
		display: inline-flex;
		background: none;
		color: currentColor;
		font-weight: 600;
	}

	#elInput_assign_content_to_wrapper [data-action="addToken"]{
		color: currentColor;
		padding: 0 var(--i-button--pa-in);
	}

	#elInput_assign_content_to_wrapper .cToken_close{
		align-self: stretch;
		display: grid;
		place-content: center;
	}

		#elInput_assign_content_to_wrapper .cToken_close::before{
			content: '';
			position: absolute;
			inset: 0;
		}

	ul.ipsButtons:has( #elInput_assign_content_to_wrapper .cToken ) [data-role="assignmentPrefix"]{
		display:inline;
	}

/* With prefix icons */
.ipsInputIcon{
	position: relative;
}

	.ipsInputIcon__icon{
		position: absolute;
		margin-top: auto;
		margin-bottom: auto;
		top: 0;
		bottom: 0;
		inset-inline-start: .8em;
		pointer-events: none;
	}

	.ipsInputIcon .ipsInput{
		padding-inline-start: 2.5em;
	}

/* Multi-language inputs */
.ipsFlagEditor{
	font-weight: 500;
	margin-bottom: .4em;
	color: var(--i-color_soft);
	display: flex;
	align-items: center;
	gap: .5em;
}

/* Error and success */
.ipsField_error, .ipsFieldRow_error :is(textarea, input, .ipsAutoComplete):not(.ipsFieldRow_errorExclude):not([type="checkbox"], [type="radio"], [type="range"], :focus, [disabled]){
	background-color: var(--i-input-error--ba-co, hsl(350 56% 93%));
	border-color: var(--i-input-error--bo-co, hsl(351 31% 60%));
	color: var(--i-input-error--co, hsl(351 72% 20%));
}
.ipsField_success, .ipsFieldRow_success :is(textarea, input):not(:focus):not([type="checkbox"], [type="radio"], [type="range"]){
	background-color: var(--i-input-success--ba-co, hsl(92 33% 92%));
	border-color: var(--i-input-success--bo-co, hsl(92 59% 30%));
	color: var(--i-input-success--co, hsl(92 72% 20%));
}

/* Different widths */
.ipsField_short{
	max-width: 200px;
}
.ipsField_medium{
	max-width: 270px;
}
.ipsField_tiny{
	max-width: 60px;
}

/* Overflowing checkboxes */
.ipsField__checkboxOverflow:not(.ipsField__checkboxOverflow--scroll) [data-role="search"]{
	display: none;
}

.ipsField__checkboxOverflow--scroll {
	display: grid;
	background-color: var(--i-input--ba-co);
	border-color: var(--i-input--bo-co);
	border-radius: var(--i-input--bo-ra);
	border-style: var(--i-input--bo-st, solid);
	border-width: var(--i-input--bo-wi);
	box-shadow: var(--i-input--bo-sh, none);
	color: var(--i-co);
	width: 100%;
}

	.ipsField__checkboxOverflow--scroll .ipsFieldList {
		padding: 1em 0;
		max-height: 200px;
		overflow-y: scroll;
	}

		.ipsField__checkboxOverflow--scroll .ipsFieldList > *{
			padding: .4em 1em;
		}

	/* Reset existing form styles */
	.ipsField__checkboxOverflow--scroll .ipsField__checkboxOverflow__search {
		max-width: none;
		border-width: 0;
		border-bottom: 1px solid var(--i-background_3);
		border-radius: 0;
		box-shadow: none;
		background: transparent;
	}

	.ipsField__checkboxOverflow--scroll .ipsField__checkboxOverflow__focused {
		background: var(--i-background_4);
	}

	/* All/none buttons */
	.ipsField__checkboxOverflow__toggles{
		padding-top: .5em;
		padding-inline-start: 2.5em;
	}

	.ipsField__checkboxOverflow__toggles button:hover{
		text-decoration: underline;
	}

	.ipsField__checkboxOverflow--scroll .ipsField__checkboxOverflow__toggles {
		padding: .8em;
		border-top: 1px solid var(--i-background_3);
	}

/* v5 todo: Does this add padding to options on Windows? */
/* Select menus */
.ipsInput option{
	padding: .6em 1em;
	color: var(--i-color_root);
	background: var(--i-background_2);
}

/* Simple select menus */
.ipsSimpleSelect{
	display: grid;
	gap: .4em;
	cursor: pointer;
}

	.ipsSimpleSelect::after{
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-style: normal;
		font-weight: 900;
		content: "\f107";
		pointer-events: none;
		grid-area: 1/-1;
		align-self: center;
		justify-self: end;
		opacity: .5;
		font-size: .8em;
		padding: 0 1em;
	}

	.ipsSimpleSelect i{
		grid-area: 1/-1;
		padding-inline-start: 1.2em;
		justify-self: start;
		align-self: center;
		opacity: .5;
		pointer-events: none;
		position: relative;
	}

	.ipsSimpleSelect select{
		padding: .5em 1em;
		padding-inline-end: 2em;
		grid-area: 1/-1;
		background: var(--i-background_3);
		border-radius: min(var(--i-design-radius), 5px);
		outline-offset: -2px;
	}

	.ipsSimpleSelect i + select{
		padding-inline-start: 3em;
	}

/* Align select content to the end */
.ipsSimpleSelect--end{
	text-align: end;
}

.ipsSimpleSelect--end select{
	direction: rtl;
	text-align: start;
	padding-inline-end: 1em;
	padding-inline-start: 2em;
}

[dir="rtl"] .ipsSimpleSelect--end select{
	direction: ltr;
}

/*
	----------------
	- Checkbox and Radio inputs
	----------------
*/

.ipsInput:where([type="checkbox"], [type="radio"]){
	-webkit-appearance: none;
	appearance: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	height: var(--i-input-toggle--size, 1.2em);
	position: relative;
	vertical-align: middle;
	width: var(--i-input-toggle--size, 1.2em);
	cursor: pointer;
	background-color: var(--i-input--ba-co);
	border-width: var(--i-input--bo-wi);
	border-style: solid;
	border-color: var(--i-input-toggle--bo-co, var(--i-input--bo-co));
	box-shadow: var(--i-input--bo-sh, none);
	flex: 0 0 auto;
}

/* Hovered and Checked */
@media (any-hover:hover){
	.ipsInput:where([type="checkbox"], [type="radio"]):hover{
		border-color: var(--i-input-hover--bo-co);
	}
}

/* Focus */
.ipsInput:where([type="checkbox"], [type="radio"]):focus-visible{
	--i-outline-color: var(--i-primary);
	border-color: var(--i-input-active--bo-co);
	outline: var(--i-outline-width) var(--i-outline-style) var(--i-outline-color);
	outline-offset: var(--i-outline-offset);
}

.ipsInput--pseudo{
	padding: 0;
	width: 1.3em;
	height: 1.3em;
	justify-content: center;
	align-items: center;
	background-clip: border-box;
	cursor: pointer;
}

.ipsInput--pseudoChecked,
.ipsInput:where([type="checkbox"], [type="radio"]):checked{
	background-color: var(--i-primary);
	color: var(--i-primary-contrast);
	border-color: transparent;
}

.ipsInput--pseudo::before,
.ipsInput:where([type="checkbox"], [type="radio"])::before{
	content: '';
	visibility: hidden;
}

	.ipsInput--pseudoChecked::before,	
	.ipsInput:where([type="checkbox"], [type="radio"]):checked::before{
		visibility: visible;
	}

/* Checkbox */
.ipsInput--pseudo,
.ipsInput:where([type="checkbox"]){
	border-radius: var(--i-input-checkbox--bo-ra, max(4px, .2em));
}

	/* Checkbox: tick */
	.ipsInput--pseudoChecked::before,
	.ipsInput:where([type="checkbox"])::before{
		content: "\f00c";
		font-family: var(--i-font-awesome);
		font-weight: 900;
		-webkit-font-smoothing: antialiased;
		display: block;
		font-style: normal;
		font-variant: normal;
		line-height: 1;
		text-rendering: auto;
		font-size: 0.75em;
	}

/* Radio */
.ipsInput:where([type="radio"]){
	border-radius: var(--i-input-radio--bo-ra, 50%);
}

	/* Radio: dot */	
	.ipsInput:where([type="radio"])::before{
		background: currentColor;
		border-radius: inherit;
		width: 40%;
		height: 40%;
	}

/* Improved click/tap area */
@media(hover:none) and (pointer:coarse){
	.ipsInput:where([type="checkbox"], [type="radio"])::after{
		content: '';
		position: absolute;
		top: 50%;
		left: 50%;
		height: max(30px, 100%);
		width: max(30px, 100%);
		transform: translate(-50%,-50%);
		cursor: pointer;
		z-index: 1;
	}
}

/* Input wrapped with label */
.ipsInputLabel{
	display: flex;
	align-items: center;
	gap: .7em;
}

	.ipsInputLabel input{
		flex: 0 0 auto;
	}

/*
	----------------
	- Label buttons
	----------------
*/

.ipsLabelButton{
	--_outline-width: 1px;
	outline: var(--_outline-width) solid var(--_border-color, color-mix(in hsl, currentColor 40%, transparent));
	outline-offset: calc(var(--_outline-width) * -1);
	border-radius: min(var(--i-design-radius), 6px);
	border-radius: var(--i-avatar--bo-ra);
	background: var(--_background, transparent);
	cursor: pointer;
	display: block;
	padding: 1em;
}

.ipsLabelButton:hover,
.ipsLabelButton:focus-within{
	outline-color: var(--_border-color--hover, color-mix(in hsl, currentColor 70%, transparent));
}

.ipsLabelButton:focus-within{
	--_outline-width: 2px;
}

.ipsLabelButton:has(:checked){
	--_outline-width: 2px;
	outline-color: var(--_border-color--checked, var(--i-primary));
}

.ipsLabelButton input{
	opacity: 0;
	position: absolute;
}

/*
	----------------
	- On/off toggle
	----------------
*/

.ipsSwitch{
	--_width: 2em;
	-webkit-appearance: none;
	appearance: none;
	display: inline-flex;
	font-size: 1.5em;
	height: 1em;
	width: var(--_width);
	vertical-align: middle;
	cursor: pointer;
	background-color: var(--i-background_6);
	/* Chrome requires the variable. Safari requires var(--i-co) instead of currentColor */
	--_bo-sh: inset color-mix(in srgb, var(--i-co) 40%, transparent) 0px 0px 0px 1px;
	box-shadow: var(--_bo-sh);
	border-radius: 50px;
	position: relative;
	transition: background 0.15s linear;
}

	.ipsSwitch::before{
		content: '';
		background: #fff;
		border-radius: inherit;
		position: absolute;
		height: 1em;
		width: 1em;
		border: 3px solid transparent;
		background-clip: padding-box;
		transition: transform .15s linear;
	}

	.ipsSwitch[data-checked],
	.ipsSwitch:checked{
		background: var(--i-color_positive);
	}

	.ipsSwitch[data-checked]::before,
	.ipsSwitch:checked::before{
		transform: translateX(calc(var(--i-lang-dir) * (var(--_width) - 100%)));
	}

	.ipsSwitch:disabled{
		cursor: not-allowed;
		filter: opacity(.25);
	}

.ipsSwitch + label{
	font-weight: 500;
	margin-inline-start: .5em;
	vertical-align: middle;
	cursor: pointer;
}


/* CodeMirror */
.CodeMirror {
	border: var(--i-input--bo-wi) var(--i-input--bo-st, solid) var(--i-input--bo-co);
	border-radius: var(--i-input--bo-ra);
	cursor: text;
}

[dir="rtl"] .CodeMirror {
	direction: ltr;
}

/* Loading */
.ipsField_loading {
	background-image: url('{resource="loaders/tiny_loading@2x.gif" inCss="true" app="core" location="front"}');
	background-size: 14px 14px;
	background-repeat: no-repeat;
	background-position: right 5px center;
}

[dir="rtl"] .ipsField_loading {
	background-position: left 5px center;
}


/* Live language translation */
.ipsField_vle {
	color: black !important;
	font-weight: normal;
}

/* Recaptcha RTL fix: from v4 */
[dir="rtl"] #recaptcha_table:not(.recaptcha_theme_clean) {
	direction: ltr !important;
}

/* Password strength */
[data-ips-scheme="light"] .ipsForm_meter{
	--i-meter_1: #C62828;
	--i-meter_2: #D84315;
	--i-meter_3: #FF8F00;
	--i-meter_4: #9E9D24;
	--i-meter_5: #2E7D32;
}
[data-ips-scheme="dark"] .ipsForm_meter{
	--i-meter_1: hsl(0 75% 80%);
	--i-meter_2: hsl(14 75% 60%);
	--i-meter_3: hsl(39 75% 60%);
	--i-meter_4: hsl(75 75% 60%);
	--i-meter_5: hsl(130 75% 61%);
}
.ipsForm_meter {
	width: 100%;
	height: 7px;
	display: block;
	margin-top: .7em;
	border-radius: 4px;
	background: color-mix(in srgb, currentColor 30%, transparent);
}

.ipsForm_meterAdvice {
	font-size: max(10px, .8em);
	font-weight: 600;
	display: block;
	margin-top: .5em;
}

	.ipsForm_meter[data-adviceValue="1"] + .ipsForm_meterAdvice { color: var(--i-meter_1);}
	.ipsForm_meter[data-adviceValue="2"] + .ipsForm_meterAdvice { color: var(--i-meter_2);}
	.ipsForm_meter[data-adviceValue="3"] + .ipsForm_meterAdvice { color: var(--i-meter_3);}
	.ipsForm_meter[data-adviceValue="4"] + .ipsForm_meterAdvice { color: var(--i-meter_4);}
	.ipsForm_meter[data-adviceValue="5"] + .ipsForm_meterAdvice { color: var(--i-meter_5);}

.ipsForm_meter::-webkit-meter-bar {
	border-radius: 4px;
	background: color-mix(in srgb, currentColor 30%, transparent);
}

/* Webkit based browsers */
.ipsForm_meter[data-adviceValue="1"]::-webkit-meter-optimum-value { background: var(--i-meter_1); }
.ipsForm_meter[data-adviceValue="2"]::-webkit-meter-optimum-value { background: var(--i-meter_2); }
.ipsForm_meter[data-adviceValue="3"]::-webkit-meter-optimum-value { background: var(--i-meter_3); }
.ipsForm_meter[data-adviceValue="4"]::-webkit-meter-optimum-value { background: var(--i-meter_4); }
.ipsForm_meter[data-adviceValue="5"]::-webkit-meter-optimum-value { background: var(--i-meter_5); }

/* Gecko based browsers */
.ipsForm_meter[data-adviceValue="1"]::-moz-meter-bar { background: var(--i-meter_1); }
.ipsForm_meter[data-adviceValue="2"]::-moz-meter-bar { background: var(--i-meter_2); }
.ipsForm_meter[data-adviceValue="3"]::-moz-meter-bar { background: var(--i-meter_3); }
.ipsForm_meter[data-adviceValue="4"]::-moz-meter-bar { background: var(--i-meter_4); }
.ipsForm_meter[data-adviceValue="5"]::-moz-meter-bar { background: var(--i-meter_5); }


