}
:where(:is(.ipsHeader__end, .ipsHeaderExtra__end) [data-ips-header-content] > *){
	margin-inline-start: auto;
}

.ipsHeader__top{
	--i-co: var(--i-headerTop--co);
	--i-header-row--he: var(--i-headerTop--he);
	background-color: var(--i-headerTop--ba-co);
	color: var(--i-co);
	min-height: var(--i-header-row--he);
}

.ipsHeader__primary{
	--i-co: var(--i-headerPrimary--co);
	--i-header-row--he: var(--i-headerPrimary--he);
	background-color: var(--i-headerPrimary--ba-co);
	color: var(--i-co);
	min-height: var(--i-header-row--he);
}

.ipsHeader__secondary{
	--i-co: var(--i-headerSecondary--co);
	--i-header-row--he: var(--i-headerSecondary--he);
	background: var(--i-headerSecondary--ba-co);
	color: var(--i-co);
	min-height: var(--i-header-row--he);
}

/* Improve spacing in iPad PWA */
@media (display-mode: standalone){
	.ipsHeader__top:first-child,
	.ipsHeader__primary:first-child{
		box-sizing: content-box;
		padding-top: env(safe-area-inset-top);
	}
}

.ipsHeaderExtra{
	--i-co: var(--i-color_contrast, currentColor);
	color: var(--i-co);
}

	.ipsLogo{
		--_font-size: calc(var(--set__i-desktop-logo--fo-si) * 1px);
		--_image-size: var(--set__i-logo--he);
		display: flex;
		align-items: center;
		color: inherit;
		font-weight: var(--set__i-logo--fo-we);
		font-family: var(--set__i-logo--fo-fa);
		text-decoration: none;
		height: var(--i-header-row--he, 100%);
		font-size: var(--_font-size);
		flex-shrink: 100;
	}

		.ipsLogo__text{
			display: grid;
			justify-items: var(--i-header-row--align, start);
			gap: clamp(7px, 0.4em, 11px);
			line-height: 1;
			white-space: nowrap;
		}

		.ipsMobileHeader .ipsLogo{
			--_font-size: calc(var(--set__i-mobile-logo--fo-si) * 1px);
			--_image-size: var(--set__i-mobile-logo--he);
			flex-shrink: 1;
		}

		.ipsMobileHeader .ipsLogo__text{
			line-height: 1.3;
			gap: 0;
			overflow: hidden;
			height: 100%;
			align-content: center;
		}

			.ipsLogo__slogan{
				font-size: .6em;
			}

			.ipsLogo__slogan:empty{
				display: none;
			}

		.ipsLogo__image{
			display: contents; /* Remove <picture> element from layout */
		}

		.ipsLogo__image img{
			object-fit: contain; /* Prevent squished logo */
			height: 100%; /* auto can be used, but 100% is best for svgs */
			max-height: calc(var(--_image-size, 100) * 1%);
			width: auto;
		}

		/* Hide the text logo if an image logo isn't available */
		[data-ips-scheme="light"] :is(.ipsLogo__image--dark, .ipsLogo__image--light:not([hidden]) ~ .ipsLogo__text),
		[data-ips-scheme="dark"] :is(.ipsLogo__image--light, .ipsLogo__image--dark:not([hidden]) ~ .ipsLogo__text){
			display: none;
		}

@media (max-width: 979px){
	.ipsResponsive_header--desktop{
		display: none !important;
	}
}
@media (min-width: 980px){
	.ipsResponsive_header--mobile{
		display: none !important;
	}
}

i-navigation-menu{
	display: block;
	position: relative;
}

/* The flex-basis must be 1% for the More menu to function */
.ipsNav{
	flex: 999 10 1%;
}

	.ipsNavBar{
		display: flex;
		justify-content: safe var(--i-header-row--align, center);
		gap: 2px;
	}

	/* Fallback for older browsers which don't support "safe" */
	@supports not (justify-content: safe center){
		.ipsNavBar{
			justify-content: var(--i-header-row--align, center);
		}
		/* If justify-content: safe end; isn't supported, add an auto margin instead for "end" alignment. Required for calculating overflow for the More menu. */
		.ipsHeader__end .ipsNavBar{
			justify-content: start;
		}
		.ipsHeader__end .ipsNavBar > li:first-child{
			margin-inline-start: auto;
		}
	}

		.ipsNavBar > li{
			flex-shrink: 0;
		}

			.ipsNavBar > li > :is(a, button){
				display: flex;
				align-items: center;
				justify-content: center;
				gap: .7em;
				padding: var(--i-nav--pa);
				white-space: nowrap;
				border-radius: var(--i-nav--bo-ra);
				background-color: var(--i-nav--ba-co);
				color: var(--i-nav--co);
				text-align: center;
				text-decoration: none;
				font-weight: var(--i-nav--fo-we);
				text-transform: var(--i-nav--te-tr);
				font-size: var(--i-nav--fo-si);
			}

			.ipsNavBar > li:not([data-active]) > a:hover,
			.ipsNavBar > li:not([data-active]) > button:hover,
			.ipsNavBar > li:not([data-active]) > [aria-expanded="true"],
			.ipsNavBar > li:not([data-active]) > button:has(~ :popover-open){
				color: var(--i-nav-hover--co);
				background-color: var(--i-nav-hover--ba-co);
			}

			/* Active buttons */
			.ipsNavBar > [data-active] > :is(a, button){
				color: var(--i-nav-active--co);
				background-color: var(--i-nav-active--ba-co);
			}

				.fa-ips--primary-nav{
					display: none;
				}

				.ipsNavBar__text{
					flex: 0 0 auto;
					display: flex;
					align-items: center;
					justify-content: center;
					gap: .5em;
				}

				.ipsNavBar .fa-angle-down{
					font-size: .75em;
					min-width: 1em; /* Helps with layout shift */
					margin-inline-start: auto; /* For summary elements in dropdowns */
				}

	.ipsNavBar > li > .ipsNav__dropdown{
		inset: auto;
		position: absolute;
		position-area: bottom;
		justify-self: anchor-center;
		position-try: flip-block, flip-inline, flip-block flip-inline;
		transition-property: display, overlay, translate, opacity;
		transition-behavior: allow-discrete;
		transition-duration: .15s;

		opacity: 0;
		translate: 0 1em;

		background-color: var(--i-nav-dropdown--ba-co);
		color: var(--i-nav-dropdown--co);
		box-shadow: var(--i-nav-dropdown--bo-sh);
		border-radius: 8px;
		font-weight: 500;
		font-size: .95em;
		line-height: 1;
		min-width: 18em;
		padding: 5px;
		white-space: nowrap;
		margin: var(--i-nav-dropdown--offset, 6px);
		overflow: visible;
	}

	/* Fill the gap to ensure hover menus stay active during mouse movements */
	[data-hover] .ipsNavBar > li > .ipsNav__dropdown::before{
		content: "";
		position: absolute;
		left: 0; right: 0;
		bottom: 100%;
		height: var(--i-nav-dropdown--offset, 6px);
	}

	@supports (not (position-area: bottom)) or (-webkit-hyphens: auto){
		.ipsNavBar > li > .ipsNav__dropdown{
			/* Reset transitioned, anchored popover as it freezes in Safari 26.0 */
			position-area: initial;
			justify-self: initial;
			position-try: initial;
			margin-left: 0;
			margin-right: 0;
		}
		/* Only apply the positioned menu once the JS has loaded */
		i-navigation-menu:defined .ipsNavBar > li > .ipsNav__dropdown{
			left: 0;
			top: var(--_anchor-v, auto);
			transform: translateX(clamp(
				var(--i-nav-dropdown--offset, 6px),
				var(--_anchor-h, 0px) - 50%,
				100vw - 100% - var(--i-nav-dropdown--offset, 6px))
			)
		}

		/* Safari 26.1: Closing popovers can jump in position. Setting a fixed position with a new top value fixes this */
		@supports (-webkit-hyphens:auto){
			i-navigation-menu:defined .ipsNavBar > li > .ipsNav__dropdown:not(:popover-open){
				position: fixed;
				top: var(--_anchor-v-fixed, auto);
			}
		}
	}

	.ipsNavBar > li > .ipsNav__dropdown:popover-open{
		opacity: 1;
		translate: 0 0;
	}
	/* Popover polyfill */
	.ipsNavBar > li > .ipsNav__dropdown.\:popover-open{
		opacity: 1;
		translate: 0 0;
	}

	@starting-style{
		.ipsNavBar > li > .ipsNav__dropdown:popover-open{
			opacity: 0;
			translate: 0 1em;
		}
	}

	.ipsNav__dropdown .ipsNav__dropdown{
		--_menu-depth: 1;
	}
	.ipsNav__dropdown .ipsNav__dropdown .ipsNav__dropdown{
		--_menu-depth: 2;
	}

		.ipsNav__dropdown :is(a, summary){
			display: flex;
			align-items: center;
			gap: .8em;
			padding: 1em 1.2em;
			color: currentColor;
			text-decoration: none;
			border-radius: 4px;
		}

			.ipsNav__dropdown :where(a, summary):hover{
				background-color: var(--i-nav-dropdown-hover--ba-co);
				color: var(--i-nav-dropdown-hover--co);
			}

			.ipsNav__dropdown [aria-current="page"]{
				background-color: var(--i-nav-dropdown-active--ba-co);
				color: var(--i-nav-dropdown-active--co);
			}

			.ipsNav__dropdown i-details-content :is(a, summary){
				padding-inline-start: 2.4em;
			}

			.ipsNav__dropdown hr{
				height: 1px;
				background: currentColor;
				margin: .3em .5em;
				opacity: .15;
			}

			.ipsNav__dropdown .ipsNavBar__text{
				justify-content: start;
				flex: 1 1 auto;
			}

			/* Add a space after internal dropdowns, if it's followed by a regular link */
			.ipsNav__dropdown > li:has(> .ipsNav__dropdownTitle){
				margin: 1.5em 0;
			}
			.ipsNav__dropdown > li:first-child{
				margin-top: 0;
			}
			.ipsNav__dropdown > li:last-child{
				margin-bottom: 0;
			}

			/* Rotate arrows in sub-dropdown menus */
			.ipsNav__dropdown details .fa-angle-down{
				rotate: -90deg;
				transition: rotate .3s;
			}
			.ipsNav__dropdown details[open] .fa-angle-down{
				rotate: 0deg;
			}

			/* Hide toggles in sub-dropdowns since the list is always shown */
			.ipsNav__dropdown .ipsNav__dropdownTitle + [popovertarget]{
				display: none;
			}

				.ipsNav__dropdownTitle{
					display: none;
					color: var(--i-color_hard);
					font-weight: 700;
					gap: .8em;
  					padding: 1em 1.2em;
					cursor: default; /* The text selection cursor seems odd here, so lets use the standard arrow */
					text-transform: uppercase;
					font-size: .9em;
				}

				.ipsNav__dropdown .ipsNav__dropdownTitle{
					display: flex;
				}
				.ipsNav__dropdownTitle .ipsNavBar__label{
					font-size: .9em;
				}

				.ipsNav__dropdownTitle .ipsNavBar__icon,
				.ipsNav__dropdownTitle .fa-angle-down{
					display: none;
				}

/* Icons */
.ipsNavBar__icon{
	line-height: 1;
	text-align: center;
	flex: 0 0 1.2em; /* Helps with layout shift */
}

	[data-ips-theme-setting-nav-bar-icons="0"] .ipsNavBar__icon{
		display: none;
	}

	.ipsNavBar__icon [style*="--icon"]::before{
		content: var(--icon);
	}

	.ipsNavBar__icon i{
		opacity: .5;
	}

/* A cloned version uses intersectionObserver to control the More menu */
.ipsNavPriority{
	position: absolute;
	top: 0; bottom: 0;
	left: 0; right: 0;
	overflow: hidden;
	visibility: hidden;
	pointer-events: none;
}

.ipsNavPriority .ipsNavBar{
	justify-content: start;
}

/* Temporarily hide previously hidden menu items on page load */
i-navigation-menu:not([data-observed]) [data-initially-hidden] {
	display: none;
}

/*
	----------------
	- Mobile header
	----------------
*/

.ipsMobileHeader{
	--i-header-row--he: var(--i-mobileHeader--he, 70px);
	--i-co: var(--i-headerMobile--co);
	background: var(--i-headerMobile--ba-co);
	color: var(--i-co);
	border-bottom: 1px solid transparent;
	border-color: color-mix(in srgb, var(--i-color_hard) 15%, transparent);
	display: flex;
	align-items: center;
	height: var(--i-mobileHeader--he, 70px);
	padding: 0 max(env(safe-area-inset-left), var(--i-layout-gutter));
	position: relative;
	z-index: var(--i-z-index_headerPrimary);
}

/* 
	If the PWA is in full screen mode, adjust the height of the mobile header to cater for the iOS status bar
	The :first-child selector is used because we only want to apply this if the mobile header is the first element. Sometimes it isn't, such as when advertisements are enabled
*/
@media (display-mode: standalone){
	.ipsMobileHeader:first-child{
		box-sizing: content-box;
		padding-top: env(safe-area-inset-top);
	}
}

@supports not (color: color-mix(in hsl, red, blue)){
	.ipsMobileHeader{
		border-width: 0;
	}
}

.ipsMobileNavIcons{
	margin-inline-start: auto;
	flex: 0 0 auto;
	display: flex;
	align-items: center;
}

/* Truncate the username if it flows over the logo */
.ipsMobileNavIcons:has(.ipsMobileNavIcons__username){
	flex-shrink: 999;
}

	.ipsMobileNavIcons__username{
		flex: 0 999 auto;
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}

	.ipsMobileNavIcons__button{
		display: flex;
		align-items: center;
		justify-content: center;
		gap: .75em;
		min-width: 40px;
		min-height: 40px;
		max-width: 100%; /* Needed to truncate long usernames */
		padding: 0 .8em;
		font-size: .9em;
		font-weight: 600;
		border-radius: min(var(--i-design-radius), 6px);
		text-align: center;
		position: relative;
		text-decoration: none;
		backdrop-filter: blur(40px); /* Attempt to improve contrast if a background image exists */
		color: inherit; /* Overwrite link color */
	}

	@media (any-hover:hover){
		.ipsMobileNavIcons__button:hover{
			background: color-mix(in srgb, currentColor 5%, transparent);
		}
	}

		.ipsMobileNavIcons__button > :is(i, svg){
			height: 1.2em;
			fill: currentColor;
		}
		.ipsMobileNavIcons__button .ipsUserPhoto{
			width: 2em;
		}

	.ipsMobileNavIcons__button .ipsNotification{
		inset-block-start: 0;
		inset-inline-end: 0;
	}

	.ipsMobileNavIcons__button--primary{
		background-color: var(--i-secondary);
		color: var(--i-secondary-contrast);
	}

	@media (any-hover:hover){
		.ipsMobileNavIcons__button--primary:hover{
			background-color: var(--i-secondary-light);
		}
	}

/* User nav */
.ipsUserNav{
	flex: 0 0 auto;
	display: flex;
	font-size: .9em;
}
.ipsUserNav--guest{
	gap: 5px;
}

	.ipsUserNav > li{
		flex: 0 0 auto;
	}

		.ipsUserNav__link{
			display: flex;
			align-items: center;
			gap: .7em;
			height: 3em;
			padding: 0 1em;
			font-weight: 600;
			border-radius: min(var(--i-design-radius), 6px);
			position: relative;
			color: currentColor;
		}

		.ipsUserNav__link:hover,
		.ipsUserNav__link[aria-expanded="true"]{
			background: color-mix(in srgb, currentColor 8%, transparent);
		}

		.ipsUserNav__link.ipsUserNav__link--sign-up{
			background: var(--i-primary);
			color: var(--i-primary-contrast);
		}

			.ipsUserNav__link > *{
				flex: 0 0 auto;
			}

			.ipsUserNav__link .ipsUserPhoto{
				width: 2em;
				margin-inline-start: -0.5em;
			}

				.ipsUserNav__link .fa-angle-down{
					font-size: .7em;
				}

				.ipsUserNav__link > i{
					min-width: 1em;
				}

				.ipsUserNav__icon{
					font-size: max(15px, 1em);
					text-align: center;
				}
	.ipsUserNav .ipsNotification{
		top: -3px;
		inset-inline-end: 3px;
		font-size: 10px;
	}

.ipsUserNav .iDropdown{
	width: 400px;
}
#elUserLink_menu .iDropdown{
	width: 340px;
}

.elUserNav_achievements__icon{
	width: 40px;
}

[data-ips-layout="side"] #cUserLink{
	order: 1;
}

/* Hide "Manage Blocks" and "Theme Editor" links while Block Manager or Theme Editor is active */
:is([data-theme-editor-active], .cWidgetsManaging) :is([data-menuitem="blockEditor"], [data-menuitem="themeEditor"]){
	display: none;
}

/* Sign in popup and register modal */
#elUserSignIn_menu .iDropdown {
	width: min(600px, 95vw);
	max-width: none;
}

#elUserSignIn_menu .iDropdown > form{
	border-radius: inherit;
	overflow: hidden; /* Crop overflow to border-radius */
}

	#elUserSignIn_menu .iDropdown:not(:has(.ipsColumns)){
		width: 340px;
	}

	#elUserSignIn_menu .ipsColumns{
		border-radius: var(--i-dropdown--bo-ra);
	}

	:is(#elUserSignIn_menu, #elRegisterButton_dialog) .ipsFieldRow{
		padding: 1em;
	}

	#elUserSignIn_menu .ipsSubmitRow{
		border-radius: 0;
	}

#elUserSignIn_internal{
	flex-basis: auto;
}

#elRegisterButton_dialog .ipsFieldRow__required{
	margin-inline-start: auto;
}

#elRegisterButton_dialog .ipsFieldRow__label a{
	text-decoration: underline;
}


/*
	----------------
	- Breadcrumb search
	----------------
*/

.ipsSearchPseudo{
	--i-search--co: currentcolor;
	--i-search--ba-co: color-mix(in srgb, var(--i-search--co) 15%, transparent);
	--i-search-hover--ba-co: color-mix(in srgb, var(--i-search--ba-co), var(--i-search--co) 15%);

	--i-outline-color: hsl(0 0% 100%);
	color: var(--i-search--co);
	flex: 0 1 var(--i-search--wi);
	background-color: var(--i-search--ba-co);
	border-radius: min(var(--i-design-radius), 6px);
	padding: 0 1em;
	height: var(--i-search--he);
	display: flex;
	align-items: center;
	gap: 1em;
	font-size: .9em;
}
	@media (hover){
		.ipsSearchPseudo:hover{
			background-color: var(--i-search-hover--ba-co);
		}
	}
	.ipsSearchPseudo i{
		flex: 0 0 1.1em;
		text-align: center;
	}
	:where(.ipsHeader__center, .ipsHeaderExtra__center) .ipsSearchPseudo{
		margin: 0;
		flex-grow: 1;
	}

	/* color-mix fallback */
@supports not (color: color-mix(in srgb, red, red)){
	.ipsSearchPseudo{
		background-color: #fff !important;
		color: #111;
	}
}

/* Pull to refresh, iOS PWA */
i-pull-to-refresh{
	display: none;
	--_limit: 180;
	--_background: var(--i-headerMobile--ba-co);
	--_color: var(--i-headerMobile--co);
	--_height: var(--i-mobileHeader--he);
}

@media (min-width: 980px){
	i-pull-to-refresh{
		--_background: var(--i-headerPrimary--ba-co);
		--_color: var(--i-headerPrimary--co);
		--_height: var(--i-headerPrimary--he);
	}	
}

/* Only show pull-to-refresh in iOS standalone PWAs. Android already has pull-to-refresh */
@supports (-webkit-touch-callout: none) {
	@media (display-mode: standalone){
		i-pull-to-refresh{
			display: block;
			color: var(--_color);
			position: absolute;
			z-index: 999;
			width: 100%;
			/* Height isn't important. We just need it tall enough for intersectionObserver to safely notice it */
			height: 5px;
			pointer-events: none;
		}
	}
}

/* Background */
i-pull-to-refresh::before{
	content: "";
	position: absolute;
	width: 100%;
	height: 400px;
	margin-top: -400px;
	background: var(--_background);
	/* The transform ensures the element is painted, even when outside of the viewport */
	transform: translate3d(0,0,0);
}

.iPullToRefresh{
	position: fixed;
	display: flex;
	width: 100%;
	height: var(--_height, 80px);
	padding-top: env(safe-area-inset-top);
	box-sizing: content-box;
}

.iPullToRefresh::after{
	content: "";
	mask: conic-gradient(
		black 0% clamp(0%, var(--_scroll, 0) / var(--_limit) * -100%, 100%),
		hsl(0 0% 0% / .1) clamp(0%, var(--_scroll, 0) / var(--_limit) * -100%, 100%) 100%
	);
	border: 3px solid;
	width: 30px;
	height: 30px;
	border-radius: 50%;
	margin: auto;
	opacity: clamp(0%, var(--_scroll, 0) / var(--_limit) * -200%, 100%);
}

@keyframes ipsPullToRefresh{
	to{
		rotate: 360deg;
	}
}

[data-ips-pwa-refreshing] .iPullToRefresh{
	background-color: var(--_background);
}

[data-ips-pwa-refreshing] .iPullToRefresh::after{
	opacity: 1;
	mask: none;
	border-color: color-mix(in hsl, currentColor 10%, transparent);
	border-top-color: currentColor;
	animation: ipsPullToRefresh .5s linear infinite;
}

/*
	----------------
	- Layout
	----------------
*/

/* Column layout */
.ipsLayout{
	display: flex;
	overflow-wrap: break-word;
	/* Apply margins incase a max-width is set on this element */
	margin-left: auto;
	margin-right: auto;
}

	.ipsLayout__app{
		flex: 1 1 auto;
		display: flex;
		flex-direction: column;
		min-height: 100vh;
		min-height: 100dvh;
	}

	.ipsLayout__main{
		flex: 1 1 auto;
		padding-top: var(--i-sp_block);
		outline-width: 0;
	}

	/* The outline is only displayed when the "Skip to content" link is clicked */
	.ipsLayout__main:target{
		outline-offset: -4px;
		outline-width: 2px;
	}

	/* Smooth scroll to <main> element when "Skip to content" is clicked */
	html:has(main:target){
		scroll-behavior: smooth;
	}

	@media (max-width: 979px){
		/* Remove padding to the main block if the breadcrumbs are visible since they add the necessary padding */
		.ipsBreadcrumb--mobile:not([hidden]) ~ .ipsLayout__main{
			padding-top: 0;
		}
	}

/* Space out all blocks by default */
:where(.ipsContentWrap > *:not(:last-child)){
	margin-bottom: var(--i-sp_block);
}

/* Columns */
.ipsLayout__columns{
	display: flex;
	flex-wrap: wrap;
	gap: var(--i-sp_block);
}

/* Flip sidebar based on setting */
[data-ips-theme-setting-flip-sidebar="1"] .ipsLayout__columns{
	flex-direction: row-reverse;
}

	.ipsLayout__primary-column{
		flex: 999 1 600px;
	}

		.ipsLayout__primary-column > * {
			margin-bottom: var(--i-sp_block);
		}

		.ipsLayout__primary-column > :nth-last-child(1 of :not([hidden])) {
			margin-bottom: 0;
		}

	.ipsLayout__secondary-column{
		flex: 1 1 calc(var(--set__i-sidebar-width, 350) * 1px);
		display: grid;
	}

	/* Make sidebar sticky, unless it contains <details> elements (since their dynamic height results in a poor UI) */
	[data-ips-theme-setting-sticky-sidebar="1"] .ipsLayout__secondary-sticky-outer:not(:has(details)){
		min-height: min(100%, calc(100vh - (var(--i-sp_block) * 2) - var(--i-sticky-offset)));
		min-height: min(100%, calc(100svh - (var(--i-sp_block) * 2) - var(--i-sticky-offset)));
		position: sticky;
		bottom: var(--i-sp_block);
		align-self: end;
	}
	[data-ips-theme-setting-sticky-sidebar="1"] .ipsLayout__secondary-sticky-inner:not(:has(details)){
		position: sticky;
		top: calc(var(--i-sticky-offset) + var(--i-sp_block));
	}

	.ipsLayout__secondary-column--hide{
		display: none;
	}
	.ipsLayout__secondary-column--managing{
		display: grid !important;
	}

	@supports selector(a:has(b)){
		/* Hide widget column by default, and show if it meets certain criteria. Older browsers rely on .ipsLayout__secondary-column--hide */
		.ipsLayout__secondary-column{
			display: none;
		}

		/* Show if there are visible widgets */
		@media (min-width: 980px){
			.ipsLayout__secondary-column:has(.ipsWidget:not(.ipsResponsive_hideDesktop .ipsWidget, [hidden] .ipsWidget, [hidden], .ipsHide)){
				display: grid;
			}
		}

		@media (min-width: 768px) and (max-width: 979px){
			.ipsLayout__secondary-column:has(.ipsWidget:not(.ipsResponsive_hideTablet .ipsWidget, [hidden] .ipsWidget, [hidden], .ipsHide)){
				display: grid;
			}
		}

		@media (max-width: 767px){
			.ipsLayout__secondary-column:has(.ipsWidget:not(.ipsResponsive_hidePhone .ipsWidget, [hidden] .ipsWidget, [hidden], .ipsHide)){
				display: grid;
			}
		}

		/* Always show sidebar if it contains certain elements, or if the Page Editor is active */
		.ipsLayout__secondary-column:not(.ipsLayout__secondary-column--hide):has(:is(#elContextualTools, [data-role="sidebarAd"], #cAnnouncementSidebar):not([hidden], .ipsHide)){
			display: grid !important;
		}
	}

	/* Always show widgets when in editing mode, even if they've been hidden for responsive reasons */
	.cWidgetContainer_managing.cWidgetContainer--isWidget:not(.cWidgetContainer--dragging) {
		display: block !important;
	}

#elContextualTools, [data-role="sidebarAd"]{
	margin-bottom: var(--i-sp_block);
}
#elContextualTools,
.ipsLayout__secondary-column .cWidgetContainer > ul{
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(min(300px, 100%), 1fr));
	gap: var(--i-sp_block);
}

.ipsWidgetHide{
	display: none !important;
}

.ipsMobileFooter {
	--i-outline-offset: -2px;
	color: var(--i-mobileFooter--co);
	box-shadow: color-mix(in srgb, var(--i-color_root) 25%, transparent) 0px -1px 0px 0px;
	background-color: var(--i-mobileFooter--ba-co);
	text-align: center;
	position: -webkit-sticky;
	position: sticky;
	bottom: 0;
	width: 100%;
	height: var(--i-mobileFooter--he);
	z-index: var(--i-z-index_mobileFooter);
	font-family: system-ui, sans-serif; /* Force footer bar to use OS font. Other fonts may be difficult to read at small sizes */
}

/* Hide if disabled via settings */
[data-ips-theme-setting-mobile-icons-location="header"] .ipsMobileFooter{
	display: none;
}

/* Move footer when editor is focused on touch devices (so it doesn't take up valuable screen space */
@media (hover:none){
	.ipsLayout:has(.ProseMirror-focused) ~ .ipsMobileFooter{
		position: static;
	}
}

@media (min-width: 980px){
	.ipsMobileFooter{
		display: none;
	}
}

	.ipsMobileFooter ul {
		display: flex;
		padding: 3px;
		height: calc(var(--i-mobileFooter--he) - env(safe-area-inset-bottom));
	}
		.ipsMobileFooter__item {
			flex: 1 1 1%;
		}

	.ipsMobileFooter__link {
		display: grid;
		text-align: center;
		align-content: center;
		gap: .3em;
		position: relative;
		height: 100%;
		width: 100%;
		color: inherit;
		text-decoration: none;
		border-radius: 4px;
		padding: .2em 0;
		touch-action: manipulation;
	}

	@media (any-hover:hover){
		.ipsMobileFooter__link:hover{
			background: color-mix(in srgb, currentColor 10%, transparent);
		}
	}

		.ipsMobileFooter__link[aria-expanded="true"] {
			background: var(--i-mobileFooter-active--ba-co);
			color: var(--i-mobileFooter-active--co);
		}

	.ipsMobileFooter__link svg{
		place-self: center;
		fill: currentColor;
		width: auto;
		height: 18px;
	}

	.ipsMobileFooter .ipsNotification {
		top: 2px;
		inset-inline-end: max(50% - 2.7em, 0em);
	}

	.ipsMobileFooter__icon{
		display: grid;
	}

	.ipsMobileFooter__text{
		font-weight: 600;
		opacity: .7;
		font-size: clamp(8px, 0.5em + 0.4vw, 10px);
		overflow: hidden;
		white-space: nowrap;
		text-overflow: ellipsis;
		max-width: 100%;
	}

/* Remove labels if theme setting requests it */
[data-ips-theme-setting-mobile-footer-labels="0"] .ipsMobileFooter__text{
	display: none;
}

/* Larger icons when text is removed */
[data-ips-theme-setting-mobile-footer-labels="0"] .ipsMobileFooter__link svg{
	height: 20px;
}

.ipsNavPanel{
	--i-co: var(--i-navPanel--co);
	color: var(--i-co);
	height: calc(100vh - var(--i-sticky-offset));
	height: calc(100dvh - var(--i-sticky-offset));
	background-color: var(--i-navPanel--ba-co);
	background-clip: padding-box;
	border-inline-end: 1px solid color-mix(in srgb, var(--i-navPanel--ba-co), currentColor 20%);
	flex: 0 0 clamp(280px, 16vw, 340px);
	position: sticky;
	top: 0;
	z-index: var(--i-z-index_offCanvas);
	display: flex;
	flex-direction: column;
}

@media (max-width: 979px){
	.ipsNavPanel{
		display: none;
	}
}

/* Hide panel when the "Manage widgets" panel is open */
@media (max-width: 2250px){
	.cWidgetsManaging .ipsNavPanel{
		display: none;
	}
}

	.ipsNavPanel .ipsLogo{
		--_image-size: var(--set__i-sidebar-ui-logo--he);
		--_font-size: calc(var(--set__i-sidebar-ui-logo--fo-si) * 1px);
		flex: 0 0 auto;
		height: calc(var(--set__i-sidebar-ui-header--he) * 1px);
		padding: 0 20px;
		box-shadow: color-mix(in srgb, var(--i-co) 15%, transparent) 0px 1px 0px;
		position: relative;
		z-index: 2;
		overflow: hidden;
	}

	.ipsNavPanel .ipsLogo__slogan{
		opacity: .8;
	}

	.ipsNavPanel__scroll{
		flex: 1 1 100%;
		overflow-y: auto;
		overscroll-behavior: contain;
		scrollbar-width: thin;
		scrollbar-color: color-mix(in srgb, var(--i-co) 40%, transparent) transparent;
	}

	@supports selector(.x::-webkit-scrollbar){
		@media(hover: hover){
			.ipsNavPanel__scroll{
				scrollbar-width: auto;
			}
			.ipsNavPanel__scroll::-webkit-scrollbar {
				width: 14px;
			}
			.ipsNavPanel__scroll::-webkit-scrollbar-track {
				background: transparent;
			}
			.ipsNavPanel__scroll::-webkit-scrollbar-thumb {
				border: 4px solid transparent;
				border-radius: 20px;
				background-color: color-mix(in srgb, var(--i-co) 40%, transparent);
				background-clip: content-box;
			}
				.ipsNavPanel__scroll::-webkit-scrollbar-thumb:hover{
					background-color: color-mix(in srgb, var(--i-co) 60%, transparent);
				}
		}
	}

	.ipsNavPanel__nav{
		--icon: "\f15c";
		padding: 1em;
	}

	.ipsNavPanel__nav > li:has(> details):not(:first-child){
		margin: clamp(0.8em, 3vh, 4em) 0;
		transition-property: margin;
		transition-duration: .25s;
	}

	/* Reduce margins on collapsed immediate siblings */
	.ipsNavPanel__nav li:has(> details:not([open])) + li:has(> details:not([open])){
		margin-top: 0;
	}
	.ipsNavPanel__nav li:has(> details:not([open])):has( + li > details:not([open])){
		margin-bottom: 0;
	}

	/* Remove transitions during page load since they interfere with restoring the scroll position */
	i-navigation-panel:not(:defined){
		& ::details-content,
		& .ipsNavPanel__nav > li:has(> details){
			transition: none;
		}
	}

	.ipsNavPanel__icon{
		flex: 0 0 1.3em;
		text-align: center;
		margin-inline-end: 0.8em;
	}

		.ipsNavPanel__icon [style*="--icon"]::before{
			content: var(--icon);
		}

		/* FA icons and svg */
		.ipsNavPanel__icon *{
			opacity: .4;
		}

		.ipsNavPanel__icon svg{
			fill: currentColor;
			width: auto;
			height: 1em;
			display: block;
		}

		.ipsNavPanel__nav [aria-current="page"] > a .ipsNavPanel__icon *{
			opacity: 1;
		}
		@media (any-hover:hover){
			a:hover .ipsNavPanel__icon *,
			button:hover .ipsNavPanel__icon *,
			summary:hover .ipsNavPanel__icon *{
				opacity: 1;
			}
		}

	.ipsNavPanel__nav summary{
		font-weight: 600;
		font-size: max(12px,.8em);
	}

		/* Remove icons from sidebar headers */
		.ipsNavPanel__nav summary .ipsNavPanel__icon{
			display: none;
		}

		/* Collapse icon */
		.ipsNavPanel__toggle-list{
			margin-inline-start: auto;
			opacity: .75;
			transition-property: rotate;
			transition-duration: .25s;
			font-size: 12px;
			rotate: calc(-90deg * var(--i-lang-dir));
		}

			[open] > summary .ipsNavPanel__toggle-list{
				rotate: 0deg;
			}

	:where(.ipsNavPanel__nav) :is(a, button, summary){
		--i-co: var(--i-navPanel--co);
		width: 100%;
		display: flex;
		align-items: center;
		padding: .65em 1.3em;
		color: var(--i-co);
		font-weight: 500;
		border-radius: min(var(--i-design-radius), 6px);
	}

	.ipsNavPanel__nav ul ul :is(a, button, summary){
		padding-inline-start: 2.6em;
	}

	.ipsNavPanel__nav a.ipsButton{
		margin: .4em 0;
	}

		@media (any-hover:hover){
			.ipsNavPanel__nav :is(a, button, summary):hover{
				--i-co: var(--i-navPanelLinkHover--co);
				background: color-mix(in srgb, var(--i-navPanelLinkHover--co) 10%, var(--i-navPanel--ba-co));
			}
		}

		.ipsNavPanel__nav [aria-current="page"] > a{
			background: var(--i-navPanelLinkActive--ba-co);
			color: var(--i-navPanelLinkActive--co);
		}

		.ipsNavPanel__search{
			--icon: "\f002";
			background: color-mix(in srgb, currentColor 10%, transparent);
			margin-bottom: 2em;
		}

		@media (any-hover:hover){
			.ipsNavPanel__nav .ipsNavPanel__search:hover{
				background: color-mix(in srgb, currentColor 20%, transparent);
			}
		}

	/* Menu separators (Eg. used above "Custom activity streams") */
	.ipsNavPanel__nav hr{
		display: none;
	}

	.ipsNavPanel__title{
		font-weight: 600;
		display: flex;
		align-items: center;
		gap: 1em;
		padding: .8em 1.3em;
		font-size: max(11px,.8em);
		text-transform: uppercase;
	}

		.ipsNavPanel__title::before,
		.ipsNavPanel__title::after{
			content: '';
			flex: 1 1 auto;
			height: 1px;
			background: currentColor;
			opacity: .3;
		}

		.ipsNavPanel__title::before{
			flex: 0 0 2em;
		}

		.ipsNavPanel__title:not(:first-child){
			margin-top: 2em;
		}

/* Breadcrumbs */
.ipsNavPanelBreadcrumbs{
	color: var(--i-color_contrast, var(--i-color_root));
}

	.ipsNavPanelBreadcrumbs .ipsHeader__align{
		padding: .5em 0;
		border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent);
	}

.ipsOffCanvas__nav{
	padding: .5em;
}

.ipsOffCanvas__nav a,
.ipsOffCanvas__nav button,
.ipsOffCanvas__nav summary,
.ipsOffCanvas__item{
	outline-offset: -2px;
	color: var(--i-co);
	display: flex;
	gap: .6em;
	align-items: center;
	font-weight: 550;
	padding: .8em 1.2em;
	width: 100%;
	text-decoration: none;
	border-radius: min(5px, var(--i-design-radius));
}

	@media (any-hover:hover){
		.ipsOffCanvas__nav :where(a:hover, button:hover, summary:hover){
			background-color: var(--i-background_3);
		}
	}

	.ipsOffCanvas__nav [aria-current="page"],
	.ipsOffCanvas__nav [aria-selected="true"]{
		background-color: var(--i-primary);
		color: var(--i-primary-contrast);
	}

	.ipsOffCanvas__icon{
		flex: 0 0 auto;
		width: 1.4em;
		line-height: 1;
		text-align: center;
		margin-inline-end: .2em;
	}

		.ipsOffCanvas__icon [style*="--icon"]::before{
			content: var(--icon);
		}

		/* FA icons and svg */
		.ipsOffCanvas__icon i,
		.ipsOffCanvas__icon svg{
			opacity: .5;
			fill: currentColor;
		}

		/* Icons in user menu */
		.ipsOffCanvas__nav--profile .fa-solid{
			width: 1.5em;
			opacity: .5;
		}

	.ipsOffCanvas__label{
		flex: 1 1 auto;
	}

		.ipsOffCanvas__nav hr{
			border-top: 1px solid currentColor;
			opacity: .15;
			margin: .5em;
		}

	.ipsOffCanvas__nav .ipsNotification{
		position: static;
	}

	.ipsOffCanvas__label:has(+ .ipsNotification){
		flex: 0 1 auto;
	}

	.ipsOffCanvas__nav summary::after,
	.ipsOffCanvas__nav [aria-expanded]::after{
		content: "\f078";
		content: "\f078" / "";
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		flex: 0 0 auto;
		margin-inline-start: auto;
		font-size: .7em;
	}

		/* Expanded menu inside dropdown */
		.ipsOffCanvas__nav [open] > summary::after,
		.ipsOffCanvas__nav [aria-expanded="true"]::after{
			content: '\f077';
			content: '\f077' / "";
		}

	.ipsOffCanvas__nav i-details-content{
		font-size: max(calc(var(--i-rem) * .9), .9em);
		font-weight: 500;
		margin-inline-start: 2.1em;
		border-inline-start: 1px solid color-mix(in srgb, var(--i-co) 20%, transparent);
		padding-inline-start: .6em;
	}

	.ipsOffCanvas__nav i-details-content a{
		padding: .6em 1.2em;
	}

	/* Mini titles in menus: Eg. "Default streams" and "Custom streams" */
	.ipsOffCanvas__title{
		text-transform: uppercase;
		font-weight: 600;
		padding: .3em 1.2em;
		color: var(--i-color_hard);  
	}

	.ipsOffCanvas__title:not(:first-child){
		margin-top: 2em;
	}

/* Align the inbox/notification icons in the user off-canvas menu. These are shown when the "icon location" is set to header */
.ipsOffCanvas__nav--user{
	display: flex;
}

.ipsOffCanvas__nav--user > li:first-child{
	flex: 1 1 auto;
}

.ipsOffCanvas__nav--user a,
.ipsOffCanvas__nav--user button{
	height: 100%;
	position: relative;
}

.ipsOffCanvas__nav--user svg{
	fill: currentColor;
}

.ipsOffCanvas__nav--user .ipsNotification{
	position: absolute;
	inset-inline-end: auto;
	top: auto;
	bottom: 50%;
	inset-inline-start: calc(50% + .5em);
}

/* Search */
.ipsOffCanvas__search-filters .ipsSimpleSelect select{
	background: none;
}

/* Breadcrumb */
.ipsOffCanvas__breadcrumb{
	flex: 0 0 auto;
	font-weight: 600;
	padding: .7em;
	overflow: auto;
	scrollbar-width: none;
	/* Necessary to allow "overscroll padding" */
	display: flex;
	justify-content: start;
}

.ipsOffCanvas__breadcrumb::-webkit-scrollbar {
	-webkit-appearance: none;
	height: 0px;
	display: none;
}

	.ipsOffCanvas__breadcrumb ol{
		display: flex;
		font-size: .9em;
		background-color: var(--if-light, var(--i-background_2)) var(--if-dark, var(--i-background_3));
		border-radius: 5px;
		flex: 1 0 max-content;
	}

	.ipsOffCanvas__breadcrumb li{
		flex: 0 0 auto;
		display: flex;
		align-items: center;
	}

	.ipsOffCanvas__breadcrumb li > a,
	.ipsOffCanvas__breadcrumb li > span{
		padding: 1em;
		display: block;
		color: var(--i-color_hard);
	}

	.ipsOffCanvas__breadcrumb .fa-house-chimney{
		margin-inline-end: .3em;
	}

	.ipsOffCanvas__breadcrumb li > span{
		opacity: .6;
	}

	.ipsOffCanvas__breadcrumb li:not(:last-child)::after {
		content: '\f054';
		opacity: .5;
		font-size: .8em;
		font-weight: 900;
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
	}

/*
	----------------
	- Search dialog
	----------------
*/

html:has(.ipsSearchDialog[open]){
	overflow: hidden;
}

.ipsSearchDialog{
	width: 100%;
	height: 100%;
	max-width: none;
	max-height: none;
	border-width: 0;
	background: hsl(210 20% 8% / .5);
	-webkit-backdrop-filter: blur(1px);
	backdrop-filter: blur(1px);

	transition-property: display, overlay, opacity;
	transition-behavior: allow-discrete;
	transition-timing-function: ease-in-out;
	transition-duration: .2s;
	opacity: 0;

	/* This fixes a bug in Safari where the dialog closes instantly with no transition */
	position: fixed;
	inset: 0;
	z-index: 999;
}

.ipsSearchDialog::backdrop{
	display: none;
}

.ipsSearchDialog[open]{
	opacity: 1;
	@starting-style{
		&{
			opacity: 0;
		}
	}
}

:where([data-ips-scheme="dark"]) .ipsSearchDialog{
	background: hsl(0 0% 0% / 60%);
}

.ipsSearchDialog__dismiss{
	position: fixed;
	inset: 0;
	opacity: 0;
	z-index: -1;
}

.ipsSearchDialog search{
	display: block;
	overflow: hidden;
	border-radius: var(--i-box--bo-ra);
	background: var(--i-box--ba-co);
	box-shadow: var(--i-dialog--bo-sh);
	width: calc(100vw - 2em);
	max-width: 880px;
	margin: 150px auto 0;

	transition-property: transform;
	transition-timing-function: ease-in-out;
	transition-duration: inherit;
	transform: translateY(-20px);
	transform-origin: 50% 0;
}

[data-ips-scheme="dark"] .ipsSearchDialog search{
	background: var(--i-background_2);
}

.ipsSearchDialog[open] search{
	transform: translateY(0px);
	@starting-style{
		&{
			transform: translateY(-20px);
		}
	}
}

.ipsSearchDialog__modal{
	cursor: auto;
	--i-co: var(--i-color_root);
	display: flex;
	flex-direction: column;
	max-height: min(600px, 100vh - 2em);
	max-height: min(600px, 100dvh - 2em);
	border-radius: inherit;
}

[data-ips-scheme="dark"] .ipsSearchDialog__modal{
	box-shadow: inset hsl(0 0% 100% / .15) 0px 1px 0px;
}

.ipsSearchDialog__input{
	flex: 0 0 auto;
	display: flex;
	gap: .6em;
	padding: 1.2em;
	color: var(--i-co);
}

	.ipsSearchDialog__input [type="text"]{		
		padding: .3em .6em;
		flex: 1 1 100%;
		outline: none;
		font-size: 1.3em;
		font-weight: 500;
	}

	.ipsSearchDialog__input [type="text"]::placeholder{
		color: inherit;
		opacity: .5;
	}

	.ipsSearchDialog__input button{
		flex: 0 0 auto;
	}

	.ipsSearchDialog__input button .fa-solid{
		font-size: .8em;
	}

.ipsSearchDialog__filters{
	font-size: max(12px, var(--i-font-size_-2));
	background: var(--i-background_2);
	border-top: 1px solid var(--i-background_5);
	color: var(--i-color_root);
	font-weight: 500;
}

[data-ips-scheme="dark"] .ipsSearchDialog__filters{
	background: var(--i-background_3);
}

	.ipsSearchDialog__filters select{
		padding-top: 1em;
		padding-bottom: 1em;
		border-radius: 0;
		/* A background is necessary for Windows otherwise it uses a white background */
		background: var(--i-background_2);
	}

	[data-ips-scheme="dark"] .ipsSearchDialog__filters select{
		background: var(--i-background_3);
	}

	[data-ips-scheme="dark"] .ipsSearchDialog__filters > *{
		outline-color: var(--i-background_4);
	}

	.ipsSearchDialog__filters select:hover{
		color: var(--i-color_hard);
	}

/* Width */
.ipsWidth{
	max-width: min(100% - max(env(safe-area-inset-left), var(--i-layout-gutter)) * 2, var(--i-layout-width));
	margin-left: auto;
	margin-right: auto;
}
	.ipsLayout_minimal .ipsWidth--main-content{
		--i-layout-width: 900px;
	}

/* Animation: classes used by javascript to add predefined animations to elements */
/* ======================================================== */
.ipsAnim {
	animation-duration: 0.5s;
	animation-fill-mode: both;
	animation-timing-function: ease-out;
	/* By setting an invisible 3d transform, we can cause */
	/* browsers to render the animation with the GPU instead */
	transform: translate3d(0,0,0);
}

/* ======================================================== */
/* FADE IN/OUT */
@keyframes fadeIn {			0% { opacity: 0; }	100% { opacity: 1; } }
@keyframes fadeOut {		0% { opacity: 1; }	100% { opacity: 0; } }

@keyframes fadeInDown {
	0% { opacity: 0; transform: translateY(-20px); }
	100% { opacity: 1; transform: translateY(0); }
}
@keyframes fadeOutDown {
	0% { opacity: 1; transform: translateY(0); }
	100% { opacity: 0; transform: translateY(20px); }
}

.ipsAnim_fade.ipsAnim_in {
	opacity: 1;
	animation-name: fadeIn;
}
.ipsAnim_fade.ipsAnim_out {
	opacity: 1;
	animation-name: fadeOut;
}
.ipsAnim_fade.ipsAnim_in.ipsAnim_down {
	animation-name: fadeInDown;
}
.ipsAnim_fade.ipsAnim_out.ipsAnim_down {
	animation-name: fadeOutDown;
}

/* ======================================================== */
/* BLIND DOWN */
@keyframes blindDown {
	0% { height: 0; }
	100% { height: auto; }
}

.ipsAnim_blind.ipsAnim_down {
	height: auto;
	animation-name: blindDown;
}

/* ======================================================== */
/* BLIND Up */
@keyframes blindUp {
	0% { height: auto; }
	100% { height: 0; }
}

.ipsAnim_blind.ipsAnim_up {
	height: 0;
	animation-name: blindUp;
}

/* ======================================================== */
/* SLIDE */
@keyframes slideFromRight {
	0% { right: -100%; }
	100% { right: 0; }
}

.ipsAnim_slide.ipsAnim_left {
	right: 0;
	animation-name: slideFromRight;
}

/* ======================================================== */
/* ZOOM */
@keyframes zoomIn {
	0% { transform: scale(0); }
	100% { transform: scale(1); }
}

.ipsAnim_zoom.ipsAnim_in {
	animation-name: zoomIn;
}

@keyframes zoomOut {
	0% { transform: scale(1); }
	100% { 
		transform: scale(0);
		opacity: 0;
	}
}

.ipsAnim_zoom.ipsAnim_out {
	animation-name: zoomOut;
	opacity: 1;
}

/* ======================================================== */
/* WOBBLE */
@keyframes wobble {
	0% { transform: translateX(0%); }
	15% { transform: translateX(-5%) rotate(-4deg); }
	30% { transform: translateX(5%) rotate(2deg); }
	45% { transform: translateX(-4%) rotate(-2deg); }
	60% { transform: translateX(4%) rotate(1deg); }
	75% { transform: translateX(-3%) rotate(-1deg); }
	100% { transform: translateX(0%);}
}

.ipsAnim_wobble {
	animation-name: wobble;
}

/* ======================================================== */
/* JIGGLE */
@keyframes jiggle {
	0% { transform: rotate(-3deg); }
	50% { transform: rotate(3deg); }
}

.ipsAnim_jiggle {
	animation: jiggle 0.3s infinite;
}

/* ======================================================== */

@keyframes fadeOutDown {
	0% {
		opacity: 1;
		transform: translateY(0);
	}
	100% {
		opacity: 0;
		transform: translateY(20px);
	}
}

.ipsAnim_fadeOutDown {
	animation-name: fadeOutDown;
}

/* ======================================================== */

@keyframes pulseOnce {
	0% { transform: scale(1); }
	50% { transform: scale(1.15); }
	100% { transform: scale(1); }
}

.ipsAnim_pulseOnce {
	animation-name: pulseOnce;
}

/* ======================================================== */

@keyframes dummy_anim {
	0% { background-color: var(--i-background_3); }
	50% { background-color: var(--i-background_6); }
	99% { background-color: var(--i-background_3); }
}

