@supports (color: oklch(from var(--i) clamp(0, (.7 - l) * 1000, 1) c h)) and (color: oklch(from red l c h)){
	.i-color_contrast{
		color: oklch(from var(--_i-vs, var(--i-body--ba-co)) clamp(0, (.7 - l) * 1000, 1) c h);
	}
