.i-hover-opacity_10:hover{ opacity: 1; }

/*
	----------------
	- Display
	----------------
*/

.i-display_block{
	display: block;
}

/* Future todo: Replace ipsHide with [hidden] */
.ipsApp .ipsHide,
.i-display_none{
	display: none;
}

.i-display_inline-block{
	display: inline-block;
}

.i-display_grid{
	display: grid;
}

.i-display_contents{
	display: contents;
}

[data-ips-scheme="dark"] .i-display_light,
[data-ips-scheme="light"] .i-display_dark{
	display: none !important;
}

.i-overflow_hidden{
	overflow: hidden;
}

.i-position_relative{
	position: relative;
}

.i-position_cover{
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	border-radius: inherit;
	object-fit: cover;
}

.i-position_sticky-top{
	position: sticky;
	top: calc(var(--i-sticky-offset, 0px) + var(--_i-sticky-margin, 0px));
	z-index: var(--i-z-index_sticky);
}
.i-position_sticky-bottom{
	position: sticky;
	bottom:  var(--_i-sticky-margin, 0px);
	z-index: var(--i-z-index_sticky);
}

:where([dir="ltr"]) .i-float_start,
:where([dir="rtl"]) .i-float_end{
	float: left;
}

:where([dir="ltr"]) .i-float_end,
:where([dir="rtl"]) .i-float_start{
	float: right;
}

.i-height_100p{
	min-height: 100%;
}

.i-width_100p{
	width: 100%;
}

/*
	----------------
	- Images
	----------------
*/

.i-aspect-ratio_10{ aspect-ratio: 10/10 }
.i-aspect-ratio_9{ aspect-ratio: 10/9 }
.i-aspect-ratio_8{ aspect-ratio: 10/8 }
.i-aspect-ratio_7{ aspect-ratio: 10/7 }
.i-aspect-ratio_6{ aspect-ratio: 10/6 }
.i-aspect-ratio_5{ aspect-ratio: 10/5 }
.i-aspect-ratio_4{ aspect-ratio: 10/4 }
.i-aspect-ratio_3{ aspect-ratio: 10/3 }

:where(img[class*="i-aspect-ratio_"]){
	width: 100%;
	object-fit: cover;
}

.i-object-fit_contain{
	object-fit: contain;
}

.i-object-fit_cover{
	object-fit: cover;
}

/*
	----------------
	- Cursor
	----------------
*/

.i-cursor_zoom-in{
	cursor: zoom-in;
}

.i-cursor_not-allowed{
	cursor: not-allowed;
}

.i-cursor_move{
	cursor: move;
}

.i-cursor_pointer{
	cursor: pointer;
}

/*
	----------------
	- Padding
	----------------
*/

.i-padding_1{ padding: var(--i-sp_1); }
.i-padding_2{ padding: var(--i-sp_2); }
.i-padding_3{ padding: var(--i-sp_3); }
.i-padding_4{ padding: var(--i-sp_4); }
.i-padding_5{ padding: var(--i-sp_5); }

.i-padding-top_1,
.i-padding-block_1{ padding-top: var(--i-sp_1); }
.i-padding-bottom_1,
.i-padding-block_1{ padding-bottom: var(--i-sp_1); }
.i-padding-top_2,
.i-padding-block_2{ padding-top: var(--i-sp_2); }
.i-padding-bottom_2,
.i-padding-block_2{ padding-bottom: var(--i-sp_2); }
.i-padding-top_3,
.i-padding-block_3{ padding-top: var(--i-sp_3); }
.i-padding-bottom_3,
.i-padding-block_3{ padding-bottom: var(--i-sp_3); }
.i-padding-top_4,
.i-padding-block_4{ padding-top: var(--i-sp_4); }
.i-padding-bottom_4,
.i-padding-block_4{ padding-bottom: var(--i-sp_4); }
.i-padding-top_5,
.i-padding-block_5{ padding-top: var(--i-sp_5); }
.i-padding-bottom_5,
.i-padding-block_5{ padding-bottom: var(--i-sp_5); }

.i-padding-start_1,
.i-padding-inline_1{ padding-inline-start: var(--i-sp_1); }
.i-padding-end_1,
.i-padding-inline_1{ padding-inline-end: var(--i-sp_1); }
.i-padding-start_2,
.i-padding-inline_2{ padding-inline-start: var(--i-sp_2); }
.i-padding-end_2,
.i-padding-inline_2{ padding-inline-end: var(--i-sp_2); }
.i-padding-start_3,
.i-padding-inline_3{ padding-inline-start: var(--i-sp_3); }
.i-padding-end_3,
.i-padding-inline_3{ padding-inline-end: var(--i-sp_3); }
.i-padding-start_4,
.i-padding-inline_4{ padding-inline-start: var(--i-sp_4); }
.i-padding-end_4,
.i-padding-inline_4{ padding-inline-end: var(--i-sp_4); }
.i-padding-start_5,
.i-padding-inline_5{ padding-inline-start: var(--i-sp_5); }
.i-padding-end_5,
.i-padding-inline_5{ padding-inline-end: var(--i-sp_5); }

.i-padding_0{ padding: 0 }
.i-padding-top_0,
.i-padding-block_0{ padding-top: 0; }
.i-padding-bottom_0,
.i-padding-block_0{ padding-bottom: 0; }
.i-padding-start_0,
.i-padding-inline_0{ padding-inline-start: 0; }
.i-padding-end_0,
.i-padding-inline_0{ padding-inline-end: 0; }

/* Hide elements on desktop */
@media (min-width: 980px){
	.ipsResponsive_hideDesktop,
	.ipsResponsive_showTablet{
		display: none !important;
	}
}

/* Hide elements on tablet and below, OR only show elements on desktops */
@media (max-width: 979px){
	.ipsResponsive_showDesktop{
		display: none !important;
	}
}

/* Hide elements on tablet only */
@media (min-width: 768px) and (max-width: 979px){
	.ipsResponsive_hideTablet{
		display: none !important;
	}
}

/* Hide elements on tablet and above, OR only show elements on phones */
@media (min-width: 768px){
	.ipsResponsive_showPhone{
		display: none !important;
	}
}

/* Hide elements on phones */
@media (max-width: 767px){
	.ipsResponsive_hidePhone,
	.ipsResponsive_showTablet{
		display: none !important;
	}
}

/*
	----------------
	- Font-size
	----------------
*/

.i-font-size_-3{ font-size: max(11px, var(--i-font-size_-3)); }
.i-font-size_-2{ font-size: max(11px, var(--i-font-size_-2)); }
.i-font-size_-1{ font-size: var(--i-font-size_-1); }
.i-font-size_1{ font-size: var(--i-font-size_1); }
.i-font-size_2{ font-size: var(--i-font-size_2); }
.i-font-size_3{ font-size: var(--i-font-size_3); }
.i-font-size_4{ font-size: var(--i-font-size_4); line-height: 1.2; }
.i-font-size_5{ font-size: var(--i-font-size_5); line-height: 1.2; }
.i-font-size_6{ font-size: var(--i-font-size_6); line-height: 1.2; }
.i-font-size_7{ font-size: var(--i-font-size_7); line-height: 1.2; }

/* This allows a smooth transition between font-sizes depending on screen size */
:where(.i-font-size_fluid){
	--_i-min-font-size: 1;
	--_i-max-font-size: 1;
}
.i-font-size_fluid{
	font-size: calc((var(--_i-min-font-size) * var(--i-rem)) + (var(--i-range) * (var(--_i-max-font-size) - var(--_i-min-font-size))));
}


/*
	----------------
	- Font-weight
	----------------
*/

.i-font-weight_100, .i-font-weight_thin{ font-weight: 100; }
.i-font-weight_200, .i-font-weight_extra-light{ font-weight: 200; }
.i-font-weight_300, .i-font-weight_light{ font-weight: 300; }
.i-font-weight_400, .i-font-weight_normal{ font-weight: 400; }
.i-font-weight_500, .i-font-weight_medium{ font-weight: 500; }
.i-font-weight_600, .i-font-weight_semi-bold{ font-weight: 600; }
.i-font-weight_700, .i-font-weight_bold{ font-weight: 700; }
.i-font-weight_800, .i-font-weight_extra-bold{ font-weight: 800; }
.i-font-weight_900, .i-font-weight_black{ font-weight: 900; }


/*
	----------------
	- Utilities
	----------------
*/

.i-font-style_italic{
	font-style: italic;
}

.i-text-transform_uppercase{
	text-transform: uppercase;
}

.i-text-transform_none{
	text-transform: none;
}

.i-text-align_center{
	text-align: center;
}

.i-text-align_start{
	text-align: start;
}

.i-text-align_end{
	text-align: end;
}

.i-word-break_break-all{
	word-break: break-all;
}

.i-text-decoration_underline,
.i-link-text-decoration_underline a,
.i-hover-text-decoration_underline:hover{
	text-decoration: underline;
}

.i-text-decoration_none{
	text-decoration: none;
}

.ipsTableOfContents__link:hover {
    text-decoration: underline;
}

    .ipsTableOfContents__link:hover > :is(.fa,.fas,.fa-solid)::before {
        text-decoration: none;
        display: inline-block;
    }

.ipsTableOfContents__linkOptions {
    z-index: var(--ips-js-zindex-top);
    position: absolute;
    padding-inline-end: 5px;
    flex-direction: column;
    align-items: stretch;
    display: none;
    background: var(--i-dropdown--ba-co);
	color: var(--i-dropdown--co);
	border-radius: var(--i-dropdown--bo-ra);
	box-shadow: var(--i-dropdown--bo-sh);
    padding: 4px;
}

    .ipsTableOfContents__linkOptions--visible {
        display: flex;
    }

.ipsTableOfContents__incrementOptions {
    display: flex;
}

.ipsTableOfContents__linkOptions .ipsButton{
    min-width: 0;
    padding: .7em;
}

.ipsTableOfContents__content {
    display: flex;
    flex-direction: column;
    gap: .5em;
}

.ipsTableOfContents__content > * {
    flex: 1 1 auto;
}

.ipsTableOfContents__item {
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
    max-width: 100%;
    display: inline-block;
}

.ipsTableOfContents__expandable {
    padding-inline-start: 1em;
}

.ipsTableOfContents__expandable > :not(summary),
.ipsTableOfContents__wrapper {
    margin-inline-start: var(--i-sp_2);
}

    .ipsTableOfContents__expandable > summary {
        display: block;
        position: relative;
    }

        .ipsTableOfContents__expandable > summary::after {
            font-weight: 900;
            position: absolute;
            inset-inline-end: calc(1em + 100%);
            content: "\2b";
            font-family: var(--i-font-awesome);
        }

        .ipsTableOfContents__expandable[open] > summary::after {
            content:  "\f068";
        }

.ipsApp .cMemberNotifications .ipsMatrixHeader,
.ipsApp .cMemberNotifications td {
	text-align: start;
}

[data-role="massToggle"], [data-role="toggle"] {
	opacity: 0;
	transition-property: opacity;
	transition-duration: .2s;
	margin-inline-start: 1em;
}

.acpRestrictions_header{
	display: flex;
	align-items: center;
	gap: .9em;
}

.acpRestrictions_subHeader {
	display: flex;
	align-items: center;
	gap: .6em;
	font-weight: 600;
	margin: 10px 0;
}

.acpRestrictions_header + ul {
	padding-inline-start: 15px;
}

.acpRestrictions_header > label {
	font-size: 15px;
}

	.acpRestrictions_subHeader h3 {
		font-size: 14px;
		cursor: pointer;
	}

	.acpRestrictions_subHeader:hover [data-role="massToggle"],
	.acpRestrictions_header:hover [data-role="toggle"] {
		opacity: 1;
	}

.acpRestrictions_subHeader h3:before {
	display: inline-block;
	font-family: var(--i-font-awesome);
	-webkit-font-smoothing: antialiased;
	text-rendering: auto;
	font-weight: 900;
	content: '\f0da';
	margin-inline-end: .6em;
}
[dir="rtl"] .acpRestrictions_subHeader h3:before {
	content: '\f0d9';
}

[dir="ltr"] .acpRestrictions_closed.acpRestrictions_subHeader h3:before {
	content: '\f0da';
}
[dir="rtl"] .acpRestrictions_closed.acpRestrictions_subHeader h3:before {
	content: '\f0d9';
}

.acpRestrictions_open.acpRestrictions_subHeader h3:before {
	content: '\f0d7';
}

.acpRestrictions_panel ul{
	display: grid;
	gap: .6em;
}

.acpRestrictions_closed.acpRestrictions_subHeader + ul {
	display: none;
}

/* Listing badges */
.ipsBadge.ipsBadge--label {
