		padding: 2em;
	}

	.acpMemberView_layoutMain {
		grid-column-start: main;
		grid-column-end: history;
	}

	.acpMemberView_layoutHistory {
		grid-column-start: history;
		grid-column-end: end;
	}
}

/* LEFT COLUMN */
.acpMemberView_photo {
	position: relative;
	text-align: center;
	margin: -45px auto 0;
	max-width: 120px;
}

.acpMemberView_photo .ipsUserPhoto{
	border: 3px solid var(--i-box--ba-co);
}

	.acpMemberView_photo .acpMemberView_editButton {
		position: absolute;
		bottom: 0;
		inset-inline-end: 0;
		white-space: nowrap;
	}

.acpMemberView_map {
