	opacity: .3;
	height: 200px;
}

/* MAIN COLUMN */
.acpMemberView_countStat {
	padding: 10px 15px;
	padding-inline-end: 50px;
	border-radius: 4px;
	display: block;
	position: relative;
	background: var(--i-background_5);
	color: var(--i-color_hard) !important;
}

	.acpMemberView_countStat .ipsMinorTitle {
		color: inherit;
		opacity: 0.8;
	}

	/* Only show arrow on buttons */
	button.acpMemberView_countStat:before {
		content: '';
		position: absolute;
		inset-inline-end: 40px;
		top: 10px;
		bottom: 10px;
		border-inline-start: 1px solid currentColor;
		opacity: .2;
	}

	button.acpMemberView_countStat:after {
		content: '\f0d7';
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-weight: 900;
		position: absolute;
		inset-inline-end: 18px;
		top: 22px;
	}


.acpMemberView_quotaNumber {
	font-size: 18px;
	font-weight: 600;
}

.acpMemberView_percentage {
	font-size: 22px;
	margin-top: 14px;
}

/* MISC */
.acpMemberView_editButton {
	background: var(--i-background_4);
	color: var(--i-color_hard);
	border-radius: 5px;
	padding: 2px 5px;
	font-size: 14px;
}

.acpMemberView_requestUnblockButton {
	background: var(--i-background_negative-soft);
	color: var(--i-color_negative);
}

	.acpMemberView_editButton .fa-caret-down {
