/* Staff Directory > *Group* > Edit */
#elRadio_staff_group_template_staff_group_template li + li{
	margin-top: 30px;
}

.cStaffDirPreview {
	max-width: 300px;
}

.cStaffDirPreview_blocks .cStaffDirPreview_block {
	height: 80px;
}

.cStaffDirPreview_full .cStaffDirPreview_block {
	height: 60px;
}

	.cStaffDirPreview_full .cStaffDirPreview_title {
		position: absolute;
		top: 10px;
		inset-inline-start: 50px;
	}

		.cStaffDirPreview_full .cStaffDirPreview_text {
			position: absolute;
			top: 30px;
			inset-inline-start: 50px;
			inset-inline-end: 10px;
		}

.cStaffDirPreview_block {
	background: var(--i-background_3);
	border-radius: 5px;
	padding: 10px;
	position: relative;
}

.cStaffDirPreview_photo {
	background: var(--i-background_6);
	width: 30px;
	height: 30px;
	border-radius: 30px;
	display: inline-block;
}

.cStaffDirPreview_text, .cStaffDirPreview_text:after {
	display: block;
	border-top: 3px dashed var(--i-background_6);
	border-bottom: 3px dashed var(--i-background_6);
	height: 10px;
}

	.cStaffDirPreview_text:after {
		content: '';
		position: relative;
		top: 12px;
		height: 4px;
		border-bottom: 0;
	}

.cStaffDirPreview_title {
	width: 40px;
	height: 10px;
	background: var(--i-color_root);
	display: inline-block;
}

.cStaffDirPreview_row {
