}

/* ======================================================== */
/* Alerts */

#elAlert {
	padding: 15px;
	display: grid;
	grid-template-columns: 1fr min(600px, calc(100vw - 30px)) 1fr;
	grid-template-rows: 1fr auto 1fr;
	max-height: 100vh;
	overflow: auto;
}

#elAlert.ipsAlert--with-form {
	grid-template-columns: 1fr min(800px, calc(100vw - 30px)) 1fr;
}

#elAlert > .ipsBox {
	grid-row: 2;
	grid-column: 2;
	height: max-content;
}

#elAlert.ipsAlert--with-form > .ipsBox {
	flex: 0 1 800px;
}
	#elAlert.ipsAlert--with-form > .ipsBox > .ipsDialog_title {
		padding-block-start: 1em;
		padding-inline: 1em;
	}

	#elAlert .ipsDialog_title{
		white-space: normal;
	}

		#elAlert .ipsForm > *{
			flex: 0 0 auto;
		}

		#elAlert .ipsDialog_title [class*="fa-"]{
			opacity: .6;
			margin-inline-end: .3em;
			font-size: 14px;
		}

		#elAlert .ipsRichText{
			flex: 1 1 auto;
			overflow-y: auto;
		}

#elAlert.ipsAlert--with-form > .ipsBox > [data-role="reply-prompt"] {
	margin: 1em;
	border-radius: var(--i-box--bo-ra);
	background-color: color-mix(in srgb, var(--i-primary) 20%, transparent);
	color: var(--i-color_root);
}

#elAlert.ipsAlert--with-form [data-role="reply-prompt"] .ipsBadge--negative {
	background-color: var(--i-color_primary);
	color: var(--i-primary-contrast);
	margin-inline-end: 0.5em;
	border-radius: 50%;
	font-weight: 600;
}

#elAlert.ipsAlert--with-form > .ipsBox > hr {
	margin-inline: 1em;
	width: calc(100% - 2em);
}

#elAlert :is(#form_messenger_to, #form_messenger_title, .ipsForm > .ipsSubmitRow) {
	display:none;
}

#elAlert:not([data-alert-required]) #messenger_content_editor .ipsFieldRow__required {
	display: none;
}

@media (min-width: 980px){
	html body {
		margin-inline-start: clamp(300px, 19vw, 500px);
	}
	#elCachingLog {
		position: fixed;
		top: 0;
		bottom: 0;
		inset-inline-start: 0;
		padding-inline-start: 10px;
		padding-top: 20px;
		padding-bottom: 70px;
		width: clamp(300px, 19vw, 500px);
		background: #212223;
		overflow: auto;
	}
	.cCachingLog {
		font-family: monospace;
		color: white;
		cursor: pointer;
	}
	.cCachingLogMethod {
		text-transform: uppercase;
	}
	.cCachingLogMethod_get {
		color: orange;
	}
	.cCachingLogMethod_set {
		color: green;
	}
	.cCachingLogMethod_check {
		color: yellow;
	}
	.cCachingLogMethod_delete {
		color: red;
	}
}

@media screen and (max-width: 979px) {
	#elCachingLog {
		display: none;
	}
}

