	color: var(--i-color_primary);
	font-weight: 500;
}









/* v5 styles below */
#elClubContainer{
	display: contents;
}

#elClubContainer > *{
	margin-bottom: var(--i-sp_block);
}

/* Cover photo tabs */
.cClubControls__tabs .ipsTabs{
	box-shadow: none;
	border-top: 1px solid;
	border-top-color: color-mix(in srgb, var(--i-co) 15%, transparent);
}

.cClubHeader--sidebar .ipsCoverPhotoMeta{
	display: none;
}

/* Browse clubs grid */
.ipsGrid--browse-clubs .ipsCoverPhoto{
	border-radius: 8px;
}

[data-role="internalEmbed"] {
	background: var(--i-background_1) !important;
	overflow: hidden;
}
[data-role="externalEmbed"]{
	background: none !important;
	overflow: hidden;
}

#ipsEmbedLoading {
	display: none;
}

.unloaded #ipsEmbedLoading {
	background: var(--i-background_1);
	display: grid;
	grid-template-columns: 42px 1fr;
	grid-template-rows: 42px 1fr;
	gap: 20px;
	padding: 20px;
	position: fixed;
	inset: 0;
}

@keyframes dummy_anim {
	0%, 100% { opacity: .5 }
	50% { opacity: 1 }
}

#ipsEmbedLoading::before,
#ipsEmbedLoading::after,
#ipsEmbedLoading span::before,
#ipsEmbedLoading span::after {
	display: block;
	content: '';
	background: var(--i-background_5);
	border-radius: 6px;
	animation: dummy_anim 2s infinite;
}

#ipsEmbedLoading::before {
	width: 100%;
	aspect-ratio: 1;
	border-radius: 50%;
}

#ipsEmbedLoading span{
	display: grid;
	gap: .5em;
}

	#ipsEmbedLoading span::before{
		width: 80%;
	}
	#ipsEmbedLoading span::after {
		width: 60%;
	}

#ipsEmbedLoading::after {
	grid-column: span 2;
}

#ipsEmbed {
	opacity: 0.0001;
    overflow: hidden;
}

/* Ensure white background is hidden from embedded tweets while in dark mode */
#ipsEmbed .twitter-tweet{
	border-radius: 15px;
	overflow: hidden;
}

/*
	----------------
	- Leaderboard
	----------------
*/

#elDateForm label {
	display: none;
}

#elDateForm input[type="date"] {
	max-width: 100%;
	margin: .5em 0;
}

.cPastLeaders_row{
	padding: 2em;
	position: relative;
	isolation: isolate;
}

	.cPastLeaders_row:hover{
		background: var(--i-background_hover);
	}

.cPastLeaders_title{
	margin-bottom: 2.2em;
	font-size: 1.8em;
	opacity: .4;
}

	.cPastLeaders_row:hover .cPastLeaders_title{
		opacity: .6;
	}

	.cPastLeaders_title a::before{
		content: '';
		position: absolute;
		inset: 0;
		z-index: -1;
	}

.cPastLeaders_title span{
	display: none;
}

.cPastLeaders_cell{
	position: relative;
	margin-top: 1.2em;
}

.cPastLeaders_cell .ipsLeaderboard_trophy {
	position: absolute;
	top: -.6em;
	inset-inline-start: -.6em;
	z-index: 1;
	font-size: .8em;
}

/*
	----------------
	- Messenger
	----------------
*/

/* Header */
.ipsMessenger__header{
	display: flex;
	justify-content: space-between;
	flex-wrap: wrap;
	gap: 1em;
	padding: 1.4em 2em;
	border-bottom: 1px solid var(--i-background_5);
}

/* Simplified inbox filters */
.ipsMessenger__inbox .ipsButtonBar{
	border-radius: 0;
	padding: 0;
	display: block;
}

/* Disable messenger and search terms */
.ipsMessenger__inbox .ipsMessage{
	--_pa: 1em;
	border-radius: 0;
}

/* Search */
.ipsMessenger__search{
	--i-co: var(--i-color_soft);
	padding: .8em;
	box-shadow: hsl(0 0% 0% / .1) 0px 1px 0px;
}

	.ipsMessenger__search form {
		display: flex;
		position: relative;
		color: var(--i-co);
		background: var(--i-background_3);
		border-radius: var(--i-box--bo-ra);
	}

	.ipsMessenger__search form:focus-within{
		outline: 2px solid currentColor;
	}

	.ipsMessenger__search .fa-magnifying-glass{
		align-self: center;
		position: absolute;
		inset-inline-start: .9em;
		pointer-events: none;
	}

	.ipsMessenger__search [type="text"]{
		flex: 1 1 auto;
		background: none;
		border-width: 0;
		box-shadow: none;
		border-radius: 0;
		padding: .9em 0;
		padding-inline-start: 2.8em;
		font-weight: 500;
		outline-width: 0;
	}

	.ipsMessenger__search-action{
		color: var(--i-co);
		padding: 0 .8em;
		display: grid;
		place-content: center;
		flex: 0 0 auto;
		text-align: center;
	}
		.ipsMessenger__search-action:hover{
			background: var(--i-background_4);
		}

	.ipsMessenger__search-action:last-of-type{
		border-start-end-radius: inherit;
		border-end-end-radius: inherit;
	}

/* Quota */
.ipsMessenger__quota{
	background: var(--i-background_2);
	padding: 1em;
	border-top: 1px solid var(--i-background_4);
}

/* Empty */
.ipsMessenger__conversation .ipsEmpty{
	padding-top: max(100px,15vh);
}

/* This allows the empty message (above) to stretch to full height */
#elMessageViewer{
	display: contents;
}

/* Conversation */
.ipsMessenger__conversation{
	background: var(--i-background_3);
	padding: .1px; /* Fix collapsing margins from header */
	border-end-end-radius: var(--i-box--bo-ra);
}
.ipsMessenger__conversationHeader,
:where(.ipsMessenger__conversation) .ipsEntry{
	background-color: var(--i-background_1);
	background-clip: padding-box;
	border: 1px solid var(--i-background_3);
	margin: 1em;
	border-radius: var(--i-box--bo-ra);
}
.ipsMessenger__conversationHeader{
	padding: 1.5em;
}

	.ipsMessenger__conversation .ipsEntry::before{
		content: none;
	}

.cMessage_leftConvo {
	opacity: 0.5;
}

.ipsMessenger__columns{
	display: grid;
}

/* 2 columns on desktop */
@media (min-width: 850px){
	.ipsMessenger__columns{	
		grid-template-columns: min(420px, 30%) 1fr;
		min-height: 500px;
	}

	.ipsMessenger__inbox{
		border-inline-end: 1px solid var(--i-background_5);
	}

	/* Hide the "Message List" button */
	.ipsButton-backToInbox{
		display: none;
	}

	#elMessageSidebar{
		height: 100%;
		max-height: 100vh;
		display: flex;
		flex-direction: column;
		position: sticky;
		top: var(--i-sticky-offset, 0px);
		z-index: 10; /* This is necessary for the fixed position "with selected" action bar to appear above editor panels and toolbars */
	}

		:where(#elMessageSidebar > *){
			flex: 0 0 auto;
		}

	.ipsMessenger__inboxList{
		overflow-y: auto;
		flex: 1 1 auto;
	}

	.ipsMessenger__quota{
		position: sticky;
		bottom: 0;
		z-index: 1;
		border-end-start-radius: var(--i-box--bo-ra);
	}

}

@media (max-width: 849px){
	.ipsMessenger{
		overflow: hidden;
	}

	.ipsMessenger__inbox,
	.ipsMessenger__conversation{
		grid-area: 1/-1;
	}

	/* Show/hide either inbox or conversation */
	[data-ipsfilterbar-viewing="filterContent"] .ipsMessenger__inbox,
	[data-ipsfilterbar-viewing="filterBar"] .ipsMessenger__conversation{
		display: none;
	}

	.ipsMessenger__conversationHeader,
	:where(.ipsMessenger__conversation) .ipsEntry{
		margin-left: 0;
		margin-right: 0;
		border-left-width: 0;
		border-right-width: 0;
		border-radius: 0;
	}
}

html body {
	margin-inline-end: 300px;
}

#elMetaTagEditor {
	position: fixed;
	top: 0;
	bottom: 0;
	inset-inline-end: 0;
	width: 300px;	
	overflow: auto;
}

#elMetaTagEditor_submit {
	position: -webkit-sticky;
	position: sticky;
	bottom: 0;
	background: #000;
	z-index: 1;
	padding: 1em;
}

#elApprovalToolbar {
	width: auto;
}

#elModCPMemberSearch {
	position: relative;
}

#elModCPApprovalSplash {
	max-width: 56ch;
	margin: 0 auto;
}

/* v5 code */
.ipsColumns--modcpanel > .ipsColumns__secondary{
	background: var(--i-background_2);
	border: 0px solid transparent;
	border-color: color-mix(in srgb, var(--i-co) 10%, transparent);
	border-bottom-width: 1px;
	padding: var(--i-sp_2);
}
.cModCP_header .ipsTitle .fa-solid{
	font-size: .65em;
}

@media (min-width: 980px){
	.ipsColumns--modcpanel > .ipsColumns__secondary{
		border-width: 0;
		border-inline-end-width: 1px;
		padding: var(--i-sp_3);
		border-end-start-radius: var(--i-box--bo-ra);
	}
}

.ipsModCpanel__stickyHeader{
	padding: var(--i-sp_2);
	background: var(--i-background_1);
	background: color-mix(in srgb, var(--i-background_1) 88%, transparent);
	box-shadow: hsl(0 0% 0% / .1) 0px 1px 0px, hsl(0 0% 0% / .04) 0px 1px 10px;
	-webkit-backdrop-filter: blur(6px);
	backdrop-filter: blur(6px);
	position: sticky;
	top: var(--i-sticky-offset, 0px);
	z-index: var(--i-z-index_sticky);
}

.ipsData__item .ipsApprovalQueueItem{
	margin: calc(var(--_padding) * -1);
}

.ipsData__item:not(:last-child) .ipsApprovalQueueItem{
	border-bottom: 5px solid var(--i-background_6);
}

/* Remove border-radius from pagination bar */
.ipsModCpanel .ipsButtonBar{
	border-radius: 0;
}

.cNotificationTypes__row{
	border-bottom: 1px solid var(--i-background_4)
}

	.cNotificationTypes__row:where(:hover) {
		background: var(--i-background_2);
	}

.cNotificationTypes__row--selected{
	background: var(--i-background_2);
}

.cNotificationTypes__toggle{
	width: 1em;
	height: 1em;
	display: grid;
	place-content: center;
}

/* Hide certain elements when either profile or content page is being viewed */
.ipsCoverPhoto--profile:not(.ipsCoverPhoto--minimal) ~ .ipsCoverPhotoMeta [data-action="goToProfile"],
.ipsCoverPhoto--minimal ~ .ipsCoverPhotoMeta [data-action="browseContent"],
.ipsCoverPhoto--minimal #ipsMenu_elprofile_edit{
	display: none !important;
}

/* Profile columns */
.ipsProfileContainer{
	container: ipsProfile / inline-size;
}
.ipsProfile{
	display: grid;
	gap: 1em;
}

.ipsProfile__sticky-inner{
	display: grid;
	gap: 1em;
	grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr));
}

@container (min-width: 768px){
	.ipsProfile{
		grid-template-columns: min(360px, 35%) 1fr;
	}

		.ipsProfile__aside{
			display: grid;
		}

		/* Make sidebar sticky, unless it contains <details> elements (since their dynamic height results in a poor UI) */
		.ipsProfile__sticky-outer{
			min-height: min(100%, calc(100vh - (var(--i-sp_block) * 2) - var(--i-sticky-offset)));
			min-height: min(100%, calc(100svh - (var(--i-sp_block) * 2) - var(--i-sticky-offset)));
			position: sticky;
			bottom: var(--i-sp_block);
			align-self: end;
		}
		.ipsProfile__sticky-inner{
			position: sticky;
			top: calc(var(--i-sticky-offset) + var(--i-sp_block));
		}
}

.ipsProfile__aside .ipsSideMenu{
	padding: 1em;
}

/* Profile reputation, solutions, followers, etc */
.ipsProfile__aside .ipsData:not(.ipsData--profileVisitors){
	--i-data--padding: 1.4em;
	--i-data--title: 1.05em;
}
	.ipsProfile__aside .ipsData:not(.ipsData--profileVisitors) .ipsData__title{
		font-weight: 600;
	}
	.ipsProfile__aside .ipsData:not(.ipsData--profileVisitors) .ipsData__desc{
		margin: 0;
		display: block;
	}

/* Stat icons */
.ipsData--profileMeta .ipsData__icon{
	opacity: .3;
	flex-basis: 1em;
	align-self: center;
	font-size: 16px;
}

/* Show long dates in "About" widget */
.ipsProfile__aside .ipsTime__long{
	display: revert;
}
.ipsProfile__aside .ipsTime__short{
	display: none;
}

.ipsProfileWidget{
	padding: 3em 1.5em;
	border-bottom: 1px solid var(--i-background_3);
	display: block; /* Used for links */
}

/* ACHIEVEMENTS */
.cProfileAchievements > a:hover {
	background: var(--i-background_2);
}

/* REP SCORES */
.cProfileRepScore {
	background: var(--i-background_5);
	color: var(--i-base-contrast_6);
	border-radius: 6px;
	text-align: center;
	display: grid;
	font-weight: 600;
}

.cProfileRepScore--badge{
	font-size: 1.5em;
}

	.cProfileRepScore--positive,
	.cProfileRepScore--solutions {
		background: var(--i-background_positive);
		color: var(--i-color_positive-soft);
	}

	.cProfileRepScore--negative {
		background: var(--i-background_negative);
		color: var(--i-color_negative-soft);
	}

.cProfileRepScore__points {
	font-size: 2em;
}

/* Subscriptions */
.cProfileSubscription {
	display: grid;
    overflow: hidden;
	border-radius: min(var(--i-design-radius), 7px);
	background-color: var(--i-background_dark);
	color: #fff;
	text-align: center;
	font-weight: 600;
}

	.cProfileSubscription > *{
		grid-area: 1/-1;
	}

	.cProfileSubscription img{
		width: 100%;
	}

	.cProfileSubscription__gradient{
	    background-image: linear-gradient(to bottom, rgba(0,0,0,0) 50%, rgba(0,0,0,0.8));
	}

	.cProfileSubscription__text {
		padding: 2em 1em;
		align-self: end;
	}

	.cProfileSubscription--with-image .cProfileSubscription__text{
		padding-top: 5em;
		text-shadow: rgba(0,0,0,0.2) 0px 1px 1px;
	}

/* Rank Progress */
.cRankHistory {
	position: relative;
	z-index: 1;
	display: grid;
	gap: 20px;
}

	.cRankHistory::before {
		content: '';
		width: 2px;
		background: var(--i-color_soft);
		position: absolute;
		top: 10px;
		bottom: 10px;
		inset-inline-start: 19px;
		z-index: -1;
		opacity: .4;
	}

	.cRankHistory__item {
		position: relative;
		display: flex;
		align-items: center;
		gap: var(--i-sp_2);
	}

		.cRankHistory__icon {
			background: var(--i-background_1);
			padding: 3px 0;
			flex: 0 0 auto;
		}

		.cRankHistory__icon img{
			width: 40px;
			aspect-ratio: 1;
			object-fit: cover;
		}

	.cRankHistory__itemBadge--unearned {
		filter: opacity(15%) grayscale(1);
	}

.ipsTabs--profile{
	border-top-left-radius: inherit;
	border-top-right-radius: inherit;
}

/* Cater for sticky tabs when scrollIntoView is run */
.ipsTabs__panels--profile{
	scroll-margin-top: 4.5em;
}

/* Featured content */
.ipsData--featured-content{
	--i-data--display-latest-photo: none;
}
.ipsData--featured-content .ipsData__desc{
	--i-data--desc-truncate: 15;
}

/* Mini thumbnails in promoted content widget */
.ipsGrid--widgets-promoted{
	--i-basis: 40px;
}

.ipsData--mini-grid .ipsGrid--widgets-promoted{
	--i-basis: 20px;
}

@media (min-width: 980px){
	html body {
		margin-inline-end: clamp(300px, 19vw, 500px);
	}

	#elQueryLog {
		position: fixed;
		top: 0;
		bottom: 0;
		inset-inline-end: 0;
		padding-bottom: 70px;
		width: clamp(300px, 19vw, 500px);
		background: #121417;
		color: #fafafa;
		overflow: auto;
	}

	:is(#elQueryLog, .elQueryLogMenu) h3 {
		color: #fff;
		padding: 1em;
		text-align: center;
		font-weight: 600;
	}

	#elQueryLog > div{
		border-bottom: 1px solid hsl(0 0% 100% / .25);
	}

	#elQueryLog [data-ipsdialog] {
		cursor: pointer;
	}

	:is(#elQueryLog, .elQueryLogMenu) .prettyprint {
		border: 0;
		background: transparent;
		white-space: pre-wrap;
		padding: 1.2em;
	}

	:is(#elQueryLog, .elQueryLogMenu) .prettyprint:hover{
		background: hsl(0 0% 100% / .08);
	}


}

@media screen and (max-width: 979px) {
	#elQueryLog {
		display: none;
	}
}

/* Referral banners */
.cReferralsGrid__image {
	background-image: var(--_referralBanner, none);
	background-size: cover;
	background-position: 50%;
}
	.cReferralsGrid__image img {
		width: 100%;
		height: 100%;
		object-fit: contain;
		object-position: 50%;
		backdrop-filter: blur(20px);
		background-image: linear-gradient(color-mix(in hsl, var(--i-background_1) 70%, transparent) 0 0);
	}

/* Referral URL inputs */
.cReferralLinks [type="text"] {
	font-family: "Courier New", monospace;
	-webkit-user-select: all;
	user-select: all;
}

@media screen and (min-width: 768px) {
	/* Search again button */
	.cSearchWrapper__button{
		position: absolute;
		inset-inline-end: 0;
		top: 0; bottom: 0;
		display: flex;
		align-items: center;
		padding: 0 7px;
	}
	#elMainSearchInput {
		padding-inline-end: 128px;
	}
}

.cLoginServiceIcon {
	display: inline-block;
	width: 30px;
	text-align: center;
}

.cLoginServiceIcon img {
	max-height: 16px;
	max-width: 30px;
    filter: brightness(20%);
}

.ipsSideMenu_itemActive .cLoginServiceIcon img {
	filter: brightness(100%);
}

.cStreamFilter {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(12em, 1fr));
	gap: 1px;
	border-bottom: 1px solid var(--i-background_4);
	overflow: hidden; /* gap overflow */
}

	.cStreamFilter > li {
		outline: 1px solid var(--i-background_3);
	}
		.cStreamFilter__toggle{
			display: block;
			width: 100%;
			padding: 1.3em;
			color: inherit;
			outline-offset: -2px;
			position: relative;
		}

			.cStreamFilter__toggle:hover{
				background-color: color-mix(in srgb, var(--i-background_3) 50%, transparent);
			}

			.cStreamFilter__toggle[aria-expanded="true"] {
				background: var(--i-primary);
				color: var(--i-primary-contrast);
			}

			.cStreamFilter__toggle .ipsMenuCaret{
				position: absolute;
				inset-inline-end: 1em;
			}

		.cStreamFilter__title {
			display: block;
			font-weight: 600;
			font-size: 1.05em;
			white-space: nowrap;
			overflow: hidden;
			text-overflow: ellipsis;
		}

	.cStreamFilter__blurb em {
		opacity: 0.3;
	}

	.cStreamFilter__blurb {
		display: block;
		overflow: hidden;
		white-space: nowrap;
		text-overflow: ellipsis;
	}

/* If the filter form doesn't exist, hide the toggle button. We do this with JS too in ips.streams.main.js for older browsers, but the below prevents the button from flashing on page load */
.ipsBox--activity-stream:not(:has(#elStreamFilterForm)) [aria-controls="elStreamFilterForm"]{
	display: none;
}

/* FILTER FORM STYLES */
.cStreamForm_list > li {
	position: relative;
}

.cStreamForm_list .ipsSideMenu_item.cStream_withOptions {
	margin-inline-end: 45px;
}

.cStreamForm_menu {
	padding: .6em;
	cursor: pointer;
	position: absolute;
	top: 0;
	inset-inline-end: 0;
	border-radius: min(var(--i-design-radius), .45em);
	border-start-start-radius: 0;
	border-end-start-radius: 0;
	color: #fff;
	background: hsl(0 0% 100% / .1);
	/* Hide by default, only show when active */
	visibility: hidden;
}

/* Hover */
.cStreamForm_menu:hover{
	background: hsl(0 0% 100% / .2);
}

/* Display cog icon when item is active */
.ipsSideMenu_itemActive + .cStreamForm_menu {
	visibility: visible;
}

.ipsSideMenu_itemActive + .cStreamForm_menu{

}

.cStreamForm_list[data-filterType="type"] .ipsSideMenu_item .cStreamForm_menu + a {
	margin-inline-end: 45px;
}

.cStreamForm_nodes {
	display: block;
	margin-inline-start: 2em;
	border-inline-start: 2px solid var(--i-background_3);
}

/* Tags page */
#elTagHeader .ipsCoverPhoto{
	padding: 8px;
	padding-bottom: 0;
}
	#elTagHeader .ipsCoverPhoto__container--default{
		aspect-ratio: auto;
		min-height: 0;
	}

/* Theme Editor */
html{
	overflow: hidden;
}
[data-ips-scheme="light"] i-theme-editor{
	--panel--ba-co: hsl(220 20% 100%);
	--panel--ba-co-alt: hsl(220 20% 96%);
	--panel--ba-co-active: hsl(220 20% 88%);
	--panel--co: hsl(220 20% 30%);
	--panel--co_soft: hsl(220 20% 50%);
	--panel--co_hard: hsl(220 20% 0%);
	--panel--bo-co: hsl(220 20% 80%);
	--vte-tooltip: hsl(220 20% 20%);
}

[data-ips-scheme="dark"] i-theme-editor{
	--panel--ba-co: hsl(220 10% 12%);
	--panel--ba-co-alt: hsl(220 10% 23%);
	--panel--ba-co-active: hsl(220 10% 30%);
	--panel--co: hsl(220 10% 70%);
	--panel--co_soft: hsl(220 10% 50%);
	--panel--co_hard: hsl(220 10% 90%);
	--panel--bo-co: hsl(220 10% 30%);
	--vte-tooltip: hsl(220 10% 40%);
}

i-theme-editor{
	display: grid;
	grid-template-columns: 1fr clamp(370px, 18vw, 450px);
	position: fixed;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	font-weight: normal;
}

i-theme-editor::-webkit-scrollbar {
	display: none;
}

i-theme-editor button{
	touch-action: manipulation;
}

i-theme-editor .i-color_soft{
	color: var(--panel--co_soft);
}
i-theme-editor .i-color_hard{
	color: var(--panel--co_hard);
}

	live-preview{
		background: oklch(32% calc(clamp(0, 100 - var(--i-base-c), 1) * 5%) var(--i-base-h));
		display: flex;
		justify-content: center;
		align-items: center;
		position: relative;
	}

	live-preview iframe{
		width: 100%;
		height: 100%;
		max-width: 100vw;
		max-height: 100vh;
		transition: .5s;
		background: var(--panel--ba-co);
	}

		:is([data-workspace-size="small"], [data-workspace-size="medium"]) live-preview iframe{
			max-width: 1180px;
			max-height: 820px;
			height: calc(100vh - 20px);
			width: calc(100% - 20px);
			border-radius: 10px;
		}

		[data-workspace-size="small"] live-preview iframe{
			max-width: 393px;
			max-height: 760px;
		}

	i-theme-editor[data-loading] live-preview::after{
		content: '';
		width: 50px;
		height: 50px;
		border-radius: 50%;
		border: 5px solid hsl(0 0% 100% / .4);
		border-top-color: #fff;
		animation: iframeLoad .6s linear infinite;
		position: absolute;
		margin: auto;
	}

	@keyframes iframeLoad {
		100% {
			transform: rotate(360deg);
		}
	}

	i-theme-editor[data-loading] live-preview iframe{
		opacity: 0;
	}

.editor__form{
	display: grid;
	grid-template-columns: auto 1fr;
	background: var(--panel--ba-co);
	color: var(--panel--co);
	box-shadow: hsl(0 0% 0% / .08) calc(var(--i-lang-dir) * -2px) 0px 0px;
	font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
	font-size: 14px;
	line-height: 1.5;
	position: relative;
}

	editor-panels{
		display: grid;
		grid-template-rows: 1fr auto;
		grid-template-areas: 'panel' 'footer';
		overflow: hidden;
		height: 100%;
	}

	editor-buttons{
		border: 0px solid var(--panel--bo-co);
		border-inline-end-width: 1px;
		padding: 6px;
		padding-bottom: calc(env(safe-area-inset-bottom) + 6px);
		display: flex;
		flex-direction: column;
	}

		editor-buttons div{
			display: grid;
			gap: 6px;
			flex: 0 0 auto;
		}

		@media (min-width: 701px){
			/* Space out workspace toggles on large screens */
			editor-buttons div:not(:last-of-type){
				margin-bottom: 2em;
				padding-bottom: 2em;
				border-bottom: 1px solid var(--panel--bo-co);
			}
		}

		editor-buttons :is(a, button){
			position: relative;
			width: 42px;
			height: 42px;
			display: flex;
			align-items: center;
			justify-content: center;
			gap: .8em;
			border-radius: 4px;
			color: inherit;
		}

		@media (any-hover:hover){
			editor-buttons :where(:is(a, button):hover){
				background-color: var(--panel--ba-co-alt);
			}
		}

		/* The light/dark values are used here instead of aria-current because the alternative is to use JS to find if light/dark should be active when System is selected */
		editor-buttons [data-active],
		[data-ips-scheme="light"] [data-ips-prefers-color-scheme="light"],
		[data-ips-scheme="dark"] [data-ips-prefers-color-scheme="dark"] {
			background-color: var(--panel--ba-co-active);
		}

		editor-buttons [type="submit"]{
			background: #46c371;
			color: #fff;
		}

			.editor-buttons__tooltip{
				position: absolute;
				inset-inline-end: calc(100% + 10px);
				top: 50%;
				background: var(--vte-tooltip);
				color: #fff;
				padding: .4em 1em;
				border-radius: 4px;
				white-space: nowrap;
				pointer-events: none;
				font-weight: bold;
				font-size: 12px;
				transform: translateY(-50%);
				transition: .1s;
			}

				.editor-buttons__tooltip::after{
					content: '';
					border: 5px solid transparent;
					border-inline-start-color: var(--vte-tooltip);
					position: absolute;
					inset-inline-start: 100%;
					top: 50%;
					transform: translateY(-50%);
				}

				editor-buttons :is(a, button):not(:hover) .editor-buttons__tooltip{
					transform: translateY(-50%) translateX(calc(-20px * var(--i-lang-dir)));
					opacity: 0;
				}

				@media(hover:none){
					.editor-buttons__tooltip{
						display: none;
					}
				}

			editor-buttons [data-active] :is(.fa-lightbulb, .fa-moon){
				font-weight: 900;
			}

			.editor-buttons__text{
				font-weight: 600;
			}

/*
	----------------
	- Panels
	----------------
*/

editor-panel{
	grid-area: panel;
	--panel-direction: 1;
	display: flex;
	flex-direction: column;
	transition-property: opacity, transform;
	transition-duration: .3s;
	background-color: var(--panel--ba-co);
	padding-top: env(safe-area-inset-top);
}
	[data-panel-prev]{
		--panel-direction: -1;
	}

	editor-panel[aria-hidden="true"]{
		opacity: 0;
		pointer-events: none;
		transform: translateX(calc(30% * var(--panel-direction)));
	}

	/* Safari scroll fix */
	editor-panel[aria-hidden="false"]{
		z-index: 1;
	}

	editor-panel > *{
		flex: 0 0 auto;
	}

/* Header */
editor-panel header{
	padding: clamp(1.2em, 5vw, 2em);
}

	editor-panel header :is(h1, h2, h3, h4){
		font-weight: 600;
		color: var(--panel--co_hard);
		font-size: 1.4em;
		line-height: 1.2;
	}

	editor-panel header p{
		font-weight: 500;
		color: var(--panel--co_soft);
		margin-top: .4em;
	}

/* Back button */
[data-panel-nav="back"]{
	color: var(--panel--co);
	padding: 1.4em;
	text-transform: uppercase;
	font-weight: 600;
	font-size: .9em;
	outline-offset: -2px;
}

	[data-panel-nav="back"]::before{
		content: '\2190';
		margin-inline-end: .5em;
		transition: transform .3s;
		display: inline-block;
	}

	[dir="rtl"] [data-panel-nav="back"]::before{
		transform: scaleX(-1);
	}

	@media (any-hover:hover){
		[dir="ltr"] [data-panel-nav="back"]:hover::before{
			transform: translateX(-5px);
		}
		[dir="rtl"] [data-panel-nav="back"]:hover::before{
			transform: scaleX(-1) translateX(-5px);
		}
		[data-panel-nav="back"]:hover{
			background: var(--panel--ba-co-alt);
		}
	}


/* Navigation list */
.theme-editor__nav{
	padding: .6em;
	display: grid;
}
.theme-editor__nav:not(:has(button)){
	display: none;
}

.theme-editor__nav button{
	display: flex;
	align-items: center;
	font-size: 1.1em;
	font-weight: 550;
	width: 100%;
	gap: 1em;
	padding: .8em 1.4em;
	border-radius: 6px;
}

	.theme-editor__nav button::after{
		content: '\f105';
		transition-property: opacity, transform;
		transition-duration: .2s;
		margin-inline-start: auto;
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-style: normal;
		font-weight: 900;
	}

	[dir="rtl"] .theme-editor__nav button::after{
		content: '\f104';
	}

	.theme-editor__nav [aria-controls="dialog__customCSS"]::after{
		content: none;
	}

	.theme-editor__nav button i{
		width: 1.2em;
		opacity: .3;
		text-align: center;
	}

	@media (any-hover:hover){
		.theme-editor__nav button:hover{
			background: var(--panel--ba-co-alt);
		}
		.theme-editor__nav button:not(:hover)::after{
			opacity: .2;
			transform: translateX(calc(var(--i-lang-dir) * -.5em));
		}
		.theme-editor__nav button:hover i{
			opacity: 1;
		}
	}

	.theme-editor__nav hr{
		border-top: 1px solid currentColor;
		margin: 1em 0;
		opacity: .2;
	}

/*
	----------------
	- Settings
	----------------
*/

.theme-editor__scroll{
	flex: 1 1 auto;
	overflow: auto;
	scrollbar-width: none;
}

	.theme-editor__scroll::-webkit-scrollbar {
		-webkit-appearance: none;
		width: 0px;
	}

theme-setting{
	display: block;
}

theme-setting:where(:not([data-type="color"])){
	padding: 20px 20px;
}

theme-setting[data-type="color"]{
	display: flex;
}

theme-setting[data-setting="header-drag"]{
	padding: 30px 5px;
}

/* Align elements inside settings */
.theme-editor__align-setting{
	display: flex;
	align-items: center;
	gap: 5px;
}

editor-panel label{
	flex: 0 1 auto;
	font-weight: 600;
	color: var(--panel--co_hard);
	cursor: pointer;
	align-self: center;
}

editor-panel small{
	flex: 1 1 100%;
	font-weight: normal;
	font-size: .9em;
	color: var(--panel--co_soft);
}

/* Make buttons (to different views) look like links */
[data-layout-link]:not([href="#"]){
	text-decoration: underline;
	display: inline;
	color: var(--panel--co_hard);
}

	[data-layout-link][href="#"]{
		pointer-events: none;
	}

:where(.theme-editor__settings) > li{
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 0 5px;
	padding: 30px 30px;
}

/* Text inputs */
editor-panel [type="text"]{
	padding: .6em 1em;
	width: 100%;
	background: var(--panel--ba-co-alt);
	border-radius: 5px;
	margin-top: .6em;
	outline-offset: 0px;
}

/* Checkboxes */
editor-panel [type="checkbox"]{
	-webkit-appearance: none;
	appearance: none;
	display: inline-block;
	font-size: 1.1em;
	height: 1em;
	width: 2em;
	align-self: center;
	flex: 0 0 auto;
	cursor: pointer;
	background-color: var(--panel--co_soft);
	/* Chrome requires the variable. Safari requires var(--i-co) instead of currentColor */
	--_bo-sh: inset color-mix(in srgb, var(--panel--co) 20%, transparent) 0px 0px 0px 1px;
	box-shadow: var(--_bo-sh);
	border-radius: 50px;
	position: relative;
	transition: background .15s;
	margin-inline-start: auto;
}

	editor-panel [type="checkbox"]::before{
		content: '';
		background: #fff;
		border-radius: inherit;
		position: absolute;
		inset-inline-start: 0;
		height: 1em;
		width: 1em;
		border: 3px solid transparent;
		background-clip: padding-box;
		transition: transform .15s;
	}

	editor-panel [type="checkbox"]:checked{
		background: #21d578;
	}

	editor-panel [type="checkbox"]:checked::before{
		inset-inline-start: 100%;
		transform: translateX(calc(-100% * var(--i-lang-dir, 1)));
	}

/* Range */
editor-panel [type="range"] {
	--i-co: var(--panel--co);
	-webkit-appearance: none;
	appearance: none;
	background: transparent;
	cursor: ew-resize;
	width: 100%;
	border: 0;
	height: 1.4em;
	box-shadow: none;
	padding: 0;
	color: var(--i-co);
}

@media (any-hover:hover){
	editor-panel :hover > [type="range"]{
		--_track--op: .7;
		--_thumb--sc: 1;
	}
}

editor-panel [type="range"]:focus-visible{
	--_track--op: .7;
	--_thumb--sc: 1;
}

editor-panel [type="range"]::-webkit-slider-runnable-track {
	background: currentColor;
	opacity: var(--_track--op, .2);
	height: 1px;
	transition: .2s;
}
editor-panel [type="range"]::-moz-range-track {
	background: currentColor;
	opacity: var(--_track--op, .2);
	height: 1px;
	transition: .2s;
}

editor-panel [type="range"]::-webkit-slider-thumb {
	-webkit-appearance: none;
	appearance: none;
	margin-top: -6px;
	background-color: var(--i-co);
	border: none;
	height: 12px;
	width: 5px;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	outline: 2px solid var(--panel--ba-co);
}
editor-panel [type="range"]::-moz-range-thumb {
	background-color: var(--i-co);
	border: none;
	height: 12px;
	width: 5px;
	transform: scale(var(--_thumb--sc, .7));
	transition: .2s;
	outline: 2px solid var(--panel--ba-co);
}

@media(hover:none){
	editor-panel [type="range"]::-webkit-slider-thumb {
		width: 40px;
		height: 20px;
		margin-top: -10px;
		border-radius: 6px;
		transform: none;
	}
}

#panel__oklch [type="range"]{
	border-radius: 15px;
	box-shadow: inset var(--if-light, hsl(0 0% 0% / .3)) var(--if-dark, hsl(0 0% 100% / .3)) 0px 0px 0px 1px;
	padding: 5px;
	height: auto;
}

[data-ips-scheme="light"] #panel__oklch :is(#light__i-base-l, #dark__i-base-l){
	background: linear-gradient(in oklch to right, oklch(70% calc(var(--i-base-c) * 50%) var(--i-base-h)), oklch(100% 1% var(--i-base-h)));
}

[data-ips-scheme="dark"] #panel__oklch :is(#light__i-base-l, #dark__i-base-l){
	background: linear-gradient(in oklch to right, oklch(20% calc(var(--i-base-c) * 50%) var(--i-base-h)), oklch(60% calc(var(--i-base-c) * 50%) var(--i-base-h)));
}

#panel__oklch #light__i-base-c,
#panel__oklch #dark__i-base-c{
	background: linear-gradient(in oklch to right, oklch(70% .1% var(--i-base-h)), oklch(70% 80% var(--i-base-h)));
}

#panel__oklch #light__i-base-h,
#panel__oklch #dark__i-base-h{
	background: linear-gradient(in oklch longer hue to right, oklch(70% 50% 0), oklch(70% 50% 360));
}

#panel__oklch [type="range"]::-webkit-slider-runnable-track {
	opacity: 1;
    background: none;
	height: auto;
}
#panel__oklch [type="range"]::-moz-range-track {
	opacity: 1;
    background: none;
	height: auto;
}
#panel__oklch [type="range"]::-webkit-slider-thumb {
	width: auto;
    height: 20px;
	aspect-ratio: 1;
    background: hsl(0 0% 0% / .3);
    outline: 2px solid white;
    outline-offset: -3px;

	transform: none;
	margin: 0;
	border-radius: 50%;
}
#panel__oklch [type="range"]::-moz-range-thumb {
	width: auto;
    height: 20px;
	aspect-ratio: 1;
    background: hsl(0 0% 0% / .3);
    outline: 2px solid white;
    outline-offset: -3px;

	transform: none;
	margin: 0;
	border-radius: 50%;
}

/* File upload */
.theme-editor__input-file{
	position: relative;
	min-height: 60px;
	background: var(--panel--ba-co-alt);
	border-radius: 6px;
	flex: 1 1 100%;
	margin-top: 1em;
	display: flex;
	align-items: center;
	gap: 1em;
	padding: 1em;
}
@media (any-hover:hover){
	.theme-editor__input-file:hover{
		background: var(--panel--ba-co-active);
	}
}
editor-panel [type="file"]{
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	opacity: 0;
	cursor: pointer;
	z-index: 1;
}

	[data-file-preview]{
		flex: 1 1 auto;
		position: relative;
	}

	[data-file-preview]::before{
		font-family: var(--i-font-awesome);
		-webkit-font-smoothing: antialiased;
		text-rendering: auto;
		font-style: normal;
		font-weight: 900;
		display: grid;
		place-content: center;
		position: absolute;
		inset: 0;
		font-size: 2em;
		opacity: .2;
	}

	[data-file-preview] img{
		outline-width: 0;
		max-height: 60px;
	}

	[data-file-preview-delete]{
		flex: 0 0 auto;
		width: 2em;
		height: 2em;
		display: grid;
		place-content: center;
		position: relative;
		z-index: 2;
		font-size: 1.3em;
	}

		[data-file-preview-delete]:not(:hover){
			opacity: .5;
		}

	[data-file-preview]:not(:has(*)) ~ button{ display: none }
	[data-file-preview]:not(:has(*))::before{ content: '\f055' }

	@supports not selector(a:has(b)){
		[data-file-preview]:-moz-only-whitespace ~ button{ display: none }
		[data-file-preview]:-moz-only-whitespace::before{ content: '\f055' }
	}

/* Range sync inputs */
editor-panel [type="number"]{
	-moz-appearance: textfield;
	margin-inline-start: auto;
	flex: 0 0 5ch;
	text-align: end;
	border-radius: 6px;
	padding: .4em;
	padding-inline-start: 0;
	font-variant-numeric: tabular-nums;
	font-weight: 600;
}

	editor-panel [type="number"]::-webkit-outer-spin-button,
	editor-panel [type="number"]::-webkit-inner-spin-button {
		-webkit-appearance: none;
		margin: 0;
	}

	editor-panel [type="number"]:not([data-range-output]),
	editor-panel [type="number"][data-range-output]:is(:hover, :focus){
		background: var(--panel--ba-co-alt);
	}

	editor-panel [type="number"]:not([data-range-output]){
		text-align: center;
	}

/* Select */
editor-panel select{
	--i-outline-width: 0px;
	color: inherit;
	padding: .7em 1.2em;
	padding-inline-end: 2.3em;
	cursor: pointer;
	background-image: var(--i-select--arrow);
	background-size: auto 1em;
	background-repeat: no-repeat;
	background-position: calc(100% - .8em) 50%;
	border-radius: 6px;
	background-color: var(--panel--ba-co-alt);
	border-width: 0;
	font-size: .9em;
	flex: 0 0 auto;
	field-sizing: content;
	margin-inline-start: auto;
	text-overflow: ellipsis;
	overflow: hidden;
	outline-offset: -2px;
	text-align: end;
}

editor-panel select:hover{
	background-color: color-mix(in srgb, var(--panel--ba-co-alt), white 5%);
}

editor-panel select:focus{
	outline-width: 0;
}

editor-panel select:focus-visible{
	outline: 2px solid currentColor;
}

[dir="rtl"] editor-panel select{
	background-position: 1em 50%;
}

/* Hide the tabs and swatches when the color picker UI is requested */
[data-show-tool="colorPicker"] :is(i-tabs, #content__colorSelector__swatches_panel){
	display: none !important;
}

[data-show-tool="colorPicker"] #content__colorSelector__colorPicker_panel{
	display: block !important;
}

/* Color palette buttons */
.theme-editor__palette{
	display: grid;
	gap: 5px;
	border-bottom: 1px solid var(--panel--bo-co);
	padding: 20px;
	margin-bottom: 20px;
	text-align: center;
	font-weight: 600;
}

	.theme-editor__palette button{
		padding: 3em 0;
		background: var(--ba-co);
		color: var(--i-co);
		position: relative;
		overflow: hidden;
		border-radius: 5px;
		outline-offset: -6px;
	}

	.theme-editor__palette [data-controls*="primary"]{
		--ba-co: var(--i-primary);
		--i-co: var(--i-primary-contrast);
	}
	.theme-editor__palette [data-controls*="secondary"]{
		--ba-co: var(--i-secondary);
		--i-co: var(--i-secondary-contrast);
	}
	.theme-editor__palette [data-controls*="base"]{
		--ba-co: var(--i-background_3);
		--i-co: var(--i-color_root);
	}

	[data-ips-scheme="light"] .theme-editor__palette [data-controls^="dark"],
	[data-ips-scheme="dark"] .theme-editor__palette [data-controls^="light"]{
		display: none;
	}

	.theme-editor__palette button::after{
		content: '';
		position: absolute;
		inset: 0;
		background: currentColor;
		opacity: 0;
		transition: .15s;
	}

	.theme-editor__palette button:hover::after{
		opacity: .15;
	}

/* Swatch buttons */
.theme-editor__swatches{
	position: relative;
	padding: .5em;
}

	.theme-editor__swatches + .theme-editor__swatches{
		margin-top: 1em;
		border-top: 1px solid var(--panel--bo-co);
		padding-top: 1.5em;
	}

	.theme-editor__swatches li{
		display: flex;
	}

		/* Hide light/dark settings when necessary */
		[data-ips-scheme="dark"] [data-setting^="light__"],
		[data-ips-scheme="light"] [data-setting^="dark__"] {
			display: none !important;
		}

	.theme-editor__swatch{
		flex: 1 1 100%;
		display: flex;
		align-items: center;
		gap: .7em;
		padding: .8em 1em;
		border-radius: 6px;
		font-size: max(.92em, 13px);
	}

	.theme-editor__swatch[style*="--swatch"]::before{
		--i-co: var(--panel--co);
		content: '';
		flex: 0 0 auto;
		width: 2em;
		height: 2em;
		border-radius: 50%;
		background: var(--swatch);
		color: var(--i-co);
		border: 1px solid;
		border-color: color-mix(in srgb, var(--i-co) 30%, transparent);
		display: grid;
		place-content: center;
		font-size: .8em;
	}

	.theme-editor__swatch[aria-current][style*="--swatch"]::before{
		outline: 2px solid var(--panel--co);
		outline-offset: -1px;
		box-shadow: inset 0 0 0 2px var(--panel--ba-co);
	}

	.theme-editor__revert{
		flex: 0 0 auto;
		display: flex;
		align-items: center;
		gap: .7em;
		padding: 0 .8em;
		border-radius: 6px;
		font-size: max(.92em, 13px);
	}

		@media (any-hover:hover){
			:is(.theme-editor__swatch, theme-setting[data-type="color"] .theme-editor__revert):where(:hover){
				background: var(--panel--ba-co-alt);
				color: var(--panel--co_hard);
			}
		}

		.theme-editor__swatch[aria-current]{
			background: var(--panel--ba-co-active);
			color: var(--panel--co_hard);
		}

	editor-tab-content hr{
		height: 1px;
		flex: 1 1 100%;
		margin: 1em;
		background: var(--panel--bo-co);
	}

/* Only show certain categories of swatches */
/*
[data-show-swatches] [data-swatch-category]{
	display: none;
}

[data-show-swatches*="base"] [data-swatch-category="base"],
[data-show-swatches*="contrast"] [data-swatch-category="contrast"],
[data-show-swatches*="brand"] [data-swatch-category="brand"]{
	display: block;
}
*/

/*
	----------------
	- Tabs
	----------------
*/

/* Hide tabs if they're not needed */
[data-hide-tabs] i-tabs{
	display: none;
}
	editor-panel .ipsTabs{
		--co: var(--panel--co_soft);
		--i-co: var(--panel--co_soft);
		--_hover-co: var(--panel--co_hard);
		--_hover-ba-co: var(--panel--ba-co-alt);
		--_active-co: var(--panel--co_hard);
		--_active-ba-co: var(--panel--ba-co-active);
		border: 1px solid color-mix(in srgb, currentColor 10%, transparent);
		border-width: 1px 0;
		background: color-mix(in srgb, currentColor 4%, transparent);
		padding: 8px;
	}

	editor-panel .ipsTabs [role="tablist"]{
		gap: 4px;
	}

	editor-panel .ipsTabs i{
		margin-inline-end: .4em;
		opacity: .6;
	}

editor-tab-content{
	display: block;
	padding: .5em;
}

editor-tab-content[aria-hidden="true"]{
	display: none;
}

/* Show both tab containers if the tabs are hidden, incase the colors are the only options */
[data-hide-tabs] editor-tab-content{
	display: block;
}

/*
	----------------
	- Color panel
	----------------
*/

/* Color preview */
[data-color-preview]{
	width: 40px;
	flex: 0 0 auto;
	aspect-ratio: 1;
	background: var(--_background, hsl(0 0% 50%));
	border: 1px solid;
	border-color: color-mix(in srgb, currentColor 20%, transparent);
	border-radius: 8px;
}

/* This lets the color picker update to the selected color when a swatch is clicked. Swatches are defined in oklch, so we need to convert to hsl for getComputedStyle to use the right format */
@supports (background: hsl(from var(--_background, hsl(0 0% 50%)) h s l)){
	[data-color-preview]{
		background: hsl(from var(--_background, hsl(0 0% 50%)) h s l);
	}
}

/* Color picker */
color-picker{
	display: block;
}

[data-color-picker]{
	padding-top: 3em;
}

.IroBox, .IroSlider{
	margin-left: auto;
	margin-right: auto;
}

/* Color picker text input */
editor-panel [data-color-picker-text]{
	outline: none;
	text-align: center;
	font-size: 1.2em;
	font-weight: 500;
	border-bottom: 2px solid;
	border-color: color-mix(in srgb, currentColor 10%, transparent);
	margin: 16px auto 0;
	display: block;
	padding: 0.5em;
	max-width: 280px;
	border-radius: 0;
	background: none;
}

	[data-color-picker-text]:is(:hover, :focus){
		border-color: color-mix(in srgb, currentColor 30%, transparent);
	}


/* Reorder header */
@media (any-hover:hover){
	.i-display_no-hover{
		display: none;
	}
}
@media (hover: none){
	.i-display_hover{
		display: none;
	}
}

.theme-editor__reorder{
	--i-co: var(--panel--co_soft);
	color: var(--i-co);
	display: flex;
	flex-wrap: wrap;
	font-weight: 600;
	border-radius: 5px;
	font-size: 10px;
    text-transform: uppercase;
    font-weight: 700;
}

	.theme-editor__reorder [draggable]{
		flex: 1 0 auto;
		min-width: 3em;
		min-height: 3em;
		line-height: 3em;
		padding: 0 .8em;
		border: 2px dashed transparent;
		border-radius: 2px;
		cursor: grab;
		user-select: none;
		overflow: hidden;
		margin: 1px;
		text-align: start;
		background: var(--panel--co);
		color: var(--panel--ba-co);
	}

	/* Large blocks for primary/secondary rows */
	.theme-editor__reorder :is([data-pos="4"], [data-pos="5"], [data-pos="6"]){
		min-height: 6em;
		line-height: 6em;
	}

	.theme-editor__reorder :is([data-pos="7"], [data-pos="8"], [data-pos="9"]){
		min-height: 4em;
		line-height: 4em;
	}

	.theme-editor__reorder > :not([data-label]){
		flex-grow: 20;
		opacity: .2;
	}
	.theme-editor__reorder > :not([data-label]):hover{
		opacity: .4;
	}

	.theme-editor__reorder [data-label="Navigation"],
	.theme-editor__reorder [data-label="Breadcrumb"]{
		flex-grow: 999;
	}

	.theme-editor__reorder :is([data-pos="2"], [data-pos="5"], [data-pos="8"], [data-pos="11"])[data-label="Search"]{
		flex-grow: 100;
	}

	.theme-editor__reorder :is([data-pos="2"], [data-pos="5"], [data-pos="8"], [data-pos="11"]){
		text-align: center;
	}
	.theme-editor__reorder :is([data-pos="3"], [data-pos="6"], [data-pos="9"], [data-pos="12"]){
		text-align: end;
	}
	.theme-editor__reorder [data-label="Breadcrumb"]{
		text-align: start;
	}

	.theme-editor__reorder [draggable]:active{
		cursor: grabbing;
	}

	.theme-editor__reorder [draggable]::before{
		content: attr(data-label);
	}

	.theme-editor__reorder-break{
		flex: 1 1 100%;
	}

	.theme-editor__reorder [data-dragging]{
		opacity: .6;
	}

	@media (hover:none){
		.theme-editor__reorder [data-dragging]{
			background-image: linear-gradient(var(--if-light,hsl(0 0% 0% / .7)) var(--if-dark,hsl(0 0% 100% / .7)) 0% 100%);
		}
	}

	.theme-editor__reorder [data-dropzone]{
		background: var(--panel--ba-co-alt);
		border-color: var(--panel--co);
		opacity: 1;
	}

	@media (any-hover:hover){
		.theme-editor__reorder [draggable][data-label]:hover{
			background-image: linear-gradient(var(--if-light,hsl(0 0% 0% / .5)) var(--if-dark,hsl(0 0% 100% / .5)) 0% 100%);
		}
	}

/* Hide the "Top" and "Secondary" header height settings if the rows are empty in the drag/drop editor */
#content__header__design:not(:has([data-name]:is([data-pos="1"], [data-pos="2"], [data-pos="3"]))) ~ [data-setting="set__i-header-top--he"],
#content__header__design:not(:has([data-name]:is([data-pos="7"], [data-pos="8"], [data-pos="9"]))) ~ [data-setting="set__i-header-secondary--he"]{
	display: none;
}

