} */


/*
	----------------
	- Save
	----------------
*/

.editor-buttons__save{
	margin-top: auto;
}

/*
	----------------
	- Dialog
	----------------
*/

.theme-editor__dialog{
	background: var(--panel--ba-co);
	border-width: 0;
	width: 1100px;
	border-radius: 8px;
	box-shadow: hsl(0 0% 0% / .2) 0px 20px 60px, hsl(0 0% 0% / .1) 0px 4px 3px -1px;
	display: flex;
	flex-direction: column;

	transform-origin: 50% 0;

	--i-animation-name: theme-editor__dialog;
}

@media (display-mode: standalone){
	.theme-editor__dialog{
		inset: 0;
		top: env(safe-area-inset-top);
		bottom: env(safe-area-inset-bottom);
		max-height: calc(100% - env(safe-area-inset-top) - env(safe-area-inset-bottom) - 40px);
	}
}

@keyframes theme-editor__dialog{
	from{
		opacity: 0;
		transform: scale(.95) translateY(-20px);
	}
}

	.theme-editor__dialog header{
		padding: 1.4em;
		flex: 0 0 auto;
		display: flex;
		align-items: center;
		gap: 8px;
		border-bottom: 1px solid var(--panel--bo-co);
	}

	.theme-editor__dialog header :is(h2, h3, h4, h5){
		font-weight: 600;
		font-size: 1.2em;
	}

	.theme-editor__dialog header > :first-child{
		margin-inline-end: auto;
	}

	.theme-editor__dialog header button{
		display: flex;
		gap: 0.8em;
		align-items: center;
		border-radius: 5px;
		padding: 0.7em 1em;
		color: var(--i-primary-contrast);
		background: var(--i-primary);
		font-weight: 600;
		font-size: .9em;
	}

	.theme-editor__dialog header button:hover{
		background: var(--i-primary-light);
	}

	.theme-editor__dialog header button[data-revert-custom-css]{
		color: var(--i-color_primary);
		background: color-mix(in srgb, currentcolor 10%, transparent);
	}
	.theme-editor__dialog header button[data-revert-custom-css]:hover{
		background: color-mix(in srgb, currentcolor 20%, transparent);
	}

	.theme-editor__dialog header button svg{
		width: auto;
		height: 1em;
		fill: currentColor;
	}

	/* Custom CSS */
	ips-code-editor{
		flex: 1 1 800px;
		overflow: auto;
	}
	ips-code-editor :is(textarea, .ipsEditor__tiptap-wrap .tiptap.ProseMirror){
		--i-outline-width: 0px;
		background: var(--panel--ba-co);
		padding: 2em;
		font-family: Monospace;
		resize: none;
		tab-size: 4;
		height: 100%;
	}
		ips-code-editor :is([data-role='reactRoot'], .ipsEditor__tiptap-wrap, .ipsEditor__tiptap-wrap > div) {
			display: contents;
		}

		ips-code-editor .ipsEditor__tiptap-wrap > .ipsEditor__toolbar {
			display: none;
		}

	.theme-editor__dialog > #customCSS-warning {
		position: absolute;
		inset-inline-end: 1em;
		inset-block-end: 1em;
	}
	.theme-editor__dialog > #customCSS-warning > .fa-solid {
		font-size: 1.5em;
		color: var(--i-color_warning);
		display: block;
		position: relative;
		z-index: 2;
	}
	#customCSS-warning > #customCSS-warning-message {
		position: absolute;
		inset-block-end: calc(100% + 1em);
		inset-inline-end: 0;
		background: var(--i-color_root);
		color: var(--i-background_1);
		z-index: -1;
		padding: 1em;
		opacity: 0;
		transition: opacity 0.25s ease;
		min-width: 400px;
	}

	#customCSS-warning:is(:hover, :focus) > #customCSS-warning-message {
		z-index: 2;
		opacity: 1;
	}

	/* Hide the "saved" textarea */
	#customCSS-saved{
		display: none;
	}

	.theme-editor__dialog footer{
		flex: 0 0 auto;
		padding: 1em;
		display: flex;
		flex-wrap: wrap;
		gap: .6em
	}

	.theme-editor__dialog footer > div{
		display: flex;
		flex-wrap: wrap;
		gap: inherit;
		flex: 1 1 auto;
	}

	.theme-editor__dialog footer .ipsButton{
		flex: 0 0 auto;
		font-size: .9em;
		padding: 1em 1.2em;
	}

	@media (max-width: 600px){
		.theme-editor__dialog footer .ipsButton{
			flex: 1 1 auto;
		}
	}

	@media (min-width: 601px){
		.theme-editor__dialog footer > div:first-child{
			flex-grow: 999;
		}
	}


/*
	----------------
	- Mobile UI
	----------------
*/

@media (hover:none){
	.editor__form :is(input, textarea){
		font-size: 16px;
	}
}

@media (min-width: 701px){
	/* Hide text labels on cancel/save buttons */
	.editor-buttons__text{
		display: none;
	}
}

@media (max-width: 700px){

	i-theme-editor{
		grid-template-columns: calc(100vw - 40px) 10px calc(100vw - 40px);
		overflow-x: auto;
		overscroll-behavior-x: contain;
		scroll-snap-type: x mandatory;
	}
	i-theme-editor::before{
		content: '||';
		color: var(--panel--ba-co);
		background: var(--panel--co_hard);
		display: grid;
		place-content: center;
	}
	i-theme-editor > *{
		scroll-snap-align: start;
	}
	/* Move editor to left panel and place light/dark toggle and cancel/save buttons at bottom of editor */
	.editor__form{
		order: -1;
		grid-template-columns: 1fr;
		grid-template-rows: 1fr auto;
	}
	[data-workspace="size"]{
		display: none !important;
	}
	editor-buttons{
		border-width: 1px 0 0 0;
		flex-direction: row;
		order: 1;
		flex-wrap: wrap;
	}
	editor-buttons div{
		display: flex;
	}
	editor-buttons [aria-controls="dialog__customCSS"]{
		display: none;
	}

	/* Push cancel/save buttons to the end */
	.editor-buttons__save{
	  margin-inline-start: auto;
	}

	/* Hide tooltips on smaller UI */
	.editor-buttons__tooltip{
		display: none;
	}

	/* Adjust size of cancel/save buttons */
	.editor-buttons__save :is(a, button){
		width: auto;
		padding: 0 1.4em;
	}

}


/*
	----------------
	- Conditionally adjust visibility of some settings
	----------------
*/

/* Conditional categories/settings: Some setting categories should be hidden depending on the status of other settings (ie. the Desktop Header settings shouldn't be displayed if the sidebar UI is enabled) */
.editor__form:has(#layout_global_view_mode [value="side"]:checked) :is([data-panel-nav][aria-controls="panel__desktopHeader"], [data-setting="set__i-logo--he"], [data-setting="set__i-desktop-logo--fo-si"]),
.editor__form:has(#layout_global_view_mode [value="default"]:checked) :is([data-panel-nav][aria-controls="panel__navigationPanel"], [data-setting="set__i-sidebar-ui-logo--he"], [data-setting="set__i-sidebar-ui-logo--fo-si"]){
	display: none;
}

/* Hide "header position" settings since they're managed by the drag/drop feature */
[data-setting="set__i-position-logo"],
[data-setting="set__i-position-navigation"],
[data-setting="set__i-position-user"],
[data-setting="set__i-position-breadcrumb"],
[data-setting="set__i-position-search"]{
	display: none;
}

/* Hide "top header" color settings if the header isn't visible */
i-theme-editor:has(.theme-editor__reorder [data-pos="1"]:not([data-name])):has(.theme-editor__reorder [data-pos="2"]:not([data-name])):has(.theme-editor__reorder [data-pos="3"]:not([data-name])) :is([data-setting="light__i-headerTop--ba-co"], [data-setting="dark__i-headerTop--ba-co"], [data-setting="light__i-headerTop--co"], [data-setting="dark__i-headerTop--co"]){
	display: none;
}

