		border-bottom: 1px dotted #fff;
		opacity: 1;
		color: #fff;
	}

	.cDashboard_bulletin h2 {
		margin-top: 5px;
		margin-bottom: 5px;
		font-size: 18px;
		font-weight: 300;
		color: #fff;
		letter-spacing: 0.3px;
	}

	.cDashboard_bulletin hr.ipsHr {
		border-color: rgba(255,255,255,0.1);
	}

	.cDashboard_bulletin i.fa-info-circle,
	.cDashboard_bulletin i.fa-warning {
		font-size: 54px;
		line-height: 1;
		color: rgba(255,255,255,0.4);
		text-shadow: none;
	}

/* COMMERCE */
.acpWidget_item #elNexusActions > li > a:hover {
	background: var(--i-background_2);
}

	.acpWidget_item .cNexusActionBadge_off{
		background: var(--i-background_5);
	}

table.diff {
	width: 100%;
}

table.diff td, table.diff th {
	width: 50%;
	max-width: 500px;
	overflow-x: auto;
}

table.diff td {
	padding: 10px;
	vertical-align: top;
	white-space: pre;
	white-space: pre-wrap;
	font-family: monospace;
}

.diffBlank {
	content: '&nbsp;';
}

.diffDeleted {
	background:rgb(255,224,224);
}

.diffInserted {
	background:rgb(224,255,224);
}

.acpEnhancement {
	border-top: 10px solid var(--i-background_5);
	padding: 1.3em;
	display: flex;
	flex-direction: column;
	position: relative;
}

.acpEnhancement_enabled {
	border-top-color: var(--i-background_positive);
}

.acpEnhancement__title{
	display: flex;
	align-items: center;
	margin-bottom: 1em;
	gap: .7em;
}

	.acpEnhancement__title h3{
		font-size: 1.1em;
		font-weight: 600;
		color: var(--i-color_hard);
	}

.acpEnhancement_buttons {
	margin-top: auto;
	padding-top: 2em
}

.acpEnhancement_logo {
	max-width: 100px;
	max-height: 30px;
	margin-inline-start: auto;
}

body#elLogin {
	display: flex;
	justify-content: center;
	align-items: center;
	overflow: auto;
	padding-top: 0;
	margin: 0 auto;
}

#elLogin_box {
	width: 98%;
	max-width: 450px;
}

.cAcpLoginBox {
	padding-left: 0;
	padding-right: 0;
}

	#elLogin_box .ipsFieldRow{
		padding: 1em 1.5em;
	}
	.cAcpLoginBox .ipsTabs__panel {
		background: transparent;
	}

.cAcpLoginBox_logo {
	text-align: center;
	margin: 40px 0 30px;
}

.cAcpLoginBox_logo img{
	width: 80%;
	margin: 0 auto;
	display: block;
}

	[data-ips-scheme="dark"] .cAcpLoginBox_logo img{
		filter: brightness(100);
	}

.cAcpLoginBox_button {
	margin-bottom: 5px;
}

/* Remove yellow auto-fill styles */
.cAcpLoginBox input{
	filter: none;
}


/* To make 2FA show as part of the form rather than a modal */
#elTwoFactorAuthentication.ipsModal {
	position: inherit;
	background: none;
}
#elTwoFactorAuthentication {
	position: inherit;
}
#elTwoFactorAuthentication > div {
	box-shadow: none;
}

.cMenuManager{
	--menu-manager--active: var(--i-primary);
}

.cMenuManager .cMenuManager_column.cMenuManager_readyToSlide {
	overflow: hidden;
}

/* Columns */
.cMenuManager_editorWrapper {
	width: 200%;
	display: flex;
}

.cMenuManager_main,
.cMenuManager_dropdown {
	flex: 0 0 50%;
	position: relative;
	padding: 20px;
	padding-bottom: 50px;
}

	.cMenuManager_leaf ~ ol {
		padding-inline-start: 1.5em;
	}

	.cMenuManager_leaf {
		background: var(--i-background_1);
		border: 2px solid var(--i-background_3);
		padding: 12px 10px;
		margin: 5px 0;
		border-radius: 6px;
		cursor: move;
		display: flex;
		align-items: center;
	}

	:where([data-ips-scheme="dark"]) .cMenuManager_leaf{
		background: var(--i-background_3);
		border-color: var(--i-background_4);
	}

		.cMenuManager_tools{
			display: flex;
			gap: 1em;
			margin-inline-start: auto;
		}

		.cMenuManager_tools [data-action="editDropdown"]{
			color: inherit;
		}

		.cMenuManager_leaf.cMenuManager_active {
			background: var(--menu-manager--active);
			color: #fff;
			border-color: var(--menu-manager--active);
			margin-inline-end: -21px;
			padding-inline-end: 20px;
			border-start-end-radius: 0px;
			border-end-end-radius: 0px;
		}

		.cMenuManager_leaf .cMenuManager_leafTitle {
			font-size: 16px;
			font-weight: 500;
		}

			.cMenuManager_leaf + ol .cMenuManager_leaf {
				padding: .6em .8em;
			}

				.cMenuManager_leaf + ol .cMenuManager_leaf.cMenuManager_active {
					padding-inline-end: 20px;
				}

				.cMenuManager_leaf + ol .cMenuManager_leaf .cMenuManager_leafTitle {
					font-size: 14px;
				}

		.cMenuManager_leaf .cMenuManager_leafMeta {
			font-size: 12px;
		}

		.cMenuManager_leaf [data-action="removeItem"],
		.cMenuManager_dropdown .ipsMenu_item [data-action="removeItem"] {
			color: inherit;
			opacity: 0.1;
			transition: opacity 0.1s linear;
		}

			.cMenuManager_leaf:hover [data-action="removeItem"],
			.cMenuManager_dropdown .ipsMenu_item:hover [data-action="removeItem"] {
				opacity: 1;
			}

.cMenuManager_emptyHover {
	border: 1px solid var(--i-color_soft);
	background: var(--i-background_4);
	border-radius: 4px;
	height: 37px;
	position: relative;
	margin-inline-start: -10px;
}

	.cMenuManager_emptyHover.cMenuManager_emptyError {
		background: #f9ebeb;
		color: #906161;
		border: 1px solid currentColor;
	}

	[data-ips-scheme="dark"] .cMenuManager_emptyHover.cMenuManager_emptyError {
		background: #5f3434;
	}

		.cMenuManager_emptyHover.cMenuManager_emptyError:before {
			content: '\f00d';
			font-family: var(--i-font-awesome);
			-webkit-font-smoothing: antialiased;
			text-rendering: auto;
			font-weight: 900;
			font-size: 18px;
			position: absolute;
			inset-inline-start: 10px;
			line-height: 40px;
		}

/* Dropdown editor */
.cMenuManager_dropdown .ipsMenu {
	position: relative;
	top: 0;
	inset-inline-start: 0;
	width: 80%;
	margin: 30px auto 50px auto;
	min-height: 30px;
	box-shadow: 0px 12px 60px rgba(0,0,0,0.2);
}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item > div {
		display: flex;
		align-items: center;
		color: var(--i-color_hard);
		padding: .8em 1em;
		cursor: move;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item {
		border: 1px solid transparent;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item a:hover {
		background: transparent;
	}

	.cMenuManager_dropdown .ipsMenu .ipsMenu_item.cMenuManager_active {
		background: var(--i-background_4);
		border-color: var(--i-primary);
	}

.cMenuManager_dropdown .ipsButton_narrow {
	padding: 0;
	border: 0;
}

.cMenuManager_emptyList {
	line-height: 40px;
	font-size: 12px;
	font-style: italic;
	opacity: 0.8;
}

/* Form editor */
.cMenuManager_form {
	position: relative;
}

	.cMenuManager_form.cMenuManager_formActive {
		border-inline-start: 4px solid var(--menu-manager--active);
		padding: 10px;
	}

.cMenuManager_form > .cMenuManager_formLoading {
	position: absolute;
	inset: 0;
}

/* Preview panel */
.cMenuManager_preview {
	position: -webkit-sticky;
	position: sticky;
	bottom: 0;
	background: var(--i-background_2);
}

	.cMenuManager_preview h2 {
		background: var(--i-primary);
		color: #fff;
		height: 48px;
		font-size: 16px;
		font-weight: 500;
		display: flex;
		align-items: center;
		gap: 1em;
	}

		.cMenuManager_preview h2 a{
			color: inherit;
		}

	.cMenuManager_preview #elPreviewTheme {
		opacity: .8;
	}

	.cMenuManager_preview [data-role="previewBody"] {

	}

	.cMenuManager_preview iframe {
		width: 100%;
		height: 300px;
	}

	.cMenuManager_preview [data-action="previewToggle"]{
		width: 3em;
		height: 3em;
		display: grid;
		place-content: center;
		background: hsl(0 0% 100% / .2);
	}
		.cMenuManager_preview [data-action="previewToggle"]:hover{
			background: hsl(0 0% 100% / .3);
		}

/* Preview frame */
#elMenuManagerPreview_body {
	padding: 50px 30px;
	--i-header-row--he: 3em;
}

.cNotification {
	position: relative;
	border-inline-start-width: 10px;
}

.cNotification_dismiss {
	width: 28px;
	height: 28px;
	border-radius: 14px;
	background: #000;
	color: #fff;
	line-height: 28px;
	text-align: center;
	position: absolute;
	top: -5px;
	inset-inline-end: -5px;
}

.cNotification_dismiss:hover {
	color: #fff;
}

#elSkinHookEditor > .ipsColumns,
#elCodeHookEditor > .ipsColumns {
	min-height: 700px;
}

.cHookEditor_sidebar {
	background: var(--i-background_1);
	height: 720px;
	overflow-y: scroll;
	overflow-x: hidden;
}

	.cHookEditor_sidebar li {
		cursor: pointer;
	}

 .cHookEditor_content {
	margin-inline-start: 7px;
}

	.cHookEditor_content .acpFormTabContent {
		border: 0;
		padding: 15px;
	}

	.cHookEditor_content .ipsTabs__tab {
		max-width: 250px !important;
	}


#elHookEditor .CodeMirror {
	height: 700px;
}

.cHookEditor_tree {
	padding: 0 15px 15px 15px;
	line-height: 1.6;
	font-size: 11px;
	font-family: 'monaco', 'courier new', monospace;
}

.cHookEditor_tree > ul {
	padding: 0;
}

.cHookEditor_tree span {
	display: inline-block;
}

.cHookEditor_tree span[data-selectable]:hover {
	background: #f9f7d2;
	cursor: pointer;
}

.cHookEditor_tree span[data-unselectable] {
	opacity: 0.4;
}

.cHookEditor_sidebar .ipsSideMenu_item a, .cHookEditor_sidebar a.ipsSideMenu_item, .cHookEditor_sidebar span.ipsSideMenu_item{
	border-radius: 0;
}

/* core - admin/system/reports.css - Supporting styles for the saved stats ACP page. */

/* In dropdowns, make sure the form is at least the height of the content */
.cStatTile__save-report-menu .iDropdown__content .ipsSubmitRow {
    border-radius: 0;
}

.cStatTile__save-report-menu .ipsMessage {
    text-wrap: auto;
    display: flex;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
    margin-bottom: 0;
}
.cStatTile__save-report-menu .ipsMessage + form .ipsFieldRow__section:not(.ipsTabs__panel *):first-child {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
}
.cStatTile__save-report-menu .ipsMessage::before {
    display: block;
    align-self: center;
}

/* Add in the styles to mimic .ipsBox.ipsBox_shadowed. Since this appears inside tabs using this app, it looks odd without a bit more separation */
[data-controller*="core.admin.members.lazyLoadingProfileBlock"] .ipsChart {
    border-radius: 5px;
    background: var(--i-background_1);
    border: 1px solid var(--i-background_3);
}

.ipsGrid--myCharts > * {
    display: flex;
    flex-direction: column;
}
.ipsGrid--myCharts .ipsChart {
    flex-grow: 1;
    display:flex;
    flex-direction: column;
}

.ipsGrid--myCharts > [data-controller*="core.admin.members.lazyLoadingProfileBlock"] > .ipsLoading {
    min-height: 300px;
}

.ipsChart .ipsChart__table-wrapper {
    max-height: 250px;
    overflow-y: auto;
}
    .ipsChart .ipsChart__table-wrapper.ipsLoading {
        overflow-y: hidden;
    }
    .ipsChart .ipsChart__table-wrapper.ipsLoading > * {
        opacity: 0;
    }

    .ipsChart .ipsChart__table-wrapper thead {
        position: sticky;
        top: 0;
    }

.ipsGrid--myCharts .ipsChart__timezone-disclaimer {
    display: none;
}

/* Overview statistics */
@keyframes updated {
	0%, 100% { 
        scale: 1;
        opacity: 1;
    }
	50% { 
        scale: .95;
        opacity: .6;
    }
}

.cStatTile {
    display: flex;
    flex-direction: column;
    padding: 1.2em;
}

    .cStatTile--updated {
        animation: updated .7s 1 ease-out;
    }

    .cStatTile__header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 1em;
    }

    .cStatTile__title {
        color: var(--i-color_hard);
        font-size: 1.3em;
        font-weight: 500;
    }

    .cStatTile__subTitle {
        color: var(--i-color_soft);
        font-weight: 500;
        margin-bottom: 5px;
    }

    .cStatTile__body {
        flex-grow: 1;
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 190px;
        text-align: center;
    }

        .cStatTile__bodyInner {
            width: 100%;
        }

    .cStatTile__icons{
        display: flex;
        gap: 3px;
        flex: 0 0 auto;
    }

    .cStatTile__icons .ipsButton{
        padding: .6em;
        min-width: 0;
    }

    .cStatTile__split {
        width: 50%;
        flex-grow: 1;
    }

.cStat__number {
    font-weight: 500;
    line-height: 1;
    display: block;
}
    .cStat__number--large {
        font-size: 50px;
        margin-bottom: 7px;
    }
    .cStat__number--medium {
        font-size: 40px;
        margin-bottom: 7px;
    }
    .cStat__number--small {
        font-size: 22px;
        margin-bottom: 5px;
        color: var(--i-color_soft);
    }

.cStat__change {
    font-weight: bold;
    line-height: 1;
    display: inline-block;
}
    .cStat__change--large {
        font-size: 17px;
    }
    .cStat__change--small {
        font-size: 12px;
    }


.cStatsGrid .ipsLoading {
	height: 100%;
}

	.cStatsGrid .ipsBox {
		position: relative;
	}
		.cStatsGrid .ipsBox > p {
			position: absolute;
			bottom: 0px;
		}

.cStatsFilters button[type="submit"] {
	margin-inline-start: 30px;
}

.cStatsFilters #dateFilterInputs {
	display: inline-block;
	margin-inline-end: 10px;
}

.ipsApp .cStatsFilters .ipsField_short {
    padding: 7px 11px;
    margin-inline-start: 10px;
    margin-inline-end: 10px;
}

.ipsApp .cStatsFilters .ipsField_short:last-child {
    margin-inline-end: 0;
}

html[dir] .ipsHovercard .ipsForm--horizontal .ipsFieldRow > .ipsFieldRow__label {
    min-width: 200px;
    width: auto;
}

.ipsFieldRow_content {
    padding-inline-start: 10px !important;
}
.ipsFieldRow_label {
    padding-inline-start: 10px !important;
}
